INSERT INTO `mac_vod` VALUES (1, 1, 0, 0, '小市民系列', '', 'xiaoshiminxilie', 1, 'X', '', 'e2f4a486', '小说改,推理,校园', 'https://i0.hdslb.com/bfs/bangumi/image/280acd8cc64255a8b5a3bbd748f9bf9022c085fb.png', 'https://i0.hdslb.com/bfs/archive/676f2be970d790f3fbdd2d112ae42d357b7ea0bc.png', '', '', '小鸠常悟朗：梅田修一朗小佐内由纪：羊宫妃那堂岛健吾：古川慎', '神户守', '', '', '互相帮助，争取成为一个彻底的小市民吧。\r\n小鸠过去因为喜欢进行被他称之为“动脑子”的推理活动，有过一段苦涩的经历，这让他决心成为一个谨小慎微的小市民。\r\n他和有着同样志向的同学小佐内结成了互帮互助的密切“', '全10集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 57, 0, 57, 57, '', 0, 0, 8.3, 0, 0, 1730788127, 1724743535, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>互相帮助，争取成为一个彻底的小市民吧。\n小鸠过去因为喜欢进行被他称之为“动脑子”的推理活动，有过一段苦涩的经历，这让他决心成为一个谨小慎微的小市民。\n他和有着同样志向的同学小佐内结成了互帮互助的密切“互惠”关系，准备以小市民的身份迎接崭新的高中生活。\n但不知为何，不可思议的事件和灾难接连不断地降临到他们的校园生活中。\n小鸠和小佐内到底能否得到梦想的小市民安稳生活呢？</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5425EA8CE81D550F50E978#第02集$MOE5425EA8CE81D550F50E97B#第03集$MOE5425EA8CE81D550F50E97A#第04集$MOE5425EA8CE81D550F50E97D#第05集$MOE5425EA8CE81D550F50E97C#第06集$MOE5425EA8CE81D550F50E97F#第07集$MOE5425EA8CE81D550F50E97E#第08集$MOE5425EA8CE81D550F50E971#第09集$MOE5425EA8CE81D550F50E970#第10集$MOE5425EA8CE81D550F50E879$$$第01集$id_XS5425EA8CE81D550F50E978#第02集$id_XS5425EA8CE81D550F50E97B#第03集$id_XS5425EA8CE81D550F50E97A#第04集$id_XS5425EA8CE81D550F50E97D#第05集$id_XS5425EA8CE81D550F50E97C#第06集$id_XS5425EA8CE81D550F50E97F#第07集$id_XS5425EA8CE81D550F50E97E#第08集$id_XS5425EA8CE81D550F50E971#第09集$id_XS5425EA8CE81D550F50E970#第10集$id_XS5425EA8CE81D550F50E879$$$第01集$id_MOE5425EA8CE81D550F50E978#第02集$id_MOE5425EA8CE81D550F50E97B#第03集$id_MOE5425EA8CE81D550F50E97A#第04集$id_MOE5425EA8CE81D550F50E97D#第05集$id_MOE5425EA8CE81D550F50E97C#第06集$id_MOE5425EA8CE81D550F50E97F#第07集$id_MOE5425EA8CE81D550F50E97E#第08集$id_MOE5425EA8CE81D550F50E971#第09集$id_MOE5425EA8CE81D550F50E970#第10集$id_MOE5425EA8CE81D550F50E879', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1282, 4, 0, 0, '神之塔 第二季', '神之塔 -Tower of God- 2nd Season', 'shenzhitadierji', 0, 'S', '', 'cdabdb2c', '漫画改,战斗,奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2905696996.jpg', 'https://i1.hdslb.com/bfs/archive/cf7cd19a18912393d262a056eef38dcb648e1407.png', '', '', '市川太一', '', '', '', '　　2024年7月より放送決定。原作でも人気の「王子の帰還」「工房戦」の２エピソードが描かれます。', '更新至第7集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 23, 0, 23, 23, '', 0, 0, 6.5, 0, 0, 1724765250, 1724758354, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　2024年7月より放送決定。原作でも人気の「王子の帰還」「工房戦」の２エピソードが描かれます。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5273EDDAED4B5F5A50E978#第02集$id_XS5273EDDAED4B5F5A50E97B#第03集$id_XS5273EDDAED4B5F5A50E97A#第04集$id_XS5273EDDAED4B5F5A50E97D#第05集$id_XS5273EDDAED4B5F5A50E97C#第06集$id_XS5273EDDAED4B5F5A50E97F#第07集$id_XS5273EDDAED4B5F5A50E97E#第08集$id_XS5273EDDAED4B5F5A50E971#第09集$id_XS5273EDDAED4B5F5A50E970#第10集$id_XS5273EDDAED4B5F5A50E879#第11集$id_XS5273EDDAED4B5F5A50E878#第12集$id_XS5273EDDAED4B5F5A50E87B$$$第01集$id_MOE5273EDDAED4B5F5A50E978#第02集$id_MOE5273EDDAED4B5F5A50E97B#第03集$id_MOE5273EDDAED4B5F5A50E97A#第04集$id_MOE5273EDDAED4B5F5A50E97D#第05集$id_MOE5273EDDAED4B5F5A50E97C#第06集$id_MOE5273EDDAED4B5F5A50E97F#第07集$id_MOE5273EDDAED4B5F5A50E97E#第08集$id_MOE5273EDDAED4B5F5A50E971#第09集$id_MOE5273EDDAED4B5F5A50E970#第10集$id_MOE5273EDDAED4B5F5A50E879#第11集$id_MOE5273EDDAED4B5F5A50E878#第12集$id_MOE5273EDDAED4B5F5A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (3, 1, 0, 0, '异世界悠闲纪行～边养娃边当冒险者～', '異世界ゆるり紀行 ～子育てしながら冒険者します～（2024）', 'yishijieyouxianjixingbianyangwabiandangmaoxianzhe', 1, 'Y', '', '8b6e071c', '异世界,奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2908918335.jpg', '', '', '', '白井悠介 Yusuke Shirai / 铃木爱奈 Aina Suzuki / 花井美春 / 户松遥', '浊川敦 / 桑原悟 / 設楽希 / 森下广人', '', '', '　　由于风之神希尔的失误而死亡，转生了的青年巧。\r\n                                    \r\n                                　　从希尔那', '全12集', '', 0, '0', '', '', '日本', '七月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 33, 0, 33, 33, '', 0, 0, 0.0, 0, 0, 1744026374, 1724758659, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '由于风之神希尔的失误而死亡，转生了的青年巧。 从希尔那里收到了表达歉意的各种技能， 然后被传送到他所管理的异世界安特尔蒂亚， 却刚好降落到了危险魔物出没的大森林……。 巧在那片森林中，发现了看起来像是双胞胎的男童女童。 为了两人的安全，取名为艾伦、艾琳娜保护他们。 两人人用格斗术轻易地打倒了魔物，巧对此感到十分震惊， 就这样一路到达了镇上，为了生计…', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0975BADDB91E5C5A50E978#第02集$MOE0975BADDB91E5C5A50E97B#第03集$MOE0975BADDB91E5C5A50E97A#第04集$MOE0975BADDB91E5C5A50E97D#第05集$MOE0975BADDB91E5C5A50E97C#第06集$MOE0975BADDB91E5C5A50E97F#第07集$MOE0975BADDB91E5C5A50E97E#第08集$MOE0975BADDB91E5C5A50E971#第09集$MOE0975BADDB91E5C5A50E970#第10集$MOE0975BADDB91E5C5A50E879#第11集$MOE0975BADDB91E5C5A50E878#第12集$MOE0975BADDB91E5C5A50E87B$$$第01集$id_XS0975BADDB91E5C5A50E978#第02集$id_XS0975BADDB91E5C5A50E97B#第03集$id_XS0975BADDB91E5C5A50E97A#第04集$id_XS0975BADDB91E5C5A50E97D#第05集$id_XS0975BADDB91E5C5A50E97C#第06集$id_XS0975BADDB91E5C5A50E97F#第07集$id_XS0975BADDB91E5C5A50E97E#第08集$id_XS0975BADDB91E5C5A50E971#第09集$id_XS0975BADDB91E5C5A50E970#第10集$id_XS0975BADDB91E5C5A50E879#第11集$id_XS0975BADDB91E5C5A50E878#第12集$id_XS0975BADDB91E5C5A50E87B$$$第01集$id_MOE0975BADDB91E5C5A50E978#第02集$id_MOE0975BADDB91E5C5A50E97B#第03集$id_MOE0975BADDB91E5C5A50E97A#第04集$id_MOE0975BADDB91E5C5A50E97D#第05集$id_MOE0975BADDB91E5C5A50E97C#第06集$id_MOE0975BADDB91E5C5A50E97F#第07集$id_MOE0975BADDB91E5C5A50E97E#第08集$id_MOE0975BADDB91E5C5A50E971#第09集$id_MOE0975BADDB91E5C5A50E970#第10集$id_MOE09