INSERT INTO `mac_vod` VALUES (4, 1, 0, 0, '深夜PUNCH', '真夜中ぱんチ（2024）', 'shenyePUNCH', 1, 'S', '', '98d5d323', '原创,搞笑', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2908974606.jpg', '', '', '', '长谷川育美 / 菲鲁兹·蓝 / 伊藤ゆいな / 羊宫妃那 / 上田瞳 / 茅野爱衣', '本间修', '', '', '　　「真夜中なのにおっはよー！真夜中ぱんチです！」\r\n                                    \r\n                                　　世界で', '全12集', '', 0, '0', '', '', '日本', '七月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 7.6, 0, 0, 1743563287, 1724759195, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '「真夜中なのにおっはよー！真夜中ぱんチです！」 世界でもっとも見られている動画投稿サイト「NewTube」。 3人組NewTuber「はりきりシスターズ」の「まさ吉」こと真咲まさきは、 とある事件がきっかけでチャンネルをクビになってしまう。 起死回生を狙う真咲の前に現れたのは、なぜか彼女に運命を感じたりぶ。 超人的な能力を持つりぶと一緒なら、最高の動画が撮れるはず。 目指せ、チャンネル登録100万人！ 現代人共感必至!? 「パリピ孔明」スタッフが贈る、ワケあり動画投稿者たちの ハイテンション・ガールズ“再生”ストーリー！', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE082FE88DED1A5F0A50E978#第02集$MOE082FE88DED1A5F0A50E97B#第03集$MOE082FE88DED1A5F0A50E97A#第04集$MOE082FE88DED1A5F0A50E97D#第05集$MOE082FE88DED1A5F0A50E97C#第06集$MOE082FE88DED1A5F0A50E97F#第07集$MOE082FE88DED1A5F0A50E97E#第08集$MOE082FE88DED1A5F0A50E971#第09集$MOE082FE88DED1A5F0A50E970#第10集$MOE082FE88DED1A5F0A50E879#第11集$MOE082FE88DED1A5F0A50E878#第12集$MOE082FE88DED1A5F0A50E87B$$$第01集$id_XS082FE88DED1A5F0A50E978#第02集$id_XS082FE88DED1A5F0A50E97B#第03集$id_XS082FE88DED1A5F0A50E97A#第04集$id_XS082FE88DED1A5F0A50E97D#第05集$id_XS082FE88DED1A5F0A50E97C#第06集$id_XS082FE88DED1A5F0A50E97F#第07集$id_XS082FE88DED1A5F0A50E97E#第08集$id_XS082FE88DED1A5F0A50E971#第09集$id_XS082FE88DED1A5F0A50E970#第10集$id_XS082FE88DED1A5F0A50E879#第11集$id_XS082FE88DED1A5F0A50E878#第12集$id_XS082FE88DED1A5F0A50E87B$$$第01集$id_MOE082FE88DED1A5F0A50E978#第02集$id_MOE082FE88DED1A5F0A50E97B#第03集$id_MOE082FE88DED1A5F0A50E97A#第04集$id_MOE082FE88DED1A5F0A50E97D#第05集$id_MOE082FE88DED1A5F0A50E97C#第06集$id_MOE082FE88DED1A5F0A50E97F#第07集$id_MOE082FE88DED1A5F0A50E97E#第08集$id_MOE082FE88DED1A5F0A50E971#第09集$id_MOE082FE88DED1A5F0A50E970#第10集$id_MOE082FE88DED1A5F0A50E879#第11集$id_MOE082FE88DED1A5F0A50E878#第12集$id_MOE082FE88DED1A5F0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (5, 1, 0, 0, '败北女角太多了！', '負けヒロインが多すぎる！', 'baibeinvjiaotaiduoliao', 1, 'B', '', '47f22f94', '校园,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2909208908.jpg', '', 'https://i0.hdslb.com/bfs/archive/708e37887a6442b724140a9199422eb0db4aa32c.jpg', '', '斋藤千和,安济知佳,上坂堇,逢坂良太,小林千晃,上田丽奈,小林裕介,田中美海,种崎敦美,寺泽百花,若山诗音,远野光,梅田修一朗', '北村翔太郎', '', '', '　　平常担任班上背景人物的我──温水和彦，偶然目击人气女同学八奈见杏菜被男生甩掉的失恋现场。「他明明说过要娶我当新娘，这不过分吗？」「那是多久前的事了？」「大概四、五岁吧。」那不算数吧？以此为契机，田', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 371, 1, 371, 371, '', 0, 0, 8.8, 0, 0, 1730931572, 1724759384, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　平常担任班上背景人物的我──温水和彦，偶然目击人气女同学八奈见杏菜被男生甩掉的失恋现场。「他明明说过要娶我当新娘，这不过分吗？」「那是多久前的事了？」「大概四、五岁吧。」那不算数吧？以此为契机，田径队的烧盐柠檬、文艺社的小鞠知花等洋溢着败北感的女生接连登场──？「温水，女生可以分成两大类。如果不是青梅竹马，就是狐狸精。」「原来如此，真豪爽的分类法。」……但愿这些因为败北而闪耀的少女们都能幸福。被败北女角──败女所环绕的谜样青春，在此揭幕！</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0520EA8ABB4F540D50E978#第02集$MOE0520EA8ABB4F540D50E97B#第03集$MOE0520EA8ABB4F540D50E97A#第04集$MOE0520EA8ABB4F540D50E97D#第05集$MOE0520EA8ABB4F540D50E97C#第06集$MOE0520EA8ABB4F540D50E97F#第07集$MOE0520EA8ABB4F540D50E97E#第08集$MOE0520EA8ABB4F540D50E971#第09集$MOE0520EA8ABB4F540D50E970#第10集$MOE0520EA8ABB4F540D50E879#第11集$MOE0520EA8ABB4F540D50E878#第12集$MOE0520EA8ABB4F540D50E87B$$$第01集$id_XS0520EA8ABB4F540D50E978#第02集$id_XS0520EA8ABB4F540D50E97B#第03集$id_XS0520EA8ABB4F540D50E97A#第04集$id_XS0520EA8ABB4F540D50E97D#第05集$id_XS0520EA8ABB4F540D50E97C#第06集$id_XS0520EA8ABB4F540D50E97F#第07集$id_XS0520EA8ABB4F540D50E97E#第08集$id_XS0520EA8ABB4F540D50E971#第09集$id_XS0520EA8ABB4F540D50E970#第10集$id_XS0520EA8ABB4F540D50E879#第11集$id_XS0520EA8ABB4F540D50E878#第12集$id_XS0520EA8ABB4F540D50E87B$$$第01集$id_MOE0520EA8ABB4F540D50E978#第02集$id_MOE0520EA8ABB4F540D50E97B#第03集$id_MOE0520EA8ABB4F540D50E97A#第04集$id_MOE0520EA8ABB4F540D50E97D#第05集$id_MOE0520EA8ABB4F540D50E97C#第06集$id_MOE0520EA8ABB4F540D50E97F#第07集$id_MOE0520EA8ABB4F540D50E97E#第08集$id_MOE0520EA8ABB4F540D50E971#第09集$id_MOE0520EA8ABB4F540D50E970#第10集$id_MOE0520EA8ABB4F540D50E879#第11集$id_MOE0520EA8ABB4F540D50E878#第12集$id_MOE0520EA8ABB4F540D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (6, 1, 0, 0, '亚托莉 -我挚爱的时光-', '', 'yatuoliwozhiaideshiguang', 1, 'Y', '', '88950488', '游戏改,校园,科幻,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/b212f52c35a77ad4b751997e320d24d01d9a45ce.png', '', '', '', '斑鸠夏生：小野贤章\n亚托莉：赤尾光\n神白水菜萌：高桥未奈美\n野岛龙司：细谷佳正\n凯瑟琳：日笠阳子\n名波凛凛花：春野杏', '加藤诚', '', '', '「在逐渐沉没的世界，我找到了你。」\n在近未来，不明原因的海平面上升导致大面积地表被海水淹没。\n幼时因意外事故失去了一条腿的少年斑鸠夏生厌倦了城市生活，迁居到了海边的乡村小镇。\n他无亲无故，留给他的只有', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 68, 0, 68, 68, '', 0, 0, 9.4, 0, 0, 1730929510, 1724759550, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「在逐渐沉没的世界，我找到了你。」\n在近未来，不明原因的海平面上升导致大面积地表被海水淹没。\n幼时因意外事故失去了一条腿的少年斑鸠夏生厌倦了城市生活，迁居到了海边的乡村小镇。\n他无亲无故，留给他的只有曾属于海洋地质学家的祖母的船和潜水艇，以及债款。\n夏生为了取回自己“失去的未来”，潜入大海寻找据说沉睡着祖母遗产的海底仓库。\n他在那里找到的，是沉睡在棺材状装置中的神秘少女——亚托莉。\n她是几乎与人类无异的，精巧且感情丰富的机器人。\n从海底被打捞上来的亚托莉说道。\n「我想完成主人留下的最后一道命令。在那之前，我来做夏生的脚！」\n在逐渐沉入海中的安宁小镇，少年与机器人少女难以忘怀的夏天开始了——</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE092FB58DB91D550150E978#第02集$MOE092FB58DB91D550150E97B#第03集$MOE092FB58DB91D550150E97A#第04集$MOE092FB58DB91D550150E97D#第05集$MOE092FB58DB91D550150E97C#第06集$MOE092FB58DB91D550150E97F#第07集$MOE092FB58DB91D550150E97E#第08集$MOE092FB58DB91D550150E971#第09集$MOE092FB58DB91D550150E970#第10集$MOE092FB58DB91D550150E879#第11集$MOE092FB58DB91D550150E878#第12集$MOE092FB58DB91D550150E87B#第13集$MOE092FB58DB91D550150E87A$$$第01集$id_XS092FB58DB91D550150E978#第02集$id_XS092FB58DB91D550150E97B#第03集$id_XS092FB58DB91D550150E97A#第04集$id_XS092FB58DB91D550150E97D#第05集$id_XS092FB58DB91D550150E97C#第06集$id_XS092FB58DB91D550150E97F#第07集$id_XS092FB58DB91D550150E97E#第08集$id_XS092FB58DB91D550150E971#第09集$id_XS092FB58DB91D550150E970#第10集$id_XS092FB58DB91D550150E879#第11集$id_XS092FB58DB91D550150E878#第12集$id_XS092FB58DB91D550150E87B#第13集$id_XS092FB58DB91D550150E87A$$$第01集$id_MOE092FB58DB91D550150E978#第02集$id_MOE092FB58DB91D550150E97B#第03集$id_MOE092FB58DB91D550150E97A#第04集$id_MOE092FB58DB91D550150E97D#第05集$id_MOE092FB58DB91D550150E97C#第06集$id_MOE092FB58DB91D550150E97F#第07集$id_MOE092FB58DB91D550150E97E#第08集$id_MOE092FB58DB91D550150E971#第09集$id_MOE092FB58DB91D550150E970#第10集$id_MOE092FB58DB91D550150E879#第11集$id_MOE092FB58DB91D550150E878#第12集$id_MOE092FB58DB91D550150E87B#第13集$id_MOE092FB58DB91D550150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (7, 1, 0, 0, '魔法少女与邪恶曾经敌对。', '', 'mofashaonvyuxieezengjingdidui', 1, 'M', '', '75f237a5', '漫画改,恋爱,奇幻', 'https://i0.hdslb.com/bfs/bangumi/image/dcd2c69e23da1c1c79e1fc5de8d6670e0cbbefa9.png', '', '', '', '米拉：小野友树\n深森白夜：中原麻衣\n使者（猫）：三木真一郎\n篝 火花：伊濑茉莉也\n使者（鸟）：绿川光\n佛马哈特：铃村健一\n贝拉朵莉丝：川澄绫子\n阿尔库俄涅：下野纮\n丝皮卡：东山奈央\n萨达尔苏德：山崎巧\n贝特尔吉斯：土师孝也', '大桥明代', '', '', '邪恶组织――侵略一切，毁灭一切。 \n这个残忍而狡猾的组织，其智囊正是王的心腹，邪恶参谋。 \n面对地面遭受侵略的危机，奋起迎战的是不幸的魔法少女・白夜。 \n与她对峙的邪恶参谋・米拉竟对她一见钟情……', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 56, 0, 56, 56, '', 0, 0, 9.9, 0, 0, 1730927205, 1724759775, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>邪恶组织――侵略一切，毁灭一切。 \n这个残忍而狡猾的组织，其智囊正是王的心腹，邪恶参谋。 \n面对地面遭受侵略的危机，奋起迎战的是不幸的魔法少女・白夜。 \n与她对峙的邪恶参谋・米拉竟对她一见钟情…… \n魔法少女与邪恶为敌，已然成为过去。 \n相爱（不）相杀的二人，究竟未来会如何――？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0622EA8ABA1E0C0C50E978#第02集$MOE0622EA8ABA1E0C0C50E97B#第03集$MOE0622EA8ABA1E0C0C50E97A#第04集$MOE0622EA8ABA1E0C0C50E97D#第05集$MOE0622EA8ABA1E0C0C50E97C#第06集$MOE0622EA8ABA1E0C0C50E97F#第07集$MOE0622EA8ABA1E0C0C50E97E#第08集$MOE0622EA8ABA1E0C0C50E971#第09集$MOE0622EA8ABA1E0C0C50E970#第10集$MOE0622EA8ABA1E0C0C50E879#第11集$MOE0622EA8ABA1E0C0C50E878#第12集$MOE0622EA8ABA1E0C0C50E87B$$$第01集$id_XS0622EA8ABA1E0C0C50E978#第02集$id_XS0622EA8ABA1E0C0C50E97B#第03集$id_XS0622EA8ABA1E0C0C50E97A#第04集$id_XS0622EA8ABA1E0C0C50E97D#第05集$id_XS0622EA8ABA1E0C0C50E97C#第06集$id_XS0622EA8ABA1E0C0C50E97F#第07集$id_XS0622EA8ABA1E0C0C50E97E#第08集$id_XS0622EA8ABA1E0C0C50E971#第09集$id_XS0622EA8ABA1E0C0C50E970#第10集$id_XS0622EA8ABA1E0C0C50E879#第11集$id_XS0622EA8ABA1E0C0C50E878#第12集$id_XS0622EA8ABA1E0C0C50E87B$$$第01集$id_MOE0622EA8ABA1E0C0C50E978#第02集$id_MOE0622EA8ABA1E0C0C50E97B#第03集$id_MOE0622EA8ABA1E0C0C50E97A#第04集$id_MOE0622EA8ABA1E0C0C50E97D#第05集$id_MOE0622EA8ABA1E0C0C50E97C#第06集$id_MOE0622EA8ABA1E0C0C50E97F#第07集$id_MOE0622EA8ABA1E0C0C50E97E#第08集$id_MOE0622EA8ABA1E0C0C50E971#第09集$id_MOE0622EA8ABA1E0C0C50E970#第10集$id_MOE0622EA8ABA1E0C0C50E879#第11集$id_MOE0622EA8ABA1E0C0C50E878#第12集$id_MOE0622EA8ABA1E0C0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (8, 1, 0, 0, '大叔新人冒险者 被最强小队拼死锻炼后无敌了', '新米オッサン冒険者、最強パーティに死ぬほど鍛えられて無敵になる。', 'dashuxinrenmaoxianzhebeizuiqiangxiaoduipinsiduanlianhouwudiliao', 1, 'D', '', 'f4a88dcd', '冒险,奇幻,魔法', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2904975166.jpg', '', '', '', '小西克幸,长冈龙步,德留慎乃佑,木村良平,下地紫野,久野美咲,丰永利行,三宅健太,大西沙织,佐藤拓也', '片贝慎', '', '', '　　起步太晚…？不管从几岁开始当冒险者、不管从几岁开始新事物…根本没差吧！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 5.5, 0, 0, 1730812161, 1724759873, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　起步太晚…？不管从几岁开始当冒险者、不管从几岁开始新事物…根本没差吧！<br/>　　『想成为冒险者，最好趁年轻比较好』可是那个男人却是过了30岁才开始。目标成为冒险者的里克‧古拉迪亚特尔，明明是个新人却有着与最高等级S级同等战斗力。<br/>　　靠着由传说队伍「奥利哈康之拳」──这个从龙到吸血鬼，名符其实的「怪物」级师父们所操出来的战斗力，将那些小看他的菁英冒险者全都打趴在地。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5723ED80B14D0E5D50E978#第02集$MOE5723ED80B14D0E5D50E97B#第03集$MOE5723ED80B14D0E5D50E97A#第04集$MOE5723ED80B14D0E5D50E97D#第05集$MOE5723ED80B14D0E5D50E97C#第06集$MOE5723ED80B14D0E5D50E97F#第07集$MOE5723ED80B14D0E5D50E97E#第08集$MOE5723ED80B14D0E5D50E971#第09集$MOE5723ED80B14D0E5D50E970#第10集$MOE5723ED80B14D0E5D50E879#第11集$MOE5723ED80B14D0E5D50E878#第12集$MOE5723ED80B14D0E5D50E87B$$$第01集$id_XS5723ED80B14D0E5D50E978#第02集$id_XS5723ED80B14D0E5D50E97B#第03集$id_XS5723ED80B14D0E5D50E97A#第04集$id_XS5723ED80B14D0E5D50E97D#第05集$id_XS5723ED80B14D0E5D50E97C#第06集$id_XS5723ED80B14D0E5D50E97F#第07集$id_XS5723ED80B14D0E5D50E97E#第08集$id_XS5723ED80B14D0E5D50E971#第09集$id_XS5723ED80B14D0E5D50E970#第10集$id_XS5723ED80B14D0E5D50E879#第11集$id_XS5723ED80B14D0E5D50E878#第12集$id_XS5723ED80B14D0E5D50E87B$$$第01集$id_MOE5723ED80B14D0E5D50E978#第02集$id_MOE5723ED80B14D0E5D50E97B#第03集$id_MOE5723ED80B14D0E5D50E97A#第04集$id_MOE5723ED80B14D0E5D50E97D#第05集$id_MOE5723ED80B14D0E5D50E97C#第06集$id_MOE5723ED80B14D0E5D50E97F#第07集$id_MOE5723ED80B14D0E5D50E97E#第08集$id_MOE5723ED80B14D0E5D50E971#第09集$id_MOE5723ED80B14D0E5D50E970#第10集$id_MOE5723ED80B14D0E5D50E879#第11集$id_MOE5723ED80B14D0E