INSERT INTO `mac_vod` VALUES (11, 1, 0, 0, '我的妻子没有感情', '僕の妻は感情がない', 'wodeqizimeiyouganqing', 1, 'W', '', 'dba48e22', '漫画改,科幻,恋爱,日常', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2909248016.jpg', '', '', '', '若井友希,松田利冴,芹泽优,青山吉能,稻垣好,丰永利行', '吉村文宏', '', '', '　　独居三年的社畜拓真为减轻家务负担买来了家务机器人米娜，和“没有感情”的机器人同居的心动故事开始了！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 78, 0, 78, 78, '', 0, 0, 6.2, 0, 0, 1730817128, 1724762236, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　独居三年的社畜拓真为减轻家务负担买来了家务机器人米娜，和“没有感情”的机器人同居的心动故事开始了！</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5575ED8CB14C5F0B50E978#第02集$MOE5575ED8CB14C5F0B50E97B#第03集$MOE5575ED8CB14C5F0B50E97A#第04集$MOE5575ED8CB14C5F0B50E97D#第05集$MOE5575ED8CB14C5F0B50E97C#第06集$MOE5575ED8CB14C5F0B50E97F#第07集$MOE5575ED8CB14C5F0B50E97E#第08集$MOE5575ED8CB14C5F0B50E971#第09集$MOE5575ED8CB14C5F0B50E970#第10集$MOE5575ED8CB14C5F0B50E879#第11集$MOE5575ED8CB14C5F0B50E878#第12集$MOE5575ED8CB14C5F0B50E87B$$$第01集$id_XS5575ED8CB14C5F0B50E978#第02集$id_XS5575ED8CB14C5F0B50E97B#第03集$id_XS5575ED8CB14C5F0B50E97A#第04集$id_XS5575ED8CB14C5F0B50E97D#第05集$id_XS5575ED8CB14C5F0B50E97C#第06集$id_XS5575ED8CB14C5F0B50E97F#第07集$id_XS5575ED8CB14C5F0B50E97E#第08集$id_XS5575ED8CB14C5F0B50E971#第09集$id_XS5575ED8CB14C5F0B50E970#第10集$id_XS5575ED8CB14C5F0B50E879#第11集$id_XS5575ED8CB14C5F0B50E878#第12集$id_XS5575ED8CB14C5F0B50E87B$$$第01集$id_MOE5575ED8CB14C5F0B50E978#第02集$id_MOE5575ED8CB14C5F0B50E97B#第03集$id_MOE5575ED8CB14C5F0B50E97A#第04集$id_MOE5575ED8CB14C5F0B50E97D#第05集$id_MOE5575ED8CB14C5F0B50E97C#第06集$id_MOE5575ED8CB14C5F0B50E97F#第07集$id_MOE5575ED8CB14C5F0B50E97E#第08集$id_MOE5575ED8CB14C5F0B50E971#第09集$id_MOE5575ED8CB14C5F0B50E970#第10集$id_MOE5575ED8CB14C5F0B50E879#第11集$id_MOE5575ED8CB14C5F0B50E878#第12集$id_MOE5575ED8CB14C5F0B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (12, 1, 0, 0, '我回来了，欢迎回来', 'ただいま、おかえり', 'wohuilailiaohuanyinghuilai', 1, 'W', '', 'c517920', '漫画改', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2904448899.jpg', '', '', '', '兴津和幸,增田俊树,本渡枫,浅沼晋太郎,鸟海浩辅,八代拓,小原好美,种崎敦美,森川智之,田丸笃志', '石平信司', '', '', '　　いちかわ壱原作漫画《我回来了，欢迎回来》（ただいま、おかえり）宣布改编成动画。该作是一部描写家庭的 BL 故事。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 7.2, 0, 0, 1731057025, 1724762482, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　いちかわ壱原作漫画《我回来了，欢迎回来》（ただいま、おかえり）宣布改编成动画。该作是一部描写家庭的 BL 故事。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5222BD8FB01B5D144DE8#第02集$MOE5222BD8FB01B5D144DEB#第03集$MOE5222BD8FB01B5D144DEA#第04集$MOE5222BD8FB01B5D144DED#第05集$MOE5222BD8FB01B5D144DEC#第06集$MOE5222BD8FB01B5D144DEF#第07集$MOE5222BD8FB01B5D144DEE#第08集$MOE5222BD8FB01B5D144DE1#第09集$MOE5222BD8FB01B5D144DE0#第10集$MOE5222BD8FB01B5D144CE9#第11集$MOE5222BD8FB01B5D144CE8#第12集$MOE5222BD8FB01B5D144CEB$$$第01集$id_XS5222BD8FB01B5D144DE8#第02集$id_XS5222BD8FB01B5D144DEB#第03集$id_XS5222BD8FB01B5D144DEA#第04集$id_XS5222BD8FB01B5D144DED#第05集$id_XS5222BD8FB01B5D144DEC#第06集$id_XS5222BD8FB01B5D144DEF#第07集$id_XS5222BD8FB01B5D144DEE#第08集$id_XS5222BD8FB01B5D144DE1#第09集$id_XS5222BD8FB01B5D144DE0#第10集$id_XS5222BD8FB01B5D144CE9#第11集$id_XS5222BD8FB01B5D144CE8#第12集$id_XS5222BD8FB01B5D144CEB$$$第01集$id_MOE5222BD8FB01B5D144DE8#第02集$id_MOE5222BD8FB01B5D144DEB#第03集$id_MOE5222BD8FB01B5D144DEA#第04集$id_MOE5222BD8FB01B5D144DED#第05集$id_MOE5222BD8FB01B5D144DEC#第06集$id_MOE5222BD8FB01B5D144DEF#第07集$id_MOE5222BD8FB01B5D144DEE#第08集$id_MOE5222BD8FB01B5D144DE1#第09集$id_MOE5222BD8FB01B5D144DE0#第10集$id_MOE5222BD8FB01B5D144CE9#第11集$id_MOE5222BD8FB01B5D144CE8#第12集$id_MOE5222BD8FB01B5D144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (285, 1, 0, 0, '某天早上变成人头麦克风的我君的人生', 'ある朝、ダミーヘッドマイクになっていた俺クンの人生（2022）', 'moutianzaoshangbianchengrentoumaikefengdewojunderensheng', 1, 'M', '', 'f5b553', '泡面', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2876134135.webp', '', '', '', '大西沙织 / 鬼头明里 / 相良茉优 / Lynn / 久保田未梦 / 水桥香织 / 杉田智和', '葛西良信', '', '', '讲述了转生为人头麦克风的“我君”和隶属于ASMR部、以“ASMR甲子园”为目标的女高中生百合们展开的闹剧故事。', '全12集', '', 0, '0', '', '', '日本', '十月', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 4.5, 0, 0, 1744109272, 1730944885, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>讲述了转生为人头麦克风的“我君”和隶属于ASMR部、以“ASMR甲子园”为目标的女高中生百合们展开的闹剧故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5722EE8DBC1A40094C#第02集$MOE5722EE8DBC1A40094F#第03集$MOE5722EE8DBC1A40094E#第04集$MOE5722EE8DBC1A400949#第05集$MOE5722EE8DBC1A400948#第06集$MOE5722EE8DBC1A40094B#第07集$MOE5722EE8DBC1A40094A#第08集$MOE5722EE8DBC1A400945#第09集$MOE5722EE8DBC1A400944#第10集$MOE5722EE8DBC1A40084D#第11集$MOE5722EE8DBC1A40084C#第12集$MOE5722EE8DBC1A40084F$$$第01集$id_XS5722EE8DBC1A40094C#第02集$id_XS5722EE8DBC1A40094F#第03集$id_XS5722EE8DBC1A40094E#第04集$id_XS5722EE8DBC1A400949#第05集$id_XS5722EE8DBC1A400948#第06集$id_XS5722EE8DBC1A40094B#第07集$id_XS5722EE8DBC1A40094A#第08集$id_XS5722EE8DBC1A400945#第09集$id_XS5722EE8DBC1A400944#第10集$id_XS5722EE8DBC1A40084D#第11集$id_XS5722EE8DBC1A40084C#第12集$id_XS5722EE8DBC1A40084F$$$第01集$id_MOE5722EE8DBC1A40094C#第02集$id_MOE5722EE8DBC1A40094F#第03集$id_MOE5722EE8DBC1A40094E#第04集$id_MOE5722EE8DBC1A400949#第05集$id_MOE5722EE8DBC1A400948#第06集$id_MOE5722EE8DBC1A40094B#第07集$id_MOE5722EE8DBC1A40094A#第08集$id_MOE5722EE8DBC1A400945#第09集$id_MOE5722EE8DBC1A400944#第10集$id_MOE5722EE8DBC1A40084D#第11集$id_MOE5722EE8DBC1A40084C#第12集$id_MOE5722EE8DBC1A40084F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (13, 1, 0, 0, '异世界失格', '異世界失格', 'yishijieshige', 1, 'Y', '', '993b5e19', '漫画改,异世界,搞笑,奇幻', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2909121018.jpg', '', '', '', '上田丽奈,杉田智和,小原好美,小野大辅,冈本信彦,岛崎信长,中原麻衣,悠木碧,木野日菜,小市真琴,铃代纱弓,大久保瑠美,神谷浩史', '河合滋树', '', '', '　　著名的大文豪在那个夜晚，与他心爱的人来到玉川上水。为了亲自了结他&amp;quot;可耻的生涯&amp;quot;。然而在此同时，那台惯例的卡车突然出现…', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 5.5, 0, 0, 1730926950, 1724762621, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　著名的大文豪在那个夜晚，与他心爱的人来到玉川上水。为了亲自了结他&quot;可耻的生涯&quot;。然而在此同时，那台惯例的卡车突然出现…<br/>　　这位作家来到异世界，按道理应该获得特殊的&quot;神授之力&quot;，结果他的状态列居然是前所未有的劣等。<br/>　　&quot;你没有在这里活下去的才能，甚至没有那个资格！&quot;<br/>　　在异世界也同样失格的作家，他崭新的冒险故事，在这里开幕。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE082EBFDABC4C5C0050E978#第02集$MOE082EBFDABC4C5C0050E97B#第03集$MOE082EBFDABC4C5C0050E97A#第04集$MOE082EBFDABC4C5C0050E97D#第05集$MOE082EBFDABC4C5C0050E97C#第06集$MOE082EBFDABC4C5C0050E97F#第07集$MOE082EBFDABC4C5C0050E97E#第08集$MOE082EBFDABC4C5C0050E971#第09集$MOE082EBFDABC4C5C0050E970#第10集$MOE082EBFDABC4C5C0050E879#第11集$MOE082EBFDABC4C5C0050E878#第12集$MOE082EBFDABC4C5C0050E87B$$$第01集$id_XS082EBFDABC4C5C0050E978#第02集$id_XS082EBFDABC4C5C0050E97B#第03集$id_XS082EBFDABC4C5C0050E97A#第04集$id_XS082EBFDABC4C5C0050E97D#第05集$id_XS082EBFDABC4C5C0050E97C#第06集$id_XS082EBFDABC4C5C0050E97F#第07集$id_XS082EBFDABC4C5C0050E97E#第08集$id_XS082EBFDABC4C5C0050E971#第09集$id_XS082EBFDABC4C5C0050E970#第10集$id_XS082EBFDABC4C5C0050E879#第11集$id_XS082EBFDABC4C5C0050E878#第12集$id_XS082EBFDABC4C5C0050E87B$$$第01集$id_MOE082EBFDABC4C5C0050E978#第02集$id_MOE082EBFDABC4C5C0050E97B#第03集$id_MOE082EBFDABC4C5C0050E97A#第04集$id_MOE082EBFDABC4C5C0050E97D#第05集$id_MOE082EBFDABC4C5C0050E97C#第06集$id_MOE082EBFDABC4C5C0050E97F#第07集$id_MOE082EBFDABC4C5C0050E97E#第08集$id_MOE082EBFDABC4C5C0050E971#第09集$id_MOE082EBFDABC4C5C0050E970#第10集$id_MOE082EBFDABC4C5C0050E879#第11集$id_MOE082EBFDABC4C5C0050E878#第12集$id_MO