INSERT INTO `mac_vod` VALUES (1256, 1, 0, 0, '搞笑漫画日和GO', '増田こうすけ劇場 ギャグマンガ日和GO（2025）', 'gaoxiaomanhuariheGO', 1, 'G', '', 'c6668422', '漫画改,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/d134786861858d45dbb8135b21e1b0b827cb774d.png', 'https://i0.hdslb.com/bfs/archive/415a6cac796474a2712009c187bf370ef91d9546.jpg', '', '', '上田祐司 / 名冢佳织 / 前田刚 / 竹本英史 / 矢部雅史 / 内藤玲 / 佐藤成美 / 小野贤章', '大地丙太郎 / たなかかずや / 湖山真奈美 / 大山佳久', '', '', '多年之后，他们又回来了！\r\n《搞笑漫画日和》时隔15年再次动画化！圣德太子、松尾芭蕉、兔美等多姿多彩的人物，通过增田幸助的超现实搞笑，将人们拖入其独特的世界观。每集都有个性丰富的角色登场，敬请期待！', '更新至第02集', '', 0, '0', '', '（每周六）22:30更新', '日本', '四月', '2025', '', '', '', '', '', '', '', 0, 0, 6, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 0.0, 0, 0, 1744472034, 1743902418, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>多年之后，他们又回来了！\r\n《搞笑漫画日和》时隔15年再次动画化！圣德太子、松尾芭蕉、兔美等多姿多彩的人物，通过增田幸助的超现实搞笑，将人们拖入其独特的世界观。每集都有个性丰富的角色登场，敬请期待！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5221BA8EB11D5F0B50E978#第02集$MOE5221BA8EB11D5F0B50E97B$$$第01集$id_XS5221BA8EB11D5F0B50E978#第02集$id_XS5221BA8EB11D5F0B50E97B$$$第01集$id_MOE5221BA8EB11D5F0B50E978#第02集$id_MOE5221BA8EB11D5F0B50E97B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1251, 1, 0, 0, '小智是女孩啦！', 'トモちゃんは女の子！（2023）', 'xiaozhishinvhaila', 1, 'X', '', '2abf50c1', '漫画改,校园,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2884412021.jpg', '', '', '', '高桥李依 / 石川界人 / 日高里菜 / 天城莎莉 / 天崎滉平 / 松冈祯丞', '难波日登志 / 桥本能理子 / 水本叶月 / 塚田拓郎 / 安藤健 / 深濑重 / 则座诚', '', '', '女高中生相泽智对自己的青梅竹马久保田淳一郎说出“我喜欢你！”的表白，对方却以为是“挚友”的宣言，“充满男子气概”的女孩子想被喜欢的人“当成女生”看待，结果总是加深两人的男子友情，环绕两人的恋爱喜剧。', '全13集', '', 0, '0', '', '', '日本', '一月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 1, 16, 16, '', 0, 0, 7.5, 0, 0, 1743857215, 1743847154, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>女高中生相泽智对自己的青梅竹马久保田淳一郎说出“我喜欢你！”的表白，对方却以为是“挚友”的宣言，“充满男子气概”的女孩子想被喜欢的人“当成女生”看待，结果总是加深两人的男子友情，环绕两人的恋爱喜剧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0376EEDEBC190E0850E978#第02集$MOE0376EEDEBC190E0850E97B#第03集$MOE0376EEDEBC190E0850E97A#第04集$MOE0376EEDEBC190E0850E97D#第05集$MOE0376EEDEBC190E0850E97C#第06集$MOE0376EEDEBC190E0850E97F#第07集$MOE0376EEDEBC190E0850E97E#第08集$MOE0376EEDEBC190E0850E971#第09集$MOE0376EEDEBC190E0850E970#第10集$MOE0376EEDEBC190E0850E879#第11集$MOE0376EEDEBC190E0850E878#第12集$MOE0376EEDEBC190E0850E87B#第13集$MOE0376EEDEBC190E0850E87A$$$第01集$id_XS0376EEDEBC190E0850E978#第02集$id_XS0376EEDEBC190E0850E97B#第03集$id_XS0376EEDEBC190E0850E97A#第04集$id_XS0376EEDEBC190E0850E97D#第05集$id_XS0376EEDEBC190E0850E97C#第06集$id_XS0376EEDEBC190E0850E97F#第07集$id_XS0376EEDEBC190E0850E97E#第08集$id_XS0376EEDEBC190E0850E971#第09集$id_XS0376EEDEBC190E0850E970#第10集$id_XS0376EEDEBC190E0850E879#第11集$id_XS0376EEDEBC190E0850E878#第12集$id_XS0376EEDEBC190E0850E87B#第13集$id_XS0376EEDEBC190E0850E87A$$$第01集$id_MOE0376EEDEBC190E0850E978#第02集$id_MOE0376EEDEBC190E0850E97B#第03集$id_MOE0376EEDEBC190E0850E97A#第04集$id_MOE0376EEDEBC190E0850E97D#第05集$id_MOE0376EEDEBC190E0850E97C#第06集$id_MOE0376EEDEBC190E0850E97F#第07集$id_MOE0376EEDEBC190E0850E97E#第08集$id_MOE0376EEDEBC190E0850E971#第09集$id_MOE0376EEDEBC190E0850E970#第10集$id_MOE0376EEDEBC190E0850E879#第11集$id_MOE0376EEDEBC190E0850E878