INSERT INTO `mac_vod` VALUES (22, 1, 0, 0, '百变的七仓同学', '疑似ハーレム（2024）', 'baibiandeqicangtongxue', 1, 'B', '', 'c3e225f0', '漫画改,校园,恋爱,日常', 'https://i0.hdslb.com/bfs/bangumi/image/931732241f619bb9c577dbaab19e52e143e2022d.png', '', '', '', '早见沙织 / 冈本信彦', '菊池聪延', '', '', '憧憬着成为像漫画里那样超人气角色的学长“北浜瑛二”，以及在演技方面天赋异禀的“七仓凛” 。七仓同学在和学长的相处过程中，常常扮演不同性格作为演技练习，小剧场式的相处模式让他们的校园生活变得有趣许多。同', '全12集', '', 0, '0', '', '', '日本', '七月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 32, 0, 32, 32, '', 0, 0, 9.8, 0, 0, 1743572634, 1725141484, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>憧憬着成为像漫画里那样超人气角色的学长“北浜瑛二”，以及在演技方面天赋异禀的“七仓凛” 。七仓同学在和学长的相处过程中，常常扮演不同性格作为演技练习，小剧场式的相处模式让他们的校园生活变得有趣许多。同处戏剧社的两人之间会产生什么火花？ 七仓凛能够以真实的自己将心意传达给学长吗？！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5224E98ABB1C0B0950E978#第02集$MOE5224E98ABB1C0B0950E97B#第03集$MOE5224E98ABB1C0B0950E97A#第04集$MOE5224E98ABB1C0B0950E97D#第05集$MOE5224E98ABB1C0B0950E97C#第06集$MOE5224E98ABB1C0B0950E97F#第07集$MOE5224E98ABB1C0B0950E97E#第08集$MOE5224E98ABB1C0B0950E971#第09集$MOE5224E98ABB1C0B0950E970#第10集$MOE5224E98ABB1C0B0950E879#第11集$MOE5224E98ABB1C0B0950E878#第12集$MOE5224E98ABB1C0B0950E87B$$$第01集$id_XS5224E98ABB1C0B0950E978#第02集$id_XS5224E98ABB1C0B0950E97B#第03集$id_XS5224E98ABB1C0B0950E97A#第04集$id_XS5224E98ABB1C0B0950E97D#第05集$id_XS5224E98ABB1C0B0950E97C#第06集$id_XS5224E98ABB1C0B0950E97F#第07集$id_XS5224E98ABB1C0B0950E97E#第08集$id_XS5224E98ABB1C0B0950E971#第09集$id_XS5224E98ABB1C0B0950E970#第10集$id_XS5224E98ABB1C0B0950E879#第11集$id_XS5224E98ABB1C0B0950E878#第12集$id_XS5224E98ABB1C0B0950E87B$$$第01集$id_MOE5224E98ABB1C0B0950E978#第02集$id_MOE5224E98ABB1C0B0950E97B#第03集$id_MOE5224E98ABB1C0B0950E97A#第04集$id_MOE5224E98ABB1C0B0950E97D#第05集$id_MOE5224E98ABB1C0B0950E97C#第06集$id_MOE5224E98ABB1C0B0950E97F#第07集$id_MOE5224E98ABB1C0B0950E97E#第08集$id_MOE5224E98ABB1C0B0950E971#第09集$id_MOE5224E98ABB1C0B0950E970#第10集$id_MOE5224E98ABB1C0B0950E879#第11集$id_MOE5224E98ABB1C0B0950E878#第12集$id_MOE5224E98ABB1C0B0950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (23, 1, 0, 0, '义妹生活', '義妹生活', 'yimeishenghuo', 1, 'Y', '', '1c6f4a5b', '小说改,日常,校园,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2909766261.jpg', 'https://i0.hdslb.com/bfs/archive/36fd4205c82d07bd15a730f8fb9be80393e98b51.jpg', '', '', '铃木爱唯,铃木实里,滨野大辉,中岛由贵,天崎滉平', '上野壮大', '', '', '　　缩短距离，构筑关系的日常。\r\n                                    \r\n                                　　高中生和美少女的同居生活。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 136, 0, 136, 136, '', 0, 0, 8.1, 0, 0, 1730815247, 1725145249, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　缩短距离，构筑关系的日常。<br/>　　高中生和美少女的同居生活。<br/>　　因为悲惨的家庭环境，对男女关系持有封闭价值观的二人约定对彼此不抱期待。<br/>　　一个渴望爱而努力，不懂撒娇的沙季和作为她的哥哥却感到迷茫的悠太。<br/>　　殊途同归的二人，渐渐相识相知……<br/>　　不知何时会亲情变质的故事……<br/>　　素昧平生的男女互相接近并彼此改变的恋爱物语。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0074BADEBD48585B50E978#第02集$MOE0074BADEBD48585B50E97B#第03集$MOE0074BADEBD48585B50E97A#第04集$MOE0074BADEBD48585B50E97D#第05集$MOE0074BADEBD48585B50E97C#第06集$MOE0074BADEBD48585B50E97F#第07集$MOE0074BADEBD48585B50E97E#第08集$MOE0074BADEBD48585B50E971#第09集$MOE0074BADEBD48585B50E970#第10集$MOE0074BADEBD48585B50E879#第11集$MOE0074BADEBD48585B50E878#第12集$MOE0074BADEBD48585B50E87B$$$第01集$id_XS0074BADEBD48585B50E978#第02集$id_XS0074BADEBD48585B50E97B#第03集$id_XS0074BADEBD48585B50E97A#第04集$id_XS0074BADEBD48585B50E97D#第05集$id_XS0074BADEBD48585B50E97C#第06集$id_XS0074BADEBD48585B50E97F#第07集$id_XS0074BADEBD48585B50E97E#第08集$id_XS0074BADEBD48585B50E971#第09集$id_XS0074BADEBD48585B50E970#第10集$id_XS0074BADEBD48585B50E879#第11集$id_XS0074BADEBD48585B50E878#第12集$id_XS0074BADEBD48585B50E87B$$$第01集$id_MOE0074BADEBD48585B50E978#第02集$id_MOE0074BADEBD48585B50E97B#第03集$id_MOE0074BADEBD48585B50E97A#第04集$id_MOE0074BADEBD48585B50E97D#第05集$id_MOE0074BADEBD48585B50E97C#第06集$id_MOE0074BADEBD48585B50E97F#第07集$id_MOE0074BADEBD48585B50E97E#第08集$id_MOE0074BADEBD48585B50E971#第09集$id_MOE0074BADEBD48585B50E970#第10集$id_MOE0074BADEBD48585B5