INSERT INTO `mac_vod` VALUES (24, 1, 0, 0, 'X特遣队的奇幻之旅', '', 'Xteqianduideqihuanzhilv', 1, 'X', '', '4d894f65', '原创,奇幻,冒险', 'https://i0.hdslb.com/bfs/bangumi/image/db55798b3c57622957a503a88b1dedd18ea249fd.png', '', '', '', '哈莉·奎茵：永濑安奈\n小丑：梅原裕一郎\n死亡射手：山口令悟\n和平使者：子安武人\n泥脸：福山润\n鲨鱼王：木村昴\n武士刀：安济知佳\n阿曼达·沃勒：鲸\n菲奥娜：上田丽奈\n塞西尔：福岛润', '长田绘里', '', '', '哈莉·奎茵、小丑、DC漫画中的反派一同来到“异世界”？！\n豁出性命的部队——自杀小队在异世界大闹一场！！横扫千军！！\n日本新作原创动画，以最强阵容为世界带来的最疯狂异世界“暴”险奇幻剧，隆重开幕！！', '全10集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 23, 0, 23, 23, '', 0, 0, 8.8, 0, 0, 1730930385, 1725145563, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>哈莉·奎茵、小丑、DC漫画中的反派一同来到“异世界”？！\n豁出性命的部队——自杀小队在异世界大闹一场！！横扫千军！！\n日本新作原创动画，以最强阵容为世界带来的最疯狂异世界“暴”险奇幻剧，隆重开幕！！</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0573B481BD4F5B0C50E978#第02集$MOE0573B481BD4F5B0C50E97B#第03集$MOE0573B481BD4F5B0C50E97A#第04集$MOE0573B481BD4F5B0C50E97D#第05集$MOE0573B481BD4F5B0C50E97C#第06集$MOE0573B481BD4F5B0C50E97F#第07集$MOE0573B481BD4F5B0C50E97E#第08集$MOE0573B481BD4F5B0C50E971#第09集$MOE0573B481BD4F5B0C50E970#第10集$MOE0573B481BD4F5B0C50E879$$$第01集$id_XS0573B481BD4F5B0C50E978#第02集$id_XS0573B481BD4F5B0C50E97B#第03集$id_XS0573B481BD4F5B0C50E97A#第04集$id_XS0573B481BD4F5B0C50E97D#第05集$id_XS0573B481BD4F5B0C50E97C#第06集$id_XS0573B481BD4F5B0C50E97F#第07集$id_XS0573B481BD4F5B0C50E97E#第08集$id_XS0573B481BD4F5B0C50E971#第09集$id_XS0573B481BD4F5B0C50E970#第10集$id_XS0573B481BD4F5B0C50E879$$$第01集$id_MOE0573B481BD4F5B0C50E978#第02集$id_MOE0573B481BD4F5B0C50E97B#第03集$id_MOE0573B481BD4F5B0C50E97A#第04集$id_MOE0573B481BD4F5B0C50E97D#第05集$id_MOE0573B481BD4F5B0C50E97C#第06集$id_MOE0573B481BD4F5B0C50E97F#第07集$id_MOE0573B481BD4F5B0C50E97E#第08集$id_MOE0573B481BD4F5B0C50E971#第09集$id_MOE0573B481BD4F5B0C50E970#第10集$id_MOE0573B481BD4F5B0C50E879', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (25, 1, 0, 0, '我要【招架】一切', '俺は全てを【パリイ】する〜逆勘違いの世界最強は冒険者になりたい〜', 'woyaozhaojiayiqie', 1, 'W', '', 'dbb34488', '冒险,奇幻,魔法', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2908184018.jpg', 'https://i0.hdslb.com/bfs/archive/0ffa3ef877abd9203b713749d77a9603450dbb6d.png', '', '', '武内骏辅,村濑步,羽多野涉,宇垣秀成,关俊彦,丰口惠美,三宅健太,三木真一郎,寺岛惇太,山野井仁,森奈奈子,前川凉子,滨野大辉', '福山大', '', '', '　　“我在所有领域都没有才能！！”被烙下【无能】烙印的我，依靠【招架】成为最强！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 5.7, 0, 0, 1730929260, 1725162049, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　“我在所有领域都没有才能！！”被烙下【无能】烙印的我，依靠【招架】成为最强！<br/>　　“毫无才能的少年”被如此称呼的离开养成所的男人：诺德。隐居起来的他，自那之后十多年每天都独自进行着防御技能【招架】的修行。然后在一天，自从将被灾害级魔物弥诺陶洛斯袭击的公主莉恩救下后，诺德命运的齿轮便开始向着意想不到的方向转动。尽管诺德只是个最低级的冒险者，却被提拔为莉恩的指导。然而诺德那不论是谁都不能不认同的空前绝后的能力，现在却只有诺德一人不知晓这一点。而种种可怖阴谋仍然接连向诺德与莉恩袭来！这位毫无自觉的最强人士终究能否拯救陷入危机的王国呢？！</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5575EE8BBD1D550150E978#第02集$MOE5575EE8BBD1D550150E97B#第03集$MOE5575EE8BBD1D550150E97A#第04集$MOE5575EE8BBD1D550150E97D#第05集$MOE5575EE8BBD1D550150E97C#第06集$MOE5575EE8BBD1D550150E97F#第07集$MOE5575EE8BBD1D550150E97E#第08集$MOE5575EE8BBD1D550150E971#第09集$MOE5575EE8BBD1D550150E970#第10集$MOE5575EE8BBD1D550150E879#第11集$MOE5575EE8BBD1D550150E878#第12集$MOE5575EE8BBD1D550150E87B$$$第01集$id_XS5575EE8BBD1D550150E978#第02集$id_XS5575EE8BBD1D550150E97B#第03集$id_XS5575EE8BBD1D550150E97A#第04集$id_XS5575EE8BBD1D550150E97D#第05集$id_XS5575EE8BBD1D550150E97C#第06集$id_XS5575EE8BBD1D550150E97F#第07集$id_XS5575EE8BBD1D550150E97E#第08集$id_XS5575EE8BBD1D550150E971#第09集$id_XS5575EE8BBD1D550150E970#第10集$id_XS5575EE8BBD1D550150E879#第11集$id_XS5575EE8BBD1D550150E878#第12集$id_XS5575EE8BBD1D550150E87B$$$第01集$id_MOE5575EE8BBD1D550150E978#第02集$id_MOE5575EE8BBD1D550150E97B#第03集$id_MOE5575EE8BBD1D550150E97A#第04集$id_MOE5575EE8BBD1D550150E97D#第05集$id_MOE5575EE8BBD1D550150E97C#第06集$id_MOE5575EE8BBD1D550150E97F#第07集$id_MOE5575EE8BBD1D550150E97E#第08集$id_MOE5575EE8BBD1D550150E971#第09集$id_MOE5575EE8BBD1D550150E970#第10集$id_MOE5575EE8BBD1D550150E879#第11集$id_MOE5575EE8BBD1D550150E878#第12集$id_MOE5575EE8BBD1D550150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (26, 1, 0, 0, '靠废柴技能【状态异常】成为最强的我将蹂躏一切', 'ハズレ枠の【状態異常スキル】で最強になった俺がすべてを蹂躙するまで', 'kaofeichaijinengzhuangtaiyichangchengweizuiqiangdewojiangroulinyiqie', 1, 'K', '', 'd518b12b', '异世界,奇幻,魔法,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2909559327.jpg', 'https://i0.hdslb.com/bfs/archive/3eadb11cd1541086ff0ddae5579d1dc363ed93b2.jpg', '', '', '汐入明日香,诹访部顺一,前田佳织里,早见沙织,山下大辉,平山笑美,长绳麻理亚,大桥贤一郎,水中雅章,奈波果林,小清水亚美,和多田美咲,上田瞳,津久井彩文,宫下早纪,铃木崚汰', '福田道生', '', '', '　　学校では空気な高校生、三森灯河はクラスメイトとともに勇者として異世界に召喚された。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 199, 0, 199, 199, '', 0, 0, 6.0, 0, 0, 1730932354, 1725166164, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　学校では空気な高校生、三森灯河はクラスメイトとともに勇者として異世界に召喚された。<br/>　　女神ヴィシスによってクラスメイトたちが次々にＳ級、Ａ級と能力を見出される中、灯河は最低ランクであるＥ級と宣言され『廃棄』対象となってしまう。<br/>　　生存率ゼロの遺跡に廃棄された灯河はハズレ枠と貶された【状態異常スキル】を駆使して遺跡脱出を試みる。<br/>　　その日から、女神ヴィシスへの復讐の炎を宿した青年は人畜無害な人間をやめ、心の奥底に隠していた本性を明かしていく……<br/>　　「はじめようか、生存競争を」</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5522BD80EB185F5B50E978#第02集$MOE5522BD80EB185F5B50E97B#第03集$MOE5522BD80EB185F5B50E97A#第04集$MOE5522BD80EB185F5B50E97D#第05集$MOE5522BD80EB185F5B50E97C#第06集$MOE5522BD80EB185F5B50E97F#第07集$MOE5522BD80EB185F5B50E97E#第08集$MOE5522BD80EB185F5B50E971#第09集$MOE5522BD80EB185F5B50E970#第10集$MOE5522BD80EB185F5B50E879#第11集$MOE5522BD80EB185F5B50E878#第12集$MOE5522BD80EB185F5B50E87B$$$第01集$id_XS5522BD80EB185F5B50E978#第02集$id_XS5522BD80EB185F5B50E97B#第03集$id_XS5522BD80EB185F5B50E97A#第04集$id_XS5522BD80EB185F5B50E97D#第05集$id_XS5522BD80EB185F5B50E97C#第06集$id_XS5522BD80EB185F5B50E97F#第07集$id_XS5522BD80EB185F5B50E97E#第08集$id_XS5522BD80EB185F5B50E971#第09集$id_XS5522BD80EB185F5B50E970#第10集$id_XS5522BD80EB185F5B50E879#第11集$id_XS5522BD80EB185F5B50E878#第12集$id_XS5522BD80EB185F5B50E87B$$$第01集$id_MOE5522BD80EB185F5B50E978#第02集$id_MOE5522BD80EB185F5B50E97B#第03集$id_MOE5522BD80EB185F5B50E97A#第04集$id_MOE5522BD80EB185F5B50E97D#第05集$id_MOE5522BD80EB185F5B50E97C#第06集$id_MOE5522BD80EB185F5B50E97F#第07集$id_MOE5522BD80EB185F5B50E97E#第08集$id_MOE5522BD80EB185F5B50E971#第09集$id_MOE5522BD80EB185F5B50E970#第10集$id_MOE5522BD80EB185F5B50E879#第11集$id_MOE5522BD80EB185F5B50E878#第12集$id_MOE5522BD80EB185F5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (27, 1, 0, 0, '前辈是男孩子', '先輩はおとこのこ Season 1', 'qianbeishinanhaizi', 1, 'Q', '', 'a81915e0', '校园,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2907812521.jpg', 'https://i0.hdslb.com/bfs/archive/2d23bb83665d25dbc211f49dd0c11c8012f5b600.jpg', '', '', '前田佳织里,中原麻衣,内田雄马,关根明良,梅田修一朗', '柳伸亮', '', '', '　　花季少女表白温柔女前辈，谁曾想前辈竟然是男生！？\r\n                                    \r\n                                　　女装', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 7.5, 0, 0, 1730780468, 1725228096, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　花季少女表白温柔女前辈，谁曾想前辈竟然是男生！？<br/>　　女装男子花冈真琴某日放学后收到了一封匿名信，“又是误以为我是女生的学弟的告白吧”，原本这么想的他遭到一年级女生苍井咲突如其来的告白。<br/>　　在真琴坦白了自己是伪娘后，咲非但没有失望反而狂喷鼻血：“简直太完美了，这代表我能同时享受男生版和女生版的前辈了！”<br/>　　虽然真琴还是拒绝了咲，但咲并未放弃，而是下定决心更要主动出击追到真琴！</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE502FBD81B81C080950E978#第02集$MOE502FBD81B81C080950E97B#第03集$MOE502FBD81B81C080950E97A#第04集$MOE502FBD81B81C080950E97D#第05集$MOE502FBD81B81C080950E97C#第06集$MOE502FBD81B81C080950E97F#第07集$MOE502FBD81B81C080950E97E#第08集$MOE502FBD81B81C080950E971#第09集$MOE502FBD81B81C080950E970#第10集$MOE502FBD81B81C080950E879#第11集$MOE502FBD81B81C080950E878#第12集$MOE502FBD81B81C080950E87B$$$第01集$id_XS502FBD81B81C080950E978#第02集$id_XS502FBD81B81C080950E97B#第03集$id_XS502FBD81B81C080950E97A#第04集$id_XS502FBD81B81C080950E97D#第05集$id_XS502FBD81B81C080950E97C#第06集$id_XS502FBD81B81C080950E97F#第07集$id_XS502FBD81B81C080950E97E#第08集$id_XS502FBD81B81C080950E971#第09集$id_XS502FBD81B81C080950E970#第10集$id_XS502FBD81B81C080950E879#第11集$id_XS502FBD81B81C080950E878#第12集$id_XS502FBD81B81C080950E87B$$$第01集$id_MOE502FBD81B81C080950E978#第02集$id_MOE502FBD81B81C080950E97B#第03集$id_MOE502FBD81B81C080950E97A#第04集$id_MOE502FBD81B81C080950E97D#第05集$id_MOE502FBD81B81C080950E97C#第06集$id_MOE502FBD81B81C080950E97F#第07集$id_MOE502FBD81B81C080950E97E#第08集$id_MOE502FBD81B81C080950E971#第09集$id_MOE502FBD81B81C080950E970#第10集$id_MOE502FBD81B81C080950E879#第11集$id_MOE502FBD81B81C080950E878#第12集$id_MOE502FBD81B81C080950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (28, 1, 0, 0, '女神咖啡厅', '女神のカフェテラス', 'nvshenkafeiting', 1, 'N', '', 'f79aa99c', '漫画改,搞笑,日常,恋爱,职场', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2888767906.jpg', '', '', '', '水中雅章 / 和气杏未 / 山根绮 / 铃代纱弓 / 濑户麻沙美 / 青木瑠璃子', '桑原智', '', '', '　　和命中注定的女孩子×5生活在同一个屋檐下！\r\n                                    \r\n                                　　东大应届入', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 64, 0, 64, 64, '', 0, 0, 6.8, 0, 0, 1733062936, 1725228910, 0, 0, 0, 0, 0.0, '', '29', '', '', '', '', '', '', '', '<p>　　和命中注定的女孩子×5生活在同一个屋檐下！<br/>　　东大应届入学的秀才粕壁隼，收到祖母的讣告后回到了阔别三年的老家——海边的一间老旧咖啡厅“Familia”。但他一推开门，就看到了5个不认识的女孩！而且她们还自称是“奶奶的家人”…<br/>　　本来打算把店拆了改成停车场赚钱的隼，在和女孩们相处过程中回想起与奶奶的过往，决定休学一年与五个女神一起共同生活，重新经营咖啡厅。<br/>　　女主角太多的海边爱情喜剧，开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5720B5D9E810545A50E978#第02集$MOE5720B5D9E810545A50E97B#第03集$MOE5720B5D9E810545A50E97A#第04集$MOE5720B5D9E810545A50E97D#第05集$MOE5720B5D9E810545A50E97C#第06集$MOE5720B5D9E810545A50E97F#第07集$MOE5720B5D9E810545A50E97E#第08集$MOE5720B5D9E810545A50E971#第09集$MOE5720B5D9E810545A50E970#第10集$MOE5720B5D9E810545A50E879#第11集$MOE5720B5D9E810545A50E878#第12集$MOE5720B5D9E810545A50E87B$$$第01集$id_XS5720B5D9E810545A50E978#第02集$id_XS5720B5D9E810545A50E97B#第03集$id_XS5720B5D9E810545A50E97A#第04集$id_XS5720B5D9E810545A50E97D#第05集$id_XS5720B5D9E810545A50E97C#第06集$id_XS5720B5D9E810545A50E97F#第07集$id_XS5720B5D9E810545A50E97E#第08集$id_XS5720B5D9E810545A50E971#第09集$id_XS5720B5D9E810545A50E970#第10集$id_XS5720B5D9E810545A50E879#第11集$id_XS5720B5D9E810545A50E878#第12集$id_XS5720B5D9E810545A50E87B$$$第01集$id_MOE5720B5D9E810545A50E978#第02集$id_MOE5720B5D9E810545A50E97B#第03集$id_MOE5720B5D9E810545A50E97A#第04集$id_MOE5720B5D9E810545A50E97D#第05集$id_MOE5720B5D9E810545A50E97C#第06集$id_MOE5720B5D9E810545A50E97F#第07集$id_MOE5720B5D9E810545A50E97E#第08集$id_MOE5720B5D9E810545A50E971#第09集$id_MOE5720B5D9E810545A50E970#第10集$id_MOE5720B5D9E810545A50E879#第11集$id_MOE5720B5D9E810545A50E878#第12集$id_MOE5720B5D9E810545A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (29, 1, 0, 0, '女神的露天咖啡厅 第二季', '女神のカフェテラス 第2期 Season 2', 'nvshendelutiankafeitingdierji', 1, 'N', '', '25f95a20', '漫画改,搞笑,日常,恋爱,职场', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2911451030.jpg', 'https://i0.hdslb.com/bfs/archive/cf671ebceeea5a55916506370ed01a7a601bab62.jpg', '', '', '伊仓一惠,上坂堇,芹泽优,花泽香菜,上田丽奈,竹达彩奈,高桥李依,青木瑠璃子,濑户麻沙美,铃代纱弓,山根绮,和气杏未,水中雅章', '桑原智', '', '', '　　——どこかの海辺にある、古びた喫茶店。\r\n                                    \r\n                                　　そこには…女神', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 77, 0, 77, 77, '', 0, 0, 0.0, 0, 0, 1730780509, 1725228922, 0, 0, 0, 0, 0.0, '', '28', '', '', '', '', '', '', '', '<p>　　——どこかの海辺にある、古びた喫茶店。<br/>　　そこには…女神様がいるらしい——<br/>　　ケンカ別れした祖母が遺した喫茶店「Familia」を継いだ主人公・粕壁 隼。<br/>　　そこには「おばあちゃんの家族」を語る見知らぬ５人の女神（カワイイ女の子）が！<br/>　　初めは衝突ばかりだったが、それぞれの過去や、<br/>　　家庭の事情を知った隼と女神たちの尽力によって様々な問題を乗り越えてきた「Familia」。<br/>　　しかし…<br/>　　隣にまさかのライバル店が⁉<br/>　　そこには5人の新たなカワイイ女の子が⁉<br/>　　そして祖母の代から続く不思議な縁が、隼と女神たちの関係をさらに深めていき…⁉<br/>　　“恋”と“家族”の六角関係が大きく動き出す！<br/>　　5人全員「正ヒロイン」の、ヒロイン多すぎシーサイドラブコメが再びここに開幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0322EA81BC485F0950E978#第02集$MOE0322EA81BC485F0950E97B#第03集$MOE0322EA81BC485F0950E97A#第04集$MOE0322EA81BC485F0950E97D#第05集$MOE0322EA81BC485F0950E97C#第06集$MOE0322EA81BC485F0950E97F#第07集$MOE0322EA81BC485F0950E97E#第08集$MOE0322EA81BC485F0950E971#第09集$MOE0322EA81BC485F0950E970#第10集$MOE0322EA81BC485F0950E879#第11集$MOE0322EA81BC485F0950E878#第12集$MOE0322EA81BC485F0950E87B$$$第01集$id_XS0322EA81BC485F0950E978#第02集$id_XS0322EA81BC485F0950E97B#第03集$id_XS0322EA81BC485F0950E97A#第04集$id_XS0322EA81BC485F0950E97D#第05集$id_XS0322EA81BC485F0950E97C#第06集$id_XS0322EA81BC485F0950E97F#第07集$id_XS0322EA81BC485F0950E97E#第08集$id_XS0322EA81BC485F0950E971#第09集$id_XS0322EA81BC485F0950E970#第10集$id_XS0322EA81BC485F0950E879#第11集$id_XS0322EA81BC485F0950E878#第12集$id_XS0322EA81BC485F0950E87B$$$第01集$id_MOE0322EA81BC485F0950E978#第02集$id_MOE0322EA81BC485F0950E97B#第03集$id_MOE0322EA81BC485F0950E97A#第04集$id_MOE0322EA81BC485F0950E97D#第05集$id_MOE0322EA81BC485F0950E97C#第06集$id_MOE0322EA81BC485F0950E97F#第07集$id_MOE0322EA81BC485F0950E97E#第08集$id_MOE0322EA81BC485F0950E971#第09集$id_MOE0322EA81BC485F0950E970#第10集$id_MOE0322EA81BC485F0950E879#第11集$id_MOE0322EA81BC485F0950E878#第12集$id_MOE0322EA81BC485F0950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (30, 1, 0, 0, '鹿乃子乃子虎视眈眈', 'しかのこのこのここしたんたん', 'lunaizinaizihushidandan', 1, 'L', '', 'a3ed7502', '漫画改,搞笑,校园', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2908721666.jpg', 'https://i0.hdslb.com/bfs/archive/dffa79edfce8e9998b167bec13ac93c9782295d5.jpg', '', '', '江口拓也,高桥伸也,鸟海浩辅,井上喜久子,赤崎千夏,土屋李央,久保由利香,和泉风花,田边留依,藤田咲,潘惠美', '太田雅彦', '', '', '　　虎视虎子，就读于东京都立日之南高中的女高中生。\r\n                                    \r\n                                　　有一天', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 65, 0, 65, 65, '', 0, 0, 7.2, 0, 0, 1730927075, 1725278281, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　虎视虎子，就读于东京都立日之南高中的女高中生。<br/>　　有一天，她在上学的路上，感觉脸上有一股冰凉的感觉。<br/>　　当她抬头时，看到一个流鼻涕的人，还有一根角被电线缠住。<br/>　　一个不能动的女孩……！ ？<br/>　　无意中帮助了长着奇怪角的女孩鹿子，<br/>　　优等生虎路虎子的生活陷入混乱……<br/>　　少女遇见鹿的故事开始了！ ！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5024E9DCBE1C5D0B50E978#第02集$MOE5024E9DCBE1C5D0B50E97B#第03集$MOE5024E9DCBE1C5D0B50E97A#第04集$MOE5024E9DCBE1C5D0B50E97D#第05集$MOE5024E9DCBE1C5D0B50E97C#第06集$MOE5024E9DCBE1C5D0B50E97F#第07集$MOE5024E9DCBE1C5D0B50E97E#第08集$MOE5024E9DCBE1C5D0B50E971#第09集$MOE5024E9DCBE1C5D0B50E970#第10集$MOE5024E9DCBE1C5D0B50E879#第11集$MOE5024E9DCBE1C5D0B50E878#第12集$MOE5024E9DCBE1C5D0B50E87B$$$第01集$id_XS5024E9DCBE1C5D0B50E978#第02集$id_XS5024E9DCBE1C5D0B50E97B#第03集$id_XS5024E9DCBE1C5D0B50E97A#第04集$id_XS5024E9DCBE1C5D0B50E97D#第05集$id_XS5024E9DCBE1C5D0B50E97C#第06集$id_XS5024E9DCBE1C5D0B50E97F#第07集$id_XS5024E9DCBE1C5D0B50E97E#第08集$id_XS5024E9DCBE1C5D0B50E971#第09集$id_XS5024E9DCBE1C5D0B50E970#第10集$id_XS5024E9DCBE1C5D0B50E879#第11集$id_XS5024E9DCBE1C5D0B50E878#第12集$id_XS5024E9DCBE1C5D0B50E87B$$$第01集$id_MOE5024E9DCBE1C5D0B50E978#第02集$id_MOE5024E9DCBE1C5D0B50E97B#第03集$id_MOE5024E9DCBE1C5D0B50E97A#第04集$id_MOE5024E9DCBE1C5D0B50E97D#第05集$id_MOE5024E9DCBE1C5D0B50E97C#第06集$id_MOE5024E9DCBE1C5D0B50E97F#第07集$id_MOE5024E9DCBE1C5D0B50E97E#第08集$id_MOE5024E9DCBE1C5D0B50E971#第09集$id_MOE5024E9DCBE1C