INSERT INTO `mac_vod` VALUES (34, 1, 0, 0, '哎咕岛消失的舔甜歌姬', 'エグミレガシー', 'aigudaoxiaoshidetiantiangeji', 1, 'A', '', '6ec71153', '搞笑', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2907696612.jpg', 'https://i0.hdslb.com/bfs/archive/3837d41d203972153c5ed1ca584653b1f5b3fd73.jpg', '', '', '大仓空人,中岛良树,小林大纪,羽多野涉,驹田航,神尾晋一郎,西山宏太朗,芹泽优,齐藤壮马,青山吉能,江口拓也', '', '', '', '　　“エンドオブザワールド”は誰の手に……！？\r\n                                    \r\n                                　　とある海に', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 8.3, 0, 0, 1730816391, 1725456595, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　“エンドオブザワールド”は誰の手に……！？<br/>　　とある海にぷっかりと浮かぶ『エグー島（とう）』。<br/>　　この島の唯一の娯楽は歌姫“エンドオブザワールド”。<br/>　　村人たちは日々、彼女の歌声に酔いしれていた。<br/>　　しかし、そんなのどかな時間は一瞬で壊れる。<br/>　　－歌姫の失踪－<br/>　　この事件以来、島は『怒り』『疑心』『不安』で溢れてしまう。<br/>　　そして、それぞれの思惑が動き始める……。<br/>　　“エンドオブザワールド”を巡る、ペロペロ大戦争！<br/>　　その運命を握るのは……、伝説の遺産『エグミレガシー』</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0772EF8FB818580A50E978#第02集$MOE0772EF8FB818580A50E97B#第03集$MOE0772EF8FB818580A50E97A#第04集$MOE0772EF8FB818580A50E97D#第05集$MOE0772EF8FB818580A50E97C#第06集$MOE0772EF8FB818580A50E97F#第07集$MOE0772EF8FB818580A50E97E#第08集$MOE0772EF8FB818580A50E971#第09集$MOE0772EF8FB818580A50E970#第10集$MOE0772EF8FB818580A50E879#第11集$MOE0772EF8FB818580A50E878#第12集$MOE0772EF8FB818580A50E87B$$$第01集$id_XS0772EF8FB818580A50E978#第02集$id_XS0772EF8FB818580A50E97B#第03集$id_XS0772EF8FB818580A50E97A#第04集$id_XS0772EF8FB818580A50E97D#第05集$id_XS0772EF8FB818580A50E97C#第06集$id_XS0772EF8FB818580A50E97F#第07集$id_XS0772EF8FB818580A50E97E#第08集$id_XS0772EF8FB818580A50E971#第09集$id_XS0772EF8FB818580A50E970#第10集$id_XS0772EF8FB818580A50E879#第11集$id_XS0772EF8FB818580A50E878#第12集$id_XS0772EF8FB818580A50E87B$$$第01集$id_MOE0772EF8FB818580A50E978#第02集$id_MOE0772EF8FB818580A50E97B#第03集$id_MOE0772EF8FB818580A50E97A#第04集$id_MOE0772EF8FB818580A50E97D#第05集$id_MOE0772EF8FB818580A50E97C#第06集$id_MOE0772EF8FB818580A50E97F#第07集