INSERT INTO `mac_vod` VALUES (37, 1, 0, 0, '雀魂 KANG!!', 'じゃんたま カン！！', 'quehunKANG', 1, 'Q', '', '828f6235', '美食', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2902995163.jpg', '', '', '', '内田真礼', '古贺一臣', '', '', '　　可愛らしく多彩なキャラクターたちと共に、オンラインで全国のプレイヤーとリアルタイム対戦ができる大人気麻雀アプリ『雀魂』！', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 0.0, 0, 0, 1725542284, 1725541807, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　可愛らしく多彩なキャラクターたちと共に、オンラインで全国のプレイヤーとリアルタイム対戦ができる大人気麻雀アプリ『雀魂』！<br/>　　そんな『雀魂』が、「じゃんたま PONG☆」に続き再びアニメ化！<br/>　　個性派の雀士たちが配信業を始めたり、男同士の二人旅へ出かけたり、果てには不良の抗争に巻き込まれたり！？<br/>　　一飜市のみならず、今度はもーっと新たなカン境へ！<br/>　　沢山のキャラでお届けするカン過できない阿鼻叫カン！<br/>　　いざ尋常に、対局スタート！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0925B4DEBF1B5E0C50E978#第02集$id_XS0925B4DEBF1B5E0C50E97B#第03集$id_XS0925B4DEBF1B5E0C50E97A#第04集$id_XS0925B4DEBF1B5E0C50E97D#第05集$id_XS0925B4DEBF1B5E0C50E97C#第06集$id_XS0925B4DEBF1B5E0C50E97F#第07集$id_XS0925B4DEBF1B5E0C50E97E#第08集$id_XS0925B4DEBF1B5E0C50E971#第09集$id_XS0925B4DEBF1B5E0C50E970#第10集$id_XS0925B4DEBF1B5E0C50E879#第11集$id_XS0925B4DEBF1B5E0C50E878#第12集$id_XS0925B4DEBF1B5E0C50E87B#第13集$id_XS0925B4DEBF1B5E0C50E87A$$$第01集$id_MOE0925B4DEBF1B5E0C50E978#第02集$id_MOE0925B4DEBF1B5E0C50E97B#第03集$id_MOE0925B4DEBF1B5E0C50E97A#第04集$id_MOE0925B4DEBF1B5E0C50E97D#第05集$id_MOE0925B4DEBF1B5E0C50E97C#第06集$id_MOE0925B4DEBF1B5E0C50E97F#第07集$id_MOE0925B4DEBF1B5E0C50E97E#第08集$id_MOE0925B4DEBF1B5E0C50E971#第09集$id_MOE0925B4DEBF1B5E0C50E970#第10集$id_MOE0925B4DEBF1B5E0C50E879#第11集$id_MOE0925B4DEBF1B5E0C50E878#第12集$id_MOE0925B4DEBF1B5E0C50E87B#第13集$id_MOE0925B4DEBF1B5E0C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (38, 1, 0, 0, '拉面赤猫', 'ラーメン赤猫', 'lamianchimao', 1, 'L', '', 'fa2f5f7b', '治愈,美食', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2913595232.jpg', '', '', '', '折原穗香,早见沙织,钉宫理惠,村濑迪与,杉山纪彰,津田健次郎', '清水久敏', '', '', '　　在猫经营的拉面店·拉面赤福工作的主人公·珠子和猫们的日常生活工作故事！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 35, 0, 35, 35, '', 0, 0, 8.5, 0, 0, 1730929138, 1725544990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　在猫经营的拉面店·拉面赤福工作的主人公·珠子和猫们的日常生活工作故事！<br/>　　来该店面试的珠子，被猫店长问到喜欢猫还是喜欢狗，诚实地回答喜欢狗，结果很爽快地被录用了！<br/>　　然后珠子被委托的工作是照顾猫猫……</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5776BEDEBC4F5A5B50E978#第02集$MOE5776BEDEBC4F5A5B50E97B#第03集$MOE5776BEDEBC4F5A5B50E97A#第04集$MOE5776BEDEBC4F5A5B50E97D#第05集$MOE5776BEDEBC4F5A5B50E97C#第06集$MOE5776BEDEBC4F5A5B50E97F#第07集$MOE5776BEDEBC4F5A5B50E97E#第08集$MOE5776BEDEBC4F5A5B50E971#第09集$MOE5776BEDEBC4F5A5B50E970#第10集$MOE5776BEDEBC4F5A5B50E879#第11集$MOE5776BEDEBC4F5A5B50E878#第12集$MOE5776BEDEBC4F5A5B50E87B$$$第01集$id_XS5776BEDEBC4F5A5B50E978#第02集$id_XS5776BEDEBC4F5A5B50E97B#第03集$id_XS5776BEDEBC4F5A5B50E97A#第04集$id_XS5776BEDEBC4F5A5B50E97D#第05集$id_XS5776BEDEBC4F5A5B50E97C#第06集$id_XS5776BEDEBC4F5A5B50E97F#第07集$id_XS5776BEDEBC4F5A5B50E97E#第08集$id_XS5776BEDEBC4F5A5B50E971#第09集$id_XS5776BEDEBC4F5A5B50E970#第10集$id_XS5776BEDEBC4F5A5B50E879#第11集$id_XS5776BEDEBC4F5A5B50E878#第12集$id_XS5776BEDEBC4F5A5B50E87B$$$第01集$id_MOE5776BEDEBC4F5A5B50E978#第02集$id_MOE5776BEDEBC4F5A5B50E97B#第03集$id_MOE5776BEDEBC4F5A5B50E97A#第04集$id_MOE5776BEDEBC4F5A5B50E97D#第05集$id_MOE5776BEDEBC4F5A5B50E97C#第06集$id_MOE5776BEDEBC4F5A5B50E97F#第07集$id_MOE5776BEDEBC4F5A5B50E97E#第08集$id_MOE5776BEDEBC4F5A5B50E971#第09集$id_MOE5776BEDEBC4F5A5B50E970#第10集$id_MOE5776BEDEBC4F5A5B50E879#第11集$id_MOE5776BEDEBC4F5A5B50E878#第12集$id_MOE5776BEDEBC4F5A5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (39, 1, 0, 0, '黄昏失焦', '黄昏アウトフォーカス（2024）', 'huanghunshijiao', 1, 'H', '', '5cad65bb', '校园,恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2908780875.jpg', '', '', '', '松冈祯丞 / 内田雄马', '渡部稳宽', '', '', '　　真央热爱电影，在学校参加电影制作社。他与孤高一匹狼的寿是室友，两人相处融洽，也彼此承诺了3项约定：「不会说出寿是同性恋的秘密」、「寿不会对真央出手」、「不干涉对方自慰」。但因缘际会下，寿要主演同性', '全12集', '', 0, '0', '', '', '日本', '七月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 7.3, 0, 0, 1743764136, 1725571131, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '真央热爱电影，在学校参加电影制作社。他与孤高一匹狼的寿是室友，两人相处融洽，也彼此承诺了3项约定：「不会说出寿是同性恋的秘密」、「寿不会对真央出手」、「不干涉对方自慰」。但因缘际会下，寿要主演同性恋角色的电影？并且由真央掌镜？透过镜头，真央看见不一样的寿，一部探讨爱的作品使两人的关系开始产生变化……', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0474EDDCBF1C0F5B50E978#第02集$MOE0474EDDCBF1C0F5B50E97B#第03集$MOE0474EDDCBF1C0F5B50E97A#第04集$MOE0474EDDCBF1C0F5B50E97D#第05集$MOE0474EDDCBF1C0F5B50E97C#第06集$MOE0474EDDCBF1C0F5B50E97F#第07集$MOE0474EDDCBF1C0F5B50E97E#第08集$MOE0474EDDCBF1C0F5B50E971#第09集$MOE0474EDDCBF1C0F5B50E970#第10集$MOE0474EDDCBF1C0F5B50E879#第11集$MOE0474EDDCBF1C0F5B50E878#第12集$MOE0474EDDCBF1C0F5B50E87B$$$第01集$id_XS0474EDDCBF1C0F5B50E978#第02集$id_XS0474EDDCBF1C0F5B50E97B#第03集$id_XS0474EDDCBF1C0F5B50E97A#第04集$id_XS0474EDDCBF1C0F5B50E97D#第05集$id_XS0474EDDCBF1C0F5B50E97C#第06集$id_XS0474EDDCBF1C0F5B50E97F#第07集$id_XS0474EDDCBF1C0F5B50E97E#第08集$id_XS0474EDDCBF1C0F5B50E971#第09集$id_XS0474EDDCBF1C0F5B50E970#第10集$id_XS0474EDDCBF1C0F5B50E879#第11集$id_XS0474EDDCBF1C0F5B50E878#第12集$id_XS0474EDDCBF1C0F5B50E87B$$$第01集$id_MOE0474EDDCBF1C0F5B50E978#第02集$id_MOE0474EDDCBF1C0F5B50E97B#第03集$id_MOE0474EDDCBF1C0F5B50E97A#第04集$id_MOE0474EDDCBF1C0F5B50E97D#第05集$id_MOE0474EDDCBF1C0F5B50E97C#第06集$id_MOE0474EDDCBF1C0F5B50E97F#第07集$id_MOE0474EDDCBF1C0F5B50E97E#第08集$id_MOE0474EDDCBF1C0F5B50E971#第09集$id_MOE0474EDDCBF1C0F5B50E970#第10集$id_MOE0474EDDCBF1C0F5B50E879#第11集$id_MOE0474EDDCBF1C0F5B50E878#第12集$id_MOE0474EDDCBF1C0F5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (40, 1, 0, 0, '恶魔的破坏', 'デッドデッドデーモンズデデデデデストラクション', 'emodepohuai', 1, 'E', '', 'a47602af', '科幻,战斗', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2897502543.jpg', '', '', '', '几田莉拉', '黑川智之', '', '', '本作以外星人入侵下的地球为背景，描述了末日下少女们的日常故事。', '全18集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 8.1, 0, 0, 1730785098, 1725572593, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　浅野いにお创作的漫画《#恶魔的破坏# DEAD DEAD DEAMON&#39;S DEDEDEDE DESTRUCTION》宣布动画化！该作将由《地球外少年少女》的制作公司 Production &nbsp;h. 负责制作。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5023BB8EB91B0C5F50E978#第02集$MOE5023BB8EB91B0C5F50E97B#第03集$MOE5023BB8EB91B0C5F50E97A#第04集$MOE5023BB8EB91B0C5F50E97D#第05集$MOE5023BB8EB91B0C5F50E97C#第06集$MOE5023BB8EB91B0C5F50E97F#第07集$MOE5023BB8EB91B0C5F50E97E#第08集$MOE5023BB8EB91B0C5F50E971#第09集$MOE5023BB8EB91B0C5F50E970#第10集$MOE5023BB8EB91B0C5F50E879#第11集$MOE5023BB8EB91B0C5F50E878#第12集$MOE5023BB8EB91B0C5F50E87B#第13集$MOE5023BB8EB91B0C5F50E87A#第14集$MOE5023BB8EB91B0C5F50E87D#第15集$MOE5023BB8EB91B0C5F50E87C#第16集$MOE5023BB8EB91B0C5F50E87F#第17集$MOE5023BB8EB91B0C5F50E87E#第18集$MOE5023BB8EB91B0C5F50E871$$$第01集$id_XS5023BB8EB91B0C5F50E978#第02集$id_XS5023BB8EB91B0C5F50E97B#第03集$id_XS5023BB8EB91B0C5F50E97A#第04集$id_XS5023BB8EB91B0C5F50E97D#第05集$id_XS5023BB8EB91B0C5F50E97C#第06集$id_XS5023BB8EB91B0C5F50E97F#第07集$id_XS5023BB8EB91B0C5F50E97E#第08集$id_XS5023BB8EB91B0C5F50E971#第09集$id_XS5023BB8EB91B0C5F50E970#第10集$id_XS5023BB8EB91B0C5F50E879#第11集$id_XS5023BB8EB91B0C5F50E878#第12集$id_XS5023BB8EB91B0C5F50E87B#第13集$id_XS5023BB8EB91B0C5F50E87A#第14集$id_XS5023BB8EB91B0C5F50E87D#第15集$id_XS5023BB8EB91B0C5F50E87C#第16集$id_XS5023BB8EB91B0C5F50E87F#第17集$id_XS5023BB8EB91B0C5F50E87E#第18集$id_XS5023BB8EB91B0C5F50E871$$$第01集$id_MOE5023BB8EB91B0C5F50E978#第02集$id_MOE5023BB8EB91B0C5F50E97B#第03集$id_MOE5023BB8EB91B0C5F50E97A#第04集$id_MOE5023BB8EB91B0C5F50E97D#第05集$id_MOE5023BB8EB91B0C5F50E97C#第06集$id_MOE5023BB8