INSERT INTO `mac_vod` VALUES (45, 1, 0, 0, '铁路浪漫谭 第二季', 'レヱル・ロマネスク2 Season 2', 'tielulangmantandierji', 1, 'T', '', '5c359d66', '泡面', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2895560742.jpg', '', '', '', '上坂堇,楠木灯,本渡枫,田所梓,日高里菜,岛袋美由利,山根绮,田中理惠', '', '', '', '　　负责铁路运输核心的人偶模块“铁路人偶”。\r\n                                    \r\n                                　　由于新交通系', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 0.0, 0, 0, 1725712275, 1725712209, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　负责铁路运输核心的人偶模块“铁路人偶”。<br/>　　由于新交通系统的出现而濒临消亡的铁路靠着旅游振兴和商品开发等逐渐恢复，铁路人偶们以进一步促进复兴为目标，集合在第2届铁路人偶高峰会上。<br/>　　这届高峰会的主题是用声音传达御一夜市的魅力。<br/>　　铁路人偶们为了寻找自己想录制的声音，挑战了户外现场录音的冒险。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0474BF8DB04D5B0F50E978#第02集$id_XS0474BF8DB04D5B0F50E97B#第03集$id_XS0474BF8DB04D5B0F50E97A#第04集$id_XS0474BF8DB04D5B0F50E97D#第05集$id_XS0474BF8DB04D5B0F50E97C#第06集$id_XS0474BF8DB04D5B0F50E97F#第07集$id_XS0474BF8DB04D5B0F50E97E#第08集$id_XS0474BF8DB04D5B0F50E971#第09集$id_XS0474BF8DB04D5B0F50E970#第10集$id_XS0474BF8DB04D5B0F50E879#第11集$id_XS0474BF8DB04D5B0F50E878#第12集$id_XS0474BF8DB04D5B0F50E87B#第13集$id_XS0474BF8DB04D5B0F50E87A$$$第01集$id_MOE0474BF8DB04D5B0F50E978#第02集$id_MOE0474BF8DB04D5B0F50E97B#第03集$id_MOE0474BF8DB04D5B0F50E97A#第04集$id_MOE0474BF8DB04D5B0F50E97D#第05集$id_MOE0474BF8DB04D5B0F50E97C#第06集$id_MOE0474BF8DB04D5B0F50E97F#第07集$id_MOE0474BF8DB04D5B0F50E97E#第08集$id_MOE0474BF8DB04D5B0F50E971#第09集$id_MOE0474BF8DB04D5B0F50E970#第10集$id_MOE0474BF8DB04D5B0F50E879#第11集$id_MOE0474BF8DB04D5B0F50E878#第12集$id_MOE0474BF8DB04D5B0F50E87B#第13集$id_MOE0474BF8DB04D5B0F50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (46, 1, 0, 0, '堤亚穆帝国物语～从断头台开始，公主重生后的逆转人生～', 'ティアムーン帝国物語 ~断頭台から始まる、姫の転生逆転ストーリー~（2023）', 'diyamudiguowuyucongduantoutaikaishigongzhuzhongshenghoudenizhuanrensheng', 1, 'D', '', '75ca5cf1', '奇幻,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2879771800.jpg', '', '', '', '上坂堇 / 楠木灯 / 梅原裕一郎 / 松冈祯丞 / 堀江瞬 / 高尾奏音 / 东山奈央 / 增田俊树 / 斋藤枫子 / 高桥李依 / 古川慎 / 长谷川玲奈 / 成田剑', '伊部勇志', '', '', '　　头，还在，我变小了。在发生革命后数年的堤亚穆帝国，被蔑称为任性皇女的米雅被革命军推上了断头台处决……本应该被处死，醒来以后却发现自己变回了12岁的样子！看来这里是重新来过的世界――她的枕边放着的是', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 6.5, 0, 0, 1742356553, 1725712339, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　头，还在，我变小了。在发生革命后数年的堤亚穆帝国，被蔑称为任性皇女的米雅被革命军推上了断头台处决……本应该被处死，醒来以后却发现自己变回了12岁的样子！看来这里是重新来过的世界――她的枕边放着的是处刑前自己所写的染血的日记。<br/>　　走上了第二人生的米雅，决定复兴帝国。是为了拯救百姓于饥饿之中？还是为了那些在内战中牺牲的士兵？都不是，自身也是为了躲避被送上断头台的命运！！<br/>　　这，这种事情很简单的！任性公主的行动居然引发了奇迹，改变历史的奇幻故事即将开始——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0622EFD9BC4A0B0850E978#第02集$MOE0622EFD9BC4A0B0850E97B#第03集$MOE0622EFD9BC4A0B0850E97A#第04集$MOE0622EFD9BC4A0B0850E97D#第05集$MOE0622EFD9BC4A0B0850E97C#第06集$MOE0622EFD9BC4A0B0850E97F#第07集$MOE0622EFD9BC4A0B0850E97E#第08集$MOE0622EFD9BC4A0B0850E971#第09集$MOE0622EFD9BC4A0B0850E970#第10集$MOE0622EFD9BC4A0B0850E879#第11集$MOE0622EFD9BC4A0B0850E878#第12集$MOE0622EFD9BC4A0B0850E87B$$$第01集$id_XS0622EFD9BC4A0B0850E978#第02集$id_XS0622EFD9BC4A0B0850E97B#第03集$id_XS0622EFD9BC4A0B0850E97A#第04集$id_XS0622EFD9BC4A0B0850E97D#第05集$id_XS0622EFD9BC4A0B0850E97C#第06集$id_XS0622EFD9BC4A0B0850E97F#第07集$id_XS0622EFD9BC4A0B0850E97E#第08集$id_XS0622EFD9BC4A0B0850E971#第09集$id_XS0622EFD9BC4A0B0850E970#第10集$id_XS0622EFD9BC4A0B0850E879#第11集$id_XS0622EFD9BC4A0B0850E878#第12集$id_XS0622EFD9BC4A0B0850E87B$$$第01集$id_MOE0622EFD9BC4A0B0850E978#第02集$id_MOE0622EFD9BC4A0B0850E97B#第03集$id_MOE0622EFD9BC4A0B0850E97A#第04集$id_MOE0622EFD9BC4A0B0850E97D#第05集$id_MOE0622EFD9BC4A0B0850E97C#第06集$id_MOE0622EFD9BC4A0B0850E97F#第07集$id_MOE0622EFD9BC4A0B0850E97E#第08集$id_MOE0622EFD9BC4A0B0850E971#第09集$id_MOE0622EFD9BC4A0B0850E970#第10集$id_MOE0622EFD9BC4A0B0850E879#第11集$id_MOE0622EFD9BC4A0B0850E878#第12集$id_MOE0622EFD9BC4A0B0850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (47, 1, 0, 0, '光之美少女 MAX HEART', 'ふたりはプリキュア Max Heart（2005）', 'guangzhimeishaonvMAXHEART', 1, 'G', '', '4f2fef8c', '原创,战斗,搞笑,日常', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2510818223.jpg', '', '', '', '本名阳子 / 野上尤加奈 / 田中理惠 / 关智一 / 矢岛晶子 / 池泽春菜 / 谷井明日香 / 松谷彼哉 / 中博史 / 松野太纪 / 永野爱 / 菊池心 / 仙台惠理 / 小松里歌 / 小林麻由子 / 埴冈由纪子 / 沼田祐介 / 安达真理 / 天田真人 / 石毛佐和 / 壹智村小真 / 水泽史绘 / 小野健一 / 七绪春日 / 泷知史 / 上别府仁资 / 高木涉 / 小林爱 / 子安武人 / 庄真由美 / 高桥直纯 / 宫下尊 / 伊藤美纪 / 置鲇龙太郎 / 藤田美歌子 / 盐屋浩三 / 西村朋', '西尾大介 / 大塚隆史 / 小村敏明 / 伊藤尚往 / 山田彻 / 岩井隆央 / 川田武范 / 座古明史', '', '', '新学期开始，美墨渚和雪城穗乃香成为菲诺奈学院女子中学部三年级学生，过着普通女孩的校园生活。', '全47集', '', 0, '', '', '', '日本', '一月', '2005', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 6.0, 0, 0, 1744300765, 1725713124, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>新学期开始，美墨渚和雪城穗乃香成为菲诺奈学院女子中学部三年级学生，过着普通女孩的校园生活。 而梅普鲁、米普鲁和保伦在上次战斗后陷入了漫长的沉睡。 此时，在光之园，在激战后受了伤的女王分裂成数个部分，消失在远处。与此同时，渚和穗乃香遭到了萨凯那的袭击。 突然，梅普鲁和米普鲁苏醒过来，两人使用新的变身器再一次变身成为“光之美少女”，不仅衣服改变了，而且力量居然也提升了！？ 为了让失去了记忆和原本姿态的女王恢复原样，渚和穗乃香以及苏醒后力量得到提升的梅普鲁、米普鲁和保伦，将与不可思议的少女・九条光一起展开新的故事。 光之美少女们能够让女王恢复原来的样子吗？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0571BEDEEC4F555A50E978#第02集$MOE0571BEDEEC4F555A50E97B#第03集$MOE0571BEDEEC4F555A50E97A#第04集$MOE0571BEDEEC4F555A50E97D#第05集$MOE0571BEDEEC4F555A50E97C#第06集$MOE0571BEDEEC4F555A50E97F#第07集$MOE0571BEDEEC4F555A50E97E#第08集$MOE0571BEDEEC4F555A50E971#第09集$MOE0571BEDEEC4F555A50E970#第10集$MOE0571BEDEEC4F555A50E879#第11集$MOE0571BEDEEC4F555A50E878#第12集$MOE0571BEDEEC4F555A50E87B#第13集$MOE0571BEDEEC4F555A50E87A#第14集$MOE0571BEDEEC4F555A50E87D#第15集$MOE0571BEDEEC4F555A50E87C#第16集$MOE0571BEDEEC4F555A50E87F#第17集$MOE0571BEDEEC4F555A50E87E#第18集$MOE0571BEDEEC4F555A50E871#第19集$MOE0571BEDEEC4F555A50E870#第20集$MOE0571BEDEEC4F555A50EB79#第21集$MOE0571BEDEEC4F555A50EB78#第22集$MOE0571BEDEEC4F555A50EB7B#第23集$MOE0571BEDEEC4F555A50EB7A#第24集$MOE0571BEDEEC4F555A50EB7D#第25集$MOE0571BEDEEC4F555A50EB7C#第26集$MOE0571BEDEEC4F555A50EB7F#第27集$MOE0571BEDEEC4F555A50EB7E#