INSERT INTO `mac_vod` VALUES (50, 1, 0, 0, '晚安世界', '', 'wananshijie', 1, 'W', '', 'b9afae5', '漫画改', 'https://i0.hdslb.com/bfs/bangumi/image/4f24d871d6dd7c58237c7a4064ca3e9b5b454294.png', '', '', NULL, '阿一 , 有间太一郎：广濑大介\n啊啊啊啊啊,有间明日真：岛崎信长\n赤羽士郎 , 有间小次郎：大冢明夫\n梅,有间雅：远藤绫\n皮可：悠木碧\n里欧：木村良平\n萨斯玛塔：七海弘希\n志贺寺：津田健次郎\n神室花：高桥李依\n有间绫：水濑祈', '菊池胜也', '', '', '在这混账世界里连接起的家庭故事。\n在网游《行星》中，有一个号称最强的四人组。\n四人组的名号是“赤羽一家”。\n他们是在网游里的模拟家庭。\n虽然他们本人并不知晓，但他们在现实世界里，也是已经支离破碎的真正', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 9.2, 0, 0, 1725741525, 1725741491, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '在这混账世界里连接起的家庭故事。\n在网游《行星》中，有一个号称最强的四人组。\n四人组的名号是“赤羽一家”。\n他们是在网游里的模拟家庭。\n虽然他们本人并不知晓，但他们在现实世界里，也是已经支离破碎的真正家人。\n家里蹲长子，优等生次子。\n不受孩子尊敬的父亲，对家庭不管不顾的母亲。\n他们不知道家人间的温暖。\n他们不知道网游里的家人间只存在虚幻的温暖\n他们不知道彼此之间其实是真正的家人。\n以赤羽一家为中心，在网游《行星》中展开，与魔物的对决、公会间的争斗，以及围绕最终目标“黑鸟”的阴谋诡计。\n将现实世界与现实家庭卷入其中，故事迎来重大推进——', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS532EEDDEE84C58144DE8#第02集$id_XS532EEDDEE84C58144DEB#第03集$id_XS532EEDDEE84C58144DEA#第04集$id_XS532EEDDEE84C58144DED#第05集$id_XS532EEDDEE84C58144DEC#第06集$id_XS532EEDDEE84C58144DEF#第07集$id_XS532EEDDEE84C58144DEE#第08集$id_XS532EEDDEE84C58144DE1#第09集$id_XS532EEDDEE84C58144DE0#第10集$id_XS532EEDDEE84C58144CE9#第11集$id_XS532EEDDEE84C58144CE8#第12集$id_XS532EEDDEE84C58144CEB$$$第01集$id_MOE532EEDDEE84C58144DE8#第02集$id_MOE532EEDDEE84C58144DEB#第03集$id_MOE532EEDDEE84C58144DEA#第04集$id_MOE532EEDDEE84C58144DED#第05集$id_MOE532EEDDEE84C58144DEC#第06集$id_MOE532EEDDEE84C58144DEF#第07集$id_MOE532EEDDEE84C58144DEE#第08集$id_MOE532EEDDEE84C58144DE1#第09集$id_MOE532EEDDEE84C58144DE0#第10集$id_MOE532EEDDEE84C58144CE9#第11集$id_MOE532EEDDEE84C58144CE8#第12集$id_MOE532EEDDEE84C58144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (51, 1, 0, 0, '彩叶草之梦', '転生したらスライムだった件 コリウスの夢（2023）', 'caiyecaozhimeng', 1, 'C', '', 'a41b935a', '异世界,奇幻,魔法,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2891778072.jpg', '', '', '', '冈咲美保 / 寺岛拓笃 / 丰口惠美 / 小林亲弘 / 古川慎 / 江口拓也 / 花江夏树 / Lynn / 富田美忧 / 冈本信彦 / 日冈夏美 / 田丸笃志 / 加藤将之 / 小松史法 / 名冢佳织 / 兴津和幸', '中山敦史', '', '', '　　电视动画《#关于我转生变成史莱姆这档事 第二季#》BD附赠的短篇小说「彩叶草之梦」 ，也是剧场版《#关于我转生变成史莱姆这档事##红莲之绊篇#》的原案小说，宣布将改编为全3集的新作原创动画，于今年', '全3集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 7.3, 0, 0, 1742388517, 1725743269, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　电视动画《#关于我转生变成史莱姆这档事 第二季#》BD附赠的短篇小说「彩叶草之梦」 ，也是剧场版《#关于我转生变成史莱姆这档事##红莲之绊篇#》的原案小说，宣布将改编为全3集的新作原创动画，于今年秋季播出，故事发生在TV动画第一季与第二季之间。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5023BDDAB01A585850E978#第02集$MOE5023BDDAB01A585850E97B#第03集$MOE5023BDDAB01A585850E97A$$$第01集$id_XS5023BDDAB01A585850E978#第02集$id_XS5023BDDAB01A585850E97B#第03集$id_XS5023BDDAB01A585850E97A$$$第01集$id_MOE5023BDDAB01A585850E978#第02集$id_MOE5023BDDAB01A585850E97B#第03集$id_MOE5023BDDAB01A585850E97A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (52, 1, 0, 0, '亡骸游戏', 'デッドマウント・デスプレイ（2023）', 'wanghaiyouxi', 1, 'W', '', '6e2489fc', '异世界,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2888433206.jpg', '', '', '', '榊原优希 / 水濑祈 / 内田雄马 / 江口拓也 / 种崎敦美 / 山路和弘 / 大久保瑠美 / 大地叶 / 长谷川育美 / 白石晴香 / 福圆美里 / 冈本信彦 / 草尾毅 / 柚木凉香 / 佐仓绫音 / 志村知幸 / 兴津和幸 / 小林沙苗 / 苍井翔太 / 小西克幸 / 花泽香菜 / 原纱友里 / 芹泽优 / 市川苍 / 岩崎征实 / 丰口惠美 / 田丸笃志 / 米泽圆 / 利根健太朗 / 松山鹰志 / 加藤将之 / 奥野香耶 / 樫井笙人 / 岛崎信长 / 七海弘希', '小野学', '', '', '　　夏古鲁亚，一个自出生以来就有阴阳眼这种能力的小孩，却因为所处的世界对阴阳眼的错误认知，一家受到了村民们的迫害。比较走运的就被教会用钱买来当圣兵作战，甚至获得民众们称之为“消灾解厄”者，而把人类的性', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 95, 0, 95, 95, '', 0, 0, 6.7, 0, 0, 1742392126, 1725766922, 0, 0, 0, 0, 0.0, '', '49', '', '', '', '', '', '', '', '<p>　　夏古鲁亚，一个自出生以来就有阴阳眼这种能力的小孩，却因为所处的世界对阴阳眼的错误认知，一家受到了村民们的迫害。比较走运的就被教会用钱买来当圣兵作战，甚至获得民众们称之为“消灾解厄”者，而把人类的性命当作玩具玩弄的阴阳眼，就沦为“尸神”。就在一次作战当中，尸神竟然将自己的灵魂跟夏古鲁亚互换，但也失去了自己的记忆。后来得知真相之后，尸神就以夏古鲁亚身分展开了新的人生。并转世到另一个平行空间˙新宿，与职业杀手美纱树和情报屋缲缲合作，专门处理一些社会上的垃圾。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0772BE8CB1100B5A50E978#第02集$MOE0772BE8CB1100B5A50E97B#第03集$MOE0772BE8CB1100B5A50E97A#第04集$MOE0772BE8CB1100B5A50E97D#第05集$MOE0772BE8CB1100B5A50E97C#第06集$MOE0772BE8CB1100B5A50E97F#第07集$MOE0772BE8CB1100B5A50E97E#第08集$MOE0772BE8CB1100B5A50E971#第09集$MOE0772BE8CB1100B5A50E970#第10集$MOE0772BE8CB1100B5A50E879#第11集$MOE0772BE8CB1100B5A50E878#第12集$MOE0772BE8CB1100B5A50E87B$$$第01集$id_XS0772BE8CB1100B5A50E978#第02集$id_XS0772BE8CB1100B5A50E97B#第03集$id_XS0772BE8CB1100B5A50E97A#第04集$id_XS0772BE8CB1100B5A50E97D#第05集$id_XS0772BE8CB1100B5A50E97C#第06集$id_XS0772BE8CB1100B5A50E97F#第07集$id_XS0772BE8CB1100B5A50E97E#第08集$id_XS0772BE8CB1100B5A50E971#第09集$id_XS0772BE8CB1100B5A50E970#第10集$id_XS0772BE8CB1100B5A50E879#第11集$id_XS0772BE8CB1100B5A50E878#第12集$id_XS0772BE8CB1100B5A50E87B$$$第01集$id_MOE0772BE8CB1100B5A50E978#第02集$id_MOE0772BE8CB1100B5A50E97B#第03集$id_MOE0772BE8CB1100B5A50E97A#第04集$id_MOE0772BE8CB1100B5A50E97D#第05集$id_MOE0772BE8CB1100B5A50E97C#第06集$id_MOE0772BE8CB1100B5A50E97F#第07集$id_MOE0772BE8CB1100B5A50E97E#第08集$id_MOE0772BE8CB1100B5A50E971#第09集$id_MOE0772BE8CB1100B5A50E970#第10集$id_MOE0772BE8CB1100B5A50E879#第11集$id_MOE0772BE8CB1100B5A50E878#第12集$id_MOE0772BE8CB1100B5A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (53, 2, 0, 0, '大雪海的卡纳 星之贤者', '', 'daxuehaidekanaxingzhixianzhe', 1, 'D', '', '76c4d2ca', '科幻,战斗,机战,原创', 'https://i0.hdslb.com/bfs/bangumi/image/181473fd8ce9a72994885b23dcb800a414a31f4d.png', '', '', '', '卡纳：细谷佳正\n莉莉哈：高桥李依\n亚欧纳：村濑步\n阿梅洛忒：坂本真绫\n奥利诺加：小西克幸\n恩加波吉：杉田智和\n汉达基尔：桧山修之', '安藤裕章', '', '', '随着“雪海”不断扩张，大地几近消失的异世界——人们在巨木“轨道树”的根部和顶部延展出的“天膜”上勉强过着日子。在天膜的少年卡纳与地面的少女莉莉哈相遇之际，改变这即将毁灭的世界的故事就此拉开了帷幕。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 0.0, 0, 0, 1725835849, 1725834439, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '随着“雪海”不断扩张，大地几近消失的异世界——人们在巨木“轨道树”的根部和顶部延展出的“天膜”上勉强过着日子。在天膜的少年卡纳与地面的少女莉莉哈相遇之际，改变这即将毁灭的世界的故事就此拉开了帷幕。', 'xs$$$moe', 'no$$$no', '$$$', '全片$id_XS0621EF8CED1B0E5850E978$$$全片$id_MOE0621EF8CED1B0E5850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (54, 2, 0, 0, '少女与战车 最终章 第4话', 'ガールズ＆パンツァー 最終章 第4話', 'shaonvyuzhanchezuizhongzhangdi4hua', 1, 'S', '', 'bc53f32d', '原创,热血,战斗', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2900025502.jpg', '', '', '', '若山诗音,下地紫野,能登麻美子,渊上舞', '水岛努', '', '', '　　半决赛・大洗女子学园 VS 继续高中的激烈赛事展开！\r\n                                    \r\n                                　　', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 0, 25, 25, '', 0, 0, 8.6, 0, 0, 1725835740, 1725835501, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　半决赛・大洗女子学园 VS 继续高中的激烈赛事展开！<br/>　　然而大洗女子学园在赛事一开始便失去鮟鱇队这张王牌，陷入前所未有的困境。面对步步进逼的继续高中，余下成员能否扭转局势！？<br/>　　另一方面，黑森峰女子学园 VS 圣葛罗莉安娜女子学院的对决亦愈演愈烈！<br/>　　黑森峰的队长・逸见艾丽卡，将以自己独特的战车道，迎战劲敌圣葛罗的队长・大吉岭！<br/>　　一秒都不能错过的两场赛事，到底谁可得到决赛的入场券！？</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5374B98BEF1A5F5D50E978$$$正片$id_MOE5374B98BEF1A5F5D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (55, 2, 0, 0, '数码宝贝02：最初的召唤', '', 'shumabaobei02zuichudezhaohuan', 1, 'S', '', 'eb0ab4c4', '动画', 'https://i0.hdslb.com/bfs/bangumi/image/9032aba9ea68d0e47ed56c6fd04d466edbda68ee.png', '', '', '', '片山福十郎 , 野田顺子 , 亚瑟·朗斯贝里 , 高桥直纯 , 朝井彩加 , 远近孝一 , 山谷祥生 , 浦和惠 , 榎木淳弥 , 松本美和 , 市道真央 , 德光由禾 , 绪方惠美 , 钉宫理惠', '', '', '', '2012年2月，东京铁塔上空出现了巨大的数码蛋。就在本宫大辅（20岁）和V仔兽修行拉面技艺的时候，遇到了虽然拿着有裂纹的数码器，但身边没有搭档数码兽的迷之青年——自称“我没有数码兽，我的搭档数码兽被我', '简中1080P', '', 0, '', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 0.0, 0, 0, 1725836234, 1725835801, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>2012年2月，东京铁塔上空出现了巨大的数码蛋。就在本宫大辅（20岁）和V仔兽修行拉面技艺的时候，遇到了虽然拿着有裂纹的数码器，但身边没有搭档数码兽的迷之青年——自称“我没有数码兽，我的搭档数码兽被我杀了，我是世界上最初和数码兽建立搭档关系的人类。”</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5475BCD9EB1D0E0D50E978$$$正片$id_MOE5475BCD9EB1D0E0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (56, 2, 0, 0, '青春猪头少年不会梦到红书包女孩', '青春ブタ野郎はランドセルガールの夢を見ない', 'qingchunzhutoushaonianbuhuimengdaohongshubaonvhai', 1, 'Q', '', 'a81d8761', '校园,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2893232628.jpg', '', '', '', '水濑祈,内田真礼,种崎敦美,东山奈央,久保由利香,濑户麻沙美,石川界人', '增井壮一', '', '', '　　进入三月，第三学期也剩下一个月。麻衣的毕业典礼这一天终于来临。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 74, 0, 74, 74, '', 0, 0, 8.0, 0, 0, 1725885244, 1725885134, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　进入三月，第三学期也剩下一个月。麻衣的毕业典礼这一天终于来临。<br/>　　“叔叔，你是谁？”<br/>　　咲太在七里滨海岸等待麻衣时，酷似童星时代的麻衣的小学生出现在他面前？<br/>　　另一方面，花枫事件之后就分开住的咲太父亲来电……<br/>　　“你妈妈说，她想见花枫一面。”<br/>　　无法接受花枫发生的事件而长年住院的母亲传达“想见她一面”的心愿……<br/>　　家人的羁绊，新思春期症候群的征兆──</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS502FBDDCB11E5B0850E978$$$正片$id_MOE502FBDDCB11E5B0850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (57, 2, 0, 0, '窗边的小豆豆', '窓ぎわのトットちゃん', 'chuangbiandexiaodoudou', 1, 'C', '', '5f19a8f9', '剧场版', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2910157875.jpg', '', '', '', '泷泽凯伦,杏,小栗旬,役所广司,大野莉莉亚', '八锹新之介', '', '', '　　影片由黑柳彻子的自传小说改编，讲述了作者黑柳彻子上小学时一段真实的故事，小豆豆因淘气被原学校退学后，来到巴学园。在小林校长的爱护和引导下，一般人眼里“怪怪”的小豆豆逐渐成了一个大家都能接受的孩子。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 8.3, 0, 0, 1725889137, 1725889036, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　影片由黑柳彻子的自传小说改编，讲述了作者黑柳彻子上小学时一段真实的故事，小豆豆因淘气被原学校退学后，来到巴学园。在小林校长的爱护和引导下，一般人眼里“怪怪”的小豆豆逐渐成了一个大家都能接受的孩子。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0471BD81E8110B0050E978$$$正片$id_MOE0471BD81E8110B0050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (58, 2, 0, 0, '间谍过家家 代号：白', '劇場版 Spy x Family Code: White', 'jiandieguojiajiadaihaobai', 1, 'J', '', '6df99f06', '剧场版', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2907078869.jpg', '', '', '', '堀总士郎,加濑康之,千叶繁,季冠霖,山新,边江,贺来贤人,中村伦也,武内骏辅,银河万丈,加藤英美里,藤原夏海,山路和弘,小野贤章,吉野裕行,佐仓绫音,甲斐田裕子,松田健一郎,种崎敦美,早见沙织,江口拓也', '片桐崇', '', '', '　　出色的间谍“黄昏”化身为心理医生劳埃德·福杰，与拥有“读心术”的超能力女孩阿尼亚、杀手约尔组成各怀秘密但意外温馨的“伪装家庭”，在共同经历笑料百出的家庭闹剧后，将踏上第一次“家庭旅行”。然而，在愉', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 60, 0, 60, 60, '', 0, 0, 7.4, 0, 0, 1725889285, 1725889219, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　出色的间谍“黄昏”化身为心理医生劳埃德·福杰，与拥有“读心术”的超能力女孩阿尼亚、杀手约尔组成各怀秘密但意外温馨的“伪装家庭”，在共同经历笑料百出的家庭闹剧后，将踏上第一次“家庭旅行”。然而，在愉快的旅途中，阿尼亚却发现了一个可能会撼动世界和平的“秘密”，令人措手不及的大危机事件来袭！世界的命运，又一次掌握在了这意外不断的临时一家人手中！</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0773EA81B04F5D0F50E978$$$正片$id_MOE0773EA81B04F5D0F50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (59, 1, 0, 0, '不死不幸', 'アンデッドアンラック（2023）', 'busibuxing', 1, 'B', '', '7126ba4a', '冒险,奇幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2897950166.jpg', '', '', '', '中村悠一 / 佳原萌枝 / 花江夏树 / 乃村健次 / 悠木碧 / 伊濑茉莉也 / 小山力也 / 钉宫理惠 / 冈本信彦 / 游佐浩二 / 杉田智和', '八濑祐树', '', '', '　　出云风子在8岁时，因自己的能力“不幸”造成了一场200人死亡的飞机事故，而她的双亲也在事故中丧生，她自此10年闭门不出。2020年8月，在一直追看的长篇少女漫画连载完结后，她决定自杀。此时她遇见拥', '全 24集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 28, 0, 28, 28, '', 0, 0, 7.7, 0, 0, 1743756464, 1725889782, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '出云风子在8岁时，因自己的能力“不幸”造成了一场200人死亡的飞机事故，而她的双亲也在事故中丧生，她自此10年闭门不出。2020年8月，在一直追看的长篇少女漫画连载完结后，她决定自杀。此时她遇见拥有“不死”能力的安迪。安迪凭借其强大的再生能力，即使在风子“不幸”能力的影响下仍能生还。阻止风子自杀后，两人出发寻找让安迪死去的方法。 随后，风子发现世上还有其他人拥有类似的异能。能够否定某事物的人被称为“否定者”，亦有由否定者组成的组织“Union”。“Union”的职责为完成“默示录”所给予的任务，例如去讨伐UMA（未确认生物）等，以规避世界再被添加“规则”，然后导致世界灭亡的下场。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0626BE8EEB48595850E978#第02集$MOE0626BE8EEB48595850E97B#第03集$MOE0626BE8EEB48595850E97A#第04集$MOE0626BE8EEB48595850E97D#第05集$MOE0626BE8EEB48595850E97C#第06集$MOE0626BE8EEB48595850E97F#第07集$MOE0626BE8EEB48595850E97E#第08集$MOE0626BE8EEB48595850E971#第09集$MOE0626BE8EEB48595850E970#第10集$MOE0626BE8EEB48595850E879#第11集$MOE0626BE8EEB48595850E878#第12集$MOE0626BE8EEB48595850E87B#第13集$MOE0626BE8EEB48595850E87A#第14集$MOE0626BE8EEB48595850E87D#第15集$MOE0626BE8EEB48595850E87C#第16集$MOE0626BE8EEB48595850E87F#第17集$MOE0626BE8EEB48595850E87E#第18集$MOE0626BE8EEB48595850E871#第19集$MOE0626BE8EEB48595850E870#第20集$MOE0626BE8EEB48595850EB79#第21集$MOE0626BE8EEB48595850EB78#第22集$MOE0626BE8EEB48595850EB7B#第23集$MOE0626BE8EEB48595850EB7A#第24集$MOE0626BE8EEB48595850EB7D$$$第01集$id_XS0626BE8EEB48595850E978#第02集$id_XS0626BE8EEB48595850E97B#第03集$id_XS0626BE8EEB48595850E97A#第04集$id_XS0626BE8EEB48595850E97D#第05集$id_XS0626BE8EEB48595850E97C#第06集$id_XS0626BE8EEB48595850E97F#第07集$id_XS0626BE8EEB48595850E97E#第08集$id_XS0626BE8EEB48595850E971#第09集$id_XS0626BE8EEB48595850E970#第10集$id_XS0626BE8EEB48595850E879#第11集$id_XS0626BE8EEB48595850E878#第12集$id_XS0626BE8EEB48595850E87B#第13集$id_XS0626BE8EEB48595850E87A#第14集$id_XS0626BE8EEB48595850E87D#第15集$id_XS0626BE8EEB48595850E87C#第16集$id_XS0626BE8EEB48595850E87F#第17集$id_XS0626BE8EEB48595850E87E#第18集$id_XS0626BE8EEB48595850E871#第19集$id_XS0626BE8EEB48595850E870#第20集$id_XS0626BE8EEB48595850EB79#第21集$id_XS0626BE8EEB48595850EB78#第22集$id_XS0626BE8EEB48595850EB7B#第23集$id_XS0626BE8EEB48595850EB7A#第24集$id_XS0626BE8EEB48595850EB7D$$$第01集$id_MOE0626BE8EEB48595850E978#第02集$id_MOE0626BE8EEB48595850E97B#第03集$id_MOE0626BE8EEB48595850E97A#第04集$id_MOE0626BE8EEB48595850E97D#第05集$id_MOE0626BE8EEB48595850E97C#第06集$id_MOE0626BE8EEB48595850E97F#第07集$id_MOE0626BE8EEB48595850E97E#第08集$id_MOE0626BE8EEB48595850E971#第09集$id_MOE0626BE8EEB48595850E970#第10集$id_MOE0626BE8EEB48595850E879#第11集$id_MOE0626BE8EEB48595850E878#第12集$id_MOE0626BE8EEB48595850E87B#第13集$id_MOE0626BE8EEB48595850E87A#第14集$id_MOE0626BE8EEB48595850E87D#第15集$id_MOE0626BE8EEB48595850E87C#第16集$id_MOE0626BE8EEB48595850E87F#第17集$id_MOE0626BE8EEB48595850E87E#第18集$id_MOE0626BE8EEB48595850E871#第19集$id_MOE0626BE8EEB48595850E870#第20集$id_MOE0626BE8EEB48595850EB79#第21集$id_MOE0626BE8EEB48595850EB78#第22集$id_MOE0626BE8EEB48595850EB7B#第23集$id_MOE0626BE8EEB48595850EB7A#第24集$id_MOE0626BE8EEB48595850EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (60, 1, 0, 0, '暴食狂战士', '暴食のベルセルク～俺だけレベルという概念を突破して最強～（2023）', 'baoshikuangzhanshi', 1, 'B', '', '39383c51', '小说改,战斗,奇幻,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/15f82a44123fd96116cd158c86152e5822f34fbd.png', '', '', '', '逢坂良太 Ryota Ohsaka / 关智一 Tomokazu Seki / 东城日沙子 / 松冈美里 / 关根瞳', '柳泽哲也', '', '', '在技能优劣决定一切的世界，被轻蔑为无用之人的少年——斐特被迫过着最底层的生活。 斐特拥有的技能“暴食”是个只会饿肚子，完全派不上用场的能力。 他被处于这个世界顶层的圣骑士一族布雷利克家族盯上，每天都被', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 7.1, 0, 0, 1742795053, 1725915987, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在技能优劣决定一切的世界，被轻蔑为无用之人的少年——斐特被迫过着最底层的生活。 斐特拥有的技能“暴食”是个只会饿肚子，完全派不上用场的能力。 他被处于这个世界顶层的圣骑士一族布雷利克家族盯上，每天都被暴力相向，并被强迫去做杂活。 唯一的救赎便是同为圣骑士，却不会轻视斐特，并且愿意和他相处的人，萝琪希·哈特。 但偶然和她一起解决掉闯入城中的盗贼之后，世界完全改变了。 夺走敌人性命的瞬间，暴食能力发动，敌人的能力流入了自身。没错，斐特拥有的技能“暴食”就是从敌人身上夺取技能、能力的恐怖力量。 获得了战斗能力的斐特遇见了同样拥有冠以大罪之名的技能，并且拥有自我意志的剑，“贪婪”的格里德，进一步投身于斗争的世界之中。为了守护重要之人，为了对抗不合理的世界，斐特将阻挡在前方的敌人吞噬殆尽。曾经只能匍匐在地苟且偷生的少年，命运开始急速转动——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE022EBF80BA4A580850E978#第02集$MOE022EBF80BA4A580850E97B#第03集$MOE022EBF80BA4A580850E97A#第04集$MOE022EBF80BA4A580850E97D#第05集$MOE022EBF80BA4A580850E97C#第06集$MOE022EBF80BA4A580850E97F#第07集$MOE022EBF80BA4A580850E97E#第08集$MOE022EBF80BA4A580850E971#第09集$MOE022EBF80BA4A580850E970#第10集$MOE022EBF80BA4A580850E879#第11集$MOE022EBF80BA4A580850E878#第12集$MOE022EBF80BA4A580850E87B$$$第01集$id_XS022EBF80BA4A580850E978#第02集$id_XS022EBF80BA4A580850E97B#第03集$id_XS022EBF80BA4A580850E97A#第04集$id_XS022EBF80BA4A580850E97D#第05集$id_XS022EBF80BA4A580850E97C#第06集$id_XS022EBF80BA4A580850E97F#第07集$id_XS022EBF80BA4A580850E97E#第08集$id_XS022EBF80BA4A580850E971#第09集$id_XS022EBF80BA4A580850E970#第10集$id_XS022EBF80BA4A580850E879#第11集$id_XS022EBF80BA4A580850E878#第12集$id_XS022EBF80BA4A580850E87B$$$第01集$id_MOE022EBF80BA4A580850E978#第02集$id_MOE022EBF80BA4A580850E97B#第03集$id_MOE022EBF80BA4A580850E97A#第04集$id_MOE022EBF80BA4A580850E97D#第05集$id_MOE022EBF80BA4A580850E97C#第06集$id_MOE022EBF80BA4A580850E97F#第07集$id_MOE022EBF80BA4A580850E97E#第08集$id_MOE022EBF80BA4A580850E971#第09集$id_MOE022EBF80BA4A580850E970#第10集$id_MOE022EBF80BA4A580850E879#第11集$id_MOE022EBF80BA4A580850E878#第12集$id_MOE022EBF80BA4A580850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (61, 1, 0, 0, '圣剑学院的魔剑使', '聖剣学院の魔剣使い（2023）', 'shengjianxueyuandemojianshi', 1, 'S', '', '454d4edf', '奇幻,校园,魔法,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2898082254.jpg', '', '', '', '井上麻里奈 / 石川由依 / 洲崎绫 / 五十岚裕美 / 黑木穗乃香 / 仲田亚里沙', '森田宏幸', '', '', '　　不死者之魔王雷欧尼斯为了日后将会迎来的决战而将自身的灵魂封印了。', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 64, 0, 64, 64, '', 0, 0, 5.6, 0, 0, 1743756409, 1725977315, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '不死者之魔王雷欧尼斯为了日后将会迎来的决战而将自身的灵魂封印了。 然而他在1000年后再度醒来时，不知为何却变成了10岁少年的模样！？ 被隶属于〈圣剑学院〉的美少女利瑟莉娅所保护的雷欧尼斯，在对这个变得截然不同的世界一头雾水的情况下，在〈圣剑学院〉入学了。 未知的敌人〈Void〉、〈第07战术都市〉、外观观是武器形态却拥有异能之力的〈圣剑〉。 在魔法被遗忘的这个未来世界，最强魔王与美少女们交织而成的圣剑与魔剑的学园幻想物语盛大开幕！', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0522B8DCBD4C095F50E978#第02集$MOE0522B8DCBD4C095F50E97B#第03集$MOE0522B8DCBD4C095F50E97A#第04集$MOE0522B8DCBD4C095F50E97D#第05集$MOE0522B8DCBD4C095F50E97C#第06集$MOE0522B8DCBD4C095F50E97F#第07集$MOE0522B8DCBD4C095F50E97E#第08集$MOE0522B8DCBD4C095F50E971#第09集$MOE0522B8DCBD4C095F50E970#第10集$MOE0522B8DCBD4C095F50E879#第11集$MOE0522B8DCBD4C095F50E878#第12集$MOE0522B8DCBD4C095F50E87B$$$第01集$id_XS0522B8DCBD4C095F50E978#第02集$id_XS0522B8DCBD4C095F50E97B#第03集$id_XS0522B8DCBD4C095F50E97A#第04集$id_XS0522B8DCBD4C095F50E97D#第05集$id_XS0522B8DCBD4C095F50E97C#第06集$id_XS0522B8DCBD4C095F50E97F#第07集$id_XS0522B8DCBD4C095F50E97E#第08集$id_XS0522B8DCBD4C095F50E971#第09集$id_XS0522B8DCBD4C095F50E970#第10集$id_XS0522B8DCBD4C095F50E879#第11集$id_XS0522B8DCBD4C095F50E878#第12集$id_XS0522B8DCBD4C095F50E87B$$$第01集$id_MOE0522B8DCBD4C095F50E978#第02集$id_MOE0522B8DCBD4C095F50E97B#第03集$id_MOE0522B8DCBD4C095F50E97A#第04集$id_MOE0522B8DCBD4C095F50E97D#第05集$id_MOE0522B8DCBD4C095F50E97C#第06集$id_MOE0522B8DCBD4C095F50E97F#第07集$id_MOE0522B8DCBD4C095F50E97E#第08集$id_MOE0522B8DCBD4C095F50E971#第09集$id_MOE0522B8DCBD4C095F50E970#第10集$id_MOE0522B8DCBD4C095F50E879#第11集$id_MOE0522B8DCBD4C095F50E878#第12集$id_MOE0522B8DCBD4C095F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (62, 1, 0, 0, '我们的雨色协议', '僕らの雨いろプロトコル', 'womendeyusexieyi', 1, 'W', '', 'e592d446', '青春,竞技', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2898019595.jpg', '', '', '', '和气杏未,本渡枫,松冈祯丞,杉田智和,木村良平,麻仓桃,水濑祈,雨宫天,小野贤章', '山本靖贵', '', '', '　　与母亲和妹妹三人一起生活的高二学生·时野谷瞬。在父亲因事故去世，妹妹受伤后，他放弃了曾经痴迷的游戏，现在在电子竞技咖啡馆“FOX ONE”工作。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 3.7, 0, 0, 1725977805, 1725977680, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　与母亲和妹妹三人一起生活的高二学生·时野谷瞬。在父亲因事故去世，妹妹受伤后，他放弃了曾经痴迷的游戏，现在在电子竞技咖啡馆“FOX ONE”工作。<br/>　　边与身为青梅竹马的游戏朋友交往，边忙于打工和学习的瞬，突然发现“FOX ONE”负有巨额债务。为偿还债务，瞬和其他人一起为取得“扎克塞里昂锦标赛”的胜利，并获得奖金努力。<br/>　　怀着内疚的心情，瞬再次进入线上游戏的世界，而在他面前出现的是曾与他一起玩游戏的“爆裂君”。<br/>　　在未知的相遇和经历，以及激烈的战斗中...瞬边苦恼着边他与伙伴们一起前进。<br/>　　通过游戏开始的他们的世界。这是讲述少年和家人，还有伙伴们的故事──。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5422B58AED1D590F50E978#第02集$id_XS5422B58AED1D590F50E97B#第03集$id_XS5422B58AED1D590F50E97A#第04集$id_XS5422B58AED1D590F50E97D#第05集$id_XS5422B58AED1D590F50E97C#第06集$id_XS5422B58AED1D590F50E97F#第07集$id_XS5422B58AED1D590F50E97E#第08集$id_XS5422B58AED1D590F50E971#第09集$id_XS5422B58AED1D590F50E970#第10集$id_XS5422B58AED1D590F50E879#第11集$id_XS5422B58AED1D590F50E878#第12集$id_XS5422B58AED1D590F50E87B$$$第01集$id_MOE5422B58AED1D590F50E978#第02集$id_MOE5422B58AED1D590F50E97B#第03集$id_MOE5422B58AED1D590F50E97A#第04集$id_MOE5422B58AED1D590F50E97D#第05集$id_MOE5422B58AED1D590F50E97C#第06集$id_MOE5422B58AED1D590F50E97F#第07集$id_MOE5422B58AED1D590F50E97E#第08集$id_MOE5422B58AED1D590F50E971#第09集$id_MOE5422B58AED1D590F50E970#第10集$id_MOE5422B58AED1D590F50E879#第11集$id_MOE5422B58AED1D590F50E878#第12集$id_MOE5422B58AED1D590F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (63, 1, 0, 0, '地下忍者', 'アンダーニンジャ（2023）', 'dixiarenzhe', 1, 'D', '', 'd44dec2e', '战斗', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2897029251.jpg', '', '', '', '坂泰斗 / 新垣樽助 / 畠中祐 / 种崎敦美 / 山下大辉 / 安济知佳 / 内田修一 / 德井青空 / 相马康一', '桑原智', '', '', '　　战国时代和幕府时代曾经盛极一时的日本忍者，因为战败而强迫解散组织，似乎从历史中消失。然而事实上，多达20万人的忍者至今依旧暗中存在，秘密监视着过敏。貌不惊人的云隐九郎（坂泰斗 配音）每天半死不活待', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 0, 25, 25, '', 0, 0, 7.6, 0, 0, 1743756342, 1725979224, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '战国时代和幕府时代曾经盛极一时的日本忍者，因为战败而强迫解散组织，似乎从历史中消失。然而事实上，多达20万人的忍者至今依旧暗中存在，秘密监视着过敏。貌不惊人的云隐九郎（坂泰斗 配音）每天半死不活待在家里，看起来就是一个纯纯的废柴，其实他是一个身怀绝技的忍者。某天，冒充成快递员的上级找上门来，派他前往某高中与死对头的忍者部队作战。沉寂太久的云隐总算被组织唤醒了，但是这个任务并不是结束，反而是一系列大事件的开始…… 本片改编自花泽健吾创作的同名漫画作品。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5523B8DCEC4A5F5C50E978#第02集$MOE5523B8DCEC4A5F5C50E97B#第03集$MOE5523B8DCEC4A5F5C50E97A#第04集$MOE5523B8DCEC4A5F5C50E97D#第05集$MOE5523B8DCEC4A5F5C50E97C#第06集$MOE5523B8DCEC4A5F5C50E97F#第07集$MOE5523B8DCEC4A5F5C50E97E#第08集$MOE5523B8DCEC4A5F5C50E971#第09集$MOE5523B8DCEC4A5F5C50E970#第10集$MOE5523B8DCEC4A5F5C50E879#第11集$MOE5523B8DCEC4A5F5C50E878#第12集$MOE5523B8DCEC4A5F5C50E87B$$$第01集$id_XS5523B8DCEC4A5F5C50E978#第02集$id_XS5523B8DCEC4A5F5C50E97B#第03集$id_XS5523B8DCEC4A5F5C50E97A#第04集$id_XS5523B8DCEC4A5F5C50E97D#第05集$id_XS5523B8DCEC4A5F5C50E97C#第06集$id_XS5523B8DCEC4A5F5C50E97F#第07集$id_XS5523B8DCEC4A5F5C50E97E#第08集$id_XS5523B8DCEC4A5F5C50E971#第09集$id_XS5523B8DCEC4A5F5C50E970#第10集$id_XS5523B8DCEC4A5F5C50E879#第11集$id_XS5523B8DCEC4A5F5C50E878#第12集$id_XS5523B8DCEC4A5F5C50E87B$$$第01集$id_MOE5523B8DCEC4A5F5C50E978#第02集$id_MOE5523B8DCEC4A5F5C50E97B#第03集$id_MOE5523B8DCEC4A5F5C50E97A#第04集$id_MOE5523B8DCEC4A5F5C50E97D#第05集$id_MOE5523B8DCEC4A5F5C50E97C#第06集$id_MOE5523B8DCEC4A5F5C50E97F#第07集$id_MOE5523B8DCEC4A5F5C50E97E#第08集$id_MOE5523B8DCEC4A5F5C50E971#第09集$id_MOE5523B8DCEC4A5F5C50E970#第10集$id_MOE5523B8DCEC4A5F5C50E879#第11集$id_MOE5523B8D