INSERT INTO `mac_vod` VALUES (64, 1, 0, 0, '破灭之国', 'はめつのおうこく（2023）', 'pomiezhiguo', 1, 'P', '', 'f414eaab', '奇幻,魔法,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2887326628.jpg', '', '', '', '石川界人 / 和气杏未', '元永庆太郎', '', '', '　　自古以来被神送往人间并一直在帮助人类的魔女一族,因为超工业革命的发展变得对人类来说已不再是必要的存在,而是一种威胁。人类开始狩猎魔女以消除魔法的不科学力量。阿多尼斯是一个年轻的魔女学徒,当他眼睁睁', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 4.3, 0, 0, 1743411741, 1725979343, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>自古以来被神送往人间并一直在帮助人类的魔女一族,因为超工业革命的发展变得对人类来说已不再是必要的存在,而是一种威胁。人类开始狩猎魔女以消除魔法的不科学力量。阿多尼斯是一个年轻的魔女学徒,当他眼睁睁的看着倾慕的魔女导师克洛伊被猎杀,痛恨这一切的他决心用所学到的魔法向人类宣誓报仇。《破灭之国》是作者yoruhashi创作的漫画作品。近日官宣动画化！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5723BD8CEC480C5B50E978#第02集$MOE5723BD8CEC480C5B50E97B#第03集$MOE5723BD8CEC480C5B50E97A#第04集$MOE5723BD8CEC480C5B50E97D#第05集$MOE5723BD8CEC480C5B50E97C#第06集$MOE5723BD8CEC480C5B50E97F#第07集$MOE5723BD8CEC480C5B50E97E#第08集$MOE5723BD8CEC480C5B50E971#第09集$MOE5723BD8CEC480C5B50E970#第10集$MOE5723BD8CEC480C5B50E879#第11集$MOE5723BD8CEC480C5B50E878#第12集$MOE5723BD8CEC480C5B50E87B$$$第01集$id_XS5723BD8CEC480C5B50E978#第02集$id_XS5723BD8CEC480C5B50E97B#第03集$id_XS5723BD8CEC480C5B50E97A#第04集$id_XS5723BD8CEC480C5B50E97D#第05集$id_XS5723BD8CEC480C5B50E97C#第06集$id_XS5723BD8CEC480C5B50E97F#第07集$id_XS5723BD8CEC480C5B50E97E#第08集$id_XS5723BD8CEC480C5B50E971#第09集$id_XS5723BD8CEC480C5B50E970#第10集$id_XS5723BD8CEC480C5B50E879#第11集$id_XS5723BD8CEC480C5B50E878#第12集$id_XS5723BD8CEC480C5B50E87B$$$第01集$id_MOE5723BD8CEC480C5B50E978#第02集$id_MOE5723BD8CEC480C5B50E97B#第03集$id_MOE5723BD8CEC480C5B50E97A#第04集$id_MOE5723BD8CEC480C5B50E97D#第05集$id_MOE5723BD8CEC480C5B50E97C#第06集$id_MOE5723BD8CEC480C5B50E97F#第07集$id_MOE5723BD8CEC480C5B50E97E#第08集$id_MOE5723BD8CEC480C5B50E971#第09集$id_MOE5723BD8CEC480C5B50E970#第10集$id_MOE5723BD8CEC480C5B50E879#第11集$id_MOE5723BD8CEC480C5B50E878#第12集$id_MOE5723BD8CEC480C5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (65, 1, 0, 0, '放课后少年花子君', '放課後少年花子くん', 'fangkehoushaonianhuazijun', 1, 'F', '', 'b53b79d3', '漫画改,奇幻', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2899529180.jpg', '', '', '', '金泽舞,森永千才,吉田有里,由爱可奈,津田健次郎,小林大纪,水岛大宙,安济知佳,土岐隼一,佐藤未奈子,内田雄马,千叶翔也,鬼头明里,绪方惠美', '北村真咲', '', '', '　　海鸥学院七大不可思议之一“厕所里的花子君”和他的助手八寻宁宁。在没有大事发生的时候都在做什幺呢？', '全4集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 44, 0, 44, 44, '', 0, 0, 7.9, 0, 0, 1726054657, 1726028581, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　海鸥学院七大不可思议之一“厕所里的花子君”和他的助手八寻宁宁。在没有大事发生的时候都在做什幺呢？</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5322BFDABE10090A50E978#第02集$id_XS5322BFDABE10090A50E97B#第03集$id_XS5322BFDABE10090A50E97A#第04集$id_XS5322BFDABE10090A50E97D$$$第01集$id_MOE5322BFDABE10090A50E978#第02集$id_MOE5322BFDABE10090A50E97B#第03集$id_MOE5322BFDABE10090A50E97A#第04集$id_MOE5322BFDABE10090A50E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (74, 1, 0, 0, '明日方舟：冬隐归路', 'アークナイツ【冬隠帰路/PERISH IN FROST】（2023）', 'mingrifangzhoudongyinguilu', 1, 'M', '', 'e7880ebc', '游戏改,科幻,热血,战斗', 'https://i0.hdslb.com/bfs/bangumi/image/66c8609c341e82439366d72c2c4ba1b8143be121.png', '', '', '', '甲斐田幸 / 黑泽朋世 / 日笠阳子 / 加隈亚衣 / 广桥凉 / 种田梨沙 / 中原麻衣 / 福圆美里 / 小清水亚美 / 石上静香 / 德井青空 / 安野希世乃 / 山寺宏一 / 日高范子 / 伊藤加奈惠 / 坂本真绫 / 天崎滉平 / 堀江瞬 / 千本木彩花 / 竹达彩奈 / 高垣彩阳 / 银河万丈 / 庄司宇芽香', '渡边祐记 / 西川将贵', '', '', '矿石病——那是会让人体逐渐结晶化直至死亡的不治之症。  \r\n罗德岛制药公司为研制出治疗矿石病的特效药物，并为解决天灾与矿石病带来的各种问题与争端、改善感染者的处境而不断采取着行动。为阻止感染者组织整合运', '全8集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 8.9, 0, 0, 1743815766, 1726054739, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>矿石病——那是会让人体逐渐结晶化直至死亡的不治之症。 &nbsp;\r\n罗德岛制药公司为研制出治疗矿石病的特效药物，并为解决天灾与矿石病带来的各种问题与争端、改善感染者的处境而不断采取着行动。为阻止感染者组织整合运动的暴行，罗德岛与炎国城市龙门签订协议，为实现各自的目标而共同行动着。\r\n在经历了与米莎和碎骨的战斗之后，阿米娅无法接受现实，独自消沉着。\r\n而在另一边，罗德岛向分城废墟派遣的侦察小队，注意到了废城中出现的特异现象……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5420B480B94C0F5A50E978#第02集$MOE5420B480B94C0F5A50E97B#第03集$MOE5420B480B94C0F5A50E97A#第04集$MOE5420B480B94C0F5A50E97D#第05集$MOE5420B480B94C0F5A50E97C#第06集$MOE5420B480B94C0F5A50E97F#第07集$MOE5420B480B94C0F5A50E97E#第08集$MOE5420B480B94C0F5A50E971$$$第01集$id_XS5420B480B94C0F5A50E978#第02集$id_XS5420B480B94C0F5A50E97B#第03集$id_XS5420B480B94C0F5A50E97A#第04集$id_XS5420B480B94C0F5A50E97D#第05集$id_XS5420B480B94C0F5A50E97C#第06集$id_XS5420B480B94C0F5A50E97F#第07集$id_XS5420B480B94C0F5A50E97E#第08集$id_XS5420B480B94C0F5A50E971$$$第01集$id_MOE5420B480B94C0F5A50E978#第02集$id_MOE5420B480B94C0F5A50E97B#第03集$id_MOE5420B480B94C0F5A50E97A#第04集$id_MOE5420B480B94C0F5A50E97D#第05集$id_MOE5420B480B94C0F5A50E97C#第06集$id_MOE5420B480B94C0F5A50E97F#第07集$id_MOE5420B480B94C0F5A50E97E#第08集$id_MOE5420B480B94C0F5A50E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (66, 1, 0, 0, '依赖药水活下去！', 'ポーション頼みで生き延びます!（2023）', 'yilaiyaoshuihuoxiaqu', 1, 'Y', '', '2bc08ee', '小说改,异世界', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2888420783.jpg', '', '', '', '久住琳 / 高柳知叶 / 小泉萌香 / 岩田阳葵 / 北川菜月', '中西伸彰', '', '', '　　因为负责管理时空之神的失误，导致平凡的上班女郎长濑香失去肉体，被迫移转到异世界继续生存下去。迫於无奈只能照办的香，告别了亲爱的家人与好友，与神谈好条件，来到异世界展开新的人生。仰赖著异世界女神所赋', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 42, 0, 42, 42, '', 0, 0, 5.0, 0, 0, 1743411398, 1726044652, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '因为负责管理时空之神的失误，导致平凡的上班女郎长濑香失去肉体，被迫移转到异世界继续生存下去。迫於无奈只能照办的香，告别了亲爱的家人与好友，与神谈好条件，来到异世界展开新的人生。仰赖著异世界女神所赋予的外挂能力以及道具箱，香初到异世界便藉由她所制作的魔法药水打出名号，但也因为这样引来不肖份子对她的觊觎。 《依赖药水活下去!》是由FUNA著作的轻小说。近日官宣动画化！', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0375EF88B14C08144DE8#第02集$MOE0375EF88B14C08144DEB#第03集$MOE0375EF88B14C08144DEA#第04集$MOE0375EF88B14C08144DED#第05集$MOE0375EF88B14C08144DEC#第06集$MOE0375EF88B14C08144DEF#第07集$MOE0375EF88B14C08144DEE#第08集$MOE0375EF88B14C08144DE1#第09集$MOE0375EF88B14C08144DE0#第10集$MOE0375EF88B14C08144CE9#第11集$MOE0375EF88B14C08144CE8#第12集$MOE0375EF88B14C08144CEB$$$第01集$id_XS0375EF88B14C08144DE8#第02集$id_XS0375EF88B14C08144DEB#第03集$id_XS0375EF88B14C08144DEA#第04集$id_XS0375EF88B14C08144DED#第05集$id_XS0375EF88B14C08144DEC#第06集$id_XS0375EF88B14C08144DEF#第07集$id_XS0375EF88B14C08144DEE#第08集$id_XS0375EF88B14C08144DE1#第09集$id_XS0375EF88B14C08144DE0#第10集$id_XS0375EF88B14C08144CE9#第11集$id_XS0375EF88B14C08144CE8#第12集$id_XS0375EF88B14C08144CEB$$$第01集$id_MOE0375EF88B14C08144DE8#第02集$id_MOE0375EF88B14C08144DEB#第03集$id_MOE0375EF88B14C08144DEA#第04集$id_MOE0375EF88B14C08144DED#第05集$id_MOE0375EF88B14C08144DEC#第06集$id_MOE0375EF88B14C08144DEF#第07集$id_MOE0375EF88B14C08144DEE#第08集$id_MOE0375EF88B14C08144DE1#第09集$id_MOE0375EF88B14C08144DE0#第10集$id_MOE0375EF88B14C08144CE9#第11集$id_MOE0375EF88B14C08144CE8#第12集$id_MOE0375EF88B14C08144CEB', '', '', '', '', 0, '', '');
