INSERT INTO `mac_vod` VALUES (71, 1, 0, 0, '爱犬指令', 'ドッグシグナル（2023）', 'aiquanzhiling', 1, 'A', '', '4b8d978f', '漫画改,日常', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2899504942.jpg', '', '', '', '小野賢章 / 鈴村健一 / 甲斐田裕子 / KENN', '古桥一浩', '', '', '　　训犬师，那是连接狗狗和人类纽带的工作。优柔寡断的青年佐村未祐在和被前女友强塞的狗狗散步时遇见了专业训犬师·羽丹真一郎，偶然的相遇使未祐的人生发生了翻天覆地的变化！', '全20集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 6.3, 0, 0, 1743777048, 1726074646, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '训犬师，那是连接狗狗和人类纽带的工作。优柔寡断的青年佐村未祐在和被前女友强塞的狗狗散步时遇见了专业训犬师·羽丹真一郎，偶然的相遇使未祐的人生发生了翻天覆地的变化！', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0575B4DCB01E555F50E978#第02集$MOE0575B4DCB01E555F50E97B#第03集$MOE0575B4DCB01E555F50E97A#第04集$MOE0575B4DCB01E555F50E97D#第05集$MOE0575B4DCB01E555F50E97C#第06集$MOE0575B4DCB01E555F50E97F#第07集$MOE0575B4DCB01E555F50E97E#第08集$MOE0575B4DCB01E555F50E971#第09集$MOE0575B4DCB01E555F50E970#第10集$MOE0575B4DCB01E555F50E879#第11集$MOE0575B4DCB01E555F50E878#第12集$MOE0575B4DCB01E555F50E87B#第13集$MOE0575B4DCB01E555F50E87A#第14集$MOE0575B4DCB01E555F50E87D#第15集$MOE0575B4DCB01E555F50E87C#第16集$MOE0575B4DCB01E555F50E87F#第17集$MOE0575B4DCB01E555F50E87E#第18集$MOE0575B4DCB01E555F50E871#第19集$MOE0575B4DCB01E555F50E870#第20集$MOE0575B4DCB01E555F50EB79$$$第01集$id_XS0575B4DCB01E555F50E978#第02集$id_XS0575B4DCB01E555F50E97B#第03集$id_XS0575B4DCB01E555F50E97A#第04集$id_XS0575B4DCB01E555F50E97D#第05集$id_XS0575B4DCB01E555F50E97C#第06集$id_XS0575B4DCB01E555F50E97F#第07集$id_XS0575B4DCB01E555F50E97E#第08集$id_XS0575B4DCB01E555F50E971#第09集$id_XS0575B4DCB01E555F50E970#第10集$id_XS0575B4DCB01E555F50E879#第11集$id_XS0575B4DCB01E555F50E878#第12集$id_XS0575B4DCB01E555F50E87B#第13集$id_XS0575B4DCB01E555F50E87A#第14集$id_XS0575B4DCB01E555F50E87D#第15集$id_XS0575B4DCB01E555F50E87C#第16集$id_XS0575B4DCB01E555F50E87F#第17集$id_XS0575B4DCB01E555F50E87E#第18集$id_XS0575B4DCB01E555F50E871#第19集$id_XS0575B4DCB01E555F50E870#第20集$id_XS0575B4DCB01E555F50EB79$$$第01集$id_MOE0575B4DCB01E555F50E978#第02集