INSERT INTO `mac_vod` VALUES (1249, 4, 0, 0, '小刻的画图写话', '', 'xiaokedehuatuxiehua', 0, 'X', '', 'fafe19ef', '游戏改,日常,萌系,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/dd01a0fa36468116f0364ea97a48fc00d1dcc004.jpg', '', '', '', '刻俄柏：濑户麻沙美 \n泡泡：赤尾光\n泡普卡： 樱咲千依\n豆苗：伊藤彩沙\n伊桑：吉野裕行\n山：中井和哉', '五味子', '', '', '一、二、一、二，列队！鞠躬！欢迎！你好呀，博士，我是豆苗，从今天起“磐蟹咖啡厅”就要在罗德岛正式营业啦~店员就是我那群可爱的小家伙们，有阿岩、大力士……哎？她们三个？你是说小刻、泡泡还有泡普卡吗？不不', '全8集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.8, 0, 0, 1726075144, 1726075063, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '一、二、一、二，列队！鞠躬！欢迎！你好呀，博士，我是豆苗，从今天起“磐蟹咖啡厅”就要在罗德岛正式营业啦~店员就是我那群可爱的小家伙们，有阿岩、大力士……哎？她们三个？你是说小刻、泡泡还有泡普卡吗？不不，她们可不是店员，她们是……嗯，你来坐坐，喝杯咖啡就知道啦~', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5776EADDB810085F50E978#第02集$id_XS5776EADDB810085F50E97B#第03集$id_XS5776EADDB810085F50E97A#第04集$id_XS5776EADDB810085F50E97D#第05集$id_XS5776EADDB810085F50E97C#第06集$id_XS5776EADDB810085F50E97F#第07集$id_XS5776EADDB810085F50E97E#第08集$id_XS5776EADDB810085F50E971$$$第01集$id_MOE5776EADDB810085F50E978#第02集$id_MOE5776EADDB810085F50E97B#第03集$id_MOE5776EADDB810085F50E97A#第04集$id_MOE5776EADDB810085F50E97D#第05集$id_MOE5776EADDB810085F50E97C#第06集$id_MOE5776EADDB810085F50E97F#第07集$id_MOE5776EADDB810085F50E97E#第08集$id_MOE5776EADDB810085F50E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (75, 1, 0, 0, '巨兽防卫企业', 'ブルバスター Season 1', 'jushoufangweiqiye', 1, 'J', '', 'd75f5d9d', '科幻,机战', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2884098929.jpg', '', '', '', '楠大典,鱼建,高田忧希,三木真一郎,濑户麻沙美,千叶翔也', '青木弘安', '', '', '　　“发射一枚导弹需要花费多少？”“战斗人员的制服干洗费用是多少？”以现实的主题为观点，至今未闻的“经济上正确的”机器人英雄故事。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 5.9, 0, 0, 1726075286, 1726075193, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　“发射一枚导弹需要花费多少？”“战斗人员的制服干洗费用是多少？”以现实的主题为观点，至今未闻的“经济上正确的”机器人英雄故事。<br/>　　年轻的技术人员冲野铁郎，带着自己开发的新型机器人BULLBUSTER，被派往害兽驱除公司波止工业。<br/>　　与由田岛担任社长的波止对峙的是被名为“巨兽”的神秘生物！<br/>　　此外，作为一个总是缺钱的小公司，波止总是受到经济问题的影响……<br/>　　机器人的燃料费、驾驶员的人工费，甚至一颗子弹的浪费都是不可接受的。<br/>　　在消灭巨兽的“理想”和成本的“现实”的夹缝中，波止的未来会是怎样？</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5520B9DEBC4D545D50E978#第02集$id_XS5520B9DEBC4D545D50E97B#第03集$id_XS5520B9DEBC4D545D50E97A#第04集$id_XS5520B9DEBC4D545D50E97D#第05集$id_XS5520B9DEBC4D545D50E97C#第06集$id_XS5520B9DEBC4D545D50E97F#第07集$id_XS5520B9DEBC4D545D50E97E#第08集$id_XS5520B9DEBC4D545D50E971#第09集$id_XS5520B9DEBC4D545D50E970#第10集$id_XS5520B9DEBC4D545D50E879#第11集$id_XS5520B9DEBC4D545D50E878#第12集$id_XS5520B9DEBC4D545D50E87B$$$第01集$id_MOE5520B9DEBC4D545D50E978#第02集$id_MOE5520B9DEBC4D545D50E97B#第03集$id_MOE5520B9DEBC4D545D50E97A#第04集$id_MOE5520B9DEBC4D545D50E97D#第05集$id_MOE5520B9DEBC4D545D50E97C#第06集$id_MOE5520B9DEBC4D545D50E97F#第07集$id_MOE5520B9DEBC4D545D50E97E#第08集$id_MOE5520B9DEBC4D545D50E971#第09集$id_MOE5520B9DEBC4D545D50E970#第10集$id_MOE5520B9DEBC4D545D50E879#第11集$id_MOE5520B9DEBC4D545D50E878#第12集$id_MOE5520B9DEBC4D545D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (76, 1, 0, 0, '星灵感应', '星屑テレパス（2023）', 'xinglingganying', 1, 'X', '', '1bbbb668', '校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2897005120.jpg', '', '', '', '船户百合绘 / 深川芹亚 / 永牟田萌 / 青木志贵 / 羊宫妃那 / 高森奈津美 / 大野柚布子 / 白砂沙帆 / 川井田夏海 / 伊藤美来 / 黑木穗乃香 / 东城日沙子', '小森香织', '', '', '　　憧憬宇宙、不擅长表达的少女小之星海果，遇见了自称外星人、有心灵感应能力的少女明内幽。想去太空的海果和想回太空的小幽，想要用自己的双手建造可以飞去宇宙的火箭，故事就此展开。', '全12集', '', 0, '0', '', '', '日本', '十月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 7.3, 0, 0, 1744324044, 1726135819, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '憧憬宇宙、不擅长表达的少女小之星海果，遇见了自称外星人、有心灵感应能力的少女明内幽。想去太空的海果和想回太空的小幽，想要用自己的双手建造可以飞去宇宙的火箭，故事就此展开。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0075EEDAEB1F5B0150E978#第02集$MOE0075EEDAEB1F5B0150E97B#第03集$MOE0075EEDAEB1F5B0150E97A#第04集$MOE0075EEDAEB1F5B0150E97D#第05集$MOE0075EEDAEB1F5B0150E97C#第06集$MOE0075EEDAEB1F5B0150E97F#第07集$MOE0075EEDAEB1F5B0150E97E#第08集$MOE0075EEDAEB1F5B0150E971#第09集$MOE0075EEDAEB1F5B0150E970#第10集$MOE0075EEDAEB1F5B0150E879#第11集$MOE0075EEDAEB1F5B0150E878#第12集$MOE0075EEDAEB1F5B0150E87B$$$第01集$id_XS0075EEDAEB1F5B0150E978#第02集$id_XS0075EEDAEB1F5B0150E97B#第03集$id_XS0075EEDAEB1F5B0150E97A#第04集$id_XS0075EEDAEB1F5B0150E97D#第05集$id_XS0075EEDAEB1F5B0150E97C#第06集$id_XS0075EEDAEB1F5B0150E97F#第07集$id_XS0075EEDAEB1F5B0150E97E#第08集$id_XS0075EEDAEB1F5B0150E971#第09集$id_XS0075EEDAEB1F5B0150E970#第10集$id_XS0075EEDAEB1F5B0150E879#第11集$id_XS0075EEDAEB1F5B0150E878#第12集$id_XS0075EEDAEB1F5B0150E87B$$$第01集$id_MOE0075EEDAEB1F5B0150E978#第02集$id_MOE0075EEDAEB1F5B0150E97B#第03集$id_MOE0075EEDAEB1F5B0150E97A#第04集$id_MOE0075EEDAEB1F5B0150E97D#第05集$id_MOE0075EEDAEB1F5B0150E97C#第06集$id_MOE0075EEDAEB1F5B0150E97F#第07集$id_MOE0075EEDAEB1F5B0150E97E#第08集$id_MOE0075EEDAEB1F5B0150E971#第09集$id_MOE0075EEDAEB1F5B0150E970#第10集$id_MOE0075EEDAEB1F5B0150E879#第11集$id_MOE0075EEDAEB1F5B0150E878#第12集$id_MOE0075EEDAEB1F5B0150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (435, 1, 0, 0, '盾之勇者成名录 第三季', '', 'dunzhiyongzhechengmingludisanji', 1, 'D', '', 'cc9a9a9f', '小说改,战斗,奇幻,穿越', 'https://i0.hdslb.com/bfs/bangumi/image/dfe9d927f97b2531d32a8007ad4864c04acc0c6e.png', '', '', '', '岩谷尚文：石川界人\n拉芙塔莉雅：濑户麻沙美\n菲洛：日高里菜\n莉西亚：原奈津子\n天木炼：松冈祯丞\n北村元康：高桥信\n川澄树：山谷祥生\n梅尔蒂：内田真礼\n艾克雷尔：青木瑠璃子\n米蕾莉亚：井上喜久子\n麦茵：布莱德库特·莎拉·惠美\n奥托克雷：仲野裕\n娜迪亚：小清水亚美\n弗乌尔：天崎滉平\n亚朵拉：小原好美\n赛茵·洛克：长绳麻理亚', '垪和等', '', '', '盾之勇者岩谷尚文在讨伐四灵之一“灵龟”之后，前往其他异世界击败了复活灵龟的元凶——京，回到了梅洛马格。\r\n新的四灵“凤凰”即将复活，尚文本想为与其战斗做准备，却得知在灵龟骚乱中拖了后腿的三勇者下落不明，', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 7.2, 0, 0, 1732288191, 1726136032, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>盾之勇者岩谷尚文在讨伐四灵之一“灵龟”之后，前往其他异世界击败了复活灵龟的元凶——京，回到了梅洛马格。\n新的四灵“凤凰”即将复活，尚文本想为与其战斗做准备，却得知在灵龟骚乱中拖了后腿的三勇者下落不明，他自己的领地也没有足够的防卫力量。\n尚文打算将流落各地的露罗洛纳村居民寻回，为今后的战斗做准备，便前往泽特布尔，试图解救被作为奴隶在此贩卖的居民。在此过程中，他与拉芙塔莉雅和菲洛一起参加了地下赌博斗技。\n求救的亚人们，心碎的三勇者，以及在幕后蠢动的婊子·麦茵。\n各种思绪交错之中，尚文究竟能否坚持自己坚信的道路。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5274B5D9B048545F50E978#第02集$MOE5274B5D9B048545F50E97B#第03集$MOE5274B5D9B048545F50E97A#第04集$MOE5274B5D9B048545F50E97D#第05集$MOE5274B5D9B048545F50E97C#第06集$MOE5274B5D9B048545F50E97F#第07集$MOE5274B5D9B048545F50E97E#第08集$MOE5274B5D9B048545F50E971#第09集$MOE5274B5D9B048545F50E970#第10集$MOE5274B5D9B048545F50E879#第11集$MOE5274B5D9B048545F50E878#第12集$MOE5274B5D9B048545F50E87B$$$第01集$id_XS5274B5D9B048545F50E978#第02集$id_XS5274B5D9B048545F50E97B#第03集$id_XS5274B5D9B048545F50E97A#第04集$id_XS5274B5D9B048545F50E97D#第05集$id_XS5274B5D9B048545F50E97C#第06集$id_XS5274B5D9B048545F50E97F#第07集$id_XS5274B5D9B048545F50E97E#第08集$id_XS5274B5D9B048545F50E971#第09集$id_XS5274B5D9B048545F50E970#第10集$id_XS5274B5D9B048545F50E879#第11集$id_XS5274B5D9B048545F50E878#第12集$id_XS5274B5D9B048545F50E87B$$$第01集$id_MOE5274B5D9B048545F50E978#第02集$id_MOE5274B5D9B048545F50E97B#第03集$id_MOE5274B5D9B048545F50E97A#第04集$id_MOE5274B5D9B048545F50E97D#第05集$id_MOE5274B5D9B048545F50E97C#第06集$id_MOE5274B5D9B048545F50E97F#第07集$id_MOE5274B5D9B048545F50E97E#第08集$id_MOE5274B5D9B048545F50E971#第09集$id_MOE5274B5D9B048545F50E970#第10集$id_MOE5274B5D9B048545F50E879#第11集$id_MOE5274B5D9B048545F50E878#第12集$id_MOE5274B5D9B048545F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (78, 1, 0, 0, 'B-PROJECT 第三季', 'B-PROJECT ～熱烈＊ラブコール～', 'BPROJECTdisanji', 1, 'B', '', 'c0fd5c11', '偶像,音乐', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2897562839.jpg', '', '', '', '伊东健人,畠中祐,濑户麻沙美,江口拓也,千叶翔也,八代拓,西山宏太朗,增田俊树,大河元气,森久保祥太郎,柿原彻也,上村祐翔,加藤和树,花江夏树,丰永利行,岸尾大辅,小野大辅', '', '', '', '　　アイドルユニット「B-PROJECT」が\r\n                                    \r\n                                　　２度目の J', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 0.0, 0, 0, 1726177467, 1726177387, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　アイドルユニット「B-PROJECT」が<br/>　　２度目の JAPAN ドームライブを成功したことで、<br/>　　業界大手のレコード会社「ガンダーラミュージック」には変化の時が訪れていた。<br/>　　A&amp;R として働く主人公・澄空つばさは、<br/>　　「キタコレ」「THRIVE」「MooNs」「KiLLER KiNG」に加えて<br/>　　新たなジャンルから参画するアーティスト「ウルトラズ」も担当することになる。<br/>　　B-PROJECTとウルトラズの出会いから生み出されるシナジーにより<br/>　　刺激的で熱烈な”ラブコール”が今、響き渡る——！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5227EADCBC4A5C0850E978#第02集$id_XS5227EADCBC4A5C0850E97B#第03集$id_XS5227EADCBC4A5C0850E97A#第04集$id_XS5227EADCBC4A5C0850E97D#第05集$id_XS5227EADCBC4A5C0850E97C#第06集$id_XS5227EADCBC4A5C0850E97F#第07集$id_XS5227EADCBC4A5C0850E97E#第08集$id_XS5227EADCBC4A5C0850E971#第09集$id_XS5227EADCBC4A5C0850E970#第10集$id_XS5227EADCBC4A5C0850E879#第11集$id_XS5227EADCBC4A5C0850E878#第12集$id_XS5227EADCBC4A5C0850E87B$$$第01集$id_MOE5227EADCBC4A5C0850E978#第02集$id_MOE5227EADCBC4A5C0850E97B#第03集$id_MOE5227EADCBC4A5C0850E97A#第04集$id_MOE5227EADCBC4A5C0850E97D#第05集$id_MOE5227EADCBC4A5C0850E97C#第06集$id_MOE5227EADCBC4A5C0850E97F#第07集$id_MOE5227EADCBC4A5C0850E97E#第08集$id_MOE5227EADCBC4A5C0850E971#第09集$id_MOE5227EADCBC4A5C0850E970#第10集$id_MOE5227EADCBC4A5C0850E879#第11集$id_MOE5227EADCBC4A5C0850E878#第12集$id_MOE5227EADCBC4A5C0850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (79, 1, 0, 0, '凹凸魔女的亲子日常', 'でこぼこ魔女の親子事情', 'aotumonvdeqinzirichang', 1, 'A', '', '8c0fa7d3', '奇幻,魔法', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2897290112.jpg', '', '', '', '丰崎爱生,三石琴乃,近藤孝行,小野大辅,关根明良,花泽香菜,朴璐美,土师孝也,水树奈奈,古贺葵', '高田真宏', '', '', '　　某天，独居在森林里的魔女艾丽莎（声优：古贺葵）捡到了人类婴儿。艾丽莎替婴儿取名为「薇奥拉」，并决定扶养她。十六年后，薇奥拉（声优：水树奈奈）不只变成超级恋母的女孩，连个子和上围成长的幅度都超乎预料', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 7.1, 0, 0, 1726177875, 1726177819, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　某天，独居在森林里的魔女艾丽莎（声优：古贺葵）捡到了人类婴儿。艾丽莎替婴儿取名为「薇奥拉」，并决定扶养她。十六年后，薇奥拉（声优：水树奈奈）不只变成超级恋母的女孩，连个子和上围成长的幅度都超乎预料…</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0974BCDEE81E090A50E978#第02集$id_XS0974BCDEE81E090A50E97B#第03集$id_XS0974BCDEE81E090A50E97A#第04集$id_XS0974BCDEE81E090A50E97D#第05集$id_XS0974BCDEE81E090A50E97C#第06集$id_XS0974BCDEE81E090A50E97F#第07集$id_XS0974BCDEE81E090A50E97E#第08集$id_XS0974BCDEE81E090A50E971#第09集$id_XS0974BCDEE81E090A50E970#第10集$id_XS0974BCDEE81E090A50E879#第11集$id_XS0974BCDEE81E090A50E878#第12集$id_XS0974BCDEE81E090A50E87B$$$第01集$id_MOE0974BCDEE81E090A50E978#第02集$id_MOE0974BCDEE81E090A50E97B#第03集$id_MOE0974BCDEE81E090A50E97A#第04集$id_MOE0974BCDEE81E090A50E97D#第05集$id_MOE0974BCDEE81E090A50E97C#第06集$id_MOE0974BCDEE81E090A50E97F#第07集$id_MOE0974BCDEE81E090A50E97E#第08集$id_MOE0974BCDEE81E090A50E971#第09集$id_MOE0974BCDEE81E090A50E970#第10集$id_MOE0974BCDEE81E090A50E879#第11集$id_MOE0974BCDEE81E090A50E878#第12集$id_MOE0974BCDEE81E090A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (80, 1, 0, 0, '捡到退婚大小姐的我，教她幸福的事', '', 'jiandaotuihundaxiaojiedewojiaotaxingfudeshi', 1, 'J', '', '7c3f4bb3', '小说改,奇幻,治愈,萌系', 'https://i0.hdslb.com/bfs/bangumi/image/27bfeea269fc014b92ef478b899680549f98e20a.png', '', '', NULL, '亚连·库洛弗德:杉田智和\n夏洛特·埃文斯:早见沙织\n艾璐卡·库洛弗德：Lynn\n米赫·巴思妥斯:大空直美\n豪雪:置鲇龙太郎\n鲁:种崎敦美\n娜塔莉亚·埃文斯:前田佳织里', '浅见隆司', '', '', '本作讲述的，是住在森林深处，不爱见人的魔法师亚连，\n与被国家追捕的公爵千金夏洛特的故事。\n某一天，亚连在森林中发现了倒在地上，遍体鳞伤的千金夏洛特。亚连不爱见人却是个老好人，无法对她置之不理便将她带回', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 62, 0, 62, 62, '', 0, 0, 9.2, 0, 0, 1726178086, 1726178069, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '本作讲述的，是住在森林深处，不爱见人的魔法师亚连，\n与被国家追捕的公爵千金夏洛特的故事。\n某一天，亚连在森林中发现了倒在地上，遍体鳞伤的千金夏洛特。亚连不爱见人却是个老好人，无法对她置之不理便将她带回了宅邸。\n遭到家庭的不公对待，还被未婚夫背叛的夏洛特让亚连心生同情，便雇佣她做自己的女仆，并让她在自己的宅邸里住了下来。\n亚连本以为夏洛特会立刻离开宅邸，却因为一个契机，要开始教她坏坏的事？！', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0674BFDEBD4B0F0A50E978#第02集$id_XS0674BFDEBD4B0F0A50E97B#第03集$id_XS0674BFDEBD4B0F0A50E97A#第04集$id_XS0674BFDEBD4B0F0A50E97D#第05集$id_XS0674BFDEBD4B0F0A50E97C#第06集$id_XS0674BFDEBD4B0F0A50E97F#第07集$id_XS0674BFDEBD4B0F0A50E97E#第08集$id_XS0674BFDEBD4B0F0A50E971#第09集$id_XS0674BFDEBD4B0F0A50E970#第10集$id_XS0674BFDEBD4B0F0A50E879#第11集$id_XS0674BFDEBD4B0F0A50E878#第12集$id_XS0674BFDEBD4B0F0A50E87B$$$第01集$id_MOE0674BFDEBD4B0F0A50E978#第02集$id_MOE0674BFDEBD4B0F0A50E97B#第03集$id_MOE0674BFDEBD4B0F0A50E97A#第04集$id_MOE0674BFDEBD4B0F0A50E97D#第05集$id_MOE0674BFDEBD4B0F0A50E97C#第06集$id_MOE0674BFDEBD4B0F0A50E97F#第07集$id_MOE0674BFDEBD4B0F0A50E97E#第08集$id_MOE0674BFDEBD4B0F0A50E971#第09集$id_MOE0674BFDEBD4B0F0A50E970#第10集$id_MOE0674BFDEBD4B0F0A50E879#第11集$id_MOE0674BFDEBD4B0F0A50E878#第12集$id_MOE0674BFDEBD4B0F0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (81, 1, 0, 0, 'OVERTAKE！', 'オーバーテイク！', 'OVERTAKE', 1, 'O', '', 'f93d089c', '运动,励志', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2889733037.jpg', '', '', '', '古屋亚南,小西克幸', '青木荣', '', '', '　　TROYCA官宣十周年纪念作始动决定！', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 7.7, 0, 0, 1726229026, 1726228966, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　TROYCA官宣十周年纪念作始动决定！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS572EBFDCB911545A50E978#第02集$id_XS572EBFDCB911545A50E97B#第03集$id_XS572EBFDCB911545A50E97A#第04集$id_XS572EBFDCB911545A50E97D#第05集$id_XS572EBFDCB911545A50E97C#第06集$id_XS572EBFDCB911545A50E97F#第07集$id_XS572EBFDCB911545A50E97E#第08集$id_XS572EBFDCB911545A50E971#第09集$id_XS572EBFDCB911545A50E970#第10集$id_XS572EBFDCB911545A50E879#第11集$id_XS572EBFDCB911545A50E878#第12集$id_XS572EBFDCB911545A50E87B$$$第01集$id_MOE572EBFDCB911545A50E978#第02集$id_MOE572EBFDCB911545A50E97B#第03集$id_MOE572EBFDCB911545A50E97A#第04集$id_MOE572EBFDCB911545A50E97D#第05集$id_MOE572EBFDCB911545A50E97C#第06集$id_MOE572EBFDCB911545A50E97F#第07集$id_MOE572EBFDCB911545A50E97E#第08集$id_MOE572EBFDCB911545A50E971#第09集$id_MOE572EBFDCB911545A50E970#第10集$id_MOE572EBFDCB911545A50E879#第11集$id_MOE572EBFDCB911545A50E878#第12集$id_MOE572EBFDCB911545A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (82, 1, 0, 0, '米奇与达利', '', 'miqiyudali', 1, 'M', '', '5a09a6d4', '漫画改,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/ceb28a13bdd54d328fec61ddb20aab6210a37a9b.png', '', '', NULL, '米奇：堀江瞬\n达利：村濑歩\n园山洋子：三石琴乃\n园山修：松山鹰志\n秋山俊平：浅沼晋太郎\n堤圆太：武内骏辅\n一条瑛二：河西健吾\n梅托莉：诸星堇\n小光：齐藤贵美子\n一条怜子：朴璐美\n一条瑛：川岛得爱\n一条华怜：关根明良', 'Mankyu', '', '', '1990年2月\n神户市北区俄勒冈村\n在孤儿院生活的双胞胎少年米奇与达利，\n有一天被富裕而安详的老夫妇园山夫妻收为了养子。\n但他们并非以「米奇」与「达利」两位少年的身份，\n而是以「园山秘鸟」这一位少年的', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 9.7, 0, 0, 1726229905, 1726229860, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '1990年2月\n神户市北区俄勒冈村\n在孤儿院生活的双胞胎少年米奇与达利，\n有一天被富裕而安详的老夫妇园山夫妻收为了养子。\n但他们并非以「米奇」与「达利」两位少年的身份，\n而是以「园山秘鸟」这一位少年的身份被收养的。\n二人隐瞒了真实身份，\n在扮演园山秘鸟的同时融入俄勒冈村。\n二人究竟为何要扮演同一个人？\n其中包含着巨大的秘密和惊人的目的。', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0476BC81E81F090D50E978#第02集$id_XS0476BC81E81F090D50E97B#第03集$id_XS0476BC81E81F090D50E97A#第04集$id_XS0476BC81E81F090D50E97D#第05集$id_XS0476BC81E81F090D50E97C#第06集$id_XS0476BC81E81F090D50E97F#第07集$id_XS0476BC81E81F090D50E97E#第08集$id_XS0476BC81E81F090D50E971#第09集$id_XS0476BC81E81F090D50E970#第10集$id_XS0476BC81E81F090D50E879#第11集$id_XS0476BC81E81F090D50E878#第12集$id_XS0476BC81E81F090D50E87B#第13集$id_XS0476BC81E81F090D50E87A$$$第01集$id_MOE0476BC81E81F090D50E978#第02集$id_MOE0476BC81E81F090D50E97B#第03集$id_MOE0476BC81E81F090D50E97A#第04集$id_MOE0476BC81E81F090D50E97D#第05集$id_MOE0476BC81E81F090D50E97C#第06集$id_MOE0476BC81E81F090D50E97F#第07集$id_MOE0476BC81E81F090D50E97E#第08集$id_MOE0476BC81E81F090D50E971#第09集$id_MOE0476BC81E81F090D50E970#第10集$id_MOE0476BC81E81F090D50E879#第11集$id_MOE0476BC81E81F090D50E878#第12集$id_MOE0476BC81E81F090D50E87B#第13集$id_MOE0476BC81E81F090D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (876, 1, 0, 0, '世界尽头的圣骑士 铁锖山之王', '最果てのパラディン 鉄錆の山の王 Season 2', 'shijiejintoudeshengqishitieqiangshanzhiwang', 1, 'S', '', '7f851433', '奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2898120394.jpg', '', '', '', '稻叶实,飞田展男,堀江由衣,小西克幸,河濑茉希,悠木碧,乃村健次,游佐浩二,铃木绘理,村濑步,千叶翔也', '岩永彰', '', '', '　　离开死者之街过去了两年，威尔也已经17岁了。\r\n                                    \r\n                                　　作为领主', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 6.3, 0, 0, 1726230067, 1726230013, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　离开死者之街过去了两年，威尔也已经17岁了。<br/>　　作为领主，他发展了“灯火河港”，渐渐地，“兽之森”恢复生机。<br/>　　但是，不合季节的花朵绽放，森林出现异常。为了解决这个问题而前往森林深处的威尔等人，从森林之王那里得到了不祥预言。<br/>　　“铁锈的山脉上，会发生‘黑灾之火’，火会熊熊燃烧将这片土地全部烧毁。”<br/>　　在灭亡的矮人之都“铁锈山脉”中沉睡的灾难是？与新的相遇一起，威尔他们的冒险再次开始！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0671B48DB81D5E0A50E978#第02集$id_XS0671B48DB81D5E0A50E97B#第03集$id_XS0671B48DB81D5E0A50E97A#第04集$id_XS0671B48DB81D5E0A50E97D#第05集$id_XS0671B48DB81D5E0A50E97C#第06集$id_XS0671B48DB81D5E0A50E97F#第07集$id_XS0671B48DB81D5E0A50E97E#第08集$id_XS0671B48DB81D5E0A50E971#第09集$id_XS0671B48DB81D5E0A50E970#第10集$id_XS0671B48DB81D5E0A50E879#第11集$id_XS0671B48DB81D5E0A50E878#第12集$id_XS0671B48DB81D5E0A50E87B$$$第01集$id_MOE0671B48DB81D5E0A50E978#第02集$id_MOE0671B48DB81D5E0A50E97B#第03集$id_MOE0671B48DB81D5E0A50E97A#第04集$id_MOE0671B48DB81D5E0A50E97D#第05集$id_MOE0671B48DB81D5E0A50E97C#第06集$id_MOE0671B48DB81D5E0A50E97F#第07集$id_MOE0671B48DB81D5E0A50E97E#第08集$id_MOE0671B48DB81D5E0A50E971#第09集$id_MOE0671B48DB81D5E0A50E970#第10集$id_MOE0671B48DB81D5E0A50E879#第11集$id_MOE0671B48DB81D5E0A50E878#第12集$id_MOE0671B48DB81D5E0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (84, 1, 0, 0, '哥布林杀手 第二季', 'ゴブリンスレイヤー 2期', 'gebulinshashoudierji', 1, 'G', '', 'dbdffa16', '奇幻,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2889732719.jpg', '', '', '', '伊濑茉莉也,松冈祯丞,日笠阳子,杉田智和,中村悠一,内田真礼,井口裕香,东山奈央,小仓唯,梅原裕一郎', '尾崎隆晴', '', '', '　　「俺は世界を救わない。ゴブリンを殺すだけだ」\r\n                                    \r\n                                　　辺境のギ', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 39, 0, 39, 39, '', 0, 0, 6.5, 0, 0, 1732326276, 1726257370, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　「俺は世界を救わない。ゴブリンを殺すだけだ」<br/>　　辺境のギルドには、ゴブリン討伐だけで銀等級（序列三位）にまで上り詰めた稀有な存在がいるという……。<br/>　　冒険者になって、はじめて組んだパーティがピンチとなった女神官。<br/>　　それを助けた者こそ、ゴブリンスレイヤーと呼ばれる男だったーー</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5575E8DEEF485C0F50E978#第02集$MOE5575E8DEEF485C0F50E97B#第03集$MOE5575E8DEEF485C0F50E97A#第04集$MOE5575E8DEEF485C0F50E97D#第05集$MOE5575E8DEEF485C0F50E97C#第06集$MOE5575E8DEEF485C0F50E97F#第07集$MOE5575E8DEEF485C0F50E97E#第08集$MOE5575E8DEEF485C0F50E971#第09集$MOE5575E8DEEF485C0F50E970#第10集$MOE5575E8DEEF485C0F50E879#第11集$MOE5575E8DEEF485C0F50E878#第12集$MOE5575E8DEEF485C0F50E87B$$$第01集$id_XS5575E8DEEF485C0F50E978#第02集$id_XS5575E8DEEF485C0F50E97B#第03集$id_XS5575E8DEEF485C0F50E97A#第04集$id_XS5575E8DEEF485C0F50E97D#第05集$id_XS5575E8DEEF485C0F50E97C#第06集$id_XS5575E8DEEF485C0F50E97F#第07集$id_XS5575E8DEEF485C0F50E97E#第08集$id_XS5575E8DEEF485C0F50E971#第09集$id_XS5575E8DEEF485C0F50E970#第10集$id_XS5575E8DEEF485C0F50E879#第11集$id_XS5575E8DEEF485C0F50E878#第12集$id_XS5575E8DEEF485C0F50E87B$$$第01集$id_MOE5575E8DEEF485C0F50E978#第02集$id_MOE5575E8DEEF485C0F50E97B#第03集$id_MOE5575E8DEEF485C0F50E97A#第04集$id_MOE5575E8DEEF485C0F50E97D#第05集$id_MOE5575E8DEEF485C0F50E97C#第06集$id_MOE5575E8DEEF485C0F50E97F#第07集$id_MOE5575E8DEEF485C0F50E97E#第08集$id_MOE5575E8DEEF485C0F50E971#第09集$id_MOE5575E8DEEF485C0F50E970#第10集$id_MOE5575E8DEEF485C0F50E879#第11集$id_MOE5575E8DEEF485C0F50E878#第12集$id_MOE5575E8DEEF485C0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (85, 4, 0, 0, '魔法使的新娘 第二季  Part.2', '魔法使いの嫁 SEASON2 第2クール', 'mofashidexinniangdierjiPart2', 0, 'M', '', '5876ccca', '漫画改,奇幻,治愈,恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2902254217.jpg', '', '', '', '诹访部顺一,甲斐田裕子,浪川大辅,定冈小百合,小山茉美,鸟海浩辅,夏谷美希,田中美海,山下大辉,田村睦心,日野聪,西山宏太朗,上田丽奈,小林大纪,山下诚一郎,河濑茉希,津田美波,远藤绫,内山昂辉,竹内良太,种崎敦美', '寺泽和晃', '', '', '　　すべてではない。けれど、エリアスを、\r\n                                    \r\n                                　　自分を受け入れる', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 1, 0, 1, 1, '', 0, 0, 7.6, 0, 0, 1726287812, 1726285991, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　すべてではない。けれど、エリアスを、<br/>　　自分を受け入れることができたチセ。<br/>　　カルタフィルスがひとときの眠りにつき、<br/>　　日常を取り戻した彼女の元に<br/>　　届いたのは、魔術師たちの<br/>　　相互扶助組織『学院』への招待状だった――。<br/>　　大英図書館の地下……<br/>　　今までとは違う魔術師達の社会。<br/>　　”人”との出会いと交わりが、<br/>　　新たな扉を開いてゆく。<br/>　　これは、私（あなた）を救う為の物語。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS042FBB8EEA4A0E5850E978#第02集$id_XS042FBB8EEA4A0E5850E97B#第03集$id_XS042FBB8EEA4A0E5850E97A#第04集$id_XS042FBB8EEA4A0E5850E97D#第05集$id_XS042FBB8EEA4A0E5850E97C#第06集$id_XS042FBB8EEA4A0E5850E97F#第07集$id_XS042FBB8EEA4A0E5850E97E#第08集$id_XS042FBB8EEA4A0E5850E971#第09集$id_XS042FBB8EEA4A0E5850E970#第10集$id_XS042FBB8EEA4A0E5850E879#第11集$id_XS042FBB8EEA4A0E5850E878#第12集$id_XS042FBB8EEA4A0E5850E87B$$$第01集$id_MOE042FBB8EEA4A0E5850E978#第02集$id_MOE042FBB8EEA4A0E5850E97B#第03集$id_MOE042FBB8EEA4A0E5850E97A#第04集$id_MOE042FBB8EEA4A0E5850E97D#第05集$id_MOE042FBB8EEA4A0E5850E97C#第06集$id_MOE042FBB8EEA4A0E5850E97F#第07集$id_MOE042FBB8EEA4A0E5850E97E#第08集$id_MOE042FBB8EEA4A0E5850E971#第09集$id_MOE042FBB8EEA4A0E5850E970#第10集$id_MOE042FBB8EEA4A0E5850E879#第11集$id_MOE042FBB8EEA4A0E5850E878#第12集$id_MOE042FBB8EEA4A0E5850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (86, 1, 0, 0, '家里蹲吸血姬的苦闷', 'ひきこまり吸血姫の悶々 Season 1', 'jialidunxixuejidekumen', 1, 'J', '', 'b5fc876', '冒险,奇幻,魔法', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2897004066.jpg', '', '', '', '井上和彦,菲鲁兹·蓝,石见舞菜香,岛袋美由利,日笠阳子,铃代纱弓,楠木灯', '南川达马', '', '', '　　《家里蹲吸血姬的苦闷》是小林湖底著作、りいちゅ负责插画、GA文库所属的轻小说。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 6.9, 0, 0, 1726287989, 1726287854, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　《家里蹲吸血姬的苦闷》是小林湖底著作、りいちゅ负责插画、GA文库所属的轻小说。<br/>　　为第11届GA文库大奖优秀奖得奖作品。近日官宣动画化决定！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5322EADBB11E5B144DE8#第02集$id_XS5322EADBB11E5B144DEB#第03集$id_XS5322EADBB11E5B144DEA#第04集$id_XS5322EADBB11E5B144DED#第05集$id_XS5322EADBB11E5B144DEC#第06集$id_XS5322EADBB11E5B144DEF#第07集$id_XS5322EADBB11E5B144DEE#第08集$id_XS5322EADBB11E5B144DE1#第09集$id_XS5322EADBB11E5B144DE0#第10集$id_XS5322EADBB11E5B144CE9#第11集$id_XS5322EADBB11E5B144CE8#第12集$id_XS5322EADBB11E5B144CEB$$$第01集$id_MOE5322EADBB11E5B144DE8#第02集$id_MOE5322EADBB11E5B144DEB#第03集$id_MOE5322EADBB11E5B144DEA#第04集$id_MOE5322EADBB11E5B144DED#第05集$id_MOE5322EADBB11E5B144DEC#第06集$id_MOE5322EADBB11E5B144DEF#第07集$id_MOE5322EADBB11E5B144DEE#第08集$id_MOE5322EADBB11E5B144DE1#第09集$id_MOE5322EADBB11E5B144DE0#第10集$id_MOE5322EADBB11E5B144CE9#第11集$id_MOE5322EADBB11E5B144CE8#第12集$id_MOE5322EADBB11E5B144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (436, 1, 0, 0, '想要成为影之实力者！第二季', '陰の実力者になりたくて！ 2nd season Season 2', 'xiangyaochengweiyingzhishilizhedierji', 1, 'X', '', '24db93db', '异世界,奇幻,冒险,魔法', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2897790474.jpg', '', '', '', '市道真央,白石晴香,羊宫妃那,富田美忧,伊藤美来,前川凉子,南真由,内田真礼,长谷川育美,早见沙织,近藤玲奈,朝井彩加,金元寿子,菲鲁兹·蓝,三森铃子,水濑祈,濑户麻沙美,杉田智和,小山刚志,伊藤静,加隈亚衣,日高里菜,山下诚一郎', '中西和也', '', '', '　　接下来的舞台是由“血之女王”、“妖狐”、“暴君”三势力统治的无法都市。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 182, 0, 182, 182, '', 0, 0, 8.4, 0, 0, 1726288304, 1726288259, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　接下来的舞台是由“血之女王”、“妖狐”、“暴君”三势力统治的无法都市。<br/>　　那里是无赖横行、弱肉强食的世界。为了讨伐吸血鬼们的支配者“血之女王”被姐姐克莱儿带走的希德，因为有机会做出“影之实力者”的行为而兴奋不已……。<br/>　　围绕“血之女王”的阴谋开始展开，无法都市三股势力混杂一起。<br/>　　此外，姐姐克莱儿也被卷入骚乱，暗影庭院也独自采取行动。<br/>　　在极度混沌中，希德不为人知地开始扮演幕后暗影。<br/>　　红月升起，觉醒的时刻到来了……</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0323E8DAB01A095B50E978#第02集$id_XS0323E8DAB01A095B50E97B#第03集$id_XS0323E8DAB01A095B50E97A#第04集$id_XS0323E8DAB01A095B50E97D#第05集$id_XS0323E8DAB01A095B50E97C#第06集$id_XS0323E8DAB01A095B50E97F#第07集$id_XS0323E8DAB01A095B50E97E#第08集$id_XS0323E8DAB01A095B50E971#第09集$id_XS0323E8DAB01A095B50E970#第10集$id_XS0323E8DAB01A095B50E879#第11集$id_XS0323E8DAB01A095B50E878#第12集$id_XS0323E8DAB01A095B50E87B$$$第01集$id_MOE0323E8DAB01A095B50E978#第02集$id_MOE0323E8DAB01A095B50E97B#第03集$id_MOE0323E8DAB01A095B50E97A#第04集$id_MOE0323E8DAB01A095B50E97D#第05集$id_MOE0323E8DAB01A095B50E97C#第06集$id_MOE0323E8DAB01A095B50E97F#第07集$id_MOE0323E8DAB01A095B50E97E#第08集$id_MOE0323E8DAB01A095B50E971#第09集$id_MOE0323E8DAB01A095B50E970#第10集$id_MOE0323E8DAB01A095B50E879#第11集$id_MOE0323E8DAB01A095B50E878#第12集$id_MOE0323E8DAB01A095B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (88, 1, 0, 0, '鸭乃桥论的禁忌推理', '', 'yanaiqiaolundejinjituili', 1, 'Y', '', 'c2b0da71', '漫画改,推理', 'https://i0.hdslb.com/bfs/bangumi/image/9f914538facb41e31fc264aaed01fc0923de8d24.png', '', '', '', '鸭乃桥论：阿座上洋平\n一色都都丸：榎木淳弥\n雨宫：日笠阳子\n修比兹·费亚：八代拓', '井畑翔太', '', '', '世界最顶尖的侦探学校“青蓝（BLUE）”，曾经有一位前途无量的稀世天才，那就是被称为青蓝创办以来最富天资之人——鸭乃桥论。而他却因为校内的某个事件，患上了作为侦探的致命“缺陷”，被逐出青蓝，并被禁止从', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 66, 0, 66, 66, '', 0, 0, 9.1, 0, 0, 1731277739, 1726288346, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '世界最顶尖的侦探学校“青蓝（BLUE）”，曾经有一位前途无量的稀世天才，那就是被称为青蓝创办以来最富天资之人——鸭乃桥论。而他却因为校内的某个事件，患上了作为侦探的致命“缺陷”，被逐出青蓝，并被禁止从事侦探工作。\n其后的五年，论一直在失意与百无聊赖中度日。直到有一天，警视厅搜查一课的刑警·一色都都丸前来请他协助侦破连环杀人案，论停止的时间再次开始流动。\n一色都都丸知晓论的烦恼，热心地提出协助他，是个“单纯的傻瓜”。\n论称呼都都丸为“都都”，感觉与他的合作蕴藏着无限的可能性，便任命都都为自己的助手。\n这对略有隐情且反差巨大的侦探搭档，将一个又一个神秘案件华丽地侦破……', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5225EE88ED485A0850E978#第02集$id_XS5225EE88ED485A0850E97B#第03集$id_XS5225EE88ED485A0850E97A#第04集$id_XS5225EE88ED485A0850E97D#第05集$id_XS5225EE88ED485A0850E97C#第06集$id_XS5225EE88ED485A0850E97F#第07集$id_XS5225EE88ED485A0850E97E#第08集$id_XS5225EE88ED485A0850E971#第09集$id_XS5225EE88ED485A0850E970#第10集$id_XS5225EE88ED485A0850E879#第11集$id_XS5225EE88ED485A0850E878#第12集$id_XS5225EE88ED485A0850E87B#第13集$id_XS5225EE88ED485A0850E87A$$$第01集$id_MOE5225EE88ED485A0850E978#第02集$id_MOE5225EE88ED485A0850E97B#第03集$id_MOE5225EE88ED485A0850E97A#第04集$id_MOE5225EE88ED485A0850E97D#第05集$id_MOE5225EE88ED485A0850E97C#第06集$id_MOE5225EE88ED485A0850E97F#第07集$id_MOE5225EE88ED485A0850E97E#第08集$id_MOE5225EE88ED485A0850E971#第09集$id_MOE5225EE88ED485A0850E970#第10集$id_MOE5225EE88ED485A0850E879#第11集$id_MOE5225EE88ED485A0850E878#第12集$id_MOE5225EE88ED485A0850E87B#第13集$id_MOE5225EE88ED485A0850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (89, 1, 0, 0, '超超超超超喜欢你的100个女朋友', '君のことが大大大大大好きな100人の彼女', 'chaochaochaochaochaoxihuannide100genvpengyou', 1, 'C', '', '1ad57d58', '校园,恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2893920908.jpg', '', '', '', '上坂堇,千叶繁,朝井彩加,濑户麻沙美,长绳麻理亚,本渡枫,富田美忧,加藤涉', '佐藤光', '', '', '　　初中的毕业典礼上，爱城恋太郎进行了人生的第100次告白，', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 165, 0, 165, 165, '', 0, 0, 8.0, 0, 0, 1726288767, 1726288712, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　初中的毕业典礼上，爱城恋太郎进行了人生的第100次告白，<br/>　　但和先前的99次一样，都被拒绝了。<br/>　　恋太郎在男女间的评价一直都很好，但总是无法被女孩当作恋爱对象。<br/>　　这天，恋太郎来到了祈求缘分的神社，<br/>　　在他虔诚膜拜时，神出现了。<br/>　　神告诉恋太郎，在升上高中后恋太郎将会遇到命运之人，并且总共有100人……。<br/>　　DEAD·OR·LOVE的学园新生活开幕！！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0076E88DBE4D580150E978#第02集$id_XS0076E88DBE4D580150E97B#第03集$id_XS0076E88DBE4D580150E97A#第04集$id_XS0076E88DBE4D580150E97D#第05集$id_XS0076E88DBE4D580150E97C#第06集$id_XS0076E88DBE4D580150E97F#第07集$id_XS0076E88DBE4D580150E97E#第08集$id_XS0076E88DBE4D580150E971#第09集$id_XS0076E88DBE4D580150E970#第10集$id_XS0076E88DBE4D580150E879#第11集$id_XS0076E88DBE4D580150E878#第12集$id_XS0076E88DBE4D580150E87B$$$第01集$id_MOE0076E88DBE4D580150E978#第02集$id_MOE0076E88DBE4D580150E97B#第03集$id_MOE0076E88DBE4D580150E97A#第04集$id_MOE0076E88DBE4D580150E97D#第05集$id_MOE0076E88DBE4D580150E97C#第06集$id_MOE0076E88DBE4D580150E97F#第07集$id_MOE0076E88DBE4D580150E97E#第08集$id_MOE0076E88DBE4D580150E971#第09集$id_MOE0076E88DBE4D580150E970#第10集$id_MOE0076E88DBE4D580150E879#第11集$id_MOE0076E88DBE4D580150E878#第12集$id_MOE0076E88DBE4D580150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (90, 1, 0, 0, '经验丰富的你和经验为零的我交往的故事', '経験済みなキミと、 経験ゼロなオレが、 お付き合いする話。', 'jingyanfengfudenihejingyanweilingdewojiaowangdegushi', 1, 'J', '', 'ea5e14df', '校园,恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2900242927.jpg', '', '', '', '冈本信彦,内田真礼,前野智昭,阪口大助,落合福嗣,楠木灯,福原绫香,古贺葵,大西沙织,花江夏树', '大庭秀昭', '', '', '　　加岛龙斗和好友游玩惩罚游戏输掉后，在认为自己不会成功的想法下，向倾慕的对象白河月爱表白。但月爱意外地接受了表白，且当天就将龙斗带到自己的房间，准备进行性行为，在龙斗的劝说下，月爱决定等到打从心底喜', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 63, 0, 63, 63, '', 0, 0, 5.5, 0, 0, 1726289076, 1726289010, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　加岛龙斗和好友游玩惩罚游戏输掉后，在认为自己不会成功的想法下，向倾慕的对象白河月爱表白。但月爱意外地接受了表白，且当天就将龙斗带到自己的房间，准备进行性行为，在龙斗的劝说下，月爱决定等到打从心底喜欢龙斗时再做。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5476B9DDB81D095F50E978#第02集$id_XS5476B9DDB81D095F50E97B#第03集$id_XS5476B9DDB81D095F50E97A#第04集$id_XS5476B9DDB81D095F50E97D#第05集$id_XS5476B9DDB81D095F50E97C#第06集$id_XS5476B9DDB81D095F50E97F#第07集$id_XS5476B9DDB81D095F50E97E#第08集$id_XS5476B9DDB81D095F50E971#第09集$id_XS5476B9DDB81D095F50E970#第10集$id_XS5476B9DDB81D095F50E879#第11集$id_XS5476B9DDB81D095F50E878#第12集$id_XS5476B9DDB81D095F50E87B$$$第01集$id_MOE5476B9DDB81D095F50E978#第02集$id_MOE5476B9DDB81D095F50E97B#第03集$id_MOE5476B9DDB81D095F50E97A#第04集$id_MOE5476B9DDB81D095F50E97D#第05集$id_MOE5476B9DDB81D095F50E97C#第06集$id_MOE5476B9DDB81D095F50E97F#第07集$id_MOE5476B9DDB81D095F50E97E#第08集$id_MOE5476B9DDB81D095F50E971#第09集$id_MOE5476B9DDB81D095F50E970#第10集$id_MOE5476B9DDB81D095F50E879#第11集$id_MOE5476B9DDB81D095F50E878#第12集$id_MOE5476B9DDB81D095F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (91, 1, 0, 0, '彻夜之歌', 'よふかしのうた（2022）', 'cheyezhige', 1, 'C', '', 'c7b66331', '漫画改,奇幻,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2874016690.jpg', '', '', '', '雨宫天 / 佐藤元 / 花守由美里 / 户松遥 / 喜多村英梨 / 伊藤静 / 大空直美 / 和气杏未 / 小野贤章 / 吉野裕行 / 日笠阳子 / 泽城美雪', '板村智幸 / 武藤信宏 / 大西景介 / 关野圭一 / 高藤聪 / 白石道太 / 安井贵司', '', '', '“我第一次在夜里，没跟任何人说就出来了。”', '全13集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 65, 0, 65, 65, '', 0, 0, 9.8, 0, 0, 1740739007, 1726289202, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“我第一次在夜里，没跟任何人说就出来了。”</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5220EE8EBF1A5E0850E978#第02集$MOE5220EE8EBF1A5E0850E97B#第03集$MOE5220EE8EBF1A5E0850E97A#第04集$MOE5220EE8EBF1A5E0850E97D#第05集$MOE5220EE8EBF1A5E0850E97C#第06集$MOE5220EE8EBF1A5E0850E97F#第07集$MOE5220EE8EBF1A5E0850E97E#第08集$MOE5220EE8EBF1A5E0850E971#第09集$MOE5220EE8EBF1A5E0850E970#第10集$MOE5220EE8EBF1A5E0850E879#第11集$MOE5220EE8EBF1A5E0850E878#第12集$MOE5220EE8EBF1A5E0850E87B#第13集$MOE5220EE8EBF1A5E0850E87A$$$第01集$id_XS5220EE8EBF1A5E0850E978#第02集$id_XS5220EE8EBF1A5E0850E97B#第03集$id_XS5220EE8EBF1A5E0850E97A#第04集$id_XS5220EE8EBF1A5E0850E97D#第05集$id_XS5220EE8EBF1A5E0850E97C#第06集$id_XS5220EE8EBF1A5E0850E97F#第07集$id_XS5220EE8EBF1A5E0850E97E#第08集$id_XS5220EE8EBF1A5E0850E971#第09集$id_XS5220EE8EBF1A5E0850E970#第10集$id_XS5220EE8EBF1A5E0850E879#第11集$id_XS5220EE8EBF1A5E0850E878#第12集$id_XS5220EE8EBF1A5E0850E87B#第13集$id_XS5220EE8EBF1A5E0850E87A$$$第01集$id_MOE5220EE8EBF1A5E0850E978#第02集$id_MOE5220EE8EBF1A5E0850E97B#第03集$id_MOE5220EE8EBF1A5E0850E97A#第04集$id_MOE5220EE8EBF1A5E0850E97D#第05集$id_MOE5220EE8EBF1A5E0850E97C#第06集$id_MOE5220EE8EBF1A5E0850E97F#第07集$id_MOE5220EE8EBF1A5E0850E97E#第08集$id_MOE5220EE8EBF1A5E0850E971#第09集$id_MOE5220EE8EBF1A5E0850E970#第10集$id_MOE5220EE8EBF1A5E0850E879#第11集$id_MOE5220EE8EBF1A5E0850E878#第12集$id_MOE5220EE8EBF1A5E0850E87B#第13集$id_MOE5220EE8EBF1A5E0850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (437, 1, 0, 0, '圣女魔力无所不能 第二季', '', 'shengnvmoliwusuobunengdierji', 1, 'S', '', '416e4ed0', '小说改,奇幻,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/2f1881a2d2b79319b33e727b8906a07e176b7839.png', '', '', NULL, '小鸟游圣：石川由依\n阿尔伯特·霍克：樱井孝宏\n约翰·瓦尔德克：江口拓也\n尤里·德鲁斯：小林裕介\n裘德：八代拓\n御园爱良：市之濑加那\n伊丽莎白·艾希莉：上田丽奈\n埃尔哈特·霍克：梅原裕一郎\n奥斯卡·邓克尔：逢坂良太\n天宥：小林千晃\n青澜：三木真一郎', '井畑翔太', '', '', '二十余岁的公司职员圣某天突然作为「圣女」被召唤到了异世界。 她发挥自己原本对植物的爱好，在药用植物研究所展开了工作，但工作狂特有的一本正经加上“圣女之力”使得她不断做出药效提升五成的药水。 另外，她还', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 8.9, 0, 0, 1726289524, 1726289477, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '二十余岁的公司职员圣某天突然作为「圣女」被召唤到了异世界。 她发挥自己原本对植物的爱好，在药用植物研究所展开了工作，但工作狂特有的一本正经加上“圣女之力”使得她不断做出药效提升五成的药水。 另外，她还在讨伐魔物时发动了威力惊人的净化魔法，人望急剧上升！ 「圣女」身份得到了正式承认，她作为斯兰塔尼亚王国的救世主，得到了人们的尊敬。照看并支持她的是研究所的约翰和裘德、宫廷魔导师团的尤里，以及与她互相吸引却仍未成为恋人的“冰封骑士”阿尔伯特。圣成为王国最重要的人物后依旧一心投身于研究，但在与阿尔伯特加深关系的同时，恋爱方面也有了新的进展——？！', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0526BADDBD4C090950E978#第02集$id_XS0526BADDBD4C090950E97B#第03集$id_XS0526BADDBD4C090950E97A#第04集$id_XS0526BADDBD4C090950E97D#第05集$id_XS0526BADDBD4C090950E97C#第06集$id_XS0526BADDBD4C090950E97F#第07集$id_XS0526BADDBD4C090950E97E#第08集$id_XS0526BADDBD4C090950E971#第09集$id_XS0526BADDBD4C090950E970#第10集$id_XS0526BADDBD4C090950E879#第11集$id_XS0526BADDBD4C090950E878#第12集$id_XS0526BADDBD4C090950E87B$$$第01集$id_MOE0526BADDBD4C090950E978#第02集$id_MOE0526BADDBD4C090950E97B#第03集$id_MOE0526BADDBD4C090950E97A#第04集$id_MOE0526BADDBD4C090950E97D#第05集$id_MOE0526BADDBD4C090950E97C#第06集$id_MOE0526BADDBD4C090950E97F#第07集$id_MOE0526BADDBD4C090950E97E#第08集$id_MOE0526BADDBD4C090950E971#第09集$id_MOE0526BADDBD4C090950E970#第10集$id_MOE0526BADDBD4C090950E879#第11集$id_MOE0526BADDBD4C090950E878#第12集$id_MOE0526BADDBD4C090950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (93, 1, 0, 0, 'Paradox Live THE ANIMATION', 'Paradox Live THE ANIMATION', 'ParadoxLiveTHEANIMATION', 1, 'P', '', '74b196a3', '音乐', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2889692754.jpg', '', '', '', '月崎志麻,矢野奖吾,畠中祐,土岐隼一,近藤孝行,丰永利行,小林裕介,寺岛惇太,花江夏树,林勇,竹内良太,96猫,村濑步,梶原岳人', '', '', '', '　　不远的将来。一种新的运动“幻影LIVE ”在饱和的HIPHOP文化中诞生。说唱歌手们通过将自己的DNA与含有被称为“幻影金属”的金属的配饰发生化学反应，创造出与情感相关的幻象，华丽的舞台让年轻观众', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 6.1, 0, 0, 1726340276, 1726340211, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　不远的将来。一种新的运动“幻影LIVE ”在饱和的HIPHOP文化中诞生。说唱歌手们通过将自己的DNA与含有被称为“幻影金属”的金属的配饰发生化学反应，创造出与情感相关的幻象，华丽的舞台让年轻观众们兴奋不已。<br/>　　与此同时，&quot; BAE&quot;、&quot; The Cat’s Whiskers&quot;、&quot; cozmez &quot;和 &quot;恶汉奴等&quot;这四支队伍在各自音乐类型中人气最高的选手收到了神秘比赛&quot; Paradox Live &quot;的邀请，比赛将在传奇俱乐部 &quot;CLUB paradox &quot;举行。<br/>　　四支队伍心中怀着种种理由决定参战，但《Paradox Live》举办的背后，却隐藏着一个难以想象的巨大阴谋……<br/>　　光与暗的漩涡 幻影舞台战斗</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0623EE89B01F0C0A50E978#第02集$id_XS0623EE89B01F0C0A50E97B#第03集$id_XS0623EE89B01F0C0A50E97A#第04集$id_XS0623EE89B01F0C0A50E97D#第05集$id_XS0623EE89B01F0C0A50E97C#第06集$id_XS0623EE89B01F0C0A50E97F#第07集$id_XS0623EE89B01F0C0A50E97E#第08集$id_XS0623EE89B01F0C0A50E971#第09集$id_XS0623EE89B01F0C0A50E970#第10集$id_XS0623EE89B01F0C0A50E879#第11集$id_XS0623EE89B01F0C0A50E878#第12集$id_XS0623EE89B01F0C0A50E87B$$$第01集$id_MOE0623EE89B01F0C0A50E978#第02集$id_MOE0623EE89B01F0C0A50E97B#第03集$id_MOE0623EE89B01F0C0A50E97A#第04集$id_MOE0623EE89B01F0C0A50E97D#第05集$id_MOE0623EE89B01F0C0A50E97C#第06集$id_MOE0623EE89B01F0C0A50E97F#第07集$id_MOE0623EE89B01F0C0A50E97E#第08集$id_MOE0623EE89B01F0C0A50E971#第09集$id_MOE0623EE89B01F0C0A50E970#第10集$id_MOE0623EE89B01F0C0A50E879#第11集$id_MOE0623EE89B01F0C0A50E878#第12集$id_MOE0623EE89B01F0C0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (663, 1, 0, 0, '赛马娘 第三季', 'ウマ娘 プリティーダービー Season 3（2023）', 'saimaniangdisanji', 1, 'S', '', '6b15f97c', '原创,运动,热血,偶像', 'https://i0.hdslb.com/bfs/bangumi/image/a6d2fbcca2f1956bbe718670d1e7cefb785bf4c3.png', '', '', '', '矢野妃菜喜 / 立花日菜 / 和气杏未 / 高野麻里佳 / 齐藤真知子 / 大西沙织 / 大桥彩香 / 木村千咲 / 上田瞳 / 冲野晃司', '及川启', '', '', '永不放弃，直至触及梦想——\r\n这是继承了别的世界的闪耀名字和灵魂的“赛马娘”的故事。\r\n北部玄驹在年幼时目睹了东海帝王创造的奇迹，梦想着自己也进入那绚丽夺目的风景中。\r\n里见光钻在一旁支持着发小的梦想，同时', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 6.8, 0, 0, 1734848347, 1726341181, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>永不放弃，直至触及梦想——\n这是继承了别的世界的闪耀名字和灵魂的“赛马娘”的故事。\n北部玄驹在年幼时目睹了东海帝王创造的奇迹，梦想着自己也进入那绚丽夺目的风景中。\n里见光钻在一旁支持着发小的梦想，同时也在努力履行自己的使命。\n面对强大的对手和难以反抗的命运，此时此刻，北部玄驹在信赖的同伴的话语和人们的声援之中，朝着梦想飞奔而去！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775BD8DEF105A5A50E978#第02集$MOE0775BD8DEF105A5A50E97B#第03集$MOE0775BD8DEF105A5A50E97A#第04集$MOE0775BD8DEF105A5A50E97D#第05集$MOE0775BD8DEF105A5A50E97C#第06集$MOE0775BD8DEF105A5A50E97F#第07集$MOE0775BD8DEF105A5A50E97E#第08集$MOE0775BD8DEF105A5A50E971#第09集$MOE0775BD8DEF105A5A50E970#第10集$MOE0775BD8DEF105A5A50E879#第11集$MOE0775BD8DEF105A5A50E878#第12集$MOE0775BD8DEF105A5A50E87B#第13集$MOE0775BD8DEF105A5A50E87A$$$第01集$id_XS0775BD8DEF105A5A50E978#第02集$id_XS0775BD8DEF105A5A50E97B#第03集$id_XS0775BD8DEF105A5A50E97A#第04集$id_XS0775BD8DEF105A5A50E97D#第05集$id_XS0775BD8DEF105A5A50E97C#第06集$id_XS0775BD8DEF105A5A50E97F#第07集$id_XS0775BD8DEF105A5A50E97E#第08集$id_XS0775BD8DEF105A5A50E971#第09集$id_XS0775BD8DEF105A5A50E970#第10集$id_XS0775BD8DEF105A5A50E879#第11集$id_XS0775BD8DEF105A5A50E878#第12集$id_XS0775BD8DEF105A5A50E87B#第13集$id_XS0775BD8DEF105A5A50E87A$$$第01集$id_MOE0775BD8DEF105A5A50E978#第02集$id_MOE0775BD8DEF105A5A50E97B#第03集$id_MOE0775BD8DEF105A5A50E97A#第04集$id_MOE0775BD8DEF105A5A50E97D#第05集$id_MOE0775BD8DEF105A5A50E97C#第06集$id_MOE0775BD8DEF105A5A50E97F#第07集$id_MOE0775BD8DEF105A5A50E97E#第08集$id_MOE0775BD8DEF105A5A50E971#第09集$id_MOE