INSERT INTO `mac_vod` VALUES (99, 1, 0, 0, '进击！巨人中学', '進撃！巨人中学校（2015）', 'jinjijurenzhongxue', 1, 'J', '', '3dcd1321', '漫画改,搞笑', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2265997114.jpg', '', '', '', '梶裕贵 / 石川由依 / 井上麻里奈 / 谷山纪章 / 岛村侑 / 小林优 / 三上枝织 / 下野纮 / 逢坂良太 / 细谷佳正 / 橋詰知久 / 藤田咲 / 神谷浩史 / 小野大辅 / 朴璐美 / 千叶进步 / 川田绅司 / 三戸耕三 / 相川奈都姫 / 鶏冠井美智子 / 三宅健太', '井端義秀', '', '', '故事发生在巨人与人类共同相处的一所学校中，艾伦和他的伙伴们将与巨人之间爆发出怎样的故事呢？', '全12集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 9.3, 0, 0, 1733397774, 1726342340, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在巨人与人类共同相处的一所学校中，艾伦和他的伙伴们将与巨人之间爆发出怎样的故事呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0273EFDCB81A5F0850E978#第02集$MOE0273EFDCB81A5F0850E97B#第03集$MOE0273EFDCB81A5F0850E97A#第04集$MOE0273EFDCB81A5F0850E97D#第05集$MOE0273EFDCB81A5F0850E97C#第06集$MOE0273EFDCB81A5F0850E97F#第07集$MOE0273EFDCB81A5F0850E97E#第08集$MOE0273EFDCB81A5F0850E971#第09集$MOE0273EFDCB81A5F0850E970#第10集$MOE0273EFDCB81A5F0850E879#第11集$MOE0273EFDCB81A5F0850E878#第12集$MOE0273EFDCB81A5F0850E87B$$$第01集$id_XS0273EFDCB81A5F0850E978#第02集$id_XS0273EFDCB81A5F0850E97B#第03集$id_XS0273EFDCB81A5F0850E97A#第04集$id_XS0273EFDCB81A5F0850E97D#第05集$id_XS0273EFDCB81A5F0850E97C#第06集$id_XS0273EFDCB81A5F0850E97F#第07集$id_XS0273EFDCB81A5F0850E97E#第08集$id_XS0273EFDCB81A5F0850E971#第09集$id_XS0273EFDCB81A5F0850E970#第10集$id_XS0273EFDCB81A5F0850E879#第11集$id_XS0273EFDCB81A5F0850E878#第12集$id_XS0273EFDCB81A5F0850E87B$$$第01集$id_MOE0273EFDCB81A5F0850E978#第02集$id_MOE0273EFDCB81A5F0850E97B#第03集$id_MOE0273EFDCB81A5F0850E97A#第04集$id_MOE0273EFDCB81A5F0850E97D#第05集$id_MOE0273EFDCB81A5F0850E97C#第06集$id_MOE0273EFDCB81A5F0850E97F#第07集$id_MOE0273EFDCB81A5F0850E97E#第08集$id_MOE0273EFDCB81A5F0850E971#第09集$id_MOE0273EFDCB81A5F0850E970#第10集$id_MOE0273EFDCB81A5F0850E879#第11集$id_MOE0273EFDCB81A5F0850E878#第12集$id_MOE0273EFDCB81A5F0850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (100, 1, 0, 0, '猪肝倒是热热再吃啊', '豚のレバーは加熱しろ', 'zhugandaoshirerezaichia', 1, 'Z', '', '8a276873', '异世界,奇幻,冒险,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2897909071.jpg', '', '', '', '楠木灯,松冈祯丞', '高桥雅之', '', '', '　　我是个生吃猪肝后失去意识的不起眼阿宅。本来想说自己转生到异世界，却只是变成一只猪！我全身是泥巴躺在猪圈，拯救我的是像天使一样温柔的美少女婕丝。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 5.0, 0, 0, 1726342643, 1726342547, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　我是个生吃猪肝后失去意识的不起眼阿宅。本来想说自己转生到异世界，却只是变成一只猪！我全身是泥巴躺在猪圈，拯救我的是像天使一样温柔的美少女婕丝。<br/>　　「哼齁！」「那个，你不用勉强说话也没关系。因为我……明白你想说什么。」她舍身照顾变成猪的我，据说她是能读懂人心的「耶稣玛」这个种族。「糟了，这样我有如猪一般的欲望不就表露无遗了吗！！」在梅斯特利亚这个剑与魔法的世界，普通的猪与能读心的美少女，打情骂俏的奇幻故事即将开始！……吗？</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0976BE8FBF115A0A50E978#第02集$id_XS0976BE8FBF115A0A50E97B#第03集$id_XS0976BE8FBF115A0A50E97A#第04集$id_XS0976BE8FBF115A0A50E97D#第05集$id_XS0976BE8FBF115A0A50E97C#第06集$id_XS0976BE8FBF115A0A50E97F#第07集$id_XS0976BE8FBF115A0A50E97E#第08集$id_XS0976BE8FBF115A0A50E971#第09集$id_XS0976BE8FBF115A0A50E970#第10集$id_XS0976BE8FBF115A0A50E879#第11集$id_XS0976BE8FBF115A0A50E878#第12集$id_XS0976BE8FBF115A0A50E87B$$$第01集$id_MOE0976BE8FBF115A0A50E978#第02集$id_MOE0976BE8FBF115A0A50E97B#第03集$id_MOE0976BE8FBF115A0A50E97A#第04集$id_MOE0976BE8FBF115A0A50E97D#第05集$id_MOE0976BE8FBF115A0A50E97C#第06集$id_MOE0976BE8FBF115A0A50E97F#第07集$id_MOE0976BE8FBF115A0A50E97E#第08集$id_MOE0976BE8FBF115A0A50E971#第09集$id_MOE0976BE8FBF115A0A50E970#第10集$id_MOE0976BE8FBF115A0A50E879#第11集$id_MOE0976BE8FBF115A0A50E878#第12集$id_MOE0976BE8FBF115A0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (101, 1, 0, 0, '我推是反派大小姐', '私の推しは悪役令嬢。 Season 1', 'wotuishifanpaidaxiaojie', 1, 'W', '', '81170b81', '异世界,魔法,校园,恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2885107437.jpg', '', '', '', '奈波果林,芹泽优', '大庭秀昭', '', '', '　　虽然我是乙女向游戏的女主角，但我不能喜欢反派大小姐吗？\r\n                                    \r\n                                　', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 7.5, 0, 0, 1726342797, 1726342737, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　虽然我是乙女向游戏的女主角，但我不能喜欢反派大小姐吗？<br/>　　转生成为乙女向游戏「Revolution」的女主角——零·缇拉的社畜OL大桥零。<br/>　　她想推的角色，不是攻略对象的王子们，而是反派大小姐——克莱尔·弗郎索瓦。<br/>　　零不仅没有对克莱尔的坏心眼产生反感，反而还高兴地接受了。<br/>　　这是容易连累周围人体质的主人公别具一格的恋爱喜剧的开端。<br/>　　将自己别扭的爱转向零的反派大小姐克莱尔，她的未来究竟是哪边？<br/>　　由いのり。执笔撰写，花ヶ田绘制插画一部轻小说，近日宣布动画化！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0926BD8FB94B550850E978#第02集$id_XS0926BD8FB94B550850E97B#第03集$id_XS0926BD8FB94B550850E97A#第04集$id_XS0926BD8FB94B550850E97D#第05集$id_XS0926BD8FB94B550850E97C#第06集$id_XS0926BD8FB94B550850E97F#第07集$id_XS0926BD8FB94B550850E97E#第08集$id_XS0926BD8FB94B550850E971#第09集$id_XS0926BD8FB94B550850E970#第10集$id_XS0926BD8FB94B550850E879#第11集$id_XS0926BD8FB94B550850E878#第12集$id_XS0926BD8FB94B550850E87B$$$第01集$id_MOE0926BD8FB94B550850E978#第02集$id_MOE0926BD8FB94B550850E97B#第03集$id_MOE0926BD8FB94B550850E97A#第04集$id_MOE0926BD8FB94B550850E97D#第05集$id_MOE0926BD8FB94B550850E97C#第06集$id_MOE0926BD8FB94B550850E97F#第07集$id_MOE0926BD8FB94B550850E97E#第08集$id_MOE0926BD8FB94B550850E971#第09集$id_MOE0926BD8FB94B550850E970#第10集$id_MOE0926BD8FB94B550850E879#第11集$id_MOE0926BD8FB94B550850E878#第12集$id_MOE0926BD8FB94B550850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (102, 1, 0, 0, '神选', 'カミエラビ', 'shenxuan', 1, 'S', '', '560f4408', '原创,奇幻,战斗,校园', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2897808643.jpg', '', '', '', '新祐树,菲鲁兹·蓝,楠木灯,梶原岳人,阿部菜摘子,内田修一,松本沙罗,佐仓绫音,浦和希', '濑下宽之', '', '', '　　就读于东京都内私立高中的高一学生护郎，既没有「希望」、「梦想」，也没有「野心」，世界对他来说是「冷漠」的东西，一边对同班同学穗香抱有淡淡的憧憬，一边和好友秋津过着毫无变化的无聊的日常生活。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 0, 25, 25, '', 0, 0, 5.9, 0, 0, 1726342941, 1726342851, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　就读于东京都内私立高中的高一学生护郎，既没有「希望」、「梦想」，也没有「野心」，世界对他来说是「冷漠」的东西，一边对同班同学穗香抱有淡淡的憧憬，一边和好友秋津过着毫无变化的无聊的日常生活。<br/>　　有一天，护郎的智能手机收到了奇怪的通知。<br/>　　你被选中了。请注入你的愿望。<br/>　　护郎被选为“伟大的意志”，为了实现愿望，他将登上“神明”的宝座，与其他神明候选人们互相残杀，直到成为最后一人。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0421BCDEBD1D5D0150E978#第02集$id_XS0421BCDEBD1D5D0150E97B#第03集$id_XS0421BCDEBD1D5D0150E97A#第04集$id_XS0421BCDEBD1D5D0150E97D#第05集$id_XS0421BCDEBD1D5D0150E97C#第06集$id_XS0421BCDEBD1D5D0150E97F#第07集$id_XS0421BCDEBD1D5D0150E97E#第08集$id_XS0421BCDEBD1D5D0150E971#第09集$id_XS0421BCDEBD1D5D0150E970#第10集$id_XS0421BCDEBD1D5D0150E879#第11集$id_XS0421BCDEBD1D5D0150E878#第12集$id_XS0421BCDEBD1D5D0150E87B$$$第01集$id_MOE0421BCDEBD1D5D0150E978#第02集$id_MOE0421BCDEBD1D5D0150E97B#第03集$id_MOE0421BCDEBD1D5D0150E97A#第04集$id_MOE0421BCDEBD1D5D0150E97D#第05集$id_MOE0421BCDEBD1D5D0150E97C#第06集$id_MOE0421BCDEBD1D5D0150E97F#第07集$id_MOE0421BCDEBD1D5D0150E97E#第08集$id_MOE0421BCDEBD1D5D0150E971#第09集$id_MOE0421BCDEBD1D5D0150E970#第10集$id_MOE0421BCDEBD1D5D0150E879#第11集$id_MOE0421BCDEBD1D5D0150E878#第12集$id_MOE0421BCDEBD1D5D0150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (103, 1, 0, 0, 'AYAKA ‐绫岛奇谭‐', 'AYAKA ‐あやか‐', 'AYAKAlingdaoqitan', 1, 'A', '', 'd7fccf05', '奇幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2893010482.jpg', '', '', '', '梅原裕一郎,鸟海浩辅,寺岛拓笃,上村祐翔', '长山延好', '', '', '　　八凰幸人是一名在儿童福利院长大的少年。某天，名为沙川尽义的神情傲然的青年来到了幸人的身边，他自称是幸人已故父亲的弟子，把幸人带去了故乡绫之岛。由七岛相连的绫之岛，盛行着火与水之龙的传说，还有名为“', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 5.3, 0, 0, 1726343153, 1726343109, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　八凰幸人是一名在儿童福利院长大的少年。某天，名为沙川尽义的神情傲然的青年来到了幸人的身边，他自称是幸人已故父亲的弟子，把幸人带去了故乡绫之岛。由七岛相连的绫之岛，盛行着火与水之龙的传说，还有名为“御灵”的神奇事物存在着的奇妙的岛屿。幸人与曾经是守护绫之岛仙人的父亲的三名弟子开始了来往，一同居住在绫之岛上。然而另外两名师兄弟鞍马春秋与伊吹朱之间却有着深深的隔阂。在平衡即将开始崩坏的“ayakai”岛上，幸人直面的真相是一—</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5520EADBEA4F5D0C50E978#第02集$id_XS5520EADBEA4F5D0C50E97B#第03集$id_XS5520EADBEA4F5D0C50E97A#第04集$id_XS5520EADBEA4F5D0C50E97D#第05集$id_XS5520EADBEA4F5D0C50E97C#第06集$id_XS5520EADBEA4F5D0C50E97F#第07集$id_XS5520EADBEA4F5D0C50E97E#第08集$id_XS5520EADBEA4F5D0C50E971#第09集$id_XS5520EADBEA4F5D0C50E970#第10集$id_XS5520EADBEA4F5D0C50E879#第11集$id_XS5520EADBEA4F5D0C50E878#第12集$id_XS5520EADBEA4F5D0C50E87B$$$第01集$id_MOE5520EADBEA4F5D0C50E978#第02集$id_MOE5520EADBEA4F5D0C50E97B#第03集$id_MOE5520EADBEA4F5D0C50E97A#第04集$id_MOE5520EADBEA4F5D0C50E97D#第05集$id_MOE5520EADBEA4F5D0C50E97C#第06集$id_MOE5520EADBEA4F5D0C50E97F#第07集$id_MOE5520EADBEA4F5D0C50E97E#第08集$id_MOE5520EADBEA4F5D0C50E971#第09集$id_MOE5520EADBEA4F5D0C50E970#第10集$id_MOE5520EADBEA4F5D0C50E879#第11集$id_MOE5520EADBEA4F5D0C50E878#第12集$id_MOE5520EADBEA4F5D0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (104, 2, 0, 0, '特别篇 吹响吧！上低音号～合奏比赛～', '', 'tebiepianchuixiangbashangdiyinhaohezoubisai', 1, 'T', '', '4b1f4a92', '小说改,校园', 'https://i0.hdslb.com/bfs/bangumi/image/3f2d233a17787237a66c502fad28023929ae5c27.png', '', '', '', '黄前久美子：黑泽朋世\n加藤叶月：朝井彩加\n川岛绿辉：丰田萌绘\n高坂丽奈：安济知佳\n冢本秀一：石谷春贵\n釜屋燕：大桥彩香\n中川夏纪：藤村鼓乃美\n吉川优子：山冈百合\n铠冢霙：种崎敦美\n伞木希美：东山奈央\n久石奏：雨宫天\n铃木美玲：七濑彩夏\n铃木五月：久野美咲\n剑崎梨梨花：杉浦栞\n泷升：樱井孝宏', '石原立也', '', '', '实力强劲的吹奏乐社上任的新社长，遇到的第一件大事就是对社内进行“调整”！？\r\n吹奏乐社的总成员数为65人。\r\n而主人公久美子身为社长的每一天，就是从为社员提供咨询及解决争端开始的。\r\n她是否能够顺利地完成她', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 9.8, 0, 0, 1726432895, 1726432712, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '实力强劲的吹奏乐社上任的新社长，遇到的第一件大事就是对社内进行“调整”！？\n吹奏乐社的总成员数为65人。\n而主人公久美子身为社长的每一天，就是从为社员提供咨询及解决争端开始的。\n她是否能够顺利地完成她的第一件工作呢？\n调音，完成！\n\n≪故事≫\n新社长久美子面临的，是决定合奏比赛代表队伍的校内预选。\n虽然久美子努力地想要让社团顺利迎来预选，但吹奏乐社这么多人，问题总是接连不断。\n她总是会被人找上门来商量各种事情，作为社长过着忙碌的每一天。\n社员们一个个都找好了队伍，但久美子自己却迟迟未能定下自己的队伍——', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0575BDDEBD48540B50E978$$$正片$id_MOE0575BDDEBD48540B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (105, 2, 0, 0, '蜡笔小新：新次元！超能力大决战', '', 'labixiaoxinxinciyuanchaonenglidajuezhan', 1, 'L', '', 'ce207f22', '动画,喜剧', 'https://i0.hdslb.com/bfs/bangumi/image/2ee7fb081b74b657eabe3bf5aee54d7bbd9ffd57.png', '', '', '', '小林由美子\n楢桥美纪\n森川智之\n兴梠里美\n真柴摩利\n林玉绪\n一龙斋贞友\n鬼头明里\n松坂桃李\n三石琴乃\n森田顺平\n七绪春日', '', '', '', '故事讲述住在诺斯特拉达姆斯邻镇的努斯特拉达马斯留下了一个预言：“在 20 和 23 并列的年份，天上会降下两道光芒。一道是黑暗之光，另一道是小小的白光……不久，黑暗之光就会拥有强大的力量，扰乱和平，给', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 196, 0, 196, 196, '', 0, 0, 8.5, 0, 0, 1726433192, 1726432963, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '故事讲述住在诺斯特拉达姆斯邻镇的努斯特拉达马斯留下了一个预言：“在 20 和 23 并列的年份，天上会降下两道光芒。一道是黑暗之光，另一道是小小的白光……不久，黑暗之光就会拥有强大的力量，扰乱和平，给世界带来巨大的混乱。”\n然后 2023 年夏天，两道光从宇宙接近。等待晚饭的新之助被白色的光击中了，身体充满不可思议的力量。“屁股……屁股热乎乎的……”一用力，玩具就会漂浮在空中！这是才能利新之助诞生的瞬间。\n另一方面，沐浴着黑光、成为黑暗护手的男人的名字是非理谷充。打工不顺利，推的偶像结婚，甚至被误认为是暴行犯而被警察追赶的他，因为得到了力量而发誓要对这个世界复仇。\n希望世界毁灭的非理谷 VS 新之助。超能力大决战即将拉开帷幕！今年夏天，面对面对绝望的新之助放出的光芒，胸口和屁股都变得热乎乎的……', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5272BE88BE4F5F0B50E978$$$正片$id_MOE5272BE88BE4F5F0B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (106, 1, 0, 0, '五等分的新娘∽特別篇', '', 'wudengfendexinniangtebiepianjinxiangangaotaidiqu', 1, 'W', '', 'd606050c', '恋爱,少女,校园', 'https://i0.hdslb.com/bfs/bangumi/image/3474794289a9eb515f8a22aa98a689459c2d35bc.png', '', '', '', '', '', '', '', '風太郎和五姊妹的高中生活只剩半年，迎來最後的暑假，要準備考試的風太郎沒辦法在暑假期間當她們的家教，正當五姊妹為此覺得沮喪時，風太郎突然打電話過來……', '全2集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 88, 0, 88, 88, '', 0, 0, 0.0, 0, 0, 1726433640, 1726433420, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>風太郎和五姊妹的高中生活只剩半年，迎來最後的暑假，要準備考試的風太郎沒辦法在暑假期間當她們的家教，正當五姊妹為此覺得沮喪時，風太郎突然打電話過來……</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5521BC8EB91C5D5A50E978#第02集$id_XS5521BC8EB91C5D5A50E97B$$$第01集$id_MOE5521BC8EB91C5D5A50E978#第02集$id_MOE5521BC8EB91C5D5A50E97B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (107, 2, 0, 0, '爱丽丝和特蕾丝的梦幻工厂', 'アリスとテレスのまぼろし工場', 'ailisiheteleisidemenghuangongchang', 1, 'A', '', '8e326974', '剧场版', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2895861483.jpg', '', '', '', '濑户康史,林遣都,久野美咲,上田丽奈,榎木淳弥', '冈田麿里', '', '', '　　因为一起突发的钢铁厂爆炸事故，失去了所有出口的城镇陷入停滞，居住在那里的初三学生正宗过着沮丧的日子。为了有朝一日能恢复原样，居民们被禁止改变，过着沉闷的生活。在这期间，正宗被神秘的同班同学睦实引导', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 6.3, 0, 0, 1726433847, 1726433773, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　因为一起突发的钢铁厂爆炸事故，失去了所有出口的城镇陷入停滞，居住在那里的初三学生正宗过着沮丧的日子。为了有朝一日能恢复原样，居民们被禁止改变，过着沉闷的生活。在这期间，正宗被神秘的同班同学睦实引导，踏入了钢铁厂的第五高炉。在那里，他们遇到了一位无法说话、像野狼一样的少女。两位少女与正宗的相遇打破了世界的平衡，不满于平凡生活的少年少女们的无法抑制的&quot;恋爱冲动&quot;开始摧毁世界——。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0972BF8ABF105A0D50E978$$$正片$id_MOE0972BF8ABF105A0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (108, 1, 0, 0, '浪客剑心 -明治剑客浪漫谭-（新作）', '', 'langkejianxinmingzhijiankelangmantanxinzuo', 1, 'L', '', 'b3438bdf', '漫画改,战斗,恋爱,热血', 'https://i0.hdslb.com/bfs/bangumi/image/397b5e3f74d43a4fb226d12d0e0f228e3da7bc1c.png', '', '', '', '绯村剑心：齐藤壮马神谷薰：高桥李依明神弥彦：小市真琴相乐左之助：八代拓高荷惠：大西沙织四乃森苍紫：内田雄马', '山本秀世', '', '', '《浪客剑心 -明治剑客浪漫谭-》于1994年在《周刊少年JUMP》上开始连载，迄今已被动画化了5次。本作是从原作第一章开始重新构筑的新作电视动画。\r\n在幕末的动乱时期，曾有一个被人畏惧地称之为“刽子手拔', '全24集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 30, 0, 30, 30, '', 0, 0, 9.5, 0, 0, 1726518235, 1726433990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《浪客剑心&nbsp;-明治剑客浪漫谭-》于1994年在《周刊少年JUMP》上开始连载，迄今已被动画化了5次。本作是从原作第一章开始重新构筑的新作电视动画。\n在幕末的动乱时期，曾有一个被人畏惧地称之为“刽子手拔刀斋”的维新志士。\n而那个男人在新时代到来之际消失在众人面前，只留下了最强剑客的传说。\n时光流逝——时值明治11年，地点在东京下町。\n腰上佩着逆刃刀，发誓不杀的流浪剑客绯村剑心，与神谷活心流代理师父神谷薰相遇了。\n剑心帮助解决了冒充活心流当街杀人的“刽子手拔刀斋”一案后，以此为契机暂住在薰的家中。\n他遇到了东京府士族出身的明神弥彦，自称打架专家的相乐左之助，与他们成为了伙伴，还因为过去的恩怨，与自己的宿敌们对战。\n努力活在新时代的人交织而成的明治剑客浪漫谭，就此开幕——</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5324B88BB14B095F50E978#第02集$id_XS5324B88BB14B095F50E97B#第03集$id_XS5324B88BB14B095F50E97A#第04集$id_XS5324B88BB14B095F50E97D#第05集$id_XS5324B88BB14B095F50E97C#第06集$id_XS5324B88BB14B095F50E97F#第07集$id_XS5324B88BB14B095F50E97E#第08集$id_XS5324B88BB14B095F50E971#第09集$id_XS5324B88BB14B095F50E970#第10集$id_XS5324B88BB14B095F50E879#第11集$id_XS5324B88BB14B095F50E878#第12集$id_XS5324B88BB14B095F50E87B#第13集$id_XS5324B88BB14B095F50E87A#第14集$id_XS5324B88BB14B095F50E87D#第15集$id_XS5324B88BB14B095F50E87C#第16集$id_XS5324B88BB14B095F50E87F#第17集$id_XS5324B88BB14B095F50E87E#第18集$id_XS5324B88BB14B095F50E871#第19集$id_XS5324B88BB14B095F50E870#第20集$id_XS5324B88BB14B095F50EB79#第21集$id_XS5324B88BB14B095F50EB78#第22集$id_XS5324B88BB14B095F50EB7B#第23集$id_XS5324B88BB14B095F50EB7A#第24集$id_XS5324B88BB14B095F50EB7D$$$第01集$id_MOE5324B88BB14B095F50E978#第02集$id_MOE5324B88BB14B095F50E97B#第03集$id_MOE5324B88BB14B095F50E97A#第04集$id_MOE5324B88BB14B095F50E97D#第05集$id_MOE5324B88BB14B095F50E97C#第06集$id_MOE5324B88BB14B095F50E97F#第07集$id_MOE5324B88BB14B095F50E97E#第08集$id_MOE5324B88BB14B095F50E971#第09集$id_MOE5324B88BB14B095F50E970#第10集$id_MOE5324B88BB14B095F50E879#第11集$id_MOE5324B88BB14B095F50E878#第12集$id_MOE5324B88BB14B095F50E87B#第13集$id_MOE5324B88BB14B095F50E87A#第14集$id_MOE5324B88BB14B095F50E87D#第15集$id_MOE5324B88BB14B095F50E87C#第16集$id_MOE5324B88BB14B095F50E87F#第17集$id_MOE5324B88BB14B095F50E87E#第18集$id_MOE5324B88BB14B095F50E871#第19集$id_MOE5324B88BB14B095F50E870#第20集$id_MOE5324B88BB14B095F50EB79#第21集$id_MOE5324B88BB14B095F50EB78#第22集$id_MOE5324B88BB14B095F50EB7B#第23集$id_MOE5324B88BB14B095F50EB7A#第24集$id_MOE5324B88BB14B095F50EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (109, 1, 0, 0, '黑暗集会', 'ダークギャザリング', 'heianjihui', 1, 'H', '', '88c7abd2', '战斗,冒险', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2876814001.jpg', '', '', '', '早见沙织,松本和香子,平野文,川口莉奈,中村义洋,花泽香菜,岛崎信长,筱原侑', '博史池畠', '', '', '　　灵感少女夜宵因交通事故失去了双亲，母亲的灵魂还在事故时被恶灵夺走，为了找回夜宵母亲的灵魂，拥有通灵体质的萤多朗和夜宵一起前往恶灵弥漫的灵异地点。', '全25集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 7.5, 0, 0, 1726434385, 1726434298, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　灵感少女夜宵因交通事故失去了双亲，母亲的灵魂还在事故时被恶灵夺走，为了找回夜宵母亲的灵魂，拥有通灵体质的萤多朗和夜宵一起前往恶灵弥漫的灵异地点。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS092FEF8FE84B090B50E978#第02集$id_XS092FEF8FE84B090B50E97B#第03集$id_XS092FEF8FE84B090B50E97A#第04集$id_XS092FEF8FE84B090B50E97D#第05集$id_XS092FEF8FE84B090B50E97C#第06集$id_XS092FEF8FE84B090B50E97F#第07集$id_XS092FEF8FE84B090B50E97E#第08集$id_XS092FEF8FE84B090B50E971#第09集$id_XS092FEF8FE84B090B50E970#第10集$id_XS092FEF8FE84B090B50E879#第11集$id_XS092FEF8FE84B090B50E878#第12集$id_XS092FEF8FE84B090B50E87B#第13集$id_XS092FEF8FE84B090B50E87A#第14集$id_XS092FEF8FE84B090B50E87D#第15集$id_XS092FEF8FE84B090B50E87C#第16集$id_XS092FEF8FE84B090B50E87F#第17集$id_XS092FEF8FE84B090B50E87E#第18集$id_XS092FEF8FE84B090B50E871#第19集$id_XS092FEF8FE84B090B50E870#第20集$id_XS092FEF8FE84B090B50EB79#第21集$id_XS092FEF8FE84B090B50EB78#第22集$id_XS092FEF8FE84B090B50EB7B#第23集$id_XS092FEF8FE84B090B50EB7A#第24集$id_XS092FEF8FE84B090B50EB7D#第25集$id_XS092FEF8FE84B090B50EB7C$$$第01集$id_MOE092FEF8FE84B090B50E978#第02集$id_MOE092FEF8FE84B090B50E97B#第03集$id_MOE092FEF8FE84B090B50E97A#第04集$id_MOE092FEF8FE84B090B50E97D#第05集$id_MOE092FEF8FE84B090B50E97C#第06集$id_MOE092FEF8FE84B090B50E97F#第07集$id_MOE092FEF8FE84B090B50E97E#第08集$id_MOE092FEF8FE84B090B50E971#第09集$id_MOE092FEF8FE84B090B50E970#第10集$id_MOE092FEF8FE84B090B50E879#第11集$id_MOE092FEF8FE84B090B50E878#第12集$id_MOE092FEF8FE84B090B50E87B#第13集$id_MOE092FEF8FE84B090B50E87A#第14集$id_MOE092FEF8FE84B090B50E87D#第15集$id_MOE092FEF8FE84B090B50E87C#第16集$id_MOE092FEF8FE84B090B50E87F#第17集$id_MOE092FEF8FE84B090B50E87E#第18集$id_MOE092FEF8FE84B090B50E871#第19集$id_MOE092FEF8FE84B090B50E870#第20集$id_MOE092FEF8FE84B090B50EB79#第21集$id_MOE092FEF8FE84B090B50EB78#第22集$id_MOE092FEF8FE84B090B50EB7B#第23集$id_MOE092FEF8FE84B090B50EB7A#第24集$id_MOE092FEF8FE84B090B50EB7D#第25集$id_MOE092FEF8FE84B090B50EB7C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (110, 1, 0, 0, '大小姐和看门犬', 'お嬢と番犬くん', 'daxiaojiehekanmenquan', 1, 'D', '', 'c14286d7', '恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2898087145.jpg', '', '', '', '今井文也,井上雄贵,寺杣昌纪,上田瞳,青山吉能,中原麻衣,榎木淳弥,梅原裕一郎,鬼头明里', '高本宣弘', '', '', '　　濑名垣一咲，今年春天开始上高中一年级——因为家里是黑道，周围的人都很害怕她，但是今后想普通地交友，普通地恋爱！', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 4.3, 0, 0, 1726434563, 1726434496, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　濑名垣一咲，今年春天开始上高中一年级——因为家里是黑道，周围的人都很害怕她，但是今后想普通地交友，普通地恋爱！<br/>　　一咲决定选择离家较远的高中就读，不料过度保护的少当家宇藤启弥虚报年龄走后门也进入了一咲的高中！？<br/>　　启弥说着“恋爱对一咲来说太早了”，坚决不让男人靠近她。但其实一咲从很久以前开始就单相思着启弥……！？</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5226B88AB11F090E50E978#第02集$id_XS5226B88AB11F090E50E97B#第03集$id_XS5226B88AB11F090E50E97A#第04集$id_XS5226B88AB11F090E50E97D#第05集$id_XS5226B88AB11F090E50E97C#第06集$id_XS5226B88AB11F090E50E97F#第07集$id_XS5226B88AB11F090E50E97E#第08集$id_XS5226B88AB11F090E50E971#第09集$id_XS5226B88AB11F090E50E970#第10集$id_XS5226B88AB11F090E50E879#第11集$id_XS5226B88AB11F090E50E878#第12集$id_XS5226B88AB11F090E50E87B#第13集$id_XS5226B88AB11F090E50E87A$$$第01集$id_MOE5226B88AB11F090E50E978#第02集$id_MOE5226B88AB11F090E50E97B#第03集$id_MOE5226B88AB11F090E50E97A#第04集$id_MOE5226B88AB11F090E50E97D#第05集$id_MOE5226B88AB11F090E50E97C#第06集$id_MOE5226B88AB11F090E50E97F#第07集$id_MOE5226B88AB11F090E50E97E#第08集$id_MOE5226B88AB11F090E50E971#第09集$id_MOE5226B88AB11F090E50E970#第10集$id_MOE5226B88AB11F090E50E879#第11集$id_MOE5226B88AB11F090E50E878#第12集$id_MOE5226B88AB11F090E50E87B#第13集$id_MOE5226B88AB11F090E50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (440, 1, 0, 0, '租借女友 第三季', '彼女、お借りします 3期', 'zujienvyoudisanji', 1, 'Z', '', '1095ba47', '漫画改,恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2888859104.jpg', '', '', '', '芹泽优,堀江瞬,高桥李依,东山奈央,悠木碧,雨宫天', '古贺一臣,宇根信也', '', '', '　　千鹤的祖母小百合的身体状况恶化了，想把自己出演的电影给祖母看的千鹤陷入了两难事态。“一起拍电影吧!!”和也决心用众筹的方式来制作千鹤主演的电影，于是便开始了电影的制作。搬到和也隔壁的八重森弥妮也被', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 336, 1, 336, 336, '', 0, 0, 7.2, 0, 0, 1726434972, 1726434632, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　千鹤的祖母小百合的身体状况恶化了，想把自己出演的电影给祖母看的千鹤陷入了两难事态。“一起拍电影吧!!”和也决心用众筹的方式来制作千鹤主演的电影，于是便开始了电影的制作。搬到和也隔壁的八重森弥妮也被卷入到他的生活当中,和也从一次“女友租借”开始的生活，变得更加闪耀!<br/>　　和也与千鹤的电影制作，到底会迎来怎样的结局呢一一!?</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0027B58DEB48590E50E978#第02集$id_XS0027B58DEB48590E50E97B#第03集$id_XS0027B58DEB48590E50E97A#第04集$id_XS0027B58DEB48590E50E97D#第05集$id_XS0027B58DEB48590E50E97C#第06集$id_XS0027B58DEB48590E50E97F#第07集$id_XS0027B58DEB48590E50E97E#第08集$id_XS0027B58DEB48590E50E971#第09集$id_XS0027B58DEB48590E50E970#第10集$id_XS0027B58DEB48590E50E879#第11集$id_XS0027B58DEB48590E50E878#第12集$id_XS0027B58DEB48590E50E87B$$$第01集$id_MOE0027B58DEB48590E50E978#第02集$id_MOE0027B58DEB48590E50E97B#第03集$id_MOE0027B58DEB48590E50E97A#第04集$id_MOE0027B58DEB48590E50E97D#第05集$id_MOE0027B58DEB48590E50E97C#第06集$id_MOE0027B58DEB48590E50E97F#第07集$id_MOE0027B58DEB48590E50E97E#第08集$id_MOE0027B58DEB48590E50E971#第09集$id_MOE0027B58DEB48590E50E970#第10集$id_MOE0027B58DEB48590E50E879#第11集$id_MOE0027B58DEB48590E50E878#第12集$id_MOE0027B58DEB48590E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (112, 1, 0, 0, '勇者赫鲁库', '', 'yongzheheluku', 1, 'Y', '', '4c1357fb', '漫画改,奇幻,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/a90d7b725c8c96e47659db3aca93d33be5ce5270.png', '', '', NULL, '赫鲁库：小西克幸\n瓦米里奥：小松未可子\n阿祖多拉：松冈祯丞\n洪：石田彰\n阿丝塔：青木志贵\n伊丝塔：白石晴香\n肯罗斯：吉野裕行\n休拉：前田玲奈\n德鲁西：中岛卓也\n洛可可：德井青空\n啾伊：井泽诗织\n克莱斯：小野元春\n爱丽希娅：近藤玲奈\n拉法叶德：宫内敦士\n米迦洛斯：平川大辅\n夏尔亚美：花守由美里\n艾迪尔：七海弘希\n泽尔基恩：森岛秀太\n哈拉奥尔：丹羽哲士\n伊丽丝：爱美', '佐藤龙雄', '', '', '在魔界的某个国家。\n在魔王被一个勇者打败后，召开了争夺新魔王宝座的竞技大赛。\n身为大赛负责人的帝国四天王瓦米里奥，看到参赛选手中居然有着本应与魔族为敌的人类勇者赫鲁库，为此大发雷霆。\n在决赛之前，瓦米', '全24集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.2, 0, 0, 1726435101, 1726435053, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '在魔界的某个国家。\n在魔王被一个勇者打败后，召开了争夺新魔王宝座的竞技大赛。\n身为大赛负责人的帝国四天王瓦米里奥，看到参赛选手中居然有着本应与魔族为敌的人类勇者赫鲁库，为此大发雷霆。\n在决赛之前，瓦米里奥收到消息说，魔王邬鲁姆的城市被攻陷。她带上包括赫鲁库在内的决赛选手前往邬鲁姆城，决心将其夺回。\n赫鲁库曾笑着说“毁灭人类吧”。\n他这话是否出自真心？那笑容下隐藏着的真相是……', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0574BD8BBC1E0B5B50E978#第02集$id_XS0574BD8BBC1E0B5B50E97B#第03集$id_XS0574BD8BBC1E0B5B50E97A#第04集$id_XS0574BD8BBC1E0B5B50E97D#第05集$id_XS0574BD8BBC1E0B5B50E97C#第06集$id_XS0574BD8BBC1E0B5B50E97F#第07集$id_XS0574BD8BBC1E0B5B50E97E#第08集$id_XS0574BD8BBC1E0B5B50E971#第09集$id_XS0574BD8BBC1E0B5B50E970#第10集$id_XS0574BD8BBC1E0B5B50E879#第11集$id_XS0574BD8BBC1E0B5B50E878#第12集$id_XS0574BD8BBC1E0B5B50E87B#第13集$id_XS0574BD8BBC1E0B5B50E87A#第14集$id_XS0574BD8BBC1E0B5B50E87D#第15集$id_XS0574BD8BBC1E0B5B50E87C#第16集$id_XS0574BD8BBC1E0B5B50E87F#第17集$id_XS0574BD8BBC1E0B5B50E87E#第18集$id_XS0574BD8BBC1E0B5B50E871#第19集$id_XS0574BD8BBC1E0B5B50E870#第20集$id_XS0574BD8BBC1E0B5B50EB79#第21集$id_XS0574BD8BBC1E0B5B50EB78#第22集$id_XS0574BD8BBC1E0B5B50EB7B#第23集$id_XS0574BD8BBC1E0B5B50EB7A#第24集$id_XS0574BD8BBC1E0B5B50EB7D$$$第01集$id_MOE0574BD8BBC1E0B5B50E978#第02集$id_MOE0574BD8BBC1E0B5B50E97B#第03集$id_MOE0574BD8BBC1E0B5B50E97A#第04集$id_MOE0574BD8BBC1E0B5B50E97D#第05集$id_MOE0574BD8BBC1E0B5B50E97C#第06集$id_MOE0574BD8BBC1E0B5B50E97F#第07集$id_MOE0574BD8BBC1E0B5B50E97E#第08集$id_MOE0574BD8BBC1E0B5B50E971#第09集$id_MOE0574BD8BBC1E0B5B50E970#第10集$id_MOE0574BD8BBC1E0B5B50E879#第11集$id_MOE0574BD8BBC1E0B5B50E878#第12集$id_MOE0574BD8BBC1E0B5B50E87B#第13集$id_MOE0574BD8BBC1E0B5B50E87A#第14集$id_MOE0574BD8BBC1E0B5B50E87D#第15集$id_MOE0574BD8BBC1E0B5B50E87C#第16集$id_MOE0574BD8BBC1E0B5B50E87F#第17集$id_MOE0574BD8BBC1E0B5B50E87E#第18集$id_MOE0574BD8BBC1E0B5B50E871#第19集$id_MOE0574BD8BBC1E0B5B50E870#第20集$id_MOE0574BD8BBC1E0B5B50EB79#第21集$id_MOE0574BD8BBC1E0B5B50EB78#第22集$id_MOE0574BD8BBC1E0B5B50EB7B#第23集$id_MOE0574BD8BBC1E0B5B50EB7A#第24集$id_MOE0574BD8BBC1E0B5B50EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (113, 1, 0, 0, '公司的小小前辈', '', 'gongsidexiaoxiaoqianbei', 1, 'G', '', 'd5870a56', '漫画改,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/a6d7de651741e62ae76096ae5e2fea26cb2449da.png', '', '', NULL, '片濑诗织里：立花日菜\n篠崎拓马：新祐树\n早川千夏：花守由美里\n秋那千寻：岛崎信长\n篠崎丰：小松未可子', '佐藤光敏', '', '', '篠崎是在吉祥物周边企业上班，入职第一年的新人。\n在他的身边，总是有一个巨大的治愈源。\n那便是入职第三年，为后辈着想，很会夸人的诗织里，她一直在关照着篠崎。\n她自然地和篠崎缩短着距离，带着一丝天然呆的举', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 40, 0, 40, 40, '', 0, 0, 9.0, 0, 0, 1726435183, 1726435161, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '篠崎是在吉祥物周边企业上班，入职第一年的新人。\n在他的身边，总是有一个巨大的治愈源。\n那便是入职第三年，为后辈着想，很会夸人的诗织里，她一直在关照着篠崎。\n她自然地和篠崎缩短着距离，带着一丝天然呆的举止，让篠崎每天都感到治愈，却也不禁胡思乱想。\n两人这单纯的前辈后辈关系，是否能够有所进展呢？\n故事就此开始！', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS5522B48FB948580F50E978#第02集$id_XS5522B48FB948580F50E97B#第03集$id_XS5522B48FB948580F50E97A#第04集$id_XS5522B48FB948580F50E97D#第05集$id_XS5522B48FB948580F50E97C#第06集$id_XS5522B48FB948580F50E97F#第07集$id_XS5522B48FB948580F50E97E#第08集$id_XS5522B48FB948580F50E971#第09集$id_XS5522B48FB948580F50E970#第10集$id_XS5522B48FB948580F50E879#第11集$id_XS5522B48FB948580F50E878#第12集$id_XS5522B48FB948580F50E87B$$$第01集$id_MOE5522B48FB948580F50E978#第02集$id_MOE5522B48FB948580F50E97B#第03集$id_MOE5522B48FB948580F50E97A#第04集$id_MOE5522B48FB948580F50E97D#第05集$id_MOE5522B48FB948580F50E97C#第06集$id_MOE5522B48FB948580F50E97F#第07集$id_MOE5522B48FB948580F50E97E#第08集$id_MOE5522B48FB948580F50E971#第09集$id_MOE5522B48FB948580F50E970#第10集$id_MOE5522B48FB948580F50E879#第11集$id_MOE5522B48FB948580F50E878#第12集$id_MOE5522B48FB948580F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (114, 1, 0, 0, '甜点转生 最强甜点师降临异世界', 'おかしな転生 ～最強パティシエ異世界降臨～', 'tiandianzhuanshengzuiqiangtiandianshijianglinyishijie', 1, 'T', '', 'abf6a0ea', '异世界,美食', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2885196113.jpg', '', '', '', '手冢宏通,日笠阳子,生天目仁美,加藤涉,奥野香耶,大久保瑠美,土田大,本渡枫,内田真礼,藤原夏海,村濑步', '葛谷直行', '', '', '　　古流望作品《甜点转生 最强甜点师降临异世界》宣布TV动画化。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 4.6, 0, 0, 1726567153, 1726567091, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　古流望作品《甜点转生 最强甜点师降临异世界》宣布TV动画化。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5075EA8EE819085850E978#第02集$id_XS5075EA8EE819085850E97B#第03集$id_XS5075EA8EE819085850E97A#第04集$id_XS5075EA8EE819085850E97D#第05集$id_XS5075EA8EE819085850E97C#第06集$id_XS5075EA8EE819085850E97F#第07集$id_XS5075EA8EE819085850E97E#第08集$id_XS5075EA8EE819085850E971#第09集$id_XS5075EA8EE819085850E970#第10集$id_XS5075EA8EE819085850E879#第11集$id_XS5075EA8EE819085850E878#第12集$id_XS5075EA8EE819085850E87B$$$第01集$id_MOE5075EA8EE819085850E978#第02集$id_MOE5075EA8EE819085850E97B#第03集$id_MOE5075EA8EE819085850E97A#第04集$id_MOE5075EA8EE819085850E97D#第05集$id_MOE5075EA8EE819085850E97C#第06集$id_MOE5075EA8EE819085850E97F#第07集$id_MOE5075EA8EE819085850E97E#第08集$id_MOE5075EA8EE819085850E971#第09集$id_MOE5075EA8EE819085850E970#第10集$id_MOE5075EA8EE819085850E879#第11集$id_MOE5075EA8EE819085850E878#第12集$id_MOE5075EA8EE819085850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (115, 1, 0, 0, '庙不可言', 'てんぷる Season 1', 'miaobukeyan', 1, 'M', '', 'ecd1318c', '恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2900032945.jpg', '', '', '', '相羽爱奈,伊藤彩沙,佐佐木未来,阿澄佳奈,石见舞菜香,高田忧希,藤田咲,安元洋贵,小西克幸,川田绅司,寺川千春,若井友希,久保田未梦,内田雄马,福山润,安济知佳,高桥智秋,上坂堇,朝日奈丸佳,山下七海,芹泽优,爱美,赤坂柾之', '古贺一臣', '', '', '　　因历代祖先的形象，以及父亲的滥情行径，而长年坚持独身主义的大学生赤神明光，因一场意外邂逅少女苍叶结月，并对她一见钟情。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 6.3, 0, 0, 1726567282, 1726567227, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　因历代祖先的形象，以及父亲的滥情行径，而长年坚持独身主义的大学生赤神明光，因一场意外邂逅少女苍叶结月，并对她一见钟情。<br/>　　茶饭不思的明光为祛除杂念，决定休学出家，不料前往的寺庙正是结月居住的尼姑庵。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5474E889BA18555A50E978#第02集$id_XS5474E889BA18555A50E97B#第03集$id_XS5474E889BA18555A50E97A#第04集$id_XS5474E889BA18555A50E97D#第05集$id_XS5474E889BA18555A50E97C#第06集$id_XS5474E889BA18555A50E97F#第07集$id_XS5474E889BA18555A50E97E#第08集$id_XS5474E889BA18555A50E971#第09集$id_XS5474E889BA18555A50E970#第10集$id_XS5474E889BA18555A50E879#第11集$id_XS5474E889BA18555A50E878#第12集$id_XS5474E889BA18555A50E87B$$$第01集$id_MOE5474E889BA18555A50E978#第02集$id_MOE5474E889BA18555A50E97B#第03集$id_MOE5474E889BA18555A50E97A#第04集$id_MOE5474E889BA18555A50E97D#第05集$id_MOE5474E889BA18555A50E97C#第06集$id_MOE5474E889BA18555A50E97F#第07集$id_MOE5474E889BA18555A50E97E#第08集$id_MOE5474E889BA18555A50E971#第09集$id_MOE5474E889BA18555A50E970#第10集$id_MOE5474E889BA18555A50E879#第11集$id_MOE5474E889BA18555A50E878#第12集$id_MOE5474E889BA18555A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (116, 1, 0, 0, 'AI电子基因', 'AIの遺電子', 'AIdianzijiyin', 1, 'A', '', '2872ea76', '科幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2892524187.jpg', '', '', '', '高森奈津美,岩中睦树,宫本侑芽,大塚刚央', '佐藤雄三', '', '', '　　故事描述世界被高度科技化，人类的梦想，科技的结晶──人型机器人，它们完全融入人类的生活，却也衍生出新的对立……和人类相似，也会「生病」的它们，有着与人类不同的「治疗」选择……贴近这些拥有烦恼的AI', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 6.6, 0, 0, 1726567718, 1726567487, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　故事描述世界被高度科技化，人类的梦想，科技的结晶──人型机器人，它们完全融入人类的生活，却也衍生出新的对立……和人类相似，也会「生病」的它们，有着与人类不同的「治疗」选择……贴近这些拥有烦恼的AI们，新型态医生须堂的故事，就此开幕。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS032FBB8AEC485A0F50E978#第02集$id_XS032FBB8AEC485A0F50E97B#第03集$id_XS032FBB8AEC485A0F50E97A#第04集$id_XS032FBB8AEC485A0F50E97D#第05集$id_XS032FBB8AEC485A0F50E97C#第06集$id_XS032FBB8AEC485A0F50E97F#第07集$id_XS032FBB8AEC485A0F50E97E#第08集$id_XS032FBB8AEC485A0F50E971#第09集$id_XS032FBB8AEC485A0F50E970#第10集$id_XS032FBB8AEC485A0F50E879#第11集$id_XS032FBB8AEC485A0F50E878#第12集$id_XS032FBB8AEC485A0F50E87B$$$第01集$id_MOE032FBB8AEC485A0F50E978#第02集$id_MOE032FBB8AEC485A0F50E97B#第03集$id_MOE032FBB8AEC485A0F50E97A#第04集$id_MOE032FBB8AEC485A0F50E97D#第05集$id_MOE032FBB8AEC485A0F50E97C#第06集$id_MOE032FBB8AEC485A0F50E97F#第07集$id_MOE032FBB8AEC485A0F50E97E#第08集$id_MOE032FBB8AEC485A0F50E971#第09集$id_MOE032FBB8AEC485A0F50E970#第10集$id_MOE032FBB8AEC485A0F50E879#第11集$id_MOE032FBB8AEC485A0F50E878#第12集$id_MOE032FBB8AEC485A0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (117, 1, 0, 0, '其实，我乃最强？', '実は俺、最強でした？', 'qishiwonaizuiqiang', 1, 'Q', '', '4e759021', '异世界,奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2879886146.jpg', '', '', '', '石见舞菜香,甲斐田裕子,久野美咲,仓持若菜,立花慎之介,小清水亚美,清水彩香,种崎敦美,村濑步', '浅见松雄,直谷隆', '', '', '　　家里蹲的我突然转生到异世界成为了一国王子，但是……我出生第一天就要被杀掉了。就在我被抛弃于森林之中时，我遭遇到了一只巨大魔兽……魔兽少女与义妹，左拥右抱的新生活开幕！', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 48, 0, 48, 48, '', 0, 0, 5.5, 0, 0, 1726613292, 1726613206, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　家里蹲的我突然转生到异世界成为了一国王子，但是……我出生第一天就要被杀掉了。就在我被抛弃于森林之中时，我遭遇到了一只巨大魔兽……魔兽少女与义妹，左拥右抱的新生活开幕！<br/>　　改编自澄守彩的同名轻小说。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0572BB8DB0195F0850E978#第02集$id_XS0572BB8DB0195F0850E97B#第03集$id_XS0572BB8DB0195F0850E97A#第04集$id_XS0572BB8DB0195F0850E97D#第05集$id_XS0572BB8DB0195F0850E97C#第06集$id_XS0572BB8DB0195F0850E97F#第07集$id_XS0572BB8DB0195F0850E97E#第08集$id_XS0572BB8DB0195F0850E971#第09集$id_XS0572BB8DB0195F0850E970#第10集$id_XS0572BB8DB0195F0850E879#第11集$id_XS0572BB8DB0195F0850E878#第12集$id_XS0572BB8DB0195F0850E87B$$$第01集$id_MOE0572BB8DB0195F0850E978#第02集$id_MOE0572BB8DB0195F0850E97B#第03集$id_MOE0572BB8DB0195F0850E97A#第04集$id_MOE0572BB8DB0195F0850E97D#第05集$id_MOE0572BB8DB0195F0850E97C#第06集$id_MOE0572BB8DB0195F0850E97F#第07集$id_MOE0572BB8DB0195F0850E97E#第08集$id_MOE0572BB8DB0195F0850E971#第09集$id_MOE0572BB8DB0195F0850E970#第10集$id_MOE0572BB8DB0195F0850E879#第11集$id_MOE0572BB8DB0195F0850E878#第12集$id_MOE0572BB8DB0195F0850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (118, 1, 0, 0, '满怀美梦的少年是现实主义者', '夢見る男子は現実主義者', 'manhuaimeimengdeshaonianshixianshizhuyizhe', 1, 'M', '', '69d8edb6', '校园,恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2889891876.jpg', '', '', '', '宫濑尚也,凉本秋穗,石原夏织,小松未可子,花守由美里', '古贺一臣', '', '', '　　「双向的单恋」，令人好心焦。佐城涉暗恋同班的美少女——夏川爱华。他满怀美梦，希望与她两情相悦而积极地展开追求，即使遭受挫折也不气馁。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 5.7, 0, 0, 1726613438, 1726613361, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　「双向的单恋」，令人好心焦。佐城涉暗恋同班的美少女——夏川爱华。他满怀美梦，希望与她两情相悦而积极地展开追求，即使遭受挫折也不气馁。<br/>　　但是，就在某一天，他的梦突然醒了。<br/>　　「条件那么好的女生……我根本高攀不起吧？」<br/>　　理解了现实之后，涉开始与爱华保持适当的距离。而这样的态度反而令爱华茫然。<br/>　　「莫非……他讨厌我了？」<br/>　　误会让爱华不知所措，开始表现出连自己都没察觉的好感……！？<br/>　　双向单恋的两人之间彼此误会、令人心痒难耐的青春恋爱喜剧，开幕！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS072EE880EC4D0F0F50E978#第02集$id_XS072EE880EC4D0F0F50E97B#第03集$id_XS072EE880EC4D0F0F50E97A#第04集$id_XS072EE880EC4D0F0F50E97D#第05集$id_XS072EE880EC4D0F0F50E97C#第06集$id_XS072EE880EC4D0F0F50E97F#第07集$id_XS072EE880EC4D0F0F50E97E#第08集$id_XS072EE880EC4D0F0F50E971#第09集$id_XS072EE880EC4D0F0F50E970#第10集$id_XS072EE880EC4D0F0F50E879#第11集$id_XS072EE880EC4D0F0F50E878#第12集$id_XS072EE880EC4D0F0F50E87B$$$第01集$id_MOE072EE880EC4D0F0F50E978#第02集$id_MOE072EE880EC4D0F0F50E97B#第03集$id_MOE072EE880EC4D0F0F50E97A#第04集$id_MOE072EE880EC4D0F0F50E97D#第05集$id_MOE072EE880EC4D0F0F50E97C#第06集$id_MOE072EE880EC4D0F0F50E97F#第07集$id_MOE072EE880EC4D0F0F50E97E#第08集$id_MOE072EE880EC4D0F0F50E971#第09集$id_MOE072EE880EC4D0F0F50E970#第10集$id_MOE072EE880EC4D0F0F50E879#第11集$id_MOE072EE880EC4D0F0F50E878#第12集$id_MOE072EE880EC4D0F0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (119, 1, 0, 0, '圣者无双～上班族、在异世界的存活之道～', '聖者無双～サラリーマン、異世界で生き残るために歩む道～（2023）', 'shengzhewushuangshangbanzuzaiyishijiedecunhuozhidao', 1, 'S', '', '6a8f359', '异世界,奇幻,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2906559139.jpg', '', '', '', '川岛零士 / 大塚明夫 / 前野智昭 / 小野大辅 / 衣川里佳 / 立花日菜 / 石见舞菜香 / 佐佐木未来 / 森久保祥太郎', '玉川真人', '', '', '　　命运之神打赌输给了异世界之神，将十个平凡的灵魂送到了异世界。', '全12集', '', 0, '0', '', '', '日本', '七月', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 4.7, 0, 0, 1744094675, 1726613479, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '命运之神打赌输给了异世界之神，将十个平凡的灵魂送到了异世界。 十个灵魂中有一个与死亡命运抗争的上班族。 这个化为抖M僵尸治愈士的男人，今后将会有怎麽样的境遇——', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0776B4DEBA1C54144DE8#第02集$MOE0776B4DEBA1C54144DEB#第03集$MOE0776B4DEBA1C54144DEA#第04集$MOE0776B4DEBA1C54144DED#第05集$MOE0776B4DEBA1C54144DEC#第06集$MOE0776B4DEBA1C54144DEF#第07集$MOE0776B4DEBA1C54144DEE#第08集$MOE0776B4DEBA1C54144DE1#第09集$MOE0776B4DEBA1C54144DE0#第10集$MOE0776B4DEBA1C54144CE9#第11集$MOE0776B4DEBA1C54144CE8#第12集$MOE0776B4DEBA1C54144CEB$$$第01集$id_XS0776B4DEBA1C54144DE8#第02集$id_XS0776B4DEBA1C54144DEB#第03集$id_XS0776B4DEBA1C54144DEA#第04集$id_XS0776B4DEBA1C54144DED#第05集$id_XS0776B4DEBA1C54144DEC#第06集$id_XS0776B4DEBA1C54144DEF#第07集$id_XS0776B4DEBA1C54144DEE#第08集$id_XS0776B4DEBA1C54144DE1#第09集$id_XS0776B4DEBA1C54144DE0#第10集$id_XS0776B4DEBA1C54144CE9#第11集$id_XS0776B4DEBA1C54144CE8#第12集$id_XS0776B4DEBA1C54144CEB$$$第01集$id_MOE0776B4DEBA1C54144DE8#第02集$id_MOE0776B4DEBA1C54144DEB#第03集$id_MOE0776B4DEBA1C54144DEA#第04集$id_MOE0776B4DEBA1C54144DED#第05集$id_MOE0776B4DEBA1C54144DEC#第06集$id_MOE0776B4DEBA1C54144DEF#第07集$id_MOE0776B4DEBA1C54144DEE#第08集$id_MOE0776B4DEBA1C54144DE1#第09集$id_MOE0776B4DEBA1C54144DE0#第10集$id_MOE0776B4DEBA1C54144CE9#第11集$id_MOE0776B4DEBA1C54144CE8#第12集$id_MOE0776B4DEBA1C54144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (120, 1, 0, 0, '能干的猫今天也忧郁', '', 'nenggandemaojintianyeyouyu', 1, 'N', '', '4040a217', '漫画改,日常,搞笑,奇幻', 'https://i0.hdslb.com/bfs/bangumi/image/9b50ba019a4020d105e471fb73e9d62f9d0400b9.png', '', '', NULL, '谕吉：安元洋贵\n福泽幸来：石川由依\n柴咲由理：加隈亚衣\n织冢馨：小西克幸\n仁科理央：M・A・O\n店长：入野自由\n优芽：竹达彩奈\n优芽妈妈：日笠阳子\n优芽外婆：久保田民绘\n幸来妈妈：佐藤聪美\n幸来爸爸：福山润\n尾代：稻濑葵\n邻居芽衣婆婆：太地琴惠', '工藤进', '', '', '「我是一只猫。但我不是普通的猫。 是一只空前绝后的『能干的猫』」 工作能力优秀但生活能力一塌糊涂的公司职员福泽幸来，某一天捡到了濒临冻死的幼猫。她取名为谕吉的这只猫在不知不觉中成长到了离奇的体格，并替', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 34, 0, 34, 34, '', 0, 0, 9.8, 0, 0, 1726613713, 1726613670, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '「我是一只猫。但我不是普通的猫。 是一只空前绝后的『能干的猫』」 工作能力优秀但生活能力一塌糊涂的公司职员福泽幸来，某一天捡到了濒临冻死的幼猫。她取名为谕吉的这只猫在不知不觉中成长到了离奇的体格，并替没用的主人做饭、洗衣、打扫、购物、跟街坊邻居打交道……成为了能完美做好一切的“能干的猫”。「我家的猫可能有点不平凡……？」幸来一边这样想，一边被谕吉做的美味饭菜牢牢抓住了胃。生活中的一切都靠谕吉支持的幸来，已经无法想象没有谕吉的生活了！这是梦幻般的完美猫咪与超懒散公司职员的悠闲自在同居生活。', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0527B888E81B5C0E50E978#第02集$id_XS0527B888E81B5C0E50E97B#第03集$id_XS0527B888E81B5C0E50E97A#第04集$id_XS0527B888E81B5C0E50E97D#第05集$id_XS0527B888E81B5C0E50E97C#第06集$id_XS0527B888E81B5C0E50E97F#第07集$id_XS0527B888E81B5C0E50E97E#第08集$id_XS0527B888E81B5C0E50E971#第09集$id_XS0527B888E81B5C0E50E970#第10集$id_XS0527B888E81B5C0E50E879#第11集$id_XS0527B888E81B5C0E50E878#第12集$id_XS0527B888E81B5C0E50E87B#第13集$id_XS0527B888E81B5C0E50E87A$$$第01集$id_MOE0527B888E81B5C0E50E978#第02集$id_MOE0527B888E81B5C0E50E97B#第03集$id_MOE0527B888E81B5C0E50E97A#第04集$id_MOE0527B888E81B5C0E50E97D#第05集$id_MOE0527B888E81B5C0E50E97C#第06集$id_MOE0527B888E81B5C0E50E97F#第07集$id_MOE0527B888E81B5C0E50E97E#第08集$id_MOE0527B888E81B5C0E50E971#第09集$id_MOE0527B888E81B5C0E50E970#第10集$id_MOE0527B888E81B5C0E50E879#第11集$id_MOE0527B888E81B5C0E50E878#第12集$id_MOE0527B888E81B5C0E50E87B#第13集$id_MOE0527B888E81B5C0E50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (121, 1, 0, 0, '卡片战斗先导者will Dress', 'アニメ：カードファイト!! ヴァンガード will+Dress（2022）', 'kapianzhandouxiandaozhewillDress', 1, 'K', '', '2ae0cdae', '游戏改', 'http://i0.hdslb.com/bfs/bangumi/image/73852afa7678a74fcf1b691dcd41d99db9de8cac.png', '', '', '', '苍井翔太 / 佐久间大介 / 内田雄马 / 小野友树', '森贤', '', '', '2021年4月播放了电视动画《卡片战斗先导者 overDress》第一季，同年10月播放了第二季。而作为续作的《卡片战斗先导者 will Dress》将在2022年7月开播！此次的角色设计依然是CLA', '全13集', '', 0, '0', '', '', '日本', '七月', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.1, 0, 0, 1744108009, 1726613903, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>2021年4月播放了电视动画《卡片战斗先导者 overDress》第一季，同年10月播放了第二季。而作为续作的《卡片战斗先导者 will Dress》将在2022年7月开播！此次的角色设计依然是CLAMP，动画制作也依然是Kinema Citrus。故事将以悠游一行人及新角色们参加的某个大赛为中心，务必不要错过新的大战！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0376E988EA4D0C5C50E978#第02集$MOE0376E988EA4D0C5C50E97B#第03集$MOE0376E988EA4D0C5C50E97A#第04集$MOE0376E988EA4D0C5C50E97D#第05集$MOE0376E988EA4D0C5C50E97C#第06集$MOE0376E988EA4D0C5C50E97F#第07集$MOE0376E988EA4D0C5C50E97E#第08集$MOE0376E988EA4D0C5C50E971#第09集$MOE0376E988EA4D0C5C50E970#第10集$MOE0376E988EA4D0C5C50E879#第11集$MOE0376E988EA4D0C5C50E878#第12集$MOE0376E988EA4D0C5C50E87B#第13集$MOE0376E988EA4D0C5C50E87A$$$第01集$id_XS0376E988EA4D0C5C50E978#第02集$id_XS0376E988EA4D0C5C50E97B#第03集$id_XS0376E988EA4D0C5C50E97A#第04集$id_XS0376E988EA4D0C5C50E97D#第05集$id_XS0376E988EA4D0C5C50E97C#第06集$id_XS0376E988EA4D0C5C50E97F#第07集$id_XS0376E988EA4D0C5C50E97E#第08集$id_XS0376E988EA4D0C5C50E971#第09集$id_XS0376E988EA4D0C5C50E970#第10集$id_XS0376E988EA4D0C5C50E879#第11集$id_XS0376E988EA4D0C5C50E878#第12集$id_XS0376E988EA4D0C5C50E87B#第13集$id_XS0376E988EA4D0C5C50E87A$$$第01集$id_MOE0376E988EA4D0C5C50E978#第02集$id_MOE0376E988EA4D0C5C50E97B#第03集$id_MOE0376E988EA4D0C5C50E97A#第04集$id_MOE0376E988EA4D0C5C50E97D#第05集$id_MOE0376E988EA4D0C5C50E97C#第06集$id_MOE0376E988EA4D0C5C50E97F#第07集$id_MOE0376E988EA4D0C5C50E97E#第08集$id_MOE0376E988EA4D0C5C50E971#第09集$id_MOE0376E988EA4D0C5C50E970#第10集$id_MOE0376E