INSERT INTO `mac_vod` VALUES (158, 1, 0, 0, '边缘服务', 'THE MARGINAL SERVICE', 'bianyuanfuwu', 1, 'B', '', '4d37fc02', '科幻,职场', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2888738995.jpg', '', '', '', '玄田哲章,宫野真守,三石琴乃,内田雄马,三木真一郎,下野纮,名冢佳织,中村悠一,杉田智和,森川智之,内山昂辉', '迫井政行', '', '', '　　有一天，地球遭到了格雷型外星人的袭击。拯救了因外星人的攻击而束手无策、处于毁灭状态的航空自卫队的，是拥有不可能存在的人脸的“传说中的生物”。国家在那次事件中首次认识到他们在地球上共存的事实之后，称', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 4.5, 0, 0, 1727892795, 1727892669, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　有一天，地球遭到了格雷型外星人的袭击。拯救了因外星人的攻击而束手无策、处于毁灭状态的航空自卫队的，是拥有不可能存在的人脸的“传说中的生物”。国家在那次事件中首次认识到他们在地球上共存的事实之后，称他们为“境界人”并监视着他们。<br/>　　几年后，由于发生了移民和不可思议的恐怖事件，世界上有一个混沌的机构成立了，那就是“边缘服务”（Marginal Service），这是取缔专门犯罪，彻底隐瞒其存在的机构。<br/>　　故事舞台是 Japan 涩宿（ジャパン澁宿）……这是一个聚集了一群穿着 Japan 所引以为豪的“束膝工装裤（ニッカポッカ）”的精英们，日夜与“境界人”对峙，守护地球的故事。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0573BF8FEF4A5D0B50E978#第02集$id_XS0573BF8FEF4A5D0B50E97B#第03集$id_XS0573BF8FEF4A5D0B50E97A#第04集$id_XS0573BF8FEF4A5D0B50E97D#第05集$id_XS0573BF8FEF4A5D0B50E97C#第06集$id_XS0573BF8FEF4A5D0B50E97F#第07集$id_XS0573BF8FEF4A5D0B50E97E#第08集$id_XS0573BF8FEF4A5D0B50E971#第09集$id_XS0573BF8FEF4A5D0B50E970#第10集$id_XS0573BF8FEF4A5D0B50E879#第11集$id_XS0573BF8FEF4A5D0B50E878#第12集$id_XS0573BF8FEF4A5D0B50E87B$$$第01集$id_MOE0573BF8FEF4A5D0B50E978#第02集$id_MOE0573BF8FEF4A5D0B50E97B#第03集$id_MOE0573BF8FEF4A5D0B50E97A#第04集$id_MOE0573BF8FEF4A5D0B50E97D#第05集$id_MOE0573BF8FEF4A5D0B50E97C#第06集$id_MOE0573BF8FEF4A5D0B50E97F#第07集$id_MOE0573BF8FEF4A5D0B50E97E#第08集$id_MOE0573BF8FEF4A5D0B50E971#第09集$id_MOE0573BF8FEF4A5D0B50E970#第10集$id_MOE0573BF8FEF4A5D0B50E879#第11集$id_MOE0573BF8FEF4A5D0B50E878#第12集$id_MOE0573BF8FEF4A5D0B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (159, 1, 0, 0, '邻人似银河', 'おとなりに銀河', 'linrensiyinhe', 1, 'L', '', '57ea4a6d', '恋爱', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2882750384.jpg', '', '', '', '日笠阳子,杉田智和,高桥李依,长绳麻理亚,远藤璃菜,八代拓,和久井优', '木村隆一', '', '', '　　从“婚约”开始的恋爱……\r\n                                    \r\n                                　　父母去世后，为了独自抚养年幼', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 6.3, 0, 0, 1727892959, 1727892916, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　从“婚约”开始的恋爱……<br/>　　父母去世后，为了独自抚养年幼的弟弟妹妹，不畅销的漫画家久我卖力地画着少女漫画。<br/>　　来到辛劳的他身边的，是干练与美貌相结合的神级助手五色小姐。<br/>　　本以为这样工作就能顺利进行了…但在偶然触碰到五色小姐身上的刺后，她对久我说：<br/>　　“我是流星之民的公主。与你结成了婚姻关系的契约。”<br/>　　没有恋爱经验的二人，从“契约”开始的新婚恋爱喜剧，开幕！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0420E9D9BD485B5D50E978#第02集$id_XS0420E9D9BD485B5D50E97B#第03集$id_XS0420E9D9BD485B5D50E97A#第04集$id_XS0420E9D9BD485B5D50E97D#第05集$id_XS0420E9D9BD485B5D50E97C#第06集$id_XS0420E9D9BD485B5D50E97F#第07集$id_XS0420E9D9BD485B5D50E97E#第08集$id_XS0420E9D9BD485B5D50E971#第09集$id_XS0420E9D9BD485B5D50E970#第10集$id_XS0420E9D9BD485B5D50E879#第11集$id_XS0420E9D9BD485B5D50E878#第12集$id_XS0420E9D9BD485B5D50E87B$$$第01集$id_MOE0420E9D9BD485B5D50E978#第02集$id_MOE0420E9D9BD485B5D50E97B#第03集$id_MOE0420E9D9BD485B5D50E97A#第04集$id_MOE0420E9D9BD485B5D50E97D#第05集$id_MOE0420E9D9BD485B5D50E97C#第06集$id_MOE0420E9D9BD485B5D50E97F#第07集$id_MOE0420E9D9BD485B5D50E97E#第08集$id_MOE0420E9D9BD485B5D50E971#第09集$id_MOE0420E9D9BD485B5D50E970#第10集$id_MOE0420E9D9BD485B5D50E879#第11集$id_MOE0420E9D9BD485B5D50E878#第12集$id_MOE0420E9D9BD485B5D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (160, 1, 0, 0, '我心里危险的东西', '僕の心のヤバイやつ', 'woxinliweixiandedongxi', 1, 'W', '', '1e64d461', '校园,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2884799201.jpg', '', '', '', '凤芳野,岩泽俊树,三野雄大,岛崎信长,田村由香里,丰崎爱生,福岛润,佐藤元,冈本信彦,种崎敦美,潘惠美,朝井彩加,羊宫妃那,堀江瞬', '久保太郎,铃木拓磨,陈达理,赤城博昭', '', '', '　　拥有健全感性的善良人市川京太郎，对位于食物链顶点的美少女山田杏奈在意得不得了。通过观察发现山田意外的一面…!? 虽然完全不知道在想什么不过非常贪吃，不如说除了吃根本什么都没在想，简直是个脑袋空空的', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 160, 0, 160, 160, '', 0, 0, 8.8, 0, 0, 1732831642, 1727893071, 0, 0, 0, 0, 0.0, '', '238', '', '', '', '', '', '', '', '<p>　　拥有健全感性的善良人市川京太郎，对位于食物链顶点的美少女山田杏奈在意得不得了。通过观察发现山田意外的一面…!? 虽然完全不知道在想什么不过非常贪吃，不如说除了吃根本什么都没在想，简直是个脑袋空空的人型母猪。理应不会缩短的两人间的距离，奇迹会发生吗!? 就这样京太郎的青春，正非常安静地发生变化……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0072BA8CED1D5B0850E978#第02集$MOE0072BA8CED1D5B0850E97B#第03集$MOE0072BA8CED1D5B0850E97A#第04集$MOE0072BA8CED1D5B0850E97D#第05集$MOE0072BA8CED1D5B0850E97C#第06集$MOE0072BA8CED1D5B0850E97F#第07集$MOE0072BA8CED1D5B0850E97E#第08集$MOE0072BA8CED1D5B0850E971#第09集$MOE0072BA8CED1D5B0850E970#第10集$MOE0072BA8CED1D5B0850E879#第11集$MOE0072BA8CED1D5B0850E878#第12集$MOE0072BA8CED1D5B0850E87B$$$第01集$id_XS0072BA8CED1D5B0850E978#第02集$id_XS0072BA8CED1D5B0850E97B#第03集$id_XS0072BA8CED1D5B0850E97A#第04集$id_XS0072BA8CED1D5B0850E97D#第05集$id_XS0072BA8CED1D5B0850E97C#第06集$id_XS0072BA8CED1D5B0850E97F#第07集$id_XS0072BA8CED1D5B0850E97E#第08集$id_XS0072BA8CED1D5B0850E971#第09集$id_XS0072BA8CED1D5B0850E970#第10集$id_XS0072BA8CED1D5B0850E879#第11集$id_XS0072BA8CED1D5B0850E878#第12集$id_XS0072BA8CED1D5B0850E87B$$$第01集$id_MOE0072BA8CED1D5B0850E978#第02集$id_MOE0072BA8CED1D5B0850E97B#第03集$id_MOE0072BA8CED1D5B0850E97A#第04集$id_MOE0072BA8CED1D5B0850E97D#第05集$id_MOE0072BA8CED1D5B0850E97C#第06集$id_MOE0072BA8CED1D5B0850E97F#第07集$id_MOE0072BA8CED1D5B0850E97E#第08集$id_MOE0072BA8CED1D5B0850E971#第09集$id_MOE0072BA8CED1D5B0850E970#第10集$id_MOE0072BA8CED1D5B0850E879#第11集$id_MOE0072BA8CED1D5B0850E878#第12集$id_MOE0