INSERT INTO `mac_vod` VALUES (162, 1, 0, 0, '无神世界中的神明活动', '神無き世界のカミサマ活動', 'wushenshijiezhongdeshenminghuodong', 1, 'W', '', 'b4476785', '冒险,奇幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2890202567.jpg', '', '', '', '江越彬纪,小清水亚美,小松未可子,高桥李依,悠木碧,速水奖,富田美忧,诹访部顺一,绪方惠美,藤泽奖,上坂堇,花泽香菜,鬼头明里,榎木淳弥', '山崎立士,末田宜史,稻叶友纪', '', '', '　　男主角卜部征人被自己的爸爸捧为新兴宗教「神地崇教」的接班人，在献祭仪式中意外转生到异世界。征人原以为终于不会有人因为被笑信奉邪教而疏远他，但这个国家饱受皇家爆政所苦，不忍好友被无故赐死的征人默默祈', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 7.5, 0, 0, 1728042622, 1728042568, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　男主角卜部征人被自己的爸爸捧为新兴宗教「神地崇教」的接班人，在献祭仪式中意外转生到异世界。征人原以为终于不会有人因为被笑信奉邪教而疏远他，但这个国家饱受皇家爆政所苦，不忍好友被无故赐死的征人默默祈祷，拥有超强神力的「御灵」马上前来搭救他，而这个御灵竟然就是神地崇教的真神 「御灵」……</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5323B88FBF1E550C50E978#第02集$id_XS5323B88FBF1E550C50E97B#第03集$id_XS5323B88FBF1E550C50E97A#第04集$id_XS5323B88FBF1E550C50E97D#第05集$id_XS5323B88FBF1E550C50E97C#第06集$id_XS5323B88FBF1E550C50E97F#第07集$id_XS5323B88FBF1E550C50E97E#第08集$id_XS5323B88FBF1E550C50E971#第09集$id_XS5323B88FBF1E550C50E970#第10集$id_XS5323B88FBF1E550C50E879#第11集$id_XS5323B88FBF1E550C50E878#第12集$id_XS5323B88FBF1E550C50E87B$$$第01集$id_MOE5323B88FBF1E550C50E978#第02集$id_MOE5323B88FBF1E550C50E97B#第03集$id_MOE5323B88FBF1E550C50E97A#第04集$id_MOE5323B88FBF1E550C50E97D#第05集$id_MOE5323B88FBF1E550C50E97C#第06集$id_MOE5323B88FBF1E550C50E97F#第07集$id_MOE5323B88FBF1E550C50E97E#第08集$id_MOE5323B88FBF1E550C50E971#第09集$id_MOE5323B88FBF1E550C50E970#第10集$id_MOE5323B88FBF1E550C50E879#第11集$id_MOE5323B88FBF1E550C50E878#第12集$id_MOE5323B88FBF1E550C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (163, 1, 0, 0, '六道的恶女们', '六道の悪女たち', 'liudaodeenvmen', 1, 'L', '', 'f18b4673', '校园,恋爱', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2889835761.jpg', '', '', '', '关根瞳,石谷春贵,松冈美里,夜道雪,大空直美,佐藤元,上坂堇', '齐藤启也', '', '', '　　在这个全是混混的学校，苦逼少年六道获得了受坏女人欢迎的能力，他的命运将要发生翻天覆地的改变……', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 5.5, 0, 0, 1728042764, 1728042712, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　在这个全是混混的学校，苦逼少年六道获得了受坏女人欢迎的能力，他的命运将要发生翻天覆地的改变……<br/>　　《六道的恶女们》是中村勇志于2016年6月23日在《周刊少年Champion》第30号起连载的漫画，也是中村老师的第1部长篇连载。近日官宣动画化！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5726B4DABD1F5A0A50E978#第02集$id_XS5726B4DABD1F5A0A50E97B#第03集$id_XS5726B4DABD1F5A0A50E97A#第04集$id_XS5726B4DABD1F5A0A50E97D#第05集$id_XS5726B4DABD1F5A0A50E97C#第06集$id_XS5726B4DABD1F5A0A50E97F#第07集$id_XS5726B4DABD1F5A0A50E97E#第08集$id_XS5726B4DABD1F5A0A50E971#第09集$id_XS5726B4DABD1F5A0A50E970#第10集$id_XS5726B4DABD1F5A0A50E879#第11集$id_XS5726B4DABD1F5A0A50E878#第12集$id_XS5726B4DABD1F5A0A50E87B$$$第01集$id_MOE5726B4DABD1F5A0A50E978#第02集$id_MOE5726B4DABD1F5A0A50E97B#第03集$id_MOE5726B4DABD1F5A0A50E97A#第04集$id_MOE5726B4DABD1F5A0A50E97D#第05集$id_MOE5726B4DABD1F5A0A50E97C#第06集$id_MOE5726B4DABD1F5A0A50E97F#第07集$id_MOE5726B4DABD1F5A0A50E97E#第08集$id_MOE5726B4DABD1F5A0A50E971#第09集$id_MOE5726B4DABD1F5A0A50E970#第10集$id_MOE5726B4DABD1F5A0A50E879#第11集$id_MOE5726B4DABD1F5A0A50E878#第12集$id_MOE5726B4DABD1F5A0A50E87B', '', '', '', '', 0, '', '');
