INSERT INTO `mac_vod` VALUES (467, 1, 0, 0, '魔术士欧菲流浪之旅 拉玛城篇', '魔術士オーフェンはぐれ旅 アーバンラマ編', 'moshushioufeiliulangzhilvlamachengpian', 1, 'M', '', '4704a791', '小说改,奇幻,战斗,冒险', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2881651521.jpg', '', '', '', '森久保祥太郎 / 大久保瑠美 / 小林裕介 / 水野麻里绘 / 渊上舞 / 小野大辅 / 青木志贵 / 榎木淳弥 / 江口拓也', '滨名孝行', '', '', 'PV链接：', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 0.0, 0, 0, 1732713399, 1728044151, 0, 0, 0, 0, 0.0, '', '468', '', '', '', '', '', '', '', '<p>PV链接：</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0520BC8CE81E540850E978#第02集$MOE0520BC8CE81E540850E97B#第03集$MOE0520BC8CE81E540850E97A#第04集$MOE0520BC8CE81E540850E97D#第05集$MOE0520BC8CE81E540850E97C#第06集$MOE0520BC8CE81E540850E97F#第07集$MOE0520BC8CE81E540850E97E#第08集$MOE0520BC8CE81E540850E971#第09集$MOE0520BC8CE81E540850E970#第10集$MOE0520BC8CE81E540850E879#第11集$MOE0520BC8CE81E540850E878#第12集$MOE0520BC8CE81E540850E87B$$$第01集$id_XS0520BC8CE81E540850E978#第02集$id_XS0520BC8CE81E540850E97B#第03集$id_XS0520BC8CE81E540850E97A#第04集$id_XS0520BC8CE81E540850E97D#第05集$id_XS0520BC8CE81E540850E97C#第06集$id_XS0520BC8CE81E540850E97F#第07集$id_XS0520BC8CE81E540850E97E#第08集$id_XS0520BC8CE81E540850E971#第09集$id_XS0520BC8CE81E540850E970#第10集$id_XS0520BC8CE81E540850E879#第11集$id_XS0520BC8CE81E540850E878#第12集$id_XS0520BC8CE81E540850E87B$$$第01集$id_MOE0520BC8CE81E540850E978#第02集$id_MOE0520BC8CE81E540850E97B#第03集$id_MOE0520BC8CE81E540850E97A#第04集$id_MOE0520BC8CE81E540850E97D#第05集$id_MOE0520BC8CE81E540850E97C#第06集$id_MOE0520BC8CE81E540850E97F#第07集$id_MOE0520BC8CE81E540850E97E#第08集$id_MOE0520BC8CE81E540850E971#第09集$id_MOE0520BC8CE81E540850E970#第10集$id_MOE0520BC8CE81E540850E879#第11集$id_MOE0520BC8CE81E540850E878#第12集$id_MOE0520BC8CE81E540850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (205, 1, 0, 0, '转生王女与天才千金的魔法革命', '転生王女と天才令嬢の魔法革命（2023）', 'zhuanshengwangnvyutiancaiqianjindemofageming', 1, 'Z', '', '8a28fdf3', '异世界,奇幻,冒险,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2877749629.jpg', '', '', '', '千本木彩花 / 石见舞菜香 / 加隈亚衣 / 坂田将吾 / 羊宫妃那 / 筱原侑 / 滨田贤二 / 坪井智浩 / 露崎亘 / 八代拓 / 冈野友佑 / 手冢宏通', '玉木慎吾', '', '', '故事发生在一个几乎人人都会使用魔法的世界之中，艾妮丝菲亚（千本木彩花 配音）是帕雷提亚王国的公主，在童年时代，她意外的重获了前世的记忆。但因为无法使用魔法，艾妮丝菲亚在贵族之中饱受轻视。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 59, 0, 59, 59, '', 0, 0, 7.8, 0, 0, 1729405524, 1729405413, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在一个几乎人人都会使用魔法的世界之中，艾妮丝菲亚（千本木彩花 配音）是帕雷提亚王国的公主，在童年时代，她意外的重获了前世的记忆。但因为无法使用魔法，艾妮丝菲亚在贵族之中饱受轻视。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0976BE80EF4D0B0A50E978#第02集$id_XS0976BE80EF4D0B0A50E97B#第03集$id_XS0976BE80EF4D0B0A50E97A#第04集$id_XS0976BE80EF4D0B0A50E97D#第05集$id_XS0976BE80EF4D0B0A50E97C#第06集$id_XS0976BE80EF4D0B0A50E97F#第07集$id_XS0976BE80EF4D0B0A50E97E#第08集$id_XS0976BE80EF4D0B0A50E971#第09集$id_XS0976BE80EF4D0B0A50E970#第10集$id_XS0976BE80EF4D0B0A50E879#第11集$id_XS0976BE80EF4D0B0A50E878#第12集$id_XS0976BE80EF4D0B0A50E87B$$$第01集$id_MOE0976BE80EF4D0B0A50E978#第02集$id_MOE0976BE80EF4D0B0A50E97B#第03集$id_MOE0976BE80EF4D0B0A50E97A#第04集$id_MOE0976BE80EF4D0B0A50E97D#第05集$id_MOE0976BE80EF4D0B0A50E97C#第06集$id_MOE0976BE80EF4D0B0A50E97F#第07集$id_MOE0976BE80EF4D0B0A50E97E#第08集$id_MOE0976BE80EF4D0B0A50E971#第09集$id_MOE0976BE80EF4D0B0A50E970#第10集$id_MOE0976BE80EF4D0B0A50E879#第11集$id_MOE0976BE80EF4D0B0A50E878#第12集$id_MOE0976BE80EF4D0B0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (169, 1, 0, 0, '赛马娘 巅峰之路', '', 'saimaniangdianfengzhilu', 1, 'S', '', 'dee189e4', '游戏改,运动,偶像', 'https://i0.hdslb.com/bfs/bangumi/image/3743fe94dce05f82048864ce26f6764b4c195d70.png', '', '', '', '成田路：中村环奈\n爱慕织姬：咲咲木瞳\n好歌剧：德井青空\n冲田训练员：土田大\n米浴：石见舞菜香\n真机伶：篠原侑\n名将怒涛：和多田美咲\n春乌菈菈：首藤志奈', '廖程芝', '', '', '经典三冠赛，皋月奖、日本德比、菊花奖。在这些一生只能挑战一次的赛事中夺冠，是所有马娘和训练员的梦想。\r\n成田路、爱慕织姬、好歌剧，这三位被称为三强的马娘，心怀绝对不能输的决意，为争夺最强，在火热的经典战', '全4集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 9.8, 0, 0, 1728118799, 1728118691, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '经典三冠赛，皋月奖、日本德比、菊花奖。在这些一生只能挑战一次的赛事中夺冠，是所有马娘和训练员的梦想。\n成田路、爱慕织姬、好歌剧，这三位被称为三强的马娘，心怀绝对不能输的决意，为争夺最强，在火热的经典战线上相互竞争。\n——赛马娘新系列网络动画企划，终于启动。', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5572E989B110080D50E978#第02集$id_XS5572E989B110080D50E97B#第03集$id_XS5572E989B110080D50E97A#第04集$id_XS5572E989B110080D50E97D$$$第01集$id_MOE5572E989B110080D50E978#第02集$id_MOE5572E989B110080D50E97B#第03集$id_MOE5572E989B110080D50E97A#第04集$id_MOE5572E989B110080D50E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (170, 1, 0, 0, '公爵的契约未婚妻', '彼女が公爵邸に行った理由', 'gongjuedeqiyueweihunqi', 1, 'G', '', 'a581f497', '异世界,恋爱,推理', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2882946912.jpg', '', '', '', '中岛爱,竹田海渡,矢野优美华,诹访部顺一,杉田智和,石田彰,土岐隼一,梅田修一朗,梅原裕一郎,宫本侑芽', '山元隼一', '', '', '　　『公爵的契约未婚妻』(彼女が公爵邸に行った理由) 动画化', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 6.8, 0, 0, 1728118885, 1728118843, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　『公爵的契约未婚妻』(彼女が公爵邸に行った理由) 动画化<br/>　　故事讲述了高三复读生朴银河不明不白地死了<br/>　　之后又莫名其妙附身到了小说里的人物身上<br/>　　然而这个要附身的对象并不是主角，而是不久之后就要送命的配角！<br/>　　为了躲避短命的命运，她和小说中的男主角做起了交易。<br/>　　然而事情并没有这么简单<br/>　　公爵这个家伙虽有着天使脸蛋内心却比恶魔还要狠毒……<br/>　　她究竟能不能从短命的命运中逃脱呢？</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5022B489EF1D540E50E978#第02集$id_XS5022B489EF1D540E50E97B#第03集$id_XS5022B489EF1D540E50E97A#第04集$id_XS5022B489EF1D540E50E97D#第05集$id_XS5022B489EF1D540E50E97C#第06集$id_XS5022B489EF1D540E50E97F#第07集$id_XS5022B489EF1D540E50E97E#第08集$id_XS5022B489EF1D540E50E971#第09集$id_XS5022B489EF1D540E50E970#第10集$id_XS5022B489EF1D540E50E879#第11集$id_XS5022B489EF1D540E50E878#第12集$id_XS5022B489EF1D540E50E87B$$$第01集$id_MOE5022B489EF1D540E50E978#第02集$id_MOE5022B489EF1D540E50E97B#第03集$id_MOE5022B489EF1D540E50E97A#第04集$id_MOE5022B489EF1D540E50E97D#第05集$id_MOE5022B489EF1D540E50E97C#第06集$id_MOE5022B489EF1D540E50E97F#第07集$id_MOE5022B489EF1D540E50E97E#第08集$id_MOE5022B489EF1D540E50E971#第09集$id_MOE5022B489EF1D540E50E970#第10集$id_MOE5022B489EF1D540E50E879#第11集$id_MOE5022B489EF1D540E50E878#第12集$id_MOE5022B489EF1D540E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (171, 1, 0, 0, '魔法师的爱徒 / 魔法使的新娘 第二季', '', 'mofashideaitumofashidexinniangdierji', 1, 'M', '', '7a0603fe', '漫画改,奇幻,治愈,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/2ad22a11139324a20540802677f72fb7c0fecf34.png', '', '', '', '种崎敦美 / 竹内良太 / 内山昂辉 / 远藤绫 / 田村睦心 / 日野聪 / 西山宏太朗 / 上田丽奈 / 小林大纪 / 山下诚一郎 / 河濑茉希 / 津田美波', '寺泽和晃', '', '', '哪怕还不是全部，但智世终于开始接受艾利亚斯，接受自己。\r\n卡达飞尔斯陷入暂时的睡眠，智世总算回归日常生活。\r\n就在这时，她收到了魔术师互助组织“学院”发来的邀请函。\r\n在大英图书馆的地下，前所未见的魔术师们', '全24集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 43, 0, 43, 43, '', 0, 0, 9.7, 0, 0, 1732536639, 1728119072, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>哪怕还不是全部，但智世终于开始接受艾利亚斯，接受自己。\n卡达飞尔斯陷入暂时的睡眠，智世总算回归日常生活。\n就在这时，她收到了魔术师互助组织“学院”发来的邀请函。\n在大英图书馆的地下，前所未见的魔术师们的社会。\n与“人们”的相遇和交往，逐渐推开新的门扉。\n这是为了拯救我（你）而生的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0676BC8EB91A0B5C50E978#第02集$MOE0676BC8EB91A0B5C50E97B#第03集$MOE0676BC8EB91A0B5C50E97A#第04集$MOE0676BC8EB91A0B5C50E97D#第05集$MOE0676BC8EB91A0B5C50E97C#第06集$MOE0676BC8EB91A0B5C50E97F#第07集$MOE0676BC8EB91A0B5C50E97E#第08集$MOE0676BC8EB91A0B5C50E971#第09集$MOE0676BC8EB91A0B5C50E970#第10集$MOE0676BC8EB91A0B5C50E879#第11集$MOE0676BC8EB91A0B5C50E878#第12集$MOE0676BC8EB91A0B5C50E87B#第13集$MOE0676BC8EB91A0B5C50E87A#第14集$MOE0676BC8EB91A0B5C50E87D#第15集$MOE0676BC8EB91A0B5C50E87C#第16集$MOE0676BC8EB91A0B5C50E87F#第17集$MOE0676BC8EB91A0B5C50E87E#第18集$MOE0676BC8EB91A0B5C50E871#第19集$MOE0676BC8EB91A0B5C50E870#第20集$MOE0676BC8EB91A0B5C50EB79#第21集$MOE0676BC8EB91A0B5C50EB78#第22集$MOE0676BC8EB91A0B5C50EB7B#第23集$MOE0676BC8EB91A0B5C50EB7A#第24集$MOE0676BC8EB91A0B5C50EB7D$$$第01集$id_XS0676BC8EB91A0B5C50E978#第02集$id_XS0676BC8EB91A0B5C50E97B#第03集$id_XS0676BC8EB91A0B5C50E97A#第04集$id_XS0676BC8EB91A0B5C50E97D#第05集$id_XS0676BC8EB91A0B5C50E97C#第06集$id_XS0676BC8EB91A0B5C50E97F#第07集$id_XS0676BC8EB91A0B5C50E97E#第08集$id_XS0676BC8EB91A0B5C50E971#第09集$id_XS0676BC8EB91A0B5C50E970#第10集$id_XS0676BC8EB91A0B5C50E879#第11集$id_XS0676BC8EB91A0B5C50E878#第12集$id_XS0676