INSERT INTO `mac_vod` VALUES (172, 1, 0, 0, '不知情的转学生硬要凑上来。', '', 'buzhiqingdezhuanxueshengyingyaocoushanglai', 1, 'B', '', 'ecf9b537', '漫画改,校园,恋爱,日常', 'https://i0.hdslb.com/bfs/bangumi/image/fe17ba639140deb31fb082ab6af9690906e03847.png', '', '', NULL, '西村茜：小原好美\n高田太阳：石上静香\n日野大地：河西健吾\n安达海美：近藤玲奈\n笠原菫：丸冈和佳奈\n北川虎太郎：天崎滉平\n高田雪子：种崎敦美\n茜的父亲：福山润', '影山楙伦', '', '', '转学生高田不明白。\n为什么同班的西村，会被班上的其他人叫成“死神”。\n“死神”这种叫法……\n真是好帅气的绰号啊！\n被取笑的女生。窃笑的同班同学。\n作为一个转学生，这个班级里发生过什么，高田完全不知情。', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 1, 25, 25, '', 0, 0, 9.8, 0, 0, 1728119255, 1728119225, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '转学生高田不明白。\n为什么同班的西村，会被班上的其他人叫成“死神”。\n“死神”这种叫法……\n真是好帅气的绰号啊！\n被取笑的女生。窃笑的同班同学。\n作为一个转学生，这个班级里发生过什么，高田完全不知情。\n无知的直率，是最强的。\n所以，他的心意能清楚明白地被她所了解。\n这样一个从小学教室开始的故事，能让所有人都清楚明白地回忆起当年。', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS5474EA81EB1C5E0E50E978#第02集$id_XS5474EA81EB1C5E0E50E97B#第03集$id_XS5474EA81EB1C5E0E50E97A#第04集$id_XS5474EA81EB1C5E0E50E97D#第05集$id_XS5474EA81EB1C5E0E50E97C#第06集$id_XS5474EA81EB1C5E0E50E97F#第07集$id_XS5474EA81EB1C5E0E50E97E#第08集$id_XS5474EA81EB1C5E0E50E971#第09集$id_XS5474EA81EB1C5E0E50E970#第10集$id_XS5474EA81EB1C5E0E50E879#第11集$id_XS5474EA81EB1C5E0E50E878#第12集$id_XS5474EA81EB1C5E0E50E87B#第13集$id_XS5474EA81EB1C5E0E50E87A$$$第01集$id_MOE5474EA81EB1C5E0E50E978#第02集$id_MOE5474EA81EB1C5E0E50E97B#第03集$id_MOE5474EA81EB1C5E0E50E97A#第04集$id_MOE5474EA81EB1C5E0E50E97D#第05集$id_MOE5474EA81EB1C5E0E50E97C#第06集$id_MOE5474EA81EB1C5E0E50E97F#第07集$id_MOE5474EA81EB1C5E0E50E97E#第08集$id_MOE5474EA81EB1C5E0E50E971#第09集$id_MOE5474EA81EB1C5E0E50E970#第10集$id_MOE5474EA81EB1C5E0E50E879#第11集$id_MOE5474EA81EB1C5E0E50E878#第12集$id_MOE5474EA81EB1C5E0E50E87B#第13集$id_MOE5474EA81EB1C5E0E50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (957, 1, 0, 0, '熊熊勇闯异世界 PUNCH!', 'くまクマ熊ベアーぱーんち！（2023）', 'xiongxiongyongchuangyishijiePUNCH', 1, 'X', '', '72f9d48e', '异世界,奇幻,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2889609993.jpg', '', '', '', '河濑茉希 / 和气杏未 / 日高里菜 / 富田美忧 / 天野聪美 / 水濑祈 / 游佐浩二 / 鹤冈聪 / 黑濑裕子 / 宫岛惠美 / 巽悠衣子 / 木野日菜', '信田祐', '', '', '　　因为一次意外，家里蹲玩家少女优奈被自称神明之手送到异世界。要说在她身上发生了什么——', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 6.0, 0, 0, 1738093083, 1728119658, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>因为一次意外，家里蹲玩家少女优奈被自称神明之手送到异世界。要说在她身上发生了什么——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0625EA81ED1D555C50E978#第02集$MOE0625EA81ED1D555C50E97B#第03集$MOE0625EA81ED1D555C50E97A#第04集$MOE0625EA81ED1D555C50E97D#第05集$MOE0625EA81ED1D555C50E97C#第06集$MOE0625EA81ED1D555C50E97F#第07集$MOE0625EA81ED1D555C50E97E#第08集$MOE0625EA81ED1D555C50E971#第09集$MOE0625EA81ED1D555C50E970#第10集$MOE0625EA81ED1D555C50E879#第11集$MOE0625EA81ED1D555C50E878#第12集$MOE0625EA81ED1D555C50E87B$$$第01集$id_XS0625EA81ED1D555C50E978#第02集$id_XS0625EA81ED1D555C50E97B#第03集$id_XS0625EA81ED1D555C50E97A#第04集$id_XS0625EA81ED1D555C50E97D#第05集$id_XS0625EA81ED1D555C50E97C#第06集$id_XS0625EA81ED1D555C50E97F#第07集$id_XS0625EA81ED1D555C50E97E#第08集$id_XS0625EA81ED1D555C50E971#第09集$id_XS0625EA81ED1D555C50E970#第10集$id_XS0625EA81ED1D555C50E879#第11集$id_XS0625EA81ED1D555C50E878#第12集$id_XS0625EA81ED1D555C50E87B$$$第01集$id_MOE0625EA81ED1D555C50E978#第02集$id_MOE0625EA81ED1D555C50E97B#第03集$id_MOE0625EA81ED1D555C50E97A#第04集$id_MOE0625EA81ED1D555C50E97D#第05集$id_MOE0625EA81ED1D555C50E97C#第06集$id_MOE0625EA81ED1D555C50E97F#第07集$id_MOE0625EA81ED1D555C50E97E#第08集$id_MOE0625EA81ED1D555C50E971#第09集$id_MOE0625EA81ED1D555C50E970#第10集$id_MOE0625EA81ED1D555C50E879#第11集$id_MOE0625EA81ED1D555C50E878#第12集$id_MOE0625EA81ED1D555C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (174, 1, 0, 0, '天国大魔境', '天国大魔境', 'tianguodamojing', 1, 'T', '', '6a02cf68', '科幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2882121656.jpg', '', '', '', '天崎滉平,水内清光,及川以造,相马康一,真堂圭,新祐树,松冈美里,黑泽朋世,武内骏辅,福圆美里,丰永利行,山村响,千本木彩花,佐藤元', '筱原准,森山悠二郎,仲野良,齐藤秀二,増田惇人,阿部将光,柴田海,五十岚海,滨田将太,小村方宏治,大塚隆史,野村和也,森大贵', '', '', '　　该剧由漫画鬼才石黑正数亲自打造，贵留子与小丸踏上寻找“天国”的旅程，极力避开专门猎杀人类的怪物。时男舍弃井井有条的生活，勇闯外面的世界。', '全13集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 8.6, 0, 0, 1728119973, 1728119861, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　该剧由漫画鬼才石黑正数亲自打造，贵留子与小丸踏上寻找“天国”的旅程，极力避开专门猎杀人类的怪物。时男舍弃井井有条的生活，勇闯外面的世界。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0776BC8AEA4F5B0150E978#第02集$id_XS0776BC8AEA4F5B0150E97B#第03集$id_XS0776BC8AEA4F5B0150E97A#第04集$id_XS0776BC8AEA4F5B0150E97D#第05集$id_XS0776BC8AEA4F5B0150E97C#第06集$id_XS0776BC8AEA4F5B0150E97F#第07集$id_XS0776BC8AEA4F5B0150E97E#第08集$id_XS0776BC8AEA4F5B0150E971#第09集$id_XS0776BC8AEA4F5B0150E970#第10集$id_XS0776BC8AEA4F5B0150E879#第11集$id_XS0776BC8AEA4F5B0150E878#第12集$id_XS0776BC8AEA4F5B0150E87B#第13集$id_XS0776BC8AEA4F5B0150E87A$$$第01集$id_MOE0776BC8AEA4F5B0150E978#第02集$id_MOE0776BC8AEA4F5B0150E97B#第03集$id_MOE0776BC8AEA4F5B0150E97A#第04集$id_MOE0776BC8AEA4F5B0150E97D#第05集$id_MOE0776BC8AEA4F5B0150E97C#第06集$id_MOE0776BC8AEA4F5B0150E97F#第07集$id_MOE0776BC8AEA4F5B0150E97E#第08集$id_MOE0776BC8AEA4F5B0150E971#第09集$id_MOE0776BC8AEA4F5B0150E970#第10集$id_MOE0776BC8AEA4F5B0150E879#第11集$id_MOE0776BC8AEA4F5B0150E878#第12集$id_MOE0776BC8AEA4F5B0150E87B#第13集$id_MOE0776BC8AEA4F5B0150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (175, 1, 0, 0, '我的百合乃工作是也', '私の百合はお仕事です！', 'wodebaihenaigongzuoshiye', 1, 'W', '', '47010adc', '恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2885535679.jpg', '', '', '', '伊藤静,濑户麻沙美,田村由香里,小市真琴,田中美海,上坂堇,小仓唯', '鸟羽聪,深濑重,嵯峨敏,池田重隆,间岛崇宽,池端隆史,三瓶圣', '', '', '　　《#我的百合乃工作是也#》是未幡创作在日本一讯社出版的以描述女性之间复杂情感的题材为主的漫画。近日，该漫画宣布TV动画化~', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 6.6, 0, 0, 1728120326, 1728120271, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　《#我的百合乃工作是也#》是未幡创作在日本一讯社出版的以描述女性之间复杂情感的题材为主的漫画。近日，该漫画宣布TV动画化~<br/>　　《#我的百合乃工作是也#》首次在2017年一月连载于《comic百合姬》第48期，并且持续连载。在中国，本漫画被以《#百合是我的工作！#》的译名于东立出版社出版。<br/>　　【简介】<br/>　　这是发生在一家以“上演美丽优雅的女子校园生活”为主题的主题咖啡厅中的故事。白木阳芽，一个在平时生活中就擅长利用自己美貌和演技来获得他人好感的一个女子高中生，因为意外被该咖啡厅店长御子柴舞骗入咖啡厅中上班。由此，一场围绕各个角色的是“真实情感”和“表演情感”争端误解开始爆发。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0520BC89B948095A50E978#第02集$id_XS0520BC89B948095A50E97B#第03集$id_XS0520BC89B948095A50E97A#第04集$id_XS0520BC89B948095A50E97D#第05集$id_XS0520BC89B948095A50E97C#第06集$id_XS0520BC89B948095A50E97F#第07集$id_XS0520BC89B948095A50E97E#第08集$id_XS0520BC89B948095A50E971#第09集$id_XS0520BC89B948095A50E970#第10集$id_XS0520BC89B948095A50E879#第11集$id_XS0520BC89B948095A50E878#第12集$id_XS0520BC89B948095A50E87B$$$第01集$id_MOE0520BC89B948095A50E978#第02集$id_MOE0520BC89B948095A50E97B#第03集$id_MOE0520BC89B948095A50E97A#第04集$id_MOE0520BC89B948095A50E97D#第05集$id_MOE0520BC89B948095A50E97C#第06集$id_MOE0520BC89B948095A50E97F#第07集$id_MOE0520BC89B948095A50E97E#第08集$id_MOE0520BC89B948095A50E971#第09集$id_MOE0520BC89B948095A50E970#第10集$id_MOE0520BC89B948095A50E879#第11集$id_MOE0520BC89B948095A50E878#第12集$id_MOE0520BC89B948095A50E87B', '', '', '', '', 0, '', '');
