INSERT INTO `mac_vod` VALUES (184, 1, 0, 0, '我家的英雄', 'マイホームヒーロー', 'wojiadeyingxiong', 1, 'W', '', 'ab6693b7', '推理', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2886828752.jpg', '', '', '', '江越彬纪,町田启太,酒卷光宏,德石胜大,山寺宏一,大塚明夫,大久保瑠美,三木真一郎,伊东健人,大原沙耶香,诹访部顺一', '龟井隆', '', '', '　　疼爱独生女零花的微不足道上班族‧鸟栖哲雄，某天因为工作关系和开始一个人生活的零花相约见面，却发现她脸上有被殴打的痕迹。在回家的路上，哲雄看见了像是犯人的男人，并尾随在其後。隔天偷偷回到女儿的公寓，', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 7.1, 0, 0, 1728259801, 1728259743, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　疼爱独生女零花的微不足道上班族‧鸟栖哲雄，某天因为工作关系和开始一个人生活的零花相约见面，却发现她脸上有被殴打的痕迹。在回家的路上，哲雄看见了像是犯人的男人，并尾随在其後。隔天偷偷回到女儿的公寓，结果却发生了使整个家庭的命运为之一变的事件。父亲为了女儿、为了家庭，走上了修罗之道。高潮迭起的悬疑故事开幕。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5075BA8EB01A0F0E50E978#第02集$id_XS5075BA8EB01A0F0E50E97B#第03集$id_XS5075BA8EB01A0F0E50E97A#第04集$id_XS5075BA8EB01A0F0E50E97D#第05集$id_XS5075BA8EB01A0F0E50E97C#第06集$id_XS5075BA8EB01A0F0E50E97F#第07集$id_XS5075BA8EB01A0F0E50E97E#第08集$id_XS5075BA8EB01A0F0E50E971#第09集$id_XS5075BA8EB01A0F0E50E970#第10集$id_XS5075BA8EB01A0F0E50E879#第11集$id_XS5075BA8EB01A0F0E50E878#第12集$id_XS5075BA8EB01A0F0E50E87B$$$第01集$id_MOE5075BA8EB01A0F0E50E978#第02集$id_MOE5075BA8EB01A0F0E50E97B#第03集$id_MOE5075BA8EB01A0F0E50E97A#第04集$id_MOE5075BA8EB01A0F0E50E97D#第05集$id_MOE5075BA8EB01A0F0E50E97C#第06集$id_MOE5075BA8EB01A0F0E50E97F#第07集$id_MOE5075BA8EB01A0F0E50E97E#第08集$id_MOE5075BA8EB01A0F0E50E971#第09集$id_MOE5075BA8EB01A0F0E50E970#第10集$id_MOE5075BA8EB01A0F0E50E879#第11集$id_MOE5075BA8EB01A0F0E50E878#第12集$id_MOE5075BA8EB01A0F0E50E87B', '', '', '', '', 0, '', '');
