INSERT INTO `mac_vod` VALUES (194, 1, 0, 0, '妖幻三重奏', 'あやかしトライアングル（2023）', 'yaohuansanzhongzou', 1, 'Y', '', '3bf1f234', '校园,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2885308590.jpg', '', '', '', '千叶翔也 / 富田美忧 / 市之濑加那 / 玄田哲章 / 户松遥 / 木野日菜 / 石毛翔弥 / 新井里美', '秋田谷典昭 / 马引圭', '', '', '风卷祭里是一名退魔忍，在斩妖除魔时却被妖王「白金」变成了女生！变成女生之后，他跟自己的青梅竹马花奏铃之间的关系，也开始产生了微妙的变化。另一方面，由于花奏铃身上有着特殊的妖力，导致许多妖怪都想要接近她', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 6.4, 0, 0, 1729276021, 1729275919, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>风卷祭里是一名退魔忍，在斩妖除魔时却被妖王「白金」变成了女生！变成女生之后，他跟自己的青梅竹马花奏铃之间的关系，也开始产生了微妙的变化。另一方面，由于花奏铃身上有着特殊的妖力，导致许多妖怪都想要接近她。祭里不仅要以女生的身份重新习惯学校与日常生活，还必须在这种状况下保护小铃，同时寻找让自己变回男生的方法……！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0275EA89EF1B5E0D50E978#第02集$id_XS0275EA89EF1B5E0D50E97B#第03集$id_XS0275EA89EF1B5E0D50E97A#第04集$id_XS0275EA89EF1B5E0D50E97D#第05集$id_XS0275EA89EF1B5E0D50E97C#第06集$id_XS0275EA89EF1B5E0D50E97F#第07集$id_XS0275EA89EF1B5E0D50E97E#第08集$id_XS0275EA89EF1B5E0D50E971#第09集$id_XS0275EA89EF1B5E0D50E970#第10集$id_XS0275EA89EF1B5E0D50E879#第11集$id_XS0275EA89EF1B5E0D50E878#第12集$id_XS0275EA89EF1B5E0D50E87B$$$第01集$id_MOE0275EA89EF1B5E0D50E978#第02集$id_MOE0275EA89EF1B5E0D50E97B#第03集$id_MOE0275EA89EF1B5E0D50E97A#第04集$id_MOE0275EA89EF1B5E0D50E97D#第05集$id_MOE0275EA89EF1B5E0D50E97C#第06集$id_MOE0275EA89EF1B5E0D50E97F#第07集$id_MOE0275EA89EF1B5E0D50E97E#第08集$id_MOE0275EA89EF1B5E0D50E971#第09集$id_MOE0275EA89EF1B5E0D50E970#第10集$id_MOE0275EA89EF1B5E0D50E879#第11集$id_MOE0275EA89EF1B5E0D50E878#第12集$id_MOE0275EA89EF1B5E0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (202, 1, 0, 0, '阿鲁斯的巨兽', '', 'alusidejushou', 1, 'A', '', '122d821b', '原创,奇幻', 'https://i0.hdslb.com/bfs/bangumi/image/3c32c3821ba2a06f1412b210fd58fa6c055713c3.png', '', '', NULL, '库米：羊宫妃那\n吉洛：森川智之\n喵娅：芹泽优\n梅兰：峰田大梦\n萝玛娜：日笠阳子', '小黑晃', '', '', '伟大的神明创造大地。当大地成熟，凡人夺取了它。巨兽为之暴怒，吞噬凡人。为了对抗巨兽，凡人求助于神明。这是剑的时代，英雄的时代，神话的时代。 “巨兽”在世界上大肆破坏，而凡人狩猎巨兽，加以解剖并利用，以', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.5, 0, 0, 1729403842, 1729403822, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '伟大的神明创造大地。当大地成熟，凡人夺取了它。巨兽为之暴怒，吞噬凡人。为了对抗巨兽，凡人求助于神明。这是剑的时代，英雄的时代，神话的时代。 “巨兽”在世界上大肆破坏，而凡人狩猎巨兽，加以解剖并利用，以此繁荣兴盛。“没死成的吉洛”靠狩猎巨兽赚钱度日，他偶然遇见了被追捕的 “第22号的库米”。为了救她，吉洛抛下往日的哀伤挺身而出。人类帝国的谋划，神秘的实验，进逼的巨兽。向着那约定的时刻，吉洛一行人开始追寻世界的秘密——', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0025BEDCB11B5C5B50E978#第02集$id_XS0025BEDCB11B5C5B50E97B#第03集$id_XS0025BEDCB11B5C5B50E97A#第04集$id_XS0025BEDCB11B5C5B50E97D#第05集$id_XS0025BEDCB11B5C5B50E97C#第06集$id_XS0025BEDCB11B5C5B50E97F#第07集$id_XS0025BEDCB11B5C5B50E97E#第08集$id_XS0025BEDCB11B5C5B50E971#第09集$id_XS0025BEDCB11B5C5B50E970#第10集$id_XS0025BEDCB11B5C5B50E879#第11集$id_XS0025BEDCB11B5C5B50E878#第12集$id_XS0025BEDCB11B5C5B50E87B$$$第01集$id_MOE0025BEDCB11B5C5B50E978#第02集$id_MOE0025BEDCB11B5C5B50E97B#第03集$id_MOE0025BEDCB11B5C5B50E97A#第04集$id_MOE0025BEDCB11B5C5B50E97D#第05集$id_MOE0025BEDCB11B5C5B50E97C#第06集$id_MOE0025BEDCB11B5C5B50E97F#第07集$id_MOE0025BEDCB11B5C5B50E97E#第08集$id_MOE0025BEDCB11B5C5B50E971#第09集$id_MOE0025BEDCB11B5C5B50E970#第10集$id_MOE0025BEDCB11B5C5B50E879#第11集$id_MOE0025BEDCB11B5C5B50E878#第12集$id_MOE0025BEDCB11B5C5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (457, 1, 0, 0, '不要欺负我，长瀞同学 第二季', 'イジらないで、長瀞さん 2nd Attack（2023）', 'buyaoqifuwochangjingtongxuedierji', 1, 'B', '', '8a55a26', '校园,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2882403838.jpg', '', '', '', '上坂堇 / 山下大辉 / 小松未可子 / 铃木爱奈 / 井泽诗织 / 水树奈奈 / 南条爱乃 / 铃代纱弓 / 前田佳织里', '后信治', '', '', '“被学妹弄哭了！”某天放学后，在偶然路过的图书室里，被超级“抖S”的学妹盯上了！欺负前辈、对前辈发难，吵闹的她的名字是——“长瀞同学”！可恨却又可爱。让人痛苦却又让人想要靠近。这是让人心中觉醒些什么的', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 40, 0, 40, 40, '', 0, 0, 8.3, 0, 0, 1732656991, 1729276142, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“被学妹弄哭了！”某天放学后，在偶然路过的图书室里，被超级“抖S”的学妹盯上了！欺负前辈、对前辈发难，吵闹的她的名字是——“长瀞同学”！可恨却又可爱。让人痛苦却又让人想要靠近。这是让人心中觉醒些什么的“S娇少女”的故事。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0976B98DE81B5B144DE8#第02集$MOE0976B98DE81B5B144DEB#第03集$MOE0976B98DE81B5B144DEA#第04集$MOE0976B98DE81B5B144DED#第05集$MOE0976B98DE81B5B144DEC#第06集$MOE0976B98DE81B5B144DEF#第07集$MOE0976B98DE81B5B144DEE#第08集$MOE0976B98DE81B5B144DE1#第09集$MOE0976B98DE81B5B144DE0#第10集$MOE0976B98DE81B5B144CE9#第11集$MOE0976B98DE81B5B144CE8#第12集$MOE0976B98DE81B5B144CEB$$$第01集$id_XS0976B98DE81B5B144DE8#第02集$id_XS0976B98DE81B5B144DEB#第03集$id_XS0976B98DE81B5B144DEA#第04集$id_XS0976B98DE81B5B144DED#第05集$id_XS0976B98DE81B5B144DEC#第06集$id_XS0976B98DE81B5B144DEF#第07集$id_XS0976B98DE81B5B144DEE#第08集$id_XS0976B98DE81B5B144DE1#第09集$id_XS0976B98DE81B5B144DE0#第10集$id_XS0976B98DE81B5B144CE9#第11集$id_XS0976B98DE81B5B144CE8#第12集$id_XS0976B98DE81B5B144CEB$$$第01集$id_MOE0976B98DE81B5B144DE8#第02集$id_MOE0976B98DE81B5B144DEB#第03集$id_MOE0976B98DE81B5B144DEA#第04集$id_MOE0976B98DE81B5B144DED#第05集$id_MOE0976B98DE81B5B144DEC#第06集$id_MOE0976B98DE81B5B144DEF#第07集$id_MOE0976B98DE81B5B144DEE#第08集$id_MOE0976B98DE81B5B144DE1#第09集$id_MOE0976B98DE81B5B144DE0#第10集$id_MOE0976B98DE81B5B144CE9#第11集$id_MOE0976B98DE81B5B144CE8#第12集$id_MOE0976B98DE81B5B144CEB', '', '', '', '', 0, '', '');
