INSERT INTO `mac_vod` VALUES (209, 1, 0, 0, '久保同学不放过我', '', 'jiubaotongxuebufangguowo', 1, 'J', '', 'b853f3aa', '漫画改,日常,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/image/58ba200c4205e00cf662800f942d547270dc1f91.png', '', '', NULL, '久保渚咲：花泽香菜\n白石纯太：河西健吾\n久保明菜：伊藤美来\n久保沙贵：雨宫天\n工藤叶月：加隈亚衣\n平玉绪：竹达彩奈', '古贺一臣', '', '', '高中一年级的白石纯太， 是一个零存在感的“路人”男生。\n同班的“女主角级”美少女·久保同学居然是唯一能找到他的人，并且总是戏弄他。\n无法成为特别存在的“路人”男生，和出现在他面前的“女主角”女生。\n在', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 112, 0, 112, 112, '', 0, 0, 9.5, 0, 0, 1729486671, 1729407216, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '高中一年级的白石纯太， 是一个零存在感的“路人”男生。\n同班的“女主角级”美少女·久保同学居然是唯一能找到他的人，并且总是戏弄他。\n无法成为特别存在的“路人”男生，和出现在他面前的“女主角”女生。\n在教室的一角，青春的色彩开始逐渐丰富——。\n无论是谁，都可以成为某个人“特别”的存在。但是这份感情对尚且稚嫩的两人来说，还不能被称为“爱”。\n距离“恋爱喜剧”两步之遥，女主角女生×路人男生的青春期甜蜜喜剧拉开序幕。', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS532FB98BEF1A0C5850E978#第02集$id_XS532FB98BEF1A0C5850E97B#第03集$id_XS532FB98BEF1A0C5850E97A#第04集$id_XS532FB98BEF1A0C5850E97D#第05集$id_XS532FB98BEF1A0C5850E97C#第06集$id_XS532FB98BEF1A0C5850E97F#第07集$id_XS532FB98BEF1A0C5850E97E#第08集$id_XS532FB98BEF1A0C5850E971#第09集$id_XS532FB98BEF1A0C5850E970#第10集$id_XS532FB98BEF1A0C5850E879#第11集$id_XS532FB98BEF1A0C5850E878#第12集$id_XS532FB98BEF1A0C5850E87B$$$第01集$id_MOE532FB98BEF1A0C5850E978#第02集$id_MOE532FB98BEF1A0C5850E97B#第03集$id_MOE532FB98BEF1A0C5850E97A#第04集$id_MOE532FB98BEF1A0C5850E97D#第05集$id_MOE532FB98BEF1A0C5850E97C#第06集$id_MOE532FB98BEF1A0C5850E97F#第07集$id_MOE532FB98BEF1A0C5850E97E#第08集$id_MOE532FB98BEF1A0C5850E971#第09集$id_MOE532FB98BEF1A0C5850E970#第10集$id_MOE532FB98BEF1A0C5850E879#第11集$id_MOE532FB98BEF1A0C5850E878#第12集$id_MOE532FB98BEF1A0C5850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (210, 1, 0, 0, '被众神捡到的男孩 第二季', '神達に拾われた男 2期（2023）', 'beizhongshenjiandaodenanhaidierji', 1, 'B', '', '90c24443', '奇幻,冒险', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2880415111.jpg', '', '', '', '田所梓 / 桑原由气 / 小野大辅 / 早见沙织 / 子安武人 / 高野麻里佳 / 桧山修之 / 江口拓也 / 石田彰 / 沼仓爱美 / 下野纮 / 铃村健一 / 平川大辅 / 榎木淳弥', '柳濑雄之', '', '', '#被神捡到的男人#第二期制作决定。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 62, 0, 62, 62, '', 0, 0, 5.0, 0, 0, 1732720277, 1729407290, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>#被神捡到的男人#第二期制作决定。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0827EF8ABD1D590A50E978#第02集$MOE0827EF8ABD1D590A50E97B#第03集$MOE0827EF8ABD1D590A50E97A#第04集$MOE0827EF8ABD1D590A50E97D#第05集$MOE0827EF8ABD1D590A50E97C#第06集$MOE0827EF8ABD1D590A50E97F#第07集$MOE0827EF8ABD1D590A50E97E#第08集$MOE0827EF8ABD1D590A50E971#第09集$MOE0827EF8ABD1D590A50E970#第10集$MOE0827EF8ABD1D590A50E879#第11集$MOE0827EF8ABD1D590A50E878#第12集$MOE0827EF8ABD1D590A50E87B$$$第01集$id_XS0827EF8ABD1D590A50E978#第02集$id_XS0827EF8ABD1D590A50E97B#第03集$id_XS0827EF8ABD1D590A50E97A#第04集$id_XS0827EF8ABD1D590A50E97D#第05集$id_XS0827EF8ABD1D590A50E97C#第06集$id_XS0827EF8ABD1D590A50E97F#第07集$id_XS0827EF8ABD1D590A50E97E#第08集$id_XS0827EF8ABD1D590A50E971#第09集$id_XS0827EF8ABD1D590A50E970#第10集$id_XS0827EF8ABD1D590A50E879#第11集$id_XS0827EF8ABD1D590A50E878#第12集$id_XS0827EF8ABD1D590A50E87B$$$第01集$id_MOE0827EF8ABD1D590A50E978#第02集$id_MOE0827EF8ABD1D590A50E97B#第03集$id_MOE0827EF8ABD1D590A50E97A#第04集$id_MOE0827EF8ABD1D590A50E97D#第05集$id_MOE0827EF8ABD1D590A50E97C#第06集$id_MOE0827EF8ABD1D590A50E97F#第07集$id_MOE0827EF8ABD1D590A50E97E#第08集$id_MOE0827EF8ABD1D590A50E971#第09集$id_MOE0827EF8ABD1D590A50E970#第10集$id_MOE0827EF8ABD1D590A50E879#第11集$id_MOE0827EF8ABD1D590A50E878#第12集$id_MOE0827EF8ABD1D590A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (211, 1, 0, 0, 'Love Live！虹咲学园学园偶像同好会 四格漫', 'にじよん あにめーしょん（2023）', 'LoveLivehongxiaoxueyuanxueyuanouxiangtonghaohuisigeman', 1, 'L', '', '4668fb26', '校园,泡面', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2880713141.jpg', '', '', '', '矢野妃菜喜 / 大西亚玖璃 / 相良茉优 / 鬼头明里 / 村上奈津实 / 久保田未梦 / 楠木灯 / 指出毬亚 / 田中千惠美 / 前田佳织里 / 小泉萌香 / 内田秀 / 法元明菜', '堀内勇冶', '', '', '東京・お台場にある高校、虹ヶ咲学園を舞台に、', '全15集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 8.7, 0, 0, 1729407715, 1729407553, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>東京・お台場にある高校、虹ヶ咲学園を舞台に、</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0521BA80EF4B5F0F50E978#第02集$id_XS0521BA80EF4B5F0F50E97B#第03集$id_XS0521BA80EF4B5F0F50E97A#第04集$id_XS0521BA80EF4B5F0F50E97D#第05集$id_XS0521BA80EF4B5F0F50E97C#第06集$id_XS0521BA80EF4B5F0F50E97F#第07集$id_XS0521BA80EF4B5F0F50E97E#第08集$id_XS0521BA80EF4B5F0F50E971#第09集$id_XS0521BA80EF4B5F0F50E970#第10集$id_XS0521BA80EF4B5F0F50E879#第11集$id_XS0521BA80EF4B5F0F50E878#第12集$id_XS0521BA80EF4B5F0F50E87B#第13集$id_XS0521BA80EF4B5F0F50E87A#第14集$id_XS0521BA80EF4B5F0F50E87D#第15集$id_XS0521BA80EF4B5F0F50E87C$$$第01集$id_MOE0521BA80EF4B5F0F50E978#第02集$id_MOE0521BA80EF4B5F0F50E97B#第03集$id_MOE0521BA80EF4B5F0F50E97A#第04集$id_MOE0521BA80EF4B5F0F50E97D#第05集$id_MOE0521BA80EF4B5F0F50E97C#第06集$id_MOE0521BA80EF4B5F0F50E97F#第07集$id_MOE0521BA80EF4B5F0F50E97E#第08集$id_MOE0521BA80EF4B5F0F50E971#第09集$id_MOE0521BA80EF4B5F0F50E970#第10集$id_MOE0521BA80EF4B5F0F50E879#第11集$id_MOE0521BA80EF4B5F0F50E878#第12集$id_MOE0521BA80EF4B5F0F50E87B#第13集$id_MOE0521BA80EF4B5F0F50E87A#第14集$id_MOE0521BA80EF4B5F0F50E87D#第15集$id_MOE0521BA80EF4B5F0F50E87C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (212, 1, 0, 0, '被解雇的暗黑士兵慢生活的第二人生', '', 'beijiegudeanheishibingmanshenghuodedierrensheng', 1, 'B', '', '66564206', '漫画改,热血,奇幻,战斗', 'https://i0.hdslb.com/bfs/bangumi/image/c8cec0e4a963e48387ecf26dda4c100a16d03861.png', '', '', NULL, '玛丽卡：藤田茜\n达里艾尔：杉田智和\n巴修巴扎：阿部敦\n加西塔：柿原徹也\n泽碧安提斯：大久保瑠美\n蕾蒂：鬼頭明里\n多萝伊：中原麻衣\n贝泽利亚：鹤冈聪\n利泽特：立花慎之介\n恩比尔：滨田贤二\n艾莉卡：渡部惠子\n史密斯：岩崎博', '追崎史敏', '', '', '作为暗黑士兵被培养长大的达里艾尔，虽然很有能力但不会使用魔法。新上司嫉妒达里艾尔的能力，以他不会魔法为借口解雇了他。达里艾尔在归途上偶遇了一名少女，并在她的带领下来到了一个人类村落。在村庄里学习冒险者', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 8.6, 0, 0, 1729407778, 1729407765, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '作为暗黑士兵被培养长大的达里艾尔，虽然很有能力但不会使用魔法。新上司嫉妒达里艾尔的能力，以他不会魔法为借口解雇了他。达里艾尔在归途上偶遇了一名少女，并在她的带领下来到了一个人类村落。在村庄里学习冒险者的技能后，他飞速地变强了……以达里艾尔为中心，魔族、怪物、人类交织成了这个闹剧动作故事和喜剧幻想篇章。', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS0721B98EBD1B5D0F50E978#第02集$id_XS0721B98EBD1B5D0F50E97B#第03集$id_XS0721B98EBD1B5D0F50E97A#第04集$id_XS0721B98EBD1B5D0F50E97D#第05集$id_XS0721B98EBD1B5D0F50E97C#第06集$id_XS0721B98EBD1B5D0F50E97F#第07集$id_XS0721B98EBD1B5D0F50E97E#第08集$id_XS0721B98EBD1B5D0F50E971#第09集$id_XS0721B98EBD1B5D0F50E970#第10集$id_XS0721B98EBD1B5D0F50E879#第11集$id_XS0721B98EBD1B5D0F50E878#第12集$id_XS0721B98EBD1B5D0F50E87B$$$第01集$id_MOE0721B98EBD1B5D0F50E978#第02集$id_MOE0721B98EBD1B5D0F50E97B#第03集$id_MOE0721B98EBD1B5D0F50E97A#第04集$id_MOE0721B98EBD1B5D0F50E97D#第05集$id_MOE0721B98EBD1B5D0F50E97C#第06集$id_MOE0721B98EBD1B5D0F50E97F#第07集$id_MOE0721B98EBD1B5D0F50E97E#第08集$id_MOE0721B98EBD1B5D0F50E971#第09集$id_MOE0721B98EBD1B5D0F50E970#第10集$id_MOE0721B98EBD1B5D0F50E879#第11集$id_MOE0721B98EBD1B5D0F50E878#第12集$id_MOE0721B98EBD1B5D0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (213, 1, 0, 0, '冰属性男子和酷酷女同事', '', 'bingshuxingnanzihekukunvtongshi', 1, 'B', '', 'd48a77d2', '漫画改,少女,乙女,职场', 'https://i0.hdslb.com/bfs/bangumi/image/c04dbc614e5e17318e5f7176fd13b7fdd13b50a2.png', '', '', NULL, '冬月：石川由依\n冰室：小林千晃\n狐森：内山夕实\n冴岛：内山昂辉\n音无：佐仓绫音\n火鸟：仲村宗悟\n雪泯：新田日和', 'Mankyu', '', '', '在这个职场里，纯白色的爱恋如雪般飞舞——。\n生活在现代的雪女后裔冰室是个一旦情绪高涨就会引发暴风雪、造出雪人或者雪洞的新上班族。\n他偷偷喜欢着略显独特而又温柔体贴的同事冬月。这份爱慕之情偶尔也会失控，', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 9.6, 0, 0, 1729407933, 1729407918, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '在这个职场里，纯白色的爱恋如雪般飞舞——。\n生活在现代的雪女后裔冰室是个一旦情绪高涨就会引发暴风雪、造出雪人或者雪洞的新上班族。\n他偷偷喜欢着略显独特而又温柔体贴的同事冬月。这份爱慕之情偶尔也会失控，导致四周变为冰天雪地。\n然而，众人眼里总是酷酷的冬月其实也对神秘的冰室十分感兴趣。\n随着每一天的工作和公司的活动，他们的关系逐渐发生变化，私下里也会一起共度时间。然而对恋爱十分笨拙的二人却迟迟无法进一步发展关系……\n由表面酷酷的二人谱写的，温暖人心的“工作系幻想爱情喜剧”即将开幕！', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS5523B4D9BE1E090B50E978#第02集$id_XS5523B4D9BE1E090B50E97B#第03集$id_XS5523B4D9BE1E090B50E97A#第04集$id_XS5523B4D9BE1E090B50E97D#第05集$id_XS5523B4D9BE1E090B50E97C#第06集$id_XS5523B4D9BE1E090B50E97F#第07集$id_XS5523B4D9BE1E090B50E97E#第08集$id_XS5523B4D9BE1E090B50E971#第09集$id_XS5523B4D9BE1E090B50E970#第10集$id_XS5523B4D9BE1E090B50E879#第11集$id_XS5523B4D9BE1E090B50E878#第12集$id_XS5523B4D9BE1E090B50E87B$$$第01集$id_MOE5523B4D9BE1E090B50E978#第02集$id_MOE5523B4D9BE1E090B50E97B#第03集$id_MOE5523B4D9BE1E090B50E97A#第04集$id_MOE5523B4D9BE1E090B50E97D#第05集$id_MOE5523B4D9BE1E090B50E97C#第06集$id_MOE5523B4D9BE1E090B50E97F#第07集$id_MOE5523B4D9BE1E090B50E97E#第08集$id_MOE5523B4D9BE1E090B50E971#第09集$id_MOE5523B4D9BE1E090B50E970#第10集$id_MOE5523B4D9BE1E090B50E879#第11集$id_MOE5523B4D9BE1E090B50E878#第12集$id_MOE5523B4D9BE1E090B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (214, 1, 0, 0, '邻家的天使同学', '', 'linjiadetianshitongxue', 1, 'L', '', 'cbef33dd', '小说改,日常,校园,治愈', 'https://i0.hdslb.com/bfs/bangumi/image/50f011dc86acb0f89bfb38384f9383a68a06bd78.png', '', '', NULL, '藤宫周：坂泰斗\n椎名真昼：石见舞菜香\n赤泽树：八代拓\n白河千岁：白石晴香', '王丽花', '', '', '高一学生藤宫周在升学后开始了他的独居生活。\n他所在的公寓隔壁，住着他们学校第一的美少女——椎名真昼。\n他们二人平时几乎没有交集。而一次大雨中，周把伞借给了浑身湿透的真昼。自此，二人便开始了奇妙的交流。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 149, 0, 149, 149, '', 0, 0, 6.8, 0, 0, 1729408020, 1729408005, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '高一学生藤宫周在升学后开始了他的独居生活。\n他所在的公寓隔壁，住着他们学校第一的美少女——椎名真昼。\n他们二人平时几乎没有交集。而一次大雨中，周把伞借给了浑身湿透的真昼。自此，二人便开始了奇妙的交流。\n周的懒散独居生活让真昼实在看不下去。她便开始为他做饭，打扫卫生，照顾他的起居。\n互为邻居的二人渐渐地开始对彼此有所了解。\n这是一个与可爱邻居之间的甜蜜又让人心急的恋爱故事——', 'xs$$$moe', '$$$', '$$$', '第01集$id_XS5275E9DEBA1A095D50E978#第02集$id_XS5275E9DEBA1A095D50E97B#第03集$id_XS5275E9DEBA1A095D50E97A#第04集$id_XS5275E9DEBA1A095D50E97D#第05集$id_XS5275E9DEBA1A095D50E97C#第06集$id_XS5275E9DEBA1A095D50E97F#第07集$id_XS5275E9DEBA1A095D50E97E#第08集$id_XS5275E9DEBA1A095D50E971#第09集$id_XS5275E9DEBA1A095D50E970#第10集$id_XS5275E9DEBA1A095D50E879#第11集$id_XS5275E9DEBA1A095D50E878#第12集$id_XS5275E9DEBA1A095D50E87B$$$第01集$id_MOE5275E9DEBA1A095D50E978#第02集$id_MOE5275E9DEBA1A095D50E97B#第03集$id_MOE5275E9DEBA1A095D50E97A#第04集$id_MOE5275E9DEBA1A095D50E97D#第05集$id_MOE5275E9DEBA1A095D50E97C#第06集$id_MOE5275E9DEBA1A095D50E97F#第07集$id_MOE5275E9DEBA1A095D50E97E#第08集$id_MOE5275E9DEBA1A095D50E971#第09集$id_MOE5275E9DEBA1A095D50E970#第10集$id_MOE5275E9DEBA1A095D50E879#第11集$id_MOE5275E9DEBA1A095D50E878#第12集$id_MOE5275E9DEBA1A095D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (215, 1, 0, 0, '万事屋斋藤到异世界', '便利屋斎藤さん、異世界に行く（2023）', 'wanshiwuzhaitengdaoyishijie', 1, 'W', '', 'a327da73', '异世界,奇幻,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2886210148.jpg', '', '', '', '木村良平 / 东山奈央 / 菲鲁兹·蓝 / 长岛雄一 / 大桥彩香 / 相马康一 / 花守由美里 / 田所阳向 / 青木瑠璃子 / 田所梓', '洼冈俊之', '', '', '一直都过得很平凡，不管是运动还是读书都差强人意，绝对无法成为第一名的普通人——斋藤，被召唤到了异世界。 即使在异世界，斋藤也绝非是特别的，一点都不强。但在与超有个性的伙伴一起挑战攻略迷宫的过程中，告诉', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 8.0, 0, 0, 1729408225, 1729408135, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>一直都过得很平凡，不管是运动还是读书都差强人意，绝对无法成为第一名的普通人——斋藤，被召唤到了异世界。 即使在异世界，斋藤也绝非是特别的，一点都不强。但在与超有个性的伙伴一起挑战攻略迷宫的过程中，告诉严重健忘的魔法师咒语、用身体当盾来保护小妖精、将针对敌人的合适武器拿给战士，他逐渐成为了队伍当中不可或缺的存在。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5024BE8FED485A0A50E978#第02集$id_XS5024BE8FED485A0A50E97B#第03集$id_XS5024BE8FED485A0A50E97A#第04集$id_XS5024BE8FED485A0A50E97D#第05集$id_XS5024BE8FED485A0A50E97C#第06集$id_XS5024BE8FED485A0A50E97F#第07集$id_XS5024BE8FED485A0A50E97E#第08集$id_XS5024BE8FED485A0A50E971#第09集$id_XS5024BE8FED485A0A50E970#第10集$id_XS5024BE8FED485A0A50E879#第11集$id_XS5024BE8FED485A0A50E878#第12集$id_XS5024BE8FED485A0A50E87B$$$第01集$id_MOE5024BE8FED485A0A50E978#第02集$id_MOE5024BE8FED485A0A50E97B#第03集$id_MOE5024BE8FED485A0A50E97A#第04集$id_MOE5024BE8FED485A0A50E97D#第05集$id_MOE5024BE8FED485A0A50E97C#第06集$id_MOE5024BE8FED485A0A50E97F#第07集$id_MOE5024BE8FED485A0A50E97E#第08集$id_MOE5024BE8FED485A0A50E971#第09集$id_MOE5024BE8FED485A0A50E970#第10集$id_MOE5024BE8FED485A0A50E879#第11集$id_MOE5024BE8FED485A0A50E878#第12集$id_MOE5024BE8FED485A0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (216, 1, 0, 0, '间谍教室', 'スパイ教室（2023）', 'jiandiejiaoshi', 1, 'J', '', '30a454e8', '校园,推理', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2876189129.jpg', '', '', '', '猪爪慎一 / 兵头一步 / 木村畅 / 川口敬一郎 / 竹町 主演	雨宫天 / 梅原裕一郎 / 伊藤美来 / 东山奈央 / 悠木碧 / 上坂堇 / 佐仓绫音 / 楠木灯 / 水濑祈', '川口敬一郎 / 池端隆史 / 后藤康德 / 藤井隆文 / 高田淳 / 佐佐木达也', '', '', '世界最强的间谍，世界最高的骗局！', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 5.5, 0, 0, 1729408789, 1729408651, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>世界最强的间谍，世界最高的骗局！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0227ED8CBC1D080150E978#第02集$id_XS0227ED8CBC1D080150E97B#第03集$id_XS0227ED8CBC1D080150E97A#第04集$id_XS0227ED8CBC1D080150E97D#第05集$id_XS0227ED8CBC1D080150E97C#第06集$id_XS0227ED8CBC1D080150E97F#第07集$id_XS0227ED8CBC1D080150E97E#第08集$id_XS0227ED8CBC1D080150E971#第09集$id_XS0227ED8CBC1D080150E970#第10集$id_XS0227ED8CBC1D080150E879#第11集$id_XS0227ED8CBC1D080150E878#第12集$id_XS0227ED8CBC1D080150E87B$$$第01集$id_MOE0227ED8CBC1D080150E978#第02集$id_MOE0227ED8CBC1D080150E97B#第03集$id_MOE0227ED8CBC1D080150E97A#第04集$id_MOE0227ED8CBC1D080150E97D#第05集$id_MOE0227ED8CBC1D080150E97C#第06集$id_MOE0227ED8CBC1D080150E97F#第07集$id_MOE0227ED8CBC1D080150E97E#第08集$id_MOE0227ED8CBC1D080150E971#第09集$id_MOE0227ED8CBC1D080150E970#第10集$id_MOE0227ED8CBC1D080150E879#第11集$id_MOE0227ED8CBC1D080150E878#第12集$id_MOE0227ED8CBC1D080150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (217, 1, 0, 0, '狩火之王', '火狩りの王（2023）', 'shouhuozhiwang', 1, 'S', '', '1ba27ab9', '奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2884854056.jpg', '', '', '', '久野美咲 / 坂本真绫 / 石毛翔弥 / 细谷佳正 / 早见沙织 / 山口爱 / 国立幸 / 小林千晃 / 小市真琴 / 三宅健太 / 名冢佳织 / 宫野真守 / 原优子 / 三木真一郎 / 宫本侑芽 / 真木骏一 / 上田耀司 / 绵贯龙之介 / 岛村侑 / 大原沙耶香 / 石田彰 / 榊原良子', '西村纯二', '', '', '人类最终战争后的世界，大地被黑森林所覆盖，人类只能在被结界守护着的少许土地上生存。被病原体入侵的人类只要靠近天然的火身体就会燃烧，而唯一能够安全使用的火只能通过狩猎栖息在黑森林深处的黑色怪兽“炎魔”采', '全10集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 6.9, 0, 0, 1730220010, 1730219860, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>人类最终战争后的世界，大地被黑森林所覆盖，人类只能在被结界守护着的少许土地上生存。被病原体入侵的人类只要靠近天然的火身体就会燃烧，而唯一能够安全使用的火只能通过狩猎栖息在黑森林深处的黑色怪兽“炎魔”采集。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0075ED8ABE480F0050E978#第02集$id_XS0075ED8ABE480F0050E97B#第03集$id_XS0075ED8ABE480F0050E97A#第04集$id_XS0075ED8ABE480F0050E97D#第05集$id_XS0075ED8ABE480F0050E97C#第06集$id_XS0075ED8ABE480F0050E97F#第07集$id_XS0075ED8ABE480F0050E97E#第08集$id_XS0075ED8ABE480F0050E971#第09集$id_XS0075ED8ABE480F0050E970#第10集$id_XS0075ED8ABE480F0050E879#$$$第01集$id_MOE0075ED8ABE480F0050E978#第02集$id_MOE0075ED8ABE480F0050E97B#第03集$id_MOE0075ED8ABE480F0050E97A#第04集$id_MOE0075ED8ABE480F0050E97D#第05集$id_MOE0075ED8ABE480F0050E97C#第06集$id_MOE0075ED8ABE480F0050E97F#第07集$id_MOE0075ED8ABE480F0050E97E#第08集$id_MOE0075ED8ABE480F0050E971#第09集$id_MOE0075ED8ABE480F0050E970#第10集$id_MOE0075ED8ABE480F0050E879', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (218, 1, 0, 0, '期待在地下城邂逅有错吗 Ⅳ 深章 灾厄篇', 'ダンジョンに出会いを求めるのは間違っているだろうかⅣ', 'qidaizaidixiachengxiehouyoucuomashenzhangzaiepian', 1, 'Q', '', 'cdbd246d', '奇幻,冒险', 'https://p2.bahamut.com.tw/B/ACG/c/81/0000115681.JPG', '', '', '', '', '橘秀樹', '', '', '迷宫都市欧拉丽─这是拥有通称『地下城』的地下壮阔迷宫的巨大都市。在这个城市里，一名弱小的女神和立志成为冒险者的少年，他们结识了许多伙伴、挑战地下城，并度过了多次的绝境，贝尔再次获得了升级。于此同时，赫', '全22集', '', 0, '', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 0.0, 0, 0, 1730227343, 1730221288, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>迷宫都市欧拉丽─这是拥有通称『地下城』的地下壮阔迷宫的巨大都市。在这个城市里，一名弱小的女神和立志成为冒险者的少年，他们结识了许多伙伴、挑战地下城，并度过了多次的绝境，贝尔再次获得了升级。于此同时，赫斯缇雅眷族眷族收到了一封通知。上面所写的是要求眷族前往地下城未到达楼层的远征任务。面对未知的冒险，少年和同伴们一同踏出了崭新的一步。</p><p>这是少年所经历，女神将其记载的眷族神话（Familiar Myth）。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5273EEDCBB1D5B5D50E978#第02集$id_XS5273EEDCBB1D5B5D50E97B#第03集$id_XS5273EEDCBB1D5B5D50E97A#第04集$id_XS5273EEDCBB1D5B5D50E97D#第05集$id_XS5273EEDCBB1D5B5D50E97C#第06集$id_XS5273EEDCBB1D5B5D50E97F#第07集$id_XS5273EEDCBB1D5B5D50E97E#第08集$id_XS5273EEDCBB1D5B5D50E971#第09集$id_XS5273EEDCBB1D5B5D50E970#第10集$id_XS5273EEDCBB1D5B5D50E879#第11集$id_XS5273EEDCBB1D5B5D50E878#第12集$id_XS5273EEDCBB1D5B5D50E87B#第13集$id_XS5273EEDCBB1D5B5D50E87A#第14集$id_XS5273EEDCBB1D5B5D50E87D#第15集$id_XS5273EEDCBB1D5B5D50E87C#第16集$id_XS5273EEDCBB1D5B5D50E87F#第17集$id_XS5273EEDCBB1D5B5D50E87E#第18集$id_XS5273EEDCBB1D5B5D50E871#第19集$id_XS5273EEDCBB1D5B5D50E870#第20集$id_XS5273EEDCBB1D5B5D50EB79#第21集$id_XS5273EEDCBB1D5B5D50EB78#第22集$id_XS5273EEDCBB1D5B5D50EB7B$$$第01集$id_MOE5273EEDCBB1D5B5D50E978#第02集$id_MOE5273EEDCBB1D5B5D50E97B#第03集$id_MOE5273EEDCBB1D5B5D50E97A#第04集$id_MOE5273EEDCBB1D5B5D50E97D#第05集$id_MOE5273EEDCBB1D5B5D50E97C#第06集$id_MOE5273EEDCBB1D5B5D50E97F#第07集$id_MOE5273EEDCBB1D5B5D50E97E#第08集$id_MOE5273EEDCBB1D5B5D50E971#第09集$id_MOE5273EEDCBB1D5B5D50E970#第10集$id_MOE5273EEDCBB1D5B5D50E879#第11集$id_MOE5273EEDCBB1D5B5D50E878#第12集$id_MOE5273EEDCBB1D5B5D50E87B#第13集$id_MOE5273EEDCBB1D5B5D50E8