INSERT INTO `mac_vod` VALUES (235, 1, 0, 0, '金属口红/METALLIC ROUGE', '', 'jinshukouhongMETALLICROUGE', 1, 'J', '', '26ad65e9', '原创,科幻,机战,战斗', 'https://i0.hdslb.com/bfs/bangumi/image/9b038e096c409153d3124e64544ef8f6ec60262a.png', '', '', NULL, '露朱·赤星：宫本侑芽\n娜奥米·奥斯曼：黑泽朋世\n吉因·荣格哈特：武内骏辅\n莎拉·菲茨杰拉德：岛村侑\n姜隆·菲特：吉野裕行\n吉尔·斯特金：小仓唯\n阿夫达尔·巴沙尔：津田健次郎\n伊甸·瓦罗克：兴津和兴\n亚修·斯塔尔：宫内敦士\n诺伊德262：小林千晃', '堀元宣', '', '', '由bones×出渊裕带来的最新战斗动作片，人造人们为命运而战，让人惊奇的黑色科幻作品！\n《交响诗篇》的动画制作公司bones，\n在《机动警察》中负责机械设计、在《宇宙战舰大和号2199》中负责总导演的', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 6.9, 0, 0, 1730549181, 1730549081, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '由bones×出渊裕带来的最新战斗动作片，人造人们为命运而战，让人惊奇的黑色科幻作品！\n《交响诗篇》的动画制作公司bones，\n在《机动警察》中负责机械设计、在《宇宙战舰大和号2199》中负责总导演的出渊裕，\n自《翼神传说》之后，时隔19年再次合作！\n\n导演是负责过《CAROLE \\u0026 TUESDAY》、《超级骗子》等作品的堀元宣，\n角色设计则是负责过《宇宙牛仔》、《幻界战线》等作品的川元利浩，\n集中最豪华的阵容，打造最壮丽的黑色科幻作品。\n\n这是一个人与人造人混居的世界——\n人造人少女露朱，和搭档娜奥米一起，\n在火星执行某个任务。\n任务内容是“杀死与政府敌对的9个人造人”。\n人造人少女露朱的战斗故事就此展开——', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0321EDDCBF1C080050E978#第02集$MOE0321EDDCBF1C080050E97B#第03集$MOE0321EDDCBF1C080050E97A#第04集$MOE0321EDDCBF1C080050E97D#第05集$MOE0321EDDCBF1C080050E97C#第06集$MOE0321EDDCBF1C080050E97F#第07集$MOE0321EDDCBF1C080050E97E#第08集$MOE0321EDDCBF1C080050E971#第09集$MOE0321EDDCBF1C080050E970#第10集$MOE0321EDDCBF1C080050E879#第11集$MOE0321EDDCBF1C080050E878#第12集$MOE0321EDDCBF1C080050E87B#第13集$MOE0321EDDCBF1C080050E87A$$$第01集$id_XS0321EDDCBF1C080050E978#第02集$id_XS0321EDDCBF1C080050E97B#第03集$id_XS0321EDDCBF1C080050E97A#第04集$id_XS0321EDDCBF1C080050E97D#第05集$id_XS0321EDDCBF1C080050E97C#第06集$id_XS0321EDDCBF1C080050E97F#第07集$id_XS0321EDDCBF1C080050E97E#第08集$id_XS0321EDDCBF1C080050E971#第09集$id_XS0321EDDCBF1C080050E970#第10集$id_XS0321EDDCBF1C080050E879#第11集$id_XS0321EDDCBF1C080050E878#第12集$id_XS0321EDDCBF1C080050E87B#第13集$id_XS0321EDDCBF1C080050E87A$$$第01集$id_MOE0321EDDCBF1C080050E978#第02集$id_MOE0321EDDCBF1C080050E97B#第03集$id_MOE0321EDDC