INSERT INTO `mac_vod` VALUES (241, 1, 0, 0, '佐佐木与文鸟小哔', '佐々木とピーちゃん（2024）', 'zuozuomuyuwenniaoxiaobi', 1, 'Z', '', 'beaa9778', '异世界,奇幻,魔法,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2900780497.jpg', '', '', '', '杉田智和 / 悠木碧 / 鬼头明里 / 高桥李依 / 富田美忧 / 水濑祈 / 置鲇龙太郎 / 大空直美 / 安元洋贵 / 福山润 / 浪川大辅 / 岩田光央 / 玄田哲章 / 绿川光 / 梶原岳人 / 岸尾大辅', '凑未来', '', '', '年近四十、有些不起眼的普通公司员工（社畜）佐佐木因为受到养了宠物的同事的影响，决心也要养宠物，意外地在宠物店与文鸟小哔相遇并购买了它。可实际上小哔其实是异世界的贤者转生而来，并拥有人类沟通的特殊能力。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 5.8, 0, 0, 1730561910, 1730561834, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>年近四十、有些不起眼的普通公司员工（社畜）佐佐木因为受到养了宠物的同事的影响，决心也要养宠物，意外地在宠物店与文鸟小哔相遇并购买了它。可实际上小哔其实是异世界的贤者转生而来，并拥有人类沟通的特殊能力。就这样，佐佐木与小哔开始了往返异世界与现实世界的新故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5372EDD9B01E5A0150E978#第02集$MOE5372EDD9B01E5A0150E97B#第03集$MOE5372EDD9B01E5A0150E97A#第04集$MOE5372EDD9B01E5A0150E97D#第05集$MOE5372EDD9B01E5A0150E97C#第06集$MOE5372EDD9B01E5A0150E97F#第07集$MOE5372EDD9B01E5A0150E97E#第08集$MOE5372EDD9B01E5A0150E971#第09集$MOE5372EDD9B01E5A0150E970#第10集$MOE5372EDD9B01E5A0150E879#第11集$MOE5372EDD9B01E5A0150E878#第12集$MOE5372EDD9B01E5A0150E87B$$$第01集$id_XS5372EDD9B01E5A0150E978#第02集$id_XS5372EDD9B01E5A0150E97B#第03集$id_XS5372EDD9B01E5A0150E97A#第04集$id_XS5372EDD9B01E5A0150E97D#第05集$id_XS5372EDD9B01E5A0150E97C#第06集$id_XS5372EDD9B01E5A0150E97F#第07集$id_XS5372EDD9B01E5A0150E97E#第08集$id_XS5372EDD9B01E5A0150E971#第09集$id_XS5372EDD9B01E5A0150E970#第10集$id_XS5372EDD9B01E5A0150E879#第11集$id_XS5372EDD9B01E5A0150E878#第12集$id_XS5372EDD9B01E5A0150E87B$$$第01集$id_MOE5372EDD9B01E5A0150E978#第02集$id_MOE5372EDD9B01E5A0150E97B#第03集$id_MOE5372EDD9B01E5A0150E97A#第04集$id_MOE5372EDD9B01E5A0150E97D#第05集$id_MOE5372EDD9B01E5A0150E97C#第06集$id_MOE5372EDD9B01E5A0150E97F#第07集$id_MOE5372EDD9B01E5A0150E97E#第08集$id_MOE5372EDD9B01E5A0150E971#第09集$id_MOE5372EDD9B01E5A0150E970#第10集$id_MOE5372EDD9B01E5A0150E879#第11集$id_MOE5372EDD9B01E5A0150E878#