INSERT INTO `mac_vod` VALUES (472, 1, 0, 0, '弱势角色友崎君 第二季', '弱キャラ友崎くん 2nd STAGE（2024）', 'ruoshijiaoseyouqijundierji', 1, 'R', '', '8ddc2461', '校园,恋爱,青春', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2900020787.jpg', '', '', '', '佐藤元 / 金元寿子 / 长谷川育美 / 茅野爱衣 / 前川凉子 / 稗田宁宁 / 水野骏太郎 / 岛崎信长 / 冈本信彦', '柳伸亮', '', '', '在游戏界赫赫有名，本人却把自己归类在「人生的弱角」的高二生友崎文也，被完美女生兼同班同学日南葵得知真实身份后，决定教导友崎「人生的游戏规则」……', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 39, 0, 39, 39, '', 0, 0, 6.6, 0, 0, 1730562126, 1730562040, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在游戏界赫赫有名，本人却把自己归类在「人生的弱角」的高二生友崎文也，被完美女生兼同班同学日南葵得知真实身份后，决定教导友崎「人生的游戏规则」……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0973E8DBBB1D5B0850E978#第02集$MOE0973E8DBBB1D5B0850E97B#第03集$MOE0973E8DBBB1D5B0850E97A#第04集$MOE0973E8DBBB1D5B0850E97D#第05集$MOE0973E8DBBB1D5B0850E97C#第06集$MOE0973E8DBBB1D5B0850E97F#第07集$MOE0973E8DBBB1D5B0850E97E#第08集$MOE0973E8DBBB1D5B0850E971#第09集$MOE0973E8DBBB1D5B0850E970#第10集$MOE0973E8DBBB1D5B0850E879#第11集$MOE0973E8DBBB1D5B0850E878#第12集$MOE0973E8DBBB1D5B0850E87B#第13集$MOE0973E8DBBB1D5B0850E87A$$$第01集$id_XS0973E8DBBB1D5B0850E978#第02集$id_XS0973E8DBBB1D5B0850E97B#第03集$id_XS0973E8DBBB1D5B0850E97A#第04集$id_XS0973E8DBBB1D5B0850E97D#第05集$id_XS0973E8DBBB1D5B0850E97C#第06集$id_XS0973E8DBBB1D5B0850E97F#第07集$id_XS0973E8DBBB1D5B0850E97E#第08集$id_XS0973E8DBBB1D5B0850E971#第09集$id_XS0973E8DBBB1D5B0850E970#第10集$id_XS0973E8DBBB1D5B0850E879#第11集$id_XS0973E8DBBB1D5B0850E878#第12集$id_XS0973E8DBBB1D5B0850E87B#第13集$id_XS0973E8DBBB1D5B0850E87A$$$第01集$id_MOE0973E8DBBB1D5B0850E978#第02集$id_MOE0973E8DBBB1D5B0850E97B#第03集$id_MOE0973E8DBBB1D5B0850E97A#第04集$id_MOE0973E8DBBB1D5B0850E97D#第05集$id_MOE0973E8DBBB1D5B0850E97C#第06集$id_MOE0973E8DBBB1D5B0850E97F#第07集$id_MOE0973E8DBBB1D5B0850E97E#第08集$id_MOE0973E8DBBB1D5B0850E971#第09集$id_MOE0973E8DBBB1D5B0850E970#第10集$id_MOE0973E8DBBB1D5B0850E879#第11集$id_MOE0973E8DBBB1D5B0850E878#第12集$id_MOE0973E8DBBB1D5B0850E87B#第13集$id_MOE0973E8DBB