INSERT INTO `mac_vod` VALUES (243, 1, 0, 0, '事与愿违的不死冒险者', '', 'shiyuyuanweidebusimaoxianzhe', 1, 'S', '', 'c41dc8fa', '小说改,魔法,冒险', 'https://i0.hdslb.com/bfs/bangumi/image/0b20292f556c2dd0c39c65398302d4bf4aa63f5e.png', '', '', NULL, '雷特·费纳：铃木崚汰\n罗琳·维维耶：小松未可子\n希拉·伊伯斯：长谷川育美\n莉娜·卢贝齐：铃代纱弓', '秋田谷典昭', '', '', '“我一定……要成为神银级冒险者。”\n抱着这样的决心，雷特成为冒险者已经十年。他踏实地磨练剑技、积累知识、为冒险者公会做着贡献，却依旧还是铜级低阶。\n即便如此，他还是坚持每天下迷宫，不懈努力着。\n有一天', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 28, 0, 28, 28, '', 0, 0, 9.4, 0, 0, 1730562270, 1730562242, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '“我一定……要成为神银级冒险者。”\n抱着这样的决心，雷特成为冒险者已经十年。他踏实地磨练剑技、积累知识、为冒险者公会做着贡献，却依旧还是铜级低阶。\n即便如此，他还是坚持每天下迷宫，不懈努力着。\n有一天，他发现了低阶迷宫“水月迷宫”的未探明区域，却遭遇了“龙”并遭其吞食。\n雷特本以为自己的命运到此为止，却不知为何恢复了意识——以最弱的魔物：骷髅的身份。\n然而雷特依旧没有绝望，而是探索着自己所能做到的事。\n他决定首先利用魔物的特性“存在进化”升格为高阶魔物，然后寻找变回人类的道路。\n成为了不死者的雷特，再次向着神银级冒险者进发。', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5223BDDCEA110B5850E978#第02集$MOE5223BDDCEA110B5850E97B#第03集$MOE5223BDDCEA110B5850E97A#第04集$MOE5223BDDCEA110B5850E97D#第05集$MOE5223BDDCEA110B5850E97C#第06集$MOE5223BDDCEA110B5850E97F#第07集$MOE5223BDDCEA110B5850E97E#第08集$MOE5223BDDCEA110B5850E971#第09集$MOE5223BDDCEA110B5850E970#第10集$MOE5223BDDCEA110B5850E879#第11集$MOE5223BDDCEA110B5850E878#第12集$MOE5223BDDCEA110B5850E87B$$$第01集$id_XS5223BDDCEA110B5850E978#第02集$id_XS5223BDDCEA110B5850E97B#第03集$id_XS5223BDDCEA110B5850E97A#第04集$id_XS5223BDDCEA110B5850E97D#第05集$id_XS5223BDDCEA110B5850E97C#第06集$id_XS5223BDDCEA110B5850E97F#第07集$id_XS5223BDDCEA110B5850E97E#第08集$id_XS5223BDDCEA110B5850E971#第09集$id_XS5223BDDCEA110B5850E970#第10集$id_XS5223BDDCEA110B5850E879#第11集$id_XS5223BDDCEA110B5850E878#第12集$id_XS5223BDDCEA110B5850E87B$$$第01集$id_MOE5223BDDCEA110B5850E978#第02集$id_MOE5223BDDCEA110B5850E97B#第03集$id_MOE5223BDDCEA110B5850E97A#第04集$id_MOE5223BDDCEA110B5850E97D#第05集$id_MOE5223BDDCEA110B5850E97C#第06集$id_MOE5223BDDCEA110B5850E97F#第07集$id_MOE5223BDDCEA110B5850E97E#第08集$id_MOE5223BDDCEA110B5850E971#第09集$id_MOE5223BDDCEA