INSERT INTO `mac_vod` VALUES (244, 1, 0, 0, '婚戒物语', '結婚指輪物語（2024）', 'hunjiewuyu', 1, 'H', '', 'e7227e5c', '异世界,奇幻,冒险,魔法,恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2886605247.jpg', '', '', '', '佐藤元 / 鬼头明里', '直谷隆', '', '', '《婚戒物语》 [1]  是漫画组合麦比（めいびい）创作，新连载于2014年03月25日发售的月刊杂志《Big Gangan》4月刊上的漫画作品。近日宣布动画化', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 71, 0, 71, 71, '', 0, 0, 4.4, 0, 0, 1730562421, 1730562348, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《婚戒物语》 [1] &nbsp;是漫画组合麦比（めいびい）创作，新连载于2014年03月25日发售的月刊杂志《Big Gangan》4月刊上的漫画作品。近日宣布动画化</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5420BE8ABE4C585A50E978#第02集$MOE5420BE8ABE4C585A50E97B#第03集$MOE5420BE8ABE4C585A50E97A#第04集$MOE5420BE8ABE4C585A50E97D#第05集$MOE5420BE8ABE4C585A50E97C#第06集$MOE5420BE8ABE4C585A50E97F#第07集$MOE5420BE8ABE4C585A50E97E#第08集$MOE5420BE8ABE4C585A50E971#第09集$MOE5420BE8ABE4C585A50E970#第10集$MOE5420BE8ABE4C585A50E879#第11集$MOE5420BE8ABE4C585A50E878#第12集$MOE5420BE8ABE4C585A50E87B$$$第01集$id_XS5420BE8ABE4C585A50E978#第02集$id_XS5420BE8ABE4C585A50E97B#第03集$id_XS5420BE8ABE4C585A50E97A#第04集$id_XS5420BE8ABE4C585A50E97D#第05集$id_XS5420BE8ABE4C585A50E97C#第06集$id_XS5420BE8ABE4C585A50E97F#第07集$id_XS5420BE8ABE4C585A50E97E#第08集$id_XS5420BE8ABE4C585A50E971#第09集$id_XS5420BE8ABE4C585A50E970#第10集$id_XS5420BE8ABE4C585A50E879#第11集$id_XS5420BE8ABE4C585A50E878#第12集$id_XS5420BE8ABE4C585A50E87B$$$第01集$id_MOE5420BE8ABE4C585A50E978#第02集$id_MOE5420BE8ABE4C585A50E97B#第03集$id_MOE5420BE8ABE4C585A50E97A#第04集$id_MOE5420BE8ABE4C585A50E97D#第05集$id_MOE5420BE8ABE4C585A50E97C#第06集$id_MOE5420BE8ABE4C585A50E97F#第07集$id_MOE5420BE8ABE4C585A50E97E#第08集$id_MOE5420BE8ABE4C585A50E971#第09集$id_MOE5420BE8ABE4C585A50E970#第10集$id_MOE5420BE8ABE4C585A50E879#第11集$id_MOE5420BE8ABE4C585A50E878#第12集$id_MOE5420BE8ABE4C585A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (245, 1, 0, 0, '外科医生爱丽丝', '外科医エリーゼ（2024）', 'waikeyishengailisi', 1, 'W', '', '1beaf73c', '异世界,奇幻,恋爱,励志', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2901920306.jpg', '', '', '', '石川由依 / 阿座上洋平 / 细谷佳正', '羽原久美子', '', '', '她的第一世是帝国的邪恶皇后，因为嫉妒害得国破家亡，最后被皇帝烧死；', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 5.8, 0, 0, 1730562575, 1730562488, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>她的第一世是帝国的邪恶皇后，因为嫉妒害得国破家亡，最后被皇帝烧死；</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0075E9D9EF1E5E5A50E978#第02集$MOE0075E9D9EF1E5E5A50E97B#第03集$MOE0075E9D9EF1E5E5A50E97A#第04集$MOE0075E9D9EF1E5E5A50E97D#第05集$MOE0075E9D9EF1E5E5A50E97C#第06集$MOE0075E9D9EF1E5E5A50E97F#第07集$MOE0075E9D9EF1E5E5A50E97E#第08集$MOE0075E9D9EF1E5E5A50E971#第09集$MOE0075E9D9EF1E5E5A50E970#第10集$MOE0075E9D9EF1E5E5A50E879#第11集$MOE0075E9D9EF1E5E5A50E878#第12集$MOE0075E9D9EF1E5E5A50E87B$$$第01集$id_XS0075E9D9EF1E5E5A50E978#第02集$id_XS0075E9D9EF1E5E5A50E97B#第03集$id_XS0075E9D9EF1E5E5A50E97A#第04集$id_XS0075E9D9EF1E5E5A50E97D#第05集$id_XS0075E9D9EF1E5E5A50E97C#第06集$id_XS0075E9D9EF1E5E5A50E97F#第07集$id_XS0075E9D9EF1E5E5A50E97E#第08集$id_XS0075E9D9EF1E5E5A50E971#第09集$id_XS0075E9D9EF1E5E5A50E970#第10集$id_XS0075E9D9EF1E5E5A50E879#第11集$id_XS0075E9D9EF1E5E5A50E878#第12集$id_XS0075E9D9EF1E5E5A50E87B$$$第01集$id_MOE0075E9D9EF1E5E5A50E978#第02集$id_MOE0075E9D9EF1E5E5A50E97B#第03集$id_MOE0075E9D9EF1E5E5A50E97A#第04集$id_MOE0075E9D9EF1E5E5A50E97D#第05集$id_MOE0075E9D9EF1E5E5A50E97C#第06集$id_MOE0075E9D9EF1E5E5A50E97F#第07集$id_MOE0075E9D9EF1E5E5A50E97E#第08集$id_MOE0075E9D9EF1E5E5A50E971#第09集$id_MOE0075E9D9EF1E5E5A50E970#第10集$id_MOE0075E9D9EF1E5E5A50E879#第11集$id_MOE0075E9D9EF1E5E5A50E878#第12集$id_MOE0075E9D9EF1E5E5A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (454, 1, 0, 0, '欢迎来到实力至上主义的教室 第三季', 'ようこそ実力至上主義の教室へ 3期（2024）', 'huanyinglaidaoshilizhishangzhuyidejiaoshidisanji', 1, 'H', '', '44679b74', '校园,悬疑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2899855808.jpg', '', '', '', '千叶翔也 / 日高里菜 / 鬼头明里 / 久保由利香 / 竹达彩奈 / 逢坂良太 / 岩泽俊树 / 东山奈央 / 阿座上洋平 / 水中雅章 / 高桥李依 / 梅原裕一郎 / 齐藤壮马 / 市道真央 / 小松未可子 / 富田美忧 / 田中美海 / 铃代纱弓 / 石川界人 / 山下诚一郎 / 小原好美 / 佐藤利奈', '岸诚二 / 桥本裕之 / 仁昌寺义人', '', '', '东京都高度育成高中，是以升学率、就业率100%为荣，每月支付相当于10万日元金钱的梦想学校。但是，其内在是只有一部分成绩优秀者才能得到好待遇的实力至上主义学校。', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 86, 0, 86, 86, '', 0, 0, 7.3, 0, 0, 1730562727, 1730562637, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>东京都高度育成高中，是以升学率、就业率100%为荣，每月支付相当于10万日元金钱的梦想学校。但是，其内在是只有一部分成绩优秀者才能得到好待遇的实力至上主义学校。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0523BA8FB04B5A0D50E978#第02集$MOE0523BA8FB04B5A0D50E97B#第03集$MOE0523BA8FB04B5A0D50E97A#第04集$MOE0523BA8FB04B5A0D50E97D#第05集$MOE0523BA8FB04B5A0D50E97C#第06集$MOE0523BA8FB04B5A0D50E97F#第07集$MOE0523BA8FB04B5A0D50E97E#第08集$MOE0523BA8FB04B5A0D50E971#第09集$MOE0523BA8FB04B5A0D50E970#第10集$MOE0523BA8FB04B5A0D50E879#第11集$MOE0523BA8FB04B5A0D50E878#第12集$MOE0523BA8FB04B5A0D50E87B#第13集$MOE0523BA8FB04B5A0D50E87A$$$第01集$id_XS0523BA8FB04B5A0D50E978#第02集$id_XS0523BA8FB04B5A0D50E97B#第03集$id_XS0523BA8FB04B5A0D50E97A#第04集$id_XS0523BA8FB04B5A0D50E97D#第05集$id_XS0523BA8FB04B5A0D50E97C#第06集$id_XS0523BA8FB04B5A0D50E97F#第07集$id_XS0523BA8FB04B5A0D50E97E#第08集$id_XS0523BA8FB04B5A0D50E971#第09集$id_XS0523BA8FB04B5A0D50E970#第10集$id_XS0523BA8FB04B5A0D50E879#第11集$id_XS0523BA8FB04B5A0D50E878#第12集$id_XS0523BA8FB04B5A0D50E87B#第13集$id_XS0523BA8FB04B5A0D50E87A$$$第01集$id_MOE0523BA8FB04B5A0D50E978#第02集$id_MOE0523BA8FB04B5A0D50E97B#第03集$id_MOE0523BA8FB04B5A0D50E97A#第04集$id_MOE0523BA8FB04B5A0D50E97D#第05集$id_MOE0523BA8FB04B5A0D50E97C#第06集$id_MOE0523BA8FB04B5A0D50E97F#第07集$id_MOE0523BA8FB04B5A0D50E97E#第08集$id_MOE0523BA8FB04B5A0D50E971#第09集$i