INSERT INTO `mac_vod` VALUES (249, 1, 0, 0, '指尖相触，恋恋不舍', 'ゆびさきと恋々（2024）', 'zhijianxiangchulianlianbushe', 1, 'Z', '', '1ab83b87', '恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2901078687.jpg', '', '', '', '诸星堇 / 宫崎游 / 大塚刚央', '村野佑太', '', '', '这是有听觉障碍的女大学生·糸濑雪和以雪之大学的前辈在世界旅行的背包客·波岐逸臣的爱情故事。有一天，在逸臣的帮助下，雪开始了两人的交流，雪被自然接触的逸臣所吸引。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 7.7, 0, 0, 1730589156, 1730589083, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是有听觉障碍的女大学生·糸濑雪和以雪之大学的前辈在世界旅行的背包客·波岐逸臣的爱情故事。有一天，在逸臣的帮助下，雪开始了两人的交流，雪被自然接触的逸臣所吸引。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0076EE80BA4B550E50E978#第02集$MOE0076EE80BA4B550E50E97B#第03集$MOE0076EE80BA4B550E50E97A#第04集$MOE0076EE80BA4B550E50E97D#第05集$MOE0076EE80BA4B550E50E97C#第06集$MOE0076EE80BA4B550E50E97F#第07集$MOE0076EE80BA4B550E50E97E#第08集$MOE0076EE80BA4B550E50E971#第09集$MOE0076EE80BA4B550E50E970#第10集$MOE0076EE80BA4B550E50E879#第11集$MOE0076EE80BA4B550E50E878#第12集$MOE0076EE80BA4B550E50E87B$$$第01集$id_XS0076EE80BA4B550E50E978#第02集$id_XS0076EE80BA4B550E50E97B#第03集$id_XS0076EE80BA4B550E50E97A#第04集$id_XS0076EE80BA4B550E50E97D#第05集$id_XS0076EE80BA4B550E50E97C#第06集$id_XS0076EE80BA4B550E50E97F#第07集$id_XS0076EE80BA4B550E50E97E#第08集$id_XS0076EE80BA4B550E50E971#第09集$id_XS0076EE80BA4B550E50E970#第10集$id_XS0076EE80BA4B550E50E879#第11集$id_XS0076EE80BA4B550E50E878#第12集$id_XS0076EE80BA4B550E50E87B$$$第01集$id_MOE0076EE80BA4B550E50E978#第02集$id_MOE0076EE80BA4B550E50E97B#第03集$id_MOE0076EE80BA4B550E50E97A#第04集$id_MOE0076EE80BA4B550E50E97D#第05集$id_MOE0076EE80BA4B550E50E97C#第06集$id_MOE0076EE80BA4B550E50E97F#第07集$id_MOE0076EE80BA4B550E50E97E#第08集$id_MOE0076EE80BA4B550E50E971#第09集$id_MOE0076EE80BA4B550E50E970#第10集$id_MOE0076EE80BA4B550E50E879#第11集$id_MOE0076EE80BA4B550E50E878#第12集$id_MOE0076EE80BA4B550E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (250, 1, 0, 0, '迷宫饭', '', 'migongfan', 1, 'M', '', '4333cb6c', '漫画改,美食,冒险,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/8cf02211c3fefa4eccc7307ca4fab404707d0cf7.png', '', '', NULL, '莱欧斯：熊谷健太郎\n玛露西尔：千本木彩花\n齐尔查克：泊明日菜\n森西：中博史\n法琳：早见沙织\n娜玛莉：三木晶\n菊朗：川田绅司', '宫岛善博', '', '', '迷宫饭。是“吃”，还是“被吃”，这是一个问题。\n在迷宫深处，莱欧斯眼看着红龙吃掉了妹妹，自己在将死之际回到了地面。\n尽管他想要马上再次挑战迷宫，但是钱和粮食都被留在了最深处。\n面对妹妹可能会被消化掉的', '全24集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 9.8, 0, 0, 1730589481, 1730589439, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '迷宫饭。是“吃”，还是“被吃”，这是一个问题。\n在迷宫深处，莱欧斯眼看着红龙吃掉了妹妹，自己在将死之际回到了地面。\n尽管他想要马上再次挑战迷宫，但是钱和粮食都被留在了最深处。\n面对妹妹可能会被消化掉的危机，莱欧斯下定了决心。\n“食物就在迷宫中自给自足吧！”\n史莱姆，蛇尾鸡，宝箱怪，还有龙！\n吃着来袭的魔物们，打通迷宫吧，冒险者！', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0524BF8BEA4B5B5A50E978#第02集$MOE0524BF8BEA4B5B5A50E97B#第03集$MOE0524BF8BEA4B5B5A50E97A#第04集$MOE0524BF8BEA4B5B5A50E97D#第05集$MOE0524BF8BEA4B5B5A50E97C#第06集$MOE0524BF8BEA4B5B5A50E97F#第07集$MOE0524BF8BEA4B5B5A50E97E#第08集$MOE0524BF8BEA4B5B5A50E971#第09集$MOE0524BF8BEA4B5B5A50E970#第10集$MOE0524BF8BEA4B5B5A50E879#第11集$MOE0524BF8BEA4B5B5A50E878#第12集$MOE0524BF8BEA4B5B5A50E87B#第13集$MOE0524BF8BEA4B5B5A50E87A#第14集$MOE0524BF8BEA4B5B5A50E87D#第15集$MOE0524BF8BEA4B5B5A50E87C#第16集$MOE0524BF8BEA4B5B5A50E87F#第17集$MOE0524BF8BEA4B5B5A50E87E#第18集$MOE0524BF8BEA4B5B5A50E871#第19集$MOE0524BF8BEA4B5B5A50E870#第20集$MOE0524BF8BEA4B5B5A50EB79#第21集$MOE0524BF8BEA4B5B5A50EB78#第22集$MOE0524BF8BEA4B5B5A50EB7B#第23集$MOE0524BF8BEA4B5B5A50EB7A#第24集$MOE0524BF8BEA4B5B5A50EB7D$$$第01集$id_XS0524BF8BEA4B5B5A50E978#第02集$id_XS0524BF8BEA4B5B5A50E97B#第03集$id_XS0524BF8BEA4B5B5A50E97A#第04集$id_XS0524BF8BEA4B5B5A50E97D#第05集$id_XS0524BF8BEA4B5B5A50E97C#第06集$id_XS0524BF8BEA4B5B5A50E97F#第07集$id_XS0524BF8BEA4B5B5A50E97E#第08集$id_XS0524BF8BEA4B5B5A50E971#第09集$id_XS0524BF8BEA4B5B5A50E970#第10集$id_XS0524BF8BEA4B5B5A50E879#第11集$id_XS0524BF8BEA4B5B5A50E878#第12集$id_XS0524BF8BEA4B5B5A50E87B#第13集$id_XS0524BF8BEA4B5B5A50E87A