INSERT INTO `mac_vod` VALUES (261, 1, 0, 0, '公主大人，接下来是“拷问”时间', '姫様“拷問”の時間です（2024）', 'gongzhudarenjiexialaishikaowenshijian', 1, 'G', '', '60565a7a', '科幻,温馨,美食', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2894042644.jpg', '', '', '', '白石晴香 / 小林亲弘 / 伊藤静 / 玄田哲章', '金森阳子', '', '', '在国王军与魔王军交战的数月后，身为国王的女儿兼国王军第三骑士团“骑士团团长”的公主沦为了魔王军的阶下囚！等待公主的是出人意料的重重拷问——！？史上最残酷的拷问时间正式拉开了序幕！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 7.3, 0, 0, 1730591480, 1730591407, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在国王军与魔王军交战的数月后，身为国王的女儿兼国王军第三骑士团“骑士团团长”的公主沦为了魔王军的阶下囚！等待公主的是出人意料的重重拷问——！？史上最残酷的拷问时间正式拉开了序幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0727B98EBC485A5850E978#第02集$MOE0727B98EBC485A5850E97B#第03集$MOE0727B98EBC485A5850E97A#第04集$MOE0727B98EBC485A5850E97D#第05集$MOE0727B98EBC485A5850E97C#第06集$MOE0727B98EBC485A5850E97F#第07集$MOE0727B98EBC485A5850E97E#第08集$MOE0727B98EBC485A5850E971#第09集$MOE0727B98EBC485A5850E970#第10集$MOE0727B98EBC485A5850E879#第11集$MOE0727B98EBC485A5850E878#第12集$MOE0727B98EBC485A5850E87B$$$第01集$id_XS0727B98EBC485A5850E978#第02集$id_XS0727B98EBC485A5850E97B#第03集$id_XS0727B98EBC485A5850E97A#第04集$id_XS0727B98EBC485A5850E97D#第05集$id_XS0727B98EBC485A5850E97C#第06集$id_XS0727B98EBC485A5850E97F#第07集$id_XS0727B98EBC485A5850E97E#第08集$id_XS0727B98EBC485A5850E971#第09集$id_XS0727B98EBC485A5850E970#第10集$id_XS0727B98EBC485A5850E879#第11集$id_XS0727B98EBC485A5850E878#第12集$id_XS0727B98EBC485A5850E87B$$$第01集$id_MOE0727B98EBC485A5850E978#第02集$id_MOE0727B98EBC485A5850E97B#第03集$id_MOE0727B98EBC485A5850E97A#第04集$id_MOE0727B98EBC485A5850E97D#第05集$id_MOE0727B98EBC485A5850E97C#第06集$id_MOE0727B98EBC485A5850E97F#第07集$id_MOE0727B98EBC485A5850E97E#第08集$id_MOE0727B98EBC485A5850E971#第09集$id_MOE0727B98EBC485A5850E970#第10集$id_MOE0727B98EBC485A5850E879#第11集$id_MOE0727B98EBC485A5850E878#第12集$id_MOE0727B98EBC485A5850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (481, 1, 0, 0, '王者天下 第五季', 'キングダム 第5シリーズ（2024）', 'wangzhetianxiadiwuji', 1, 'W', '', 'e9e26423', '历史', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2881654196.jpg', '', '', '', '森田成一 / 福山润 / 钉宫理惠 / 日笠阳子 / 赤城进 / 鸟海浩辅 / 伊藤健太郎 / 永峰遥 / 乃村健次 / 佐久间元辉 / 小西克幸 / 八代拓 / 莲岳大 / 森川智之 / 平川大辅 / 石井康嗣', '今泉贤一', '', '', '「王者天下」动画第5季制作决定 2024年1月开播！', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 9.2, 0, 0, 1732999508, 1730591846, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「王者天下」动画第5季制作决定 2024年1月开播！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE542EE98ABF1D5F0A50E978#第02集$MOE542EE98ABF1D5F0A50E97B#第03集$MOE542EE98ABF1D5F0A50E97A#第04集$MOE542EE98ABF1D5F0A50E97D#第05集$MOE542EE98ABF1D5F0A50E97C#第06集$MOE542EE98ABF1D5F0A50E97F#第07集$MOE542EE98ABF1D5F0A50E97E#第08集$MOE542EE98ABF1D5F0A50E971#第09集$MOE542EE98ABF1D5F0A50E970#第10集$MOE542EE98ABF1D5F0A50E879#第11集$MOE542EE98ABF1D5F0A50E878#第12集$MOE542EE98ABF1D5F0A50E87B#第13集$MOE542EE98ABF1D5F0A50E87A$$$第01集$id_XS542EE98ABF1D5F0A50E978#第02集$id_XS542EE98ABF1D5F0A50E97B#第03集$id_XS542EE98ABF1D5F0A50E97A#第04集$id_XS542EE98ABF1D5F0A50E97D#第05集$id_XS542EE98ABF1D5F0A50E97C#第06集$id_XS542EE98ABF1D5F0A50E97F#第07集$id_XS542EE98ABF1D5F0A50E97E#第08集$id_XS542EE98ABF1D5F0A50E971#第09集$id_XS542EE98ABF1D5F0A50E970#第10集$id_XS542EE98ABF1D5F0A50E879#第11集$id_XS542EE98ABF1D5F0A50E878#第12集$id_XS542EE98ABF1D5F0A50E87B#第13集$id_XS542EE98ABF1D5F0A50E87A$$$第01集$id_MOE542EE98ABF1D5F0A50E978#第02集$id_MOE542EE98ABF1D5F0A50E97B#第03集$id_MOE542EE98ABF1D5F0A50E97A#第04集$id_MOE542EE98ABF1D5F0A50E97D#第05集$id_MOE542EE98ABF1D5F0A50E97C#第06集$id_MOE542EE98ABF1D5F0A50E97F#第07集$id_MOE542EE98ABF1D5F0A50E97E#第08集$id_MOE542EE98ABF1D5F0A50E971#第09集$id_MOE542EE98ABF1D5F0A50E970#第10集$id_MOE542EE98ABF1D5F0A50E879#第11集$id_MOE542EE98ABF1D5F0A50E878#第12集$id_MOE542EE98ABF1D5F0A50E87B#第13集$id_MOE542EE98ABF1D5F0A50E87A', '', '', '', '', 0, '', '');
