INSERT INTO `mac_vod` VALUES (266, 1, 0, 0, '我独自升级', '', 'woduzishengji', 1, 'W', '', 'e5679eee', '漫画改,战斗,冒险,奇幻', 'https://i0.hdslb.com/bfs/bangumi/image/3a3eb31610713c19bed556fa915a2b7776d8c85d.png', '', '', NULL, '水篠旬：坂泰斗\n诸菱贤太：中村源太\n水篠葵：三川华月\n向坂雫：上田丽奈\n最上真：平川大辅\n白川大虎：东地宏树\n后藤清臣：银河万丈\n犬饲晃：古川慎', '中重俊祐', '', '', '自从连接异次元与当前世界的通道“门”突然出现后已过去十余年，\n世界上出现了被称为“猎人”的，觉醒了非凡力量的人们。\n猎人在门内攻略地下城以获取回报以维持生计，\n但在强者如云的猎人中，「水篠旬」作为被称', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 348, 1, 348, 348, '', 0, 0, 8.9, 0, 0, 1730595993, 1730595968, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '自从连接异次元与当前世界的通道“门”突然出现后已过去十余年，\n世界上出现了被称为“猎人”的，觉醒了非凡力量的人们。\n猎人在门内攻略地下城以获取回报以维持生计，\n但在强者如云的猎人中，「水篠旬」作为被称作人类最弱武器的低级猎人生活着。\n某一天，遭遇了隐藏在低级地下城中的高级双重地下城后，\n身受重伤濒临死亡的水篠旬面前出现了神秘的任务窗口。\n\n死到临头，决定接受任务的水篠旬，\n成为了唯一能够「升级」的人——', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5422BA8FB04C085C50E978#第02集$MOE5422BA8FB04C085C50E97B#第03集$MOE5422BA8FB04C085C50E97A#第04集$MOE5422BA8FB04C085C50E97D#第05集$MOE5422BA8FB04C085C50E97C#第06集$MOE5422BA8FB04C085C50E97F#第07集$MOE5422BA8FB04C085C50E97E#第08集$MOE5422BA8FB04C085C50E971#第09集$MOE5422BA8FB04C085C50E970#第10集$MOE5422BA8FB04C085C50E879#第11集$MOE5422BA8FB04C085C50E878#第12集$MOE5422BA8FB04C085C50E87B$$$第01集$id_XS5422BA8FB04C085C50E978#第02集$id_XS5422BA8FB04C085C50E97B#第03集$id_XS5422BA8FB04C085C50E97A#第04集$id_XS5422BA8FB04C085C50E97D#第05集$id_XS5422BA8FB04C085C50E97C#第06集$id_XS5422BA8FB04C085C50E97F#第07集$id_XS5422BA8FB04C085C50E97E#第08集$id_XS5422BA8FB04C085C50E971#第09集$id_XS5422BA8FB04C085C50E970#第10集$id_XS5422BA8FB04C085C50E879#第11集$id_XS5422BA8FB04C085C50E878#第12集$id_XS5422BA8FB04C085C50E87B$$$第01集$id_MOE5422BA8FB04C085C50E978#第02集$id_MOE5422BA8FB04C085C50E97B#第03集$id_MOE5422BA8FB04C085C50E97A#第04集$id_MOE5422BA8FB04C085C50E97D#第05集$id_MOE5422BA8FB04C085C50E97C#第06集$id_MOE5422BA8FB04C085C50E97F#第07集$id_MOE5422BA8FB04C085C50E97E#第08集$id_MOE5422BA8FB04C085C50E971#第09集$id_MOE5422BA8FB04C085C50E970#第10集$id_MOE5422BA8FB04C085C50E879#第