INSERT INTO `mac_vod` VALUES (275, 1, 0, 0, '地下城里的人们', '', 'dixiachengliderenmen', 1, 'D', '', 'a58adce8', '漫画改,冒险,魔法,萌系', 'https://i0.hdslb.com/bfs/bangumi/image/794fd4a5a575b0777ae408b235dfd5e4181c9adf.png', '', '', NULL, '柯蕾：千本木彩花\n贝尔：铃代纱弓\n兰加德：楠见尚己\n前代：飞田展男\n雷西林吉：大冢芳忠\n芙琳：M·A·O', '山井纱也香', '', '', '在父亲消失于安特穆尔格的地下城后，盗贼少女柯蕾追寻着他的足迹，一直在独自挑战地下城。最后，她终于来到了从未有人踏足过的地下9层。结果在和第一个魔兽战斗时，就弄塌了地下城的墙壁！而在崩塌的墙壁后出现的是', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.6, 0, 0, 1730811958, 1730811938, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '在父亲消失于安特穆尔格的地下城后，盗贼少女柯蕾追寻着他的足迹，一直在独自挑战地下城。最后，她终于来到了从未有人踏足过的地下9层。结果在和第一个魔兽战斗时，就弄塌了地下城的墙壁！而在崩塌的墙壁后出现的是……管理员？！\n这便是由地下城里的劳动者们呈现的，迷宫工作奇幻故事。', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5022B4D9ED4A080150E978#第02集$MOE5022B4D9ED4A080150E97B#第03集$MOE5022B4D9ED4A080150E97A#第04集$MOE5022B4D9ED4A080150E97D#第05集$MOE5022B4D9ED4A080150E97C#第06集$MOE5022B4D9ED4A080150E97F#第07集$MOE5022B4D9ED4A080150E97E#第08集$MOE5022B4D9ED4A080150E971#第09集$MOE5022B4D9ED4A080150E970#第10集$MOE5022B4D9ED4A080150E879#第11集$MOE5022B4D9ED4A080150E878#第12集$MOE5022B4D9ED4A080150E87B$$$第01集$id_XS5022B4D9ED4A080150E978#第02集$id_XS5022B4D9ED4A080150E97B#第03集$id_XS5022B4D9ED4A080150E97A#第04集$id_XS5022B4D9ED4A080150E97D#第05集$id_XS5022B4D9ED4A080150E97C#第06集$id_XS5022B4D9ED4A080150E97F#第07集$id_XS5022B4D9ED4A080150E97E#第08集$id_XS5022B4D9ED4A080150E971#第09集$id_XS5022B4D9ED4A080150E970#第10集$id_XS5022B4D9ED4A080150E879#第11集$id_XS5022B4D9ED4A080150E878#第12集$id_XS5022B4D9ED4A080150E87B$$$第01集$id_MOE5022B4D9ED4A080150E978#第02集$id_MOE5022B4D9ED4A080150E97B#第03集$id_MOE5022B4D9ED4A080150E97A#第04集$id_MOE5022B4D9ED4A080150E97D#第05集$id_MOE5022B4D9ED4A080150E97C#第06集$id_MOE5022B4D9ED4A080150E97F#第07集$id_MOE5022B4D9ED4A080150E97E#第08集$id_MOE5022B4D9ED4A080150E971#第09集$id_MOE5022B4D9ED4A080150E970#第10集$id_MOE5022B4D9ED4A080150E879#第11集$id_MOE5022B4D9ED4A080150E878#第12集$id_MOE5022B4D9ED4A080150E87B', '', '', '', '', 0, '', ''