INSERT INTO `mac_vod` VALUES (298, 1, 0, 0, '蘑菇狗', 'きのこいぬ（2024）', 'mogugou', 1, 'M', '', '71a354fd', '漫画改', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2911386009.jpg', 'https://i1.hdslb.com/bfs/archive/c23842517e8d52afd89767e7c0cf3f619c1ed6c8.jpg', '', '', '小林大纪 / 上村祐翔 / 永濑安奈 / 寺岛拓笃 / 久野美咲 / 日菜 / 千本木彩花', '浅野景利', '', '', '某天庭院里突然长出了一只「蘑菇狗狗」，它像狗狗一样摇晃着尾巴，本质却是蘑菇？虽然它是谜一般的存在，跟它在一起却会让人开怀大笑。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 40, 0, 40, 40, '', 0, 0, 0.0, 0, 0, 1735690338, 1730956826, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>某天庭院里突然长出了一只「蘑菇狗狗」，它像狗狗一样摇晃着尾巴，本质却是蘑菇？虽然它是谜一般的存在，跟它在一起却会让人开怀大笑。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0626ED8BBC1D0B5D50E978#第02集$MOE0626ED8BBC1D0B5D50E97B#第03集$MOE0626ED8BBC1D0B5D50E97A#第04集$MOE0626ED8BBC1D0B5D50E97D#第05集$MOE0626ED8BBC1D0B5D50E97C#第06集$MOE0626ED8BBC1D0B5D50E97F#第07集$MOE0626ED8BBC1D0B5D50E97E#第08集$MOE0626ED8BBC1D0B5D50E971#第09集$MOE0626ED8BBC1D0B5D50E970#第10集$MOE0626ED8BBC1D0B5D50E879#第11集$MOE0626ED8BBC1D0B5D50E878#第12集$MOE0626ED8BBC1D0B5D50E87B$$$第01集$id_XS0626ED8BBC1D0B5D50E978#第02集$id_XS0626ED8BBC1D0B5D50E97B#第03集$id_XS0626ED8BBC1D0B5D50E97A#第04集$id_XS0626ED8BBC1D0B5D50E97D#第05集$id_XS0626ED8BBC1D0B5D50E97C#第06集$id_XS0626ED8BBC1D0B5D50E97F#第07集$id_XS0626ED8BBC1D0B5D50E97E#第08集$id_XS0626ED8BBC1D0B5D50E971#第09集$id_XS0626ED8BBC1D0B5D50E970#第10集$id_XS0626ED8BBC1D0B5D50E879#第11集$id_XS0626ED8BBC1D0B5D50E878#第12集$id_XS0626ED8BBC1D0B5D50E87B$$$第01集$id_MOE0626ED8BBC1D0B5D50E978#第02集$id_MOE0626ED8BBC1D0B5D50E97B#第03集$id_MOE0626ED8BBC1D0B5D50E97A#第04集$id_MOE0626ED8BBC1D0B5D50E97D#第05集$id_MOE0626ED8BBC1D0B5D50E97C#第06集$id_MOE0626ED8BBC1D0B5D50E97F#第07集$id_MOE0626ED8BBC1D0B5D50E97E#第08集$id_MOE0626ED8BBC1D0B5D50E971#第09集$id_MOE0626ED8BBC1D0B5D50E970#第10集$id_MOE0626ED8BBC1D0B5D50E879#第11集$id_MOE0626ED8BBC1D0B5D50E878#第12集$id_MOE0626ED8BBC1D0B5D50E87B', '', '', '', '', 0, '', '');
