INSERT INTO `mac_vod` VALUES (300, 1, 0, 0, '重生大小姐正在攻略龙帝殿下', 'やり直し令嬢は竜帝陛下を攻略中（2024）', 'zhongshengdaxiaojiezhengzaigongluelongdidianxia', 1, 'Z', '', 'ebc2c596', '小说改,异世界,奇幻,恋爱,日常', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2909149381.jpg', 'https://i1.hdslb.com/bfs/archive/e9cc63de86435278ddde8b6699b9f3bc0f7b8641.jpg', '', '', '内田秀 / 户谷菊之介 / 井泽诗织 / 日野麻里 / 橘龙丸 / 土岐隼一 / 贯井柚佳 / 真野步 / 名冢佳织 / 古川慎', '铃木健太郎', '', '', '千金小姐吉儿遭到太子以莫须有的罪名悔婚并宣判死刑。就在临死之际，她竟重生到了10岁时订下婚约的那场派对！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 94, 0, 94, 94, '', 0, 0, 0.0, 0, 0, 1736535930, 1730957481, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>千金小姐吉儿遭到太子以莫须有的罪名悔婚并宣判死刑。就在临死之际，她竟重生到了10岁时订下婚约的那场派对！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5475EF8AEA1C540F50E978#第02集$MOE5475EF8AEA1C540F50E97B#第03集$MOE5475EF8AEA1C540F50E97A#第04集$MOE5475EF8AEA1C540F50E97D#第05集$MOE5475EF8AEA1C540F50E97C#第06集$MOE5475EF8AEA1C540F50E97F#第07集$MOE5475EF8AEA1C540F50E97E#第08集$MOE5475EF8AEA1C540F50E971#第09集$MOE5475EF8AEA1C540F50E970#第10集$MOE5475EF8AEA1C540F50E879#第11集$MOE5475EF8AEA1C540F50E878#第12集$MOE5475EF8AEA1C540F50E87B$$$第01集$id_XS5475EF8AEA1C540F50E978#第02集$id_XS5475EF8AEA1C540F50E97B#第03集$id_XS5475EF8AEA1C540F50E97A#第04集$id_XS5475EF8AEA1C540F50E97D#第05集$id_XS5475EF8AEA1C540F50E97C#第06集$id_XS5475EF8AEA1C540F50E97F#第07集$id_XS5475EF8AEA1C540F50E97E#第08集$id_XS5475EF8AEA1C540F50E971#第09集$id_XS5475EF8AEA1C540F50E970#第10集$id_XS5475EF8AEA1C540F50E879#第11集$id_XS5475EF8AEA1C540F50E878#第12集$id_XS5475EF8AEA1C540F50E87B$$$第01集$id_MOE5475EF8AEA1C540F50E978#第02集$id_MOE5475EF8AEA1C540F50E97B#第03集$id_MOE5475EF8AEA1C540F50E97A#第04集$id_MOE5475EF8AEA1C540F50E97D#第05集$id_MOE5475EF8AEA1C540F50E97C#第06集$id_MOE5475EF8AEA1C540F50E97F#第07集$id_MOE5475EF8AEA1C540F50E97E#第08集$id_MOE5475EF8AEA1C540F50E971#第09集$id_MOE5475EF8AEA1C540F50E970#第10集$id_MOE5475EF8AEA1C540F50E879#第11集$id_MOE5475EF8AEA1C540F50E878#第12集$id_MOE5475EF8AEA1C540F50E87B', '', '', '', 