INSERT INTO `mac_vod` VALUES (301, 1, 0, 0, '妻子变成小学生。', '妻、小学生になる。（2024）', 'qizibianchengxiaoxuesheng', 1, 'Q', '', '702f366c', '温馨,悠闲', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2912511773.jpg', 'https://i1.hdslb.com/bfs/archive/8a8fb57dae84213dfeca9e4675a8def9a95094b8.jpg', '', '', '平川大辅 / 悠木碧 / 野村麻衣子 / 冈崎加奈 / 小岛幸子 / 岩中睦树', '阿部记之', '', '', '新岛圭介自十年前最爱的妻子贵惠去世后，完全没有生气，被周围的人看作是阴郁的男人。虽然他最希望自己的独生女麻衣幸福，但除了赚取生活费之外什么也没做，心里很难过，甚至连沟通都很困难。两人的时间，停止了十年', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 50, 0, 50, 50, '', 0, 0, 7.5, 0, 0, 1734300116, 1730957741, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>新岛圭介自十年前最爱的妻子贵惠去世后，完全没有生气，被周围的人看作是阴郁的男人。虽然他最希望自己的独生女麻衣幸福，但除了赚取生活费之外什么也没做，心里很难过，甚至连沟通都很困难。两人的时间，停止了十年。有一天，背着双肩包的陌生女孩拜访了这对父女。她说“我是十年前去世的你的妻子。” 妻子在这个世界上重生了。停止了的家庭时间，又重新开始了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0627BEDEBA1F5B5A50E978#第02集$MOE0627BEDEBA1F5B5A50E97B#第03集$MOE0627BEDEBA1F5B5A50E97A#第04集$MOE0627BEDEBA1F5B5A50E97D#第05集$MOE0627BEDEBA1F5B5A50E97C#第06集$MOE0627BEDEBA1F5B5A50E97F#第07集$MOE0627BEDEBA1F5B5A50E97E#第08集$MOE0627BEDEBA1F5B5A50E971#第09集$MOE0627BEDEBA1F5B5A50E970#第10集$MOE0627BEDEBA1F5B5A50E879#第11集$MOE0627BEDEBA1F5B5A50E878#第12集$MOE0627BEDEBA1F5B5A50E87B$$$第01集$id_XS0627BEDEBA1F5B5A50E978#第02集$id_XS0627BEDEBA1F5B5A50E97B#第03集$id_XS0627BEDEBA1F5B5A50E97A#第04集$id_XS0627BEDEBA1F5B5A50E97D#第05集$id_XS0627BEDEBA1F5B5A50E97C#第06集$id_XS0627BEDEBA1F5B5A50E97F#第07集$id_XS0627BEDEBA1F5B5A50E97E#第08集$id_XS0627BEDEBA1F5B5A50E971#第09集$id_XS0627BEDEBA1F5B5A50E970#第10集$id_XS0627BEDEBA1F5B5A50E879#第11集$id_XS0627BEDEBA1F5B5A50E878#第12集$id_XS0627BEDEBA1F5B5A50E87B$$$第01集$id_MOE0627BEDEBA1F5B5A50E978#第02集$id_MOE0627BEDEBA1F5B5A50E97B#第03集$id_MOE0627BEDEBA1F5B5A50E97A#第04集$id_MOE0627BEDEBA1F5B5A50E97D#第05集$id_MOE0627BEDEBA1F5B5A50E97C#第06集$id_MOE0627BEDEBA1F5B5A50E97F#第07集$id_MOE0627BEDEBA1F5B5A50E97E#第08集$id_MOE0627BEDEBA1F5B5A50E971#第09集$id_MOE0627BEDEBA1F5B5A50E970#第10集$id_MOE0627BEDEBA