INSERT INTO `mac_vod` VALUES (302, 1, 0, 0, '悲喜渔生', 'ネガポジアングラー（2024）', 'beixiyusheng', 1, 'B', '', 'c36d18f0', '原创,日常', 'https://i0.hdslb.com/bfs/bangumi/image/433850f77e7a39725c6160c7791b4949392edeff.png', 'https://i0.hdslb.com/bfs/archive/50371914c2416df1bd8ce27f889b23929694024d.png', '', '', '岩中睦树 / 菲鲁兹·蓝 / 石川界人', '上村泰', '', '', '大学生佐佐木常宏身背巨额债务，又被医生告知只余两年寿命。\r\n他终日郁郁寡欢，在一次被催债人追逐中失足坠海，幸而被热爱垂钓的少女花以及钓友贵明救助。\r\n在花的劝说下，常宏开始了人生中第一次垂钓，与其他钓友也', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 50, 0, 50, 50, '', 0, 0, 9.6, 0, 0, 1734724085, 1730957958, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>大学生佐佐木常宏身背巨额债务，又被医生告知只余两年寿命。\n他终日郁郁寡欢，在一次被催债人追逐中失足坠海，幸而被热爱垂钓的少女花以及钓友贵明救助。\n在花的劝说下，常宏开始了人生中第一次垂钓，与其他钓友也逐渐熟悉，并开始在花以及贵明工作的便利店打工。\n期初，他一度苦于各种生涩的术语和糠虾的腥味，但还是逐渐喜欢上了垂钓。鱼儿中钩的触感触达手中，那也是生命的实感——\n“一路下坡，只能抬头仰望的人生，不可能轻易改观” \n抱有如此想法的常宏，会通过垂钓获得怎样的感悟？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5224BADCB8110B0950E978#第02集$MOE5224BADCB8110B0950E97B#第03集$MOE5224BADCB8110B0950E97A#第04集$MOE5224BADCB8110B0950E97D#第05集$MOE5224BADCB8110B0950E97C#第06集$MOE5224BADCB8110B0950E97F#第07集$MOE5224BADCB8110B0950E97E#第08集$MOE5224BADCB8110B0950E971#第09集$MOE5224BADCB8110B0950E970#第10集$MOE5224BADCB8110B0950E879#第11集$MOE5224BADCB8110B0950E878#第12集$MOE5224BADCB8110B0950E87B$$$第01集$id_XS5224BADCB8110B0950E978#第02集$id_XS5224BADCB8110B0950E97B#第03集$id_XS5224BADCB8110B0950E97A#第04集$id_XS5224BADCB8110B0950E97D#第05集$id_XS5224BADCB8110B0950E97C#第06集$id_XS5224BADCB8110B0950E97F#第07集$id_XS5224BADCB8110B0950E97E#第08集$id_XS5224BADCB8110B0950E971#第09集$id_XS5224BADCB8110B0950E970#第10集$id_XS5224BADCB8110B0950E879#第11集$id_XS5224BADCB8110B0950E878#第12集$id_XS5224BADCB8110B0950E87B$$$第01集$id_MOE5224BADCB8110B0950E978#第02集$id_MOE5224BADCB8110B0950E97B#第03集$id_MOE5224BADCB8110B0950E97A#第04集$id_MOE5224BADCB8110B0950E97D#第05集$id_MOE5224BADCB8110B0950E97C#第06集$id_MOE5224BADCB8110B0950E97F#第07集$id_MOE5224BADCB8110B0950E97E#第08集$id_MOE5224BADCB8110B0950E971#第09集$id_MOE5224BADCB8110B0950E970#第10集$id_MOE5224BADCB8110B0950E879#第11集$id_MOE5224BADCB8110B0950E878#第12集$id_MOE5224BADCB8110B0950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (303, 1, 0, 0, '辰星降临之国的妮娜', '星降る王国のニナ（2024）', 'chenxingjianglinzhiguodenina', 1, 'C', '', 'd00505ae', '漫画改,少女,奇幻,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/b9694b56aefe2eefb4c3c18c4dba8c49040641de.png', 'https://i0.hdslb.com/bfs/archive/a34989c7e5e8fdd912c5ec270434c1dcca66f817.jpg', '', '', '田中美海 / 梅原裕一郎 / 内山昂辉 / 东山奈央 / 冨沢竜也', '驹屋健一郎', '', '', '在福尔托纳王国的郭外生活的孤儿妮娜，拥有和辰星之神一般深蓝色——琉璃色的眼睛。由于和死于意外事故的福尔托纳王国公主阿丽莎拥有相同颜色的眼睛，妮娜被第二王子阿兹尔找到，并被要求成为公主的替代品。作为辰星', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 110, 0, 110, 110, '', 0, 0, 8.4, 0, 0, 1735916371, 1730958298, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在福尔托纳王国的郭外生活的孤儿妮娜，拥有和辰星之神一般深蓝色——琉璃色的眼睛。由于和死于意外事故的福尔托纳王国公主阿丽莎拥有相同颜色的眼睛，妮娜被第二王子阿兹尔找到，并被要求成为公主的替代品。作为辰星巫女以及公主的替身，妮娜被赐予的使命是——在三个月后，作为假冒新娘，嫁给大国加尔加达的第一王子赛特。即使被命运玩弄，妮娜也为自己受人需要而感到欣喜。她直率的双眼注视的究竟是什么……为守护珍爱之人而下定决心之时，各自的命运都开始发生巨变！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5527BC8DB91C0C5C50E978#第02集$MOE5527BC8DB91C0C5C50E97B#第03集$MOE5527BC8DB91C0C5C50E97A#第04集$MOE5527BC8DB91C0C5C50E97D#第05集$MOE5527BC8DB91C0C5C50E97C#第06集$MOE5527BC8DB91C0C5C50E97F#第07集$MOE5527BC8DB91C0C5C50E97E#第08集$MOE5527BC8DB91C0C5C50E971#第09集$MOE5527BC8DB91C0C5C50E970#第10集$MOE5527BC8DB91C0C5C50E879#第11集$MOE5527BC8DB91C0C5C50E878#第12集$MOE5527BC8DB91C0C5C50E87B$$$第01集$id_XS5527BC8DB91C0C5C50E978#第02集$id_XS5527BC8DB91C0C5C50E97B#第03集$id_XS5527BC8DB91C0C5C50E97A#第04集$id_XS5527BC8DB91C0C5C50E97D#第05集$id_XS5527BC8DB91C0C5C50E97C#第06集$id_XS5527BC8DB91C0C5C50E97F#第07集$id_XS5527BC8DB91C0C5C50E97E#第08集$id_XS5527BC8DB91C0C5C50E971#第09集$id_XS5527BC8DB91C0C5C50E970#第10集$id_XS5527BC8DB91C0C5C50E879#第11集$id_XS5527BC8DB91C0C5C50E878#第12集$id_XS5527BC8DB91C0C5C50E87B$$$第01集$id_MOE5527BC8DB91C0C5C50E978#第02集$id_MOE5527BC8DB91C0C5C50E97B#第03集$id_MOE5527BC8DB91C0C5C50E97A#第04集$id_MOE5527BC8DB91C0C5C50E97D#第05集$id_MOE5527BC8DB91C0C5C50E97C#第06集$id_MOE5527BC8DB91C0C5C50E97F#第07集$id_MOE5527BC8DB91C0C5C50E97E#第08集$id_MOE5527BC8DB91C0C5C50E971#第09集$id_MOE5527BC8DB91C0C5C50E970#第10集$id_MOE5527BC8DB91C0C5C50E879#第11集$id_MOE5527BC8DB91C0C5C50E878#第12集$id_MOE5527BC8DB91C0C5C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (304, 1, 0, 0, '重来吧、魔王大人！R', '魔王様、リトライ!R（2024）', 'zhonglaibamowangdarenR', 1, 'Z', '', 'f9fe886d', '漫画改,奇幻,冒险,穿越', 'https://i0.hdslb.com/bfs/bangumi/image/fcfd4378b7a3c7219f4a679f1d23fd93cc795688.png', 'https://i1.hdslb.com/bfs/archive/2a673e7b90d0083f0083499a8f2a28f77ffa9e5e.jpg', '', '', '津田健次郎 / 麻仓桃 / 和气杏未 / 野口衣织 / 铃木爱奈 / 驹田航 / 铃木实里 / 橘美来 / 熊谷健太郎 / 日笠阳子 / 栞子', '古贺一臣', '', '', '大野晶在登录着自己运营的「无尽游戏」的最终头目「魔王·九内伯斗」这一角色时，被送到了异世界。\r\n他在那里邂逅了神秘少女「亚可」和圣女「露娜」等人，并与游戏中的部下和在异世界遇见的同伴们一起，一步步稳固在', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 89, 0, 89, 89, '', 0, 0, 5.7, 0, 0, 1734870854, 1730958541, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>大野晶在登录着自己运营的「无尽游戏」的最终头目「魔王·九内伯斗」这一角色时，被送到了异世界。\n他在那里邂逅了神秘少女「亚可」和圣女「露娜」等人，并与游戏中的部下和在异世界遇见的同伴们一起，一步步稳固在异世界的地盘后，为了寻找回到现实世界的办法而踏上了新的旅途。\n以「魔王」为中心的故事再度启航……！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE572EEADDB1115B5D50E978#第02集$MOE572EEADDB1115B5D50E97B#第03集$MOE572EEADDB1115B5D50E97A#第04集$MOE572EEADDB1115B5D50E97D#第05集$MOE572EEADDB1115B5D50E97C#第06集$MOE572EEADDB1115B5D50E97F#第07集$MOE572EEADDB1115B5D50E97E#第08集$MOE572EEADDB1115B5D50E971#第09集$MOE572EEADDB1115B5D50E970#第10集$MOE572EEADDB1115B5D50E879#第11集$MOE572EEADDB1115B5D50E878#第12集$MOE572EEADDB1115B5D50E87B$$$第01集$id_XS572EEADDB1115B5D50E978#第02集$id_XS572EEADDB1115B5D50E97B#第03集$id_XS572EEADDB1115B5D50E97A#第04集$id_XS572EEADDB1115B5D50E97D#第05集$id_XS572EEADDB1115B5D50E97C#第06集$id_XS572EEADDB1115B5D50E97F#第07集$id_XS572EEADDB1115B5D50E97E#第08集$id_XS572EEADDB1115B5D50E971#第09集$id_XS572EEADDB1115B5D50E970#第10集$id_XS572EEADDB1115B5D50E879#第11集$id_XS572EEADDB1115B5D50E878#第12集$id_XS572EEADDB1115B5D50E87B$$$第01集$id_MOE572EEADDB1115B5D50E978#第02集$id_MOE572EEADDB1115B5D50E97B#第03集$id_MOE572EEADDB1115B5D50E97A#第04集$id_MOE572EEADDB1115B5D50E97D#第05集$id_MOE572EEADDB1115B5D50E97C#第06集$id_MOE572EEADDB1115B5D50E97F#第07集$id_MOE572EEADDB1115B5D50E97E#第08集$id_MOE572EEADDB1115B5D50E971#第09集$id_MOE572EEADDB11