INSERT INTO `mac_vod` VALUES (306, 1, 0, 0, '妖怪学校的新人教师', '妖怪学校の先生はじめました！（2024）', 'yaoguaixuexiaodexinrenjiaoshi', 1, 'Y', '', '9e007384', '校园,青春,温馨', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2911982389.jpg', '', '', '', '逢坂良太 / 铃木崚汰 / 谷江玲音 / 坂泰斗 / 鬼头明里 / 高野洸 / 绫坂晴名 / 榊原优希 / 杉田智和 / 光富崇雄 / 日向朔公 / 森奈奈子 / 堀江瞬 / 岩崎谅太 / 福山润 / 苍井翔太 / 前野智昭 / 森永千才 / 柳原哲也', '小野胜巳', '', '', 'ビビリで、泣き虫なヘタレ人間教師・ 安倍晴明あべはるあき。', '全24集', '', 0, '0', '', '', '日本', '十月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 183, 0, 183, 183, '', 0, 0, 6.3, 0, 0, 1743517800, 1730959146, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '这个故事里有一名胆小又爱哭的新教师「安倍晴明」。憧憬成为教师的他，刚开始高兴不久，却发现任职的百鬼学园竟然是妖怪们的学校！学园长雇用软弱怯懦，而且还是人类的晴明究竟是为了什么…！？\n描绘了个性迥异的妖怪学生和老师——晴明之间奇妙而热闹的日常，这就是一部愉快妖怪学园喜剧！现在，开始上课！', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0872BC88BE1A550D50E978#第02集$MOE0872BC88BE1A550D50E97B#第03集$MOE0872BC88BE1A550D50E97A#第04集$MOE0872BC88BE1A550D50E97D#第05集$MOE0872BC88BE1A550D50E97C#第06集$MOE0872BC88BE1A550D50E97F#第07集$MOE0872BC88BE1A550D50E97E#第08集$MOE0872BC88BE1A550D50E971#第09集$MOE0872BC88BE1A550D50E970#第10集$MOE0872BC88BE1A550D50E879#第11集$MOE0872BC88BE1A550D50E878#第12集$MOE0872BC88BE1A550D50E87B#第13集$MOE0872BC88BE1A550D50E87A#第14集$MOE0872BC88BE1A550D50E87D#第15集$MOE0872BC88BE1A550D50E87C#第16集$MOE0872BC88BE1A550D50E87F#第17集$MOE0872BC88BE1A550D50E87E#第18集$MOE0872BC88BE1A550D50E871#第19集$MOE0872BC88BE1A550D50E870#第20集$MOE0872BC88BE1A550D50EB79#第21集$MOE0872BC88BE1A550D50EB78#第22集$MOE0872BC88BE1A550D50EB7B#第23集$MOE0872BC88BE1A550D50EB7A#第24集$MOE0872BC88BE1A550D50EB7D$$$第01集$id_XS0872BC88BE1A550D50E978#第02集$id_XS0872BC88BE1A550D50E97B#第03集$id_XS0872BC88BE1A550D50E97A#第04集$id_XS0872BC88BE1A550D50E97D#第05集$id_XS0872BC88BE1A550D50E97C#第06集$id_XS0872BC88BE1A550D50E97F#第07集$id_XS0872BC88BE1A550D50E97E#第08集$id_XS0872BC88BE1A550D50E971#第09集$id_XS0872BC88BE1A550D50E970#第10集$id_XS0872BC88BE1A550D50E879#第11集$id_XS0872BC88BE1A550D50E878#第12集$id_XS0872BC88BE1A550D50E87B#第13集$id_XS0872BC88BE1A550D50E87A#第