INSERT INTO `mac_vod` VALUES (307, 1, 0, 0, '愿来世为他人', '来世は他人がいい（2024）', 'yuanlaishiweitaren', 1, 'Y', '', 'd531894c', '恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2909965249.jpg', 'https://i1.hdslb.com/bfs/archive/a15c9a90ed8c822b6f9b1ed85b8df5eb55112773.jpg', '', '', '上田瞳 / 石田彰 / 游佐浩二 / 神谷浩史 / 上田耀司 / 中井和哉', '川濑敏文', '', '', '高中女生染井吉乃出生成长于极道之家。虽然家庭环境特殊，却也一直循规蹈矩过着平稳的日子。然而，就在吉乃与未婚夫深山雾岛宿命地相遇之后，原本平静的生活为之一变！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 126, 0, 126, 126, '', 0, 0, 6.2, 0, 0, 1735063433, 1730960123, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高中女生染井吉乃出生成长于极道之家。虽然家庭环境特殊，却也一直循规蹈矩过着平稳的日子。然而，就在吉乃与未婚夫深山雾岛宿命地相遇之后，原本平静的生活为之一变！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5522BF89B110595A50E978#第02集$MOE5522BF89B110595A50E97B#第03集$MOE5522BF89B110595A50E97A#第04集$MOE5522BF89B110595A50E97D#第05集$MOE5522BF89B110595A50E97C#第06集$MOE5522BF89B110595A50E97F#第07集$MOE5522BF89B110595A50E97E#第08集$MOE5522BF89B110595A50E971#第09集$MOE5522BF89B110595A50E970#第10集$MOE5522BF89B110595A50E879#第11集$MOE5522BF89B110595A50E878#第12集$MOE5522BF89B110595A50E87B$$$第01集$id_XS5522BF89B110595A50E978#第02集$id_XS5522BF89B110595A50E97B#第03集$id_XS5522BF89B110595A50E97A#第04集$id_XS5522BF89B110595A50E97D#第05集$id_XS5522BF89B110595A50E97C#第06集$id_XS5522BF89B110595A50E97F#第07集$id_XS5522BF89B110595A50E97E#第08集$id_XS5522BF89B110595A50E971#第09集$id_XS5522BF89B110595A50E970#第10集$id_XS5522BF89B110595A50E879#第11集$id_XS5522BF89B110595A50E878#第12集$id_XS5522BF89B110595A50E87B$$$第01集$id_MOE5522BF89B110595A50E978#第02集$id_MOE5522BF89B110595A50E97B#第03集$id_MOE5522BF89B110595A50E97A#第04集$id_MOE5522BF89B110595A50E97D#第05集$id_MOE5522BF89B110595A50E97C#第06集$id_MOE5522BF89B110595A50E97F#第07集$id_MOE5522BF89B110595A50E97E#第08集$id_MOE5522BF89B110595A50E971#第09集$id_MOE5522BF89B110595A50E970#第10集$id_MOE5522BF89B110595A50E879#第11集$id_MOE5522BF89B110595A50E878#第12集$id_MOE5522BF89B110595A50E87B', '', '', '', '', 0, '', '');
