INSERT INTO `mac_vod` VALUES (314, 1, 0, 0, '青之箱', 'アオのハコ（2024）', 'qingzhixiang', 1, 'Q', '', '365b33b8', '漫画改,校园,恋爱,治愈', 'https://i0.hdslb.com/bfs/bangumi/image/95b5753dbeb0cf155647572d3e9e45965b1ffd88.png', '', '', '', '千叶翔也 / 上田丽奈 / 鬼头明里 / 小林千晃 / 内田雄马', '矢野雄一郎', '', '', '在《周刊少年JUMP》好评连载的三浦糀创作的人气漫画《青之箱》。作品描写了个性丰满的角色们各怀心绪投身于社团活动的样子，以及“喜欢上某人时”的纤细心理活动。自2021年4月开始连载以来，吸引了众多读者', '全25集', '', 0, '0', '', '', '日本', '十月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 341, 0, 341, 341, '', 0, 0, 9.5, 0, 0, 1742538085, 1730963473, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在《周刊少年JUMP》好评连载的三浦糀创作的人气漫画《青之箱》。作品描写了个性丰满的角色们各怀心绪投身于社团活动的样子，以及“喜欢上某人时”的纤细心理活动。自2021年4月开始连载以来，吸引了众多读者。以青涩感触动人心的青春社团恋爱故事终于动画化！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0221B9DABA1A0F0150E978#第02集$MOE0221B9DABA1A0F0150E97B#第03集$MOE0221B9DABA1A0F0150E97A#第04集$MOE0221B9DABA1A0F0150E97D#第05集$MOE0221B9DABA1A0F0150E97C#第06集$MOE0221B9DABA1A0F0150E97F#第07集$MOE0221B9DABA1A0F0150E97E#第08集$MOE0221B9DABA1A0F0150E971#第09集$MOE0221B9DABA1A0F0150E970#第10集$MOE0221B9DABA1A0F0150E879#第11集$MOE0221B9DABA1A0F0150E878#第12集$MOE0221B9DABA1A0F0150E87B#第13集$MOE0221B9DABA1A0F0150E87A#第14集$MOE0221B9DABA1A0F0150E87D#第15集$MOE0221B9DABA1A0F0150E87C#第16集$MOE0221B9DABA1A0F0150E87F#第17集$MOE0221B9DABA1A0F0150E87E#第18集$MOE0221B9DABA1A0F0150E871#第19集$MOE0221B9DABA1A0F0150E870#第20集$MOE0221B9DABA1A0F0150EB79#第21集$MOE0221B9DABA1A0F0150EB78#第22集$MOE0221B9DABA1A0F0150EB7B#第23集$MOE0221B9DABA1A0F0150EB7A#第24集$MOE0221B9DABA1A0F0150EB7D#第25集$MOE0221B9DABA1A0F0150EB7C$$$第01集$id_XS0221B9DABA1A0F0150E978#第02集$id_XS0221B9DABA1A0F0150E97B#第03集$id_XS0221B9DABA1A0F0150E97A#第04集$id_XS0221B9DABA1A0F0150E97D#第05集$id_XS0221B9DABA1A0F0150E97C#第06集$id_XS0221B9DABA1A0F0150E97F#第07集$id_XS0221B9DABA1A0F0150E97E#第08集$id_XS0221B9DABA1A0F0150E971#第09集$id_XS0221B9DABA1A0F0150E970#第10集$id_XS0221B9DABA1A0F0150E879#第11集$id_XS0221B9DABA1A0F0150E878#第12集$id_XS0221B9DABA1A0F0150E87B#第13集$id_XS0221B9DABA1A0F0150E87A#第14集$id_XS0221B9DABA1A0F