INSERT INTO `mac_vod` VALUES (315, 1, 0, 0, '缘结甘神家', '甘神さんちの縁結び（2024）', 'yuanjieganshenjia', 1, 'Y', '', '1c62a598', '恋爱,青春', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2904687428.jpg', '', '', '', '铃木崚汰 / 上坂堇 / 本渡枫 / 若山诗音 / 水树奈奈 / 安济知佳 / 岛田敏 / 堀江由衣 / 游佐浩二 / 伊藤彩沙 / 白石晴香 / 阿部菜摘子', '安部祐二郎 / 渡边浩', '', '', '在孤儿院长大的男高中生志愿是京都大学的医学院，有一天他被通知到了需要离开孤儿院去别家借住的年纪，本来希望有一个可以读书的环境，但生存的条件却是“以女婿的身份接任神社”？不相信神一心学医的他和神社家三位', '全24集', '', 0, '0', '', '', '日本', '十月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 442, 0, 442, 442, '', 0, 0, 6.2, 0, 0, 1742916965, 1730963917, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在孤儿院长大的男高中生志愿是京都大学的医学院，有一天他被通知到了需要离开孤儿院去别家借住的年纪，本来希望有一个可以读书的环境，但生存的条件却是“以女婿的身份接任神社”？不相信神一心学医的他和神社家三位性格各异的巫女小姐姐同住一个屋檐下，等待他们的是新的化学反应还是神明的奇迹？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0074BA8AE81C540150E978#第02集$MOE0074BA8AE81C540150E97B#第03集$MOE0074BA8AE81C540150E97A#第04集$MOE0074BA8AE81C540150E97D#第05集$MOE0074BA8AE81C540150E97C#第06集$MOE0074BA8AE81C540150E97F#第07集$MOE0074BA8AE81C540150E97E#第08集$MOE0074BA8AE81C540150E971#第09集$MOE0074BA8AE81C540150E970#第10集$MOE0074BA8AE81C540150E879#第11集$MOE0074BA8AE81C540150E878#第12集$MOE0074BA8AE81C540150E87B#第13集$MOE0074BA8AE81C540150E87A#第14集$MOE0074BA8AE81C540150E87D#第15集$MOE0074BA8AE81C540150E87C#第16集$MOE0074BA8AE81C540150E87F#第17集$MOE0074BA8AE81C540150E87E#第18集$MOE0074BA8AE81C540150E871#第19集$MOE0074BA8AE81C540150E870#第20集$MOE0074BA8AE81C540150EB79#第21集$MOE0074BA8AE81C540150EB78#第22集$MOE0074BA8AE81C540150EB7B#第23集$MOE0074BA8AE81C540150EB7A#第24集$MOE0074BA8AE81C540150EB7D$$$第01集$id_XS0074BA8AE81C540150E978#第02集$id_XS0074BA8AE81C540150E97B#第03集$id_XS0074BA8AE81C540150E97A#第04集$id_XS0074BA8AE81C540150E97D#第05集$id_XS0074BA8AE81C540150E97C#第06集$id_XS0074BA8AE81C540150E97F#第07集$id_XS0074BA8AE81C540150E97E#第08集$id_XS0074BA8AE81C540150E971#第09集$id_XS0074BA8AE81C540150E970#第10集$id_XS0074BA8AE81C540150E879#第11集$id_XS0074BA8AE81C540150E878#第12集$id_XS0074BA8AE81C540150E87B#第13集$id_XS0074BA8AE81C5401