INSERT INTO `mac_vod` VALUES (321, 1, 0, 0, '青之驱魔师 雪之尽头篇', '青の祓魔師 雪ノ果篇（2024）', 'qingzhiqumoshixuezhijintoupian', 1, 'Q', '', 'ce353ef', '奇幻,冒险,校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2913062670.jpg', 'https://i1.hdslb.com/bfs/archive/9cb7c2d910e7b30cfb9bb247d28973b44d9ee2f5.jpg', '', '', '冈本信彦 / 福山润', '', '', '', 'TVアニメ『青の祓魔師 島根啓明結社篇』の続編を描く、『青の祓魔師 雪ノ果（ゆきのはて）篇』2024年10月放送決定！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 63, 0, 63, 63, '', 0, 0, 0.0, 0, 0, 1735753835, 1730965611, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>TVアニメ『青の祓魔師 島根啓明結社篇』の続編を描く、『青の祓魔師 雪ノ果（ゆきのはて）篇』2024年10月放送決定！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5272BF8DBA4C0B144DE8#第02集$MOE5272BF8DBA4C0B144DEB#第03集$MOE5272BF8DBA4C0B144DEA#第04集$MOE5272BF8DBA4C0B144DED#第05集$MOE5272BF8DBA4C0B144DEC#第06集$MOE5272BF8DBA4C0B144DEF#第07集$MOE5272BF8DBA4C0B144DEE#第08集$MOE5272BF8DBA4C0B144DE1#第09集$MOE5272BF8DBA4C0B144DE0#第10集$MOE5272BF8DBA4C0B144CE9#第11集$MOE5272BF8DBA4C0B144CE8#第12集$MOE5272BF8DBA4C0B144CEB$$$第01集$id_XS5272BF8DBA4C0B144DE8#第02集$id_XS5272BF8DBA4C0B144DEB#第03集$id_XS5272BF8DBA4C0B144DEA#第04集$id_XS5272BF8DBA4C0B144DED#第05集$id_XS5272BF8DBA4C0B144DEC#第06集$id_XS5272BF8DBA4C0B144DEF#第07集$id_XS5272BF8DBA4C0B144DEE#第08集$id_XS5272BF8DBA4C0B144DE1#第09集$id_XS5272BF8DBA4C0B144DE0#第10集$id_XS5272BF8DBA4C0B144CE9#第11集$id_XS5272BF8DBA4C0B144CE8#第12集$id_XS5272BF8DBA4C0B144CEB$$$第01集$id_MOE5272BF8DBA4C0B144DE8#第02集$id_MOE5272BF8DBA4C0B144DEB#第03集$id_MOE5272BF8DBA4C0B144DEA#第04集$id_MOE5272BF8DBA4C0B144DED#第05集$id_MOE5272BF8DBA4C0B144DEC#第06集$id_MOE5272BF8DBA4C0B144DEF#第07集$id_MOE5272BF8DBA4C0B144DEE#第08集$id_MOE5272BF8DBA4C0B144DE1#第09集$id_MOE5272BF8DBA4C0B144DE0#第10集$id_MOE5272BF8DBA4C0B144CE9#第11集$id_MOE5272BF8DBA4C0B144CE8#第12集$id_MOE5272BF8DBA4C0B144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (322, 1, 0, 0, '机械手臂 Mecha-Ude', 'メカウデ（2024）', 'jixieshoubiMechaUde', 1, 'J', '', '4d3dee4f', '战斗,科幻,机战', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2909247439.jpg', 'https://i1.hdslb.com/bfs/archive/ac888f3faa17b4664070b308ad7da38938b5d455.jpg', '', '', '丰永利行 / 杉田智和 / 岛村侑 / 石川界人 / 朴璐美 / 天月 / 东地宏树 / 中村悠一 / 悠木碧 / 日笠阳子', 'オカモト', '', '', '大约 100 年前。为了寻求在母星中枯竭的生命能量”阿比特“的机械生命体从异次元来访。它们为了穿梭次元，将姿态收缩到手臂模样，降落在”阿比特“丰富的地球上，通过寄生在其他生物上而得以在地球上生活，并与', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 56, 0, 56, 56, '', 0, 0, 0.0, 0, 0, 1734789289, 1730965881, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>大约 100 年前。为了寻求在母星中枯竭的生命能量”阿比特“的机械生命体从异次元来访。它们为了穿梭次元，将姿态收缩到手臂模样，降落在”阿比特“丰富的地球上，通过寄生在其他生物上而得以在地球上生活，并与一部分人类秘密接触，开始寻找”阿比特“。人们将那个模样的它们称为“机械臂”。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0573BFDCEC4C595F50E978#第02集$MOE0573BFDCEC4C595F50E97B#第03集$MOE0573BFDCEC4C595F50E97A#第04集$MOE0573BFDCEC4C595F50E97D#第05集$MOE0573BFDCEC4C595F50E97C#第06集$MOE0573BFDCEC4C595F50E97F#第07集$MOE0573BFDCEC4C595F50E97E#第08集$MOE0573BFDCEC4C595F50E971#第09集$MOE0573BFDCEC4C595F50E970#第10集$MOE0573BFDCEC4C595F50E879#第11集$MOE0573BFDCEC4C595F50E878#第12集$MOE0573BFDCEC4C595F50E87B$$$第01集$id_XS0573BFDCEC4C595F50E978#第02集$id_XS0573BFDCEC4C595F50E97B#第03集$id_XS0573BFDCEC4C595F50E97A#第04集$id_XS0573BFDCEC4C595F50E97D#第05集$id_XS0573BFDCEC4C595F50E97C#第06集$id_XS0573BFDCEC4C595F50E97F#第07集$id_XS0573BFDCEC4C595F50E97E#第08集$id_XS0573BFDCEC4C595F50E971#第09集$id_XS0573BFDCEC4C595F50E970#第10集$id_XS0573BFDCEC4C595F50E879#第11集$id_XS0573BFDCEC4C595F50E878#第12集$id_XS0573BFDCEC4C595F50E87B$$$第01集$id_MOE0573BFDCEC4C595F50E978#第02集$id_MOE0573BFDCEC4C595F50E97B#第03集$id_MOE0573BFDCEC4C595F50E97A#第04集$id_MOE0573BFDCEC4C595F50E97D#第05集$id_MOE0573BFDCEC4C595F50E97C#第06集$id_MOE0573BFDCEC4C595F50E97F#第07集$id_MOE0573BFDCEC4C595F50E97E#第08集$id_MOE0573BFDCEC4C595F50E971#第09集$id_MOE0573BFDCEC4C595F50E970#第10集$id_MOE0573BFDCEC4C595F50E8