INSERT INTO `mac_vod` VALUES (323, 1, 0, 0, '乱马1/2', 'らんま1/2（2024）', 'luanma12', 1, 'L', '', '7acbba8b', '漫画改,搞笑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2912408930.jpg', 'https://i1.hdslb.com/bfs/archive/0afcbd54bfcd504776f031e2957a47ec4460cdc0.jpg', '', '', '山口胜平 / 林原惠美 / 日高范子 / 长岛雄一 / 高山南 / 井上喜久子 / 大塚明夫 / 山寺宏一 / 佐久间玲 / 杉田智和 / 佐仓绫音 / 森川智之 / 宫野真守 / 悠木碧', '宇田钢之介', '', '', '早乙女乱马和天道道场的天道茜在父母安排下订下婚约，但是乱马有个非常特别的烦恼，他在中国受训时，不小心掉进了咒泉乡的诅咒之泉，从此之后，他的身体出现了古怪特性，只要碰到冷水就会变成女生，再碰到热水才会变', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 76, 0, 76, 76, '', 0, 0, 9.0, 0, 0, 1735366799, 1730966317, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>早乙女乱马和天道道场的天道茜在父母安排下订下婚约，但是乱马有个非常特别的烦恼，他在中国受训时，不小心掉进了咒泉乡的诅咒之泉，从此之后，他的身体出现了古怪特性，只要碰到冷水就会变成女生，再碰到热水才会变回男生。超搞笑动作浪漫喜剧就此拉开序幕，且看乱马、小茜和其他性格鲜明的独特角色打打闹闹，笑料大放送！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0676EFDAEB48555B50E978#第02集$MOE0676EFDAEB48555B50E97B#第03集$MOE0676EFDAEB48555B50E97A#第04集$MOE0676EFDAEB48555B50E97D#第05集$MOE0676EFDAEB48555B50E97C#第06集$MOE0676EFDAEB48555B50E97F#第07集$MOE0676EFDAEB48555B50E97E#第08集$MOE0676EFDAEB48555B50E971#第09集$MOE0676EFDAEB48555B50E970#第10集$MOE0676EFDAEB48555B50E879#第11集$MOE0676EFDAEB48555B50E878#第12集$MOE0676EFDAEB48555B50E87B$$$第01集$id_XS0676EFDAEB48555B50E978#第02集$id_XS0676EFDAEB48555B50E97B#第03集$id_XS0676EFDAEB48555B50E97A#第04集$id_XS0676EFDAEB48555B50E97D#第05集$id_XS0676EFDAEB48555B50E97C#第06集$id_XS0676EFDAEB48555B50E97F#第07集$id_XS0676EFDAEB48555B50E97E#第08集$id_XS0676EFDAEB48555B50E971#第09集$id_XS0676EFDAEB48555B50E970#第10集$id_XS0676EFDAEB48555B50E879#第11集$id_XS0676EFDAEB48555B50E878#第12集$id_XS0676EFDAEB48555B50E87B$$$第01集$id_MOE0676EFDAEB48555B50E978#第02集$id_MOE0676EFDAEB48555B50E97B#第03集$id_MOE0676EFDAEB48555B50E97A#第04集$id_MOE0676EFDAEB48555B50E97D#第05集$id_MOE0676EFDAEB48555B50E97C#第06集$id_MOE0676EFDAEB48555B50E97F#第07集$id_MOE0676EFDAEB48555B50E97E#第08集$id_MOE0676EFDAEB48555B50E971#第09集$id_MOE0676EFDAEB48555B50E970#第10集$i