INSERT INTO `mac_vod` VALUES (584, 1, 0, 0, '反叛的鲁路修', 'コードギアス 反逆のルルーシュ（2006）', 'fanpandeluluxiu', 1, 'F', '', '8fd956fe', '原创,热血,动作,科幻', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517464011.jpg', '', '', '', '福山润 / 樱井孝宏 / 野上尤加奈 / 小清水亚美 / 南央美 / 名冢佳织 / 井上喜久子 / 真殿光昭 / 加濑康之 / 大原沙耶香 / 皆川纯子 / 折笠富美子 / 千叶纱子 / 杉山纪彰 / 若本规夫 / 新井里美', '谷口悟朗 / 村田和也 / 秋田谷典昭 / 政木伸一 / 三宅和男 / 三好正人 / 鸟羽聪 / 山田彻 / 工藤宽显', '', '', '鲁路修本是帝国的王子，在母后遇害后，和失明的妹妹一起被流放到11区（原日本国）作为人质。在那里他们结识了日本王子朱雀，三人共同度过一段美好的童年时光。帝国最终全面攻陷了11区，鲁路修和妹妹的安宁生活再', '全25集', '', 0, '0', '', '', '日本', '日语', '2006', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 59, 0, 59, 59, '', 0, 0, 9.1, 0, 0, 1734235489, 1734195545, 0, 0, 0, 0, 0.0, '', '585,586', '', '', '', '', '', '', '', '<p>鲁路修本是帝国的王子，在母后遇害后，和失明的妹妹一起被流放到11区（原日本国）作为人质。在那里他们结识了日本王子朱雀，三人共同度过一段美好的童年时光。帝国最终全面攻陷了11区，鲁路修和妹妹的安宁生活再次被剥夺，朱雀和他们也分散了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0971E881BC1F0B5C50E978#第02集$MOE0971E881BC1F0B5C50E97B#第03集$MOE0971E881BC1F0B5C50E97A#第04集$MOE0971E881BC1F0B5C50E97D#第05集$MOE0971E881BC1F0B5C50E97C#第06集$MOE0971E881BC1F0B5C50E97F#第07集$MOE0971E881BC1F0B5C50E97E#第08集$MOE0971E881BC1F0B5C50E971#第09集$MOE0971E881BC1F0B5C50E970#第10集$MOE0971E881BC1F0B5C50E879#第11集$MOE0971E881BC1F0B5C50E878#第12集$MOE0971E881BC1F0B5C50E87B#第13集$MOE0971E881BC1F0B5C50E87A#第14集$MOE0971E881BC1F0B5C50E87D#第15集$MOE0971E881BC1F0B5C50E87C#第16集$MOE0971E881BC1F0B5C50E87F#第17集$MOE0971E881BC1F0B5C50E87E#第18集$MOE0971E881BC1F0B5C50E871#第19集$MOE0971E881BC1F0B5C50E870#第20集$MOE0971E881BC1F0B5C50EB79#第21集$MOE0971E881BC1F0B5C50EB78#第22集$MOE0971E881BC1F0B5C50EB7B#第23集$MOE0971E881BC1F0B5C50EB7A#第24集$MOE0971E881BC1F0B5C50EB7D#第25集$MOE0971E881BC1F0B5C50EB7C$$$第01集$id_XS0971E881BC1F0B5C50E978#第02集$id_XS0971E881BC1F0B5C50E97B#第03集$id_XS0971E881BC1F0B5C50E97A#第04集$id_XS0971E881BC1F0B5C50E97D#第05集$id_XS0971E881BC1F0B5C50E97C#第06集$id_XS0971E881BC1F0B5C50E97F#第07集$id_XS0971E881BC1F0B5C50E97E#第08集$id_XS0971E881BC1F0B5C50E971#第09集$id_XS0971E881BC1F0B5C50E970#第10集$id_XS0971E881BC1