INSERT INTO `mac_vod` VALUES (330, 1, 0, 0, '蓝色监狱 / 蓝色禁区', 'ブルーロック（2022）', 'lansejianyulansejinqu', 1, 'L', '', '6b9718c9', '漫画改,运动,热血', 'https://i0.hdslb.com/bfs/bangumi/image/bc02e3350f95d3b584fde18368d99280db763660.png', '', '', '', '浦和希 / 海渡翼 / 小野友树 / 齐藤壮马 / 中泽匡智 / 松冈祯丞 / 千叶翔也 / 仲村宗悟 / 梶田大嗣 / 绵贯龙之介 / 市川苍 / 铃村健一 / 神谷浩史 / 幸村惠理 / 诹访部顺一 / 花江夏树 / 铃木崚汰 / 岛崎信长 / 内田雄马 / 兴津和幸 / 内山昂辉 / 小西克幸 / 立花慎之介 / 樱井孝宏 / 下野纮 / 神尾晋一郎 / 驹田航 / 高桥大辅 / 中村悠一 / 古川慎 / 河西健吾 / 江口拓也 / 新祐树 / 岛田敏 / 佐佐木义人 / 相马康一 / 中原麻衣 /', '渡边彻明 / 石川俊介 / 横山和基 / 仓富康平 / 山崎隆 / 室谷靖 / 鸟羽聪 / 木村宽 / 美甘义人 / 川濑正雄 / 石黑达也 / 榎田敬宏 / 小野田雄亮 / 井之川慎太郎', '', '', '不当世界第一的利己主义者，就当不上世界第一的前锋。为了培养出能带领日本队夺得世界杯的前锋，日本足球协会制定了一个计划。其名为「蓝色监狱」计划。300名高中生被召集于此，并且全员都是前锋。以其中299人', '全24集', '', 0, '0', '', '', '日本', '十月', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 150, 0, 150, 150, '', 0, 0, 9.5, 0, 0, 1731191980, 1731191950, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>不当世界第一的利己主义者，就当不上世界第一的前锋。为了培养出能带领日本队夺得世界杯的前锋，日本足球协会制定了一个计划。其名为「蓝色监狱」计划。300名高中生被召集于此，并且全员都是前锋。以其中299人的足球生涯为代价诞生的，为日本足球掀起革命的前锋究竟是谁？现在，史上最热血、最疯狂的足球动画开幕了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775B58FB8110E0050E978#第02集$MOE0775B58FB8110E0050E97B#第03集$MOE0775B58FB8110E0050E97A#第04集$MOE0775B58FB8110E0050E97D#第05集$MOE0775B58FB8110E0050E97C#第06集$MOE0775B58FB8110E0050E97F#第07集$MOE0775B58FB8110E0050E97E#第08集$MOE0775B58FB8110E0050E971#第09集$MOE0775B58FB8110E0050E970#第10集$MOE0775B58FB8110E0050E879#第11集$MOE0775B58FB8110E0050E878#第12集$MOE0775B58FB8110E0050E87B#第13集$MOE0775B58FB8110E0050E87A#第14集$MOE0775B58FB8110E0050E87D#第15集$MOE0775B58FB8110E0050E87C#第16集$MOE0775B58FB8110E0050E87F#第17集$MOE0775B58FB8110E0050E87E#第18集$MOE0775B58FB8110E0050E871#第19集$MOE0775B58FB8110E0050E870#第20集$MOE0775B58FB8110E0050EB79#第21集$MOE0775B58FB8110E0050EB78#第22集$MOE0775B58FB8110E0050EB7B#第23集$MOE0775B58FB8110E0050EB7A#第24集$MOE0775B58FB8110E0050EB7D$$$第01集$id_XS0775B58FB8110E0050E978#第02集$id_XS0775B58FB8110E0050E97B#第03集$id_XS0775B58FB8110E0050E97A#第04集$id_XS0775B58FB8110E0050E97D