INSERT INTO `mac_vod` VALUES (332, 1, 0, 0, '怪人的沙拉碗', '変人のサラダボウル（2024）', 'guairendeshalawan', 1, 'G', '', '4358db20', '异世界,魔法,推理,悠闲', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2905222603.jpg', '', '', '', '古川慎 / 矢野妃菜喜 / 市道真央 / 大地叶 / 藤田茜 / 沼仓爱美 / 高田忧希 / 真野美月 / 上田耀司 / 立花慎之介 / 鸟海浩辅', '佐藤昌文', '', '', '贫苦的侦探镝矢惣助，遇到了操纵魔法的异世界皇女莎拉。惣助开始了与莎拉的同居生活，莎拉很快就习惯了现代日本。另一方面，在莎拉之后被转移的女骑士莉薇亚，在流浪的同时，过着令人惊喜的生活。向前稳定生活的两个', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 7.4, 0, 0, 1731222333, 1731215674, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>贫苦的侦探镝矢惣助，遇到了操纵魔法的异世界皇女莎拉。惣助开始了与莎拉的同居生活，莎拉很快就习惯了现代日本。另一方面，在莎拉之后被转移的女骑士莉薇亚，在流浪的同时，过着令人惊喜的生活。向前稳定生活的两个异世界人，不仅影响了惣助，也影响了鬼畜律师、分手公司工作员、宗教人士与住在这区的怪人们……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0524B980ED4B5F0950E978#第02集$MOE0524B980ED4B5F0950E97B#第03集$MOE0524B980ED4B5F0950E97A#第04集$MOE0524B980ED4B5F0950E97D#第05集$MOE0524B980ED4B5F0950E97C#第06集$MOE0524B980ED4B5F0950E97F#第07集$MOE0524B980ED4B5F0950E97E#第08集$MOE0524B980ED4B5F0950E971#第09集$MOE0524B980ED4B5F0950E970#第10集$MOE0524B980ED4B5F0950E879#第11集$MOE0524B980ED4B5F0950E878#第12集$MOE0524B980ED4B5F0950E87B$$$第01集$id_XS0524B980ED4B5F0950E978#第02集$id_XS0524B980ED4B5F0950E97B#第03集$id_XS0524B980ED4B5F0950E97A#第04集$id_XS0524B980ED4B5F0950E97D#第05集$id_XS0524B980ED4B5F0950E97C#第06集$id_XS0524B980ED4B5F0950E97F#第07集$id_XS0524B980ED4B5F0950E97E#第08集$id_XS0524B980ED4B5F0950E971#第09集$id_XS0524B980ED4B5F0950E970#第10集$id_XS0524B980ED4B5F0950E879#第11集$id_XS0524B980ED4B5F0950E878#第12集$id_XS0524B980ED4B5F0950E87B$$$第01集$id_MOE0524B980ED4B5F0950E978#第02集$id_MOE0524B980ED4B5F0950E97B#第03集$id_MOE0524B980ED4B5F0950E97A#第04集$id_MOE0524B980ED4B5F0950E97D#第05集$id_MOE0524B980ED4B5F0950E97C#第06集$id_MOE0524B980ED4B5F0950E97F#第07集$id_MOE0524B980ED4B5F0950E97E#第08集$id_MOE0524B980ED4B5F0950E971#第09集$id_MOE0524B980ED4B5F0950E970#第10集$id_MOE0524B980ED4B5F0950E879#第11集$id_MOE0524B980ED4B5F0950E878#第12集$id_MOE0524B980ED4B