INSERT INTO `mac_vod` VALUES (333, 1, 0, 0, '恋语轻唱', 'ささやくように恋を唄う（2024）', 'lianyuqingchang', 1, 'L', '', '7e595e2d', '校园,恋爱,青春', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2896993886.jpg', '', '', '', '岛野花 / 濑户麻沙美 / 小松未可子 / 小原好美 / 加隈亚衣 / 根本优奈', '真野玲', '', '', '高中入学第一天，在新生欢迎会上看到乐队“SSGIRLS”的演奏的新生木野日鞠，崇拜上担任吉他主唱的朝凪依，对她一见钟情。', '全10集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 6.4, 0, 0, 1731225922, 1731215880, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高中入学第一天，在新生欢迎会上看到乐队“SSGIRLS”的演奏的新生木野日鞠，崇拜上担任吉他主唱的朝凪依，对她一见钟情。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0672B981BC4C5F5D50E978#第02集$MOE0672B981BC4C5F5D50E97B#第03集$MOE0672B981BC4C5F5D50E97A#第04集$MOE0672B981BC4C5F5D50E97D#第05集$MOE0672B981BC4C5F5D50E97C#第06集$MOE0672B981BC4C5F5D50E97F#第07集$MOE0672B981BC4C5F5D50E97E#第08集$MOE0672B981BC4C5F5D50E971#第09集$MOE0672B981BC4C5F5D50E970#第10集$MOE0672B981BC4C5F5D50E879$$$第01集$id_XS0672B981BC4C5F5D50E978#第02集$id_XS0672B981BC4C5F5D50E97B#第03集$id_XS0672B981BC4C5F5D50E97A#第04集$id_XS0672B981BC4C5F5D50E97D#第05集$id_XS0672B981BC4C5F5D50E97C#第06集$id_XS0672B981BC4C5F5D50E97F#第07集$id_XS0672B981BC4C5F5D50E97E#第08集$id_XS0672B981BC4C5F5D50E971#第09集$id_XS0672B981BC4C5F5D50E970#第10集$id_XS0672B981BC4C5F5D50E879$$$第01集$id_MOE0672B981BC4C5F5D50E978#第02集$id_MOE0672B981BC4C5F5D50E97B#第03集$id_MOE0672B981BC4C5F5D50E97A#第04集$id_MOE0672B981BC4C5F5D50E97D#第05集$id_MOE0672B981BC4C5F5D50E97C#第06集$id_MOE0672B981BC4C5F5D50E97F#第07集$id_MOE0672B981BC4C5F5D50E97E#第08集$id_MOE0672B981BC4C5F5D50E971#第09集$id_MOE0672B981BC4C5F5D50E970#第10集$id_MOE0672B981BC4C5F5D50E879', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (334, 1, 0, 0, '新世界之门', '', 'xinshijiezhimen', 1, 'X', '', 'bd0b6560', '小说改,战斗,奇幻', 'https://i0.hdslb.com/bfs/bangumi/image/3c33f014529d8f2767f4c98020a9d338c070b42a.png', '', '', NULL, '进：小野贤章\n休妮·莱依萨：濑户麻沙美\n蒂尔娜·卢森特：本渡枫\n柚叶：冈咲美保\n威尔海姆·艾维斯：比留间俊哉\n米莉：凉本秋穗\n拉希娅·露泽尔：石原夏织\n莉安·斯特莱尔·贝鲁利希特：Lynn\n幻狼：星祐树\n吉拉特·艾斯特里亚：三上哲\n沃尔夫冈·艾斯特雷亚：铃木达央\n库欧蕾·艾斯特雷亚：花泽香菜', '中津环', '', '', '线上游戏《THE NEW GATE》\n这个拥有众多玩家的虚拟空间某日突然风云突变，将人们困在游戏的世界中大肆折磨。\n为了打破现状，一个名为“进”的青年，身为游戏内最强玩家挺身而出。\n阻挡在他面前的，是', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 28, 0, 28, 28, '', 0, 0, 6.1, 0, 0, 1731221681, 1731221661, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '线上游戏《THE NEW GATE》\n这个拥有众多玩家的虚拟空间某日突然风云突变，将人们困在游戏的世界中大肆折磨。\n为了打破现状，一个名为“进”的青年，身为游戏内最强玩家挺身而出。\n阻挡在他面前的，是这个世界中最大的敌人“原初（Origin）”\n“结束了！！”\n经历了殊死的战斗，进的一斩终于贯穿了“原初”的躯体。\n响亮的广播宣告着游戏的通关，以及被困玩家的解放。\n然而就在这一刹那，一扇崭新的门扉突然打开——\n随着光芒罩下，展现在进眼前的……\n是《THE NEW GATE》通关500年后的游戏世界！\n由风波凌创作的奇幻小说《THE NEW GATE》在粉丝的期待中终于动画化！\n在变为现实的游戏世界中，身为最强玩家的青年将开创崭新的传说。', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5373BCDABF1C5B0950E978#第02集$MOE5373BCDABF1C5B0950E97B#第03集$MOE5373BCDABF1C5B0950E97A#第04集$MOE5373BCDABF1C5B0950E97D#第05集$MOE5373BCDABF1C5B0950E97C#第06集$MOE5373BCDABF1C5B0950E97F#第07集$MOE5373BCDABF1C5B0950E97E#第08集$MOE5373BCDABF1C5B0950E971#第09集$MOE5373BCDABF1C5B0950E970#第10集$MOE5373BCDABF1C5B0950E879#第11集$MOE5373BCDABF1C5B0950E878#第12集$MOE5373BCDABF1C5B0950E87B$$$第01集$id_XS5373BCDABF1C5B0950E978#第02集$id_XS5373BCDABF1C5B0950E97B#第03集$id_XS5373BCDABF1C5B0950E97A#第04集$id_XS5373BCDABF1C5B0950E97D#第05集$id_XS5373BCDABF1C5B0950E97C#第06集$id_XS5373BCDABF1C5B0950E97F#第07集$id_XS5373BCDABF1C5B0950E97E#第08集$id_XS5373BCDABF1C5B0950E971#第09集$id_XS5373BCDABF1C5B0950E970#第10集$id_XS5373BCDABF1C5B0950E879#第11集$id_XS5373BCDABF1C5B0950E878#第12集$id_XS5373BCDABF1C5B0950E87B$$$第01集$id_MOE5373BCDABF1C5B0950E978#第02集$id_MOE5373BCDABF1C5B0950E97B#第03集$id_MOE5373BCDABF1C5B0950E97A#第04集$id_MOE5373BCDABF1C5B0950E97D#第05集$id_MOE