INSERT INTO `mac_vod` VALUES (340, 1, 0, 0, '叹气的亡灵想隐退', '嘆きの亡霊は引退したい（2024）', 'tanqidewanglingxiangyintui', 1, 'T', '', '381742ce', '小说改,异世界,战斗,搞笑,奇幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2913228937.jpg', '', '', '', '小野贤章 / 久保田未梦 / 菲鲁兹·蓝 / 小原好美 / 天崎滉平 / 杉田智和 / 古贺葵 / 大地叶 / 关根明良 / 关幸司 / 前田诚二 / 福山润 / 大塚明夫 / 道井悠', '高田真宏', '', '', 'トレジャーハンターになろうぜ', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 136, 0, 136, 136, '', 0, 0, 6.6, 0, 0, 1734997264, 1731271063, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>トレジャーハンターになろうぜ</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE022FBD8FBD1B0E5C50E978#第02集$MOE022FBD8FBD1B0E5C50E97B#第03集$MOE022FBD8FBD1B0E5C50E97A#第04集$MOE022FBD8FBD1B0E5C50E97D#第05集$MOE022FBD8FBD1B0E5C50E97C#第06集$MOE022FBD8FBD1B0E5C50E97F#第07集$MOE022FBD8FBD1B0E5C50E97E#第08集$MOE022FBD8FBD1B0E5C50E971#第09集$MOE022FBD8FBD1B0E5C50E970#第10集$MOE022FBD8FBD1B0E5C50E879#第11集$MOE022FBD8FBD1B0E5C50E878#第12集$MOE022FBD8FBD1B0E5C50E87B#第13集$MOE022FBD8FBD1B0E5C50E87A$$$第01集$id_XS022FBD8FBD1B0E5C50E978#第02集$id_XS022FBD8FBD1B0E5C50E97B#第03集$id_XS022FBD8FBD1B0E5C50E97A#第04集$id_XS022FBD8FBD1B0E5C50E97D#第05集$id_XS022FBD8FBD1B0E5C50E97C#第06集$id_XS022FBD8FBD1B0E5C50E97F#第07集$id_XS022FBD8FBD1B0E5C50E97E#第08集$id_XS022FBD8FBD1B0E5C50E971#第09集$id_XS022FBD8FBD1B0E5C50E970#第10集$id_XS022FBD8FBD1B0E5C50E879#第11集$id_XS022FBD8FBD1B0E5C50E878#第12集$id_XS022FBD8FBD1B0E5C50E87B#第13集$id_XS022FBD8FBD1B0E5C50E87A$$$第01集$id_MOE022FBD8FBD1B0E5C50E978#第02集$id_MOE022FBD8FBD1B0E5C50E97B#第03集$id_MOE022FBD8FBD1B0E5C50E97A#第04集$id_MOE022FBD8FBD1B0E5C50E97D#第05集$id_MOE022FBD8FBD1B0E5C50E97C#第06集$id_MOE022FBD8FBD1B0E5C50E97F#第07集$id_MOE022FBD8FBD1B0E5C50E97E#第08集$id_MOE022FBD8FBD1B0E5C50E971#第09集$id_MOE022FBD8FBD1B0E5C50E970#第10集$id_MOE022FBD8FBD1B0E5C50E879#第11集$id_MOE022FBD8FBD1B0E5C50E878#第12集$id_MOE022FBD8FBD1B0E5C50E87B#第13集$id_MOE022FBD8FBD1B0E5C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (341, 1, 0, 0, '鸭乃桥论的禁忌推理 第二季', '鴨乃橋ロンの禁断推理 2nd Season（2024）', 'yanaiqiaolundejinjituilidierji', 1, 'Y', '', '11cdd346', '漫画改', 'https://i0.hdslb.com/bfs/bangumi/image/8c217fd7cbbdc4e6f70614b74198d1e7f1ad75fe.png', '', '', '', '阿座上洋平', '井畑翔太', '', '', '在世界顶尖侦探学校·青蓝被誉为天才的鸭乃桥论，因患上某个致命“缺陷”，被剥夺了成为侦探的资格。在度过一段怀才不遇的岁月后，与警视厅搜查一课的一色都都丸——外号“都都”的相遇，极大改变了他的命运。论负责', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 154, 0, 154, 154, '', 0, 0, 0.0, 0, 0, 1735682611, 1731275614, 0, 0, 0, 0, 0.0, '', '88', '', '', '', '', '', '', '', '<p>在世界顶尖侦探学校·青蓝被誉为天才的鸭乃桥论，因患上某个致命“缺陷”，被剥夺了成为侦探的资格。在度过一段怀才不遇的岁月后，与警视厅搜查一课的一色都都丸——外号“都都”的相遇，极大改变了他的命运。论负责解谜，都都负责侦查，他们接连侦破疑难案件，逐渐成为了名搭档。青蓝内部也有论的理解者在两眼发光地关注着他的动向。其中一人就是校长艾梅利希。她告诉论，导致他被开除的“染血实习案”是一个圈套。其幕后主使，是制造了众多悬案的“史上最凶恶的犯罪一族”——M家，家主名叫麦罗·莫里亚蒂。为了给予论更大的绝望，麦罗将妹妹·温特派往了日本。论与麦罗之间究竟有何恩怨？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0026EFDCED1A590F50E978#第02集$MOE0026EFDCED1A590F50E97B#第03集$MOE0026EFDCED1A590F50E97A#第04集$MOE0026EFDCED1A590F50E97D#第05集$MOE0026EFDCED1A590F50E97C#第06集$MOE0026EFDCED1A590F50E97F#第07集$MOE0026EFDCED1A590F50E97E#第08集$MOE0026EFDCED1A590F50E971#第09集$MOE0026EFDCED1A590F50E970#第10集$MOE0026EFDCED1A590F50E879#第11集$MOE0026EFDCED1A590F50E878#第12集$MOE0026EFDCED1A590F50E87B#第13集$MOE0026EFDCED1A590F50E87A$$$第01集$id_XS0026EFDCED1A590F50E978#第02集$id_XS0026EFDCED1A590F50E97B#第03集$id_XS0026EFDCED1A590F50E97A#第04集$id_XS0026EFDCED1A590F50E97D#第05集$id_XS0026EFDCED1A590F50E97C#第06集$id_XS0026EFDCED1A590F50E97F#第07集$id_XS0026EFDCED1A590F50E97E#第08集$id_XS0026EFDCED1A590F50E971#第09集$id_XS0026EFDCED1A590F50E970#第10集$id_XS0026EFDCED1A590F50E879#第11集$id_XS0026EFDCED1A590F50E878#第12集$id_XS0026EFDCED1A590F50E87B#第13集$id_XS0026EFDCED1A590F50E87A$$$第01集$id_MOE0026EFDCED1A590F50E978#第02集$id_MOE0026EFDCED1A590F50E97B#第03集$id_MOE0026EFDCED1A590F50E97A#第04集$id_MOE0026EFDCED1A590F50E97D#第05集$id_MOE0026EFDCED1A590F50E97C#第06集$id_MOE0026EFDCED1A590F50E97F#第07集$id_MOE0026EFDCED1A590F50E97E#第08集$id_MOE0026EFDCED1A590F50E971#第09集$id_MOE0026EFDCED1A590F50E970#第10集$id_MOE0026EFDCED1A590F50E879#第11集$id_MOE0026EFDCED1A590F50E878#第12集$id_MOE0026EFDCED1A590F50E87B#第13集$id_MOE0026EFDCED1A590F50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (342, 4, 0, 0, '鸭乃桥论的禁忌推理', '', 'yanaiqiaolundejinjituili', 0, 'Y', '', '', '', 'https://i0.hdslb.com/bfs/bangumi/image/8c217fd7cbbdc4e6f70614b74198d1e7f1ad75fe.png', '', '', '', '', '', '', '', '在世界顶尖侦探学校·青蓝被誉为天才的鸭乃桥论，因患上某个致命“缺陷”，被剥夺了成为侦探的资格。在度过一段怀才不遇的岁月后，与警视厅搜查一课的一色都都丸——外号“都都”的相遇，极大改变了他的命运。论负责', '', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 0.0, 0, 0, 1731275695, 1731275695, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在世界顶尖侦探学校·青蓝被誉为天才的鸭乃桥论，因患上某个致命“缺陷”，被剥夺了成为侦探的资格。在度过一段怀才不遇的岁月后，与警视厅搜查一课的一色都都丸——外号“都都”的相遇，极大改变了他的命运。论负责解谜，都都负责侦查，他们接连侦破疑难案件，逐渐成为了名搭档。青蓝内部也有论的理解者在两眼发光地关注着他的动向。其中一人就是校长艾梅利希。她告诉论，导致他被开除的“染血实习案”是一个圈套。其幕后主使，是制造了众多悬案的“史上最凶恶的犯罪一族”——M家，家主名叫麦罗·莫里亚蒂。为了给予论更大的绝望，麦罗将妹妹·温特派往了日本。论与麦罗之间究竟有何恩怨？</p>', '', '', '', '', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (343, 1, 0, 0, '终末的火车前往何方？', '终末トレインどこへいく？（2024）', 'zhongmodehuocheqianwanghefang', 1, 'Z', '', '294e0ddf', '原创,奇幻,冒险,少女,催泪', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2896219060.jpg', '', '', '', '安济知佳 / 和气杏未 / 久远艾丽莎 / 木野日菜', '水岛努', '', '', '郊外的某个小镇。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 29, 0, 29, 29, '', 0, 0, 7.6, 0, 0, 1731348682, 1731305983, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>郊外的某个小镇。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032EB8DDB94D095F50E978#第02集$MOE032EB8DDB94D095F50E97B#第03集$MOE032EB8DDB94D095F50E97A#第04集$MOE032EB8DDB94D095F50E97D#第05集$MOE032EB8DDB94D095F50E97C#第06集$MOE032EB8DDB94D095F50E97F#第07集$MOE032EB8DDB94D095F50E97E#第08集$MOE032EB8DDB94D095F50E971#第09集$MOE032EB8DDB94D095F50E970#第10集$MOE032EB8DDB94D095F50E879#第11集$MOE032EB8DDB94D095F50E878#第11.5集$MOE032EB8DDB94D095F50E87B#第12集$MOE032EB8DDB94D095F50E87A$$$第01集$id_XS032EB8DDB94D095F50E978#第02集$id_XS032EB8DDB94D095F50E97B#第03集$id_XS032EB8DDB94D095F50E97A#第04集$id_XS032EB8DDB94D095F50E97D#第05集$id_XS032EB8DDB94D095F50E97C#第06集$id_XS032EB8DDB94D095F50E97F#第07集$id_XS032EB8DDB94D095F50E97E#第08集$id_XS032EB8DDB94D095F50E971#第09集$id_XS032EB8DDB94D095F50E970#第10集$id_XS032EB8DDB94D095F50E879#第11集$id_XS032EB8DDB94D095F50E878#第11.5集$id_XS032EB8DDB94D095F50E87B#第12集$id_XS032EB8DDB94D095F50E87A$$$第01集$id_MOE032EB8DDB94D095F50E978#第02集$id_MOE032EB8DDB94D095F50E97B#第03集$id_MOE032EB8DDB94D095F50E97A#第04集$id_MOE032EB8DDB94D095F50E97D#第05集$id_MOE032EB8DDB94D095F50E97C#第06集$id_MOE032EB8DDB94D095F50E97F#第07集$id_MOE032EB8DDB94D095F50E97E#第08集$id_MOE032EB8DDB94D095F50E971#第09集$id_MOE032EB8DDB94D095F50E970#第10集$id_MOE032EB8DDB94D095F50E879#第11集$id_MOE032EB8DDB94D095F50E878#第11.5集$id_MOE032EB8DDB94D095F50E87B#第12集$id_MOE032EB8DDB94D095F50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (344, 1, 0, 0, '声优广播的台前幕后', '', 'shengyouguangbodetaiqianmuhou', 1, 'S', '', 'db5e2dcb', '小说改,少女,声控,萌系', 'https://i0.hdslb.com/bfs/bangumi/image/494689a323389b7ce6532426ebfeea754bd4b483.jpg', '', '', NULL, '歌种安美／佐藤由美子：伊藤美来\n夕暮夕阳／渡边千佳：丰田萌绘\n樱并木乙女：长谷川育美\n柚日咲芽来：东山奈央', '橘秀树', '', '', '「夕阳和~」「安美的！」\n「「高中生广播~！」」\n「本节目是由碰巧就读于同一所高中、同一个班级的我们，为大家带来教室氛围的节目！」\n无论是作为声优还是作为同班同学都关系极好的二人，放松地做声优广播……', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 9.1, 0, 0, 1731306234, 1731306196, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '「夕阳和~」「安美的！」\n「「高中生广播~！」」\n「本节目是由碰巧就读于同一所高中、同一个班级的我们，为大家带来教室氛围的节目！」\n无论是作为声优还是作为同班同学都关系极好的二人，放松地做声优广播……但这仅仅是「台前」的模样。\n夕阳的本性是阴沉的土妹子，而安美则是地道的辣妹。\n容貌和性格都正好相反的二人，一开口就要吵架。\n「……怎么这么晃眼。你这样跟平时形象的差别真的大到吓人，平时的阴沉都到哪去了？」\n「你才是，别用这副模样发出可爱的声音啊」\n录音结束后便就地变成修罗场，挖苦和谩骂势如风暴！\n和这种人一起做广播，我绝对办不到！\n但是，节目可不会等人……！\n前途坎坷的声优广播，会持续多久……？！\n靠职业精神欺骗全世界！暴露就要结束的青春声优节目，现已播出!', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5575B9DDBB4D0E5B50E978#第02集$MOE5575B9DDBB4D0E5B50E97B#第03集$MOE5575B9DDBB4D0E5B50E97A#第04集$MOE5575B9DDBB4D0E5B50E97D#第05集$MOE5575B9DDBB4D0E5B50E97C#第06集$MOE5575B9DDBB4D0E5B50E97F#第07集$MOE5575B9DDBB4D0E5B50E97E#第08集$MOE5575B9DDBB4D0E5B50E971#第09集$MOE5575B9DDBB4D0E5B50E970#第10集$MOE5575B9DDBB4D0E5B50E879#第11集$MOE5575B9DDBB4D0E5B50E878#第12集$MOE5575B9DDBB4D0E5B50E87B$$$第01集$id_XS5575B9DDBB4D0E5B50E978#第02集$id_XS5575B9DDBB4D0E5B50E97B#第03集$id_XS5575B9DDBB4D0E5B50E97A#第04集$id_XS5575B9DDBB4D0E5B50E97D#第05集$id_XS5575B9DDBB4D0E5B50E97C#第06集$id_XS5575B9DDBB4D0E5B50E97F#第07集$id_XS5575B9DDBB4D0E5B50E97E#第08集$id_XS5575B9DDBB4D0E5B50E971#第09集$id_XS5575B9DDBB4D0E5B50E970#第10集$id_XS5575B9DDBB4D0E5B50E879#第11集$id_XS5575B9DDBB4D0E5B50E878#第12集$id_XS5575B9DDBB4D0E5B50E87B$$$第01集$id_MOE5575B9DDBB4D0E5B50E978#第02集$id_MOE5575B9DDBB4D0E5B50E97B#第03集$id_MOE5575B9DDBB4D0E5B50E97A#第04集$id_MOE5575B9DDBB4D0E5B50E97D#第05集$id_MOE5575B9DDBB4D0E5B50E97C#第06集$id_MOE5575B9DDBB4D0E5B50E97F#第07集$id_MOE5575B9DDBB4D0E5B50E97E#第08集$id_MOE5575B9DDBB4D0E5B50E971#第09集$id_MOE5575B9DDBB4D0E5B50E970#第10集$id_MOE5575B9DDBB4D0E5B50E879#第11集$id_MOE5575B9DDBB4D0E5B50E878#第12集$id_MOE5575B9DDBB4D0E5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (345, 1, 0, 0, '神渴望着游戏。', '', 'shenkewangzhuoyouxi', 1, 'S', '', '876b1f61', '小说改,奇幻,智斗,冒险', 'https://i0.hdslb.com/bfs/bangumi/image/dbfefc0da48fc486868485e697c1e0ca0f0fdfdf.png', '', '', NULL, '斐伊：岛崎信长\n莉奥蕾茜：鬼头明里\n帕尔：立花日菜\n奈琉：中村环奈', '白石达也', '', '', '人类VS神明 终极奇幻头脑战！\n闲来无事的众神设计了斗智游戏“众神游戏”，众神赐予神咒的人类被称为使徒，若在“众神游戏”中取得10胜将获得巨大祝福。\n然而，尚无一人实现完全通关。\n因为神明性情多变、不', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 28, 0, 28, 28, '', 0, 0, 6.2, 0, 0, 1731319888, 1731306308, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '人类VS神明 终极奇幻头脑战！\n闲来无事的众神设计了斗智游戏“众神游戏”，众神赐予神咒的人类被称为使徒，若在“众神游戏”中取得10胜将获得巨大祝福。\n然而，尚无一人实现完全通关。\n因为神明性情多变、不讲道理，时而令人无法理解。从漫长的沉睡中苏醒的前神明少女·蕾茜，刚醒来便说道“把这个时代最会玩游戏的人类带来”。\n而被选中的人，就是酷爱游戏的少年·斐伊。他在众神游戏中获得3胜且未尝败绩，被称为“近年最杰出的新星”而备受期待。就这样，斐伊和蕾茜开始一同挑战众神游戏。\n以完全通关为目标的斐伊和蕾茜，与神明的终极头脑战拉开了帷幕！', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0920BADAB84F5B0850E978#第02集$MOE0920BADAB84F5B0850E97B#第03集$MOE0920BADAB84F5B0850E97A#第04集$MOE0920BADAB84F5B0850E97D#第05集$MOE0920BADAB84F5B0850E97C#第06集$MOE0920BADAB84F5B0850E97F#第07集$MOE0920BADAB84F5B0850E97E#第08集$MOE0920BADAB84F5B0850E971#第09集$MOE0920BADAB84F5B0850E970#第10集$MOE0920BADAB84F5B0850E879#第11集$MOE0920BADAB84F5B0850E878#第12集$MOE0920BADAB84F5B0850E87B#第13集$MOE0920BADAB84F5B0850E87A$$$第01集$id_XS0920BADAB84F5B0850E978#第02集$id_XS0920BADAB84F5B0850E97B#第03集$id_XS0920BADAB84F5B0850E97A#第04集$id_XS0920BADAB84F5B0850E97D#第05集$id_XS0920BADAB84F5B0850E97C#第06集$id_XS0920BADAB84F5B0850E97F#第07集$id_XS0920BADAB84F5B0850E97E#第08集$id_XS0920BADAB84F5B0850E971#第09集$id_XS0920BADAB84F5B0850E970#第10集$id_XS0920BADAB84F5B0850E879#第11集$id_XS0920BADAB84F5B0850E878#第12集$id_XS0920BADAB84F5B0850E87B#第13集$id_XS0920BADAB84F5B0850E87A$$$第01集$id_MOE0920BADAB84F5B0850E978#第02集$id_MOE0920BADAB84F5B0850E97B#第03集$id_MOE0920BADAB84F5B0850E97A#第04集$id_MOE0920BADAB84F5B0850E97D#第05集$id_MOE0920BADAB84F5B0850E97C#第06集$id_MOE0920BADAB84F5B0850E97F#第07集$id_MOE0920BADAB84F5B0850E97E#第08集$id_MOE0920BADA