INSERT INTO `mac_vod` VALUES (347, 1, 0, 0, '单人房、日照一般、附天使。', 'ワンルーム、日当たり普通、天使つき。（2024）', 'danrenfangrizhaoyibanfutianshi', 1, 'D', '', 'eac4310b', '校园,恋爱,温馨,悠闲', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2906317109.jpg', '', '', '', '梅田修一朗 / 远野光 / 集贝花 / 大西沙织 / 小仓唯 / 高尾奏音', '大西健太', '', '', '德光森太郎是个平凡的高中男生，因父母工作关系目前一个人住。一天他的住处阳台上竟躺了个可爱女孩飞羽，她自称是天使，奉神明之命来到人界学习人类相关之事！', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 63, 0, 63, 63, '', 0, 0, 6.3, 0, 0, 1731373655, 1731317669, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>德光森太郎是个平凡的高中男生，因父母工作关系目前一个人住。一天他的住处阳台上竟躺了个可爱女孩飞羽，她自称是天使，奉神明之命来到人界学习人类相关之事！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5476EF8CBA185D5B50E978#第02集$MOE5476EF8CBA185D5B50E97B#第03集$MOE5476EF8CBA185D5B50E97A#第04集$MOE5476EF8CBA185D5B50E97D#第05集$MOE5476EF8CBA185D5B50E97C#第06集$MOE5476EF8CBA185D5B50E97F#第07集$MOE5476EF8CBA185D5B50E97E#第08集$MOE5476EF8CBA185D5B50E971#第09集$MOE5476EF8CBA185D5B50E970#第10集$MOE5476EF8CBA185D5B50E879#第11集$MOE5476EF8CBA185D5B50E878#第12集$MOE5476EF8CBA185D5B50E87B$$$第01集$id_XS5476EF8CBA185D5B50E978#第02集$id_XS5476EF8CBA185D5B50E97B#第03集$id_XS5476EF8CBA185D5B50E97A#第04集$id_XS5476EF8CBA185D5B50E97D#第05集$id_XS5476EF8CBA185D5B50E97C#第06集$id_XS5476EF8CBA185D5B50E97F#第07集$id_XS5476EF8CBA185D5B50E97E#第08集$id_XS5476EF8CBA185D5B50E971#第09集$id_XS5476EF8CBA185D5B50E970#第10集$id_XS5476EF8CBA185D5B50E879#第11集$id_XS5476EF8CBA185D5B50E878#第12集$id_XS5476EF8CBA185D5B50E87B$$$第01集$id_MOE5476EF8CBA185D5B50E978#第02集$id_MOE5476EF8CBA185D5B50E97B#第03集$id_MOE5476EF8CBA185D5B50E97A#第04集$id_MOE5476EF8CBA185D5B50E97D#第05集$id_MOE5476EF8CBA185D5B50E97C#第06集$id_MOE5476EF8CBA185D5B50E97F#第07集$id_MOE5476EF8CBA185D5B50E97E#第08集$id_MOE5476EF8CBA185D5B50E971#第09集$id_MOE5476EF8CBA185D5B50E970#第10集$id_MOE5476EF8CBA185D5B50E879#第11集$id_MOE5476EF8CBA185D5B50E878#第12集$id_MOE5476EF8CBA185D5B50E87B', '', '', '', '', 0, '', '');
