INSERT INTO `mac_vod` VALUES (501, 1, 0, 0, '魔法科高校的劣等生 第三季', '魔法科高校の劣等生 3期（2024）', 'mofakegaoxiaodeliedengshengdisanji', 1, 'M', '', '9e4c496e', '奇幻,冒险,科幻,校园,魔法', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2906041967.jpg', '', '', '', '中村悠一 / 早见沙织 / 安野希世乃 / 户谷菊之介 / 内山夕实 / 寺岛拓笃 / 佐藤聪美 / 田丸笃志 / 雨宫天 / 巽悠衣子 / 内田真礼 / 加藤英美里 / 花泽香菜 / 喜多村英梨 / 悠木碧 / 橘龙丸 / 游佐浩二 / 大塚芳忠', 'ジミー・ストーン', '', '', '魔法。それが現実の技術として確立されてから約一世紀が過ぎていた。', '全13集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 61, 0, 61, 61, '', 0, 0, 6.2, 0, 0, 1733227832, 1731466153, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>魔法。それが現実の技術として確立されてから約一世紀が過ぎていた。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0872B8DBBD105B5C50E978#第02集$MOE0872B8DBBD105B5C50E97B#第03集$MOE0872B8DBBD105B5C50E97A#第04集$MOE0872B8DBBD105B5C50E97D#第05集$MOE0872B8DBBD105B5C50E97C#第06集$MOE0872B8DBBD105B5C50E97F#第07集$MOE0872B8DBBD105B5C50E97E#第08集$MOE0872B8DBBD105B5C50E971#第09集$MOE0872B8DBBD105B5C50E970#第10集$MOE0872B8DBBD105B5C50E879#第11集$MOE0872B8DBBD105B5C50E878#第12集$MOE0872B8DBBD105B5C50E87B#第13集$MOE0872B8DBBD105B5C50E87A$$$第01集$id_XS0872B8DBBD105B5C50E978#第02集$id_XS0872B8DBBD105B5C50E97B#第03集$id_XS0872B8DBBD105B5C50E97A#第04集$id_XS0872B8DBBD105B5C50E97D#第05集$id_XS0872B8DBBD105B5C50E97C#第06集$id_XS0872B8DBBD105B5C50E97F#第07集$id_XS0872B8DBBD105B5C50E97E#第08集$id_XS0872B8DBBD105B5C50E971#第09集$id_XS0872B8DBBD105B5C50E970#第10集$id_XS0872B8DBBD105B5C50E879#第11集$id_XS0872B8DBBD105B5C50E878#第12集$id_XS0872B8DBBD105B5C50E87B#第13集$id_XS0872B8DBBD105B5C50E87A$$$第01集$id_MOE0872B8DBBD105B5C50E978#第02集$id_MOE0872B8DBBD105B5C50E97B#第03集$id_MOE0872B8DBBD105B5C50E97A#第04集$id_MOE0872B8DBBD105B5C50E97D#第05集$id_MOE0872B8DBBD105B5C50E97C#第06集$id_MOE0872B8DBBD105B5C50E97F#第07集$id_MOE0872B8DBBD105B5C50E97E#第08集$id_MOE0872B8DBBD105B5C50E971#第09集$id_MOE0872B8DBBD105B5C50E970#第10集$id_MOE0872B8DBBD105B5C50E879#第11集$id_MOE0872B8DBBD105B5C50E878#第12集$id_MOE0872B8DBBD105B5C50E87B#第13集$id_MOE0872B8DBBD1