INSERT INTO `mac_vod` VALUES (366, 1, 0, 0, '女子竞轮！', 'リンカイ！（2024）', 'nvzijinglun', 1, 'N', '', 'caf6bab1', '励志,运动,竞技', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2889831774.jpg', '', '', '', '川村海乃 / 葵梓 / 长谷川玲奈 / 北守彩香 / 杉山里穗 / 日向未南 / 佐佐木李子', '石山贵明', '', '', '女高中生伊东泉在“RINKAI LEAGUE”——目睹了女子自行车火热比赛后，与同伴们发誓要成为自行车赛车手。', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 0.0, 0, 0, 1731552358, 1731466625, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>女高中生伊东泉在“RINKAI LEAGUE”——目睹了女子自行车火热比赛后，与同伴们发誓要成为自行车赛车手。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5276EA8EEB480F0850E978#第02集$MOE5276EA8EEB480F0850E97B#第03集$MOE5276EA8EEB480F0850E97A#第04集$MOE5276EA8EEB480F0850E97D#第05集$MOE5276EA8EEB480F0850E97C#第06集$MOE5276EA8EEB480F0850E97F#第07集$MOE5276EA8EEB480F0850E97E#第08集$MOE5276EA8EEB480F0850E971#第09集$MOE5276EA8EEB480F0850E970#第10集$MOE5276EA8EEB480F0850E879#第11集$MOE5276EA8EEB480F0850E878#第12集$MOE5276EA8EEB480F0850E87B$$$第01集$id_XS5276EA8EEB480F0850E978#第02集$id_XS5276EA8EEB480F0850E97B#第03集$id_XS5276EA8EEB480F0850E97A#第04集$id_XS5276EA8EEB480F0850E97D#第05集$id_XS5276EA8EEB480F0850E97C#第06集$id_XS5276EA8EEB480F0850E97F#第07集$id_XS5276EA8EEB480F0850E97E#第08集$id_XS5276EA8EEB480F0850E971#第09集$id_XS5276EA8EEB480F0850E970#第10集$id_XS5276EA8EEB480F0850E879#第11集$id_XS5276EA8EEB480F0850E878#第12集$id_XS5276EA8EEB480F0850E87B$$$第01集$id_MOE5276EA8EEB480F0850E978#第02集$id_MOE5276EA8EEB480F0850E97B#第03集$id_MOE5276EA8EEB480F0850E97A#第04集$id_MOE5276EA8EEB480F0850E97D#第05集$id_MOE5276EA8EEB480F0850E97C#第06集$id_MOE5276EA8EEB480F0850E97F#第07集$id_MOE5276EA8EEB480F0850E97E#第08集$id_MOE5276EA8EEB480F0850E971#第09集$id_MOE5276EA8EEB480F0850E970#第10集$id_MOE5276EA8EEB480F0850E879#第11集$id_MOE5276EA8EEB480F0850E878#第12集$id_MOE5276EA8EEB480F0850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (484, 1, 0, 0, '黑执事：寄宿学校篇', '', 'heizhishijisuxuexiaopian', 1, 'H', '', '24039aa8', '漫画改,奇幻,校园', 'https://i0.hdslb.com/bfs/bangumi/image/b19b958acad0c6fcc6bb798b1581b0d4a85d4499.png', '', '', '', '小野大辅 / 坂本真绫', '冈田坚二朗', '', '', '19世纪的英国，名门贵族法多姆凯贝家的管家锡巴斯查恩·米加艾里斯，与他的13岁主人西雅尔·法多姆凯贝一同作为“女王的看门狗”，承接着社会黑暗面的肮脏工作。\r\n有一天，西雅尔收到女王来信，信中说就读于英国', '全11集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 27, 0, 27, 27, '', 0, 0, 9.1, 0, 0, 1733026373, 1731466723, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>19世纪的英国，名门贵族法多姆凯贝家的管家锡巴斯查恩·米加艾里斯，与他的13岁主人西雅尔·法多姆凯贝一同作为“女王的看门狗”，承接着社会黑暗面的肮脏工作。\n有一天，西雅尔收到女王来信，信中说就读于英国顶尖名门寄宿学校·威士顿的亲戚德瑞克以及其他数名学生失去了音讯，西雅尔与锡巴斯查恩遂进入威士顿学校卧底调查此事。\n事件的真相究竟是…？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0323BC8BB0480C0150E978#第02集$MOE0323BC8BB0480C0150E97B#第03集$MOE0323BC8BB0480C0150E97A#第04集$MOE0323BC8BB0480C0150E97D#第05集$MOE0323BC8BB0480C0150E97C#第06集$MOE0323BC8BB0480C0150E97F#第07集$MOE0323BC8BB0480C0150E97E#第08集$MOE0323BC8BB0480C0150E971#第09集$MOE0323BC8BB0480C0150E970#第10集$MOE0323BC8BB0480C0150E879#第11集$MOE0323BC8BB0480C0150E878$$$第01集$id_XS0323BC8BB0480C0150E978#第02集$id_XS0323BC8BB0480C0150E97B#第03集$id_XS0323BC8BB0480C0150E97A#第04集$id_XS0323BC8BB0480C0150E97D#第05集$id_XS0323BC8BB0480C0150E97C#第06集$id_XS0323BC8BB0480C0150E97F#第07集$id_XS0323BC8BB0480C0150E97E#第08集$id_XS0323BC8BB0480C0150E971#第09集$id_XS0323BC8BB0480C0150E970#第10集$id_XS0323BC8BB0480C0150E879#第11集$id_XS0323BC8BB0480C0150E878$$$第01集$id_MOE0323BC8BB0480C0150E978#第02集$id_MOE0323BC8BB0480C0150E97B#第03集$id_MOE0323BC8BB0480C0150E97A#第04集$id_MOE0323BC8BB0480C0150E97D#第05集$id_MOE0323BC8BB0480C0150E97C#第06集$id_MOE0323BC8BB0480C0150E97F#第07集$id_MOE0323BC8BB0480C0150E97E#第08集$id_MOE0323BC8BB0480C0150E971#第09集$id_MOE0323BC8BB0480C0150E970#第10集$id_MOE0323BC8BB0480C0150E879#第11集$id_MOE0323BC8BB0480C0150E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (508, 1, 0, 0, '鬼灭之刃 柱训练篇', '', 'guimiezhirenzhuxunlianpian', 1, 'G', '', 'd5bf0ad5', '漫画改,奇幻,热血', 'https://i0.hdslb.com/bfs/bangumi/image/07a4ec8e2a95558a99859e1e374fe4b634e47aaf.png', '', '', '', '花江夏树 / 鬼头明里 / 下野纮 / 松冈祯丞 / 樱井孝宏 / 小西克幸 / 河西健吾 / 早见沙织 / 花泽香菜 / 铃村健一 / 关智一 / 杉田智和', '外崎春雄', '', '', '以集英社《JUMP COMICS》1卷~23卷累积发行量突破1亿5000万册的吾峠呼世晴的漫画作品为原作。动画由ufotable制作。\r\n\r\n本作的开端是，家人被鬼杀害的少年灶门炭治郎，为了让变成鬼的妹妹', '全8集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 162, 1, 162, 162, '', 0, 0, 9.7, 0, 0, 1733277597, 1731466797, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>以集英社《JUMP COMICS》1卷~23卷累积发行量突破1亿5000万册的吾峠呼世晴的漫画作品为原作。动画由ufotable制作。\n\n本作的开端是，家人被鬼杀害的少年灶门炭治郎，为了让变成鬼的妹妹祢豆子变回人类，加入了「鬼杀队」。2019年4月《电视动画「鬼灭之刃」灶门炭治郎 立志篇》开始播出，2020年10月《剧场版「鬼灭之刃」无限列车篇》公开，2021年至2022年间，《电视动画「鬼灭之刃」无限列车篇》《电视动画「鬼灭之刃」游郭篇》发布播出，\n2023年2月《世界巡回放映「鬼灭之刃」上弦集结、并前往刀匠村》公开，4月《电视动画「鬼灭之刃」刀匠村篇》发布播出。\n2024年2月起《世界巡回放映「鬼灭之刃」牵绊的奇迹，并前往柱训练》公开，\n并决定在5月播出《电视动画「鬼灭之刃」柱训练篇》。\n\n前往柱训练——\n鬼杀队最强的剑士「柱」与鬼杀队员们。\n为迎接未来与鬼舞辻无惨的决战，开展了「柱训练」。\n胸怀各自的信念，炭治郎与众柱的崭新故事开幕了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5522EEDEB948090C50E978#第02集$MOE5522EEDEB948090C50E97B#第03集$MOE5522EEDEB948090C50E97A#第04集$MOE5522EEDEB948090C50E97D#第05集$MOE5522EEDEB948090C50E97C#第06集$MOE5522EEDEB948090C50E97F#第07集$MOE5522EEDEB948090C50E97E#第08集$MOE5522EEDEB948090C50E971$$$第01集$id_XS5522EEDEB948090C50E978#第02集$id_XS5522EEDEB948090C50E97B#第03集$id_XS5522EEDEB948090C50E97A#第04集$id_XS5522EEDEB948090C50E97D#第05集$id_XS5522EEDEB948090C50E97C#第06集$id_XS5522EEDEB948090C50E97F#第07集$id_XS5522EEDEB948090C50E97E#第08集$id_XS5522EEDEB948090C50E971$$$第01集$id_MOE5522EEDEB948090C50E978#第02集$id_MOE5522EEDEB948090C50E97B#第03集$id_MOE5522EEDEB948090C50E97A#第04集$id_MOE5522EEDEB948090C50E97D#第05集$id_MOE5522EEDEB948090C50E97C#第06集$id_MOE5522EEDEB948090C50E97F#第07集$id_MOE5522EEDEB948090C50E97E#第08集$id_MOE5522EEDEB948090C50E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (369, 1, 0, 0, '乌鸦不择主', '烏は主を選ばない（2024）', 'wuyabuzezhu', 1, 'W', '', '1a034893', '小说改,奇幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2904748066.jpg', '', '', '', '田村睦心 / 入野自由 / 本泉莉奈 / 七海弘希 / 福原绫香 / 钉宫理惠 / 竹内荣治 / 日野聪 / 白熊宽嗣 / 河西健吾 / 青山吉能 / 田中敦子', '京极义昭', '', '', '季節は春。皇太子・若宮の后（きさき）を選ぶ「登殿（とうでん）の儀」が始まった。南家の姫・浜木綿（はまゆう）、西家の姫・真赭の薄（ますほのすすき）、北家の姫・白珠（しらたま）、そして病の姉に代わり急きょ', '全20集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 7.3, 0, 0, 1731557109, 1731466906, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>季節は春。皇太子・若宮の后（きさき）を選ぶ「登殿（とうでん）の儀」が始まった。南家の姫・浜木綿（はまゆう）、西家の姫・真赭の薄（ますほのすすき）、北家の姫・白珠（しらたま）、そして病の姉に代わり急きょ登殿した東家の姫・あせび。山内の統治者・次期“金烏（きんう）”たる若宮の妻に選ばれるのは、四人のうちただ一人だけ。張り詰めた空気が漂う女の園で、あせびはまだ見ぬ若宮への想いを募らせていく。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0076BC8BBD11540A50E978#第02集$MOE0076BC8BBD11540A50E97B#第03集$MOE0076BC8BBD11540A50E97A#第04集$MOE0076BC8BBD11540A50E97D#第05集$MOE0076BC8BBD11540A50E97C#第06集$MOE0076BC8BBD11540A50E97F#第07集$MOE0076BC8BBD11540A50E97E#第08集$MOE0076BC8BBD11540A50E971#第09集$MOE0076BC8BBD11540A50E970#第10集$MOE0076BC8BBD11540A50E879#第11集$MOE0076BC8BBD11540A50E878#第12集$MOE0076BC8BBD11540A50E87B#第13集$MOE0076BC8BBD11540A50E87A#第14集$MOE0076BC8BBD11540A50E87D#第15集$MOE0076BC8BBD11540A50E87C#第16集$MOE0076BC8BBD11540A50E87F#第17集$MOE0076BC8BBD11540A50E87E#第18集$MOE0076BC8BBD11540A50E871#第19集$MOE0076BC8BBD11540A50E870#第20集$MOE0076BC8BBD11540A50EB79$$$第01集$id_XS0076BC8BBD11540A50E978#第02集$id_XS0076BC8BBD11540A50E97B#第03集$id_XS0076BC8BBD11540A50E97A#第04集$id_XS0076BC8BBD11540A50E97D#第05集$id_XS0076BC8BBD11540A50E97C#第06集$id_XS0076BC8BBD11540A50E97F#第07集$id_XS0076BC8BBD11540A50E97E#第08集$id_XS0076BC8BBD11540A50E971#第09集$id_XS0076BC8BBD11540A50E970#第10集$id_XS0076BC8BBD11540A50E879#第11集$id_XS0076BC8BBD11540A50E878#第12集$id_XS0076BC8BBD11540A50E87B#第13集$id_XS0076BC8BBD11540A50E87A#第14集$id_XS0076BC8BBD11540A50E87D#第15集$id_XS0076BC8BBD11540A50E87C#第16集$id_XS0076BC