INSERT INTO `mac_vod` VALUES (370, 1, 0, 0, '蔚蓝档案 The Animation', 'ブルーアーカイブ The Animation（2024）', 'weilandanganTheAnimation', 1, 'W', '', 'c303edb4', '校园,青春,科幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2903501194.jpg', '', '', '', '小仓唯 / 花守由美里 / 大桥彩香 / 三浦千幸 / 原田彩枫 / 近藤玲奈 / 藤井雪代 / 石飞惠里花 / 大久保瑠美 / 小原好美 / 坂田将吾', '山岸大悟 / 牧俊治', '', '', 'ここが、私たちの居場所だから', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 122, 0, 122, 122, '', 0, 0, 6.3, 0, 0, 1731616108, 1731466963, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>ここが、私たちの居場所だから</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5224BC8BEC4D0F0D50E978#第02集$MOE5224BC8BEC4D0F0D50E97B#第03集$MOE5224BC8BEC4D0F0D50E97A#第04集$MOE5224BC8BEC4D0F0D50E97D#第05集$MOE5224BC8BEC4D0F0D50E97C#第06集$MOE5224BC8BEC4D0F0D50E97F#第07集$MOE5224BC8BEC4D0F0D50E97E#第08集$MOE5224BC8BEC4D0F0D50E971#第09集$MOE5224BC8BEC4D0F0D50E970#第10集$MOE5224BC8BEC4D0F0D50E879#第11集$MOE5224BC8BEC4D0F0D50E878#第12集$MOE5224BC8BEC4D0F0D50E87B$$$第01集$id_XS5224BC8BEC4D0F0D50E978#第02集$id_XS5224BC8BEC4D0F0D50E97B#第03集$id_XS5224BC8BEC4D0F0D50E97A#第04集$id_XS5224BC8BEC4D0F0D50E97D#第05集$id_XS5224BC8BEC4D0F0D50E97C#第06集$id_XS5224BC8BEC4D0F0D50E97F#第07集$id_XS5224BC8BEC4D0F0D50E97E#第08集$id_XS5224BC8BEC4D0F0D50E971#第09集$id_XS5224BC8BEC4D0F0D50E970#第10集$id_XS5224BC8BEC4D0F0D50E879#第11集$id_XS5224BC8BEC4D0F0D50E878#第12集$id_XS5224BC8BEC4D0F0D50E87B$$$第01集$id_MOE5224BC8BEC4D0F0D50E978#第02集$id_MOE5224BC8BEC4D0F0D50E97B#第03集$id_MOE5224BC8BEC4D0F0D50E97A#第04集$id_MOE5224BC8BEC4D0F0D50E97D#第05集$id_MOE5224BC8BEC4D0F0D50E97C#第06集$id_MOE5224BC8BEC4D0F0D50E97F#第07集$id_MOE5224BC8BEC4D0F0D50E97E#第08集$id_MOE5224BC8BEC4D0F0D50E971#第09集$id_MOE5224BC8BEC4D0F0D50E970#第10集$id_MOE5224BC8BEC4D0F0D50E879#第11集$id_MOE5224BC8BEC4D0F0D50E878#第12集$id_MOE5224BC8BEC4D0F0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (371, 1, 0, 0, '花野井君和相思病', '花野井くんと恋の病（2024）', 'huayejingjunhexiangsibing', 1, 'H', '', 'ad7def2f', '校园,恋爱,温馨', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2904440073.jpg', '', '', '', '花泽香菜 / 小林千晃 / 久保由利香 / 坂本真绫 / 木村良平 / 逢坂良太 / 铃代纱弓 / 兴津和幸', '牧野友映', '', '', '虽然有家人和朋友，高中1年级学生·日生萤与恋爱无缘。有一天，她说看到了隔壁班的帅哥·花野井被甩的现场。看到花野井一个人站在公园里。萤火虫不经意地把伞递了过来。因为那件小事，后来花野井公开向我告白说:“', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 5.6, 0, 0, 1731488730, 1731467079, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>虽然有家人和朋友，高中1年级学生·日生萤与恋爱无缘。有一天，她说看到了隔壁班的帅哥·花野井被甩的现场。看到花野井一个人站在公园里。萤火虫不经意地把伞递了过来。因为那件小事，后来花野井公开向我告白说:“请和我交往吧。”、“喜欢”是什么？“恋爱”是怎么回事？面对突如其来的告白，萤火虫不知所措。为了“喜欢的孩子”，什么都愿意做。倾注的爱情无限大的花野井君。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5073BBDCEC4F5F5F50E978#第02集$MOE5073BBDCEC4F5F5F50E97B#第03集$MOE5073BBDCEC4F5F5F50E97A#第04集$MOE5073BBDCEC4F5F5F50E97D#第05集$MOE5073BBDCEC4F5F5F50E97C#第06集$MOE5073BBDCEC4F5F5F50E97F#第07集$MOE5073BBDCEC4F5F5F50E97E#第08集$MOE5073BBDCEC4F5F5F50E971#第09集$MOE5073BBDCEC4F5F5F50E970#第10集$MOE5073BBDCEC4F5F5F50E879#第11集$MOE5073BBDCEC4F5F5F50E878#第12集$MOE5073BBDCEC4F5F5F50E87B$$$第01集$id_XS5073BBDCEC4F5F5F50E978#第02集$id_XS5073BBDCEC4F5F5F50E97B#第03集$id_XS5073BBDCEC4F5F5F50E97A#第04集$id_XS5073BBDCEC4F5F5F50E97D#第05集$id_XS5073BBDCEC4F5F5F50E97C#第06集$id_XS5073BBDCEC4F5F5F50E97F#第07集$id_XS5073BBDCEC4F5F5F50E97E#第08集$id_XS5073BBDCEC4F5F5F50E971#第09集$id_XS5073BBDCEC4F5F5F50E970#第10集$id_XS5073BBDCEC4F5F5F50E879#第11集$id_XS5073BBDCEC4F5F5F50E878#第12集$id_XS5073BBDCEC4F5F5F50E87B$$$第01集$id_MOE5073BBDCEC4F5F5F50E978#第02集$id_MOE5073BBDCEC4F5F5F50E97B#第03集$id_MOE5073BBDCEC4F5F5F50E97A#第04集$id_MOE5073BBDCEC4F5F5F50E97D#第05集$id_MOE5073BBDCEC4F5F5F50E97C#第06集$id_MOE5073BBDCEC4F5F5F50E97F#第07集$id_MOE5073BBDCEC4F5F5F50E97E#第08集$id_MOE5073BBDCEC4F5F5F50E971#第09集$id_MOE5073BBDCEC4F5F5F50E970#第10集$id_MOE5073BBDCEC4F5F5F50E879#第11集$id_MOE5073BBDCEC4F5F5F50E878#第12集$id_MOE