INSERT INTO `mac_vod` VALUES (374, 1, 0, 0, '失忆投捕', '忘却バッテリー（2024）', 'shiyitoubo', 1, 'S', '', 'd3028d8', '校园,青春,运动,竞技', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2906010120.jpg', '', '', '', '增田俊树 / 宫野真守 / 阿座上洋平 / 岛崎信长 / 梶裕贵 / 山谷祥生 / 大塚刚央 / 石井马克 / 河西健吾', '中园真登', '', '', '曾折断无数同龄球儿之心的、日本第一的初中生投捕组合·清峰叶流火和要圭，面对来自全国74所名门高校的热情挖角，竟然悉数拒绝、从此销声匿迹……并且出现在一所普通到不能再普通、且没有棒球部的都立高校？背后的', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 8.8, 0, 0, 1731589818, 1731467579, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>曾折断无数同龄球儿之心的、日本第一的初中生投捕组合·清峰叶流火和要圭，面对来自全国74所名门高校的热情挖角，竟然悉数拒绝、从此销声匿迹……并且出现在一所普通到不能再普通、且没有棒球部的都立高校？背后的原因，竟然是因事故失忆的要圭？</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5524BC8AB14D55144DE8#第02集$MOE5524BC8AB14D55144DEB#第03集$MOE5524BC8AB14D55144DEA#第04集$MOE5524BC8AB14D55144DED#第05集$MOE5524BC8AB14D55144DEC#第06集$MOE5524BC8AB14D55144DEF#第07集$MOE5524BC8AB14D55144DEE#第08集$MOE5524BC8AB14D55144DE1#第09集$MOE5524BC8AB14D55144DE0#第10集$MOE5524BC8AB14D55144CE9#第11集$MOE5524BC8AB14D55144CE8#第12集$MOE5524BC8AB14D55144CEB$$$第01集$id_XS5524BC8AB14D55144DE8#第02集$id_XS5524BC8AB14D55144DEB#第03集$id_XS5524BC8AB14D55144DEA#第04集$id_XS5524BC8AB14D55144DED#第05集$id_XS5524BC8AB14D55144DEC#第06集$id_XS5524BC8AB14D55144DEF#第07集$id_XS5524BC8AB14D55144DEE#第08集$id_XS5524BC8AB14D55144DE1#第09集$id_XS5524BC8AB14D55144DE0#第10集$id_XS5524BC8AB14D55144CE9#第11集$id_XS5524BC8AB14D55144CE8#第12集$id_XS5524BC8AB14D55144CEB$$$第01集$id_MOE5524BC8AB14D55144DE8#第02集$id_MOE5524BC8AB14D55144DEB#第03集$id_MOE5524BC8AB14D55144DEA#第04集$id_MOE5524BC8AB14D55144DED#第05集$id_MOE5524BC8AB14D55144DEC#第06集$id_MOE5524BC8AB14D55144DEF#第07集$id_MOE5524BC8AB14D55144DEE#第08集$id_MOE5524BC8AB14D55144DE1#第09集$id_MOE5524BC8AB14D55144DE0#第10集$id_MOE5524BC8AB14D55144CE9#第11集$id_MOE5524BC8AB14D55144CE8#第12集$id_MOE5524BC8AB14D55144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (377, 1, 0, 0, '无职转生：到了异世界就拿出真本事', '無職転生～異世界行ったら本気だす～（2021）', 'wuzhizhuanshengdaoliaoyishijiejiunachuzhenbenshi', 1, 'W', '', '8a9305e8', '异世界,奇幻,冒险,魔法,战斗', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2627757433.jpg', '', '', '', '内山夕实 / 小原好美 / 茅野爱衣 / 加隈亚衣 / 森川智之 / 金元寿子 / Lynn / 浪川大辅', '冈本学', '', '', '一场车祸夺走了34岁无业家里蹲男青年的生命，当他再度苏醒之后，震惊的发现自己竟然穿越到了异世界中，附身在了一位名为鲁迪乌斯（内山夕实 配音）的贵族少爷身上。面对这命运之神给予他的重新来过的机会，男子发', '全11集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 177, 0, 177, 177, '', 0, 0, 5.5, 0, 0, 1731634589, 1731467708, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>一场车祸夺走了34岁无业家里蹲男青年的生命，当他再度苏醒之后，震惊的发现自己竟然穿越到了异世界中，附身在了一位名为鲁迪乌斯（内山夕实 配音）的贵族少爷身上。面对这命运之神给予他的重新来过的机会，男子发誓这一世一定要拿出点真本事来认真的生活。然而，尽管鲁迪乌斯有着这般宏达的决心，但废柴大叔的本性却还是屡屡暴露。</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0976B58BB91C080150E978#第02集$id_XS0976B58BB91C080150E97B#第03集$id_XS0976B58BB91C080150E97A#第04集$id_XS0976B58BB91C080150E97D#第05集$id_XS0976B58BB91C080150E97C#第06集$id_XS0976B58BB91C080150E97F#第07集$id_XS0976B58BB91C080150E97E#第08集$id_XS0976B58BB91C080150E971#第09集$id_XS0976B58BB91C080150E970#第10集$id_XS0976B58BB91C080150E879#第11集$id_XS0976B58BB91C080150E878$$$第01集$id_MOE0976B58BB91C080150E978#第02集$id_MOE0976B58BB91C080150E97B#第03集$id_MOE0976B58BB91C080150E97A#第04集$id_MOE0976B58BB91C080150E97D#第05集$id_MOE0976B58BB91C080150E97C#第06集$id_MOE0976B58BB91C080150E97F#第07集$id_MOE0976B58BB91C080150E97E#第08集$id_MOE0976B58BB91C080150E971#第09集$id_MOE0976B58BB91C080150E970#第10集$id_MOE0976B58BB91C080150E879#第11集$id_MOE0976B58BB91C080150E878', '', '', '', '', 0, '', '');
