INSERT INTO `mac_vod` VALUES (391, 1, 0, 0, '一兆游戏', 'トリリオンゲーム（2024）', 'yizhaoyouxi', 1, 'Y', '', 'a8e90532', '励志,职场', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2914581485.jpg', '', '', '', '大塚刚央 / 石毛翔弥 / 市道真央 / 东地宏树 / 田中有纪 / 土师孝也 / 铃木崚汰 / 若山诗音 / 水中雅章 / 千本木彩花 / 安田陆矢 / 新祐树', '佐藤雄三', '', '', '在计算机宅男阿学遭到混混纠缠时，出手救了他的是隔壁班素昧平生的阿阳。脑子动得快、八面玲珑、做坏事却不懂得踩剎车的阿阳，与有着沟通障碍、计算机知识却非常丰富的阿学，两人就此结下不解之缘，成为互补的最强搭', '全26集', '', 0, '0', '', '', '日本', '十月', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 76, 0, 76, 76, '', 0, 0, 6.2, 0, 0, 1743244264, 1731617520, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在计算机宅男阿学遭到混混纠缠时，出手救了他的是隔壁班素昧平生的阿阳。脑子动得快、八面玲珑、做坏事却不懂得踩剎车的阿阳，与有着沟通障碍、计算机知识却非常丰富的阿学，两人就此结下不解之缘，成为互补的最强搭档。毕业后，两人决定白手起家创业，一起赚到能买到世界上任何想要东西的「一兆美元」！为此，他们决定挑战世界级黑客大赛SECCHAM……！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE502FE981B91C5E0B50E978#第02集$MOE502FE981B91C5E0B50E97B#第03集$MOE502FE981B91C5E0B50E97A#第04集$MOE502FE981B91C5E0B50E97D#第05集$MOE502FE981B91C5E0B50E97C#第06集$MOE502FE981B91C5E0B50E97F#第07集$MOE502FE981B91C5E0B50E97E#第08集$MOE502FE981B91C5E0B50E971#第09集$MOE502FE981B91C5E0B50E970#第10集$MOE502FE981B91C5E0B50E879#第11集$MOE502FE981B91C5E0B50E878#第12集$MOE502FE981B91C5E0B50E87B#第13集$MOE502FE981B91C5E0B50E87A#第14集$MOE502FE981B91C5E0B50E87D#第15集$MOE502FE981B91C5E0B50E87C#第16集$MOE502FE981B91C5E0B50E87F#第17集$MOE502FE981B91C5E0B50E87E#第18集$MOE502FE981B91C5E0B50E871#第19集$MOE502FE981B91C5E0B50E870#第20集$MOE502FE981B91C5E0B50EB79#第21集$MOE502FE981B91C5E0B50EB78#第22集$MOE502FE981B91C5E0B50EB7B#第23集$MOE502FE981B91C5E0B50EB7A#第24集$MOE502FE981B91C5E0B50EB7D#第25集$MOE502FE981B91C5E0B50EB7C#第26集$MOE502FE981B91C5E0B50EB7F$$$第01集$id_XS502FE981B91C5E0B50E978#第02集$id_XS502FE981B91C5E0B50E97B#第03集$id_XS502FE981B91C5E0B50E97A#第04集$id_XS502FE981B91C5E0B50E97D#第05集$id_XS502FE981B91C5E0B50E97C#第06集$id_XS502FE981B91C5E0B50E97F#第07集$id_XS502FE981B91C5E0B50E97E#第08集$id_XS502FE981B91C5E0B50E971#第09集$id_XS502FE981B91C5E0B50E970#第10集$id_XS502FE981B91C5E0B50E879#第11集$id_XS502FE98