INSERT INTO `mac_vod` VALUES (511, 1, 0, 0, '进击的巨人 最终季 完结篇', '進撃の巨人 The Final Season 完結編（2023）', 'jinjidejurenzuizhongjiwanjiepian', 1, 'J', '', 'e3ee2551', '动作,冒险,战争', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2883720945.jpg', '', '', '', '梶裕贵 / 石川由依 / 井上麻里奈 / 神谷浩史 / 细谷佳正 / 下野纮 / 三上枝织 / 谷山纪章 / 朴璐美 / 子安武人 / 花江夏树 / 佐仓绫音 / 沼仓爱美', '林祐一郎', '', '', 'NHK総合にて2023年放送決定！', '全2集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 151, 0, 151, 151, '', 0, 0, 9.5, 0, 0, 1733373614, 1733329553, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>NHK総合にて2023年放送決定！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '前篇$MOE5424E9DDBB1C580850E978#后篇$MOE5424E9DDBB1C580850E97B$$$前篇$id_XS5424E9DDBB1C580850E978#后篇$id_XS5424E9DDBB1C580850E97B$$$前篇$id_MOE5424E9DDBB1C580850E978#后篇$id_MOE5424E9DDBB1C580850E97B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (393, 1, 0, 0, '吹响吧！上低音号 第二季', '', 'chuixiangbashangdiyinhaodierji', 1, 'C', '', 'fa132914', '音乐,小说改,励志,日常', 'http://i0.hdslb.com/bfs/bangumi/image/fa2700aa713fd3f770599fe816b4f84f260519ca.jpg', '', '', '', '黄前久美子：黑泽朋世\n加藤叶月：朝井彩加\n川岛绿辉：丰田萌绘\n高坂丽奈：安济知佳\n田中明日香：寿美菜子\n小笠原晴香：早见沙织\n中世古香织：茅原实里\n冢本秀一：石谷春贵\n泷升：樱井孝宏\n伞木希美：东山奈央\n黄前麻美子：沼仓爱美\n松本美知惠：久川绫\n桥本真博：中村悠一\n新山聪美：桑岛法子', '', '', '', '吹奏乐竞赛京都府大赛。在那里漂亮地取得金奖的北宇治高中吹奏乐部，向着下一个舞台·强豪云集的关西大赛发起挑战……！', '全13集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 9.9, 0, 0, 1731759323, 1731742738, 0, 0, 0, 0, 0.0, '', '394', '', '', '', '', '', '', '', '<p>吹奏乐竞赛京都府大赛。在那里漂亮地取得金奖的北宇治高中吹奏乐部，向着下一个舞台·强豪云集的关西大赛发起挑战……！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5776BD8BBB105C0D50E978#第02集$id_XS5776BD8BBB105C0D50E97B#第03集$id_XS5776BD8BBB105C0D50E97A#第04集$id_XS5776BD8BBB105C0D50E97D#第05集$id_XS5776BD8BBB105C0D50E97C#第06集$id_XS5776BD8BBB105C0D50E97F#第07集$id_XS5776BD8BBB105C0D50E97E#第08集$id_XS5776BD8BBB105C0D50E971#第09集$id_XS5776BD8BBB105C0D50E970#第10集$id_XS5776BD8BBB105C0D50E879#第11集$id_XS5776BD8BBB105C0D50E878#第12集$id_XS5776BD8BBB105C0D50E87B#第13集$id_XS5776BD8BBB105C0D50E87A$$$第01集$id_MOE5776BD8BBB105C0D50E978#第02集$id_MOE5776BD8BBB105C0D50E97B#第03集$id_MOE5776BD8BBB105C0D50E97A#第04集$id_MOE5776BD8BBB105C0D50E97D#第05集$id_MOE5776BD8BBB105C0D50E97C#第06集$id_MOE5776BD8BBB105C0D50E97F#第07集$id_MOE5776BD8BBB105C0D50E97E#第08集$id_MOE5776BD8BBB105C0D50E971#第09集$id_MOE5776BD8BBB105C0D50E970#第10集$id_MOE5776BD8BBB105C0D50E879#第11集$id_MOE5776BD8BBB105C0D50E878#第12集$id_MOE5776BD8BBB105C0D50E87B#第13集$id_MOE5776BD8BBB105C0D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (338, 1, 0, 0, '吹响吧！上低音号', '', 'chuixiangbashangdiyinhao', 1, 'C', '', '5674e794', '音乐,校园,少女,励志', 'https://i0.hdslb.com/bfs/bangumi/8fa9d26fe84bcb09e7f6707ac0f7260deb8761ac.jpg', '', '', '', '黄前久美子：黑泽朋世\n加藤叶月：朝井彩加\n川岛绿辉：丰田萌绘\n高坂丽奈：安济知佳\n田中明日香：寿美菜子\n小笠原晴香：早见沙织\n中世古香织：茅原实里\n冢本秀一：石谷春贵\n泷升：樱井孝宏', '', '', '', '初中曾是吹奏乐部部员的黄前久美子，在刚进入高中的春天，与同班同学加藤叶月、川岛绿辉一起去参考吹奏乐部。\r\n在那里，久美子遇见了以前的同班同学高坂丽奈。叶月和绿辉决定加入吹奏乐部，但久美子却有些犹豫。\r\n她', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 9.8, 0, 0, 1731759270, 1731743925, 0, 0, 0, 0, 0.0, '', '393,394', '', '', '', '', '', '', '', '<p>初中曾是吹奏乐部部员的黄前久美子，在刚进入高中的春天，与同班同学加藤叶月、川岛绿辉一起去参考吹奏乐部。\n在那里，久美子遇见了以前的同班同学高坂丽奈。叶月和绿辉决定加入吹奏乐部，但久美子却有些犹豫。\n她回想起了在初中吹奏乐比赛时，自己与丽奈之间发生的事情——</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS0421BB8CEC1E540D50E978#第02集$id_XS0421BB8CEC1E540D50E97B#第03集$id_XS0421BB8CEC1E540D50E97A#第04集$id_XS0421BB8CEC1E540D50E97D#第05集$id_XS0421BB8CEC1E540D50E97C#第06集$id_XS0421BB8CEC1E540D50E97F#第07集$id_XS0421BB8CEC1E540D50E97E#第08集$id_XS0421BB8CEC1E540D50E971#第09集$id_XS0421BB8CEC1E540D50E970#第10集$id_XS0421BB8CEC1E540D50E879#第11集$id_XS0421BB8CEC1E540D50E878#第12集$id_XS0421BB8CEC1E540D50E87B#第13集$id_XS0421BB8CEC1E540D50E87A$$$第01集$id_MOE0421BB8CEC1E540D50E978#第02集$id_MOE0421BB8CEC1E540D50E97B#第03集$id_MOE0421BB8CEC1E540D50E97A#第04集$id_MOE0421BB8CEC1E540D50E97D#第05集$id_MOE0421BB8CEC1E540D50E97C#第06集$id_MOE0421BB8CEC1E540D50E97F#第07集$id_MOE0421BB8CEC1E540D50E97E#第08集$id_MOE0421BB8CEC1E540D50E971#第09集$id_MOE0421BB8CEC1E540D50E970#第10集$id_MOE0421BB8CEC1E540D50E879#第11集$id_MOE0421BB8CEC1E540D50E878#第12集$id_MOE0421BB8CEC1E540D50E87B#第13集$id_MOE0421BB8CEC1E540D50E87A', '', '', '', '', 0, '', '');
