INSERT INTO `mac_vod` VALUES (396, 1, 0, 0, '间谍过家家 第一季', 'SPY×FAMILY（2022）', 'jiandieguojiajiadiyiji', 1, 'J', '', 'a51b0754', '漫画改,日常,搞笑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2869306649.jpg', '', '', '', '江口拓也 / 早见沙织 / 种崎敦美 / 吉野裕行 / 甲斐田裕子 / 山路和弘 / 藤原夏海 / 加藤英美里 / 小野贤章 / 松田健一郎', '古桥一浩 / 片桐崇 / 原田孝宏 / 高桥谦仁 / 赤井俊文 / 堀口和树 / 山本阳介 / 北川朋哉', '', '', '为了潜入名校，西国能力最强的间谍“黄昏”被下令组建家庭.但是，他的“女儿”居然是能够读取他人内心的超能力者！“妻子”是暗杀者？互相隐藏了真实身份的新家庭，面临考验与世界危机的痛快家庭喜剧就此展开！！', '全25集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 56, 0, 56, 56, '', 0, 0, 8.9, 0, 0, 1731789843, 1731760342, 0, 0, 0, 0, 0.0, '', '19', '', '', '', '', '', '', '', '<p>为了潜入名校，西国能力最强的间谍“黄昏”被下令组建家庭.但是，他的“女儿”居然是能够读取他人内心的超能力者！“妻子”是暗杀者？互相隐藏了真实身份的新家庭，面临考验与世界危机的痛快家庭喜剧就此展开！！</p>', 'xs$$$moe', 'no$$$no', '$$$', '第01集$id_XS5022BDDAB91E580D50E978#第02集$id_XS5022BDDAB91E580D50E97B#第03集$id_XS5022BDDAB91E580D50E97A#第04集$id_XS5022BDDAB91E580D50E97D#第05集$id_XS5022BDDAB91E580D50E97C#第06集$id_XS5022BDDAB91E580D50E97F#第07集$id_XS5022BDDAB91E580D50E97E#第08集$id_XS5022BDDAB91E580D50E971#第09集$id_XS5022BDDAB91E580D50E970#第10集$id_XS5022BDDAB91E580D50E879#第11集$id_XS5022BDDAB91E580D50E878#第12集$id_XS5022BDDAB91E580D50E87B#第13集$id_XS5022BDDAB91E580D50E87A#第14集$id_XS5022BDDAB91E580D50E87D#第15集$id_XS5022BDDAB91E580D50E87C#第16集$id_XS5022BDDAB91E580D50E87F#第17集$id_XS5022BDDAB91E580D50E87E#第18集$id_XS5022BDDAB91E580D50E871#第19集$id_XS5022BDDAB91E580D50E870#第20集$id_XS5022BDDAB91E580D50EB79#第21集$id_XS5022BDDAB91E580D50EB78#第22集$id_XS5022BDDAB91E580D50EB7B#第23集$id_XS5022BDDAB91E580D50EB7A#第24集$id_XS5022BDDAB91E580D50EB7D#第25集$id_XS5022BDDAB91E580D50EB7C$$$第01集$id_MOE5022BDDAB91E580D50E978#第02集$id_MOE5022BDDAB91E580D50E97B#第03集$id_MOE5022BDDAB91E580D50E97A#第04集$id_MOE5022BDDAB91E580D50E97D#第05集$id_MOE5022BDDAB91E580D50E97C#第06集$id_MOE5022BDDAB91E580D50E97F#第07集$id_MOE5022BDDAB91E580D50E97E#第08集$id_MOE5022BDDAB91E580D50E971#第09集$id_MOE5022BDDAB91E580D50E970#第10集$id_MOE5022BDDAB91E580D50E879#第11集$id_M