INSERT INTO `mac_vod` VALUES (400, 1, 0, 0, '夏目友人帐 第三季', '夏目友人帳 参（2011）', 'xiamuyourenzhangdisanji', 1, 'X', '', '157f09a0', '漫画改,奇幻,日常', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2210833325.jpg', '', '', '', '神谷浩史 / 井上和彦 / 小林沙苗 / 石田彰 / 堀江一真 / 木村良平 / 菅沼久义 / 诹访部顺一', '大森贵弘 / 植田秀仁 / 高桥秀弥 / 园田雅裕 / 松田清 / 久木晃嗣', '', '', '现正在白泉社旗下的少女漫画杂志《LaLa》上刊载的《夏目友人帐》，于白泉社的《夏目友人帐》官网上突然更新了一个天大喜讯——在2月24号发售的《LaLa 4月号》，《夏目友人帐》将会迎来一个重大发表!', '全13集', '', 0, '0', '', '', '日本', '日语', '2011', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 9.6, 0, 0, 1731849603, 1731829762, 0, 0, 0, 0, 0.0, '', '401,402,403,404', '', '', '', '', '', '', '', '<p>现正在白泉社旗下的少女漫画杂志《LaLa》上刊载的《夏目友人帐》，于白泉社的《夏目友人帐》官网上突然更新了一个天大喜讯——在2月24号发售的《LaLa 4月号》，《夏目友人帐》将会迎来一个重大发表! 是TV动画第三期吗?</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0022BBDEB9100C0950E978#第02集$MOE0022BBDEB9100C0950E97B#第03集$MOE0022BBDEB9100C0950E97A#第04集$MOE0022BBDEB9100C0950E97D#第05集$MOE0022BBDEB9100C0950E97C#第06集$MOE0022BBDEB9100C0950E97F#第07集$MOE0022BBDEB9100C0950E97E#第08集$MOE0022BBDEB9100C0950E971#第09集$MOE0022BBDEB9100C0950E970#第10集$MOE0022BBDEB9100C0950E879#第11集$MOE0022BBDEB9100C0950E878#第12集$MOE0022BBDEB9100C0950E87B#第13集$MOE0022BBDEB9100C0950E87A$$$第01集$id_XS0022BBDEB9100C0950E978#第02集$id_XS0022BBDEB9100C0950E97B#第03集$id_XS0022BBDEB9100C0950E97A#第04集$id_XS0022BBDEB9100C0950E97D#第05集$id_XS0022BBDEB9100C0950E97C#第06集$id_XS0022BBDEB9100C0950E97F#第07集$id_XS0022BBDEB9100C0950E97E#第08集$id_XS0022BBDEB9100C0950E971#第09集$id_XS0022BBDEB9100C0950E970#第10集$id_XS0022BBDEB9100C0950E879#第11集$id_XS0022BBDEB9100C0950E878#第12集$id_XS0022BBDEB9100C0950E87B#第13集$id_XS0022BBDEB9100C0950E87A$$$第01集$id_MOE0022BBDEB9100C0950E978#第02集$id_MOE0022BBDEB9100C0950E97B#第03集$id_MOE0022BBDEB9100C0950E97A#第04集$id_MOE0022BBDEB9100C0950E97D#第05集$id_MOE0022BBDEB9100C0950E97C#第06集$id_MOE0022BBDEB9100C0950E97F#第07集$id_MOE0022BBDEB9100C0950E97E#第08集$id_MOE0022BBDEB9100C0950E971#第09集$id_MOE0022BBDEB9100C0950E970#第10集$id_MOE0022BBDEB9100C0950E