INSERT INTO `mac_vod` VALUES (401, 1, 0, 0, '夏目友人帐 第四季', '夏目友人帳 肆（2012）', 'xiamuyourenzhangdisiji', 1, 'X', '', 'a25210c5', '漫画改,奇幻,日常', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1971342267.jpg', '', '', '', '神谷浩史 / 井上和彦 / 小林沙苗 / 石田彰', '大森贵弘 / 小岛正幸 / 黑柳利充 / 园田雅裕 / 出合小都美 / 松田清', '', '', '高中生夏目本来可以拥有平凡的高中生活，但是，他却能看到妖怪，并因此而苦恼。很多次，他都差点被妖怪夺去性命。', '全13集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 9.6, 0, 0, 1731868670, 1731846020, 0, 0, 0, 0, 0.0, '', '402,403,404', '', '', '', '', '', '', '', '<p>高中生夏目本来可以拥有平凡的高中生活，但是，他却能看到妖怪，并因此而苦恼。很多次，他都差点被妖怪夺去性命。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5025B98AB8190E0C50E978#第02集$MOE5025B98AB8190E0C50E97B#第03集$MOE5025B98AB8190E0C50E97A#第04集$MOE5025B98AB8190E0C50E97D#第05集$MOE5025B98AB8190E0C50E97C#第06集$MOE5025B98AB8190E0C50E97F#第07集$MOE5025B98AB8190E0C50E97E#第08集$MOE5025B98AB8190E0C50E971#第09集$MOE5025B98AB8190E0C50E970#第10集$MOE5025B98AB8190E0C50E879#第11集$MOE5025B98AB8190E0C50E878#第12集$MOE5025B98AB8190E0C50E87B#第13集$MOE5025B98AB8190E0C50E87A$$$第01集$id_XS5025B98AB8190E0C50E978#第02集$id_XS5025B98AB8190E0C50E97B#第03集$id_XS5025B98AB8190E0C50E97A#第04集$id_XS5025B98AB8190E0C50E97D#第05集$id_XS5025B98AB8190E0C50E97C#第06集$id_XS5025B98AB8190E0C50E97F#第07集$id_XS5025B98AB8190E0C50E97E#第08集$id_XS5025B98AB8190E0C50E971#第09集$id_XS5025B98AB8190E0C50E970#第10集$id_XS5025B98AB8190E0C50E879#第11集$id_XS5025B98AB8190E0C50E878#第12集$id_XS5025B98AB8190E0C50E87B#第13集$id_XS5025B98AB8190E0C50E87A$$$第01集$id_MOE5025B98AB8190E0C50E978#第02集$id_MOE5025B98AB8190E0C50E97B#第03集$id_MOE5025B98AB8190E0C50E97A#第04集$id_MOE5025B98AB8190E0C50E97D#第05集$id_MOE5025B98AB8190E0C50E97C#第06集$id_MOE5025B98AB8190E0C50E97F#第07集$id_MOE5025B98AB8190E0C50E97E#第08集$id_MOE5025B98AB8190E0C50E971#第09集$id_MOE5025B98AB8190E0C50E970#第10集$id_MOE5025B98AB8190E0C50E879#第11集$id_MOE5025B98AB8190E0C50E878#第12集$id_MOE5025B98AB8190E0C50E87B#第13集$id_MOE5025B98AB8190E0C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (402, 1, 0, 0, '夏目友人帐 第五季', '夏目友人帳 伍（2016）', 'xiamuyourenzhangdiwuji', 1, 'X', '', 'cdccd582', '漫画改,奇幻,日常', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2386647830.jpg', '', '', '', '神谷浩史 / 井上和彦 / 石田彰 / 堀江一真 / 菅沼久义 / 藤村步 / 诹访部顺一 / 小林沙苗 / 伊藤美纪 / 木村良平 / 泽城美雪 / 佐藤利奈', '大森贵弘 / 出合小都美', '', '', '从小便能看见妖怪的少年夏目贵志。自从他从祖母玲子那里继承了与妖怪成为主从并将其名字书写在上的契约书“友人帐”以来，便与自称为保镖的妖怪猫咪老师一同，开始了将名字返还给妖怪的每一天。夏目与各种各样的妖怪', '全11集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 33, 0, 33, 33, '', 0, 0, 9.6, 0, 0, 1731879386, 1731869308, 0, 0, 0, 0, 0.0, '', '403,404', '', '', '', '', '', '', '', '<p>从小便能看见妖怪的少年夏目贵志。自从他从祖母玲子那里继承了与妖怪成为主从并将其名字书写在上的契约书“友人帐”以来，便与自称为保镖的妖怪猫咪老师一同，开始了将名字返还给妖怪的每一天。夏目与各种各样的妖怪与善良人们相遇，在构筑温暖的场所同时，也反复寄托着想要守护重要之物的想法。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5273EFDBED1C550B50E978#第02集$MOE5273EFDBED1C550B50E97B#第03集$MOE5273EFDBED1C550B50E97A#第04集$MOE5273EFDBED1C550B50E97D#第05集$MOE5273EFDBED1C550B50E97C#第06集$MOE5273EFDBED1C550B50E97F#第07集$MOE5273EFDBED1C550B50E97E#第08集$MOE5273EFDBED1C550B50E971#第09集$MOE5273EFDBED1C550B50E970#第10集$MOE5273EFDBED1C550B50E879#第11集$MOE5273EFDBED1C550B50E878$$$第01集$id_XS5273EFDBED1C550B50E978#第02集$id_XS5273EFDBED1C550B50E97B#第03集$id_XS5273EFDBED1C550B50E97A#第04集$id_XS5273EFDBED1C550B50E97D#第05集$id_XS5273EFDBED1C550B50E97C#第06集$id_XS5273EFDBED1C550B50E97F#第07集$id_XS5273EFDBED1C550B50E97E#第08集$id_XS5273EFDBED1C550B50E971#第09集$id_XS5273EFDBED1C550B50E970#第10集$id_XS5273EFDBED1C550B50E879#第11集$id_XS5273EFDBED1C550B50E878$$$第01集$id_MOE5273EFDBED1C550B50E978#第02集$id_MOE5273EFDBED1C550B50E97B#第03集$id_MOE5273EFDBED1C550B50E97A#第04集$id_MOE5273EFDBED1C550B50E97D#第05集$id_MOE5273EFDBED1C550B50E97C#第06集$id_MOE5273EFDBED1C550B50E97F#第07集$id_MOE5273EFDBED1C550B50E97E#第08集$id_MOE5273EFDBED1C550B50E971#第09集$id_MOE5273EFDBED1C550B50E970#第10集$id_MOE5273EFDBED1C550B50E879#第11集$id_MOE5273EFDBED1C550B50E878', '', '', '', '', 0, '', '');
