INSERT INTO `mac_vod` VALUES (397, 1, 0, 0, '约会大作战', '', 'yuehuidazuozhan', 1, 'Y', '', '2fdc1b9c', '小说改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/ad4dc7bf7bef59255536e54fe818985b0e270d14.jpg', '', '', '', '岛崎信长 / 井上麻里奈 / 竹达彩奈 / 富㭴美铃 / 野水伊织 / 真田麻美 / 佐土原香织 / 远藤绫', '元永庆太郎 / 木村真一郎 / 高林久弥 / 安藤贵史 / 铃木薰', '', '', '【本片翻译由澄空学园字幕组提供】故事是讲述一名普通的高中二年级生五河士道，突然在某一天遇上了一场大爆炸，而在这场大爆炸之中竟然出现一名身穿盔甲手持大剑的神秘美少女。原来这名少女的真正身份是“精灵”，是', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 116, 0, 116, 116, '', 0, 0, 9.3, 0, 0, 1731900994, 1731881813, 0, 0, 0, 0, 0.0, '', '405,406,407,408', '', '', '', '', '', '', '', '<p>【本片翻译由澄空学园字幕组提供】故事是讲述一名普通的高中二年级生五河士道，突然在某一天遇上了一场大爆炸，而在这场大爆炸之中竟然出现一名身穿盔甲手持大剑的神秘美少女。原来这名少女的真正身份是“精灵”，是会给世界带来毁灭性灾难的存在，她的再次出现，将会给地球带来毁灭性的未来！然而主人公士道却有方法阻止世界毁灭，这个唯一能够阻止世界毁灭的方法就是——要与她约会！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0371E8DBB84B545A50E978#第02集$MOE0371E8DBB84B545A50E97B#第03集$MOE0371E8DBB84B545A50E97A#第04集$MOE0371E8DBB84B545A50E97D#第05集$MOE0371E8DBB84B545A50E97C#第06集$MOE0371E8DBB84B545A50E97F#第07集$MOE0371E8DBB84B545A50E97E#第08集$MOE0371E8DBB84B545A50E971#第09集$MOE0371E8DBB84B545A50E970#第10集$MOE0371E8DBB84B545A50E879#第11集$MOE0371E8DBB84B545A50E878#第12集$MOE0371E8DBB84B545A50E87B#OAD$MOE0371E8DBB84B545A50E87A$$$第01集$id_XS0371E8DBB84B545A50E978#第02集$id_XS0371E8DBB84B545A50E97B#第03集$id_XS0371E8DBB84B545A50E97A#第04集$id_XS0371E8DBB84B545A50E97D#第05集$id_XS0371E8DBB84B545A50E97C#第06集$id_XS0371E8DBB84B545A50E97F#第07集$id_XS0371E8DBB84B545A50E97E#第08集$id_XS0371E8DBB84B545A50E971#第09集$id_XS0371E8DBB84B545A50E970#第10集$id_XS0371E8DBB84B545A50E879#第11集$id_XS0371E8DBB84B545A50E878#第12集$id_XS0371E8DBB84B545A50E87B#OAD$id_XS0371E8DBB84B545A50E87A$$$第01集$id_MOE0371E8DBB84B545A50E978#第02集$id_MOE0371E8DBB84B545A50E97B#第03集$id_MOE0371E8DBB84B545A50E97A#第04集$id_MOE0371E8DBB84B545A50E97D#第05集$id_MOE0371E8DBB84B545A50E97C#第06集$id_MOE0371E8DBB84B545A50E97F#第07集$id_MOE0371E8DBB84B545A50E97E#第08集$id_MOE0371E8DBB84B545A50E971#第09集$id_MOE0371E