INSERT INTO `mac_vod` VALUES (405, 1, 0, 0, '约会大作战2', 'デート・ア・ライブⅡ（2014）', 'yuehuidazuozhan2', 1, 'Y', '', 'e343bd79', '小说改,奇幻,战斗', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2180648280.jpg', '', '', '', '岛崎信长 / 井上麻里奈 / 竹达彩奈 / 富㭴美铃 / 野水伊织 / 真田麻美 / 内田真礼 / 布里德卡特·塞拉·惠美 / 茅原实里 / 远藤绫 / 子安武人 / 佐土原香织 / 胜杏里 / 甲斐田裕子 / 伊藤静 / 置鲇龙太郎 / 中田让治 / 三石琴乃', '元永庆太郎', '', '', '五河士道（岛崎信长 配音）是一位平凡的高中生，一次偶然之中，他邂逅了名为十香（井上麻里奈 配音）的精灵。精灵是来自于异世界的物种，虽然有着足以迷惑人类的可爱外表，却亦拥有着能够毁灭世界的可怕能力。', '全10集 OAD', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 91, 0, 91, 91, '', 0, 0, 7.3, 0, 0, 1731902717, 1731891701, 0, 0, 0, 0, 0.0, '', '406,407,408', '', '', '', '', '', '', '', '<p>五河士道（岛崎信长 配音）是一位平凡的高中生，一次偶然之中，他邂逅了名为十香（井上麻里奈 配音）的精灵。精灵是来自于异世界的物种，虽然有着足以迷惑人类的可爱外表，却亦拥有着能够毁灭世界的可怕能力。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5424B88BEB4D5A0050E978#第02集$MOE5424B88BEB4D5A0050E97B#第03集$MOE5424B88BEB4D5A0050E97A#第04集$MOE5424B88BEB4D5A0050E97D#第05集$MOE5424B88BEB4D5A0050E97C#第06集$MOE5424B88BEB4D5A0050E97F#第07集$MOE5424B88BEB4D5A0050E97E#第08集$MOE5424B88BEB4D5A0050E971#第09集$MOE5424B88BEB4D5A0050E970#第10集$MOE5424B88BEB4D5A0050E879#OAD$MOE5424B88BEB4D5A0050E878$$$第01集$id_XS5424B88BEB4D5A0050E978#第02集$id_XS5424B88BEB4D5A0050E97B#第03集$id_XS5424B88BEB4D5A0050E97A#第04集$id_XS5424B88BEB4D5A0050E97D#第05集$id_XS5424B88BEB4D5A0050E97C#第06集$id_XS5424B88BEB4D5A0050E97F#第07集$id_XS5424B88BEB4D5A0050E97E#第08集$id_XS5424B88BEB4D5A0050E971#第09集$id_XS5424B88BEB4D5A0050E970#第10集$id_XS5424B88BEB4D5A0050E879#OAD$id_XS5424B88BEB4D5A0050E878$$$第01集$id_MOE5424B88BEB4D5A0050E978#第02集$id_MOE5424B88BEB4D5A0050E97B#第03集$id_MOE5424B88BEB4D5A0050E97A#第04集$id_MOE5424B88BEB4D5A0050E97D#第05集$id_MOE5424B88BEB4D5A0050E97C#第06集$id_MOE5424B88BEB4D5A0050E97F#第07集$id_MOE5424B88BEB4D5A0050E97E#第08集$id_MOE5424B88BEB4D5A0050E971#第09集$id_MOE5424B88BEB4D5A0050E970#第10集$id_MOE5424B88BEB4D5A0050E879#OAD$id_MOE5424B88BEB4D5A0050E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (406, 1, 0, 0, '约会大作战3', 'デート・ア・ライブⅢ（2019）', 'yuehuidazuozhan3', 1, 'Y', '', '94448def', '小说改,奇幻,战斗', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2873577795.jpg', '', '', '', '岛崎信长 / 井上麻里奈 / 富㭴美铃 / 竹达彩奈 / 野水伊织 / 真田麻美 / 内田真礼 / 布里德卡特·塞拉·惠美 / 茅原实里 / 置鲇龙太郎 / 伊藤静 / 中田让治 / 远藤绫 / 三石琴乃', '元永庆太郎 / 则座诚 / 山口美浩 / 原田奈奈 / 羽多野浩平 / 佐佐木真哉 / 中村近世 / 岛崎奈奈子 / 铃木吉男 / 秦义人', '', '', '人类遭逢了名为“空间震”的新型灾害。震撼空间、将一切破坏殆尽的这一灾厄，是由于精灵自临界显现而发生的。为了阻止空间震，使人类免遭灾厄而必须采取的措施，是使用武力歼灭精灵，或者是——“与其约会，使其娇羞', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 65, 0, 65, 65, '', 0, 0, 6.6, 0, 0, 1731912829, 1731899421, 0, 0, 0, 0, 0.0, '', '407,408', '', '', '', '', '', '', '', '<p>人类遭逢了名为“空间震”的新型灾害。震撼空间、将一切破坏殆尽的这一灾厄，是由于精灵自临界显现而发生的。为了阻止空间震，使人类免遭灾厄而必须采取的措施，是使用武力歼灭精灵，或者是——“与其约会，使其娇羞”！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0823B88CB14D085F50E978#第02集$MOE0823B88CB14D085F50E97B#第03集$MOE0823B88CB14D085F50E97A#第04集$MOE0823B88CB14D085F50E97D#第05集$MOE0823B88CB14D085F50E97C#第06集$MOE0823B88CB14D085F50E97F#第07集$MOE0823B88CB14D085F50E97E#第08集$MOE0823B88CB14D085F50E971#第09集$MOE0823B88CB14D085F50E970#第10集$MOE0823B88CB14D085F50E879#第11集$MOE0823B88CB14D085F50E878#第12集$MOE0823B88CB14D085F50E87B$$$第01集$id_XS0823B88CB14D085F50E978#第02集$id_XS0823B88CB14D085F50E97B#第03集$id_XS0823B88CB14D085F50E97A#第04集$id_XS0823B88CB14D085F50E97D#第05集$id_XS0823B88CB14D085F50E97C#第06集$id_XS0823B88CB14D085F50E97F#第07集$id_XS0823B88CB14D085F50E97E#第08集$id_XS0823B88CB14D085F50E971#第09集$id_XS0823B88CB14D085F50E970#第10集$id_XS0823B88CB14D085F50E879#第11集$id_XS0823B88CB14D085F50E878#第12集$id_XS0823B88CB14D085F50E87B$$$第01集$id_MOE0823B88CB14D085F50E978#第02集$id_MOE0823B88CB14D085F50E97B#第03集$id_MOE0823B88CB14D085F50E97A#第04集$id_MOE0823B88CB14D085F50E97D#第05集$id_MOE0823B88CB14D085F50E97C#第06集$id_MOE0823B88CB14D085F50E97F#第07集$id_MOE0823B88CB14D085F50E97E#第08集$id_MOE0823B88CB14D085F50E971#第09集$id_MOE0823B88CB14D085F50E970#第10集$id_MOE0823B88CB14D085F50E879#第1