INSERT INTO `mac_vod` VALUES (407, 1, 0, 0, '约会大作战4', 'デート・ア・ライブIV（2022）', 'yuehuidazuozhan4', 1, 'Y', '', 'a20184c', '小说改,奇幻,战斗', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2914932187.jpg', '', '', '', '岛崎信长 / 井上麻里奈 / 真田麻美 / 富㭴美铃 / 竹达彩奈 / 野水伊织 / 内田真礼 / 布里德卡特·塞拉·惠美 / 茅原实里 / 真野步 / 生天目仁美 / 影山灯 / 远藤绫 / 味里 / 子安武人 / 中田让治 / 置鲇龙太郎 / 伊藤静 / 月宫美鸟 / 村井理沙子 / 藏合纱惠子 / 西田望见 / 花守由美里 / 松井惠理子 / 大西沙织 / 三石琴乃', '中川淳 / 神户洋行 / 吉田俊司 / 渡边正彦 / 长滨亘彦 / 西村大树 / 小野田雄亮 / 黑田晃一郎', '', '', '伴随着“空间震”这一前所未有的灾害，出现了一些称为“精灵”的神秘少女，对于拥有压倒性力量、被称为灾难的她们，数十年间，人类从未停止对抗她们的步伐。', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 50, 0, 50, 50, '', 0, 0, 8.3, 0, 0, 1731918431, 1731906798, 0, 0, 0, 0, 0.0, '', '408', '', '', '', '', '', '', '', '<p>伴随着“空间震”这一前所未有的灾害，出现了一些称为“精灵”的神秘少女，对于拥有压倒性力量、被称为灾难的她们，数十年间，人类从未停止对抗她们的步伐。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5025BC89B11D0E144DE8#第02集$MOE5025BC89B11D0E144DEB#第03集$MOE5025BC89B11D0E144DEA#第04集$MOE5025BC89B11D0E144DED#第05集$MOE5025BC89B11D0E144DEC#第06集$MOE5025BC89B11D0E144DEF#第07集$MOE5025BC89B11D0E144DEE#第08集$MOE5025BC89B11D0E144DE1#第09集$MOE5025BC89B11D0E144DE0#第10集$MOE5025BC89B11D0E144CE9#第11集$MOE5025BC89B11D0E144CE8#第12集$MOE5025BC89B11D0E144CEB$$$第01集$id_XS5025BC89B11D0E144DE8#第02集$id_XS5025BC89B11D0E144DEB#第03集$id_XS5025BC89B11D0E144DEA#第04集$id_XS5025BC89B11D0E144DED#第05集$id_XS5025BC89B11D0E144DEC#第06集$id_XS5025BC89B11D0E144DEF#第07集$id_XS5025BC89B11D0E144DEE#第08集$id_XS5025BC89B11D0E144DE1#第09集$id_XS5025BC89B11D0E144DE0#第10集$id_XS5025BC89B11D0E144CE9#第11集$id_XS5025BC89B11D0E144CE8#第12集$id_XS5025BC89B11D0E144CEB$$$第01集$id_MOE5025BC89B11D0E144DE8#第02集$id_MOE5025BC89B11D0E144DEB#第03集$id_MOE5025BC89B11D0E144DEA#第04集$id_MOE5025BC89B11D0E144DED#第05集$id_MOE5025BC89B11D0E144DEC#第06集$id_MOE5025BC89B11D0E144DEF#第07集$id_MOE5025BC89B11D0E144DEE#第08集$id_MOE5025BC89B11D0E144DE1#第09集$id_MOE5025BC89B11D0E144DE0#第10集$id_MOE5025BC89B11D0E144CE9#第11集$id_MOE5025BC89B11D0E144CE8#第12集$id_MOE5025BC89B11D0E144