INSERT INTO `mac_vod` VALUES (416, 1, 0, 0, '刀剑神域外传 Gun Gale Online', 'ソードアート・オンライン オルタナティブ ガンゲイル・オンライン（2018）', 'daojianshenyuwaichuanGunGaleOnline', 1, 'D', '', '209b2aca', '战斗,科幻,冒险', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2915355961.jpg', '', '', '', '楠木灯 / 日笠阳子 / 兴津和幸 / 赤崎千夏', '迫井政行', '', '', '在枪与钢铁的世界“Gun Gale Online”享受着单人游戏的女性玩家·莲。喜欢可爱事物的她，全身清一色的粉红色装备，不断累积游戏经验，并逐渐增强实力。之后，由于某件事而对于PK（玩家狩猎）觉醒了', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 29, 0, 29, 29, '', 0, 0, 7.5, 0, 0, 1732009781, 1731998194, 0, 0, 0, 0, 0.0, '', '417', '', '', '', '', '', '', '', '<p>在枪与钢铁的世界“Gun Gale Online”享受着单人游戏的女性玩家·莲。喜欢可爱事物的她，全身清一色的粉红色装备，不断累积游戏经验，并逐渐增强实力。之后，由于某件事而对于PK（玩家狩猎）觉醒了兴趣的莲沉迷于PK中，并终于到达被人称作“粉红恶魔”的地步。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0327B5DABB480E5850E978#第02集$MOE0327B5DABB480E5850E97B#第03集$MOE0327B5DABB480E5850E97A#第04集$MOE0327B5DABB480E5850E97D#第05集$MOE0327B5DABB480E5850E97C#第06集$MOE0327B5DABB480E5850E97F#第07集$MOE0327B5DABB480E5850E97E#第08集$MOE0327B5DABB480E5850E971#第09集$MOE0327B5DABB480E5850E970#第10集$MOE0327B5DABB480E5850E879#第11集$MOE0327B5DABB480E5850E878#第12集$MOE0327B5DABB480E5850E87B$$$第01集$id_XS0327B5DABB480E5850E978#第02集$id_XS0327B5DABB480E5850E97B#第03集$id_XS0327B5DABB480E5850E97A#第04集$id_XS0327B5DABB480E5850E97D#第05集$id_XS0327B5DABB480E5850E97C#第06集$id_XS0327B5DABB480E5850E97F#第07集$id_XS0327B5DABB480E5850E97E#第08集$id_XS0327B5DABB480E5850E971#第09集$id_XS0327B5DABB480E5850E970#第10集$id_XS0327B5DABB480E5850E879#第11集$id_XS0327B5DABB480E5850E878#第12集$id_XS0327B5DABB480E5850E87B$$$第01集$id_MOE0327B5DABB480E5850E978#第02集$id_MOE0327B5DABB480E5850E97B#第03集$id_MOE0327B5DABB480E5850E97A#第04集$id_MOE0327B5DABB480E5850E97D#第05集$id_MOE0327B5DABB480E5850E97C#第06集$id_MOE0327B5DABB480E5850E97F#第07集$id_MOE0327B5DABB480E5850E97E#第08集$id_MOE0327B5DABB480E5850E971#第09集$id_MOE0327B5DABB480E5850E970#第10集$id_MOE0327B5DABB480E5850E879#第11集$id_MOE0327B5DABB480E5850E878#第12集$id_MOE0327B5DABB480E5850E87