INSERT INTO `mac_vod` VALUES (326, 2, 0, 0, '刀剑神域ExtraEdition', 'ソードアート・オンライン Extra Edition（2013）', 'daojianshenyuExtraEdition', 1, 'D', '', '4d228187', '剧场版', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190898669.jpg', '', '', '', '松冈祯丞 / 户松遥 / 伊藤加奈惠 / 竹达彩奈 / 日高里菜 / 高垣彩阳 / 平田广明 / 安元洋贵 / 井泽诗织 / 森川智之 / 伊藤美纪 / 羽佐间道夫 / 阪脩 / 后藤弘树 / 关智一 / 桧山修之 / 田丸笃志 / 早见沙织 / 游佐浩二 / 大川透 / 山路和弘 / 子安武人 / 高桥伸也 / 三宅健太 / 村濑步 / 矢作纱友里 / 斋藤千和 / 山寺宏一', '伊藤智彦', '', '', '为了想看鲸鱼的结衣，桐人等人一起挑战 ALO 世界的水中任务，但却发现莉法不会游泳的惊愕事实，于是亚丝娜、西莉卡、莉兹贝特等人决定在现实世界的室内游泳池为她做特训…...，而桐人要与某人见面。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 6.9, 0, 0, 1732012629, 1732006007, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>为了想看鲸鱼的结衣，桐人等人一起挑战 ALO 世界的水中任务，但却发现莉法不会游泳的惊愕事实，于是亚丝娜、西莉卡、莉兹贝特等人决定在现实世界的室内游泳池为她做特训…...，而桐人要与某人见面。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0573BE8AB118550E50E978$$$正片$id_MOE0573BE8AB118550E50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (418, 2, 0, 0, '刀剑神域：序列之争', '劇場版 ソードアート・オンライン -オーディナル・スケール-（2017）', 'daojianshenyuxuliezhizheng', 1, 'D', '', 'f4b0c534', '剧场版', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2498371582.jpg', '', '', '', '松冈祯丞 / 户松遥 / 伊藤加奈惠 / 竹达彩奈 / 日高里菜 / 高垣彩阳 / 泽城美雪 / 平田广明 / 安元洋贵 / 井泽诗织 / 木内秀信 / 矢作纱友里 / 斋藤千和 / 三宅健太 / 村濑步 / 岛村侑 / 鹤冈聪 / 松田健一郎 / 明坂聪美 / 朝井彩加 / 石谷春贵 / 井上雄贵 / 迫田孝也 / 相马康一 / 高桥伸也 / 森川智之 / 山寺宏一 / 神田沙也加 / 井上芳雄 / 鹿贺丈史', '伊藤智彦', '', '', '2022年，天才编程者茅场晶彦所开发的世界最早的完全潜行专用装备设备《NERvGear》。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 7.0, 0, 0, 1732014325, 1732008082, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>2022年，天才编程者茅场晶彦所开发的世界最早的完全潜行专用装备设备《NERvGear》。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5723EE88EA1C5E0D50E978$$$正片$id_MOE5723EE88EA1C5E0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (419, 2, 0, 0, '刀剑神域进击篇：无星之夜', '劇場版 ソードアート・オンライン プログレッシブ 星なき夜のアリア（2021）', 'daojianshenyujinjipianwuxingzhiye', 1, 'D', '', '9fe330be', '剧场版', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2666701646.jpg', '', '', '', '松冈祯丞 / 户松遥 / 水濑祈 / 平田广明 / 安元洋贵 / 日高里菜 / 桧山修之 / 关智一', '河野亚矢子 / 小原正和 / 甲斐泰之', '', '', '这是“闪光”与“黑衣剑士”在被如此称呼之前的故事——', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 8.0, 0, 0, 1732024909, 1732008101, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是“闪光”与“黑衣剑士”在被如此称呼之前的故事——</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0871E98BBA190F5C50E978$$$正片$id_MOE0871E98BBA190F5C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (420, 2, 0, 0, '刀剑神域进击篇：暮色黄昏', '劇場版 ソードアート・オンライン プログレッシブ 冥き夕闇のスケルツォ（2022）', 'daojianshenyujinjipianmusehuanghun', 1, 'D', '', 'f73129e1', '剧场版', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2892365943.jpg', '', '', '', '松冈祯丞 / 户松遥 / 井泽诗织 / 水濑祈 / 安元洋贵 / 关智一 / 本渡枫 / 永野由祐 / 大塚刚央 / 高桥伸也 / 阿座上洋平 / 玉井勇辉 / 关幸司 / 逢坂良太 / 小林裕介', '河野亚矢子', '', '', '世界首个VRMMORPG游戏《Sword Art Online》成为了“死亡游戏”。距1万名用户被困在游戏中一事发生，已有一个多月。攻略了钢铁浮游城“艾恩葛朗特”第一层后，亚丝娜继续与桐人搭档，以最顶', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 6.6, 0, 0, 1732024972, 1732008121, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>世界首个VRMMORPG游戏《Sword Art Online》成为了“死亡游戏”。距1万名用户被困在游戏中一事发生，已有一个多月。攻略了钢铁浮游城“艾恩葛朗特”第一层后，亚丝娜继续与桐人搭档，以最顶层为目标继续着旅程。然而，带领玩家攻略游戏的两大精英公会“ALS”（艾恩葛朗特解放队）和“DKB”（龙骑士团）之间爆发了冲突，这背后，有一名神秘人物在暗中行动。在命悬一线的危险战斗中，继“攻略”压力后的另一重“威胁”将桐人和亚丝娜卷入其中。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5720BF89BB10080850E978$$$正片$id_MOE5720BF89BB10080850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (421, 1, 0, 0, '在地下城寻求邂逅是否搞错了什么', '', 'zaidixiachengxunqiuxiehoushifougaocuoliaoshime', 1, 'Z', '', 'ff214053', '架空,小说改,奇幻,战斗', 'https://p2.bahamut.com.tw/B/ACG/c/70/0000073570.JPG', '', '', '', '', '山川吉树', '', '', '迷宫都市欧拉丽，通称「地下城」，是有广大的地下迷宫的巨大都市。名扁未知的兴奋、光辉显赫的荣耀、以及相遇可爱女生的浪漫，在这人们的曹想与欲望交集的城市里，以冒险者扁志愿的少年 具雨遇见了成员扁0人的神明', '全13集 OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 79, 0, 79, 79, '', 0, 0, 9.0, 0, 0, 1732130164, 1732025653, 0, 0, 0, 0, 0.0, '', '422,423,424,425,426', '', '', '', '', '', '', '', '<p>迷宫都市欧拉丽，通称「地下城」，是有广大的地下迷宫的巨大都市。名扁未知的兴奋、光辉显赫的荣耀、以及相遇可爱女生的浪漫，在这人们的曹想与欲望交集的城市里，以冒险者扁志愿的少年 具雨遇见了成员扁0人的神明大人赫斯缇雅，由少年踏出、女神记叙的「眷族物语」的冒险即将展开。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5771BE89BD19580A50E978#第02集$MOE5771BE89BD19580A50E97B#第03集$MOE5771BE89BD19580A50E97A#第04集$MOE5771BE89BD19580A50E97D#第05集$MOE5771BE89BD19580A50E97C#第06集$MOE5771BE89BD19580A50E97F#第07集$MOE5771BE89BD19580A50E97E#第08集$MOE5771BE89BD19580A50E971#第09集$MOE5771BE89BD19580A50E970#第10集$MOE5771BE89BD19580A50E879#第11集$MOE5771BE89BD19580A50E878#第12集$MOE5771BE89BD19580A50E87B#第13集$MOE5771BE89BD19580A50E87A#OVA$MOE5771BE89BD19580A50E87D$$$第01集$id_XS5771BE89BD19580A50E978#第02集$id_XS5771BE89BD19580A50E97B#第03集$id_XS5771BE89BD19580A50E97A#第04集$id_XS5771BE89BD19580A50E97D#第05集$id_XS5771BE89BD19580A50E97C#第06集$id_XS5771BE89BD19580A50E97F#第07集$id_XS5771BE89BD19580A50E97E#第08集$id_XS5771BE89BD19580A50E971#第09集$id_XS5771BE89BD19580A50E970#第10集$id_XS5771BE89BD19580A50E879#第11集$id_XS5771BE89BD19580A50E878#第12集$id_XS5771BE89BD19580A50E87B#第13集$id_XS5771BE89BD19580A50E87A#OVA$id_XS5771BE89BD19580A50E87D$$$第01集$id_MOE5771BE89BD19580A50E978#第02集$id_MOE5771BE89BD19580A50E97B#第03集$id_MOE5771BE89BD19580A50E97A#第04集$id_MOE5771BE89BD19580A50E97D#第05集$id_MOE5771BE89BD19580A50E97C#第06集$id_MOE5771BE89BD19580A50E97F#第07集$id_MOE5771BE89BD19580A50E97E#第08集$id_MOE5771BE89BD19580A50E971#第09集$id_MOE5771BE89BD19580A50E970#第10集$id_MOE5771BE89BD19580A50E879#第11集$id_MOE5771BE89BD19580A50E878#第12集$id_MOE5771BE89BD19580A50E87B#第13集$id_MOE5771BE89BD19580A50E87A#OVA$id_MOE5771BE89BD19580A50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (422, 1, 0, 0, '在地下城寻求邂逅是否搞错了什么 第二季', '', 'zaidixiachengxunqiuxiehoushifougaocuoliaoshimedierji', 1, 'Z', '', '2f40b8f6', '架空,小说改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/cbda2ba01bdc1e99db1f732dd3d2b963789039dc.png', '', '', '', '贝尔·克朗尼：松冈祯丞\n赫斯缇雅：水濑祈\n莉莉露卡·厄德：内田真礼\n韦尔夫·克罗佐：细谷佳正\n倭·命：赤崎千夏\n琉·璃昂：早见沙织\n艾丝·华伦斯坦：大西沙织\n阿伊莎·贝尔卡：渡边明乃\n三条野·春姬：千菅春香\n达芙妮·拉洛斯：小若和郁那\n卡珊德拉·伊利翁：真野步\n雅辛托斯·克里欧：KENN\n阿波罗：逢坂良太', '', '', '', '这座城市住着众多的神，其中心存在着通往地心深处——深渊的“地下城”。城市的名字是迷宫都市欧拉丽。\n女神赫斯缇雅与冒险者贝尔·克朗尼，一如既往地是主神和仅仅一名眷族的最小构成。但达成了世界最快升级这一伟', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 9.0, 0, 0, 1732130235, 1732053594, 0, 0, 0, 0, 0.0, '', '423,424,425', '', '', '', '', '', '', '', '这座城市住着众多的神，其中心存在着通往地心深处——深渊的“地下城”。城市的名字是迷宫都市欧拉丽。\n女神赫斯缇雅与冒险者贝尔·克朗尼，一如既往地是主神和仅仅一名眷族的最小构成。但达成了世界最快升级这一伟业的贝尔，开始受到前所未有的的万众瞩目——\n迷宫中的相遇，以及冒险——这是再次开始编织的，少年所走过的，女神所记录的【眷族物语】', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0371B888EB110B0F50E978#第02集$MOE0371B888EB110B0F50E97B#第03集$MOE0371B888EB110B0F50E97A#第04集$MOE0371B888EB110B0F50E97D#第05集$MOE0371B888EB110B0F50E97C#第06集$MOE0371B888EB110B0F50E97F#第07集$MOE0371B888EB110B0F50E97E#第08集$MOE0371B888EB110B0F50E971#第09集$MOE0371B888EB110B0F50E970#第10集$MOE0371B888EB110B0F50E879#第11集$MOE0371B888EB110B0F50E878#第12集$MOE0371B888EB110B0F50E87B#OVA$MOE0371B888EB110B0F50E87A$$$第01集$id_XS0371B888EB110B0F50E978#第02集$id_XS0371B888EB110B0F50E97B#第03集$id_XS0371B888EB110B0F50E97A#第04集$id_XS0371B888EB110B0F50E97D#第05集$id_XS0371B888EB110B0F50E97C#第06集$id_XS0371B888EB110B0F50E97F#第07集$id_XS0371B888EB110B0F50E97E#第08集$id_XS0371B888EB110B0F50E971#第09集$id_XS0371B888EB110B0F50E970#第10集$id_XS0371B888EB110B0F50E879#第11集$id_XS0371B888EB110B0F50E878#第12集$id_XS0371B888EB110B0F50E87B#OVA$id_XS0371B888EB110B0F50E87A$$$第01集$id_MOE0371B888EB110B0F50E978#第02集$id_MOE0371B888EB110B0F50E97B#第03集$id_MOE0371B888EB110B0F50E97A#第04集$id_MOE0371B888EB110B0F50E97D#第05集$id_MOE0371B888EB110B0F50E97C#第06集$id_MOE0371B888EB110B0F50E97F#第07集$id_MOE0371B888EB110B0F50E97E#第08集$id_MOE0371B888EB110B0F50E971#第09集$id_MOE0371B888EB110B0F50E970#第10集$id_MOE0371B888EB110B0F50E879#第11集$id_MOE0371B888EB110B0F50E878#第12集$id_MOE0371B888EB110B0F50E87B#OVA$id_MOE0371B888EB110B0F50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (423, 1, 0, 0, '在地下城寻求邂逅是否搞错了什么 第三季', '', 'zaidixiachengxunqiuxiehoushifougaocuoliaoshimedisanji', 1, 'Z', '', '625e1ba4', '冒险,架空,奇幻,小说改', 'http://i0.hdslb.com/bfs/bangumi/image/bf8b064feb1384d3ff4436030d7bb270a19c62af.png', '', '', '', '贝尔·克朗尼：松冈祯丞\n赫斯缇雅：水濑祈\n莉莉露卡·厄德：内田真礼\n韦尔夫·克罗佐：细谷佳正\n倭·命：赤崎千夏\n三条野·春姬：千菅春香\n琉·璃昂：早见沙织\n艾丝·华伦斯坦：大西沙织', '橘秀树', '', '', '这座城市住着众多的神，其中心存在着通往地心深处——深渊的“地下城”。城市的名字是迷宫都市欧拉丽。女神赫斯缇雅与冒险者贝尔·克朗尼，一如既往地是主神和仅仅一名眷族的最小构成。但达成了世界最快升级这一伟业', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 58, 0, 58, 58, '', 0, 0, 9.2, 0, 0, 1732130270, 1732080231, 0, 0, 0, 0, 0.0, '', '424,425', '', '', '', '', '', '', '', '这座城市住着众多的神，其中心存在着通往地心深处——深渊的“地下城”。城市的名字是迷宫都市欧拉丽。女神赫斯缇雅与冒险者贝尔·克朗尼，一如既往地是主神和仅仅一名眷族的最小构成。但达成了世界最快升级这一伟业的贝尔，开始受到前所未有的的万众瞩目——迷宫中的相遇，以及冒险——这是再次开始编织的，少年所走过的，女神所记录的【眷族物语】', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0725B9DDB84B0C0D50E978#第02集$MOE0725B9DDB84B0C0D50E97B#第03集$MOE0725B9DDB84B0C0D50E97A#第04集$MOE0725B9DDB84B0C0D50E97D#第05集$MOE0725B9DDB84B0C0D50E97C#第06集$MOE0725B9DDB84B0C0D50E97F#第07集$MOE0725B9DDB84B0C0D50E97E#第08集$MOE0725B9DDB84B0C0D50E971#第09集$MOE0725B9DDB84B0C0D50E970#第10集$MOE0725B9DDB84B0C0D50E879#第11集$MOE0725B9DDB84B0C0D50E878#第12集$MOE0725B9DDB84B0C0D50E87B#OVA$MOE0725B9DDB84B0C0D50E87A$$$第01集$id_XS0725B9DDB84B0C0D50E978#第02集$id_XS0725B9DDB84B0C0D50E97B#第03集$id_XS0725B9DDB84B0C0D50E97A#第04集$id_XS0725B9DDB84B0C0D50E97D#第05集$id_XS0725B9DDB84B0C0D50E97C#第06集$id_XS0725B9DDB84B0C0D50E97F#第07集$id_XS0725B9DDB84B0C0D50E97E#第08集$id_XS0725B9DDB84B0C0D50E971#第09集$id_XS0725B9DDB84B0C0D50E970#第10集$id_XS0725B9DDB84B0C0D50E879#第11集$id_XS0725B9DDB84B0C0D50E878#第12集$id_XS0725B9DDB84B0C0D50E87B#OVA$id_XS0725B9DDB84B0C0D50E87A$$$第01集$id_MOE0725B9DDB84B0C0D50E978#第02集$id_MOE0725B9DDB84B0C0D50E97B#第03集$id_MOE0725B9DDB84B0C0D50E97A#第04集$id_MOE0725B9DDB84B0C0D50E97D#第05集$id_MOE0725B9DDB84B0C0D50E97C#第06集$id_MOE0725B9DDB84B0C0D50E97F#第07集$id_MOE0725B9DDB84B0C0D50E97E#第08集$id_MOE