INSERT INTO `mac_vod` VALUES (68, 1, 0, 0, '女友成堆', 'カノジョも彼女（2021）', 'nvyouchengdui', 1, 'N', '', 'c79d13a2', '校园,恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2641572583.jpg', '', '', '', '榎木淳弥 / 佐仓绫音 / 和气杏未 / 竹达彩奈 / 高桥李依', '桑原智', '', '', '向井直也（榎木淳弥 配音）是一名性格异常认真的男子高中生，认真到有些可笑的地步。从小学1年级起，他就深深的喜欢上了自己的青梅竹马佐木咲（佐仓绫音 配音），并且以每月一次的频率向她告白，均以失败告终。一', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 58, 0, 58, 58, '', 0, 0, 6.6, 0, 0, 1732142861, 1732107839, 0, 0, 0, 0, 0.0, '', '427', '', '', '', '', '', '', '', '<p>向井直也（榎木淳弥 配音）是一名性格异常认真的男子高中生，认真到有些可笑的地步。从小学1年级起，他就深深的喜欢上了自己的青梅竹马佐木咲（佐仓绫音 配音），并且以每月一次的频率向她告白，均以失败告终。一晃眼多年过去，直也和咲都升上了高中，终于，咲答应了直也的告白，成为了他的女友，真是可喜可贺。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5220B5DCB81A0C0B50E978#第02集$MOE5220B5DCB81A0C0B50E97B#第03集$MOE5220B5DCB81A0C0B50E97A#第04集$MOE5220B5DCB81A0C0B50E97D#第05集$MOE5220B5DCB81A0C0B50E97C#第06集$MOE5220B5DCB81A0C0B50E97F#第07集$MOE5220B5DCB81A0C0B50E97E#第08集$MOE5220B5DCB81A0C0B50E971#第09集$MOE5220B5DCB81A0C0B50E970#第10集$MOE5220B5DCB81A0C0B50E879#第11集$MOE5220B5DCB81A0C0B50E878#第12集$MOE5220B5DCB81A0C0B50E87B$$$第01集$id_XS5220B5DCB81A0C0B50E978#第02集$id_XS5220B5DCB81A0C0B50E97B#第03集$id_XS5220B5DCB81A0C0B50E97A#第04集$id_XS5220B5DCB81A0C0B50E97D#第05集$id_XS5220B5DCB81A0C0B50E97C#第06集$id_XS5220B5DCB81A0C0B50E97F#第07集$id_XS5220B5DCB81A0C0B50E97E#第08集$id_XS5220B5DCB81A0C0B50E971#第09集$id_XS5220B5DCB81A0C0B50E970#第10集$id_XS5220B5DCB81A0C0B50E879#第11集$id_XS5220B5DCB81A0C0B50E878#第12集$id_XS5220B5DCB81A0C0B50E87B$$$第01集$id_MOE5220B5DCB81A0C0B50E978#第02集$id_MOE5220B5DCB81A0C0B50E97B#第03集$id_MOE5220B5DCB81A0C0B50E97A#第04集$id_MOE5220B5DCB81A0C0B50E97D#第05集$id_MOE5220B5DCB81A0C0B50E97C#第06集$id_MOE5220B5DCB81A0C0B50E97F#第07集$id_MOE5220B5DCB81A0C0B50E97E#第08集$id_MOE5220B5DCB81A0C0B50E971#第09集$id_MOE5220B5DCB81A0C0B50E970#第10集$id_MOE5220B5DCB81A0C0B50E879#第11集$id_MOE5220B5DCB81A0C0B50E878#第12集$id_MOE5220B5DCB81A0C0B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (428, 2, 0, 0, 'Re：从零开始的异世界生活雪之回忆', 'Re:ゼロから始める異世界生活 Memory Snow（2018）', 'Reconglingkaishideyishijieshenghuoxuezhihuiyi', 1, 'R', '', '7ac3d7e0', '剧场版', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515741354.jpg', '', '', '', '小林裕介 / 高桥李依 / 内山夕实 / 水濑祈 / 村川梨衣 / 新井里美 / 子安武人 / 高野麻里佳 / 小林由美子 / 石上静香 / 筱田南 / 芳野由奈 / 桑原由气 / 木岛隆一', '渡边政治 / 美甘义人 / 古贺一臣', '', '', '昴等人打倒了诅咒的元凶——魔兽沃尔加姆，拯救了阿拉姆村的孩子们。终于到来的安稳并未持续很久，昴就瞒着所有人前去挑战某个极秘任务。但尽管昴做了变装，也很快就被以佩特拉为首的村里的孩子们识破了真实身份。开', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 36, 0, 36, 36, '', 0, 0, 8.2, 0, 0, 1732145061, 1732129888, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>昴等人打倒了诅咒的元凶——魔兽沃尔加姆，拯救了阿拉姆村的孩子们。终于到来的安稳并未持续很久，昴就瞒着所有人前去挑战某个极秘任务。但尽管昴做了变装，也很快就被以佩特拉为首的村里的孩子们识破了真实身份。开始后5秒就曝光的这一任务，是事前调查和爱蜜莉雅约会的路线……</p>', 'xs$$$moe', 'no$$$no', '$$$', 'OVA$id_XS0676EF8BED1E080950E978$$$OVA$id_MOE0676EF8BED1E080950E978', '', '', '', '', 0, '', '');
