INSERT INTO `mac_vod` VALUES (221, 1, 0, 0, '总之就是非常可爱 女子高中篇', 'トニカクカワイイ 女子高編（2023）', 'zongzhijiushifeichangkeainvzigaozhongpian', 1, 'Z', '', '4167a8aa', '漫画改,搞笑,治愈,奇幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2893518515.jpg', '', '', '', '鬼头明里 / 榎木淳弥 / 芹泽优 / 上坂堇 / 上田瞳 / 长江里加 / 松田彩音 / 林鼓子 / 羊宫妃那 / 前田佳织里 / 佐仓绫音', '博史池畠', '', '', '在中学时代的恩师柳老师的请求下，星空被任命为高中教师。但任职地竟然是个女子高中。一边是被活力满满的女高中生们包围的星空，一边是表面冷静，内心不平静的司。', '全4集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 51, 0, 51, 51, '', 0, 0, 8.6, 0, 0, 1732478856, 1732450226, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在中学时代的恩师柳老师的请求下，星空被任命为高中教师。但任职地竟然是个女子高中。一边是被活力满满的女高中生们包围的星空，一边是表面冷静，内心不平静的司。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0526BA8FE8110C5850E978#第02集$MOE0526BA8FE8110C5850E97B#第03集$MOE0526BA8FE8110C5850E97A#第04集$MOE0526BA8FE8110C5850E97D$$$第01集$id_XS0526BA8FE8110C5850E978#第02集$id_XS0526BA8FE8110C5850E97B#第03集$id_XS0526BA8FE8110C5850E97A#第04集$id_XS0526BA8FE8110C5850E97D$$$第01集$id_MOE0526BA8FE8110C5850E978#第02集$id_MOE0526BA8FE8110C5850E97B#第03集$id_MOE0526BA8FE8110C5850E97A#第04集$id_MOE0526BA8FE8110C5850E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (450, 1, 0, 0, '小鸟之翼', 'BIRDIE WING -Golf Girls’ Story-（2022）', 'xiaoniaozhiyi', 1, 'X', '', 'ce1debd1', '运动', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870198438.jpg', '', '', '', '鬼头明里 / 濑户麻沙美 / 小清水亚美 / 关根明良 / 古谷彻 / 池田秀一 / 行成桃姬 / 藤田咲 / 中原麻衣 / 田村由香里 / 小林优 / 市道真央 / 新井里美 / 名冢佳织 / 佐藤利奈 / 甲斐田裕子 / 木下纱华', '稻垣隆行', '', '', '故事发生在一个名为纳弗雷斯的国家之中，伊芙（鬼头明里 配音）是拥有着绝佳技术的天才高尔夫少女，她参加高尔夫比赛的唯一目的就是钱，这项运动实际上并不能给她带来什么真正的快乐。', '全13集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 7.9, 0, 0, 1732491619, 1732473353, 0, 0, 0, 0, 0.0, '', '451', '', '', '', '', '', '', '', '<p>故事发生在一个名为纳弗雷斯的国家之中，伊芙（鬼头明里 配音）是拥有着绝佳技术的天才高尔夫少女，她参加高尔夫比赛的唯一目的就是钱，这项运动实际上并不能给她带来什么真正的快乐。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5272BDDCEC4B090850E978#第02集$MOE5272BDDCEC4B090850E97B#第03集$MOE5272BDDCEC4B090850E97A#第04集$MOE5272BDDCEC4B090850E97D#第05集$MOE5272BDDCEC4B090850E97C#第06集$MOE5272BDDCEC4B090850E97F#第07集$MOE5272BDDCEC4B090850E97E#第08集$MOE5272BDDCEC4B090850E971#第09集$MOE5272BDDCEC4B090850E970#第10集$MOE5272BDDCEC4B090850E879#第11集$MOE5272BDDCEC4B090850E878#第12集$MOE5272BDDCEC4B090850E87B#第13集$MOE5272BDDCEC4B090850E87A$$$第01集$id_XS5272BDDCEC4B090850E978#第02集$id_XS5272BDDCEC4B090850E97B#第03集$id_XS5272BDDCEC4B090850E97A#第04集$id_XS5272BDDCEC4B090850E97D#第05集$id_XS5272BDDCEC4B090850E97C#第06集$id_XS5272BDDCEC4B090850E97F#第07集$id_XS5272BDDCEC4B090850E97E#第08集$id_XS5272BDDCEC4B090850E971#第09集$id_XS5272BDDCEC4B090850E970#第10集$id_XS5272BDDCEC4B090850E879#第11集$id_XS5272BDDCEC4B090850E878#第12集$id_XS5272BDDCEC4B090850E87B#第13集$id_XS5272BDDCEC4B090850E87A$$$第01集$id_MOE5272BDDCEC4B090850E978#第02集$id_MOE5272BDDCEC4B090850E97B#第03集$id_MOE5272BDDCEC4B090850E97A#第04集$id_MOE5272BDDCEC4B090850E97D#第05集$id_MOE5272BDDCEC4B090850E97C#第06集$id_MOE5272BDDCEC4B090850E97F#第07集$id_MOE5272BDDCEC4B090850E97E#第08集$id_MOE5272BDDCEC4B090850E971#第09集$id_MOE5272BDDCEC4B090850E970#第10集$id_MOE5272BDDCEC4B090850E879#第11集$id_MOE52