INSERT INTO `mac_vod` VALUES (157, 1, 0, 0, '魔法使的新娘', '魔法使いの嫁（2017）', 'mofashidexinniang', 1, 'M', '', 'c532e951', '漫画改,奇幻,治愈,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497954989.jpg', '', '', '', '种崎敦美 / 竹内良太 / 内山昂辉 / 远藤绫 / 甲斐田裕子 / 森川智之 / 诹访部顺一 / 浪川大辅 / 日野聪 / 田村睦心 / 大原沙耶香 / 山口胜平 / 村濑步 / 藤原夏海 / 久野美咲 / 朝井彩加 / 石田彰', '长沼范裕 / 野亦则行 / 金森阳子 / 平向智子 / 左藤洋二 / 铃木拓磨 / 二宫壮史 / 荒井省吾 / 河原龙太', '', '', '羽鸟智世（种崎敦美 配音）表面看来只是一个略微冷淡的平凡少女，实际上却隐藏着可怜的身世。年幼时，智世的母亲自杀，父亲离家出走，无处可去的他在十五岁那一年成为了商品被地下拍卖会组织卖给了名为艾利亚斯（竹', '全24集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 8.4, 0, 0, 1732536568, 1732490725, 0, 0, 0, 0, 0.0, '', '171', '', '', '', '', '', '', '', '<p>羽鸟智世（种崎敦美 配音）表面看来只是一个略微冷淡的平凡少女，实际上却隐藏着可怜的身世。年幼时，智世的母亲自杀，父亲离家出走，无处可去的他在十五岁那一年成为了商品被地下拍卖会组织卖给了名为艾利亚斯（竹内良太 配音）的魔法使。其实，智世拥有着夜之宠儿的特殊体质，能够在无意识之中吸收外界所散发的魔力，是十分稀有的物种。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5222BF8AEC10580850E978#第02集$MOE5222BF8AEC10580850E97B#第03集$MOE5222BF8AEC10580850E97A#第04集$MOE5222BF8AEC10580850E97D#第05集$MOE5222BF8AEC10580850E97C#第06集$MOE5222BF8AEC10580850E97F#第07集$MOE5222BF8AEC10580850E97E#第08集$MOE5222BF8AEC10580850E971#第09集$MOE5222BF8AEC10580850E970#第10集$MOE5222BF8AEC10580850E879#第11集$MOE5222BF8AEC10580850E878#第12集$MOE5222BF8AEC10580850E87B#第13集$MOE5222BF8AEC10580850E87A#第14集$MOE5222BF8AEC10580850E87D#第15集$MOE5222BF8AEC10580850E87C#第16集$MOE5222BF8AEC10580850E87F#第17集$MOE5222BF8AEC10580850E87E#第18集$MOE5222BF8AEC10580850E871#第19集$MOE5222BF8AEC10580850E870#第20集$MOE5222BF8AEC10580850EB79#第21集$MOE5222BF8AEC10580850EB78#第22集$MOE5222BF8AEC10580850EB7B#第23集$MOE5222BF8AEC10580850EB7A#第24集$MOE5222BF8AEC10580850EB7D$$$第01集$id_XS5222BF8AEC10580850E978#第02集$id_XS5222BF8AEC10580850E97B#第03集$id_XS5222BF8AEC10580850E97A#第04集$id_XS5222BF8AEC10580850E97D#第05集$id_XS5222BF8AEC10580850E97C#第06集$id_XS5222BF8AEC10580850E97F#第07集$id_XS5222BF8AEC10580850E97E#第08集$id_XS5222BF8AEC10580850E971#第09集$id_XS5222BF8AEC10580850E970#第10集$id_XS5222B