INSERT INTO `mac_vod` VALUES (463, 1, 0, 0, '不死者之王 第四季', 'オーバーロードⅣ（2022）', 'busizhezhiwangdisiji', 1, 'B', '', '6911c5ac', '小说改,奇幻,战斗,架空', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2786009959.jpg', '', '', '', '日野聪 / 原由实 / 上坂堇 / 加藤英美里 / 内山夕实 / 加藤将之 / 三宅健太 / 宫野真守 / 市之濑加那', '伊藤尚往', '', '', '剧情承接上一季，安兹以耶·兰提尔为根据地建立了“安兹·乌尔·恭魔导国”，但却使安兹陷入了烦恼的境地。他作为一个国家的国王，该如何引导这个国家呢？', '全13集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 68, 0, 68, 68, '', 0, 0, 7.8, 0, 0, 1732641066, 1732578904, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>剧情承接上一季，安兹以耶·兰提尔为根据地建立了“安兹·乌尔·恭魔导国”，但却使安兹陷入了烦恼的境地。他作为一个国家的国王，该如何引导这个国家呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE072EBD89EA1C0C5A50E978#第02集$MOE072EBD89EA1C0C5A50E97B#第03集$MOE072EBD89EA1C0C5A50E97A#第04集$MOE072EBD89EA1C0C5A50E97D#第05集$MOE072EBD89EA1C0C5A50E97C#第06集$MOE072EBD89EA1C0C5A50E97F#第07集$MOE072EBD89EA1C0C5A50E97E#第08集$MOE072EBD89EA1C0C5A50E971#第09集$MOE072EBD89EA1C0C5A50E970#第10集$MOE072EBD89EA1C0C5A50E879#第11集$MOE072EBD89EA1C0C5A50E878#第12集$MOE072EBD89EA1C0C5A50E87B#第13集$MOE072EBD89EA1C0C5A50E87A$$$第01集$id_XS072EBD89EA1C0C5A50E978#第02集$id_XS072EBD89EA1C0C5A50E97B#第03集$id_XS072EBD89EA1C0C5A50E97A#第04集$id_XS072EBD89EA1C0C5A50E97D#第05集$id_XS072EBD89EA1C0C5A50E97C#第06集$id_XS072EBD89EA1C0C5A50E97F#第07集$id_XS072EBD89EA1C0C5A50E97E#第08集$id_XS072EBD89EA1C0C5A50E971#第09集$id_XS072EBD89EA1C0C5A50E970#第10集$id_XS072EBD89EA1C0C5A50E879#第11集$id_XS072EBD89EA1C0C5A50E878#第12集$id_XS072EBD89EA1C0C5A50E87B#第13集$id_XS072EBD89EA1C0C5A50E87A$$$第01集$id_MOE072EBD89EA1C0C5A50E978#第02集$id_MOE072EBD89EA1C0C5A50E97B#第03集$id_MOE072EBD89EA1C0C5A50E97A#第04集$id_MOE072EBD89EA1C0C5A50E97D#第05集$id_MOE072EBD89EA1C0C5A50E97C#第06集$id_MOE072EBD89EA1C0C5A50E97F#第07集$id_MOE072EBD89EA1C0C5A50E97E#第08集$id_MOE072EBD89EA1C0C5A50E971#第09集$id_MOE072EBD89EA1C0C5A50E970#第10集$id_MOE072EBD89EA1C0C5A50E879#第11集$id_MOE072EBD89EA1C0C5A50E878#第12集$id_MOE072EBD89EA1C0C5A50E87B#第13集$id_MOE072EBD89EA1C0C5A50E87A',