INSERT INTO `mac_vod` VALUES (199, 1, 0, 0, '虚构推理', '虚構推理（2020）', 'xugoutuili', 1, 'X', '', 'd1c35967', '漫画改,奇幻,神魔,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625651140.jpg', '', '', '', '鬼头明里 / 宫野真守 / 福圆美里 / 上坂堇 / 滨田贤二 / 佐古真弓 / 下山吉光 / 本山香织 / 塙爱美 / 后藤弘树 / 宫田幸季 / 前田玲奈 / 飞田展男', '后藤圭二 / 菅原静贵 / 吉田理纱子 / 山内东生雄', '', '', '深夜，挥舞巨大钢筋袭击人类的亡灵“钢人七濑”。是单纯的都市传说，还是真正的亡灵？给予妖魔鬼怪们智慧的巫女——岩永琴子，与之正面抗衡。为了消灭由人类想象力创造的恐怖妖怪，为了对抗虚构，琴子设下了由虚构组', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 70, 0, 70, 70, '', 0, 0, 7.5, 0, 0, 1732669165, 1732639654, 0, 0, 0, 0, 0.0, '', '464', '', '', '', '', '', '', '', '<p>深夜，挥舞巨大钢筋袭击人类的亡灵“钢人七濑”。是单纯的都市传说，还是真正的亡灵？给予妖魔鬼怪们智慧的巫女——岩永琴子，与之正面抗衡。为了消灭由人类想象力创造的恐怖妖怪，为了对抗虚构，琴子设下了由虚构组成的重重机关。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5526EF8BBC105B0E50E978#第02集$MOE5526EF8BBC105B0E50E97B#第03集$MOE5526EF8BBC105B0E50E97A#第04集$MOE5526EF8BBC105B0E50E97D#第05集$MOE5526EF8BBC105B0E50E97C#第06集$MOE5526EF8BBC105B0E50E97F#第07集$MOE5526EF8BBC105B0E50E97E#第08集$MOE5526EF8BBC105B0E50E971#第09集$MOE5526EF8BBC105B0E50E970#第10集$MOE5526EF8BBC105B0E50E879#第11集$MOE5526EF8BBC105B0E50E878#第12集$MOE5526EF8BBC105B0E50E87B$$$第01集$id_XS5526EF8BBC105B0E50E978#第02集$id_XS5526EF8BBC105B0E50E97B#第03集$id_XS5526EF8BBC105B0E50E97A#第04集$id_XS5526EF8BBC105B0E50E97D#第05集$id_XS5526EF8BBC105B0E50E97C#第06集$id_XS5526EF8BBC105B0E50E97F#第07集$id_XS5526EF8BBC105B0E50E97E#第08集$id_XS5526EF8BBC105B0E50E971#第09集$id_XS5526EF8BBC105B0E50E970#第10集$id_XS5526EF8BBC105B0E50E879#第11集$id_XS5526EF8BBC105B0E50E878#第12集$id_XS5526EF8BBC105B0E50E87B$$$第01集$id_MOE5526EF8BBC105B0E50E978#第02集$id_MOE5526EF8BBC105B0E50E97B#第03集$id_MOE5526EF8BBC105B0E50E97A#第04集$id_MOE5526EF8BBC105B0E50E97D#第05集$id_MOE5526EF8BBC105B0E50E97C#第06集$id_MOE5526EF8BBC105B0E50E97F#第07集$id_MOE5526EF8BBC105B0E50E97E#第08集$id_MOE5526EF8BBC105B0E50E971#第09集$id_MOE5526EF8BBC105B0E50E970#第10集$id_MOE5526EF8BBC105B0E50E879#第11集$id_MOE5526EF8BBC105B0E50E878#第12集$id_MOE5526EF8BBC105B0E50E87B', 