INSERT INTO `mac_vod` VALUES (465, 1, 0, 0, '魔术士欧菲流浪之旅', '', 'moshushioufeiliulangzhilv', 1, 'M', '', '6cdf624f', '小说改,奇幻,战斗,架空', 'http://i0.hdslb.com/bfs/bangumi/image/b4f434a5bc79b094a26aae7dfafef42dca7c1277.jpg', '', '', '', '森久保祥太郎 / 大久保瑠美 / 小林裕介 / 水野麻里绘 / 渊上舞 / 浪川大辅 / 日笠阳子 / 伊藤静 / 坂泰斗 / 安田陆矢 / 前野智昭', '滨名孝行', '', '', '生活在大陆最高级的魔术士养成机关“牙之塔”的奇利男谢洛，是在大陆最强魔术士·查尔德曼的教导下修行学习，并继承了他所有战斗技术和暗杀技术的被称为“钢之继承者”的精英魔术士。\r\n为了寻找在某次实验中变成了异', '全14集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 6.5, 0, 0, 1732709901, 1732657274, 0, 0, 0, 0, 0.0, '', '466,467,468', '', '', '', '', '', '', '', '<p>生活在大陆最高级的魔术士养成机关“牙之塔”的奇利男谢洛，是在大陆最强魔术士·查尔德曼的教导下修行学习，并继承了他所有战斗技术和暗杀技术的被称为“钢之继承者”的精英魔术士。\n为了寻找在某次实验中变成了异形姿态的义姐·阿莎莉，离开了“牙之塔”的奇利男谢洛舍弃了过去，改名为欧菲，在多多坎达市做着非法放贷的营生。他在那里遇到了不请自来的大小姐克丽奥以及少年弟子马吉克，并与他们一起踏上了拯救阿莎莉的旅程。\n与此同时，欧菲遇见了前来讨伐阿莎莉的曾经的师父·查尔德曼与哈帝亚、可米库隆等过去的同伴们，种种思绪交错过后，欧菲还是决定走上自己选择的道路。\n欧菲一行人穿越了芬里尔之森，赶往塔弗雷姆。终于，他们抵达了欧菲曾经修行的地方“牙之塔”所在的城市。在那里等待着欧菲他们的是，超乎想象的强大敌人。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0774E8DEBF1B595F50E978#第02集$MOE0774E8DEBF1B595F50E97B#第03集$MOE0774E8DEBF1B595F50E97A#第04集$MOE0774E8DEBF1B595F50E97D#第05集$MOE0774E8DEBF1B595F50E97C#第06集$MOE0774E8DEBF1B595F50E97F#第07集$MOE0774E8DEBF1B595F50E97E#第08集$MOE0774E8DEBF1B595F50E971#第09集$MOE0774E8DEBF1B595F50E970#第10集$MOE0774E8DEBF1B595F50E879#第11集$MOE0774E8DEBF1B595F50E878#第12集$MOE0774E8DEBF1B595F50E87B#第13集$MOE0774E8DEBF1B595F50E87A#第14集$MOE0774E8DEBF1B595F50E87D$$$第01集$id_XS0774E8DEBF1B595F50E978#第02集$id_XS0774E8DEBF1B595F50E97B#第03集$id_XS0774E8DEBF1B595F50E97A#第04集$id_XS0774E8DEBF1B595F50E97D#第05集$id_XS0774E8DEBF1B595F50E97C#第06集$id_XS0774E8DEBF1B595F50E97F#第07集$id_XS0774E8DEBF1B595F50E97E#第08集$id_XS0774E8DEBF1B595F50E971#第09集$id_XS0774E8DEBF1B595F50E970#第10集$id_XS0774E8DEBF1B595F50E879#第11集$id_XS0774E8DEBF1B595F50E878#第12集$id_XS0774E8DEBF1B595F50E87B#第13集$id_XS0774E8DEBF1B595F50E87A#第14集$id_XS0774E8DEBF1B595F50E87D$$$第01集$id_MOE0774E8DEBF1B595F50E978#第02集$id_MOE0774E8DEBF1B595F50E97B#第03集$id_MOE0774E8DEBF1B595F50E97A#第04集$id_MOE0774E8DEBF1B595F50E97D#第05集$id_MOE0774E8DEBF1B595F50E97C#第06集$id_MOE0774E8DEBF1B595F50E97F#第07集$id_MOE0774E8DEBF1B595F50E97E#第08集$id_MOE0774E8DEBF1B595F50E971#第09集$id_MOE0774E8DEBF1B595F50E970#第10集$id_MOE0774E8DEBF1B595F50E879#第11集$id_MOE0774E8DEBF1B595F50E878#第12集$id_MOE0774E8DEBF1B595F50E87B#第13集$id_MOE0774E8DEBF1B595F50E87A#第14集$id_MOE0774E8DEBF1B595F50E87D', '', '', '', '', 0, '', '');
