INSERT INTO `mac_vod` VALUES (468, 1, 0, 0, '魔术士欧菲流浪之旅 圣域篇', '魔術士オーフェンはぐれ旅 聖域編（2023）', 'moshushioufeiliulangzhilvshengyupian', 1, 'M', '', '5a07cbe3', '小说改,奇幻,战斗,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2890195158.jpg', '', '', '', '森久保祥太郎 / 大久保瑠美 / 安元洋贵 / 日野聪 / 金田朋子 / 石田彰 / 日笠阳子 / 小林裕介 / 水野まりえ / 渊上舞 / 小野大辅 / 青木志贵 / 榎木淳弥 / 江口拓也', '滨名孝行', '', '', 'TVアニメ「魔術士オーフェンはぐれ旅 聖域編」が2023年4月に放送決定。キービジュアルと追加キャストが公開された。', '全12集', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 0.0, 0, 0, 1732717412, 1732657339, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>TVアニメ「魔術士オーフェンはぐれ旅 聖域編」が2023年4月に放送決定。キービジュアルと追加キャストが公開された。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0476BC8FEA4B080A50E978#第02集$MOE0476BC8FEA4B080A50E97B#第03集$MOE0476BC8FEA4B080A50E97A#第04集$MOE0476BC8FEA4B080A50E97D#第05集$MOE0476BC8FEA4B080A50E97C#第06集$MOE0476BC8FEA4B080A50E97F#第07集$MOE0476BC8FEA4B080A50E97E#第08集$MOE0476BC8FEA4B080A50E971#第09集$MOE0476BC8FEA4B080A50E970#第10集$MOE0476BC8FEA4B080A50E879#第11集$MOE0476BC8FEA4B080A50E878#第12集$MOE0476BC8FEA4B080A50E87B$$$第01集$id_XS0476BC8FEA4B080A50E978#第02集$id_XS0476BC8FEA4B080A50E97B#第03集$id_XS0476BC8FEA4B080A50E97A#第04集$id_XS0476BC8FEA4B080A50E97D#第05集$id_XS0476BC8FEA4B080A50E97C#第06集$id_XS0476BC8FEA4B080A50E97F#第07集$id_XS0476BC8FEA4B080A50E97E#第08集$id_XS0476BC8FEA4B080A50E971#第09集$id_XS0476BC8FEA4B080A50E970#第10集$id_XS0476BC8FEA4B080A50E879#第11集$id_XS0476BC8FEA4B080A50E878#第12集$id_XS0476BC8FEA4B080A50E87B$$$第01集$id_MOE0476BC8FEA4B080A50E978#第02集$id_MOE0476BC8FEA4B080A50E97B#第03集$id_MOE0476BC8FEA4B080A50E97A#第04集$id_MOE0476BC8FEA4B080A50E97D#第05集$id_MOE0476BC8FEA4B080A50E97C#第06集$id_MOE0476BC8FEA4B080A50E97F#第07集$id_MOE0476BC8FEA4B080A50E97E#第08集$id_MOE0476BC8FEA4B080A50E971#第09集$id_MOE0476BC8FEA4B080A50E970#第10集$id_MOE0476BC8FEA4B080A50E879#第11集$id_MOE0476BC8FEA4B080A50E878#第12集$id_MOE0476BC8FEA4B080A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (168, 1, 0, 0, '被众神捡到的男孩', '神達に拾われた男（2020）', 'beizhongshenjiandaodenanhai', 1, 'B', '', 'b87946ba', '奇幻,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616711332.jpg', '', '', '', '田所梓 / 早见沙织 / 子安武人 / 桑原由气 / 小野大辅 / 高野麻里佳 / 清川元梦 / 井上喜久子 / 小市真琴 / 安元洋贵 / 古川慎', '柳濑雄之', '', '', '平凡上班族竹林龙马（田所梓 配音）几乎没有过过一天舒心日子，39岁了还孑然一身，在黑心企业里为贪心的老板做牛做马。终于，在狭窄又潮湿的单身公寓里，他的生命走到了尽头，然而当龙马再度睁开眼时，发现自己竟', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 5.8, 0, 0, 1732717762, 1732709164, 0, 0, 0, 0, 0.0, '', '210', '', '', '', '', '', '', '', '<p>平凡上班族竹林龙马（田所梓 配音）几乎没有过过一天舒心日子，39岁了还孑然一身，在黑心企业里为贪心的老板做牛做马。终于，在狭窄又潮湿的单身公寓里，他的生命走到了尽头，然而当龙马再度睁开眼时，发现自己竟然转生来到了异世界中，成为了一名年仅8岁的少年。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE532FBB81BD1F0F5850E978#第02集$MOE532FBB81BD1F0F5850E97B#第03集$MOE532FBB81BD1F0F5850E97A#第04集$MOE532FBB81BD1F0F5850E97D#第05集$MOE532FBB81BD1F0F5850E97C#第06集$MOE532FBB81BD1F0F5850E97F#第07集$MOE532FBB81BD1F0F5850E97E#第08集$MOE532FBB81BD1F0F5850E971#第09集$MOE532FBB81BD1F0F5850E970#第10集$MOE532FBB81BD1F0F5850E879#第11集$MOE532FBB81BD1F0F5850E878#第12集$MOE532FBB81BD1F0F5850E87B$$$第01集$id_XS532FBB81BD1F0F5850E978#第02集$id_XS532FBB81BD1F0F5850E97B#第03集$id_XS532FBB81BD1F0F5850E97A#第04集$id_XS532FBB81BD1F0F5850E97D#第05集$id_XS532FBB81BD1F0F5850E97C#第06集$id_XS532FBB81BD1F0F5850E97F#第07集$id_XS532FBB81BD1F0F5850E97E#第08集$id_XS532FBB81BD1F0F5850E971#第09集$id_XS532FBB81BD1F0F5850E970#第10集$id_XS532FBB81BD1F0F5850E879#第11集$id_XS532FBB81BD1F0F5850E878#第12集$id_XS532FBB81BD1F0F5850E87B$$$第01集$id_MOE532FBB81BD1F0F5850E978#第02集$id_MOE532FBB81BD1F0F5850E97B#第03集$id_MOE532FBB81BD1F0F5850E97A#第04集$id_MOE532FBB81BD1F0F5850E97D#第05集$id_MOE532FBB81BD1F0F5850E97C#第06集$id_MOE532FBB81BD1F0F5850E97F#第07集$id_MOE532FBB81BD1F0F5850E97E#第08集$id_MOE532FBB81BD1F0F5850E971#第09集$id_MOE532FBB81BD1F0F5850E970#第10集$id_MOE532FBB81BD1F0F5850E879#第11集$id_MOE532FBB81BD1F0F5850E878#第12集$id_MOE532FBB81BD1F0F5850E87B', 