INSERT INTO `mac_vod` VALUES (474, 1, 0, 0, '王者天下', 'キングダム（2012）', 'wangzhetianxia', 1, 'W', '', '7f814097', '历史,战争', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1566425703.jpg', '', '', '', '森田成一 / 福山润 / 钉宫理惠 / 日笠阳子 / 小山力也', '神谷纯', '', '', '时值纪元前——至此未曾经历大一统的中原大陆，正处于长达500年的春秋战国时代。主角是生于严苛的战乱之世的少年——信，他是秦国境内一个立志成为大将军的年轻人，却因故卷入春秋战国的秦国宫廷内斗(秦始皇幼年', '全38集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 50, 0, 50, 50, '', 0, 0, 8.1, 0, 0, 1732955389, 1732835486, 0, 0, 0, 0, 0.0, '', '475,476,477,481', '', '', '', '', '', '', '', '<p>时值纪元前——至此未曾经历大一统的中原大陆，正处于长达500年的春秋战国时代。主角是生于严苛的战乱之世的少年——信，他是秦国境内一个立志成为大将军的年轻人，却因故卷入春秋战国的秦国宫廷内斗(秦始皇幼年时期) 。他将以一己之力于天下留名！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0671B489BD19540E50E978#第02集$MOE0671B489BD19540E50E97B#第03集$MOE0671B489BD19540E50E97A#第04集$MOE0671B489BD19540E50E97D#第05集$MOE0671B489BD19540E50E97C#第06集$MOE0671B489BD19540E50E97F#第07集$MOE0671B489BD19540E50E97E#第08集$MOE0671B489BD19540E50E971#第09集$MOE0671B489BD19540E50E970#第10集$MOE0671B489BD19540E50E879#第11集$MOE0671B489BD19540E50E878#第12集$MOE0671B489BD19540E50E87B#第13集$MOE0671B489BD19540E50E87A#第14集$MOE0671B489BD19540E50E87D#第15集$MOE0671B489BD19540E50E87C#第16集$MOE0671B489BD19540E50E87F#第17集$MOE0671B489BD19540E50E87E#第18集$MOE0671B489BD19540E50E871#第19集$MOE0671B489BD19540E50E870#第20集$MOE0671B489BD19540E50EB79#第21集$MOE0671B489BD19540E50EB78#第22集$MOE0671B489BD19540E50EB7B#第23集$MOE0671B489BD19540E50EB7A#第24集$MOE0671B489BD19540E50EB7D#第25集$MOE0671B489BD19540E50EB7C#第26集$MOE0671B489BD19540E50EB7F#第27集$MOE0671B489BD19540E50EB7E#第28集$MOE0671B489BD19540E50EB71#第29集$MOE0671B489BD19540E50EB70#第30集$MOE0671B489BD19540E50EA79#第31集$MOE0671B489BD19540E50EA78#第32集$MOE0671B489BD19540E50EA7B#第33集$MOE0671B489BD19540E50EA7A#第34集$MOE0671B489BD19540E50EA7D#第35集$MOE0671B489BD19540E50EA7C#第36集$MOE0671B489BD19540E50EA7F#第37集$MOE0671B489BD19540E50EA7E#第38集$MOE0671B489BD19540E50EA71$$$第01集$id_XS0671B489BD19540E50E978#第02集$id_XS0671B489BD19540E5