INSERT INTO `mac_vod` VALUES (476, 1, 0, 0, '王者天下 第三季', 'キングダム 第3シリーズ（2020）', 'wangzhetianxiadisanji', 1, 'W', '', '3151b801', '历史,战争', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2589161322.jpg', '', '', '', '森田成一 / 福山润 / 钉宫理惠 / 斋藤志郎 / 楠大典 / 加藤亮夫 / 伊藤健太郎 / 堀内贤雄 / 细谷佳正 / 野岛裕史 / 森川智之 / 内田夕夜 / 田中敦子 / 田中美央 / 浪川大辅 / 铃木达央 / 上村祐翔', '今泉贤一', '', '', '纪元前，在中国西方的秦国，年轻的千人将·信曾与已故的好友有着「天下的大将军」这一共同的梦想，而至今仍以此为目标。 此时，秦国成功攻陷了军事上最重要的据点山阳，并由此向中华统一又迈进了一步。但，对于可能', '全26集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.1, 0, 0, 1732968487, 1732835545, 0, 0, 0, 0, 0.0, '', '477,481', '', '', '', '', '', '', '', '<p>纪元前，在中国西方的秦国，年轻的千人将·信曾与已故的好友有着「天下的大将军」这一共同的梦想，而至今仍以此为目标。 此时，秦国成功攻陷了军事上最重要的据点山阳，并由此向中华统一又迈进了一步。但，对于可能改写七国势力图的这一手感到危机感的赵国天才军师·李牧，以楚国宰相·春申君为总大将，楚、赵、魏、燕、韩、齐六国兴起合纵军，开始进攻秦国！ 面对前所未有的危机，秦国集结所拥有的全部武力，迎击合纵军！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0226B989EB115D0850E978#第02集$MOE0226B989EB115D0850E97B#第03集$MOE0226B989EB115D0850E97A#第04集$MOE0226B989EB115D0850E97D#第05集$MOE0226B989EB115D0850E97C#第06集$MOE0226B989EB115D0850E97F#第07集$MOE0226B989EB115D0850E97E#第08集$MOE0226B989EB115D0850E971#第09集$MOE0226B989EB115D0850E970#第10集$MOE0226B989EB115D0850E879#第11集$MOE0226B989EB115D0850E878#第12集$MOE0226B989EB115D0850E87B#第13集$MOE0226B989EB115D0850E87A#第14集$MOE0226B989EB115D0850E87D#第15集$MOE0226B989EB115D0850E87C#第16集$MOE0226B989EB115D0850E87F#第17集$MOE0226B989EB115D0850E87E#第18集$MOE0226B989EB115D0850E871#第19集$MOE0226B989EB115D0850E870#第20集$MOE0226B989EB115D0850EB79#第21集$MOE0226B989EB115D0850EB78#第22集$MOE0226B989EB115D0850EB7B#第23集$MOE0226B989EB115D0850EB7A#第24集$MOE0226B989EB115D0850EB7D#第25集$MOE0226B989EB115D0850EB7C#第26集$MOE0226B989EB115D0850EB7F$$$第01集$id_XS0226B989EB115D0850E978#第02集$id_XS0226B989EB115D0850E97B#第03集$id_XS0226B989EB115D0850E97A#第04集$id_XS0226B989EB115D0850E97D#第05集$id_XS0226B989EB115D0850E97C#第06集$id_XS0226B989EB115D0850E97F#第07集$id_XS0226B989EB115D0850E97E#第08集$id_XS0226B989EB115D08