INSERT INTO `mac_vod` VALUES (477, 1, 0, 0, '王者天下 第四季', 'キングダム 第4シリーズ（2022）', 'wangzhetianxiadisiji', 1, 'W', '', '867ca164', '历史,战争', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2868431099.jpg', '', '', '', '森田成一 / 福山润 / 钉宫理惠 / 日笠阳子 / 宫田幸季 / 玄田哲章 / 诹访部顺一 / 仲野裕 / 伊藤健太郎 / 楠大典 / 加藤亮夫 / 堀内贤雄 / 伊藤和晃 / 细谷佳正 / 野岛裕史 / 森川智之 / 浪川大辅 / 田中敦子', '今泉贤一', '', '', '嬴政は、函谷関攻防戦で自らの才を証明してみせ、まもなく行われる成人の儀式「加冠の儀」において、国内外に向け自らが「第31代秦王」であることを宣言し、国の実権を取り戻すことを誓う。しかし、中華全土を巻き', '全26集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.1, 0, 0, 1732990230, 1732835564, 0, 0, 0, 0, 0.0, '', '481', '', '', '', '', '', '', '', '<p>嬴政は、函谷関攻防戦で自らの才を証明してみせ、まもなく行われる成人の儀式「加冠の儀」において、国内外に向け自らが「第31代秦王」であることを宣言し、国の実権を取り戻すことを誓う。しかし、中華全土を巻き込んだ戦いは、攻め込まれた秦国も、合従軍に参加した国々にも大きな爪痕を残した。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0921BBDBE8185B0D50E978#第02集$MOE0921BBDBE8185B0D50E97B#第03集$MOE0921BBDBE8185B0D50E97A#第04集$MOE0921BBDBE8185B0D50E97D#第05集$MOE0921BBDBE8185B0D50E97C#第06集$MOE0921BBDBE8185B0D50E97F#第07集$MOE0921BBDBE8185B0D50E97E#第08集$MOE0921BBDBE8185B0D50E971#第09集$MOE0921BBDBE8185B0D50E970#第10集$MOE0921BBDBE8185B0D50E879#第11集$MOE0921BBDBE8185B0D50E878#第12集$MOE0921BBDBE8185B0D50E87B#第13集$MOE0921BBDBE8185B0D50E87A#第14集$MOE0921BBDBE8185B0D50E87D#第15集$MOE0921BBDBE8185B0D50E87C#第16集$MOE0921BBDBE8185B0D50E87F#第17集$MOE0921BBDBE8185B0D50E87E#第18集$MOE0921BBDBE8185B0D50E871#第19集$MOE0921BBDBE8185B0D50E870#第20集$MOE0921BBDBE8185B0D50EB79#第21集$MOE0921BBDBE8185B0D50EB78#第22集$MOE0921BBDBE8185B0D50EB7B#第23集$MOE0921BBDBE8185B0D50EB7A#第24集$MOE0921BBDBE8185B0D50EB7D#第25集$MOE0921BBDBE8185B0D50EB7C#第26集$MOE0921BBDBE8185B0D50EB7F$$$第01集$id_XS0921BBDBE8185B0D50E978#第02集$id_XS0921BBDBE8185B0D50E97B#第03集$id_XS0921BBDBE8185B0D50E97A#第04集$id_XS0921BBDBE8185B0D50E97D#第05集$id_XS0921BBDBE8185B0D50E97C#第06集$id_XS0921BBDBE8185B0D50E97F#第07集$id_XS0921BBDBE8185B0D50E97E#第08集$id_XS0921BBDBE8185B0D50E971#第09集$id_XS0921BBDBE8185B0D50E970#第10集$id_XS0921BBDBE8