INSERT INTO `mac_vod` VALUES (479, 1, 0, 0, '五等分的新娘 第二季', '五等分の花嫁∬（2021）', 'wudengfendexinniangdierji', 1, 'W', '', 'e61fbbd5', '漫画改,恋爱,校园,日常', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2621588088.jpg', '', '', '', '松冈祯丞 / 花泽香菜 / 竹达彩奈 / 伊藤美来 / 佐仓绫音 / 水濑祈 / 高森奈津美 / 日野聪 / 黑田崇矢', '小森香织', '', '', '上杉风太郎（松冈祯丞 配音）是就读于高中二年级的平凡男生，唯一的亮点就是学习方面异常的优秀，每次考试都能得到满分。上杉的家境非常的贫穷，欠下了巨额债务，为了还债，上杉不得不开始勤工俭学，受中野一家人的', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 104, 0, 104, 104, '', 0, 0, 8.5, 0, 0, 1732921111, 1732897688, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>上杉风太郎（松冈祯丞 配音）是就读于高中二年级的平凡男生，唯一的亮点就是学习方面异常的优秀，每次考试都能得到满分。上杉的家境非常的贫穷，欠下了巨额债务，为了还债，上杉不得不开始勤工俭学，受中野一家人的聘用，成为了中野家五姐妹的家庭教师。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5421BDDEEB4B090C50E978#第02集$MOE5421BDDEEB4B090C50E97B#第03集$MOE5421BDDEEB4B090C50E97A#第04集$MOE5421BDDEEB4B090C50E97D#第05集$MOE5421BDDEEB4B090C50E97C#第06集$MOE5421BDDEEB4B090C50E97F#第07集$MOE5421BDDEEB4B090C50E97E#第08集$MOE5421BDDEEB4B090C50E971#第09集$MOE5421BDDEEB4B090C50E970#第10集$MOE5421BDDEEB4B090C50E879#第11集$MOE5421BDDEEB4B090C50E878#第12集$MOE5421BDDEEB4B090C50E87B$$$第01集$id_XS5421BDDEEB4B090C50E978#第02集$id_XS5421BDDEEB4B090C50E97B#第03集$id_XS5421BDDEEB4B090C50E97A#第04集$id_XS5421BDDEEB4B090C50E97D#第05集$id_XS5421BDDEEB4B090C50E97C#第06集$id_XS5421BDDEEB4B090C50E97F#第07集$id_XS5421BDDEEB4B090C50E97E#第08集$id_XS5421BDDEEB4B090C50E971#第09集$id_XS5421BDDEEB4B090C50E970#第10集$id_XS5421BDDEEB4B090C50E879#第11集$id_XS5421BDDEEB4B090C50E878#第12集$id_XS5421BDDEEB4B090C50E87B$$$第01集$id_MOE5421BDDEEB4B090C50E978#第02集$id_MOE5421BDDEEB4B090C50E97B#第03集$id_MOE5421BDDEEB4B090C50E97A#第04集$id_MOE5421BDDEEB4B090C50E97D#第05集$id_MOE5421BDDEEB4B090C50E97C#第06集$id_MOE5421BDDEEB4B090C50E97F#第07集$id_MOE5421BDDEEB4B090C50E97E#第08集$id_MOE5421BDDEEB4B090C50E971#第09集$id_MOE5421BDDEEB4B090C50E970#第10集$id_MOE5421BDDEEB4B090C50E879#第11集$id_MOE5421BDDEEB4B090C50E878#第12集$id_MOE5421BDDEEB4B090C50E87B', '', '', '', '',