INSERT INTO `mac_vod` VALUES (480, 2, 0, 0, '五等分的新娘剧场版', '映画 五等分の花嫁（2022）', 'wudengfendexinniangjuchangban', 1, 'W', '', '61802039', '剧场版', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2869548961.jpg', '', '', '', '松冈祯丞 / 花泽香菜 / 竹达彩奈 / 伊藤美来 / 佐仓绫音 / 水濑祈', '神保昌登', '', '', '「濒临留级」、「讨厌念书」的五胞胎美少女，', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 148, 0, 148, 148, '', 0, 0, 8.7, 0, 0, 1732921120, 1732897755, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「濒临留级」、「讨厌念书」的五胞胎美少女，</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0726B488BB195E0050E978$$$正片$id_MOE0726B488BB195E0050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (262, 1, 0, 0, '黑执事', '', 'heizhishi', 1, 'H', '', 'd443fb41', '漫画改', 'http://i0.hdslb.com/bfs/bangumi/ffcbbb5536dee729d14413a840556a8a4fbcdd6c.jpg', '', '', '', '坂本真绫 / 小野大辅 / 诹访部顺一 / 东地宏树 / 梶裕贵 / 加藤英美里 / 藤村俊二 / 田村由香里 / 朴璐美 / 福山润 / 游佐浩二', '筱原俊哉 / 津田尚克 / 小仓宏文 / 吉村爱 / 下司泰弘 / 筑紫大介 / 铃木健太郎 / 长滨亘彦 / 市村彻夫 / 大久保富彦', '', '', '时值19世纪，在英国名门贵族凡多姆海伍家，有一位神秘、优雅、十全十美的执事，他就是“黑执事” 塞巴斯蒂安。虽然塞巴斯蒂安总是淡淡地说： “我只是一名执事罢了”，但举止、知识、品味、料理、武术等等没有任', '全24集 OVA', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 54, 0, 54, 54, '', 0, 0, 9.8, 0, 0, 1733005157, 1732930154, 0, 0, 0, 0, 0.0, '', '482,483,484', '', '', '', '', '', '', '', '<p>时值19世纪，在英国名门贵族凡多姆海伍家，有一位神秘、优雅、十全十美的执事，他就是“黑执事” 塞巴斯蒂安。虽然塞巴斯蒂安总是淡淡地说： “我只是一名执事罢了”，但举止、知识、品味、料理、武术等等没有任何事能难得倒他！塞巴斯蒂安的主人，是年仅12 岁就位居凡多姆海伍家族的当主--夏尔。夏尔不仅只花了短短3年的时间，就让凡多姆公司成为英国最大的零食玩具制造商，更在台面下为女王执行秘密任务，因此又被称为“邪恶贵族”！塞巴斯蒂安除了负责照顾夏尔的日常生活起居之外，还得帮成事不足、败事有余的家仆们收拾善后。最重要的是，塞巴斯蒂安必须因应夏尔各种任性的要求，优雅达成不可能的任务！“身为 凡多姆海恩家的执事，怎能连这点小事也办不到？”为了主人夏尔，塞巴斯蒂安将尽心服侍、实现主人所有的愿望。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5523B88BEF4B590850E978#第02集$MOE5523B88BEF4B590850E97B#第03集$MOE5523B88BEF4B590850E97A#第04集$MOE5523B88BEF4B590850E97D#第05集$MOE5523B88BEF4B590850E97C#第06集$MOE5523B88BEF4B590850E97F#第07集$MOE5523B88BEF4B590850E97E#第08集$MOE5523B88BEF4B590850E971#第09集$MOE5523B88BEF4B590850E970#第10集$MOE5523B88BEF4B590850E879#第11集$MOE5523B88BEF4B590850E878#第12集$MOE5523B88BEF4B590850E87B#第13集$MOE5523B88BEF4B590850E87A#第14集$MOE5523B88BEF4B590850E87D#第15集$MOE5523B88BEF4B590850E87C#第16集$MOE5523B88BEF4B590850E87F#第17集$MOE5523B88BEF4B590850E87E#第18集$MOE5523B88BEF4B590850E871#第19集$MOE5523B88BEF4B590850E870#第20集$MOE5523B88BEF4B590850EB79#第21集$MOE5523B88BEF4B590850EB78#第22集$MOE5523B88BEF4B590850EB7B#第23集$MOE5523B88BEF4B590850EB7A#第24集$MOE5523B88BEF4B590850EB7D#OVA$MOE5523B88BEF4B590850EB7C$$$第01集$id_XS5523B88BEF4B590850E978#第02集$id_XS5523B88BEF4B590850E97B#第03集$id_XS5523B88BEF4B590850E97A#第04集$id_XS5523B88BEF4B590850E97D#第05集$id_XS5523B88