INSERT INTO `mac_vod` VALUES (483, 1, 0, 0, '黑执事：马戏团篇', '黒執事 Book of Circus（2014）', 'heizhishimaxituanpian', 1, 'H', '', '34e085b', '漫画改', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2185468491.jpg', '', '', '', '小野大辅 / 坂本真绫 / 宫野真守 / 高垣彩阳 / 甲斐田裕子 / 冈本信彦 / 寺岛拓笃 / 东地宏树 / 梶裕贵 / 加藤英美里 / 藤村俊二 / 杉山纪彰 / 大桥贤一郎 / 福山润 / 立花慎之介 / 安元洋贵 / 田村由香里 / 游佐浩二 / 矢作纱友里 / 诹访部顺一 / 菅沼久义', '阿部记之 / 所智一 / 小坂春女 / 政木伸一 / 飞田刚 / 熨斗谷充孝', '', '', '凡多姆海恩家族的宅邸内百花齐放，黑执事塞巴斯蒂安•米卡利斯（小野大辅 配音）进退有节，优雅矜持地招待来访的客人。而庄园的主人夏尔（坂本真绫 配音）则在田中（藤村俊二 配音）、梅琳（加藤英美里 配音）、', '全10集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 8.7, 0, 0, 1733025969, 1732968963, 0, 0, 0, 0, 0.0, '', '484', '', '', '', '', '', '', '', '<p>凡多姆海恩家族的宅邸内百花齐放，黑执事塞巴斯蒂安•米卡利斯（小野大辅 配音）进退有节，优雅矜持地招待来访的客人。而庄园的主人夏尔（坂本真绫 配音）则在田中（藤村俊二 配音）、梅琳（加藤英美里 配音）、菲尼（梶裕贵 配音）等仆从的环绕下度过平凡舒适的每一天。这一日，夏尔收到了维多利亚女王的来信。信中称名叫诺亚方舟的马戏团即将巡回来到他们所在的城市，而该马戏团所到之处必然会发生儿童失踪事件。作为“女王的看门狗”，夏尔责无旁贷担负起调查的重任。几经周折，夏尔和塞巴斯蒂安成功混入马戏团，他们在这里见到了各种各样生活在底层的可怜人，同时也发现了寻常难以察觉的可怕黑幕……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0223E988B11C0F144DE8#第02集$MOE0223E988B11C0F144DEB#第03集$MOE0223E988B11C0F144DEA#第04集$MOE0223E988B11C0F144DED#第05集$MOE0223E988B11C0F144DEC#第06集$MOE0223E988B11C0F144DEF#第07集$MOE0223E988B11C0F144DEE#第08集$MOE0223E988B11C0F144DE1#第09集$MOE0223E988B11C0F144DE0#第10集$MOE0223E988B11C0F144CE9$$$第01集$id_XS0223E988B11C0F144DE8#第02集$id_XS0223E988B11C0F144DEB#第03集$id_XS0223E988B11C0F144DEA#第04集$id_XS0223E988B11C0F144DED#第05集$id_XS0223E988B11C0F144DEC#第06集$id_XS0223E988B11C0F144DEF#第07集$id_XS0223E988B11C0F144DEE#第08集$id_XS0223E988B11C0F144DE1#第09集$id_XS0223E988B11C0F144DE0#第10集$id_XS0223E988B11C0F144CE9$$$第01集$id_MOE0223E988B11C0F144DE8#第02集$id_MOE0223E988B11C0F144DEB#第03集$id_MOE0223E988B11C0F144DEA#第04集$id_MOE0223E988B11C0F144DED#第05集$id_MOE0223E988B11C0F144DEC#第06集$id_MOE0223E988B11C0F144DEF#第07集$id_MOE0223E988B11C0F144DEE#第08集$id_MOE0223E988B11C0F144DE1#第09集$id_MOE0223E988B11C0F144DE0#第10集$id_MOE0223E988B11C0F144CE9', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (367, 1, 0, 0, '黑执事OVA：幽鬼城杀人事件篇', '黒執事 Book of Murder（2014）', 'heizhishiOVAyouguichengsharenshijianpianshangjuan', 1, 'H', '', '320a4446', '漫画改', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190940108.jpg', '', '', '', '小野大辅 / 坂本真绫 / 加藤英美里 / 梶裕贵 / 东地宏树 / 藤村俊二 / 立花慎之介 / 安元洋贵 / 田村由香里 / 游佐浩二 / 矢作纱友里 / 诹访部顺一 / 木村良平 / 前野智昭 / 浅沼晋太郎', '阿部记之', '', '', '19世纪的英国，以13岁小小年龄便成为凡多姆海恩家族的掌门人并被人称为“邪恶贵族”的夏尔（坂本真绫 配音），在集上佳才学、智慧、武功、料理、气质于一身的完美而毒舌的黑执事塞巴斯蒂安•米卡利斯（小野大辅', '全2集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 8.7, 0, 0, 1733035171, 1733017898, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>19世纪的英国，以13岁小小年龄便成为凡多姆海恩家族的掌门人并被人称为“邪恶贵族”的夏尔（坂本真绫 配音），在集上佳才学、智慧、武功、料理、气质于一身的完美而毒舌的黑执事塞巴斯蒂安•米卡利斯（小野大辅 配音）的陪伴下，度过平静的每一天。这一日，凡多姆海恩家族举行了一次盛大的聚会，名不见经传的作家亚瑟（浅沼晋太郎 配音）在会场上遭遇了杀人事件。作为主人的夏尔遭到嫌疑犯的指控，而几经周折揭开谜团的塞巴斯蒂安竟然面临丧失性命的危险……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '前篇$MOE0225BCD9BD1D590F50E978#后篇$MOE0225BCD9BD1D590F50E97B$$$前篇$id_XS0225BCD9BD1D590F50E978#后篇$id_XS0225BCD9BD1D590F50E97B$$$前篇$id_MOE0225BCD9BD1D590F50E978#后篇$id_MOE0225BCD9BD1D590F50E97B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (485, 2, 0, 0, '黑执事：豪华客船篇', '黒執事 Book of the Atlantic（2017）', 'heizhishihaohuakechuanpian', 1, 'H', '', 'ca6b2ef6', '剧场版', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497235921.jpg', '', '', '', '小野大辅 / 坂本真绫 / 诹访部顺一 / 福山润 / 大桥贤一郎 / 杉山纪彰 / 田村由香里 / 山下诚一郎 / 田中敦子 / 中田让治 / 石川界人 / 铃木达央 / 寺岛拓笃 / 木村良平 / 前野智昭 / 游佐浩二 / 朴璐美 / 东地宏树 / 梶裕贵 / 加藤英美里 / 藤村俊二 / 濑田宏美 / 宫本茉奈 / 花藤莲 / 增元拓也 / 榊孝辅 / 今村一志洋 / 野坂尚也 / 阿部薮一 / 佐原诚 / 有村百惠 / 伊波奈奈 / 君岛哲 / 工藤雅久 / 高宫彩织 / 堤义光 / 西乡彩香 ', '阿部记之', '', '', '19世纪的英国，名门贵族凡多姆海威家的执事塞巴斯蒂安·米卡利斯跟随着13岁的主人夏尔·凡多姆海威作为“女王的番犬”每天都背负着黑社会的肮脏工作。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 8.7, 0, 0, 1733035307, 1733018093, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>19世纪的英国，名门贵族凡多姆海威家的执事塞巴斯蒂安·米卡利斯跟随着13岁的主人夏尔·凡多姆海威作为“女王的番犬”每天都背负着黑社会的肮脏工作。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5276BADABB4C0B0F50E978$$$正片$id_MOE5276BADABB4C0B0F50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (271, 1, 0, 0, '新 福星小子', 'うる星やつら（2022）', 'xinfuxingxiaozi', 1, 'X', '', '50abe794', '科幻,恋爱', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2886232020.jpg', '', '', '', '上坂堇 / 神谷浩史 / 内田真礼 / 宫野真守 / 高木涉 / 泽城美雪 / 花泽香菜 / 小西克幸 / 早见沙织 / 石上静香 / 水树奈奈 / 三宅健太 / 樱井孝宏 / 井上麻里奈 / 古川登志夫 / 户田惠子 / 小山力也 / 平野文', '高桥秀弥 Takahashi Hideya / 木村泰大 Kimura Yasuhiro / 龟井隆广 Kamei Takahiro', '', '', '友引高中二年级4班的学生诸星当，堪称史上最好色的男子，虽然有青梅竹马的阿忍，但他仍然四处搭讪，为了美女命都可以不顾。某天外星鬼族入侵地球，鬼族首领要求双方各派出一名代表，通过赛跑决定地球的命运。一向厄', '全23集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 8.2, 0, 0, 1733055460, 1733024520, 0, 0, 0, 0, 0.0, '', '486', '', '', '', '', '', '', '', '<p>友引高中二年级4班的学生诸星当，堪称史上最好色的男子，虽然有青梅竹马的阿忍，但他仍然四处搭讪，为了美女命都可以不顾。某天外星鬼族入侵地球，鬼族首领要求双方各派出一名代表，通过赛跑决定地球的命运。一向厄运缠身的阿当成了当之无愧的中彩者，鬼族则派出首领的女儿——身穿比基尼，吊眼梢，会飞会放电的小美女拉姆。这场重要的比赛最终以阿当获胜告终，而拉姆却爱上了这个不着调的对手。从此，他们的命运被紧紧联系在一起，也由此引发了一系列神奇、爆笑、感人的小故事……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0427EDDAEC1E540D50E978#第02集$MOE0427EDDAEC1E540D50E97B#第03集$MOE0427EDDAEC1E540D50E97A#第04集$MOE0427EDDAEC1E540D50E97D#第05集$MOE0427EDDAEC1E540D50E97C#第06集$MOE0427EDDAEC1E540D50E97F#第07集$MOE0427EDDAEC1E540D50E97E#第08集$MOE0427EDDAEC1E540D50E971#第09集$MOE0427EDDAEC1E540D50E970#第10集$MOE0427EDDAEC1E540D50E879#第11集$MOE0427EDDAEC1E540D50E878#第12集$MOE0427EDDAEC1E540D50E87B#第13集$MOE0427EDDAEC1E540D50E87A#第14集$MOE0427EDDAEC1E540D50E87D#第15集$MOE0427EDDAEC1E540D50E87C#第16集$MOE0427EDDAEC1E540D50E87F#第17集$MOE0427EDDAEC1E540D50E87E#第18集$MOE0427EDDAEC1E540D50E871#第19集$MOE0427EDDAEC1E540D50E870#第20集$MOE0427EDDAEC1E540D50EB79#第21集$MOE0427EDDAEC1E540D50EB78#第22集$MOE0427EDDAEC1E540D50EB7B#第23集$MOE0427EDDAEC1E540D50EB7A$$$第01集$id_XS0427EDDAEC1E540D50E978#第02集$id_XS0427EDDAEC1E540D50E97B#第03集$id_XS0427EDDAEC1E540D50E97A#第04集$id_XS0427EDDAEC1E540D50E97D#第05集$id_XS0427EDDAEC1E540D50E97C#第06集$id_XS0427EDDAEC1E540D50E97F#第07集$id_XS0427EDDAEC1E540D50E97E#第08集$id_XS0427EDDAEC1E540D50E971#第09集$id_X