INSERT INTO `mac_vod` VALUES (489, 1, 0, 0, '摇曳露营△', 'ゆるキャン△（2018）', 'yaoyeluying', 1, 'Y', '', 'b3f9c7f3', '漫画改,治愈,搞笑,日常', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508739716.jpg', '', '', '', '花守由美里 / 东山奈央 / 原纱友里 / 丰崎爱生 / 高桥李依 / 井上麻里奈 / 松田利冴 / 川澄绫子 / 伊藤静 / 国立幸 / 水桥香织 / 山本希望 / 大畑伸太郎 / 大塚明夫', '京极义昭 / 金子伸吾 / 则座诚 / 岩崎太郎 / 长滨亘彦 / 矢花馨 / 山崎雄太 / 小松达彦 / 镰仲史阳', '', '', '这是，某个冬日的故事。 女高中生抚子刚从静冈搬家到山梨，为了观赏“绘制在千元纸币上的”富士山，骑着自行车来到本栖湖。但不巧天气是阴天，没能看到富士山，抚子累得当场躺下睡着了。当她醒过来的时候，时间已是', '全12集 SP', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 51, 0, 51, 51, '', 0, 0, 9.4, 0, 0, 1733120955, 1733070167, 0, 0, 0, 0, 0.0, '', '490,491', '', '', '', '', '', '', '', '<p>这是，某个冬日的故事。 女高中生抚子刚从静冈搬家到山梨，为了观赏“绘制在千元纸币上的”富士山，骑着自行车来到本栖湖。但不巧天气是阴天，没能看到富士山，抚子累得当场躺下睡着了。当她醒过来的时候，时间已是深夜。在第一次到达的地方，早已忘记了回家的路途。一个爱好露营的女孩子凛，向不安胆怯的抚子伸出了援手。为了温暖冻僵的身体，两人点燃了篝火。噼啪噼啪的柴火爆音，在静寂的湖畔显得沁人心脾。围着篝火，抚子和凛一边捧着咖喱面一边对话。终于，两人期盼已久的瞬间到来了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5324EA81EA1E0B0A50E978#第02集$MOE5324EA81EA1E0B0A50E97B#第03集$MOE5324EA81EA1E0B0A50E97A#第04集$MOE5324EA81EA1E0B0A50E97D#第05集$MOE5324EA81EA1E0B0A50E97C#第06集$MOE5324EA81EA1E0B0A50E97F#第07集$MOE5324EA81EA1E0B0A50E97E#第08集$MOE5324EA81EA1E0B0A50E971#第09集$MOE5324EA81EA1E0B0A50E970#第10集$MOE5324EA81EA1E0B0A50E879#第11集$MOE5324EA81EA1E0B0A50E878#第12集$MOE5324EA81EA1E0B0A50E87B#SP01$MOE5324EA81EA1E0B0A50E87A#SP02$MOE5324EA81EA1E0B0A50E87D#SP03$MOE5324EA81EA1E0B0A50E87C$$$第01集$id_XS5324EA81EA1E0B0A50E978#第02集$id_XS5324EA81EA1E0B0A50E97B#第03集$id_XS5324EA81EA1E0B0A50E97A#第04集$id_XS5324EA81EA1E0B0A50E97D#第05集$id_XS5324EA81EA1E0B0A50E97C#第06集$id_XS5324EA81EA1E0B0A50E97F#第07集$id_XS5324EA81EA1E0B0A50E97E#第08集$id_XS5324EA81EA1E0B0A50E971#第09集$id_XS5324EA81EA1E0B0A50E970#第10集$id_XS5324EA81EA1E0B0A50E879#第11集$id_XS5324EA81EA1E0B0A50E878#第12集$id_XS5324EA81EA1E0B0A50E87B#SP01$id_XS5324EA81EA1E0B0A50E87A#SP02$id_XS5324EA81EA1E0B0A50E87D#SP03$id_XS5324EA81EA1E0B0A50E87C$$$第01集$id_MOE5324EA81EA1E0B0A50E978#第02集$id_MOE