INSERT INTO `mac_vod` VALUES (490, 1, 0, 0, '摇曳露营△ 第二季', 'ゆるキャン△ SEASON 2（2021）', 'yaoyeluyingdierji', 1, 'Y', '', 'd27fad05', '漫画改,治愈,搞笑,日常', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2628004719.jpg', '', '', '', '花守由美里 / 东山奈央 / 原纱友里 / 丰崎爱生 / 高桥李依 / 黑泽朋世 / 伊藤静 / 井上麻里奈 / 松田利冴 / 水桥香织 / 樱井孝宏 / 大塚明夫', '京极义昭 / 岩崎太郎 / 金子伸吾', '', '', '这也是，某个冬日的故事。山梨的女高中生志摩凛，乘着钟爱的机车一路前往滨名湖。从除夕这天开始，久违了的单人露营。从山梨出发前往静冈县磐田。在磐田迎来新年，今天则是第三天。虽然行驶了相当长的距离，但仍然感', '全13集 SP', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.5, 0, 0, 1733126370, 1733070564, 0, 0, 0, 0, 0.0, '', '491', '', '', '', '', '', '', '', '<p>这也是，某个冬日的故事。山梨的女高中生志摩凛，乘着钟爱的机车一路前往滨名湖。从除夕这天开始，久违了的单人露营。从山梨出发前往静冈县磐田。在磐田迎来新年，今天则是第三天。虽然行驶了相当长的距离，但仍然感觉很开心。就在此时，停靠在海边的凛忽然想道「果然，我还是很喜欢单人露营啊」</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5525BBDEE84D5D0C50E978#第02集$MOE5525BBDEE84D5D0C50E97B#第03集$MOE5525BBDEE84D5D0C50E97A#第04集$MOE5525BBDEE84D5D0C50E97D#第05集$MOE5525BBDEE84D5D0C50E97C#第06集$MOE5525BBDEE84D5D0C50E97F#第07集$MOE5525BBDEE84D5D0C50E97E#第08集$MOE5525BBDEE84D5D0C50E971#第09集$MOE5525BBDEE84D5D0C50E970#第10集$MOE5525BBDEE84D5D0C50E879#第11集$MOE5525BBDEE84D5D0C50E878#第12集$MOE5525BBDEE84D5D0C50E87B#第13集$MOE5525BBDEE84D5D0C50E87A#SP01$MOE5525BBDEE84D5D0C50E87D#SP02$MOE5525BBDEE84D5D0C50E87C$$$第01集$id_XS5525BBDEE84D5D0C50E978#第02集$id_XS5525BBDEE84D5D0C50E97B#第03集$id_XS5525BBDEE84D5D0C50E97A#第04集$id_XS5525BBDEE84D5D0C50E97D#第05集$id_XS5525BBDEE84D5D0C50E97C#第06集$id_XS5525BBDEE84D5D0C50E97F#第07集$id_XS5525BBDEE84D5D0C50E97E#第08集$id_XS5525BBDEE84D5D0C50E971#第09集$id_XS5525BBDEE84D5D0C50E970#第10集$id_XS5525BBDEE84D5D0C50E879#第11集$id_XS5525BBDEE84D5D0C50E878#第12集$id_XS5525BBDEE84D5D0C50E87B#第13集$id_XS5525BBDEE84D5D0C50E87A#SP01$id_XS5525BBDEE84D5D0C50E87D#SP02$id_XS5525BBDEE84D5D0C50E87C$$$第01集$id_MOE5525BBDEE84D5D0C50E978#第02集$id_MOE5525BBDEE84D5D0C50E97B#第03集$id_MOE5525BBDEE84D5D0C50E97A#第04集$id_MOE5525BBDEE84D5D0C50E97D#第05集$id_MOE5525BBDEE84D5D0C50E97C#第06集$