INSERT INTO `mac_vod` VALUES (510, 1, 0, 0, '进击的巨人 最终季', '進撃の巨人 The Final Season（2020）', 'jinjidejurenzuizhongji', 1, 'J', '', '118fd80e', '动作,冒险,战争', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2605274206.jpg', '', '', '', '梶裕贵 / 石川由依 / 井上麻里奈 / 三上枝织 / 下野纮 / 小林优 / 谷山纪章 / 细谷佳正 / 朴璐美 / 神谷浩史 / 子安武人 / 花江夏树 / 佐仓绫音 / 沼仓爱美 / 增田俊树 / 村濑步 / / 小野贤章 / 榎木淳弥 / 渡边明乃 / 斋贺光希 / 井上和彦 / 齐藤次郎 / 花轮英司', '林祐一郎 / 宇田钢之助 / 山崎光惠 / 森邦宏 / 宍户淳 / 德土大介 / 平向智子 / 牧田佳织 / 下司泰弘 / 大峰辉之 / 茉田哲明 / 高桥英俊 / 曹毅 / 杨烈骏', '', '', '在艾伦他们居住的帕拉迪岛之外，还存在一个其他人类居住的世界。当中一个国家「玛雷」与其他各国爆发战争。陷入苦战之际，他们决定要攻进帕拉迪岛，把「始祖的巨人」抢过来。在这里又看到另一群孩子们拼命求生存的身', '全28集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 149, 0, 149, 149, '', 0, 0, 9.4, 0, 0, 1733338749, 1733258023, 0, 0, 0, 0, 0.0, '', '511', '', '', '', '', '', '', '', '<p>在艾伦他们居住的帕拉迪岛之外，还存在一个其他人类居住的世界。当中一个国家「玛雷」与其他各国爆发战争。陷入苦战之际，他们决定要攻进帕拉迪岛，把「始祖的巨人」抢过来。在这里又看到另一群孩子们拼命求生存的身影……。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0026B4DEED115D5C50E978#第02集$MOE0026B4DEED115D5C50E97B#第03集$MOE0026B4DEED115D5C50E97A#第04集$MOE0026B4DEED115D5C50E97D#第05集$MOE0026B4DEED115D5C50E97C#第06集$MOE0026B4DEED115D5C50E97F#第07集$MOE0026B4DEED115D5C50E97E#第08集$MOE0026B4DEED115D5C50E971#第09集$MOE0026B4DEED115D5C50E970#第10集$MOE0026B4DEED115D5C50E879#第11集$MOE0026B4DEED115D5C50E878#第12集$MOE0026B4DEED115D5C50E87B#第13集$MOE0026B4DEED115D5C50E87A#第14集$MOE0026B4DEED115D5C50E87D#第15集$MOE0026B4DEED115D5C50E87C#第16集$MOE0026B4DEED115D5C50E87F#第17集$MOE0026B4DEED115D5C50E87E#第18集$MOE0026B4DEED115D5C50E871#第19集$MOE0026B4DEED115D5C50E870#第20集$MOE0026B4DEED115D5C50EB79#第21集$MOE0026B4DEED115D5C50EB78#第22集$MOE0026B4DEED115D5C50EB7B#第23集$MOE0026B4DEED115D5C50EB7A#第24集$MOE0026B4DEED115D5C50EB7D#第25集$MOE0026B4DEED115D5C50EB7C#第26集$MOE0026B4DEED115D5C50EB7F#第27集$MOE0026B4DEED115D5C50EB7E#第28集$MOE0026B4DEED115D5C50EB71$$$第01集$id_XS0026B4DEED115D5C50E978#第02集$id_XS0026B4DEED115D5C50E97B#第03集$id_XS0026B4DEED115D5C50E97A#第04集$id_XS0026B4DEED115D5C50E97D#第05集$id_XS0026B