INSERT INTO `mac_vod` VALUES (525, 1, 0, 0, '某科学的超电磁炮S', '', 'moukexuedechaodiancipaoS', 1, 'M', '', '2d97b8d8', '校园,战斗,奇幻,科幻', 'https://i0.hdslb.com/bfs/bangumi/image/090d4aa97754d1d80206e461eb633b28b9deed07.jpg', '', '', '', '佐藤利奈 / 新井里美 / 丰崎爱生 / 伊藤加奈惠 / 阿部敦 / 冈本信彦 / 佐佐木望 / 野水伊织 / 寿美菜子 / 户松遥 / 南条爱乃 / 植田佳奈 / 福圆美里 / 柚木凉香 / 浅仓杏美 / 津田美波 / 花泽香菜 / 佐藤聪美 / 竹达彩奈 / 麻仓桃 / 木户衣吹 / 山崎遥 / 川原庆久 / 川田绅司 / 仲野裕 / 生天目仁美 / 甲斐田裕子 / 远藤绫 / 林和良 / 铃木达央 / 沼仓爱美 / 金元寿子 / 叶山郁美 / 间岛淳司 / 小清水亚美 / 内田真礼 / 洲崎绫 /', '长井龙雪 / 笠井贤一 / 后藤圭二 / 樱美胜志 / 铃木洋平 / 绀野直幸 / 石川健介 / 石井和彦 / 高岛大辅 / 园田雅裕 / 池端隆史 / 羽多野浩平', '', '', '《科学超电磁炮（とある科学の超电磁炮）》是以镰池和马所著作的轻小说《魔法禁书目录》的人气角色御坂美琴为主角所作的外传漫画，由冬川基作画，连载于月刊Comic电击大王，至2009年12月已经累计销售18', '全24集 OVA', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 9.7, 0, 0, 1733534649, 1733443330, 0, 0, 0, 0, 0.0, '', '526', '', '', '', '', '', '', '', '<p>《科学超电磁炮（とある科学の超电磁炮）》是以镰池和马所著作的轻小说《魔法禁书目录》的人气角色御坂美琴为主角所作的外传漫画，由冬川基作画，连载于月刊Comic电击大王，至2009年12月已经累计销售180万部。2009年10月改编为电视动画，共25集（24集 番外篇1集），由J.C.STAFF制作。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0373B58FEB11090150E978#第02集$MOE0373B58FEB11090150E97B#第03集$MOE0373B58FEB11090150E97A#第04集$MOE0373B58FEB11090150E97D#第05集$MOE0373B58FEB11090150E97C#第06集$MOE0373B58FEB11090150E97F#第07集$MOE0373B58FEB11090150E97E#第08集$MOE0373B58FEB11090150E971#第09集$MOE0373B58FEB11090150E970#第10集$MOE0373B58FEB11090150E879#第11集$MOE0373B58FEB11090150E878#第12集$MOE0373B58FEB11090150E87B#第13集$MOE0373B58FEB11090150E87A#第14集$MOE0373B58FEB11090150E87D#第15集$MOE0373B58FEB11090150E87C#第16集$MOE0373B58FEB11090150E87F#第17集$MOE0373B58FEB11090150E87E#第18集$MOE0373B58FEB11090150E871#第19集$MOE0373B58FEB11090150E870#第20集$MOE0373B58FEB11090150EB79#第21集$MOE0373B58FEB11090150EB78#第22集$MOE0373B58FEB11090150EB7B#第23集$MOE0373B58FEB11090150EB7A#第24集$MOE0373B58FEB11090150EB7D#OVA$MOE0373B58FEB11090150EB7C$$$第01集$id_XS0373B58FEB11090150E978#第02集$id_XS0373B58FEB11090150E97B#第03集$id_XS0373B58FEB11090150E97A#第04集$id_XS0373B58FEB1