INSERT INTO `mac_vod` VALUES (527, 1, 0, 0, '某科学的一方通行', '', 'moukexuedeyifangtongxing', 1, 'M', '', 'e2706481', '漫画改,科幻,战斗,魔法', 'http://i0.hdslb.com/bfs/bangumi/ade6781efe9cdfd7e40cba2d6e34381287efa634.jpg', '', '', '', '冈本信彦 / 日高里菜 / 久保由利香 / 渡部纱弓 / 甲斐田裕子 / 逢坂良太 / 真野步', '镰仲史阳', '', '', '位于东京西部的巨大“学园都市”。 \r\n在总人口达230万人，其中约8成是学生的这座都市中，实施着超能力开发的特殊课程，学生们的能力被给予从“无能力Level 0”到“超能力Level 5”的六阶段评价。', '全12集 SP', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 1, 17, 17, '', 0, 0, 6.7, 0, 0, 1733541569, 1733443381, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>位于东京西部的巨大“学园都市”。 \n在总人口达230万人，其中约8成是学生的这座都市中，实施着超能力开发的特殊课程，学生们的能力被给予从“无能力Level 0”到“超能力Level 5”的六阶段评价。 \n在这样的学园都市君临能力者顶点的最强能力者·一方通行。他在仅有7人的“超能力者”当中也以远超其他人的能力位居第一。不断重复、脱离常轨的“实验”，以及在追求绝对力量的最后品尝到的败北。在那之后，随着与一位少女——最后之作的相遇，他的命运产生了巨大变化。 \n最强而最凶的“恶”——一方通行， \n扫平学园都市的“黑暗”!!</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5425BB88BF1D550850E978#第02集$MOE5425BB88BF1D550850E97B#第03集$MOE5425BB88BF1D550850E97A#第04集$MOE5425BB88BF1D550850E97D#第05集$MOE5425BB88BF1D550850E97C#第06集$MOE5425BB88BF1D550850E97F#第07集$MOE5425BB88BF1D550850E97E#第08集$MOE5425BB88BF1D550850E971#第09集$MOE5425BB88BF1D550850E970#第10集$MOE5425BB88BF1D550850E879#第11集$MOE5425BB88BF1D550850E878#第12集$MOE5425BB88BF1D550850E87B#SP$MOE5425BB88BF1D550850E87A$$$第01集$id_XS5425BB88BF1D550850E978#第02集$id_XS5425BB88BF1D550850E97B#第03集$id_XS5425BB88BF1D550850E97A#第04集$id_XS5425BB88BF1D550850E97D#第05集$id_XS5425BB88BF1D550850E97C#第06集$id_XS5425BB88BF1D550850E97F#第07集$id_XS5425BB88BF1D550850E97E#第08集$id_XS5425BB88BF1D550850E971#第09集$id_XS5425BB88BF1D550850E970#第10集$id_XS5425BB88BF1D550850E879#第11集$id_XS5425BB88BF1D550850E878#第12集$id_XS5425BB88BF1D550850E87B#SP$id_XS5425BB88BF1D550850E87A$$$第01集$id_MOE5425BB88BF1D550850E978#第02集$id_MOE5425BB88BF1D550850E97B#第03集$id_MOE5425BB88BF1D550850E97A#第04集$id_MOE5425BB88BF1D550850E97D#第05集$id_MOE5425BB88BF1D550850E97C#第06集$id_MOE5425BB88BF1D550850E97F#第07集$id_MOE5425BB88BF1D550850E97E#第08集$id_MOE5425BB88BF1D550850E971#第09集$id_MOE5425BB88BF1D550850E970#第10集$id_MOE5425BB88BF1D550850E879#第11集$id_MOE5425BB88BF1D550850E878#第12集$id_MOE5425BB88BF1D550850E87B#SP$id_MOE5425BB88BF1D550850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (528, 1, 0, 0, '辉夜大小姐想让我告白～天才们的恋爱头脑战～', '', 'huiyedaxiaojiexiangrangwogaobaitiancaimendelianaitounaozhan', 1, 'H', '', '63e1b9ef', '恋爱,智斗,校园,搞笑', 'http://i0.hdslb.com/bfs/bangumi/451037aabcdce0379752e087720673609894161a.png', '', '', '', '古贺葵 / 古川慎 / 小原好美 / 铃木崚汰 / 花守由美里 / 青山穰 / 麻仓桃 / 八代拓 / 铃代纱弓 / 子安武人', '畠山守 / 小原正和 / 飞田刚 / 久保太郎 / 宇都宫正记', '', '', '家庭背景与人品都很棒！！一大群有前途的秀才所聚集的秀知院学园！！在那里的学生会相遇的副会长·四宫辉夜与会长·白银御行原本应该是彼此受到了对方吸引…但想不到都过半年了却仍然什么事情也没发生！！最麻烦的是', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 44, 0, 44, 44, '', 0, 0, 9.8, 0, 0, 1733576873, 1733539238, 0, 0, 0, 0, 0.0, '', '529,530,531', '', '', '', '', '', '', '', '<p>家庭背景与人品都很棒！！一大群有前途的秀才所聚集的秀知院学园！！在那里的学生会相遇的副会长·四宫辉夜与会长·白银御行原本应该是彼此受到了对方吸引…但想不到都过半年了却仍然什么事情也没发生！！最麻烦的是这两个自尊心超强、无法坦率的家伙，居然开始想着要“设法让对方向自己告白”！？\n直到恋情有下落之前会很欢乐的故事！！新感觉“斗智”爱情喜剧、就此开战！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0724E989EB10085F50E978#第02集$MOE0724E989EB10085F50E97B#第03集$MOE0724E989EB10085F50E97A#第04集$MOE0724E989EB10085F50E97D#第05集$MOE0724E989EB10085F50E97C#第06集$MOE0724E989EB10085F50E97F#第07集$MOE0724E989EB10085F50E97E#第08集$MOE0724E989EB10085F50E971#第09集$MOE0724E989EB10085F50E970#第10集$MOE0724E989EB10085F50E879#第11集$MOE0724E989EB10085F50E878#第12集$MOE0724E989EB10085F50E87B$$$第01集$id_XS0724E989EB10085F50E978#第02集$id_XS0724E989EB10085F50E97B#第03集$id_XS0724E989EB10085F50E97A#第04集$id_XS0724E989EB10085F50E97D#第05集$id_XS0724E989EB10085F50E97C#第06集$id_XS0724E989EB10085F50E97F#第07集$id_XS0724E989EB10085F50E97E#第08集$id_XS0724E989EB10085F50E971#第09集$id_XS0724E989EB10085F50E970#第10集$id_XS0724E989EB10085F50E879#第11集$id_XS0724E989EB10085F50E878#第12集$id_XS0724E989EB10085F50E87B$$$第01集$id_MOE0724E989EB10085F50E978#第02集$id_MOE0724E989EB10085F50E97B#第03集$id_MOE0724E989EB10085F50E97A#第04集$id_MOE0724E989EB10085F50E97D#第05集$id_MOE0724E989EB10085F50E97C#第06集$id_MOE0724E989EB10085F50E97F#第07集$id_MOE0724E989EB10085F50E97E#第08集$id_MOE0724E989EB10085F50E971#第09集$id_MOE0724E989EB10085F50E970#第10集$id_MOE0724E989EB10085F50E879#第11集$id_MOE0724E989EB10085F50E878#第12集$id_MOE0724E989EB10085F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (529, 1, 0, 0, '辉夜大小姐想让我告白？～天才们的恋爱头脑战～', '', 'huiyedaxiaojiexiangrangwogaobaitiancaimendelianaitounaozhan', 1, 'H', '', '48709601', '恋爱,漫画改,搞笑,校园', 'http://i0.hdslb.com/bfs/bangumi/image/83ad052250e9a803e4ebaa47bef971cb079e0543.png', '', '', '', '古贺葵 / 古川慎 / 小原好美 / 铃木崚汰 / 富田美忧 / 铃代纱弓 / 花守由美里 / 日高里菜', '畠山守', '', '', '秀才所聚集的名校·秀知院学园，在那里的学生会相遇的副会长·四宫辉夜与会长·白银御行，是任何人都认为适合对方的两个天才，原以为他们马上就能交往了，但他们因为自尊心超强一直没能告白！！在“如何让对方告白”', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 33, 0, 33, 33, '', 0, 0, 9.8, 0, 0, 1733576993, 1733539255, 0, 0, 0, 0, 0.0, '', '530,531', '', '', '', '', '', '', '', '<p>秀才所聚集的名校·秀知院学园，在那里的学生会相遇的副会长·四宫辉夜与会长·白银御行，是任何人都认为适合对方的两个天才，原以为他们马上就能交往了，但他们因为自尊心超强一直没能告白！！在“如何让对方告白”的恋爱头脑战中绞尽脑汁的2人，那种罕见的才智热暴走！！已经无法控制了！！恋爱使天才变成笨蛋！！新感觉“斗智”？爱情喜剧、再次开战！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE052FBB88B01F5D0850E978#第02集$MOE052FBB88B01F5D0850E97B#第03集$MOE052FBB88B01F5D0850E97A#第04集$MOE052FBB88B01F5D0850E97D#第05集$MOE052FBB88B01F5D0850E97C#第06集$MOE052FBB88B01F5D0850E97F#第07集$MOE052FBB88B01F5D0850E97E#第08集$MOE052FBB88B01F5D0850E971#第09集$MOE052FBB88B01F5D0850E970#第10集$MOE052FBB88B01F5D0850E879#第11集$MOE052FBB88B01F5D0850E878#第12集$MOE052FBB88B01F5D0850E87B#OVA$MOE052FBB88B01F5D0850E87A$$$第01集$id_XS052FBB88B01F5D0850E978#第02集$id_XS052FBB88B01F5D0850E97B#第03集$id_XS052FBB88B01F5D0850E97A#第04集$id_XS052FBB88B01F5D0850E97D#第05集$id_XS052FBB88B01F5D0850E97C#第06集$id_XS052FBB88B01F5D0850E97F#第07集$id_XS052FBB88B01F5D0850E97E#第08集$id_XS052FBB88B01F5D0850E971#第09集$id_XS052FBB88B01F5D0850E970#第10集$id_XS052FBB88B01F5D0850E879#第11集$id_XS052FBB88B01F5D0850E878#第12集$id_XS052FBB88B01F5D0850E87B#OVA$id_XS052FBB88B01F5D0850E87A$$$第01集$id_MOE052FBB88B01F5D0850E978#第02集$id_MOE052FBB88B01F5D0850E97B#第03集$id_MOE052FBB88B01F5D0850E97A#第04集$id_MOE052FBB88B01F5D0850E97D#第05集$id_MOE052FBB88B01F5D0850E97C#第06集$id_MOE052FBB88B01F5D0850E97F#第07集$id_MOE052FBB88B01F5D0850E97E#第08集$id_MOE052FBB88B01F5D0850E971#第09集$id_MOE052FBB88B01F5D0850E970#第10集$id_MOE052FBB88B01F5D0850E879#第11集$id_MOE052FBB88B01F5D0850E878#第12集$id_MOE052FBB88B01F5D0850E87B#OVA$id_MOE052FBB88B01F5D0850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (530, 1, 0, 0, '辉夜大小姐想让我告白 -究极浪漫-', '', 'huiyedaxiaojiexiangrangwogaobaijiujilangman', 1, 'H', '', '88e54b9e', '漫画改,搞笑,恋爱,校园', 'http://i0.hdslb.com/bfs/bangumi/image/ffe6ebdf6770e7975bf830bee73a03c79e81b690.png', '', '', '', '古贺葵 / 古川慎 / 小原好美 / 铃木崚汰 / 富田美忧 / 花守由美里 / 麻仓桃 / 日高里菜 / 八代拓 / 市之濑加那 / 福原遥 / 青山穰', '畠山守', '', '', '秀知院学园是秀才云集的菁英学校，在学生会中担任学生会副会长·四宫辉夜遇见了学生会长·白银御行。\r\n原以为这两个任谁都觉得很登对的天才应该很快就会在一起，但这两人却因为过高的自尊心导致他们终没能向对方告白', '全13集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 9.5, 0, 0, 1733595946, 1733539271, 0, 0, 0, 0, 0.0, '', '531', '', '', '', '', '', '', '', '<p>秀知院学园是秀才云集的菁英学校，在学生会中担任学生会副会长·四宫辉夜遇见了学生会长·白银御行。\n原以为这两个任谁都觉得很登对的天才应该很快就会在一起，但这两人却因为过高的自尊心导致他们终没能向对方告白。\n“该用什么办法才能让对方向自己告白呢？”在这场恋爱头脑战中用尽各种智慧谋略、身经百战的两人，各自在心中下了某个决心。\n在秀知院学园高中部的文化祭“奉心祭”的最终日到来前，两人的恋情将会出现巨大的进展。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE092FE98DBD4B545C50E978#第02集$MOE092FE98DBD4B545C50E97B#第03集$MOE092FE98DBD4B545C50E97A#第04集$MOE092FE98DBD4B545C50E97D#第05集$MOE092FE98DBD4B545C50E97C#第06集$MOE092FE98DBD4B545C50E97F#第07集$MOE092FE98DBD4B545C50E97E#第08集$MOE092FE98DBD4B545C50E971#第09集$MOE092FE98DBD4B545C50E970#第10集$MOE092FE98DBD4B545C50E879#第11集$MOE092FE98DBD4B545C50E878#第12集$MOE092FE98DBD4B545C50E87B#第13集$MOE092FE98DBD4B545C50E87A$$$第01集$id_XS092FE98DBD4B545C50E978#第02集$id_XS092FE98DBD4B545C50E97B#第03集$id_XS092FE98DBD4B545C50E97A#第04集$id_XS092FE98DBD4B545C50E97D#第05集$id_XS092FE98DBD4B545C50E97C#第06集$id_XS092FE98DBD4B545C50E97F#第07集$id_XS092FE98DBD4B545C50E97E#第08集$id_XS092FE98DBD4B545C50E971#第09集$id_XS092FE98DBD4B545C50E970#第10集$id_XS092FE98DBD4B545C50E879#第11集$id_XS092FE98DBD4B545C50E878#第12集$id_XS092FE98DBD4B545C50E87B#第13集$id_XS092FE98DBD4B545C50E87A$$$第01集$id_MOE092FE98DBD4B545C50E978#第02集$id_MOE092FE98DBD4B545C50E97B#第03集$id_MOE092FE98DBD4B545C50E97A#第04集$id_MOE092FE98DBD4B545C50E97D#第05集$id_MOE092FE98DBD4B545C50E97C#第06集$id_MOE092FE98DBD4B545C50E97F#第07集$id_MOE092FE98DBD4B545C50E97E#第08集$id_MOE092FE98DBD4B545C50E971#第09集$id_MOE092FE98DBD4B545C50E970#第10集$id_MOE092FE98DBD4B545C50E879#第11集$id_MOE092FE98DBD4B545C50E878#第12集$id_MOE092FE98DBD4B545C50E87B#第13集$id_MOE092FE98DBD4B545C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (531, 1, 0, 0, '辉夜大小姐想让我告白：初吻不会结束', 'かぐや様は告らせたい-ファーストキッスは終わらない-（2022）', 'huiyedaxiaojiexiangrangwogaobaichuwenbuhuijieshu', 1, 'H', '', '42a27a21', '漫画改,恋爱,搞笑,校园', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2895358601.jpg', '', '', '', '古贺葵 / 古川慎 / 小原好美 / 铃木崚汰 / 富田美忧 / 花守由美里 / 麻仓桃 / 日高里菜 / 八代拓 / 铃代纱弓 / 子安武人 / 青山穰 / 福原遥', '畠山守', '', '', '两人冻结的内心，在没有下雪的东京夜空渐渐融化。', '全4集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 9.2, 0, 0, 1733618278, 1733578149, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>两人冻结的内心，在没有下雪的东京夜空渐渐融化。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0525ED8ABE485F0850E978#第02集$MOE0525ED8ABE485F0850E97B#第03集$MOE0525ED8ABE485F0850E97A#第04集$MOE0525ED8ABE485F0850E97D$$$第01集$id_XS0525ED8ABE485F0850E978#第02集$id_XS0525ED8ABE485F0850E97B#第03集$id_XS0525ED8ABE485F0850E97A#第04集$id_XS0525ED8ABE485F0850E97D$$$第01集$id_MOE0525ED8ABE485F0850E978#第02集$id_MOE0525ED8ABE485F0850E97B#第03集$id_MOE0525ED8ABE485F0850E97A#第04集$id_MOE0525ED8ABE485F0850E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (532, 1, 0, 0, '紫罗兰永恒花园', '', 'ziluolanyonghenghuayuan', 1, 'Z', '', 'ab31d243', '治愈,励志,职场,催泪', 'http://i0.hdslb.com/bfs/bangumi/image/6565f297b31fb4a4a0337557033426930c3b88c0.png', '', '', '', '石川由依 / 子安武人 / 浪川大辅 / 远藤绫 / 内山昂辉 / 茅原实里 / 户松遥', '石立太一 / 藤田春香 / 木上益治 / 武本康弘 / 小川太一 / 山村卓也 / 北之原孝将', '', '', '某个大陆的、某个时代。\r\n大陆南北分割的战争结束了，世界走向了和平。\r\n在战争中作为军人的薇尔莉特•伊芙加登，怀抱着对她来说无比重要之人留下的“话语”，离开军队来到了大港口城市。\r\n踊跃的人群在排列着煤气灯', '全13集 OVA', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 170, 0, 170, 170, '', 0, 0, 9.8, 0, 0, 1733618475, 1733594512, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>某个大陆的、某个时代。\n大陆南北分割的战争结束了，世界走向了和平。\n在战争中作为军人的薇尔莉特•伊芙加登，怀抱着对她来说无比重要之人留下的“话语”，离开军队来到了大港口城市。\n踊跃的人群在排列着煤气灯的街道马路上来来往往地穿梭着。薇尔莉特在街道上找到了“代写书信”的工作。那是根据委托人的想法来组织出相应语言的工作。\n她直面委托人、触碰着他们内心深处的坦率感情。与此同时，薇尔莉特在记录书信时，渐渐明白那“话语”的含义。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5075BF89ED1B590A50E978#第02集$MOE5075BF89ED1B590A50E97B#第03集$MOE5075BF89ED1B590A50E97A#第04集$MOE5075BF89ED1B590A50E97D#第05集$MOE5075BF89ED1B590A50E97C#第06集$MOE5075BF89ED1B590A50E97F#第07集$MOE5075BF89ED1B590A50E97E#第08集$MOE5075BF89ED1B590A50E971#第09集$MOE5075BF89ED1B590A50E970#第10集$MOE5075BF89ED1B590A50E879#第11集$MOE5075BF89ED1B590A50E878#第12集$MOE5075BF89ED1B590A50E87B#第13集$MOE5075BF89ED1B590A50E87A#OVA$MOE5075BF89ED1B590A50E87D$$$第01集$id_XS5075BF89ED1B590A50E978#第02集$id_XS5075BF89ED1B590A50E97B#第03集$id_XS5075BF89ED1B590A50E97A#第04集$id_XS5075BF89ED1B590A50E97D#第05集$id_XS5075BF89ED1B590A50E97C#第06集$id_XS5075BF89ED1B590A50E97F#第07集$id_XS5075BF89ED1B590A50E97E#第08集$id_XS5075BF89ED1B590A50E971#第09集$id_XS5075BF89ED1B590A50E970#第10集$id_XS5075BF89ED1B590A50E879#第11集$id_XS5075BF89ED1B590A50E878#第12集$id_XS5075BF89ED1B590A50E87B#第13集$id_XS5075BF89ED1B590A50E87A#OVA$id_XS5075BF89ED1B590A50E87D$$$第01集$id_MOE5075BF89ED1B590A50E978#第02集$id_MOE5075BF89ED1B590A50E97B#第03集$id_MOE5075BF89ED1B590A50E97A#第04集$id_MOE5075BF89ED1B590A50E97D#第05集$id_MOE5075BF89ED1B590A50E97C#第06集$id_MOE5075BF89ED1B590A50E97F#第07集$id_MOE5075BF89ED1B590A50E97E#第08集$id_MOE5075BF89ED1B590A50E971#第09集$id_MOE5075BF89ED1B590A50E970#第10集$id_MOE5075BF89ED1B590A50E879#第11集$id_MOE5075BF89ED1B590A50E878#第12集$id_MOE5075BF89ED1B590A50E87B#第13集$id_MOE5075BF89ED1B590A50E87A#OVA$id_MOE5075BF89ED1B590A50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (533, 2, 0, 0, '紫罗兰永恒花园外传：永远与自动手记人偶', '', 'ziluolanyonghenghuayuanwaichuanyongyuanyuzidongshoujirenou', 1, 'Z', '', '763b096a', '剧情,动画,小说改', 'http://i0.hdslb.com/bfs/bangumi/image/107eb93eff876dee16da4bf270b31c3e250e49d6.png', '', '', '', '石川由依 / 茅原实里 / 远藤绫 / 寿美菜子 / 子安武人 / 户松遥 / 内山昂辉 / 悠木碧', '藤田春香', '', '', '某个大陆的、某个时代。大陆南北分割的战争结束了，世界走向了和平。在战争中作为军人的薇尔莉特•伊芙加登，怀抱着对她来说无比重要之人留下的“话语”，离开军队来到了大港口城市。踊跃的人群在排列着煤气灯的街道', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 9.9, 0, 0, 1733692012, 1733621179, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>某个大陆的、某个时代。大陆南北分割的战争结束了，世界走向了和平。在战争中作为军人的薇尔莉特•伊芙加登，怀抱着对她来说无比重要之人留下的“话语”，离开军队来到了大港口城市。踊跃的人群在排列着煤气灯的街道马路上来来往往地穿梭着。薇尔莉特在街道上找到了“代写书 信”的工作。那是根据委托人的想法来组织出相应语言的工作。她直面委托人、触碰着他们内心深处的坦率感情。与此同时，薇尔莉特在记录书信时，渐渐明白那“话语”的含义...</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0621BFDAB9105B5850E978$$$正片$id_MOE0621BFDAB9105B5850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (534, 2, 0, 0, '紫罗兰永恒花园 剧场版', '', 'ziluolanyonghenghuayuanjuchangban', 1, 'Z', '', 'd486dd93', '动画,奇幻,爱情,剧情', 'https://i0.hdslb.com/bfs/bangumi/image/2e800bc5154dcaad24a46d33e2af82be7aa9a2e9.png', '', '', '', '石川由依 / 浪川大辅 / 子安武人 / 木内秀信 / 户松遥 / 内山昂辉 / 远藤绫 / 茅原实里 / 水桥香织 / 佐藤利奈 / 松元惠 / 诸星堇 / 中田让治 / 间宫康弘 / 宫本充 / 筱原惠美 / 京田尚子 / 引坂理绘 / 川澄绫子 / 远藤大智 / Mayuno Yasokawa', '石立太一', '', '', '从事代笔职业的她，名叫薇尔莉特·伊芙加登。在让人们伤痕累累的战争结束后数年，崭新的时代来临，世界也逐渐恢复平稳，生活也随着新技术的开发而改变，大家都在向前迈进。但是，薇尔莉特每天都在思念“那个人”，她', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 61, 0, 61, 61, '', 0, 0, 9.9, 0, 0, 1733692115, 1733621205, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>从事代笔职业的她，名叫薇尔莉特·伊芙加登。在让人们伤痕累累的战争结束后数年，崭新的时代来临，世界也逐渐恢复平稳，生活也随着新技术的开发而改变，大家都在向前迈进。但是，薇尔莉特每天都在思念“那个人”，她坚信他一定还活着。直到某天，她在邮局的仓库里发现了一封收件人不明的信……</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5523B48EED4D540A50E978$$$正片$id_MOE5523B48EED4D540A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (139, 1, 0, 0, '堀与宫村', '', 'kuyugongcun', 1, 'K', '', 'fb0743d1', '漫画改,校园,恋爱,少女', 'http://i0.hdslb.com/bfs/bangumi/image/039c4e0b14e27c7a9e5cce2f20a6efd3c8909401.png', '', '', '', '户松遥 / 内山昂辉 / 山下诚一郎 / 小坂井祐梨绘 / 冈本信彦 / 市道真央 / 近藤玲奈 / 山下大辉 / 福山润 / 八代拓 / 千叶翔也 / 麻仓桃 / 小野大辅 / 茅野爱衣 / 寺崎裕香 / 金元寿子', '石滨真史 / 柴田彰久 / 江岛泰男 / 松林唯人 / 佐佐木忍 / 山本阳介', '', '', '不论是谁，都会有不想被人知道的一面。\r\n\r\n在学校中漂亮大方、成绩优秀的人气女生堀，私下却打扮土气、忙于家务和照顾弟弟。\r\n在学校中是阴暗宅男形象的宫村，生活中却是打扮时尚、带耳钉的帅气男生。\r\n因为一次特别', '全13集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 176, 0, 176, 176, '', 0, 0, 9.8, 0, 0, 1733714758, 1733700714, 0, 0, 0, 0, 0.0, '', '540', '', '', '', '', '', '', '', '<p>不论是谁，都会有不想被人知道的一面。\n\n在学校中漂亮大方、成绩优秀的人气女生堀，私下却打扮土气、忙于家务和照顾弟弟。\n在学校中是阴暗宅男形象的宫村，生活中却是打扮时尚、带耳钉的帅气男生。\n因为一次特别的相遇，两人开始有了交集。\n\n互相拥有对方秘密的两人，感情也在不断发酵。恋爱、友情，充满青春气息的超微碳酸系校园生活就此开始！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5775BC8FBD1A090850E978#第02集$MOE5775BC8FBD1A090850E97B#第03集$MOE5775BC8FBD1A090850E97A#第04集$MOE5775BC8FBD1A090850E97D#第05集$MOE5775BC8FBD1A090850E97C#第06集$MOE5775BC8FBD1A090850E97F#第07集$MOE5775BC8FBD1A090850E97E#第08集$MOE5775BC8FBD1A090850E971#第09集$MOE5775BC8FBD1A090850E970#第10集$MOE5775BC8FBD1A090850E879#第11集$MOE5775BC8FBD1A090850E878#第12集$MOE5775BC8FBD1A090850E87B#第13集$MOE5775BC8FBD1A090850E87A$$$第01集$id_XS5775BC8FBD1A090850E978#第02集$id_XS5775BC8FBD1A090850E97B#第03集$id_XS5775BC8FBD1A090850E97A#第04集$id_XS5775BC8FBD1A090850E97D#第05集$id_XS5775BC8FBD1A090850E97C#第06集$id_XS5775BC8FBD1A090850E97F#第07集$id_XS5775BC8FBD1A090850E97E#第08集$id_XS5775BC8FBD1A090850E971#第09集$id_XS5775BC8FBD1A090850E970#第10集$id_XS5775BC8FBD1A090850E879#第11集$id_XS5775BC8FBD1A090850E878#第12集$id_XS5775BC8FBD1A090850E87B#第13集$id_XS5775BC8FBD1A090850E87A$$$第01集$id_MOE5775BC8FBD1A090850E978#第02集$id_MOE5775BC8FBD1A090850E97B#第03集$id_MOE5775BC8FBD1A090850E97A#第04集$id_MOE5775BC8FBD1A090850E97D#第05集$id_MOE5775BC8FBD1A090850E97C#第06集$id_MOE5775BC8FBD1A090850E97F#第07集$id_MOE5775BC8FBD1A090850E97