INSERT INTO `mac_vod` VALUES (536, 1, 0, 0, '小林家的龙女仆', '', 'xiaolinjiadelongnvpu', 1, 'X', '', '1fd0f7c3', '萌系,搞笑,日常,漫画改', 'http://i0.hdslb.com/bfs/bangumi/image/c72a95c3cae82f58f8fa25facd40960aa2003d26.png', '', '', '', '田村睦心 / 桑原由气 / 长绳麻理亚 / 高田忧希 / 高桥未奈美 / 加藤英美里 / 后藤邑子 / 石原夏织 / 小野大辅 / 中村悠一', '武本康弘 / 山田尚子 / 山村卓也 / 藤田春香 / 北之原孝将 / 小川太一 / 木上益治', '', '', '在单身的辛苦OL小林身边突然出现的女仆装束的美少女托尔。\r\n长着角和尾巴的她的身姿正是所谓的龙娘。\r\n在醉酒的小林邀请下说要到家里去的托尔，鬼使神差地开始以小林家女仆的身份工作……！？\r\n“女仆” “龙”=', '全13集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 53, 0, 53, 53, '', 0, 0, 9.7, 0, 0, 1733671595, 1733627977, 0, 0, 0, 0, 0.0, '', '537', '', '', '', '', '', '', '', '<p>在单身的辛苦OL小林身边突然出现的女仆装束的美少女托尔。\n长着角和尾巴的她的身姿正是所谓的龙娘。\n在醉酒的小林邀请下说要到家里去的托尔，鬼使神差地开始以小林家女仆的身份工作……！？\n“女仆” “龙”=“女仆龙”有着笨手笨脚的可爱之处！\n龙娘与人类之间基本上很温暖、偶尔有些黑暗的异种族间交流喜剧！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0071E888EF1E0E0A50E978#第02集$MOE0071E888EF1E0E0A50E97B#第03集$MOE0071E888EF1E0E0A50E97A#第04集$MOE0071E888EF1E0E0A50E97D#第05集$MOE0071E888EF1E0E0A50E97C#第06集$MOE0071E888EF1E0E0A50E97F#第07集$MOE0071E888EF1E0E0A50E97E#第08集$MOE0071E888EF1E0E0A50E971#第09集$MOE0071E888EF1E0E0A50E970#第10集$MOE0071E888EF1E0E0A50E879#第11集$MOE0071E888EF1E0E0A50E878#第12集$MOE0071E888EF1E0E0A50E87B#第13集$MOE0071E888EF1E0E0A50E87A#OVA$MOE0071E888EF1E0E0A50E87D$$$第01集$id_XS0071E888EF1E0E0A50E978#第02集$id_XS0071E888EF1E0E0A50E97B#第03集$id_XS0071E888EF1E0E0A50E97A#第04集$id_XS0071E888EF1E0E0A50E97D#第05集$id_XS0071E888EF1E0E0A50E97C#第06集$id_XS0071E888EF1E0E0A50E97F#第07集$id_XS0071E888EF1E0E0A50E97E#第08集$id_XS0071E888EF1E0E0A50E971#第09集$id_XS0071E888EF1E0E0A50E970#第10集$id_XS0071E888EF1E0E0A50E879#第11集$id_XS0071E888EF1E0E0A50E878#第12集$id_XS0071E888EF1E0E0A50E87B#第13集$id_XS0071E888EF1E0E0A50E87A#OVA$id_XS0071E888EF1E0E0A50E87D$$$第01集$id_MOE0071E888EF1E0E0A50E978#第02集$id_MOE0071E888EF1E0E0A50E97B#第03集$id_MOE0071E888EF1E0E0A50E97A#第04集$id_MOE0071E888EF1E0E0A50E97D#第05集$id_MOE0071E888EF1E0E0A50E97C#第06集$id_MOE0071E888EF1E0E0A50E97F#第07集$i