INSERT INTO `mac_vod` VALUES (537, 1, 0, 0, '小林家的龙女仆S', '小林さんちのメイドラゴンS（2021）', 'xiaolinjiadelongnvpuS', 1, 'X', '', '2212ac3e', '漫画改,搞笑,日常,萌系', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867701731.jpg', '', '', '', '田村睦心 / 桑原由气 / 长绳麻理亚 / 高田忧希 / 岭内知美 / 高桥未奈美 / 加藤英美里 / 后藤邑子 / 石原夏织 / 小野大辅 / 中村悠一', '武本康弘 / 石原立也 / 北之原孝将 / 山村卓也 / 小川太一', '', '', '主人公小林是一位女性系统工程师，某天她喝酒喝的很醉兴冲冲的跑到了山上遇到了一头龙，酒醉之下的小林对着龙大倒苦水。听到龙说自己无家可归时，小林趁着酒意开玩笑的说“那你就来我家吧”，之后龙真的就跑到小林的', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 8.9, 0, 0, 1733692440, 1733670050, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>主人公小林是一位女性系统工程师，某天她喝酒喝的很醉兴冲冲的跑到了山上遇到了一头龙，酒醉之下的小林对着龙大倒苦水。听到龙说自己无家可归时，小林趁着酒意开玩笑的说“那你就来我家吧”，之后龙真的就跑到小林的家里，并且还变成了一位女仆——于是一位龙女仆和小林的同居生活就这样开始了……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0325BD8AE84A5E5C50E978#第02集$MOE0325BD8AE84A5E5C50E97B#第03集$MOE0325BD8AE84A5E5C50E97A#第04集$MOE0325BD8AE84A5E5C50E97D#第05集$MOE0325BD8AE84A5E5C50E97C#第06集$MOE0325BD8AE84A5E5C50E97F#第07集$MOE0325BD8AE84A5E5C50E97E#第08集$MOE0325BD8AE84A5E5C50E971#第09集$MOE0325BD8AE84A5E5C50E970#第10集$MOE0325BD8AE84A5E5C50E879#第11集$MOE0325BD8AE84A5E5C50E878#第12集$MOE0325BD8AE84A5E5C50E87B#OVA$MOE0325BD8AE84A5E5C50E87A$$$第01集$id_XS0325BD8AE84A5E5C50E978#第02集$id_XS0325BD8AE84A5E5C50E97B#第03集$id_XS0325BD8AE84A5E5C50E97A#第04集$id_XS0325BD8AE84A5E5C50E97D#第05集$id_XS0325BD8AE84A5E5C50E97C#第06集$id_XS0325BD8AE84A5E5C50E97F#第07集$id_XS0325BD8AE84A5E5C50E97E#第08集$id_XS0325BD8AE84A5E5C50E971#第09集$id_XS0325BD8AE84A5E5C50E970#第10集$id_XS0325BD8AE84A5E5C50E879#第11集$id_XS0325BD8AE84A5E5C50E878#第12集$id_XS0325BD8AE84A5E5C50E87B#OVA$id_XS0325BD8AE84A5E5C50E87A$$$第01集$id_MOE0325BD8AE84A5E5C50E978#第02集$id_MOE0325BD8AE84A5E5C50E97B#第03集$id_MOE0325BD8AE84A5E5C50E97A#第04集$id_MOE0325BD8AE84A5E5C50E97D#第05集$id_MOE0325BD8AE84A5E5C50E97C#第06集$id_MOE0325BD8AE84A5E5C50E97F#第07集$id_MOE0325BD8AE84A5E5C50E97E#第08集$id_MOE0325BD8AE84A5E5C50E971#第09集$id_MOE0325BD8AE84A