INSERT INTO `mac_vod` VALUES (749, 3, 0, 0, '千与千寻', '千と千尋の神隠し（2001）', 'qianyuqianxun', 1, 'Q', '', '8a52cbf9', '奇幻', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557573348.jpg', '', '', '', '柊瑠美 / 入野自由 / 夏木真理 / 菅原文太 / 中村彰男 / 玉井夕海 / 神木隆之介 / 内藤刚志 / 泽口靖子 / 我修院达也 / 大泉洋 / 小林郁夫 / 上条恒彦 / 小野武彦', '宫崎骏', '', '', '千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道——他们去到了另外一个诡异世界—一个中世纪的小镇。远处飘来食物的香味，爸爸妈妈大快朵颐，孰料之后变成了猪！这时小镇上渐渐来了许多样子古', '简中4K', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 129, 0, 129, 129, '', 0, 0, 9.4, 0, 0, 1736525124, 1735730493, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道——他们去到了另外一个诡异世界—一个中世纪的小镇。远处飘来食物的香味，爸爸妈妈大快朵颐，孰料之后变成了猪！这时小镇上渐渐来了许多样子古怪、半透明的人。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0976B98AEA4B0B0050E978$$$正片$id_MOE0976B98AEA4B0B0050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (549, 1, 0, 0, '埃罗芒阿老师', '', 'ailuomangalaoshi', 1, 'A', '', '69d47e49', '小说改,搞笑,恋爱', 'https://i0.hdslb.com/bfs/bangumi/a223b1376633625be1cd214c34d8bf34a1e03770.jpg', '', '', '', '松冈祯丞 / 藤田茜 / 高桥未奈美 / 大西沙织 / 木户衣吹 / 石川由依 / 岛崎信长 / 小松未可子', '竹下良平 / 嵯峨敏 / 石川俊介', '', '', '高中生兼小说作家的“和泉正宗”（笔名：和泉征宗）有个家里蹲的妹妹“和泉纱雾”。一年前才成为家人的她，却完全不走出居室，并也用力踩踏地板，要我帮她准备食物。为了这段称不上“兄妹”的关系，正宗得想个办法让', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 9.3, 0, 0, 1733878840, 1733824696, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高中生兼小说作家的“和泉正宗”（笔名：和泉征宗）有个家里蹲的妹妹“和泉纱雾”。一年前才成为家人的她，却完全不走出居室，并也用力踩踏地板，要我帮她准备食物。为了这段称不上“兄妹”的关系，正宗得想个办法让她自己走出居室才行，因为两人已是目前仅存能相依为命的“家人”……至于正宗的搭挡插画家“煽情漫画老师”，是个能够画出非常棒煽情图的可靠伙伴。虽然双方并没见过面，但我一直很感谢他！只是在某一天，正宗突然发现到一个冲击事实，那就是“煽情漫画老师”其实就是纱雾！？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE072EE88CBE4C590050E978#第02集$MOE072EE88CBE4C590050E97B#第03集$MOE072EE88CBE4C590050E97A#第04集$MOE072EE88CBE4C590050E97D#第05集$MOE072EE88CBE4C590050E97C#第06集$MOE072EE88CBE4C590050E97F#第07集$MOE072EE88CBE4C590050E97E#第08集$MOE072EE88CBE4C590050E971#第09集$MOE072EE88CBE4C590050E970#第10集$MOE072EE88CBE4C590050E879#第11集$MOE072EE88CBE4C590050E878#第12集$MOE072EE88CBE4C590050E87B#OVA01$MOE072EE88CBE4C590050E87A#OVA02$MOE072EE88CBE4C590050E87D$$$第01集$id_XS072EE88CBE4C590050E978#第02集$id_XS072EE88CBE4C590050E97B#第03集$id_XS072EE88CBE4C590050E97A#第04集$id_XS072EE88CBE4C590050E97D#第05集$id_XS072EE88CBE4C590050E97C#第06集$id_XS072EE88CBE4C590050E97F#第07集$id_XS072EE88CBE4C590050E97E#第08集$id_XS072EE88CBE4C590050E971#第09集$id_XS072EE88CBE4C590050E970#第10集$id_XS072EE88CBE4C590050E879#第11集$id_XS072EE88CBE4C590050E878#第12集$id_XS072EE88CBE4C590050E87B#OVA01$id_XS072EE88CBE4C590050E87A#OVA02$id_XS072EE88CBE4C590050E87D$$$第01集$id_MOE072EE88CBE4C590050E978#第02集$id_MOE072EE88CBE4C590050E97B#第03集$id_MOE072EE88CBE4C590050E97A#第04集$id_MOE072EE88CBE4C590050E97D#第05集$id_MOE072EE88CBE4C590050E97C#第06集$id_MOE072EE88CBE4C590050E97F#第07集$id_MOE072EE88CBE4C590050E97E#第08集$id_MOE072EE88CBE4C590050E971#第09集$id_MOE072EE88CBE4C590050E970#第10集$id_MOE072EE88CBE4C590050E879#第11集$id_MOE072EE88CBE4C590050E878#第12集$id_MOE072EE88CBE4C590050E87B#OVA01$id_MOE072EE88CBE4C590050E87A#OVA02$id_MOE072EE88CBE4C590050E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (550, 1, 0, 0, '四月是你的谎言', '', 'siyueshinidehuangyan', 1, 'S', '', 'ba4f9ddf', '漫画改,催泪,恋爱,少女', 'https://i0.hdslb.com/bfs/bangumi/image/ec912249f5bf1fe1521c9a2df5ae655567bd85ef.png', '', '', '', '花江夏树 / 种田梨沙 / 佐仓绫音 / 逢坂良太 / 早见沙织 / 梶裕贵 / 茅野爱衣 / 能登麻美子', '石黑恭平 / 石滨真史 / 柴山智隆 / 石井俊匡 / 岩田和也 / 井端义秀 / 高桥英俊 / 原田孝宏 / 中村章子 / 黑木美幸 / 仓田绫子 / 河野亚矢子 / 间岛崇宽 / 川越崇弘 / 福岛利规 / 矢岛武 / 小岛崇史', '', '', '从小接受母亲严格的钢琴训练，并在各种音乐比赛上获胜的“神童”——有马公生，11岁那年因为母亲去世，他从此变得听不见钢琴的声音，因而放弃了弹奏钢琴。\r\n国中三年级时，在青梅竹马椿的引见下，公生认识了与他同', '全22集 OAD', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 107, 0, 107, 107, '', 0, 0, 9.8, 0, 0, 1733886866, 1733824824, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>从小接受母亲严格的钢琴训练，并在各种音乐比赛上获胜的“神童”——有马公生，11岁那年因为母亲去世，他从此变得听不见钢琴的声音，因而放弃了弹奏钢琴。\n国中三年级时，在青梅竹马椿的引见下，公生认识了与他同年级的小提琴手——宫园薰，并于一场比赛中被薰自由奔放的演奏风格所吸引。自此，公生的日常生活开始有了改变。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5376B8DEB04D095F50E978#第02集$MOE5376B8DEB04D095F50E97B#第03集$MOE5376B8DEB04D095F50E97A#第04集$MOE5376B8DEB04D095F50E97D#第05集$MOE5376B8DEB04D095F50E97C#第06集$MOE5376B8DEB04D095F50E97F#第07集$MOE5376B8DEB04D095F50E97E#第08集$MOE5376B8DEB04D095F50E971#第09集$MOE5376B8DEB04D095F50E970#第10集$MOE5376B8DEB04D095F50E879#第11集$MOE5376B8DEB04D095F50E878#第12集$MOE5376B8DEB04D095F50E87B#第13集$MOE5376B8DEB04D095F50E87A#第14集$MOE5376B8DEB04D095F50E87D#第15集$MOE5376B8DEB04D095F50E87C#第16集$MOE5376B8DEB04D095F50E87F#第17集$MOE5376B8DEB04D095F50E87E#第18集$MOE5376B8DEB04D095F50E871#第19集$MOE5376B8DEB04D095F50E870#第20集$MOE5376B8DEB04D095F50EB79#第21集$MOE5376B8DEB04D095F50EB78#第22集$MOE5376B8DEB04D095F50EB7B#OAD$MOE5376B8DEB04D095F50EB7A$$$第01集$id_XS5376B8DEB04D095F50E978#第02集$id_XS5376B8DEB04D095F50E97B#第03集$id_XS5376B8DEB04D095F50E97A#第04集$id_XS5376B8DEB04D095F50E97D#第05集$id_XS5376B8DEB04D095F50E97C#第06集$id_XS5376B8DEB04D095F50E97F#第07集$id_XS5376B8DEB04D095F50E97E#第08集$id_XS5376B8DEB04D095F50E971#第09集$id_XS5376B8DEB04D095F50E970#第10集$id_XS5376B8DEB04D095F50E879#第11集$id_XS5376B8D