INSERT INTO `mac_vod` VALUES (556, 1, 0, 0, '徒然喜欢你', '', 'turanxihuanni', 1, 'T', '', 'de7a21d', '恋爱,校园,漫画改,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/cb4dde6d68cf3a826538d84925e123a1148b779d.png', '', '', '', '石川界人 / 水濑祈 / 前野智昭 / 小仓唯 / 小野贤章 / 佐仓绫音 / 熊谷健太郎 / 三宅晴佳 / 花泽香菜 / 天崎滉平 / 户松遥 / 浪川大辅', '金子拓 / 笔坂明规 / 所俊克 / 滨崎彻 / 山本天志 / 牧野友映', '', '', '故事讲述了青梅竹马之间、学生会长与不良少女之间、前辈与后辈之间、同学之间等多种不同角色的恋爱群像剧。', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.7, 0, 0, 1733912662, 1733891693, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事讲述了青梅竹马之间、学生会长与不良少女之间、前辈与后辈之间、同学之间等多种不同角色的恋爱群像剧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5572BBD9BB1809144DE8#第02集$MOE5572BBD9BB1809144DEB#第03集$MOE5572BBD9BB1809144DEA#第04集$MOE5572BBD9BB1809144DED#第05集$MOE5572BBD9BB1809144DEC#第06集$MOE5572BBD9BB1809144DEF#第07集$MOE5572BBD9BB1809144DEE#第08集$MOE5572BBD9BB1809144DE1#第09集$MOE5572BBD9BB1809144DE0#第10集$MOE5572BBD9BB1809144CE9#第11集$MOE5572BBD9BB1809144CE8#第12集$MOE5572BBD9BB1809144CEB$$$第01集$id_XS5572BBD9BB1809144DE8#第02集$id_XS5572BBD9BB1809144DEB#第03集$id_XS5572BBD9BB1809144DEA#第04集$id_XS5572BBD9BB1809144DED#第05集$id_XS5572BBD9BB1809144DEC#第06集$id_XS5572BBD9BB1809144DEF#第07集$id_XS5572BBD9BB1809144DEE#第08集$id_XS5572BBD9BB1809144DE1#第09集$id_XS5572BBD9BB1809144DE0#第10集$id_XS5572BBD9BB1809144CE9#第11集$id_XS5572BBD9BB1809144CE8#第12集$id_XS5572BBD9BB1809144CEB$$$第01集$id_MOE5572BBD9BB1809144DE8#第02集$id_MOE5572BBD9BB1809144DEB#第03集$id_MOE5572BBD9BB1809144DEA#第04集$id_MOE5572BBD9BB1809144DED#第05集$id_MOE5572BBD9BB1809144DEC#第06集$id_MOE5572BBD9BB1809144DEF#第07集$id_MOE5572BBD9BB1809144DEE#第08集$id_MOE5572BBD9BB1809144DE1#第09集$id_MOE5572BBD9BB1809144DE0#第10集$id_MOE5572BBD9BB1809144CE9#第11集$id_MOE5572BBD9BB1809144CE8#第12集$id_MOE5572BBD9BB1809144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (557, 1, 0, 0, '我的青春恋爱物语果然有问题', '', 'wodeqingchunlianaiwuyuguoranyouwenti', 1, 'W', '', 'ea0b8b2e', '恋爱,小说改,日常,校园', 'http://i0.hdslb.com/bfs/bangumi/image/8d1200b8c8b795dd3a7baae33afcec42fbd1947c.png', '', '', '', '江口拓也 / 早见沙织 / 东山奈央 / 小松未可子 / 悠木碧 / 桧山修之 / 柚木凉香 / 中原麻衣 / 近藤隆 / 井上麻里奈 / 佐佐木望 / 小清水亚美', '吉村爱 / 高桥秀弥 / 有富兴二 / 河村智之 / 中野英明 / 黑川智之 / 石川俊介 / 野亦则行 / 吉田理纱子', '', '', '就读于千叶市立综武高等学校高二年级的比企谷八幡，从幼年时代就交不到什么朋友。正当他已经放弃了交朋友这种念头的时候，生活指导老师平冢静介绍他进入了学校第一美女——俗称校花的雪之下雪乃所在的“奉仕部”。奉', '全13集 OVA', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 72, 0, 72, 72, '', 0, 0, 9.7, 0, 0, 1733956076, 1733891952, 0, 0, 0, 0, 0.0, '', '558,559', '', '', '', '', '', '', '', '<p>就读于千叶市立综武高等学校高二年级的比企谷八幡，从幼年时代就交不到什么朋友。正当他已经放弃了交朋友这种念头的时候，生活指导老师平冢静介绍他进入了学校第一美女——俗称校花的雪之下雪乃所在的“奉仕部”。奉仕部是一个暗中帮助学生们解决问题的部门，所以不对外招募部员，都是以介绍的方式为部门输送新鲜血液。进入了奉仕部的八幡，和与他有着完全相反个性的由比滨结衣、中二病全开的材木坐义辉、网球部的可爱男孩子户冢彩加等人，展开了一段段奇妙的故事……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5476BCDAB14B5F5C50E978#第02集$MOE5476BCDAB14B5F5C50E97B#第03集$MOE5476BCDAB14B5F5C50E97A#第04集$MOE5476BCDAB14B5F5C50E97D#第05集$MOE5476BCDAB14B5F5C50E97C#第06集$MOE5476BCDAB14B5F5C50E97F#第07集$MOE5476BCDAB14B5F5C50E97E#第08集$MOE5476BCDAB14B5F5C50E971#第09集$MOE5476BCDAB14B5F5C50E970#第10集$MOE5476BCDAB14B5F5C50E879#第11集$MOE5476BCDAB14B5F5C50E878#第12集$MOE5476BCDAB14B5F5C50E87B#第13集$MOE5476BCDAB14B5F5C50E87A#OVA$MOE5476BCDAB14B5F5C50E87D$$$第01集$id_XS5476BCDAB14B5F5C50E978#第02集$id_XS5476BCDAB14B5F5C50E97B#第03集$id_XS5476BCDAB14B5F5C50E97A#第04集$id_XS5476BCDAB14B5F5C50E97D#第05集$id_XS5476BCDAB14B5F5C50E97C#第06集$id_XS5476BCDAB14B5F5C50E97F#第07集$id_XS5476BCDAB14B5F5C50E97E#第08集$id_XS5476BCDAB14B5F5C50E971#第09集$id_XS5476BCDAB14B5F5C50E970#第10集$id_XS5476BCDAB14B5F5C50E879#第11集$id_XS5476BCDAB14B5F5C50E878#第12集$id_XS5476BCDAB14B5F5C50E87B#第13集$id_XS5476BCDAB14B5F5C50E87A#OVA$id_XS5476BCDAB14B5F5C50E87D$$$第01集$id_MOE5476BCDAB14B5F5C50E978#第02集$id_MOE5476BCDAB14B5F5C50E97B#第03集$id_MOE5476BCDAB14B5F5C50E97A#第0