INSERT INTO `mac_vod` VALUES (573, 1, 0, 0, '干物妹！小埋', '', 'ganwumeixiaomai', 1, 'G', '', '1d9415bd', '萌系,日常', 'http://i0.hdslb.com/bfs/bangumi/image/e7fb0d62e99b974e00e19b68e51e8b1fcdfc02d5.png', '', '', '', '田中爱美 / 野岛健儿 / 影山灯 / 白石晴香 / 古川由利奈 / 安元洋贵 / 柿原彻也 / 小清水亚美 / 富田美忧 / 浅野真澄 / 前田玲奈 / 茜屋日海夏 / 前田弘喜', '太田雅彦 / 今泉贤一 / 大隈孝晴 / 矢花馨 / 守田艺成 / 福本洁 / 荒井省吾 / 野木森达哉', '', '', '我的妹妹小埋16岁，完美的妹妹，完美的高中生，但在家里却是个超懒的干物妹。\r\n然而妹妹在家的一切她生活中的朋友并不知道，居住在同一栋楼的天然少女，以及无意间来到我家的冷酷少女，她们会发现小埋的真实面目吗', '全12集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 81, 0, 81, 81, '', 0, 0, 9.3, 0, 0, 1734123793, 1734051374, 0, 0, 0, 0, 0.0, '', '574', '', '', '', '', '', '', '', '<p>我的妹妹小埋16岁，完美的妹妹，完美的高中生，但在家里却是个超懒的干物妹。\n然而妹妹在家的一切她生活中的朋友并不知道，居住在同一栋楼的天然少女，以及无意间来到我家的冷酷少女，她们会发现小埋的真实面目吗？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0073B58CB81C0F5D50E978#第02集$MOE0073B58CB81C0F5D50E97B#第03集$MOE0073B58CB81C0F5D50E97A#第04集$MOE0073B58CB81C0F5D50E97D#第05集$MOE0073B58CB81C0F5D50E97C#第06集$MOE0073B58CB81C0F5D50E97F#第07集$MOE0073B58CB81C0F5D50E97E#第08集$MOE0073B58CB81C0F5D50E971#第09集$MOE0073B58CB81C0F5D50E970#第10集$MOE0073B58CB81C0F5D50E879#第11集$MOE0073B58CB81C0F5D50E878#第12集$MOE0073B58CB81C0F5D50E87B$$$第01集$id_XS0073B58CB81C0F5D50E978#第02集$id_XS0073B58CB81C0F5D50E97B#第03集$id_XS0073B58CB81C0F5D50E97A#第04集$id_XS0073B58CB81C0F5D50E97D#第05集$id_XS0073B58CB81C0F5D50E97C#第06集$id_XS0073B58CB81C0F5D50E97F#第07集$id_XS0073B58CB81C0F5D50E97E#第08集$id_XS0073B58CB81C0F5D50E971#第09集$id_XS0073B58CB81C0F5D50E970#第10集$id_XS0073B58CB81C0F5D50E879#第11集$id_XS0073B58CB81C0F5D50E878#第12集$id_XS0073B58CB81C0F5D50E87B$$$第01集$id_MOE0073B58CB81C0F5D50E978#第02集$id_MOE0073B58CB81C0F5D50E97B#第03集$id_MOE0073B58CB81C0F5D50E97A#第04集$id_MOE0073B58CB81C0F5D50E97D#第05集$id_MOE0073B58CB81C0F5D50E97C#第06集$id_MOE0073B58CB81C0F5D50E97F#第07集$id_MOE0073B58CB81C0F5D50E97E#第08集$id_MOE0073B58CB81C0F5D50E971#第09集$id_MOE0073B58CB81C0F5D50E970#第10集$id_MOE0073B58CB81C0F5D50E879#第11集$id_MOE0073B58CB81C0F5D50E878#第12集$id_MOE