INSERT INTO `mac_vod` VALUES (574, 1, 0, 0, '干物妹！小埋R', '', 'ganwumeixiaomaiR', 1, 'G', '', 'e2aa8471', '萌系,搞笑,日常,漫画改', 'http://i0.hdslb.com/bfs/bangumi/e4edc4b821e92840453fe6e36ade81d92e85d0bc.jpg', '', '', '', '田中爱美 / 野岛健儿 / 影山灯 / 白石晴香 / 古川由利奈 / 安元洋贵 / 柿原彻也 / 小清水亚美 / 井上喜久子 / 冈本信彦 / 水濑祈', '太田雅彦 / 上坪亮树 / 直谷隆 / 原口浩 / 守田艺成 / 荒井省吾', '', '', '小埋，复活！在房间无限展开的宇宙，再临……！\r\n在外人人称羡的才色兼备“美妹”，一回到家，就变身成不为人知的一心犯懒“干物妹”……！？极尽无所事事之能事的干物妹小埋，一手可乐一手薯片，沉浸于漫画、游戏、', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 32, 0, 32, 32, '', 0, 0, 9.5, 0, 0, 1734136296, 1734052629, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>小埋，复活！在房间无限展开的宇宙，再临……！\n在外人人称羡的才色兼备“美妹”，一回到家，就变身成不为人知的一心犯懒“干物妹”……！？极尽无所事事之能事的干物妹小埋，一手可乐一手薯片，沉浸于漫画、游戏、动画、网络……，将一同生活的哥哥太平放置在旁，忠于欲望向前突进！和同班同学海老名、切绘、希尔芬的关系也逐渐加深，小埋的日常变得越来越热闹！！！\n小埋的最强、最棒的日常，再次开始！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5425EDD9B11D5A0850E978#第02集$MOE5425EDD9B11D5A0850E97B#第03集$MOE5425EDD9B11D5A0850E97A#第04集$MOE5425EDD9B11D5A0850E97D#第05集$MOE5425EDD9B11D5A0850E97C#第06集$MOE5425EDD9B11D5A0850E97F#第07集$MOE5425EDD9B11D5A0850E97E#第08集$MOE5425EDD9B11D5A0850E971#第09集$MOE5425EDD9B11D5A0850E970#第10集$MOE5425EDD9B11D5A0850E879#第11集$MOE5425EDD9B11D5A0850E878#第12集$MOE5425EDD9B11D5A0850E87B$$$第01集$id_XS5425EDD9B11D5A0850E978#第02集$id_XS5425EDD9B11D5A0850E97B#第03集$id_XS5425EDD9B11D5A0850E97A#第04集$id_XS5425EDD9B11D5A0850E97D#第05集$id_XS5425EDD9B11D5A0850E97C#第06集$id_XS5425EDD9B11D5A0850E97F#第07集$id_XS5425EDD9B11D5A0850E97E#第08集$id_XS5425EDD9B11D5A0850E971#第09集$id_XS5425EDD9B11D5A0850E970#第10集$id_XS5425EDD9B11D5A0850E879#第11集$id_XS5425EDD9B11D5A0850E878#第12集$id_XS5425EDD9B11D5A0850E87B$$$第01集$id_MOE5425EDD9B11D5A0850E978#第02集$id_MOE5425EDD9B11D5A0850E97B#第03集$id_MOE5425EDD9B11D5A0850E97A#第04集$id_MOE5425EDD9B11D5A0850E97D#第05集$id_MOE5425EDD9B11D5A0850E97C#第06集$id_MOE5425EDD9B11D5A0850E97F#第07集$id_MOE5425EDD9B11D5A0850E97E#第08集$id_MOE5425EDD9B11D5A0850E971#第09集$id_MOE5425EDD9B11D5A0850E970#第10集$id_MOE5425EDD9B