INSERT INTO `mac_vod` VALUES (575, 1, 0, 0, '干物妹！小埋 OVA', '', 'ganwumeixiaomaiOVA', 1, 'G', '', '9454e510', '治愈,日常,校园,萌系', 'http://i0.hdslb.com/bfs/bangumi/c80bbbb0104e7f60c1df67eebf684917880ab7b2.jpg', '', '', '', '田中爱美 / 野岛健儿 / 影山灯 / 白石晴香 / 古川由利奈', '太田雅彦', '', '', '单行本第7、10卷限定版同捆OAD', 'OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 23, 0, 23, 23, '', 0, 0, 9.5, 0, 0, 1734139477, 1734052639, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>单行本第7、10卷限定版同捆OAD</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0823B98CEC1C5C0950E978#第02集$MOE0823B98CEC1C5C0950E97B$$$第01集$id_XS0823B98CEC1C5C0950E978#第02集$id_XS0823B98CEC1C5C0950E97B$$$第01集$id_MOE0823B98CEC1C5C0950E978#第02集$id_MOE0823B98CEC1C5C0950E97B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (576, 2, 0, 0, '游戏人生 零', 'ノーゲーム・ノーライフ ゼロ（2017）', 'youxirenshengling', 1, 'Y', '', '108c28f', '剧场版', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561782374.jpg', '', '', '', '松冈祯丞 / 茅野爱衣 / 日笠阳子 / 田村由香里 / 能登麻美子 / 井口裕香 / 泽城美雪 / 大川透 / 兴津和幸 / Lynn / 诹访部顺一 / 堀江由衣 / 森奈奈子 / 竹内良太 / 大地叶 / 石上静香 / 滨野大辉 / 手冢宏通 / 钉宫理惠', '石塚敦子', '', '', '距今超过六千年的远古世界，天地割裂的凄惨战争持续不断，毫无还手之力的人类被拥有强大力量的各个种族逼入绝境，濒临灭亡。此时率领人类的年轻领袖里克，与机凯种少女休比偶然相遇。被同伴抛弃的休比，为了修复故障', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 44, 0, 44, 44, '', 0, 0, 7.7, 0, 0, 1734139636, 1734092970, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>距今超过六千年的远古世界，天地割裂的凄惨战争持续不断，毫无还手之力的人类被拥有强大力量的各个种族逼入绝境，濒临灭亡。此时率领人类的年轻领袖里克，与机凯种少女休比偶然相遇。被同伴抛弃的休比，为了修复故障，拜托里克把“人类的心”告诉自己。机凯种少女的单纯与真诚，使得里克对休比逐渐放下戒备、敞开心扉，二人感情亦日渐升温。最终二人带领人类共同面对终极一战，少女休比也将面临恋人与生命的残酷抉择。末日来临，在251秒的时间里，赌上一场深情告白。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0027B4DBBB110B144DE8$$$正片$id_MOE0027B4DBBB110B144DE8', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (577, 1, 0, 0, '命运之夜', 'Fate/stay night（2006）', 'mingyunzhiye', 1, 'M', '', '9f23bb4c', '游戏改,奇幻,战斗,魔法', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2260549012.jpg', '', '', '', '杉山纪彰 / 川澄绫子 / 植田佳奈 / 下屋则子 / 伊藤美纪 / 诹访部顺一 / 浅川悠', '山口祐司 / 上田茂 / 小林浩辅 / 冈岛国敏 / 秋田谷典昭 / 吉田俊司', '', '', '十年前，几乎毁灭世界的大灾难中，卫宫士郎被魔术师卫宫切嗣所救，成为其养子。', '全24集', '', 0, '0', '', '', '日本', '日语', '2006', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 7.9, 0, 0, 1734163492, 1734093050, 0, 0, 0, 0, 0.0, '', '578,579', '', '', '', '', '', '', '', '<p>十年前，几乎毁灭世界的大灾难中，卫宫士郎被魔术师卫宫切嗣所救，成为其养子。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0871BE8BEB4B595A50E978#第02集$MOE0871BE8BEB4B595A50E97B#第03集$MOE0871BE8BEB4B595A50E97A#第04集$MOE0871BE8BEB4B595A50E97D#第05集$MOE0871BE8BEB4B595A50E97C#第06集$MOE0871BE8BEB4B595A50E97F#第07集$MOE0871BE8BEB4B595A50E97E#第08集$MOE0871BE8BEB4B595A50E971#第09集$MOE0871BE8BEB4B595A50E970#第10集$MOE0871BE8BEB4B595A50E879#第11集$MOE0871BE8BEB4B595A50E878#第12集$MOE0871BE8BEB4B595A50E87B#第13集$MOE0871BE8BEB4B595A50E87A#第14集$MOE0871BE8BEB4B595A50E87D#第15集$MOE0871BE8BEB4B595A50E87C#第16集$MOE0871BE8BEB4B595A50E87F#第17集$MOE0871BE8BEB4B595A50E87E#第18集$MOE0871BE8BEB4B595A50E871#第19集$MOE0871BE8BEB4B595A50E870#第20集$MOE0871BE8BEB4B595A50EB79#第21集$MOE0871BE8BEB4B595A50EB78#第22集$MOE0871BE8BEB4B595A50EB7B#第23集$MOE0871BE8BEB4B595A50EB7A#第24集$MOE0871BE8BEB4B595A50EB7D$$$第01集$id_XS0871BE8BEB4B595A50E978#第02集$id_XS0871BE8BEB4B595A50E97B#第03集$id_XS0871BE8BEB4B595A50E97A#第04集$id_XS0871BE8BEB4B595A50E97D#第05集$id_XS0871BE8BEB4B595A50E97C#第06集$id_XS0871BE8BEB4B595A50E97F#第07集$id_XS0871BE8BEB4B595A50E97E#第08集$id_XS0871BE8BEB4B595A50E971#第09集$id_XS0871BE8BEB4B595A50E970#第10集$id_XS0871BE8BEB4B595A50E879#第11集$id_XS0871BE8BEB4B595A50E878#第12集$id_XS0871BE8BEB4B595A50E87B#第13集$id_XS0871BE8BEB4B595A50E87A#第14集$id_XS0871BE8BEB4B595A50E87D#第15集$id_XS0871BE8BEB4B595A50E87C#第16集$id_XS0871BE8BEB4B595A50E87F#第17集$id_XS0871BE8BEB4B595A50E87E#第18集$id_XS0871BE8BE