INSERT INTO `mac_vod` VALUES (579, 1, 0, 0, '命运之夜 无限剑制', 'Fate/stay night [Unlimited Blade Works]（2014）', 'mingyunzhiyewuxianjianzhi', 1, 'M', '', '87238c85', '热血,奇幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2220182517.jpg', '', '', '', '杉山纪彰 / 植田佳奈 / 川澄绫子 / 诹访部顺一 / 下屋则子 / 门胁舞以 / 神奈延年 / 伊藤美纪 / 中田让治 / 小山力也 / 神谷浩史 / 三木真一郎 / 田中敦子 / 寺杣昌纪 / 浅川悠 / 西前忠久 / 真殿光昭 / 关智一', '三浦贵博', '', '', '圣杯是传说中可实现持有者一切愿望的宝物。而为了得到圣杯的仪式就被称为圣杯战争。', '全25集 Sunny Day', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 8.7, 0, 0, 1734201136, 1734139766, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>圣杯是传说中可实现持有者一切愿望的宝物。而为了得到圣杯的仪式就被称为圣杯战争。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第00集$MOE0920BE8BB14A550C50E978#第01集$MOE0920BE8BB14A550C50E97B#第02集$MOE0920BE8BB14A550C50E97A#第03集$MOE0920BE8BB14A550C50E97D#第04集$MOE0920BE8BB14A550C50E97C#第05集$MOE0920BE8BB14A550C50E97F#第06集$MOE0920BE8BB14A550C50E97E#第07集$MOE0920BE8BB14A550C50E971#第08集$MOE0920BE8BB14A550C50E970#第09集$MOE0920BE8BB14A550C50E879#第10集$MOE0920BE8BB14A550C50E878#第11集$MOE0920BE8BB14A550C50E87B#第12集$MOE0920BE8BB14A550C50E87A#第13集$MOE0920BE8BB14A550C50E87D#第14集$MOE0920BE8BB14A550C50E87C#第15集$MOE0920BE8BB14A550C50E87F#第16集$MOE0920BE8BB14A550C50E87E#第17集$MOE0920BE8BB14A550C50E871#第18集$MOE0920BE8BB14A550C50E870#第19集$MOE0920BE8BB14A550C50EB79#第20集$MOE0920BE8BB14A550C50EB78#第21集$MOE0920BE8BB14A550C50EB7B#第22集$MOE0920BE8BB14A550C50EB7A#第23集$MOE0920BE8BB14A550C50EB7D#第24集$MOE0920BE8BB14A550C50EB7C#第25集$MOE0920BE8BB14A550C50EB7F#Sunny Day$MOE0920BE8BB14A550C50EB7E$$$第00集$id_XS0920BE8BB14A550C50E978#第01集$id_XS0920BE8BB14A550C50E97B#第02集$id_XS0920BE8BB14A550C50E97A#第03集$id_XS0920BE8BB14A550C50E97D#第04集$id_XS0920BE8BB14A550C50E97C#第05集$id_XS0920BE8BB14A550C50E97F#第06集$id_XS0920BE8BB14A550C50E97E#第07集$id_XS0920BE8BB14A550C50E971#第08集$id_XS0920BE8BB14A550C50E970#第09集$id_XS0920BE8BB14A550C50E879#第10集$id_XS0920BE8BB14A550C50E878#第11集$id_XS0920BE8BB14A550C50E87B#第1