INSERT INTO `mac_vod` VALUES (594, 2, 0, 0, '复活的鲁路修', 'コードギアス 復活のルルーシュ（2019）', 'fuhuodeluluxiu', 1, 'F', '', '521d2ecb', '剧场版', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2548230523.jpg', '', '', '', '福山润 / 野上尤加奈 / 樱井孝宏 / 名冢佳织 / 小清水亚美 / 白鸟哲 / 新井里美 / 千叶纱子 / 真殿光昭 / 桧山修之 / 皆川纯子 / 幸野善之 / 成田剑 / 后藤邑子 / 保志总一朗 / 井上伦宏 / 仓田雅世 / 三户耕三 / 黑泽朋世 / 高田裕司 / 渡边明乃 / 金井美香 / 折笠富美子 / 大原沙耶香 / 杉山纪彰 / 户田惠子 / 村濑步 / 大塚明夫 / 岛崎信长 / 高木涉 / 津田健次郎', '谷口悟朗', '', '', '光和2年。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 8.7, 0, 0, 1734431836, 1734232926, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>光和2年。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0425BDDCBB4C0E5B50E978$$$正片$id_MOE0425BDDCBB4C0E5B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (595, 1, 0, 0, '莉可丽丝', '', 'likelisi', 1, 'L', '', 'fa1404d', '原创,日常,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/53e6a08505b5a889feb14d2f5ee8a7f22b961847.png', '', '', '', '安济知佳 / 若山诗音 / 小清水亚美 / 久野美咲 / 榊孝辅 / 河濑茉希 / 泽海阳子 / 上田耀司 / 松冈祯丞 / 八神结香 / 榊原优希 / 小市真琴', '足立慎吾 / 丸山裕介 / 伊福觉志 / 关晓子 / 柴田裕介 / 竹内哲也 / 佐久间贵史 / 尾之上知久', '', '', '安宁的日常——背后却暗藏秘密\r\n将犯罪防患于未然的秘密组织——“DA（Direct Attack）”\r\n隶属于DA的少女特工——“莉可丽丝”\r\n\r\n理所当然的日常，都要归功于她们。\r\n\r\n咖啡厅“莉可莉可” 作为', '全13集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 51, 0, 51, 51, '', 0, 0, 9.2, 0, 0, 1734260863, 1734239715, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>安宁的日常——背后却暗藏秘密\n将犯罪防患于未然的秘密组织——“DA（Direct Attack）”\n隶属于DA的少女特工——“莉可丽丝”\n\n理所当然的日常，都要归功于她们。\n\n咖啡厅“莉可莉可” 作为DA支部，员工有号称史上最强莉可丽丝的精英·锦木千束、优秀却暗藏隐情的莉可丽丝·井上泷奈。\n\n这里供应的不光是咖啡和甜品，还有照顾孩子、代为购物、教外国人日语等服务，全都不像是“莉可丽丝”会做的事。\n\n自由随性又乐天的和平主义者·千束和效率至上的泷奈，反差巨大的两人组成搭档，开始了忙忙碌碌的每一天。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5776BD8CB91D09144DE8#第02集$MOE5776BD8CB91D09144DEB#第03集$MOE5776BD8CB91D09144DEA#第04集$MOE5776BD8CB91D09144DED#第05集$MOE5776BD8CB91D09144DEC#第06集$MOE5776BD8CB91D09144DEF#第07集$MOE5776BD8CB91D09144DEE#第08集$MOE5776BD8CB91D09144DE1#第09集$MOE5776BD8CB91D09144DE0#第10集$MOE5776BD8CB91D09144CE9#第11集$MOE5776BD8CB91D09144CE8#第12集$MOE5776BD8CB91D09144CEB#第13集$MOE5776BD8CB91D09144CEA$$$第01集$id_XS5776BD8CB91D09144DE8#第02集$id_XS5776BD8CB91D09144DEB#第03集$id_XS5776BD8CB91D09144DEA#第04集$id_XS5776BD8CB91D09144DED#第05集$id_XS5776BD8CB91D09144DEC#第06集$id_XS5776BD8CB91D09144DEF#第07集$id_XS5776BD8CB91D09144DEE#第08集$id_XS5776BD8CB91D09144DE1#第09集$id_XS5776BD8CB91D09144DE0#第10集$id_XS5776BD8CB91D09144CE9#第11集$id_XS5776BD8CB91D09144CE8#第12集$id_XS5776BD8CB91D09144CEB#第13集$id_XS5776BD8CB91D09144CEA$$$第01集$id_MOE5776BD8CB91D09144DE8#第02集$id_MOE5776BD8CB91D09144DEB#第03集$id_MOE5776BD8CB91D09144DEA#第04集$id_MOE5776BD8CB91D09144DED#第05集$id_MOE5776BD8CB91D09144DEC#第06集$id_MOE5776BD8CB91D09144DEF#第07集$id_MOE5776BD8CB91D09