INSERT INTO `mac_vod` VALUES (596, 1, 0, 0, '东京卍复仇者', '东京复仇者（2021）', 'dongjingwanfuchouzhe', 1, 'D', '', 'fb4fc7f8', '漫画改', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2639668389.jpg', '', '', '', '新祐树 / 和气杏未 / 逢坂良太 / 林勇 / 铃木达央 / 水中雅章 / 松冈祯丞 / 木村昴 / 野津山幸宏 / 河西健吾 / 小野大辅 / 寺岛拓笃 / 广濑裕也 / 武内骏辅 / 叶山翔太 / 日野聪 / 竹内荣治', '初见浩一', '', '', '花垣武道是个生活潦倒的打工仔，有天，他得知国中时交往的唯一一个女友橘日向，遭罪凶恶的恶党组织“东京卍会”杀害。', '全24集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 7.3, 0, 0, 1734325476, 1734261275, 0, 0, 0, 0, 0.0, '', '597,598', '', '', '', '', '', '', '', '<p>花垣武道是个生活潦倒的打工仔，有天，他得知国中时交往的唯一一个女友橘日向，遭罪凶恶的恶党组织“东京卍会”杀害。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5775B8DEEA1E0B0150E978#第02集$MOE5775B8DEEA1E0B0150E97B#第03集$MOE5775B8DEEA1E0B0150E97A#第04集$MOE5775B8DEEA1E0B0150E97D#第05集$MOE5775B8DEEA1E0B0150E97C#第06集$MOE5775B8DEEA1E0B0150E97F#第07集$MOE5775B8DEEA1E0B0150E97E#第08集$MOE5775B8DEEA1E0B0150E971#第09集$MOE5775B8DEEA1E0B0150E970#第10集$MOE5775B8DEEA1E0B0150E879#第11集$MOE5775B8DEEA1E0B0150E878#第12集$MOE5775B8DEEA1E0B0150E87B#第13集$MOE5775B8DEEA1E0B0150E87A#第14集$MOE5775B8DEEA1E0B0150E87D#第15集$MOE5775B8DEEA1E0B0150E87C#第16集$MOE5775B8DEEA1E0B0150E87F#第17集$MOE5775B8DEEA1E0B0150E87E#第18集$MOE5775B8DEEA1E0B0150E871#第19集$MOE5775B8DEEA1E0B0150E870#第20集$MOE5775B8DEEA1E0B0150EB79#第21集$MOE5775B8DEEA1E0B0150EB78#第22集$MOE5775B8DEEA1E0B0150EB7B#第23集$MOE5775B8DEEA1E0B0150EB7A#第24集$MOE5775B8DEEA1E0B0150EB7D$$$第01集$id_XS5775B8DEEA1E0B0150E978#第02集$id_XS5775B8DEEA1E0B0150E97B#第03集$id_XS5775B8DEEA1E0B0150E97A#第04集$id_XS5775B8DEEA1E0B0150E97D#第05集$id_XS5775B8DEEA1E0B0150E97C#第06集$id_XS5775B8DEEA1E0B0150E97F#第07集$id_XS5775B8DEEA1E0B0150E97E#第08集$id_XS5775B8DEEA1E0B0150E971#第09集$id_XS5775B8DEEA1E0B0150E970#第10集$id_XS5775B8DEEA1E0B0150E879#第11集$id_XS5775B8DEEA1E0B0150E878#第12集$id_XS5775B8DEEA1E0B0150E87B#第13集$id_XS5775B8DEEA1E0B0150E87A#第14集$id_XS5775B8DEEA1E0B0150E87D#第15集$id_XS5775B8DEEA1E0B0150E87C#第16集$id_XS5775B8DEEA1E0B015