INSERT INTO `mac_vod` VALUES (602, 1, 0, 0, '魔法少女☆伊莉雅', 'Fate/kaleid liner プリズマ☆イリヤ（2013）', 'mofashaonvyiliya', 1, 'M', '', '9d9f6cd0', '校园,萌系,热血,战斗', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1949695573.webp', '', '', '', '门胁舞以 / 名冢佳织 / 植田佳奈 / 伊藤静 / 高野直子 / 松来未祐 / 杉山纪彰 / 七绪春日 / 宫川美保 / 伊藤美纪 / 伊濑茉莉也 / 加藤英美里 / 伊藤加奈惠 / 佐藤聪美 / 浪川大辅 / 大原沙耶香', '大沼心', '', '', '伊莉雅是一个就读穗群原学园的普通女孩，有一天被万花筒之杖的人工天然精灵「魔法红宝石」强制缔结契约，成为「魔法少女伊莉雅」。她在万花筒之杖前任持有者远坂凛的命令下，开始被迫帮忙回收阶级卡片……', '全10集 OVA SP', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 9.5, 0, 0, 1734408432, 1734354155, 0, 0, 0, 0, 0.0, '', '603,604,605', '', '', '', '', '', '', '', '<p>伊莉雅是一个就读穗群原学园的普通女孩，有一天被万花筒之杖的人工天然精灵「魔法红宝石」强制缔结契约，成为「魔法少女伊莉雅」。她在万花筒之杖前任持有者远坂凛的命令下，开始被迫帮忙回收阶级卡片……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0873B5DEBF4A090950E978#第02集$MOE0873B5DEBF4A090950E97B#第03集$MOE0873B5DEBF4A090950E97A#第04集$MOE0873B5DEBF4A090950E97D#第05集$MOE0873B5DEBF4A090950E97C#第06集$MOE0873B5DEBF4A090950E97F#第07集$MOE0873B5DEBF4A090950E97E#第08集$MOE0873B5DEBF4A090950E971#第09集$MOE0873B5DEBF4A090950E970#第10集$MOE0873B5DEBF4A090950E879#OVA$MOE0873B5DEBF4A090950E878#SP01$MOE0873B5DEBF4A090950E87B#SP02$MOE0873B5DEBF4A090950E87A#SP03$MOE0873B5DEBF4A090950E87D#SP04$MOE0873B5DEBF4A090950E87C#SP05$MOE0873B5DEBF4A090950E87F$$$第01集$id_XS0873B5DEBF4A090950E978#第02集$id_XS0873B5DEBF4A090950E97B#第03集$id_XS0873B5DEBF4A090950E97A#第04集$id_XS0873B5DEBF4A090950E97D#第05集$id_XS0873B5DEBF4A090950E97C#第06集$id_XS0873B5DEBF4A090950E97F#第07集$id_XS0873B5DEBF4A090950E97E#第08集$id_XS0873B5DEBF4A090950E971#第09集$id_XS0873B5DEBF4A090950E970#第10集$id_XS0873B5DEBF4A090950E879#OVA$id_XS0873B5DEBF4A090950E878#SP01$id_XS0873B5DEBF4A090950E87B#SP02$id_XS0873B5DEBF4A090950E87A#SP03$id_XS0873B5DEBF4A090950E87D#SP04$id_XS0873B5DEBF4A090950E87C#SP05$id_XS0873B5DEBF4A090950E87F$$$第01集$id_MOE0873B5DEBF4A090950E978#第02集$id_MOE0873B5DEBF4A090950E97B#第03集$id_MOE0873B5DEBF4A090950E97A#第04集$id_MOE0873B5DEBF4