INSERT INTO `mac_vod` VALUES (620, 1, 0, 0, '夏日重现', 'サマータイムレンダ（2022）', 'xiarizhongxian', 1, 'X', '', '6bc118d3', '漫画改,奇幻,战斗,推理', 'http://i0.hdslb.com/bfs/bangumi/image/4b2547ffdd6f40f997454b37c0ad48624a1730d9.jpg', '', '', '', '花江夏树 / 永濑安奈 / 白砂沙帆 / 日笠阳子 / 浦山迅 / 小野贤章 / 河濑茉希 / 钉宫理惠 / 久野美咲 / 三瓶由布子 / 小西克幸 / 上田耀司 / 大塚明夫 / 玄田哲章 / 河合纱希子', '渡边步', '', '', '“潮死了。”\r\n\r\n网代慎平收到发小——小舟潮的讣告后，回到了阔别两年的故乡——和歌山市日都岛。\r\n\r\n慎平与亲人朋友重聚，葬礼也顺利地进行着。\r\n然而，好友告诉他“潮的死有疑点，可能是他杀”。\r\n\r\n第二天，邻近', '全25集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 93, 1, 93, 93, '', 0, 0, 9.8, 0, 0, 1734566383, 1734458812, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“潮死了。”\n\n网代慎平收到发小——小舟潮的讣告后，回到了阔别两年的故乡——和歌山市日都岛。\n\n慎平与亲人朋友重聚，葬礼也顺利地进行着。\n然而，好友告诉他“潮的死有疑点，可能是他杀”。\n\n第二天，邻近的一家人突然全部失踪。与此同时，慎平听说了一个不祥的传闻。\n\n“看到与自己一模一样的‘影子’就会被杀。会被影子杀死！”\n\n而且，潮的妹妹——澪说“姐姐在去世的三天前看到了影子”？！\n\n纪淡海峡的夏日小岛上，跨越时间的科幻悬疑剧即将开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775EF89B811090A50E978#第02集$MOE0775EF89B811090A50E97B#第03集$MOE0775EF89B811090A50E97A#第04集$MOE0775EF89B811090A50E97D#第05集$MOE0775EF89B811090A50E97C#第06集$MOE0775EF89B811090A50E97F#第07集$MOE0775EF89B811090A50E97E#第08集$MOE0775EF89B811090A50E971#第09集$MOE0775EF89B811090A50E970#第10集$MOE0775EF89B811090A50E879#第11集$MOE0775EF89B811090A50E878#第12集$MOE0775EF89B811090A50E87B#第13集$MOE0775EF89B811090A50E87A#第14集$MOE0775EF89B811090A50E87D#第15集$MOE0775EF89B811090A50E87C#第16集$MOE0775EF89B811090A50E87F#第17集$MOE0775EF89B811090A50E87E#第18集$MOE0775EF89B811090A50E871#第19集$MOE0775EF89B811090A50E870#第20集$MOE0775EF89B811090A50EB79#第21集$MOE0775EF89B811090A50EB78#第22集$MOE0775EF89B811090A50EB7B#第23集$MOE0775EF89B811090A50EB7A#第24集$MOE0775EF89B811090A50EB7D#第25集$MOE0775EF89B811090A50EB7C$$$第01集$id_XS0775EF89B811090A50E978#第02集$id_XS0775EF89B811090A50E97B#第03集$id_XS0775EF89B811090A50E97A#第04集$id_XS0775EF89B811090A50E97D#第05集$id_XS0775EF89B811090A50E97C#第06集$id_XS0775EF89B811090A50E97F#第07集$id_XS0775EF89B811090A50E97E#第08集$id_XS0775EF89B811