INSERT INTO `mac_vod` VALUES (626, 1, 0, 0, '境界的彼方', '境界の彼方（2013）', 'jingjiedebifang', 1, 'J', '', '6fbdfb6e', '恋爱,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/92824bc6a8c7aabbf494c0b276d4aa7b70842976.jpg', '', '', '', '种田梨沙 / 大桥贤一郎 / 茅原实里 / 铃木达央 / 进藤尚美 / 渡边明乃 / / 川澄绫子 / 今野宏美 / 丰田萌绘 / 山冈百合', '石立太一 / 木上益治 / 山田尚子 / 武本康弘 / 北之原孝将 / 小川太一 / 河浪荣作', '', '', '【本片翻译由澄空学园字幕组提供】“那一族”唯一存活下来的少女与根本说不上是存在的“半妖”少年的二个人之间的故事。由人类与妖梦所生出的少年神原秋人某天在学校的屋顶上遇到从天而降的少女栗山未来。就算在异界', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 9.5, 0, 0, 1734618210, 1734546954, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由澄空学园字幕组提供】“那一族”唯一存活下来的少女与根本说不上是存在的“半妖”少年的二个人之间的故事。由人类与妖梦所生出的少年神原秋人某天在学校的屋顶上遇到从天而降的少女栗山未来。就算在异界士中，她也算是拥有著特异之诅咒一族最后活下来的少女。不变的教室、不变的日常、不变的世界，原本日子理应如此一天一天的走过。不过……唯一生存下来的少女与半妖少年的相会成为了这个世界唯一的改变……。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第00集$MOE0771EEDCEF4B5B5C50E979#第01集$MOE0771EEDCEF4B5B5C50E978#第02集$MOE0771EEDCEF4B5B5C50E97B#第03集$MOE0771EEDCEF4B5B5C50E97A#第04集$MOE0771EEDCEF4B5B5C50E97D#第05集$MOE0771EEDCEF4B5B5C50E97C#第06集$MOE0771EEDCEF4B5B5C50E97F#第07集$MOE0771EEDCEF4B5B5C50E97E#第08集$MOE0771EEDCEF4B5B5C50E971#第09集$MOE0771EEDCEF4B5B5C50E970#第10集$MOE0771EEDCEF4B5B5C50E879#第11集$MOE0771EEDCEF4B5B5C50E878#第12集$MOE0771EEDCEF4B5B5C50E87B$$$第00集$id_XS0771EEDCEF4B5B5C50E979#第01集$id_XS0771EEDCEF4B5B5C50E978#第02集$id_XS0771EEDCEF4B5B5C50E97B#第03集$id_XS0771EEDCEF4B5B5C50E97A#第04集$id_XS0771EEDCEF4B5B5C50E97D#第05集$id_XS0771EEDCEF4B5B5C50E97C#第06集$id_XS0771EEDCEF4B5B5C50E97F#第07集$id_XS0771EEDCEF4B5B5C50E97E#第08集$id_XS0771EEDCEF4B5B5C50E971#第09集$id_XS0771EEDCEF4B5B5C50E970#第10集$id_XS0771EEDCEF4B5B5C50E879#第11集$id_XS0771EEDCEF4B5B5C50E878#第12集$id_XS0771EEDCEF4B5B5C50E87B$$$第00集$id_MOE0771EEDCEF4B5B5C50E979#第01集$id_MOE0771EEDCEF4B5B5C50E978#第02集$id_MOE0771EEDCEF4B5B5C50E97B#第03集$id_MOE0771EEDCEF4B5B5C50E97A#第04集$id_MOE0771EEDCEF4B5B5C50E97D#第05集$id_MOE0771EEDCEF4B5B5C50E97C#第06集$id_MOE0771EEDCEF4B5B5C50E97F#第07集$id_MOE07