INSERT INTO `mac_vod` VALUES (636, 1, 0, 0, 'CLANNAD ～AFTER STORY～', '团子大家族 第二季（2008）', 'CLANNADAFTERSTORY', 1, 'C', '', '23fd9aac', '时泪,校园,治愈,催泪', 'http://i0.hdslb.com/bfs/bangumi/image/3a74ca41bae1a94e45b3d23afbb62b7ab613b5df.png', '', '', '', '中村悠一 / 中原麻衣 / 兴梠里美 / 置鲇龙太郎 / 井上喜久子 / 绿川光 / 野中蓝 / 阪口大助 / 田村由香里 / 皆口裕子 / 雪野五月 / 榎本温子 / 广桥凉 / 神田朱未 / 能登麻美子 / 桑岛法子 / 川名真知子 / 朴璐美 / 相泽舞 / 金子英彦 / 川庄美雪 / 鹿野优以 / 室园丈裕 / 园部启一 / 早水理沙 / 山口由里子 / 泽田敏子 / 青野武 / 桑谷夏子 / 小野大辅 / 中博史 / 麻生美代子 / 矢岛晶子 / 川上伦子', '石原立也 / 山田尚子 / 石立太一 / 高雄统子 / 坂本一也 / 北之原孝将', '', '', '在某个小镇，主角冈崎朋也因家庭因素成为不良少年，一直与春原阳平为伍，在光坂高校过着潦倒的生活，但冀望终有一天能够离开所在的小镇。某一天，他在学校坡道前发现了一个止步不前的女孩，在朋也认识了这个名为“古', '全22集 OVA', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 68, 0, 68, 68, '', 0, 0, 9.9, 0, 0, 1734693056, 1734650613, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在某个小镇，主角冈崎朋也因家庭因素成为不良少年，一直与春原阳平为伍，在光坂高校过着潦倒的生活，但冀望终有一天能够离开所在的小镇。某一天，他在学校坡道前发现了一个止步不前的女孩，在朋也认识了这个名为“古河渚”的女孩后，他的生活开始有了重大的变化。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0324EADCB0480C5A50E978#第02集$MOE0324EADCB0480C5A50E97B#第03集$MOE0324EADCB0480C5A50E97A#第04集$MOE0324EADCB0480C5A50E97D#第05集$MOE0324EADCB0480C5A50E97C#第06集$MOE0324EADCB0480C5A50E97F#第07集$MOE0324EADCB0480C5A50E97E#第08集$MOE0324EADCB0480C5A50E971#第09集$MOE0324EADCB0480C5A50E970#第10集$MOE0324EADCB0480C5A50E879#第11集$MOE0324EADCB0480C5A50E878#第12集$MOE0324EADCB0480C5A50E87B#第13集$MOE0324EADCB0480C5A50E87A#第14集$MOE0324EADCB0480C5A50E87D#第15集$MOE0324EADCB0480C5A50E87C#第16集$MOE0324EADCB0480C5A50E87F#第17集$MOE0324EADCB0480C5A50E87E#第18集$MOE0324EADCB0480C5A50E871#第19集$MOE0324EADCB0480C5A50E870#第20集$MOE0324EADCB0480C5A50EB79#第21集$MOE0324EADCB0480C5A50EB78#第22集$MOE0324EADCB0480C5A50EB7B#一年前的事$MOE0324EADCB0480C5A50EB7A#另一个世界 杏篇$MOE0324EADCB0480C5A50EB7D#总集篇$MOE0324EADCB0480C5A50EB7C$$$第01集$id_XS0324EADCB0480C5A50E978#第02集$id_XS0324EADCB0480C5A50E97B#第03集$id_XS0324EADCB0480C5A50E97A#第04集$id_XS0324EADCB0480C5A50E97D#第05集$id_XS0324EADCB0480C5A50E97C#第06集$id_XS0324EADCB048