INSERT INTO `mac_vod` VALUES (643, 2, 0, 0, '天使降临到我身边：珍贵的朋友', '私に天使が舞い降りた！プレシャス・フレンズ（2022）', 'tianshijianglindaowoshenbianzhenguidepengyou', 1, 'T', '', 'd03376b0', '日常,治愈,漫画改,萌系', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2874423776.jpg', '', '', '', '上田丽奈 / 指出毬亚 / 长江里加 / 鬼头明里 / 大和田仁美 / 大空直美 / Lynn', '平牧大辅', '', '', '超絶かわいいあの娘と仲良くなりたい系スケッチコメディーが劇場で再び開幕！', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 8.1, 0, 0, 1734759773, 1734724625, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>超絶かわいいあの娘と仲良くなりたい系スケッチコメディーが劇場で再び開幕！</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5527BF8BBE1F0F0950E978$$$正片$id_MOE5527BF8BBE1F0F0950E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (644, 1, 0, 0, '孤独摇滚！', 'ぼっち・ざ・ろっく！（2022）', 'guduyaogun', 1, 'G', '', 'fb35c475', '漫画改,音乐,日常', 'https://i0.hdslb.com/bfs/bangumi/image/d9d6284e0919ecfda41981c1f9119f993db62935.jpg', '', '', '', '青山吉能 / 铃代纱弓 / 水野朔 / 长谷川育美 / 间岛淳司 / 末柄里惠 / 和多田美咲 / 内田真礼 / 小岩井小鸟 / 千本木彩花 / 天城莎莉 / 河濑茉希', '斋藤圭一郎', '', '', '绰号“小孤独”的后藤独，是一个喜爱吉他的孤独少女。经常在家里独自弹奏吉他，但因为一些事情，加入了伊地知虹夏领衔的“纽带乐队”。不敢在他人面前演奏的后藤，能否成为一个出色的乐队成员呢……', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 267, 0, 267, 267, '', 0, 0, 9.9, 0, 0, 1734761139, 1734724973, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>绰号“小孤独”的后藤独，是一个喜爱吉他的孤独少女。经常在家里独自弹奏吉他，但因为一些事情，加入了伊地知虹夏领衔的“纽带乐队”。不敢在他人面前演奏的后藤，能否成为一个出色的乐队成员呢……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5775BF8DEA1D5A0C50E978#第02集$MOE5775BF8DEA1D5A0C50E97B#第03集$MOE5775BF8DEA1D5A0C50E97A#第04集$MOE5775BF8DEA1D5A0C50E97D#第05集$MOE5775BF8DEA1D5A0C50E97C#第06集$MOE5775BF8DEA1D5A0C50E97F#第07集$MOE5775BF8DEA1D5A0C50E97E#第08集$MOE5775BF8DEA1D5A0C50E971#第09集$MOE5775BF8DEA1D5A0C50E970#第10集$MOE5775BF8DEA1D5A0C50E879#第11集$MOE5775BF8DEA1D5A0C50E878#第11.5集$MOE5775BF8DEA1D5A0C50E87B#第12集$MOE5775BF8DEA1D5A0C50E87A$$$第01集$id_XS5775BF8DEA1D5A0C50E978#第02集$id_XS5775BF8DEA1D5A0C50E97B#第03集$id_XS5775BF8DEA1D5A0C50E97A#第04集$id_XS5775BF8DEA1D5A0C50E97D#第05集$id_XS5775BF8DEA1D5A0C50E97C#第06集$id_XS5775BF8DEA1D5A0C50E97F#第07集$id_XS5775BF8DEA1D5A0C50E97E#第08集$id_XS5775BF8DEA1D5A0C50E971#第09集$id_XS5775BF8DEA1D5A0C50E970#第10集$id_XS5775BF8DEA1D5A0C50E879#第11集$id_XS5775BF8DEA1D5A0C50E878#第11.5集$id_XS5775BF8DEA1D5A0C50E87B#第12集$id_XS5775BF8DEA1D5A0C50E87A$$$第01集$id_MOE5775BF8DEA1D5A0C50E978#第02集$id_MOE5775BF8DEA1D5A0C50E97B#第03集$id_MOE5775BF8DEA1D5A0C50E97A#第04集$id_MOE5775BF8DEA1D5A0C50E97D#第05集$id_MOE5775BF8DEA1D5A0C50E97C#第06集$id_MOE5775BF8DEA1D5A0C50E97F#第07集$id_MOE5775BF8DEA1D5A0C50E97E#第08集$id_MOE5775BF8DEA1D5A0C50E971#第09集$id_MOE5775BF8DEA1D5A0C50E970#第10集$id_MOE5775BF8DEA1D5A0C50E879#第11集$id_MOE5775BF8DEA1D5A0C50E878#第1