INSERT INTO `mac_vod` VALUES (645, 1, 0, 0, '龙与虎', 'とらドラ!（2008）', 'longyuhu', 1, 'L', '', '64261141', '少女,校园,治愈,催泪', 'http://i0.hdslb.com/bfs/bangumi/144910805f172d16c5f544f43939a05d8ca20576.jpg', '', '', '', '钉宫理惠 / 间岛淳司 / 堀江由衣 / 野岛裕史 / 喜多村英梨 / 兴津和幸 / 吉野裕行 / 野中蓝 / 甲斐田裕子 / 田中理惠 / 大原沙耶香 / 阿澄佳奈 / 冈本信彦 / 古泽彻 / 大原崇 / 金光宣明 / 大浦冬华 / 青木强 / 后藤沙绪里 / 日笠阳子 / 石川桃子 / 中村知子 / 高梁碧 / 瞰野纯 / 阿部敦 / 佐藤拓也 / 松原大典 / 逢坂力 / 中西英树 / 石井一贵 / 立花慎之介', '长井龙雪 / 笠井贤一 / 樱美胜志 / 铃木洋平 / 桥本敏一 / 高岛大辅 / 三木俊明 / 石田畅 / 青井小夜 / 雄谷将仁 / 久保山英一 / 浅野胜也 / 斋藤德明 / 山崎茂', '', '', '樱花飞舞的四月，全新的高中二年级，新的班级……\r\n眼神凶恶的普通男孩——高须龙儿，遇上了众人害怕、凶暴残忍的“掌中老虎”逢坂大河，还知道了她不欲为人知的秘密。这就是龙虎相争爱与战斗的序幕。\r\n再加上总是笑', '全25集 OVA', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 9.7, 0, 0, 1734775963, 1734725046, 0, 0, 0, 0, 0.0, '', '646', '', '', '', '', '', '', '', '<p>樱花飞舞的四月，全新的高中二年级，新的班级……\n眼神凶恶的普通男孩——高须龙儿，遇上了众人害怕、凶暴残忍的“掌中老虎”逢坂大河，还知道了她不欲为人知的秘密。这就是龙虎相争爱与战斗的序幕。\n再加上总是笑眯眯的超元气女孩栉枝实乃梨，以及文武双全、勤勉正直，不过却有点奇怪的眼镜班长北村佑作。这群家伙的恋爱怎么会有意想中的那么顺利呢！\n《TIGER×DRAGON！龙与虎》即是一个能带给你关于朋友、恋人和家人间关系启示的校园作品。由《我们俩的田村同学》作者竹宫悠由子以及插画家泰送上的超强恋爱喜剧在此登场。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0723BE8EB818590850E978#第02集$MOE0723BE8EB818590850E97B#第03集$MOE0723BE8EB818590850E97A#第04集$MOE0723BE8EB818590850E97D#第05集$MOE0723BE8EB818590850E97C#第06集$MOE0723BE8EB818590850E97F#第07集$MOE0723BE8EB818590850E97E#第08集$MOE0723BE8EB818590850E971#第09集$MOE0723BE8EB818590850E970#第10集$MOE0723BE8EB818590850E879#第11集$MOE0723BE8EB818590850E878#第12集$MOE0723BE8EB818590850E87B#第13集$MOE0723BE8EB818590850E87A#第14集$MOE0723BE8EB818590850E87D#第15集$MOE0723BE8EB818590850E87C#第16集$MOE0723BE8EB818590850E87F#第17集$MOE0723BE8EB818590850E87E#第18集$MOE0723BE8EB818590850E871#第19集$MOE0723BE8EB818590850E870#第20集$MOE0723BE8EB818590850EB79#第21集$MOE0723BE8EB818590850EB78#第22集$MOE0723BE8EB818590850EB7B#第23集$MOE0723BE8EB818590850EB7A#第24集$MOE0723BE8EB818590850EB7D#第25集$MOE0723BE8EB818590850EB7C#OVA$MOE0723BE8EB818590850EB7F$$$第01集$id_XS0723BE8EB818590850