INSERT INTO `mac_vod` VALUES (647, 1, 0, 0, '月色真美', '月がきれい（2017）', 'yuesezhenmei', 1, 'Y', '', 'a6ad5267', '校园,恋爱,治愈,原创', 'http://i0.hdslb.com/bfs/bangumi/5ce66f68d54052e3a305524b9b06a76977e974fc.jpg', '', '', '', '千叶翔也 / 小原好美 / 田丸笃志 / 村川梨衣 / 白石晴香 / 笔村荣心 / 金子诚 / 石见舞菜香 / 铃木美园 / 千菅春香 / 井上穗乃花 / 广濑裕也 / 熊谷健太郎 / 东山奈央 / 岩中睦树 / 冈和男 / 井上喜久子 / 岩田光央 / 斋藤千和 / 前川凉子 / 石井马克 / 古川慎', '岸诚二 / 池端隆史 / 平井义通 / 藤井隆文 / 平峰义大 / 岩崎光洋 / 中田诚', '', '', '茜与小太郎。\r\n第一次被分到同班，相识的两人。\r\n同班同学、社团伙伴、教师、父母……与周围的关联，自己的成长。\r\n在那个一边被变化与不安追着，一边慌慌张张地向前飞奔的季节之中，有着一段稚嫩而又令人眩目的青春', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 22, 0, 22, 22, '', 0, 0, 9.8, 0, 0, 1734788741, 1734725288, 0, 0, 0, 0, 0.0, '', '648', '', '', '', '', '', '', '', '<p>茜与小太郎。\n第一次被分到同班，相识的两人。\n同班同学、社团伙伴、教师、父母……与周围的关联，自己的成长。\n在那个一边被变化与不安追着，一边慌慌张张地向前飞奔的季节之中，有着一段稚嫩而又令人眩目的青春校园生活。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5021EDDCBC1B5B0E50E978#第02集$MOE5021EDDCBC1B5B0E50E97B#第03集$MOE5021EDDCBC1B5B0E50E97A#第04集$MOE5021EDDCBC1B5B0E50E97D#第05集$MOE5021EDDCBC1B5B0E50E97C#第06集$MOE5021EDDCBC1B5B0E50E97F#第07集$MOE5021EDDCBC1B5B0E50E97E#第08集$MOE5021EDDCBC1B5B0E50E971#第09集$MOE5021EDDCBC1B5B0E50E970#第10集$MOE5021EDDCBC1B5B0E50E879#第11集$MOE5021EDDCBC1B5B0E50E878#第12集$MOE5021EDDCBC1B5B0E50E87B$$$第01集$id_XS5021EDDCBC1B5B0E50E978#第02集$id_XS5021EDDCBC1B5B0E50E97B#第03集$id_XS5021EDDCBC1B5B0E50E97A#第04集$id_XS5021EDDCBC1B5B0E50E97D#第05集$id_XS5021EDDCBC1B5B0E50E97C#第06集$id_XS5021EDDCBC1B5B0E50E97F#第07集$id_XS5021EDDCBC1B5B0E50E97E#第08集$id_XS5021EDDCBC1B5B0E50E971#第09集$id_XS5021EDDCBC1B5B0E50E970#第10集$id_XS5021EDDCBC1B5B0E50E879#第11集$id_XS5021EDDCBC1B5B0E50E878#第12集$id_XS5021EDDCBC1B5B0E50E87B$$$第01集$id_MOE5021EDDCBC1B5B0E50E978#第02集$id_MOE5021EDDCBC1B5B0E50E97B#第03集$id_MOE5021EDDCBC1B5B0E50E97A#第04集$id_MOE5021EDDCBC1B5B0E50E97D#第05集$id_MOE5021EDDCBC1B5B0E50E97C#第06集$id_MOE5021EDDCBC1B5B0E50E97F#第07集$id_MOE5021EDDCBC1B5B0E50E97E#第08集$id_MOE5021EDDCBC1B5B0E50E971#第09集$id_MOE5021EDDCBC1B5B0E50E970#第10集$id