INSERT INTO `mac_vod` VALUES (651, 1, 0, 0, '龙王的工作！', 'りゅうおうのおしごと！（2018）', 'longwangdegongzuo', 1, 'L', '', '588f2505', '小说改,职场', 'http://i0.hdslb.com/bfs/bangumi/b0207dd5dd7a1ce700b9e8f4dbbcfe03c922be6a.jpg', '', '', '', '内田雄马 / 日高里菜 / 佐仓绫音 / 金元寿子 / 茅野爱衣 / 久保由利香 / 桥本千波 / 小仓唯 / 冈本信彦 / 关俊彦 / 千本木彩花 / 速水奖 / 水木一郎 / 堀江美都子', '柳伸亮 / 鴫野彰 / 松本正幸 / 筱崎康行 / 羽多野浩平 / 佐佐木纯人', '', '', '本片围绕着“将棋”这个竞技项目展开，主人公“九头龙八一”仅16岁就获得了将棋界最强头衔“龙王”，某天他的家中竟突然出现了一名9岁的小学女生“雏鹤爱”，并且对方还要成为八一的弟子？！在这样的背景下，一场', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.1, 0, 0, 1734869090, 1734775480, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本片围绕着“将棋”这个竞技项目展开，主人公“九头龙八一”仅16岁就获得了将棋界最强头衔“龙王”，某天他的家中竟突然出现了一名9岁的小学女生“雏鹤爱”，并且对方还要成为八一的弟子？！在这样的背景下，一场奇妙的同居生活就此开始。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE042FB4DEBB1C5D0C50E978#第02集$MOE042FB4DEBB1C5D0C50E97B#第03集$MOE042FB4DEBB1C5D0C50E97A#第04集$MOE042FB4DEBB1C5D0C50E97D#第05集$MOE042FB4DEBB1C5D0C50E97C#第06集$MOE042FB4DEBB1C5D0C50E97F#第07集$MOE042FB4DEBB1C5D0C50E97E#第08集$MOE042FB4DEBB1C5D0C50E971#第09集$MOE042FB4DEBB1C5D0C50E970#第10集$MOE042FB4DEBB1C5D0C50E879#第11集$MOE042FB4DEBB1C5D0C50E878#第12集$MOE042FB4DEBB1C5D0C50E87B$$$第01集$id_XS042FB4DEBB1C5D0C50E978#第02集$id_XS042FB4DEBB1C5D0C50E97B#第03集$id_XS042FB4DEBB1C5D0C50E97A#第04集$id_XS042FB4DEBB1C5D0C50E97D#第05集$id_XS042FB4DEBB1C5D0C50E97C#第06集$id_XS042FB4DEBB1C5D0C50E97F#第07集$id_XS042FB4DEBB1C5D0C50E97E#第08集$id_XS042FB4DEBB1C5D0C50E971#第09集$id_XS042FB4DEBB1C5D0C50E970#第10集$id_XS042FB4DEBB1C5D0C50E879#第11集$id_XS042FB4DEBB1C5D0C50E878#第12集$id_XS042FB4DEBB1C5D0C50E87B$$$第01集$id_MOE042FB4DEBB1C5D0C50E978#第02集$id_MOE042FB4DEBB1C5D0C50E97B#第03集$id_MOE042FB4DEBB1C5D0C50E97A#第04集$id_MOE042FB4DEBB1C5D0C50E97D#第05集$id_MOE042FB4DEBB1C5D0C50E97C#第06集$id_MOE042FB4DEBB1C5D0C50E97F#第07集$id_MOE042FB4DEBB1C5D0C50E97E#第08集$id_MOE042FB4DEBB1C5D0C50E971#第09集$id_MOE042FB4DEBB1C5D0C50E970#第10集$id_MOE042FB4DEBB1C5D0C50E879#第11集$id_MOE042FB4DEBB1C5D0C50E878#第12集