INSERT INTO `mac_vod` VALUES (652, 1, 0, 0, '笨女孩', 'アホガール（2017）', 'bennvhai', 1, 'B', '', 'dbfb2746', '搞笑,校园,漫画改', 'http://i0.hdslb.com/bfs/bangumi/c897c607f6d2e40a18cb9656aed48ea26c252721.jpg', '', '', '', '悠木碧 / 杉田智和 / 原田彩枫 / 上坂堇 / 日笠阳子 / 浪川大辅 / 八代拓 / 千本木彩花 / 佐藤利奈 / 市道真央 / 前田玲奈 / 井口裕香', '草川启造 / 玉木慎吾', '', '', '空前绝后的笨蛋，就在这里！\r\n笨到无可救药的女高中生·花畑佳子。\r\n非常喜欢香蕉。\r\n非常喜欢青梅竹马的阿君。\r\n以上！', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 9.3, 0, 0, 1734873595, 1734775515, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>空前绝后的笨蛋，就在这里！\n笨到无可救药的女高中生·花畑佳子。\n非常喜欢香蕉。\n非常喜欢青梅竹马的阿君。\n以上！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5575EADABB1E590F50E978#第02集$MOE5575EADABB1E590F50E97B#第03集$MOE5575EADABB1E590F50E97A#第04集$MOE5575EADABB1E590F50E97D#第05集$MOE5575EADABB1E590F50E97C#第06集$MOE5575EADABB1E590F50E97F#第07集$MOE5575EADABB1E590F50E97E#第08集$MOE5575EADABB1E590F50E971#第09集$MOE5575EADABB1E590F50E970#第10集$MOE5575EADABB1E590F50E879#第11集$MOE5575EADABB1E590F50E878#第12集$MOE5575EADABB1E590F50E87B$$$第01集$id_XS5575EADABB1E590F50E978#第02集$id_XS5575EADABB1E590F50E97B#第03集$id_XS5575EADABB1E590F50E97A#第04集$id_XS5575EADABB1E590F50E97D#第05集$id_XS5575EADABB1E590F50E97C#第06集$id_XS5575EADABB1E590F50E97F#第07集$id_XS5575EADABB1E590F50E97E#第08集$id_XS5575EADABB1E590F50E971#第09集$id_XS5575EADABB1E590F50E970#第10集$id_XS5575EADABB1E590F50E879#第11集$id_XS5575EADABB1E590F50E878#第12集$id_XS5575EADABB1E590F50E87B$$$第01集$id_MOE5575EADABB1E590F50E978#第02集$id_MOE5575EADABB1E590F50E97B#第03集$id_MOE5575EADABB1E590F50E97A#第04集$id_MOE5575EADABB1E590F50E97D#第05集$id_MOE5575EADABB1E590F50E97C#第06集$id_MOE5575EADABB1E590F50E97F#第07集$id_MOE5575EADABB1E590F50E97E#第08集$id_MOE5575EADABB1E590F50E971#第09集$id_MOE5575EADABB1E590F50E970#第10集$id_MOE5575EADABB1E590F50E879#第11集$id_MOE5575EADABB1E590F50E878#第12集$id_MOE5575EADABB1E590F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (653, 1, 0, 0, '野良神', 'ノラガミ（2014）', 'yeliangshen', 1, 'Y', '', 'cac84ce7', '奇幻,战斗,漫画改,神魔', 'http://i0.hdslb.com/bfs/bangumi/f1146494f45cc2c4a3fa0d081c5ecf4bc3147442.jpg', '', '', '', '神谷浩史 / 内田真礼 / 梶裕贵 / 石川界人 / 钉宫理惠 / 樱井孝宏 / 大川透 / 早见沙织 / 今井麻美 / 茜屋日海夏 / 井泽诗织 / 丰崎爱生 / 小野大辅 / 泽城美雪 / 福山润 / 井上和彦 / 小泽亚李 / 高桥伸也 / 星野贵纪 / 东城日沙子 / 西山宏太朗 / 明坂聪美 / 芹泽优 / 种崎敦美 / 置鲇龙太郎 / 巽悠衣子 / 山本兼平 / 山谷祥生 / 村田太志', '田村耕太郎', '', '', '【本片翻译由WOLF字幕组友情提供】神明的世界，居然也像人类世界一样竞争激烈！没有神社供奉（公司）、缺少香火（资本）的落魄神明夜斗，因为性格缺陷，导致手下的神器（员工）纷纷跳槽。怀抱“受万民景仰”这个', '全12集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 33, 0, 33, 33, '', 0, 0, 9.5, 0, 0, 1734896119, 1734775548, 0, 0, 0, 0, 0.0, '', '654', '', '', '', '', '', '', '', '<p>【本片翻译由WOLF字幕组友情提供】神明的世界，居然也像人类世界一样竞争激烈！没有神社供奉（公司）、缺少香火（资本）的落魄神明夜斗，因为性格缺陷，导致手下的神器（员工）纷纷跳槽。怀抱“受万民景仰”这个伟大梦想的他，只好只身在此岸与彼岸间徘徊，为五块钱的香油钱（五斗米）折腰，接受上至斩妖除魔、下至修东修西的各类委托…… 超贴近现实社会的新神明物语！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5276EF80BD4A080E50E978#第02集$MOE5276EF80BD4A080E50E97B#第03集$MOE5276EF80BD4A080E50E97A#第04集$MOE5276EF80BD4A080E50E97D#第05集$MOE5276EF80BD4A080E50E97C#第06集$MOE5276EF80BD4A080E50E97F#第07集$MOE5276EF80BD4A080E50E97E#第08集$MOE5276EF80BD4A080E50E971#第09集$MOE5276EF80BD4A080E50E970#第10集$MOE5276EF80BD4A080E50E879#第11集$MOE5276EF80BD4A080E50E878#第12集$MOE5276EF80BD4A080E50E87B$$$第01集$id_XS5276EF80BD4A080E50E978#第02集$id_XS5276EF80BD4A080E50E97B#第03集$id_XS5276EF80BD4A080E50E97A#第04集$id_XS5276EF80BD4A080E50E97D#第05集$id_XS5276EF80BD4A080E50E97C#第06集$id_XS5276EF80BD4A080E50E97F#第07集$id_XS5276EF80BD4A080E50E97E#第08集$id_XS5276EF80BD4A080E50E971#第09集$id_XS5276EF80BD4A080E50E970#第10集$id_XS5276EF80BD4A080E50E879#第11集$id_XS5276EF80BD4A080E50E878#第12集$id_XS5276EF80BD4A080E50E87B$$$第01集$id_MOE5276EF80BD4A080E50E978#第02集$id_MOE5276EF80BD4A080E50E97B#第03集$id_MOE5276EF80BD4A080E50E97A#第04集$id_MOE5276EF80BD4A080E50E97D#第05集$id_MOE5276EF80BD4A080E50E97C#第06集$id_MOE5276EF80BD4A080E50E97F#第07集$id_MOE5276EF80BD4A080E50E97E#第08集$id_MOE5276EF80BD4A080E50E971#第09集$id_MOE5276EF80BD4A080E50E970#第10集$id_MOE5276EF80BD4A080E50E879#第11集$id_MOE5276EF80BD4A080E50E878#第12集$id_MOE5276EF80BD4A080E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (654, 1, 0, 0, '野良神 ARAGOTO', 'ノラガミ ARAGOTO（2015）', 'yeliangshenARAGOTO', 1, 'Y', '', '4bec2a09', '奇幻,战斗,漫画改,神魔', 'http://i0.hdslb.com/bfs/bangumi/88775e3bd8fa1dc147b5e1686c604162cf06ae8b.jpg', '', '', '', '神谷浩史 / 内田真礼 / 梶裕贵 / 泽城美雪 / 福山润 / 丰崎爱生 / 小野大辅 / 大川透 / 井上和彦 / 今井麻美 / 钉宫理惠', 'タムラコータロー', '', '', '在此岸与彼岸的交界处，八百万神明和服侍他们的死灵——神器，以及被称为妖的魑魅魍魉一同生活着。\r\n某天，普通的女初中生一岐日和意外遇到了居无定所、没有工作、自称是“神”的青年夜斗。其实此话不假，夜斗是个没', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 58, 0, 58, 58, '', 0, 0, 9.4, 0, 0, 1734915168, 1734775572, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在此岸与彼岸的交界处，八百万神明和服侍他们的死灵——神器，以及被称为妖的魑魅魍魉一同生活着。\n某天，普通的女初中生一岐日和意外遇到了居无定所、没有工作、自称是“神”的青年夜斗。其实此话不假，夜斗是个没有神社供奉、缺少香火的落魄神明，因为性格缺陷，导致手下的神器纷纷跳槽。怀抱“受万民景仰”这个伟大愿望的他，只好只身在此岸与彼岸间徘徊，为五元（日语中“五元”与“有缘”同音）的香油钱折腰，接受上至斩妖除魔，下至修东修西的各类委托。\n然而像这样一个粗心大意、性情不定，而且不能很好地听人祈愿、没有人知道的神明却有一个能力，那就是将此岸与彼岸以及其夹缝——世上各种杂七杂八的东西斩断。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0575E9DBBB485D0050E978#第02集$MOE0575E9DBBB485D0050E97B#第03集$MOE0575E9DBBB485D0050E97A#第04集$MOE0575E9DBBB485D0050E97D#第05集$MOE0575E9DBBB485D0050E97C#第06集$MOE0575E9DBBB485D0050E97F#第07集$MOE0575E9DBBB485D0050E97E#第08集$MOE0575E9DBBB485D0050E971#第09集$MOE0575E9DBBB485D0050E970#第10集$MOE0575E9DBBB485D0050E879#第11集$MOE0575E9DBBB485D0050E878#第12集$MOE0575E9DBBB485D0050E87B#第13集$MOE0575E9DBBB485D0050E87A$$$第01集$id_XS0575E9DBBB485D0050E978#第02集$id_XS0575E9DBBB485D0050E97B#第03集$id_XS0575E9DBBB485D0050E97A#第04集$id_XS0575E9DBBB485D0050E97D#第05集$id_XS0575E9DBBB485D0050E97C#第06集$id_XS0575E9DBBB485D0050E97F#第07集$id_XS0575E9DBBB485D0050E97E#第08集$id_XS0575E9DBBB485D0050E971#第09集$id_XS0575E9DBBB485D0050E970#第10集$id_XS0575E9DBBB485D0050E879#第11集$id_XS0575E9DBBB485D0050E878#第12集$id_XS0575E9DBBB485D0050E87B#第13集$id_XS0575E9DBBB485D0050E87A$$$第01集$id_MOE0575E9DBBB485D0050E978#第02集$id_MOE0575E9DBBB485D0050E97B#第03集$id_MOE0575E9DBBB485D0050E97A#第04集$id_MOE0575E9DBBB485D0050E97D#第05集$id_MOE0575E9DBBB485D0050E97C#第06集$id_MOE0575E9DBBB485D0050E97F#第07集$id_MOE0575E9DBBB485D0050E97E#第08集$id_MOE0575E9DBBB485D0050E971#第09集$id_MOE0575E9DBBB485D0050E970#第10集$id_MOE0575E9DBBB485D0050E879#第11集$id_MOE0575E9DBBB485D0050E878#第12集$id_MOE0575E9DBBB485D0050E87B#第13集$id_MOE0575E9DBBB485D0050E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (655, 1, 0, 0, 'Re：创世主们', 'Re:CREATORS（2017）', 'Rechuangzaozhu', 1, 'R', '', 'bbaadaee', '奇幻,科幻,穿越,原创', 'http://i0.hdslb.com/bfs/bangumi/3944fe0b84a5763cde6b0573773b89ba86b4321d.jpg', '', '', '', '山下大辉 / 小松未可子 / 水濑祈 / 日笠阳子 / 村川梨衣 / 铃村健一 / 雨宫天 / 坂本真绫 / 斧笃 / 丰崎爱生 / 小西克幸', '青木荣 / 加藤诚 / 别所诚人 / 栗山贵行 / 守田艺成 / 佐藤清光 / 铃木拓磨 / 渡部周 / 林宏树', '', '', '人类创作了许许多多的故事。\r\n喜悦、悲伤、愤怒、感动。这些引人入胜的故事撼动着人们的心灵。\r\n但是，那些不过是作为旁观者的感想罢了。\r\n如果，故事中的登场人物们拥有了“意志”。那么对于他们来说，创作出故事的', '全22集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 8.9, 0, 0, 1734914938, 1734775596, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>人类创作了许许多多的故事。\n喜悦、悲伤、愤怒、感动。这些引人入胜的故事撼动着人们的心灵。\n但是，那些不过是作为旁观者的感想罢了。\n如果，故事中的登场人物们拥有了“意志”。那么对于他们来说，创作出故事的我们，是神一般的存在吗？\n\n——在我等的世界内发起变革。\n——对诸神之地进行制裁。\n\n任何人，都将成为“创造主(Creator)”。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5375EDD9ED48085C50E978#第02集$MOE5375EDD9ED48085C50E97B#第03集$MOE5375EDD9ED48085C50E97A#第04集$MOE5375EDD9ED48085C50E97D#第05集$MOE5375EDD9ED48085C50E97C#第06集$MOE5375EDD9ED48085C50E97F#第07集$MOE5375EDD9ED48085C50E97E#第08集$MOE5375EDD9ED48085C50E971#第09集$MOE5375EDD9ED48085C50E970#第10集$MOE5375EDD9ED48085C50E879#第11集$MOE5375EDD9ED48085C50E878#第12集$MOE5375EDD9ED48085C50E87B#第13集$MOE5375EDD9ED48085C50E87A#第14集$MOE5375EDD9ED48085C50E87D#第15集$MOE5375EDD9ED48085C50E87C#第16集$MOE5375EDD9ED48085C50E87F#第17集$MOE5375EDD9ED48085C50E87E#第18集$MOE5375EDD9ED48085C50E871#第19集$MOE5375EDD9ED48085C50E870#第20集$MOE5375EDD9ED48085C50EB79#第21集$MOE5375EDD9ED48085C50EB78#第22集$MOE5375EDD9ED48085C50EB7B$$$第01集$id_XS5375EDD9ED48085C50E978#第02集$id_XS5375EDD9ED48085C50E97B#第03集$id_XS5375EDD9ED48085C50E97A#第04集$id_XS5375EDD9ED48085C50E97D#第05集$id_XS5375EDD9ED48085C50E97C#第06集$id_XS5375EDD9ED48085C50E97F#第07集$id_XS5375EDD9ED48085C50E97E#第08集$id_XS5375EDD9ED48085C50E971#第09集$id_XS5375EDD9ED48085C50E970#第10集$id_XS5375EDD9ED48085C50E879#第11集$id_XS5375EDD9ED48085C50E878#第12集$id_XS5375EDD9ED48085C50E87B#