INSERT INTO `mac_vod` VALUES (660, 1, 0, 0, '暗杀教室 课外授业篇', '暗殺教室 第2期 課外授業編（2016）', 'anshajiaoshikewaishouyepian', 1, 'A', '', 'feadeee1', '校园,动作,励志', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2364373676.jpg', '', '', '', '福山润 / 渊上舞 / 浅沼晋太郎 / 水岛大宙 / 田中美海', '岸诚二', '', '', '与目前正在播出的TV动画版「暗杀教室 第二期」联动的「暗杀教室 第二期 课外授课篇」将于3月11日起在dTV独占配信。这次动画化的是在TV版中并没有出现的「竹林的一课」和「支配者的一课 第2节课」等。', '全8集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 8.4, 0, 0, 1734818848, 1734786977, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>与目前正在播出的TV动画版「暗杀教室 第二期」联动的「暗杀教室 第二期 课外授课篇」将于3月11日起在dTV独占配信。这次动画化的是在TV版中并没有出现的「竹林的一课」和「支配者的一课 第2节课」等。「课外授课篇」共4话，一话约5分钟 ，后追加4话，共计8话。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5772EDDCEC4C080850E978#第02集$MOE5772EDDCEC4C080850E97B#第03集$MOE5772EDDCEC4C080850E97A#第04集$MOE5772EDDCEC4C080850E97D#第05集$MOE5772EDDCEC4C080850E97C#第06集$MOE5772EDDCEC4C080850E97F#第07集$MOE5772EDDCEC4C080850E97E#第08集$MOE5772EDDCEC4C080850E971$$$第01集$id_XS5772EDDCEC4C080850E978#第02集$id_XS5772EDDCEC4C080850E97B#第03集$id_XS5772EDDCEC4C080850E97A#第04集$id_XS5772EDDCEC4C080850E97D#第05集$id_XS5772EDDCEC4C080850E97C#第06集$id_XS5772EDDCEC4C080850E97F#第07集$id_XS5772EDDCEC4C080850E97E#第08集$id_XS5772EDDCEC4C080850E971$$$第01集$id_MOE5772EDDCEC4C080850E978#第02集$id_MOE5772EDDCEC4C080850E97B#第03集$id_MOE5772EDDCEC4C080850E97A#第04集$id_MOE5772EDDCEC4C080850E97D#第05集$id_MOE5772EDDCEC4C080850E97C#第06集$id_MOE5772EDDCEC4C080850E97F#第07集$id_MOE5772EDDCEC4C080850E97E#第08集$id_MOE5772EDDCEC4C080850E971', '', '', '', '', 0, '', '');
