INSERT INTO `mac_vod` VALUES (662, 1, 0, 0, '赛马娘 第二季', 'ウマ娘 プリティーダービー Season 2（2021）', 'saimaniangdierji', 1, 'S', '', '260b5a2e', '游戏改,运动,偶像,催泪', 'http://i0.hdslb.com/bfs/bangumi/image/c87869bc63883138e9f561a7c303284f6ed1dc89.png', '', '', '', '和气杏未 / 高野麻里佳 / 齐藤真知子 / 大桥彩香 / 青木琉璃子 / 高桥未奈美 / 高柳知叶 / 前田玲奈 / 上田瞳 / 田所梓 / 大坪由佳 / 木村千咲 / 德井青空 / 相坂优歌 / 巽悠衣子 / 松井惠理子 / Lynn / 大西沙织 / 鬼头明里 / 山本希望 / 渡部优衣 / 大空直美 / 福原绫香 / 小仓唯 / 铃木绘理 / 首藤志奈 / 高桥花林 / 土师亚文 / 新田日和 / 桥本千波 / 大和田仁美 / 渡部惠子 / 津田美波 / 香坂沙希 / 优木加奈 / 井上遥乃 /', '及川启 / 成田巧 / 太田知章 / 筑紫大介 / 种村绫隆 / 本间修 / 藤本悟 / 吉川志我津', '', '', '憧憬着皇帝，向不败的三连冠冲刺的马娘东海帝皇，\r\n以及背负着名家的荣耀，向天皇赏连霸发起挑战的目白麦昆。\r\n二人既是对手，也是伙伴，一同向着梦想——\r\n「闪光系列赛」的优胜，全力奔跑！', '全13集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 9.9, 0, 0, 1734840883, 1734809015, 0, 0, 0, 0, 0.0, '', '663', '', '', '', '', '', '', '', '<p>憧憬着皇帝，向不败的三连冠冲刺的马娘东海帝皇，\n以及背负着名家的荣耀，向天皇赏连霸发起挑战的目白麦昆。\n二人既是对手，也是伙伴，一同向着梦想——\n「闪光系列赛」的优胜，全力奔跑！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0321BCDABC485F5C50E978#第02集$MOE0321BCDABC485F5C50E97B#第03集$MOE0321BCDABC485F5C50E97A#第04集$MOE0321BCDABC485F5C50E97D#第05集$MOE0321BCDABC485F5C50E97C#第06集$MOE0321BCDABC485F5C50E97F#第07集$MOE0321BCDABC485F5C50E97E#第08集$MOE0321BCDABC485F5C50E971#第09集$MOE0321BCDABC485F5C50E970#第10集$MOE0321BCDABC485F5C50E879#第11集$MOE0321BCDABC485F5C50E878#第12集$MOE0321BCDABC485F5C50E87B#第13集$MOE0321BCDABC485F5C50E87A$$$第01集$id_XS0321BCDABC485F5C50E978#第02集$id_XS0321BCDABC485F5C50E97B#第03集$id_XS0321BCDABC485F5C50E97A#第04集$id_XS0321BCDABC485F5C50E97D#第05集$id_XS0321BCDABC485F5C50E97C#第06集$id_XS0321BCDABC485F5C50E97F#第07集$id_XS0321BCDABC485F5C50E97E#第08集$id_XS0321BCDABC485F5C50E971#第09集$id_XS0321BCDABC485F5C50E970#第10集$id_XS0321BCDABC485F5C50E879#第11集$id_XS0321BCDABC485F5C50E878#第12集$id_XS0321BCDABC485F5C50E87B#第13集$id_XS0321BCDABC485F5C50E87A$$$第01集$id_MOE0321BCDABC485F5C50E978#第02集$id_MOE0321BCDABC485F5C50E97B#第03集$id_MOE0321BCDABC485F5C50E97A#第04集$id_MOE0321BCDABC485F5C50E97D#第