INSERT INTO `mac_vod` VALUES (666, 1, 0, 0, '入间同学入魔了', '魔入りました！入間くん（2019）', 'rujiantongxuerumoliao', 1, 'R', '', 'f57a891d', '漫画改,校园,搞笑,奇幻', 'http://i0.hdslb.com/bfs/bangumi/image/8ae5fbfcdbe71a4289d5fbcd37b75e1056cdddfd.png', '', '', '', '村濑步 / 木村良平 / 朝井彩加 / 早见沙织 / 小野大辅 / 佐藤拓也 / 黑田崇矢 / 斋贺光希 / 东山奈央 / 柿原彻也 / 山谷祥生 / 本渡枫 / 梶原岳人 / 吉永拓斗 / 大河元气 / 土岐隼一 / 浅见春那 / 森永千才 / 山本希望 / 舞原由佳 / 三谷绫子 / 井泽诗织 / 江口拓也 / 八代拓 / 石井马克 / 新井里美 / 中村大志 / 下崎纮史 / 乡田穗积', '森胁真琴 / 稻垣隆行 / 菱川直树 / 佐藤昌文 / 马引圭 / 榎本守 / 宫崎修治', '', '', '无法拒绝任何拜托的老好人铃木入间，是个从1岁开始就踏入社会、为了金钱东奔西走、在修罗场求生的十四岁少年，他的父母为了金钱将他卖给了恶魔！阴差阳错之下他签下了恶魔契约、进入了恶魔学院、成为了特待生，并且', '全23集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 9.5, 0, 0, 1734997816, 1734874155, 0, 0, 0, 0, 0.0, '', '667,668', '', '', '', '', '', '', '', '<p>无法拒绝任何拜托的老好人铃木入间，是个从1岁开始就踏入社会、为了金钱东奔西走、在修罗场求生的十四岁少年，他的父母为了金钱将他卖给了恶魔！阴差阳错之下他签下了恶魔契约、进入了恶魔学院、成为了特待生，并且即将与学院第一的新生代表决斗——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5722BBD9B1105C5D50E978#第02集$MOE5722BBD9B1105C5D50E97B#第03集$MOE5722BBD9B1105C5D50E97A#第04集$MOE5722BBD9B1105C5D50E97D#第05集$MOE5722BBD9B1105C5D50E97C#第06集$MOE5722BBD9B1105C5D50E97F#第07集$MOE5722BBD9B1105C5D50E97E#第08集$MOE5722BBD9B1105C5D50E971#第09集$MOE5722BBD9B1105C5D50E970#第10集$MOE5722BBD9B1105C5D50E879#第11集$MOE5722BBD9B1105C5D50E878#第12集$MOE5722BBD9B1105C5D50E87B#第13集$MOE5722BBD9B1105C5D50E87A#第14集$MOE5722BBD9B1105C5D50E87D#第15集$MOE5722BBD9B1105C5D50E87C#第16集$MOE5722BBD9B1105C5D50E87F#第17集$MOE5722BBD9B1105C5D50E87E#第18集$MOE5722BBD9B1105C5D50E871#第19集$MOE5722BBD9B1105C5D50E870#第20集$MOE5722BBD9B1105C5D50EB79#第21集$MOE5722BBD9B1105C5D50EB78#第22集$MOE5722BBD9B1105C5D50EB7B#第23集$MOE5722BBD9B1105C5D50EB7A$$$第01集$id_XS5722BBD9B1105C5D50E978#第02集$id_XS5722BBD9B1105C5D50E97B#第03集$id_XS5722BBD9B1105C5D50E97A#第04集$id_XS5722BBD9B1105C5D50E97D#第05集$id_XS5722BBD9B1105C5D50E97C#第06集$id_XS5722BBD9B1105C5D50E97F#第07集$id_XS5722BBD9B1105C5D50E97E#第08集$id_XS5722BBD9B1105C5D50E971#第09集$id_XS5722BBD9B1105C5D50E970#