INSERT INTO `mac_vod` VALUES (670, 1, 0, 0, '齐木楠雄的灾难 第二季', '斉木楠雄のΨ難 第2期（2018）', 'qimunanxiongdezainandierji', 1, 'Q', '', '401d49f1', '搞笑,校园,漫画改,奇幻', 'http://i0.hdslb.com/bfs/bangumi/5e32e992cbb666d42b931a1ab8e3752f9d490b93.jpg', '', '', '', '神谷浩史 / 小野大辅 / 岛崎信长 / 日野聪 / 花江夏树 / 茅野爱衣 / 田村由香里 / 内田真礼 / 细谷佳正 / 前野智昭 / 森久保祥太郎 / 岩田光央 / 爱河里花子 / 山寺宏一 / 田中理惠 / 野岛健儿 / / 梶裕贵 / 喜多村英梨 / 市道真央', '樱井弘明 / 富永恒雄 / 则座诚 / 铃木行 / 筑紫大介 / 村田尚树 / 秦义人 / 本间修 / 牧野友映 / 铃木恭兵 / 佐佐木纯人', '', '', '能够窥视别人的内心、看透墙壁、以念力移动物品、瞬间移动，一出生就拥有一切的超能力！他就是沉默寡言的超能力者，齐木楠雄。在一个平凡的日本家庭，父母都很普通，齐木楠雄的出生却不平凡。齐木楠雄天生下来就是个', '全24集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.8, 0, 0, 1735081522, 1734874455, 0, 0, 0, 0, 0.0, '', '671,672', '', '', '', '', '', '', '', '<p>能够窥视别人的内心、看透墙壁、以念力移动物品、瞬间移动，一出生就拥有一切的超能力！他就是沉默寡言的超能力者，齐木楠雄。在一个平凡的日本家庭，父母都很普通，齐木楠雄的出生却不平凡。齐木楠雄天生下来就是个超能力者，长大后逐渐明白自己与别人不同，虽然拥有足以毁灭世界的力量，但齐木楠雄每天只是想办法让自己默默地隐藏在人群之中。不想引人注目因此极力做个平凡人，直到国中都顺利当个不起眼的学生。然而事与愿违，他上了PK学园遇上了许多特别的同学后，楠雄的父母以及笨蛋燃堂力、中二病患者海藤等人却一点也不打算让他安安静静地过活，甚至连全校第一的美少女照桥都爱上了他！平凡的日子逐渐变成对他来说是个多灾多难的生活...究竟楠雄能不能使用他的超能力，在持续不断的灾难中继续过着不受瞩目的平稳生活？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0527BDDCBD100B0850E978#第02集$MOE0527BDDCBD100B0850E97B#第03集$MOE0527BDDCBD100B0850E97A#第04集$MOE0527BDDCBD100B0850E97D#第05集$MOE0527BDDCBD100B0850E97C#第06集$MOE0527BDDCBD100B0850E97F#第07集$MOE0527BDDCBD100B0850E97E#第08集$MOE0527BDDCBD100B0850E971#第09集$MOE0527BDDCBD100B0850E970#第10集$MOE0527BDDCBD100B0850E879#第11集$MOE0527BDDCBD100B0850E878#第12集$MOE0527BDDCBD100B0850E87B#第13集$MOE0527BDDCBD100B0850E87A#第14集$MOE0527BDDCBD100B0850E87D#第15集$MOE0527BDDCBD100B0850E87C#第16集$MOE0527BDDCBD100B0850E87F#第17集$MOE0527BDDCBD100B0850E87E#第18集$MOE0527BDDCBD100B0850E871#第19集$MOE0527BDDCBD100B0850E870#第20集$MOE0527BDDCBD100B0850EB79#第21集$MOE0527BDDCBD100B0850EB78#第22集$MOE0527BDDCBD100B0850EB7B#第23集$MOE0527BDDCBD100B0850EB7A#第24集$MOE0527BDDCBD100B0850EB7D$$$第01集$id_XS0527BDDCBD100B0850E978#第02集$id_XS0527BDDCBD100B0850E97B#第03集$id_XS0527BDDCBD100B0850E97A#第04集$id_XS0527BDDCBD100B0850E97D#第05集$id_XS0527BDDCBD100B0850E97C#第06集$id_XS0527BDDCBD100B0850E97F#第07集$id_XS0527BDDCBD100B0850E97E#第08集$id_XS0527BDDCBD100B0850E971#第09集$id_XS0527BDDCBD100B0850E970#第10集$id_XS0527BDDCBD100B0850E879#第11集$id_XS0527BDDCBD100B0850E878#第12集$id_XS0527BDDCBD100B0850E87B#第13集$id_XS0527BDDCBD100B0850E87A#第14集$id_XS0527BDDCBD100B0850E87D#第15集$id_XS0527BDDCBD100B0850E87C#第16集$id_XS0527BDDCBD100B0850E87F#第17集$id_XS0527BDDCBD100B0850E87E#第18集$id_XS0527BDDCBD100B0850E871#第19集$id_XS0527BDDCBD100B0850E870#第20集$id_XS0527BDDCBD100B0850EB79#第21集$id_XS0527BDDCBD100B0850EB78#第22集$id_XS0527BDDCBD100B0850EB7B#第23集$id_XS0527BDDCBD100B0850EB7A#第24集$id_XS0527BDDCBD100B0850EB7D$$$第01集$id_MOE0527BDDCBD100B0850E978#第02集$id_MOE0527BDDCBD100B0850E97B#第03集$id_MOE0527BDDCBD100B0850E97A#第04集$id_MOE0527BDDCBD100B0850E97D#第05集$id_MOE0527BDDCBD100B0850E97C#第06集$id_MOE0527BDDCBD100B0850E97F#第07集$id_MOE0527BDDCBD100B0850E97E#第08集$id_MOE0527BDDCBD100B0850E971#第09集$id_MOE0527BDDCBD100B0850E970#第10集$id_MOE0527BDDCBD100B0850E879#第11集$id_MOE0527BDDCBD100B0850E878#第12集$id_MOE0527BDDCBD100B0850E87B#第13集$id_MOE0527BDDCBD100B0850E87A#第14集$id_MOE0527BDDCBD100B0850E87D#第15集$id_MOE0527BDDCBD100B0850E87C#第16集$id_MOE0527BDDCBD100B0850E87F#第17集$id_MOE0527BDDCBD100B0850E87E#第18集$id_MOE0527BDDCBD100B0850E871#第19集$id_MOE0527BDDCBD100B0850E870#第20集$id_MOE0527BDDCBD100B0850EB79#第21集$id_MOE0527BDDCBD100B0850EB78#第22集$id_MOE0527BDDCBD100B0850EB7B#第23集$id_MOE0527BDDCBD100B0850EB7A#第24集$id_MOE0527BDDCBD100B0850EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (671, 1, 0, 0, '齐木楠雄的灾难 完结篇', '斉木楠雄のΨ難 完結編（2018）', 'qimunanxiongdezainanwanjiepian', 1, 'Q', '', '5d4c117c', '搞笑,校园,漫画改,奇幻', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541609859.webp', '', '', '', '神谷浩史 / 小野大辅 / 岛崎信长 / 茅野爱衣 / 日野聪 / 田村由香里 / 内田真礼 / 花江夏树 / 细谷佳正 / 喜多村英梨 / 松风雅也 / 梶裕贵 / 岩田光央 / 爱河里花子 / 野岛健儿 / 樱井浩美 / 本渡枫 / 市道真央 / 田所阳向 / 古川慎', '樱井弘明 / 则座诚', '', '', '完结篇讲述了原作漫画中「忍舞市旅行的小插曲」哦！在忍舞市中，等待齐木和他的小伙伴们的灾难是…！？', '全1集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.8, 0, 0, 1735091656, 1734874461, 0, 0, 0, 0, 0.0, '', '672', '', '', '', '', '', '', '', '<p>完结篇讲述了原作漫画中「忍舞市旅行的小插曲」哦！在忍舞市中，等待齐木和他的小伙伴们的灾难是…！？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0473B8DBB8185A5A50E978$$$第01集$id_XS0473B8DBB8185A5A50E978$$$第01集$id_MOE0473B8DBB8185A5A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (672, 1, 0, 0, '齐木楠雄的灾难 始动篇', '斉木楠雄のΨ難 Ψ始動編（2019）', 'qimunanxiongdezainanshidongpian', 1, 'Q', '', '71077b44', '漫画改,奇幻,日常,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/ba59822eded39b5254fb01448a7f1502101d5624.png', '', '', '', '神谷浩史 / 岛崎信长 / 小野大辅 / 岩田光央 / 爱河里花子 / 茅野爱衣 / 田村由香里 / 日野聪 / 花江夏树 / 鸟海浩辅 / 东山奈央', '樱井弘明 / 则座诚 / 湖山祯崇 / 本间修', '', '', '在电视剧中堪称帅气的超能力，对于高中生齐木楠雄来说只是招致灾难的元凶。作为新动画系列展开的楠雄的日常又会如何！？', '全6集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.8, 0, 0, 1735091730, 1734874468, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在电视剧中堪称帅气的超能力，对于高中生齐木楠雄来说只是招致灾难的元凶。作为新动画系列展开的楠雄的日常又会如何！？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0626BC8FBE4B590D50E978#第02集$MOE0626BC8FBE4B590D50E97B#第03集$MOE0626BC8FBE4B590D50E97A#第04集$MOE0626BC8FBE4B590D50E97D#第05集$MOE0626BC8FBE4B590D50E97C#第06集$MOE0626BC8FBE4B590D50E97F$$$第01集$id_XS0626BC8FBE4B590D50E978#第02集$id_XS0626BC8FBE4B590D50E97B#第03集$id_XS0626BC8FBE4B590D50E97A#第04集$id_XS0626BC8FBE4B590D50E97D#第05集$id_XS0626BC8FBE4B590D50E97C#第06集$id_XS0626BC8FBE4B590D50E97F$$$第01集$id_MOE0626BC8FBE4B590D50E978#第02集$id_MOE0626BC8FBE4B590D50E97B#第03集$id_MOE0626BC8FBE4B590D50E97A#第04集$id_MOE0626BC8FBE4B590D50E97D#第05集$id_MOE0626BC8FBE4B590D50E97C#第06集$id_MOE0626BC8FBE4B590D50E97F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (673, 1, 0, 0, '擅长捉弄的高木同学', 'からかい上手の高木さん（2018）', 'shanchangzhuonongdegaomutongxue', 1, 'S', '', 'dc9872f8', '漫画改,恋爱,校园,搞笑', 'https://i0.hdslb.com/bfs/bangumi/image/27cf3257e5072bc389855636f97a801a66eee267.png', '', '', '', '高桥李依 / 梶裕贵 / 小原好美 / 市道真央 / 小仓唯 / 内田雄马 / 小岩井小鸟 / 冈本信彦 / 落合福嗣 / 田所阳向', '赤城博昭 / 宇根信也 / 大岛博之 / 铃木恭兵 / 佐藤真人 / 村田尚树 / 小仓宏文 / 深濑重', '', '', '害羞就输了的「捉弄」喜剧\r\n\r\n「今天一定要捉弄高木同学，让她觉得丢脸！」在某间中学里，有个一直被坐在隔壁的女孩——高木同学捉弄的男孩西片。他每天都努力奋斗，要反过来捉弄高木同学，但……？\r\n\r\n高木同学和西', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 45, 0, 45, 45, '', 0, 0, 9.9, 0, 0, 1735109298, 1734874515, 0, 0, 0, 0, 0.0, '', '674,675', '', '', '', '', '', '', '', '<p>害羞就输了的「捉弄」喜剧\n\n「今天一定要捉弄高木同学，让她觉得丢脸！」在某间中学里，有个一直被坐在隔壁的女孩——高木同学捉弄的男孩西片。他每天都努力奋斗，要反过来捉弄高木同学，但……？\n\n高木同学和西片的全力「捉弄」青春战斗就此开战！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5574B580BE1B0B0150E978#第02集$MOE5574B580BE1B0B0150E97B#第03集$MOE5574B580BE1B0B0150E97A#第04集$MOE5574B580BE1B0B0150E97D#第05集$MOE5574B580BE1B0B0150E97C#第06集$MOE5574B580BE1B0B0150E97F#第07集$MOE5574B580BE1B0B0150E97E#第08集$MOE5574B580BE1B0B0150E971#第09集$MOE5574B580BE1B0B0150E970#第10集$MOE5574B580BE1B0B0150E879#第11集$MOE5574B580BE1B0B0150E878#第12集$MOE5574B580BE1B0B0150E87B#OVA$MOE5574B580BE1B0B0150E87A$$$第01集$id_XS5574B580BE1B0B0150E978#第02集$id_XS5574B580BE1B0B0150E97B#第03集$id_XS5574B580BE1B0B0150E97A#第04集$id_XS5574B580BE1B0B0150E97D#第05集$id_XS5574B580BE1B0B0150E97C#第06集$id_XS5574B580BE1B0B0150E97F#第07集$id_XS5574B580BE1B0B0150E97E#第08集$id_XS5574B580BE1B0B0150E971#第09集$id_XS5574B580BE1B0B0150E970#第10集$id_XS5574B580BE1B0B0150E879#第11集$id_XS5574B580BE1B0B0150E878#第12集$id_XS5574B580BE1B0B0150E87B#OVA$id_XS5574B580BE1B0B0150E87A$$$第01集$id_MOE5574B580BE1B0B0150E978#第02集$id_MOE5574B580BE1B0B0150E97B#第03集$id_MOE5574B580BE1B0B0150E97A#第04集$id_MOE5574B580BE1B0B0150E97D#第05集$id_MOE5574B580BE1B0B0150E97C#第06集$id_MOE5574B580BE1B0B0150E97F#第07集$id_MOE5574B580BE1B0B0150E97E#第08集$id_MOE5574B580BE1B0B0150