INSERT INTO `mac_vod` VALUES (674, 1, 0, 0, '擅长捉弄的高木同学 第二季', 'からかい上手の高木さん2（2019）', 'shanchangzhuonongdegaomutongxuedierji', 1, 'S', '', '49d34f09', '漫画改,恋爱,校园,搞笑', 'http://i0.hdslb.com/bfs/bangumi/4c7324327dd9ae035007c3e9bc40cd2ce08635b1.jpg', '', '', '', '高桥李依 / 梶裕贵 / 小原好美 / 市道真央 / 小仓唯 / 内田雄马 / 小岩井小鸟 / 冈本信彦 / 落合福嗣 / 内山昂辉 / 悠木碧 / 田所阳向', '赤城博昭 / 宇根信也 / 村田尚树 / 深濑重 / 伊福觉志 / 松村树里亚', '', '', '“今天一定要捉弄高木同学，让她害羞！”\r\n某所初中里，邻座女生高木同学总是捉弄男生西片。\r\n西片为了反过来戏弄高木同学，每天都在奋斗着……\r\n高木同学和西片的全力“捉弄”青春之战就此开始。', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.9, 0, 0, 1735109410, 1734874541, 0, 0, 0, 0, 0.0, '', '675', '', '', '', '', '', '', '', '<p>“今天一定要捉弄高木同学，让她害羞！”\n某所初中里，邻座女生高木同学总是捉弄男生西片。\n西片为了反过来戏弄高木同学，每天都在奋斗着……\n高木同学和西片的全力“捉弄”青春之战就此开始。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE052EE88BBD4F5D0050E978#第02集$MOE052EE88BBD4F5D0050E97B#第03集$MOE052EE88BBD4F5D0050E97A#第04集$MOE052EE88BBD4F5D0050E97D#第05集$MOE052EE88BBD4F5D0050E97C#第06集$MOE052EE88BBD4F5D0050E97F#第07集$MOE052EE88BBD4F5D0050E97E#第08集$MOE052EE88BBD4F5D0050E971#第09集$MOE052EE88BBD4F5D0050E970#第10集$MOE052EE88BBD4F5D0050E879#第11集$MOE052EE88BBD4F5D0050E878#第12集$MOE052EE88BBD4F5D0050E87B$$$第01集$id_XS052EE88BBD4F5D0050E978#第02集$id_XS052EE88BBD4F5D0050E97B#第03集$id_XS052EE88BBD4F5D0050E97A#第04集$id_XS052EE88BBD4F5D0050E97D#第05集$id_XS052EE88BBD4F5D0050E97C#第06集$id_XS052EE88BBD4F5D0050E97F#第07集$id_XS052EE88BBD4F5D0050E97E#第08集$id_XS052EE88BBD4F5D0050E971#第09集$id_XS052EE88BBD4F5D0050E970#第10集$id_XS052EE88BBD4F5D0050E879#第11集$id_XS052EE88BBD4F5D0050E878#第12集$id_XS052EE88BBD4F5D0050E87B$$$第01集$id_MOE052EE88BBD4F5D0050E978#第02集$id_MOE052EE88BBD4F5D0050E97B#第03集$id_MOE052EE88BBD4F5D0050E97A#第04集$id_MOE052EE88BBD4F5D0050E97D#第05集$id_MOE052EE88BBD4F5D0050E97C#第06集$id_MOE052EE88BBD4F5D0050E97F#第07集$id_MOE052EE88BBD4F5D0050E97E#第08集$id_MOE052EE88BBD4F5D0050E971#第09集$id_MOE052EE88BBD4F5D0050E970#第10集$id_MOE052EE88BBD4F5D0050E879#第11集$id_MOE052EE88BBD4F5D0050E878#第12集$id_MOE052EE88BBD4F5D0050E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (675, 1, 0, 0, '擅长捉弄的高木同学 第三季', 'からかい上手の高木さん3（2022）', 'shanchangzhuonongdegaomutongxuedisanji', 1, 'S', '', '4cdec5b', '漫画改,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/image/b56ed5170780b398a545fa0e142af678b90bfda8.jpg', '', '', '', '高桥李依 / 梶裕贵 / 小原好美 / 市道真央 / 小仓唯 / 内田雄马 / 小岩井小鸟 / 冈本信彦 / 落合福嗣 / 内山昂辉 / 悠木碧 / 田所阳向', '赤城博昭', '', '', '“捉弄”缩短了二人的距离，\r\n2022年想要守候的初恋就在这里。\r\n\r\n在一所初中里，有一个叫做西片的男生，他时不时就会遭到同桌女生高木的捉弄。\r\n西片每次思考对策，想要捉弄回高木，都会被高木看透。\r\n\r\n于是西', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 9.9, 0, 0, 1735110746, 1734874547, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“捉弄”缩短了二人的距离，\n2022年想要守候的初恋就在这里。\n\n在一所初中里，有一个叫做西片的男生，他时不时就会遭到同桌女生高木的捉弄。\n西片每次思考对策，想要捉弄回高木，都会被高木看透。\n\n于是西片每天都绞尽脑汁，想要扳回一城…\n然而随着时间变化的不止是季节，还有西片的心境？\n看似占据优势的高木似乎也发生了让她动摇的事情？\n\n是看对方喜欢自己，还是将喜欢展现给对方看——\n让人止不住微笑和心动的“捉弄战争”，终于要进入最终回合！？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0574E8DDEA1C0F144DE8#第02集$MOE0574E8DDEA1C0F144DEB#第03集$MOE0574E8DDEA1C0F144DEA#第04集$MOE0574E8DDEA1C0F144DED#第05集$MOE0574E8DDEA1C0F144DEC#第06集$MOE0574E8DDEA1C0F144DEF#第07集$MOE0574E8DDEA1C0F144DEE#第08集$MOE0574E8DDEA1C0F144DE1#第09集$MOE0574E8DDEA1C0F144DE0#第10集$MOE0574E8DDEA1C0F144CE9#第11集$MOE0574E8DDEA1C0F144CE8#第12集$MOE0574E8DDEA1C0F144CEB$$$第01集$id_XS0574E8DDEA1C0F144DE8#第02集$id_XS0574E8DDEA1C0F144DEB#第03集$id_XS0574E8DDEA1C0F144DEA#第04集$id_XS0574E8DDEA1C0F144DED#第05集$id_XS0574E8DDEA1C0F144DEC#第06集$id_XS0574E8DDEA1C0F144DEF#第07集$id_XS0574E8DDEA1C0F144DEE#第08集$id_XS0574E8DDEA1C0F144DE1#第09集$id_XS0574E8DDEA1C0F144DE0#第10集$id_XS0574E8DDEA1C0F144CE9#第11集$id_XS0574E8DDEA1C0F144CE8#第12集$id_XS0574E8DDEA1C0F144CEB$$$第01集$id_MOE0574E8DDEA1C0F144DE8#第02集$id_MOE0574E8DDEA1C0F144DEB#第03集$id_MOE0574E8DDEA1C0F144DEA#第04集$id_MOE0574E8DDEA1C0F144DED#第05集$id_MOE0574E8DDEA1C0F144DEC#第06集$id_MOE0574E8DDEA1C0F144DEF#第07集$id_MOE0574E8DDEA1C0F144DEE#第08集$id_MOE0574E8DDEA1C0F144DE1#第09集$id_MOE0574E8DDEA1C0F144DE0#第10集$id_MOE0574E8DDEA1C0F144CE9#第11集$id_MOE0574E8DDEA1C0F144CE8#第12集$id_MOE0574E8DDEA1C0F144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (676, 2, 0, 0, '擅长捉弄的高木同学 剧场版', 'からかい上手の高木さん 劇場版（2022）', 'shanchangzhuonongdegaomutongxuejuchangban', 1, 'S', '', 'daf93db3', '漫画改,搞笑,治愈,恋爱', 'https://i0.hdslb.com/bfs/bangumi/image/8494b0785550977b99cd8bf94b11bec208baccca.png', '', '', '', '高桥李依 / 梶裕贵 / 小原好美 / 市道真央 / 小仓唯 / 落合福嗣 / 冈本信彦 / 内山昂辉 / 悠木碧 / 内田雄马 / 小岩井小鸟 / 田所阳向 / 水濑祈 / 户松遥', '赤城博昭', '', '', '在一所初中里，有一个叫做西片的男生，时常遭到同桌女生高木同学的捉弄。\r\n每次他设法捉弄回去，都会被高木同学看透。\r\n季节变换，两个人都升上了三年级。周围的同学们开始思考将来，掺杂着不安与期待的同时，高木同', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.9, 0, 0, 1735110876, 1734874554, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在一所初中里，有一个叫做西片的男生，时常遭到同桌女生高木同学的捉弄。\n每次他设法捉弄回去，都会被高木同学看透。\n季节变换，两个人都升上了三年级。周围的同学们开始思考将来，掺杂着不安与期待的同时，高木同学与西片之间的距离仍未改变。\n\n于是，初中最后的夏天即将开始――\n\n放暑假前一天，二人在归途中偶然邂逅了一只小猫。\n二人为它取名为「小花」，决定在找到猫妈妈之前在神社境内照顾它。\n小花与二人越来越亲密，二人则悉心照料着它。\n\n小小的邂逅带来的，幸福包裹着的盛夏日子，\n养育出崭新的情愫——</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5576EA81BA4D0F0A50E978$$$正片$id_MOE5576EA81BA4D0F0A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (677, 1, 0, 0, '约定的梦幻岛', '約束のネバーランド（2019）', 'yuedingdemenghuandao', 1, 'Y', '', '105a2e5b', '漫画改,热血,冒险,励志', 'http://i0.hdslb.com/bfs/bangumi/65f89e0a0d050ff987159829fcf565faae199d08.png', '', '', '', '诸星堇 / 伊濑茉莉也 / 内田真礼 / 甲斐田裕子 / 藤田奈央 / 植木慎英 / Lynn / 河野日和 / 石上静香 / 茅野爱衣 / 日野麻里 / 森优子 / 小泽亚李 / 小山茉美 / 小林沙苗', '神户守', '', '', '仰慕的母亲并非亲生母亲。一起生活的他们并非兄弟。\r\nGrace=Field House是没有父母的孩子们居住的地方。虽然没有血缘关系，但妈妈和38个兄弟都度过了幸福的每一天，这是不可替代的家。\r\n但是，他', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.8, 0, 0, 1735124810, 1734874672, 0, 0, 0, 0, 0.0, '', '678', '', '', '', '', '', '', '', '<p>仰慕的母亲并非亲生母亲。一起生活的他们并非兄弟。\nGrace=Field House是没有父母的孩子们居住的地方。虽然没有血缘关系，但妈妈和38个兄弟都度过了幸福的每一天，这是不可替代的家。\n但是，他们的日常在某一天突然宣告结束……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0027B9D9BB4C585B50E978#第02集$MOE0027B9D9BB4C585B50E97B#第03集$MOE0027B9D9BB4C585B50E97A#第04集$MOE0027B9D9BB4C585B50E97D#第05集$MOE0027B9D9BB4C585B50E97C#第06集$MOE0027B9D9BB4C585B50E97F#第07集$MOE0027B9D9BB4C585B50E97E#第08集$MOE0027B9D9BB4C585B50E971#第09集$MOE0027B9D9BB4C585B50E970#第10集$MOE0027B9D9BB4C585B50E879#第11集$MOE0027B9D9BB4C585B50E878#第12集$MOE0027B9D9BB4C585B50E87B$$$第01集$id_XS0027B9D9BB4C585B50E978#第02集$id_XS0027B9D9BB4C585B50E97B#第03集$id_XS0027B9D9BB4C585B50E97A#第04集$id_XS0027B9D9BB4C585B50E97D#第05集$id_XS0027B9D9BB4C585B50E97C#第06集$id_XS0027B9D9BB4C585B50E97F#第07集$id_XS0027B9D9BB4C585B50E97E#第08集$id_XS0027B9D9BB4C585B50E971#第09集$id_XS0027B9D9BB4C585B50E970#第10集$id_XS0027B9D9BB4C585B50E879#第11集$id_XS0027B9D9BB4C585B50E878#第12集$id_XS0027B9D9BB4C585B50E87B$$$第01集$id_MOE0027B9D9BB4C585B50E978#第02集$id_MOE0027B9D9BB4C585B50E97B#第03集$id_MOE0027B9D9BB4C585B50E97A#第04集$id_MOE0027B9D9BB4C585B50E97D#第05集$id_MOE0027B9D9BB4C585B50E97C#第06集$id_MOE0027B9D9BB4C585B50E97F#第07集$id_MOE0027B9D9BB4C585B50E97E#第08集$id_MOE0027B9D9BB4C585B50E971#第09集$id_MOE0027B9D9BB4C585B50E970#第10集$id_MOE0027B9D9BB4C585B50E879#第11集$id_MOE0027B9D9BB4C585B50E878#第12集$id_MOE0027B9D9BB4C585B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (678, 1, 0, 0, '约定的梦幻岛 第二季', '約束のネバーランド Season 2（2021）', 'yuedingdemenghuandaodierji', 1, 'Y', '', 'ace4f90c', '漫画改,热血,冒险,励志', 'http://i0.hdslb.com/bfs/bangumi/image/4e259309f0746011c54d5882e3ab8aabdee3d2ad.png', '', '', '', '诸星堇 / 伊濑茉莉也 / 植木慎英 / Lynn / 石上静香 / 茅野爱衣 / 日野麻里 / 森优子 / 青山吉能 / 河野日和 / 林鼓子 / 久远艾丽莎 / 白城奈央 / 神尾晋一郎 / 种崎敦美', '神户守', '', '', '——自由、是多么美丽、而又多么残酷啊。\r\n成功从Grace=Field House逃出的15个孩子。\r\n等待在抛弃虚伪的乐园而勇敢追求自由的他们的面前是、未曾见过的动植物、\r\n以及一路追赶而来的「鬼」……外', '全11集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 2.8, 0, 0, 1735125278, 1734874707, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>——自由、是多么美丽、而又多么残酷啊。\n成功从Grace=Field House逃出的15个孩子。\n等待在抛弃虚伪的乐园而勇敢追求自由的他们的面前是、未曾见过的动植物、\n以及一路追赶而来的「鬼」……外面的世界是如此美丽，却也如此残酷。\n但是孩子们并没有放弃。\n「密涅瓦」的讯息、诺曼留下的一支笔\n根据这些引导，奔向明天。\n去迎接留在House的「家人」，为了完成那个约定。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5074E98CEF105D5A50E978#第02集$MOE5074E98CEF105D5A50E97B#第03集$MOE5074E98CEF105D5A50E97A#第04集$MOE5074E98CEF105D5A50E97D#第05集$MOE5074E98CEF105D5A50E97C#第06集$MOE5074E98CEF105D5A50E97F#第07集$MOE5074E98CEF105D5A50E97E#第08集$MOE5074E98CEF105D5A50E971#第09集$MOE5074E98CEF105D5A50E970#第10集$MOE5074E98CEF105D5A50E879#第11集$MOE5074E98CEF105D5A50E878$$$第01集$id_XS5074E98CEF105D5A50E978#第02集$id_XS5074E98CEF105D5A50E97B#第03集$id_XS5074E98CEF105D5A50E97A#第04集$id_XS5074E98CEF105D5A50E97D#第05集$id_XS5074E98CEF105D5A50E97C#第06集$id_XS5074E98CEF105D5A50E97F#第07集$id_XS5074E98CEF105D5A50E97E#第08集$id_XS5074E98CEF105D5A50E971#第09集$id_XS5074E98CEF105D5A50E970#第10集$id_XS5074E98CEF105D5A50E879#第11集$id_XS5074E98CEF105D5A50E878$$$第01集$id_MOE5074E98CEF105D5A50E978#第02集$id_MOE5074E98CEF105D5A50E97B#第03集$id_MOE5074E98CEF105D5A50E97A#第04集$id_MOE5074E98CEF105D5A50E97D#第05集$id_MOE5074E98CEF105D5A50E97C#第06集$id_MOE5074E98CEF105D5A50E97F#第07集$id_MOE5074E98CEF105D5A50E97E#第08集$id_MOE5074E98CEF105D5A50E971#第09集$id_MOE5074E98CEF105D5A50E970#第10集$id_MOE5074E98CEF105D5A50E879#第11集$id_MOE5074E98CEF105D5A50E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (679, 1, 0, 0, '玉子市场', 'たまこまーけっと（2013）', 'yuzishichang', 1, 'Y', '', 'ae796a04', '萌系,少女,治愈,日常', 'http://i0.hdslb.com/bfs/bangumi/67da3dae76e526a925b78b1d8abe21c870333491.jpg', '', '', '', '洲崎绫 / 田丸笃志 / 金子有希 / 长妻树里 / 山下百合惠 / 日高里菜 / 辻谷耕史 / 津久井教生 / 渡边久美子 / 山崎巧 / 家中宏 / 成田剑 / 日笠阳子 / 川原庆久 / 野坂尚也 / 山冈百合 / 下野纮 / 藤原启治 / 西村知道 / 立木文彦 / 雪野五月 / 小野大辅', '山田尚子 / 石原立也 / 武本康弘 / 石立太一 / 河浪荣作 / 小川太一 / 北之原孝将 / 木上益治', '', '', '　　座落某个小镇的兔子商店街上，有一间日式饼店，住着一位十分喜欢饼类小吃的高中一年级女生——玉子。除了偶尔在店铺协助父亲，以及钻研新口味的饼类小吃外，她亦有跟学校的朋友参与羽毛球部活动。而饼店对面是同', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 29, 0, 29, 29, '', 0, 0, 9.8, 0, 0, 1735132648, 1734874718, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　座落某个小镇的兔子商店街上，有一间日式饼店，住着一位十分喜欢饼类小吃的高中一年级女生——玉子。除了偶尔在店铺协助父亲，以及钻研新口味的饼类小吃外，她亦有跟学校的朋友参与羽毛球部活动。而饼店对面是同行的竞争对手，两边的父亲经常都因生意问题而喧哗。不过对方儿子——饼藏却自小跟玉子建立青梅竹马的关系，近日更不断隐约地表达心思，只是玉子没有特别注意，更常常被旁观的朋友拿出来扰攘一番。总而言之，玉子就是在商店街众人的护荫下，如此热闹地渡过每一天，生活可谓过得相当快乐。\n　　除夕，也就是玉子的生日，处于商店街年末最繁忙的时刻。庆祝仪式已经成为了商店街上下的惯例，唯独今年的饼藏没有准时来到。直到他带着礼物来到之时……一只光辉灿烂的鸟出现在众人面前。偶然变得越来越热闹的兔子商店街，亦正式开始其稍微不同的新一年。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5072BB81BF485D0D50E978#第02集$MOE5072BB81BF485D0D50E97B#第03集$MOE5072BB81BF485D0D50E97A#第04集$MOE5072BB81BF485D0D50E97D#第05集$MOE5072BB81BF485D0D50E97C#第06集$MOE5072BB81BF485D0D50E97F#第07集$MOE5072BB81BF485D0D50E97E#第08集$MOE5072BB81BF485D0D50E971#第09集$MOE5072BB81BF485D0D50E970#第10集$MOE5072BB81BF485D0D50E879#第11集$MOE5072BB81BF485D0D50E878#第12集$MOE5072BB81BF485D0D50E87B$$$第01集$id_XS5072BB81BF485D0D50E978#第02集$id_XS5072BB81BF485D0D50E97B#第03集$id_XS5072BB81BF485D0D50E97A#第04集$id_XS5072BB81BF485D0D50E97D#第05集$id_XS5072BB81BF485D0D50E97C#第06集$id_XS5072BB81BF485D0D50E97F#第07集$id_XS5072BB81BF485D0D50E97E#第08集$id_XS5072BB81BF485D0D50E971#第09集$id_XS5072BB81BF485D0D50E970#第10集$id_XS5072BB81BF485D0D50E879#第11集$id_XS5072BB81BF485D0D50E878#第12集$id_XS5072BB81BF485D0D50E87B$$$第01集$id_MOE5072BB81BF485D0D50E978#第02集$id_MOE5072BB81BF485D0D50E97B#第03集$id_MOE5072BB81BF485D0D50E97A#第04集$id_MOE5072BB81BF485D0D50E97D#第05集$id_MOE5072BB81BF485D0D50E97C#第06集$id_MOE5072BB81BF485D0D50E97F#第07集$id_MOE5072BB81BF485D0D50E97E#第08集$id_MOE5072BB81BF485D0D50E971#第09集$id_MOE5072BB81BF485D0D50E970#第10集$id_MOE5072BB81BF485D0D50E879#第11集$id_MOE5072BB81BF485D0D50E878#第12集$id_MOE5072BB81BF485D0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (680, 2, 0, 0, '玉子爱情故事', 'たまこラブストーリー（2014）', 'yuziaiqinggushi', 1, 'Y', '', '707f4774', '校园,少女,恋爱', 'http://i0.hdslb.com/bfs/bangumi/3d781d52aa2b93188836a1725ecdd286f8df136f.jpg', '', '', '', '洲崎绫 / 田丸笃志 / 金子有希 / 长妻树里 / 山下百合惠 / 日高里菜 / 藤原启治 / 日笠阳子 / 西村知道 / 立木文彦 / 雪野五月 / 辻谷耕史 / 津久井教生 / 岩男润子 / 渡边久美子 / 家中宏 / 成田剑 / 小野大辅 / 川原庆久 / 山下大辉 / 藤村鼓乃美 / 照井春佳 / 升望 / 山崎巧 / 山冈百合 / 下野纮', '山田尚子', '', '', '【本片翻译由雪飘工作室提供】时已入春，已经进入高中三年级的北白川玉子仍然总是想着打糕的事情。春天傍晚的放学路上，玉子好友四人组谈论着关于将来出路的事情。大家虽然对此感到不安，但似乎对将来的事情都有好好', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 27, 0, 27, 27, '', 0, 0, 9.9, 0, 0, 1735143307, 1734874783, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由雪飘工作室提供】时已入春，已经进入高中三年级的北白川玉子仍然总是想着打糕的事情。春天傍晚的放学路上，玉子好友四人组谈论着关于将来出路的事情。大家虽然对此感到不安，但似乎对将来的事情都有好好地考虑过。玉子也无意中说出自己将来想要继承家业。同时，住在玉子家的对面、一直和她在一起的饼藏，也下定了某种决心。——周围的各种事物都在逐渐改变着，一点一点地动摇着玉子的心。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0627BBDEBD1E5A0D50E978$$$正片$id_MOE0627BBDEBD1E5A0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (681, 1, 0, 0, '动物狂想曲 / BEASTARS', 'BEASTARS（2019）', 'dongwukuangxiangquBEASTARS', 1, 'D', '', '96420b83', '漫画改,奇幻,恋爱,校园', 'http://i0.hdslb.com/bfs/bangumi/9585f07662bfc460d157fa431543aa98f6f3a9be.png', '', '', '', '小林亲弘 / 千本木彩花 / 小野友树 / 种崎敦美 / 榎木淳弥 / 内田雄马 / 大塚刚央 / 小林直人 / 下妻由幸 / 冈本信彦', '松见真一', '', '', '肉食兽和草食兽共存的世界。在食肉被视为重罪的情况下 ，全寄宿制的名门高中·却里顿学园发生了学生被吞噬的“食杀事件”。\r\n在充斥着不安的校园里，戏剧部的怪人·灰狼雷格西过着与其“庞大身躯”和“锐利尖牙”相', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 9.7, 0, 0, 1735178816, 1734895684, 0, 0, 0, 0, 0.0, '', '682,683', '', '', '', '', '', '', '', '<p>肉食兽和草食兽共存的世界。在食肉被视为重罪的情况下 ，全寄宿制的名门高中·却里顿学园发生了学生被吞噬的“食杀事件”。\n在充斥着不安的校园里，戏剧部的怪人·灰狼雷格西过着与其“庞大身躯”和“锐利尖牙”相反的安静生活。但是和小巧的兔子的女学生·春的相遇，打动了雷格西的心。\n“我追求她的心情，是恋爱？还是食欲？”\n他真正遇到的东西，是他自己的本能——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0821B88AB94B550A50E978#第02集$MOE0821B88AB94B550A50E97B#第03集$MOE0821B88AB94B550A50E97A#第04集$MOE0821B88AB94B550A50E97D#第05集$MOE0821B88AB94B550A50E97C#第06集$MOE0821B88AB94B550A50E97F#第07集$MOE0821B88AB94B550A50E97E#第08集$MOE0821B88AB94B550A50E971#第09集$MOE0821B88AB94B550A50E970#第10集$MOE0821B88AB94B550A50E879#第11集$MOE0821B88AB94B550A50E878#第12集$MOE0821B88AB94B550A50E87B$$$第01集$id_XS0821B88AB94B550A50E978#第02集$id_XS0821B88AB94B550A50E97B#第03集$id_XS0821B88AB94B550A50E97A#第04集$id_XS0821B88AB94B550A50E97D#第05集$id_XS0821B88AB94B550A50E97C#第06集$id_XS0821B88AB94B550A50E97F#第07集$id_XS0821B88AB94B550A50E97E#第08集$id_XS0821B88AB94B550A50E971#第09集$id_XS0821B88AB94B550A50E970#第10集$id_XS0821B88AB94B550A50E879#第11集$id_XS0821B88AB94B550A50E878#第12集$id_XS0821B88AB94B550A50E87B$$$第01集$id_MOE0821B88AB94B550A50E978#第02集$id_MOE0821B88AB94B550A50E97B#第03集$id_MOE0821B88AB94B550A50E97A#第04集$id_MOE0821B88AB94B550A50E97D#第05集$id_MOE0821B88AB94B550A50E97C#第06集$id_MOE0821B88AB94B550A50E97F#第07集$id_MOE0821B88AB94B550A50E97E#第08集$id_MOE0821B88AB94B550A50E971#第09集$id_MOE0821B88AB94B550A50E970#第10集$id_MOE0821B88AB94B550A50E879#第11集$id_MOE0821B88AB94B550A50E878#第12集$id_MOE0821B88AB94B550A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (682, 1, 0, 0, '动物狂想曲 / BEASTARS 第二季', 'BEASTARS 2nd Season（2021）', 'dongwukuangxiangquBEASTARSdierji', 1, 'D', '', '6cdc040b', '漫画改,校园,恋爱,架空', 'http://i0.hdslb.com/bfs/bangumi/image/de1dc90a7fb5456a9db09b0e21b1d04e3a1606cb.png', '', '', '', '小林亲弘 / 千本木彩花 / 小野友树 / 种崎敦美 / 白熊宽嗣 / 梶裕贵 / 楠大典 / 大塚明夫 / 榎木淳弥 / 虎岛贵明 / 木村昴 / 松本和香子 / 内田雄马 / 大塚刚央 / 小林直人 / 下妻由幸 / 冈本信彦 / 落合福嗣 / 渡部纱弓 / 室元气 / 井口祐一 / 原优子 / 兼政郁人', '松见真一 / 则座诚 / 下司泰弘', '', '', '「我要变得更强。因为我不想输给这个社会和本能。」\r\n雷格西接受了自己食肉动物的身份，并朝着与春的恋情迈进了一步。然而，雷格西本以为自己回到了平静的校园生活，却不知新的危机正在逼近。那就是悬而未决的「食杀', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.1, 0, 0, 1735178977, 1734895697, 0, 0, 0, 0, 0.0, '', '683', '', '', '', '', '', '', '', '<p>「我要变得更强。因为我不想输给这个社会和本能。」\n雷格西接受了自己食肉动物的身份，并朝着与春的恋情迈进了一步。然而，雷格西本以为自己回到了平静的校园生活，却不知新的危机正在逼近。那就是悬而未决的「食杀事件」的犯人的身影…！而且在黑市，本应被打倒了的狮子组的残党，组成了「新狮子组」开始重新积蓄力量…面对新的强大试炼，雷格西能否保护好「真正重要的东西」呢？\n食欲、肉欲、渴望被认可。被各种欲望玩弄于股掌之间，年轻动物们的青春还远未结束…！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0774E8DBB91D5D5B50E978#第02集$MOE0774E8DBB91D5D5B50E97B#第03集$MOE0774E8DBB91D5D5B50E97A#第04集$MOE0774E8DBB91D5D5B50E97D#第05集$MOE0774E8DBB91D5D5B50E97C#第06集$MOE0774E8DBB91D5D5B50E97F#第07集$MOE0774E8DBB91D5D5B50E97E#第08集$MOE0774E8DBB91D5D5B50E971#第09集$MOE0774E8DBB91D5D5B50E970#第10集$MOE0774E8DBB91D5D5B50E879#第11集$MOE0774E8DBB91D5D5B50E878#第12集$MOE0774E8DBB91D5D5B50E87B$$$第01集$id_XS0774E8DBB91D5D5B50E978#第02集$id_XS0774E8DBB91D5D5B50E97B#第03集$id_XS0774E8DBB91D5D5B50E97A#第04集$id_XS0774E8DBB91D5D5B50E97D#第05集$id_XS0774E8DBB91D5D5B50E97C#第06集$id_XS0774E8DBB91D5D5B50E97F#第07集$id_XS0774E8DBB91D5D5B50E97E#第08集$id_XS0774E8DBB91D5D5B50E971#第09集$id_XS0774E8DBB91D5D5B50E970#第10集$id_XS0774E8DBB91D5D5B50E879#第11集$id_XS0774E8DBB91D5D5B50E878#第12集$id_XS0774E8DBB91D5D5B50E87B$$$第01集$id_MOE0774E8DBB91D5D5B50E978#第02集$id_MOE0774E8DBB91D5D5B50E97B#第03集$id_MOE0774E8DBB91D5D5B50E97A#第04集$id_MOE0774E8DBB91D5D5B50E97D#第05集$id_MOE0774E8DBB91D5D5B50E97C#第06集$id_MOE0774E8DBB91D5D5B50E97F#第07集$id_MOE0774E8DBB91D5D5B50E97E#第08集$id_MOE0774E8DBB91D5D5B50E971#第09集$id_MOE0774E8DBB91D5D5B50E970#第10集$id_MOE0774E8DBB91D5D5B50E879#第11集$id_MOE0774E8DBB91D5D5B50E878#第12集$id_MOE0774E8DBB91D5D5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (683, 1, 0, 0, '动物狂想曲 / BEASTARS 最终季', 'BEASTARS Final Season（2024）', 'dongwukuangxiangquzuizhongji', 1, 'D', '', 'c2e1dc94', '漫画改,奇幻,恋爱,校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2910287548.jpg', '', '', '', '小林亲弘 / 千本木彩花 / 小野友树 / 玄田哲章 / 折笠富美子 / 室元气 / 榎木淳弥 / 种崎敦美 / 梶裕贵 / 木村昴 / 大塚明夫 / 三木真一郎 / 千叶繁 / 冲野晃司', '松见真一', '', '', '动物人类剧集《动物狂想曲》迎来新篇章！在最后一战之后，灰狼雷格西去了哪里?《动物狂想曲》是一部动物人类剧集，背景设定在双足食肉动物和食草动物共同生活的世界中。在这个独特的世界里，灰狼雷格西和他的同学们', '全12集', '', 0, '0', '', '', '日本', '日语', '2024', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 8.6, 0, 0, 1735179324, 1734895746, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>动物人类剧集《动物狂想曲》迎来新篇章！在最后一战之后，灰狼雷格西去了哪里?《动物狂想曲》是一部动物人类剧集，背景设定在双足食肉动物和食草动物共同生活的世界中。在这个独特的世界里，灰狼雷格西和他的同学们就读于樱顿高中，所有的学生都住在宿舍里。这是一个超越物种的爱与友谊的故事。然而，有时，他们作为食肉动物和食草动物不可抑制的本能会导致悲剧事件。新的一章讲述了第一季和第二季之后的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5225E989ED4A540D50E978#第02集$MOE5225E989ED4A540D50E97B#第03集$MOE5225E989ED4A540D50E97A#第04集$MOE5225E989ED4A540D50E97D#第05集$MOE5225E989ED4A540D50E97C#第06集$MOE5225E989ED4A540D50E97F#第07集$MOE5225E989ED4A540D50E97E#第08集$MOE5225E989ED4A540D50E971#第09集$MOE5225E989ED4A540D50E970#第10集$MOE5225E989ED4A540D50E879#第11集$MOE5225E989ED4A540D50E878#第12集$MOE5225E989ED4A540D50E87B$$$第01集$id_XS5225E989ED4A540D50E978#第02集$id_XS5225E989ED4A540D50E97B#第03集$id_XS5225E989ED4A540D50E97A#第04集$id_XS5225E989ED4A540D50E97D#第05集$id_XS5225E989ED4A540D50E97C#第06集$id_XS5225E989ED4A540D50E97F#第07集$id_XS5225E989ED4A540D50E97E#第08集$id_XS5225E989ED4A540D50E971#第09集$id_XS5225E989ED4A540D50E970#第10集$id_XS5225E989ED4A540D50E879#第11集$id_XS5225E989ED4A540D50E878#第12集$id_XS5225E989ED4A540D50E87B$$$第01集$id_MOE5225E989ED4A540D50E978#第02集$id_MOE5225E989ED4A540D50E97B#第03集$id_MOE5225E989ED4A540D50E97A#第04集$id_MOE5225E989ED4A540D50E97D#第05集$id_MOE5225E989ED4A540D50E97C#第06集$id_MOE5225E989ED4A540D50E97F#第07集$id_MOE5225E989ED4A540D50E97E#第08集$id_MOE5225E989ED4A540D50E971#第09集$id_MOE5225E989ED