INSERT INTO `mac_vod` VALUES (684, 1, 0, 0, '珈百璃的堕落', 'ガヴリールドロップアウト（2017）', 'jiabailideduoluo', 1, 'J', '', 'eef56972', '日常,漫画改,神魔', 'http://i0.hdslb.com/bfs/bangumi/7b9a5a6e6c5ca157a4c18b01093a7bb1701f4606.jpg', '', '', '', '富田美忧 / 大西沙织 / 大空直美 / 花泽香菜 / 水濑祈 / 渊上舞 / 梅津秀行 / 小山刚志 / 井泽美香子 / 木野日菜 / 诸星堇 / 泽城美雪 / 藤井雪代 / 武虎 / 河原木志穗 / 川岛得爱 / 柚木凉香 / 寺崎裕香 / 高冈瓶瓶 / 山田真一', '太田雅彦 / 远藤彻哉 / 上坪亮树 / 荒井省吾 / 矢花馨 / 原口浩 / 守田艺成 / 野木森达哉 / 佐佐木达也', '', '', '天使学校的首席天使来到了地球！ \r\n……但是，住惯了地球的她，开始过起整天逃学打网游的自甘堕落生活。\r\n化身为怠惰的废柴天使，简称“废天使”的加百列，早就把让全部人类幸福的目标抛到九霄云外，并发誓要充分享', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 23, 0, 23, 23, '', 0, 0, 9.6, 0, 0, 1735182450, 1734895801, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>天使学校的首席天使来到了地球！ \n……但是，住惯了地球的她，开始过起整天逃学打网游的自甘堕落生活。\n化身为怠惰的废柴天使，简称“废天使”的加百列，早就把让全部人类幸福的目标抛到九霄云外，并发誓要充分享受娱乐——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5472EA8DBF105A0B50E978#第02集$MOE5472EA8DBF105A0B50E97B#第03集$MOE5472EA8DBF105A0B50E97A#第04集$MOE5472EA8DBF105A0B50E97D#第05集$MOE5472EA8DBF105A0B50E97C#第06集$MOE5472EA8DBF105A0B50E97F#第07集$MOE5472EA8DBF105A0B50E97E#第08集$MOE5472EA8DBF105A0B50E971#第09集$MOE5472EA8DBF105A0B50E970#第10集$MOE5472EA8DBF105A0B50E879#第11集$MOE5472EA8DBF105A0B50E878#第12集$MOE5472EA8DBF105A0B50E87B#OVA01$MOE5472EA8DBF105A0B50E87A#OVA02$MOE5472EA8DBF105A0B50E87D$$$第01集$id_XS5472EA8DBF105A0B50E978#第02集$id_XS5472EA8DBF105A0B50E97B#第03集$id_XS5472EA8DBF105A0B50E97A#第04集$id_XS5472EA8DBF105A0B50E97D#第05集$id_XS5472EA8DBF105A0B50E97C#第06集$id_XS5472EA8DBF105A0B50E97F#第07集$id_XS5472EA8DBF105A0B50E97E#第08集$id_XS5472EA8DBF105A0B50E971#第09集$id_XS5472EA8DBF105A0B50E970#第10集$id_XS5472EA8DBF105A0B50E879#第11集$id_XS5472EA8DBF105A0B50E878#第12集$id_XS5472EA8DBF105A0B50E87B#OVA01$id_XS5472EA8DBF105A0B50E87A#OVA02$id_XS5472EA8DBF105A0B50E87D$$$第01集$id_MOE5472EA8DBF105A0B50E978#第02集$id_MOE5472EA8DBF105A0B50E97B#第03集$id_MOE5472EA8DBF105A0B50E97A#第04集$id_MOE5472EA8DBF105A0B50E97D#第05集$id_MOE5472EA8DBF105A0B50E97C#第06集$id_MOE5472EA8DBF105A0B50E97F#第07集$id_MOE5472EA8DBF105A0B50E97E#第08集$id_MOE5472EA8DBF105A0B50E971#第09集$id_MOE5472EA8DBF105A0B50E970#第10集$id_MOE5472EA8DBF105A0B50E879#第11集$id_MOE5472EA8DBF105A0B50E878#第12集$id_MOE5472EA8DBF105A0B50E87B#OVA01$id_MOE5472EA8DBF105A0B50E87A#OVA02$id_MOE5472EA8DBF105A0B50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (685, 1, 0, 0, '电波女与青春男', '電波女と青春男（2011）', 'dianbonvyuqingchunnan', 1, 'D', '', '22fc5fd1', '萌系,日常,小说改', 'http://i0.hdslb.com/bfs/bangumi/image/9b50343a4332c36f10a4e5b43557460bc7439414.jpg', '', '', '', '大龟明日香 / 入野自由 / 加藤英美里 / 渊上舞 / 野中蓝', '新房昭之 / 宫本幸裕 / 畠山守 / 川畑乔 / 八濑祐树 / 板村智幸 / 间岛崇宽 / 美甘义人 / 向井雅浩', '', '', '故事的主角是将“青春点数”分配到自己的行动和相关的事情上、有时欢喜有时忧愁的少年丹羽真，及把被子卷在身上、自称外星人的“电波女”（却是美少女）的藤和艾莉欧。作品以这二人为中心，展开了有点奇怪、却又非常', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2011', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 27, 0, 27, 27, '', 0, 0, 9.7, 0, 0, 1734934310, 1734914231, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事的主角是将“青春点数”分配到自己的行动和相关的事情上、有时欢喜有时忧愁的少年丹羽真，及把被子卷在身上、自称外星人的“电波女”（却是美少女）的藤和艾莉欧。作品以这二人为中心，展开了有点奇怪、却又非常清爽的青春故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0325EADBBC4F090850E978#第02集$MOE0325EADBBC4F090850E97B#第03集$MOE0325EADBBC4F090850E97A#第04集$MOE0325EADBBC4F090850E97D#第05集$MOE0325EADBBC4F090850E97C#第06集$MOE0325EADBBC4F090850E97F#第07集$MOE0325EADBBC4F090850E97E#第08集$MOE0325EADBBC4F090850E971#第09集$MOE0325EADBBC4F090850E970#第10集$MOE0325EADBBC4F090850E879#第11集$MOE0325EADBBC4F090850E878#第12集$MOE0325EADBBC4F090850E87B#OVA$MOE0325EADBBC4F090850E87A$$$第01集$id_XS0325EADBBC4F090850E978#第02集$id_XS0325EADBBC4F090850E97B#第03集$id_XS0325EADBBC4F090850E97A#第04集$id_XS0325EADBBC4F090850E97D#第05集$id_XS0325EADBBC4F090850E97C#第06集$id_XS0325EADBBC4F090850E97F#第07集$id_XS0325EADBBC4F090850E97E#第08集$id_XS0325EADBBC4F090850E971#第09集$id_XS0325EADBBC4F090850E970#第10集$id_XS0325EADBBC4F090850E879#第11集$id_XS0325EADBBC4F090850E878#第12集$id_XS0325EADBBC4F090850E87B#OVA$id_XS0325EADBBC4F090850E87A$$$第01集$id_MOE0325EADBBC4F090850E978#第02集$id_MOE0325EADBBC4F090850E97B#第03集$id_MOE0325EADBBC4F090850E97A#第04集$id_MOE0325EADBBC4F090850E97D#第05集$id_MOE0325EADBBC4F090850E97C#第06集$id_MOE0325EADBBC4F090850E97F#第07集$id_MOE0325EADBBC4F090850E97E#第08集$id_MOE0325EADBBC4F090850E971#第09集$id_MOE0325EADBBC4F090850E970#第10集$id_MOE0325EADBBC4F090850E879#第11集$id