INSERT INTO `mac_vod` VALUES (688, 1, 0, 0, 'BanG Dream! 第二季', 'BanG Dream! 2nd Season（2019）', 'BanGDreamdierji', 1, 'B', '', '8434e12', '原创,少女,声控,音乐', 'http://i0.hdslb.com/bfs/bangumi/f872b7d98f6bd4ca0ac20166f39392f8f8ec297d.png', '', '', '', '爱美 / 大冢纱英 / 西本里美 / 大桥彩香 / 伊藤彩沙 / 佐仓绫音 / 前岛亚美 / 相羽爱奈 / 伊藤美来', '柿本广大 / 信田祐 / 野上和男 / 浅利藤彰 / 高桥成世 / 间岛崇宽', '', '', '升上高中二年级的香澄等Poppin&#039;Party成员，不论是在学生会还是在家帮忙，不论是补习还是打工都十分繁忙。\r\n五人在一起的时间逐渐减少，在作为据点的仓库也难以集合。\r\n在这样的她们身边，出现了一位少女', '全13集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 9.7, 0, 0, 1734966796, 1734931073, 0, 0, 0, 0, 0.0, '', '689,757', '', '', '', '', '', '', '', '<p>升上高中二年级的香澄等Poppin&#39;Party成员，不论是在学生会还是在家帮忙，不论是补习还是打工都十分繁忙。\r\n五人在一起的时间逐渐减少，在作为据点的仓库也难以集合。\r\n在这样的她们身边，出现了一位少女——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0923BF8CEC185F144DE8#第02集$MOE0923BF8CEC185F144DEB#第03集$MOE0923BF8CEC185F144DEA#第04集$MOE0923BF8CEC185F144DED#第05集$MOE0923BF8CEC185F144DEC#第06集$MOE0923BF8CEC185F144DEF#第07集$MOE0923BF8CEC185F144DEE#第08集$MOE0923BF8CEC185F144DE1#第09集$MOE0923BF8CEC185F144DE0#第10集$MOE0923BF8CEC185F144CE9#第11集$MOE0923BF8CEC185F144CE8#第12集$MOE0923BF8CEC185F144CEB#第13集$MOE0923BF8CEC185F144CEA$$$第01集$id_XS0923BF8CEC185F144DE8#第02集$id_XS0923BF8CEC185F144DEB#第03集$id_XS0923BF8CEC185F144DEA#第04集$id_XS0923BF8CEC185F144DED#第05集$id_XS0923BF8CEC185F144DEC#第06集$id_XS0923BF8CEC185F144DEF#第07集$id_XS0923BF8CEC185F144DEE#第08集$id_XS0923BF8CEC185F144DE1#第09集$id_XS0923BF8CEC185F144DE0#第10集$id_XS0923BF8CEC185F144CE9#第11集$id_XS0923BF8CEC185F144CE8#第12集$id_XS0923BF8CEC185F144CEB#第13集$id_XS0923BF8CEC185F144CEA$$$第01集$id_MOE0923BF8CEC185F144DE8#第02集$id_MOE0923BF8CEC185F144DEB#第03集$id_MOE0923BF8CEC185F144DEA#第04集$id_MOE0923BF8CEC185F144DED#第05集$id_MOE0923BF8CEC185F144DEC#第06集$id_MOE0923BF8CEC185F144DEF#第07集$id_MOE0923BF8CEC185F144DEE#第08集$id_MOE0923BF8CEC185F144DE1#第09集$id_MOE0923BF8CEC185F144DE0#第10集$id_MOE0923BF8CEC185F144CE9#第11集$id_MOE0923BF8CEC185F144CE8#第12集$id_