INSERT INTO `mac_vod` VALUES (689, 1, 0, 0, 'BanG Dream! 梦想协奏曲 第三季', 'BanG Dream! 3rd Season（2020）', 'BanGDreammengxiangxiezouqudisanji', 1, 'B', '', '4e69737d', '原创,校园,音乐', 'http://i0.hdslb.com/bfs/bangumi/image/9e5bd6bd1c2c8b53f75fe42d107ef38e1c3ec6cc.png', '', '', '', '爱美 / 大冢纱英 / 西本里美 / 大桥彩香 / 伊藤彩沙 / 相羽爱奈 / 工藤晴香 / 中岛由贵 / 樱川惠 / 志崎桦音 / 小原莉子 / 仓知玲凤 / 纺木吏佐 / 佐仓绫音 / 三泽纱千香 / 加藤英美里 / 日笠阳子 / 金元寿子 / 前岛亚美', '柿本广大 / 高桥成世 / 佐藤阳 / 间岛崇宽', '', '', '少女香澄一直寻找着幼年时在欣赏星空时所感受到的那股星之鼓动……直至高中入学后不久，香澄在古物商仓库中偶然看见了一把星型吉他、她心中那股封闭已久的情感就此流露而出。以此为契机、香澄与4位同样在寻找光辉之', '全13集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 24, 0, 24, 24, '', 0, 0, 9.8, 0, 0, 1734997085, 1734931081, 0, 0, 0, 0, 0.0, '', '757', '', '', '', '', '', '', '', '<p>少女香澄一直寻找着幼年时在欣赏星空时所感受到的那股星之鼓动……直至高中入学后不久，香澄在古物商仓库中偶然看见了一把星型吉他、她心中那股封闭已久的情感就此流露而出。以此为契机、香澄与4位同样在寻找光辉之所的女孩们相遇，一同演奏出了单凭一人无法表现出的音乐，共同朝着梦想迈进！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0572BA81BE1A5A5D50E978#第02集$MOE0572BA81BE1A5A5D50E97B#第03集$MOE0572BA81BE1A5A5D50E97A#第04集$MOE0572BA81BE1A5A5D50E97D#第05集$MOE0572BA81BE1A5A5D50E97C#第06集$MOE0572BA81BE1A5A5D50E97F#第07集$MOE0572BA81BE1A5A5D50E97E#第08集$MOE0572BA81BE1A5A5D50E971#第09集$MOE0572BA81BE1A5A5D50E970#第10集$MOE0572BA81BE1A5A5D50E879#第11集$MOE0572BA81BE1A5A5D50E878#第12集$MOE0572BA81BE1A5A5D50E87B#第13集$MOE0572BA81BE1A5A5D50E87A$$$第01集$id_XS0572BA81BE1A5A5D50E978#第02集$id_XS0572BA81BE1A5A5D50E97B#第03集$id_XS0572BA81BE1A5A5D50E97A#第04集$id_XS0572BA81BE1A5A5D50E97D#第05集$id_XS0572BA81BE1A5A5D50E97C#第06集$id_XS0572BA81BE1A5A5D50E97F#第07集$id_XS0572BA81BE1A5A5D50E97E#第08集$id_XS0572BA81BE1A5A5D50E971#第09集$id_XS0572BA81BE1A5A5D50E970#第10集$id_XS0572BA81BE1A5A5D50E879#第11集$id_XS0572BA81BE1A5A5D50E878#第12集$id_XS0572BA81BE1A5A5D50E87B#第13集$id_XS0572BA81BE1A5A5D50E87A$$$第01集$id_MOE0572BA81BE1A5A5D50E978#第02集$id_MOE0572BA81BE1A5A5D50E97B#第03集$id_MOE0572BA81BE1A5A5D50E97A#第04集$id_MOE0572BA81BE1A5A5D50E97D#第05集$id_MOE0572BA81BE1A5A5D50E97C#第06集$id_MOE0572BA81BE1A5A5D50E97F#第07集$id_MOE