INSERT INTO `mac_vod` VALUES (747, 1, 0, 0, '柑橘味香气', 'Citrus（2018）', 'ganjuweixiangqi', 1, 'G', '', '4e604bf6', '恋爱', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2518012513.jpg', '', '', '', '竹达彩奈 / 津田美波 / 藤井雪代 / 久保由利香 / 井泽诗织 / 叶山郁美 / 金元寿子 / 松嵜丽 / 前野智昭 / 植田佳奈', '高桥丈夫', '', '', '蓝原柚子（竹达彩奈 配音）是一名高中一年级的女生，外表看上去非常时尚的她，实际上却是一个内心里意外的天真，一点恋爱经验都没有的纯情女孩。由于家庭的原因，柚子进入了一所女子高中就读，这让柚子的心里非常不', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 54, 0, 54, 54, '', 0, 0, 7.8, 0, 0, 1735690290, 1735678265, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>蓝原柚子（竹达彩奈 配音）是一名高中一年级的女生，外表看上去非常时尚的她，实际上却是一个内心里意外的天真，一点恋爱经验都没有的纯情女孩。由于家庭的原因，柚子进入了一所女子高中就读，这让柚子的心里非常不满，因为在这里，她能交到男朋友的概率简直微乎其微。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0572BA88BD4B0B0F50E978#第02集$MOE0572BA88BD4B0B0F50E97B#第03集$MOE0572BA88BD4B0B0F50E97A#第04集$MOE0572BA88BD4B0B0F50E97D#第05集$MOE0572BA88BD4B0B0F50E97C#第06集$MOE0572BA88BD4B0B0F50E97F#第07集$MOE0572BA88BD4B0B0F50E97E#第08集$MOE0572BA88BD4B0B0F50E971#第09集$MOE0572BA88BD4B0B0F50E970#第10集$MOE0572BA88BD4B0B0F50E879#第11集$MOE0572BA88BD4B0B0F50E878#第12集$MOE0572BA88BD4B0B0F50E87B$$$第01集$id_XS0572BA88BD4B0B0F50E978#第02集$id_XS0572BA88BD4B0B0F50E97B#第03集$id_XS0572BA88BD4B0B0F50E97A#第04集$id_XS0572BA88BD4B0B0F50E97D#第05集$id_XS0572BA88BD4B0B0F50E97C#第06集$id_XS0572BA88BD4B0B0F50E97F#第07集$id_XS0572BA88BD4B0B0F50E97E#第08集$id_XS0572BA88BD4B0B0F50E971#第09集$id_XS0572BA88BD4B0B0F50E970#第10集$id_XS0572BA88BD4B0B0F50E879#第11集$id_XS0572BA88BD4B0B0F50E878#第12集$id_XS0572BA88BD4B0B0F50E87B$$$第01集$id_MOE0572BA88BD4B0B0F50E978#第02集$id_MOE0572BA88BD4B0B0F50E97B#第03集$id_MOE0572BA88BD4B0B0F50E97A#第04集$id_MOE0572BA88BD4B0B0F50E97D#第05集$id_MOE0572BA88BD4B0B0F50E97C#第06集$id_MOE0572BA88BD4B0B0F50E97F#第07集$id_MOE0572BA88BD4B0B0F50E97E#第08集$id_MOE0572BA88BD4B0B0F50E971#第09集$id_MOE0572BA88BD4B0B0F50E970#第10集$id_MOE0572BA88BD4B0B0F50E879#第11集$id_MOE0572BA88BD4B0B0F50E878#第12集$id_MOE0572BA88BD4B0B0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (690, 1, 0, 0, '一拳超人', 'ワンパンマン（2015）', 'yiquanchaoren', 1, 'Y', '', '41891a61', '动作,搞笑', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2234184583.jpg', '', '', '', '古川慎 / 石川界人 / 梶裕贵 / 悠木碧 / 中村悠一 / 山路和弘 / 安元洋贵 / 樱井孝宏 / 小西克幸 / 宫野真守 / 早见沙织 / 津田健次郎 / 高山南 / 玄田哲章 / 上田耀司 / 浪川大辅 / 日野聪 / 上田祐司 / 鸟海浩辅 / 羽多野涉 / 小野坂昌也 / 细谷佳正 / 飞田展男 / 内山昂辉 / 小山力也 / 关智一 / 三木真一郎 / 宫崎宽务 / 泽城美雪 / 石冢运升 / 高木涉 / 森川智之', '夏目真悟 / 吉泽俊一 / 牛岛新一郎 / 山冈实 / 久木晃嗣 / 八田洋介 / 武藤信宏', '', '', '曾经，埼玉（古川慎 配音）只是一介平凡的上班族，某日，在偶然之中遇见了遭到变种螃蟹攻击的少年，心中升腾起了正义之感，对其出手相救。就此之后，埼玉幼年时代的英雄梦想在内心里死灰复燃，为了变得更加强大，埼', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 46, 0, 46, 46, '', 0, 0, 9.4, 0, 0, 1735031471, 1735003716, 0, 0, 0, 0, 0.0, '', '691', '', '', '', '', '', '', '', '<p>曾经，埼玉（古川慎 配音）只是一介平凡的上班族，某日，在偶然之中遇见了遭到变种螃蟹攻击的少年，心中升腾起了正义之感，对其出手相救。就此之后，埼玉幼年时代的英雄梦想在内心里死灰复燃，为了变得更加强大，埼玉开始了艰苦的训练，一晃眼数年过去，他仿佛脱胎换骨般的获得了异常强大的力量，但却付出了变成光头的代价。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0526B481B8485B0850E978#第02集$MOE0526B481B8485B0850E97B#第03集$MOE0526B481B8485B0850E97A#第04集$MOE0526B481B8485B0850E97D#第05集$MOE0526B481B8485B0850E97C#第06集$MOE0526B481B8485B0850E97F#第07集$MOE0526B481B8485B0850E97E#第08集$MOE0526B481B8485B0850E971#第09集$MOE0526B481B8485B0850E970#第10集$MOE0526B481B8485B0850E879#第11集$MOE0526B481B8485B0850E878#第12集$MOE0526B481B8485B0850E87B#OVA01$MOE0526B481B8485B0850E87A#OVA02$MOE0526B481B8485B0850E87D#OVA03$MOE0526B481B8485B0850E87C#OVA04$MOE0526B481B8485B0850E87F#OVA05$MOE0526B481B8485B0850E87E#OVA06$MOE0526B481B8485B0850E871$$$第01集$id_XS0526B481B8485B0850E978#第02集$id_XS0526B481B8485B0850E97B#第03集$id_XS0526B481B8485B0850E97A#第04集$id_XS0526B481B8485B0850E97D#第05集$id_XS0526B481B8485B0850E97C#第06集$id_XS0526B481B8485B0850E97F#第07集$id_XS0526B481B8485B0850E97E#第08集$id_XS0526B481B8485B0850E971#第09集$id_XS0526B481B8485B0850E970#第10集$id_XS0526B481B8485B0850E879#第11集$id_XS0526B481B8485B0850E878#第12集$id_XS0526B481B8485B0850E87B#OVA01$id_XS0526B481B8485