INSERT INTO `mac_vod` VALUES (704, 1, 0, 0, '女高中生的虚度日常', '女子高生の無駄づかい（2019）', 'nvgaozhongshengdexudurichang', 1, 'N', '', 'e3dffe99', '搞笑,校园,漫画改,日常', 'http://i0.hdslb.com/bfs/bangumi/image/4bcc16c200fc2fb67372d65bfdd8960f99874edc.png', '', '', '', '赤崎千夏 / 户松遥 / 丰崎爱生 / 长绳麻理亚 / 富田美忧 / 高桥李依 / 佐藤聪美 / 市道真央 / 兴津和幸 / 上田丽奈 / 名冢佳织 / 落合福嗣 / 松冈祯丞 / 岛崎信长', '高桥丈夫 / 三瓶圣 / 下司泰弘 / 榎本守 / 间岛崇宽', '', '', '被浪费的青春——\r\n偏差值差不多的田中（通称“笨蛋”）、沉迷于BL的菊池（通称：“御宅”）、面无表情的才女・鹭宫（通称“机器人”）。个性十足的女高中生们无所事事的日常校园生活——', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 9.8, 0, 0, 1735290670, 1735242424, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>被浪费的青春——\n偏差值差不多的田中（通称“笨蛋”）、沉迷于BL的菊池（通称：“御宅”）、面无表情的才女・鹭宫（通称“机器人”）。个性十足的女高中生们无所事事的日常校园生活——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5424E8DEEF4C540050E978#第02集$MOE5424E8DEEF4C540050E97B#第03集$MOE5424E8DEEF4C540050E97A#第04集$MOE5424E8DEEF4C540050E97D#第05集$MOE5424E8DEEF4C540050E97C#第06集$MOE5424E8DEEF4C540050E97F#第07集$MOE5424E8DEEF4C540050E97E#第08集$MOE5424E8DEEF4C540050E971#第09集$MOE5424E8DEEF4C540050E970#第10集$MOE5424E8DEEF4C540050E879#第11集$MOE5424E8DEEF4C540050E878#第12集$MOE5424E8DEEF4C540050E87B$$$第01集$id_XS5424E8DEEF4C540050E978#第02集$id_XS5424E8DEEF4C540050E97B#第03集$id_XS5424E8DEEF4C540050E97A#第04集$id_XS5424E8DEEF4C540050E97D#第05集$id_XS5424E8DEEF4C540050E97C#第06集$id_XS5424E8DEEF4C540050E97F#第07集$id_XS5424E8DEEF4C540050E97E#第08集$id_XS5424E8DEEF4C540050E971#第09集$id_XS5424E8DEEF4C540050E970#第10集$id_XS5424E8DEEF4C540050E879#第11集$id_XS5424E8DEEF4C540050E878#第12集$id_XS5424E8DEEF4C540050E87B$$$第01集$id_MOE5424E8DEEF4C540050E978#第02集$id_MOE5424E8DEEF4C540050E97B#第03集$id_MOE5424E8DEEF4C540050E97A#第04集$id_MOE5424E8DEEF4C540050E97D#第05集$id_MOE5424E8DEEF4C540050E97C#第06集$id_MOE5424E8DEEF4C540050E97F#第07集$id_MOE5424E8DEEF4C540050E97E#第08集$id_MOE5424E8DEEF4C540050E971#第09集$id_MOE5424E8DEEF4C540050E970#第10集$id_MOE5424E8DEEF4C540050E879#第11集$id_MOE5424E8DEEF4C540050E878#第12集$id_MOE5424E8