INSERT INTO `mac_vod` VALUES (720, 2, 0, 0, '空之境界 第三章 痛觉残留', '劇場版 空の境界 第三章 痛覚残留（2008）', 'kongzhijingjiedisanzhangtongjuecanliu', 1, 'K', '', '6f2965b', '小说改,奇幻,冒险', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1070325111.jpg', '', '', '', '坂本真绫 / 铃村健一 / 本田贵子 / 藤村步 / 高桥研二 / 浅沼晋太郎 / 安元洋贵 / 中村悠一 / 能登麻美子', '小船井充', '', '', '1998年7月，饮酒会归来的下雨之夜，黑桐干也收留了一位无家可归的少女。但不久，少女不辞而别，去向不明。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.9, 0, 0, 1735406297, 1735342328, 0, 0, 0, 0, 0.0, '', '721,722,723,724,725,727,728', '', '', '', '', '', '', '', '<p>1998年7月，饮酒会归来的下雨之夜，黑桐干也收留了一位无家可归的少女。但不久，少女不辞而别，去向不明。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0771BE81BF1C0F144DE8$$$正片$id_MOE0771BE81BF1C0F144DE8', '', '', '', '', 0, '', '');
