INSERT INTO `mac_vod` VALUES (722, 2, 0, 0, '空之境界 第五章 矛盾螺旋', '劇場版 空の境界 第五章 矛盾螺旋（2008）', 'kongzhijingjiediwuzhangmaodunluoxuan', 1, 'K', '', 'cfe40b02', '小说改,奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194403556.jpg', '', '', '', '坂本真绫 / 柿原彻也 / 中田让治 / 游佐浩二 / 五十岚裕美 / 山野井仁 / 伊藤美纪 / 东地宏树 / 藤村步 / 本田贵子 / 铃村健一', '平尾隆之', '', '', '“荒耶，你在追求什么？”“真正的睿智。”“在哪里追求？”“只在自己的心里。”', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.3, 0, 0, 1735406490, 1735342362, 0, 0, 0, 0, 0.0, '', '723,724,725,727,728', '', '', '', '', '', '', '', '<p>“荒耶，你在追求什么？”“真正的睿智。”“在哪里追求？”“只在自己的心里。”</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5271E98CB94B5D0B50E978$$$正片$id_MOE5271E98CB94B5D0B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (723, 2, 0, 0, '空之境界 第六章 忘却录音', '劇場版 空の境界 第六章 忘却録音（2008）', 'kongzhijingjiediliuzhangwangqueluyin', 1, 'K', '', '5d338da6', '小说改,奇幻,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1957634133.jpg', '', '', '', '坂本真绫 / 铃村健一 / 本田贵子 / 藤村步 / 水树奈奈 / 置鲇龙太郎 / 喜多村英梨 / 石上裕一 / 井口裕香 / 保志总一朗 / 中田让治', '三浦贵博', '', '', '1999年1月，黑桐鲜花所就读的高级女子中学——礼园出现了神秘的事件。一年四班的学生橘佳织在宿舍起火事件中身亡，随后，一年四班全体同学的生活改变了。每天活在痛苦与烦恼中的她们，收到了不明来源的信件。不', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 8.3, 0, 0, 1735406577, 1735342381, 0, 0, 0, 0, 0.0, '', '724,725,727,728', '', '', '', '', '', '', '', '<p>1999年1月，黑桐鲜花所就读的高级女子中学——礼园出现了神秘的事件。一年四班的学生橘佳织在宿舍起火事件中身亡，随后，一年四班全体同学的生活改变了。每天活在痛苦与烦恼中的她们，收到了不明来源的信件。不安的情绪在礼园全体学生间蔓延。为了解决事件，两仪式假扮学生潜入礼园，与黑桐鲜花一同调查事件的原委。另一方面，黑桐干也在使用自己的方法追踪事件的真相。而事件的背后，似乎还有那个男人，魔术师荒耶宗莲的安排。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0473BF8BB14D0C0F50E978$$$正片$id_MOE0473BF8BB14D0C0F50E978', '', '', '', '', 0, '', '');
