INSERT INTO `mac_vod` VALUES (725, 2, 0, 0, '空之境界 终章 空之境界', '劇場版 空の境界 終章 空の境界（2010）', 'kongzhijingjiezhongzhangkongzhijingjie', 1, 'K', '', '48bdddc4', '小说改,奇幻,冒险', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2876182136.jpg', '', '', '', '坂本真绫 / 铃村健一', '近藤光', '', '', '“黑桐，你知道吗，杀人和杀戮是不一样的。据说，人一生只能杀一个人？”', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 8.6, 0, 0, 1735406766, 1735342484, 0, 0, 0, 0, 0.0, '', '727,728', '', '', '', '', '', '', '', '<p>“黑桐，你知道吗，杀人和杀戮是不一样的。据说，人一生只能杀一个人？”</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS052FEEDCED4D0E0D50E978$$$正片$id_MOE052FEEDCED4D0E0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (726, 1, 0, 0, '青之驱魔师 终夜篇', '青の祓魔師 終夜篇（2025）', 'qingzhiqumoshizhongyepian', 1, 'Q', '', 'c4c24c33', '漫画改,奇幻,热血,战斗', 'https://pic3.iqiyipic.com/image/20250103/88/44/a_100600052_m_601_zh-CN_m2_260_360.webp', '', '', '', '冈本信彦 / 福山润', '吉田大輔', '', '', '为了寻找突然消失的修罗，燐和雪男两兄弟动身前往青森的永久蛇湖。这里是修罗的出身地――狮郎过去安置保护她的地方。在搜索过程中，燐和雪男得知了等待着修罗的宿命。\r\n\r\n另一方面，来到正十字骑士团日本分部的', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 82, 0, 82, 82, '', 0, 0, 9.1, 0, 0, 1743921078, 1735342545, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>为了寻找突然消失的修罗，燐和雪男两兄弟动身前往青森的永久蛇湖。这里是修罗的出身地――狮郎过去安置保护她的地方。在搜索过程中，燐和雪男得知了等待着修罗的宿命。\r\n\r\n另一方面，来到正十字骑士团日本分部的四大骑士之一・雷霆开始着手调查启明结社。\r\n一切都是从「青色之夜」开始的――如此推测的雷霆，即将慢慢踏足进入骑士团的黑暗面……。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5223EF8ABD4A5E0A50E978#第02集$MOE5223EF8ABD4A5E0A50E97B#第03集$MOE5223EF8ABD4A5E0A50E97A#第04集$MOE5223EF8ABD4A5E0A50E97D#第05集$MOE5223EF8ABD4A5E0A50E97C#第06集$MOE5223EF8ABD4A5E0A50E97F#第07集$MOE5223EF8ABD4A5E0A50E97E#第08集$MOE5223EF8ABD4A5E0A50E971#第09集$MOE5223EF8ABD4A5E0A50E970#第10集$MOE5223EF8ABD4A5E0A50E879#第11集$MOE5223EF8ABD4A5E0A50E878#第12集$MOE5223EF8ABD4A5E0A50E87B$$$第01集$id_XS5223EF8ABD4A5E0A50E978#第02集$id_XS5223EF8ABD4A5E0A50E97B#第03集$id_XS5223EF8ABD4A5E0A50E97A#第04集$id_XS5223EF8ABD4A5E0A50E97D#第05集$id_XS5223EF8ABD4A5E0A50E97C#第06集$id_XS5223EF8ABD4A5E0A50E97F#第07集$id_XS5223EF8ABD4A5E0A50E97E#第08集$id_XS5223EF8ABD4A5E0A50E971#第09集$id_XS5223EF8ABD4A5E0A50E970#第10集$id_XS5223EF8ABD4A5E0A50E879#第11集$id_XS5223EF8ABD4A5E0A50E878#第12集$id_XS5223EF8ABD4A5E0A50E87B$$$第01集$id_MOE5223EF8ABD4A5E0A50E978#第02集$id_MOE5223EF8ABD4A5E0A50E97B#第03集$id_MOE5223EF8ABD4A5E0A50E97A#第04集$id_MOE5223EF8ABD4A5E0A50E97D#第05集$id_MOE5223EF8ABD4A5E0A50E97C#第06集$id_MOE5223EF8ABD4A5E0A50E97F#第07集$id_MOE5223EF8ABD4A5E0A50E97E#第08集$id_MOE5223EF8ABD4A5E0A50E971#第09集$id_MOE5223EF8ABD4A5E0A50E970#第10集$id_MOE5223EF8ABD4A5E0A50E879#第11集$id_MOE5223EF8ABD4A5E0A50E878#第12集$id_MOE5223EF8ABD4A5E0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (727, 2, 0, 0, '空之境界 未来福音', '劇場版 空の境界 未来福音（2013）', 'kongzhijingjieweilaifuyin', 1, 'K', '', 'd22860ce', '小说改,奇幻,冒险', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2037135869.jpg', '', '', '', '坂本真绫 / 铃村健一 / 本田贵子 / 井口裕香 / 石田彰 / 金元寿子 / 藤村步 / 东地宏树 / 大西沙织 / 松本和香子', '须藤友德', '', '', '1998年夏季，拥有预测型未来视的女孩濑尾静音（井口裕香 配音）邂逅伽蓝之堂的黑桐干也（铃村健一 配音）。从对方口中，她了解到未来视的真相，心中的疑惑和焦虑也烟消云散，但同时也看到了干也悲剧性的未来。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.1, 0, 0, 1735421233, 1735342559, 0, 0, 0, 0, 0.0, '', '728', '', '', '', '', '', '', '', '<p>1998年夏季，拥有预测型未来视的女孩濑尾静音（井口裕香 配音）邂逅伽蓝之堂的黑桐干也（铃村健一 配音）。从对方口中，她了解到未来视的真相，心中的疑惑和焦虑也烟消云散，但同时也看到了干也悲剧性的未来。另一方面，拥有测定型未来视的职业炸弹狂魔仓密目琉夏，利用自己构建的未来制造一系列恐怖袭击事件，直到他遭遇冷静干练的两仪式（坂本真绫 配音），命运的齿轮开始转动。转眼来到2010年，失去了未来视能力的瓶仓光瑠（石田彰 配音）转行做了绘本画家，命运安排他和两仪式及其女儿未那（金元寿子 配音）相逢，此后他和崇拜自己的未那拜访了传奇占卜师观布子之母……</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5525BE80BF190E5C50E978$$$正片$id_MOE5525BE80BF190E5C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (728, 2, 0, 0, '空之境界 未来福音 extrachorus', '劇場版 空の境界 未来福音 extra chorus（2013）', 'kongzhijingjieweilaifuyinextrachorus', 1, 'K', '', 'ce6ea16f', '小说改,奇幻,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2215965143.jpg', '', '', '', '坂本真绫 / 铃村健一 / 本田贵子 / 藤村步 / 能登麻美子 / 种田梨沙 / 井口裕香', '青木荣', '', '', '痛觉残留：经历了和职业炸弹狂魔仓密目琉夏的惨烈对决后，伤痕累累的两仪式（坂本真绫 配音）待在家中静养。适逢黑桐干也（铃村健一 配音）需外出公干，他自顾自将一只黑猫托付给两仪照看。两仪与黑猫的关系巧巧起', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.1, 0, 0, 1735421310, 1735342639, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>痛觉残留：经历了和职业炸弹狂魔仓密目琉夏的惨烈对决后，伤痕累累的两仪式（坂本真绫 配音）待在家中静养。适逢黑桐干也（铃村健一 配音）需外出公干，他自顾自将一只黑猫托付给两仪照看。两仪与黑猫的关系巧巧起了变化；俯瞰风景：礼园女子学院八名女孩自杀，宫月理理栖（种田梨沙 配音）凭吊自杀的好友安藤由子，后悔自己没有和她一同赴死。就在此时，业已失明的浅上藤乃（能登麻美子 配音）出现在宫月面前；新年参拜：1998年即将过去，干也和两仪并肩走在去神社参拜的路上。寒冷的冬夜，两颗孤独之心不知不觉越来越近。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5272BADDE8185B5F50E978$$$正片$id_MOE5272BADDE8185B5F50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (729, 1, 0, 0, '青春之旅', 'アオハライド（2014）', 'qingchunzhilv', 1, 'Q', '', '7d0975d6', '少女,恋爱,校园', 'http://i0.hdslb.com/bfs/bangumi/image/19c1294d6a70134e65cc6f66169fcccf25893f88.jpg', '', '', '', '内田真礼 / 梶裕贵 / 茅野爱衣 / 小松未可子 / 大桥贤一郎 / 松冈祯丞 / 井上麻里奈 / 白石凉子 / 平川大辅 / 山下大辉', '吉村爱 / 宫下新平 / 铃木孝聪 / 绵田慎也 / 河村智之 / 高桥英俊 / 工藤利春', '', '', '故事主要讲述的是对于不擅长与男生打交道的主人公吉冈双叶来说，“田中君”是特别的存在。由于在暑假时田中君转校了，所以双叶未能向他传达自己内心的感情。之后，受到男生欢迎的双叶也因此被其他女生排挤，就这样度', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 9.5, 0, 0, 1737201070, 1735378990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '故事主要讲述的是对于不擅长与男生打交道的主人公吉冈双叶来说，“田中君”是特别的存在。由于在暑假时田中君转校了，所以双叶未能向他传达自己内心的感情。之后，受到男生欢迎的双叶也因此被其他女生排挤，就这样度过了难受的中学时代。升入高中以后，为了不被女生讨厌而故意做出一些粗心大意的举动的双叶，与她的初恋对象“田中君”重逢。然而，田中君在初中时的性格也已改变了，故事便由此展开。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0673BC81BE1C090F50E978#第02集$MOE0673BC81BE1C090F50E97B#第03集$MOE0673BC81BE1C090F50E97A#第04集$MOE0673BC81BE1C090F50E97D#第05集$MOE0673BC81BE1C090F50E97C#第06集$MOE0673BC81BE1C090F50E97F#第07集$MOE0673BC81BE1C090F50E97E#第08集$MOE0673BC81BE1C090F50E971#第09集$MOE0673BC81BE1C090F50E970#第10集$MOE0673BC81BE1C090F50E879#第11集$MOE0673BC81BE1C090F50E878#第12集$MOE0673BC81BE1C090F50E87B#OAD01$MOE0673BC81BE1C090F50E87A#OAD02$MOE0673BC81BE1C090F50E87D$$$第01集$id_XS0673BC81BE1C090F50E978#第02集$id_XS0673BC81BE1C090F50E97B#第03集$id_XS0673BC81BE1C090F50E97A#第04集$id_XS0673BC81BE1C090F50E97D#第05集$id_XS0673BC81BE1C090F50E97C#第06集$id_XS0673BC81BE1C090F50E97F#第07集$id_XS0673BC81BE1C090F50E97E#第08集$id_XS0673BC81BE1C090F50E971#第09集$id_XS0673BC81BE1C090F50E970#第10集$id_XS0673BC81BE1C090F50E879#第11集$id_XS0673BC81BE1C090F50E878#第12集$id_XS0673BC81BE1C090F50E87B#OAD01$id_XS0673BC81BE1C090F50E87A#OAD02$id_XS0673BC81BE1C090F50E87D$$$第01集$id_MOE0673BC81BE1C090F50E978#第02集$id_MOE0673BC81BE1C090F50E97B#第03集$id_MOE0673BC81BE1C090F50E97A#第04集$id_MOE0673BC81BE1C090F50E97D#第05集$id_MOE0673BC81BE1C090F50E97C#第06集$id_MOE0673BC81BE1C090F50E97F#第07集$id_MOE0673BC81BE1C090F50E97E#第08集$id_MOE0673BC81BE1C090F50E971#第09集$id_MOE0673BC81BE1C090F50E970#第10集$id_MOE0673BC81BE1C090F50E879#第11集$id_MOE0673BC81BE1C090F50E878#第12集$id_MOE0673BC81BE1C090F50E87B#OAD01$id_MOE0673BC81BE1C090F50E87A#OAD02$id_MOE0673BC81BE1C090F50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (730, 1, 0, 0, 'S级怪兽《贝希摩斯》被误认成小猫，成为精灵女孩的骑士(宠物)一起生活', 'Sランクモンスターの《ベヒーモス》だけど、猫と間違われてエルフ娘の騎士(ペット)として暮らしてます（2025）', 'Sjiguaishoubeiximosibeiwurenchengxiaomaochengweijinglingnvhaideqishichongwuyiqishenghuo', 1, 'S', '', '8b60cc05', '奇幻,冒险,魔法,搞笑', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2916263982.jpg', '', '', '', '畠中祐 / 杉山里穗 / 矢野妃菜喜 / 楠木灯 / 上田瞳 / 大渊野野花 / 和久井优 / 内田真礼', '平川哲生', '', '', '迷宮都市・リューイン。', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 420, 0, 420, 420, '', 0, 0, 5.5, 0, 0, 1743752947, 1735400365, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这里是迷宫都市——琉因。这座城镇中有着充满怪兽的迷宫，而聚集了大</p><p>量的冒险者。</p><p>丧命而转生的主角在迷宫当中醒来，其外型却怎么看都是只小猫！？但地</p><p>的真实身分是——灾害级的S级怪默「具希摩斯」的幼默！</p><p>地遇见了一位D级的新人冒险者——爱莉亚。爱莉亚将地误认为小猫，把</p><p>受到重伤的地带回家包案照顾，并将地取名篇「球球」，然后收养为宠</p><p>物。球球被她的温柔举止打动，而发誓要成为守护爱莉亚的骑士。</p><p>球球活用地S级的力量，与爱莉亚一起在迷宫冒险。地将遇见性格丰富的</p><p>伙伴们，以骑士（宠物）的身分过起有时会受人溺爱的每一天！</p><p><br/></p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0975BA88EA4A5D0C50E978#第02集$MOE0975BA88EA4A5D0C50E97B#第03集$MOE0975BA88EA4A5D0C50E97A#第04集$MOE0975BA88EA4A5D0C50E97D#第05集$MOE0975BA88EA4A5D0C50E97C#第06集$MOE0975BA88EA4A5D0C50E97F#第07集$MOE0975BA88EA4A5D0C50E97E#第08集$MOE0975BA88EA4A5D0C50E971#第09集$MOE0975BA88EA4A5D0C50E970#第10集$MOE0975BA88EA4A5D0C50E879#第11集$MOE0975BA88EA4A5D0C50E878#第12集$MOE0975BA88EA4A5D0C50E87B$$$第01集$id_XS0975BA88EA4A5D0C50E978#第02集$id_XS0975BA88EA4A5D0C50E97B#第03集$id_XS0975BA88EA4A5D0C50E97A#第04集$id_XS0975BA88EA4A5D0C50E97D#第05集$id_XS0975BA88EA4A5D0C50E97C#第06集$id_XS0975BA88EA4A5D0C50E97F#第07集$id_XS0975BA88EA4A5D0C50E97E#第08集$id_XS0975BA88EA4A5D0C50E971#第09集$id_XS0975BA88EA4A5D0C50E970#第10集$id_XS0975BA88EA4A5D0C50E879#第11集$id_XS0975BA88EA4A5D0C50E878#第12集$id_XS0975BA88EA4A5D0C50E87B$$$第01集$id_MOE0975BA88EA4A5D0C50E978#第02集$id_MOE0975BA88EA4A5D0C50E97B#第03集$id_MOE0975BA88EA4A5D0C50E97A#第04集$id_MOE0975BA88EA4A5D0C50E97D#第05集$id_MOE0975BA88EA4A5D0C50E97C#第06集$id_MOE0975BA88EA4A5D0