INSERT INTO `mac_vod` VALUES (732, 1, 0, 0, '电锯人', '鏈鋸人（2022）', 'dianjuren', 1, 'L', '', 'fa698495', '漫画改,热血,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/300e6d42bbfa633f45d69bca6240f014c0d9de5b.png', '', '', '', '戶谷菊之介/井澤詩織/楠木燈/坂田將吾/菲魯茲·藍/伊瀨茉莉也/高橋花林/八代拓', '中山龍', '', '', '描述背负了父亲遗留下庞大债务、因此过著极端负穷生活的少年淀治，他因为救了恶魔波奇塔，并与牠一起以恶魔猎人的身分斩杀低阶恶魔来换取酬劳。有一天，流氓骗了淀治，让他成为一堆恶魔的祭品，淀治在临死之际，波奇', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 174, 0, 174, 174, '', 0, 0, 0.0, 0, 0, 1735435139, 1735422209, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>描述背负了父亲遗留下庞大债务、因此过著极端负穷生活的少年淀治，他因为救了恶魔波奇塔，并与牠一起以恶魔猎人的身分斩杀低阶恶魔来换取酬劳。有一天，流氓骗了淀治，让他成为一堆恶魔的祭品，淀治在临死之际，波奇塔牺牲自己，把心脏给了他，让他复活并拥有了恶魔的力量，只要一拉位在心脏那边的链子就能发动。之后淀治被公安人员看上，因此成为公安的恶魔猎人，就此展开奇妙的杀戮人生。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE5776BA81B11D540C50E978#第02集$MOE5776BA81B11D540C50E97B#第03集$MOE5776BA81B11D540C50E97A#第04集$MOE5776BA81B11D540C50E97D#第05集$MOE5776BA81B11D540C50E97C#第06集$MOE5776BA81B11D540C50E97F#第07集$MOE5776BA81B11D540C50E97E#第08集$MOE5776BA81B11D540C50E971#第09集$MOE5776BA81B11D540C50E970#第10集$MOE5776BA81B11D540C50E879#第11集$MOE5776BA81B11D540C50E878#第12集$MOE5776BA81B11D540C50E87B$$$第01集$id_XS5776BA81B11D540C50E978#第02集$id_XS5776BA81B11D540C50E97B#第03集$id_XS5776BA81B11D540C50E97A#第04集$id_XS5776BA81B11D540C50E97D#第05集$id_XS5776BA81B11D540C50E97C#第06集$id_XS5776BA81B11D540C50E97F#第07集$id_XS5776BA81B11D540C50E97E#第08集$id_XS5776BA81B11D540C50E971#第09集$id_XS5776BA81B11D540C50E970#第10集$id_XS5776BA81B11D540C50E879#第11集$id_XS5776BA81B11D540C50E878#第12集$id_XS5776BA81B11D540C50E87B$$$第01集$id_MOE5776BA81B11D540C50E978#第02集$id_MOE5776BA81B11D540C50E97B#第03集$id_MOE5776BA81B11D540C50E97A#第04集$id_MOE5776BA81B11D540C50E97D#第05集$id_MOE5776BA81B11D540C50E97C#第06集$id_MOE5776BA81B11D540C50E97F#第07集$id_MOE5776BA81B11D540C50E97E#第08集$id_MOE5776BA81B11D540C50E971#第09集$id_MOE5776BA81B11D540C50E970#第10集$id_MOE5776BA81B11D540C50E879#第11集$id_MOE5776BA81B11D540C50E878#第12集$id_MOE5776BA81B11D540C50E87B', 