INSERT INTO `mac_vod` VALUES (737, 1, 0, 0, '甘城光辉游乐园', '甘城ブリリアントパーク（2014）', 'ganchengguanghuiyouleyuan', 1, 'G', '', '2752a22a', '日常,奇幻,励志,职场', 'http://i0.hdslb.com/bfs/bangumi/image/d15c7b1a5b6e90abeea78844ff97f9443fc2588c.png', '', '', '', '内山昂辉 / 加隈亚衣 / 藤井雪代 / 川澄绫子 / 野中蓝 / 白石凉子 / 相坂优歌 / 黑泽朋世 / 三上枝织 / 津田美波 / 五十岚裕美 / 高森奈津美 / 千菅春香 / 中村樱 / 福山润 / 桧山修之 / 寺岛拓笃 / 日野聪 / 中田让治 / 三木真一郎 / 田中正彦 / 诹访部顺一', '武本康弘 / 石原立也 / 北之原孝将 / 藤田春香 / 小川太一 / 山村卓也 / 河浪荣作', '', '', '被谜之转校生——千斗五十铃强迫而接受游乐园约会的可儿江西也，不知何故被拉到的地方，却是一个充满了破旧游乐设施的日本第一的遗憾游乐园——甘城辉煌游乐园。这座游乐园建立于泡沫经济全盛期，近年假日来客人数不', '全14集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 9.7, 0, 0, 1735530929, 1735429933, 0, 0, 0, 0, 0.0, '', '738', '', '', '', '', '', '', '', '<p>被谜之转校生——千斗五十铃强迫而接受游乐园约会的可儿江西也，不知何故被拉到的地方，却是一个充满了破旧游乐设施的日本第一的遗憾游乐园——甘城辉煌游乐园。这座游乐园建立于泡沫经济全盛期，近年假日来客人数不超过3000人，同时也是臭名远播的最糟约会地点代名词，现在最大的问题是，三个月内来客人数如不满25万人就得关闭。\n被引荐给了游乐园的管理者，“真正的”公主——拉媞珐的西也，不知为何突然被托付了重建这个陷入闭园危机的游乐园的重任。\n原来，这里不是游乐园——？！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0320B98AE81B5F5850E978#第02集$MOE0320B98AE81B5F5850E97B#第03集$MOE0320B98AE81B5F5850E97A#第04集$MOE0320B98AE81B5F5850E97D#第05集$MOE0320B98AE81B5F5850E97C#第06集$MOE0320B98AE81B5F5850E97F#第07集$MOE0320B98AE81B5F5850E97E#第08集$MOE0320B98AE81B5F5850E971#第09集$MOE0320B98AE81B5F5850E970#第10集$MOE0320B98AE81B5F5850E879#第11集$MOE0320B98AE81B5F5850E878#第12集$MOE0320B98AE81B5F5850E87B#第13集$MOE0320B98AE81B5F5850E87A#第14集$MOE0320B98AE81B5F5850E87D$$$第01集$id_XS0320B98AE81B5F5850E978#第02集$id_XS0320B98AE81B5F5850E97B#第03集$id_XS0320B98AE81B5F5850E97A#第04集$id_XS0320B98AE81B5F5850E97D#第05集$id_XS0320B98AE81B5F5850E97C#第06集$id_XS0320B98AE81B5F5850E97F#第07集$id_XS0320B98AE81B5F5850E97E#第08集$id_XS0320B98AE81B5F5850E971#第09集$id_XS0320B98AE81B5F5850E970#第10集$id_XS0320B98AE81B5F5850E879#第11集$id_XS0320B98AE81B5F5850E878#第12集$id_XS0320B98AE81B5F5850E87B#第13集$id_XS0320B98AE81B5F5850E87A#第14集$id_XS0320B98AE81B5F5850E87D$$$第01集$id_MOE0320B98AE81B5F5850E978#第02集$id_MOE0320B98AE81B5F5850E97B#第03集$id_MOE0320B98AE81B5F5850E97A#第04集$id_MOE0320B98AE81B5F5850E97D#第05集$id_MOE0320B98AE81B5F5850E97C#第06集$id_MOE0320B98AE81B5F5850E97F#第07集$id_MOE0320B98AE81B5F5850E97E#第08集$id_MOE0320B98AE81B5F5850E971#第09集$id_MOE0320B98AE81B5F5850E970#第10集$id_MOE0320B98AE81B5F5850E879#第11集$id_MOE0320B98AE81B5F5850E878#第12集$id_MOE0320B98AE81B5F5850E87B#第13集$id_MOE0320B98AE81B5F5850E87A#第14集$id_MOE0320B98AE81B5F5850E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (738, 1, 0, 0, '甘城光辉游乐园 SP 激动人心小剧场', '甘城ブリリアントパーク わくわくミニシアター（2014）', 'ganchengguanghuiyouleyuanSPjidongrenxinxiaojuchang', 1, 'G', '', '201633e3', '日常,治愈', 'http://i0.hdslb.com/bfs/bangumi/88739b4d0f11ac59eda06629fc131a0ae347974b.jpg', '', '', '', '内山昂辉 / 加隈亚衣 / 藤井雪代 / 相坂优歌 / 三上枝织', '武本康弘', '', '', '本作的舞台是架空都市甘城市，其中一座即将倒闭的主题公园“甘城光辉游乐园”。故事主要描写主角——自恋的高中生可儿江西也拯救游乐园、与吉祥物打闹的日常生活。', 'SP', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 9.7, 0, 0, 1735531165, 1735429971, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本作的舞台是架空都市甘城市，其中一座即将倒闭的主题公园“甘城光辉游乐园”。故事主要描写主角——自恋的高中生可儿江西也拯救游乐园、与吉祥物打闹的日常生活。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'SP01$MOE0327BD8EBA1A080A50E978#SP02$MOE0327BD8EBA1A080A50E97B#SP03$MOE0327BD8EBA1A080A50E97A#SP04$MOE0327BD8EBA1A080A50E97D#SP05$MOE0327BD8EBA1A080A50E97C#SP06$MOE0327BD8EBA1A080A50E97F#SP07$MOE0327BD8EBA1A080A50E97E$$$SP01$id_XS0327BD8EBA1A080A50E978#SP02$id_XS0327BD8EBA1A080A50E97B#SP03$id_XS0327BD8EBA1A080A50E97A#SP04$id_XS0327BD8EBA1A080A50E97D#SP05$id_XS0327BD8EBA1A080A50E97C#SP06$id_XS0327BD8EBA1A080A50E97F#SP07$id_XS0327BD8EBA1A080A50E97E$$$SP01$id_MOE0327BD8EBA1A080A50E978#SP02$id_MOE0327BD8EBA1A080A50E97B#SP03$id_MOE0327BD8EBA1A080A50E97A#SP04$id_MOE0327BD8EBA1A080A50E97D#SP05$id_MOE0327BD8EBA1A080A50E97C#SP06$id_MOE0327BD8EBA1A080A50E97F#SP07$id_MOE0327BD8EBA1A080A50E97E', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (739, 1, 0, 0, '在魔王城说晚安', '魔王城でおやすみ（2020）', 'zaimowangchengshuowanan', 1, 'Z', '', '30314a6c', '漫画改,奇幻,治愈,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/43cebed282c8af72960ece8a35826467c2501d77.png', '', '', '', '水濑祈 / 松冈祯丞 / 石川界人 / 小林亲弘 / 下野纮 / 小山力也 / 高桥伸也 / 山根雅史 / 相马康一 / 大原沙耶香 / 黑田崇矢 / 大塚刚央 / 大桥彩香 / 诹访部顺一 / 佐仓绫音 / 早见沙织', '山崎光惠 / 野吕纯惠 / 大隈孝晴 / 守田艺成 / 野木森达哉 / 白幡良志之', '', '', '从前，在那人与魔共同生活的时代。\r\n魔王将人类公主掳走，幽禁在了自己的城堡里——。\r\n被囚禁的栖夜莉丝公主，在囚牢中如此低语：“除了睡觉……没有别的事情干。”\r\n公主从囚牢中偷偷逃出来，为了获得更优质的睡眠', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.7, 0, 0, 1735542686, 1735429990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>从前，在那人与魔共同生活的时代。\n魔王将人类公主掳走，幽禁在了自己的城堡里——。\n被囚禁的栖夜莉丝公主，在囚牢中如此低语：“除了睡觉……没有别的事情干。”\n公主从囚牢中偷偷逃出来，为了获得更优质的睡眠而在魔王城中……探索!?\n随心所欲的人质公主把魔物们折腾得团团转！\n睡眠奇幻喜剧，开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0227BF89BD485B5A50E978#第02集$MOE0227BF89BD485B5A50E97B#第03集$MOE0227BF89BD485B5A50E97A#第04集$MOE0227BF89BD485B5A50E97D#第05集$MOE0227BF89BD485B5A50E97C#第06集$MOE0227BF89BD485B5A50E97F#第07集$MOE0227BF89BD485B5A50E97E#第08集$MOE0227BF89BD485B5A50E971#第09集$MOE0227BF89BD485B5A50E970#第10集$MOE0227BF89BD485B5A50E879#第11集$MOE0227BF89BD485B5A50E878#第12集$MOE0227BF89BD485B5A50E87B$$$第01集$id_XS0227BF89BD485B5A50E978#第02集$id_XS0227BF89BD485B5A50E97B#第03集$id_XS0227BF89BD485B5A50E97A#第04集$id_XS0227BF89BD485B5A50E97D#第05集$id_XS0227BF89BD485B5A50E97C#第06集$id_XS0227BF89BD485B5A50E97F#第07集$id_XS0227BF89BD485B5A50E97E#第08集$id_XS0227BF89BD485B5A50E971#第09集$id_XS0227BF89BD485B5A50E970#第10集$id_XS0227BF89BD485B5A50E879#第11集$id_XS0227BF89BD485B5A50E878#第12集$id_XS0227BF89BD485B5A50E87B$$$第01集$id_MOE0227BF89BD485B5A50E978#第02集$id_MOE0227BF89BD485B5A50E97B#第03集$id_MOE0227BF89BD485B5A50E97A#第04集$id_MOE0227BF89BD485B5A50E97D#第05集$id_MOE0227BF89BD485B5A50E97C#第06集$id_MOE0227BF89BD485B5A50E97F#第07集$id_MOE0227BF89BD485B5A50E97E#第08集$id_MOE0227BF89BD485B5A50E971#第09集$id_MOE0227BF89BD485B