INSERT INTO `mac_vod` VALUES (741, 1, 0, 0, '百变小樱', 'カードキャプターさくら（1998）', 'baibianxiaoying', 1, 'B', '', 'c7830e7b', '少女,魔法,冒险', 'http://i0.hdslb.com/bfs/bangumi/6fda8e95e61db0157008fc293360117d904239e4.jpg', '', '', '', '丹下樱 / 岩男润子 / 久川绫 / 小野坂昌也 / 熊井统子 / 绪方惠美 / 关智一 / 田中秀幸 / 野上尤加奈 / 伊藤美纪 / 佐佐木望 / 筱原惠美 / 冬马由美 / 小西克幸 / 柚木凉香 / 川上伦子 / 本井英美 / 松本美和 / 宫崎一成 / 林一夫 / 皆口裕子', '浅香守生 / 神户守 / 片渊须直 / 田中洋之 / 坂田纯一 / 高柳滋仁 / 政木伸一 / 中西伸彰 / 佐伯昭志 / 真野玲 / 水野和则 / 山口赖房 / 八谷贤一 / 长滨亘彦 / 松井仁之 / 三家本泰美 / 安藤健 / 三笠修 / 高濑节夫 / 桥本直人 / 富永恒雄', '', '', '木之本樱，是擅长体育的小学4年级学生。某天，小樱从学校回家，在平常都没有人的地下书房发现似乎有什么人的样子。小樱走下去一看，那里有一本闪耀着金色光芒的书。里面装有牌，然而，在读写在上面的文字的时候，刮', '全70集', '', 0, '0', '', '', '日本', '日语', '1998', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 62, 0, 62, 62, '', 0, 0, 9.9, 0, 0, 1737443820, 1735430086, 0, 0, 0, 0, 0.0, '', '902', '', '', '', '', '', '', '', '<p>木之本樱，是擅长体育的小学4年级学生。某天，小樱从学校回家，在平常都没有人的地下书房发现似乎有什么人的样子。小樱走下去一看，那里有一本闪耀着金色光芒的书。里面装有牌，然而，在读写在上面的文字的时候，刮来了剧烈的风，牌四处飞散开去。从书的最后，出现了名为可鲁贝洛斯的奇妙生物，书中写着库洛牌的封印被解开之时，灾难就会降临世间之类的话。随后，可鲁贝洛斯将封印的钥匙交给了小樱，令她成为收复牌的魔卡捕获者。当晚，小樱用魔法与实体化的魔卡对决……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5220B48BB94C5A5B50E978#第02集$MOE5220B48BB94C5A5B50E97B#第03集$MOE5220B48BB94C5A5B50E97A#第04集$MOE5220B48BB94C5A5B50E97D#第05集$MOE5220B48BB94C5A5B50E97C#第06集$MOE5220B48BB94C5A5B50E97F#第07集$MOE5220B48BB94C5A5B50E97E#第08集$MOE5220B48BB94C5A5B50E971#第09集$MOE5220B48BB94C5A5B50E970#第10集$MOE5220B48BB94C5A5B50E879#第11集$MOE5220B48BB94C5A5B50E878#第12集$MOE5220B48BB94C5A5B50E87B#第13集$MOE5220B48BB94C5A5B50E87A#第14集$MOE5220B48BB94C5A5B50E87D#第15集$MOE5220B48BB94C5A5B50E87C#第16集$MOE5220B48BB94C5A5B50E87F#第17集$MOE5220B48BB94C5A5B50E87E#第18集$MOE5220B48BB94C5A5B50E871#第19集$MOE5220B48BB94C5A5B50E870#第20集$MOE5220B48BB94C5A5B50EB79#第21集$MOE5220B48BB94C5A5B50EB78#第22集$MOE5220B48BB94C5A5B50EB7B#第23集$MOE5220B48BB94C5A5B50EB7A#第24集$MOE5220B48BB94C5A5B50EB7D#第25集$MOE5220B48BB94C5A5B50EB7C#第26集$MOE5220B48BB94C5A5B50EB7F#第27集$MOE5220B48BB94C5A5B50EB7E#第28集$MOE5220B48BB94C5A5B50EB71#第29集$MOE5220B48BB94C5A