INSERT INTO `mac_vod` VALUES (742, 1, 0, 0, '瓦尼塔斯的手记', 'ヴァニタスの手記（2021）', 'wanitasideshouji', 1, 'W', '', '280f8b83', '漫画改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/9aec14cf711e7968aa1796ae9ba2db8613a113de.png', '', '', '', '花江夏树 / 石川界人 / 水濑祈 / 下地紫野 / 茅野爱衣 / 石田彰 / 小牧未侑 / 木内太郎 / 游佐浩二 / 久間梨穂', '板村智幸', '', '', '这是逐渐走向毁灭的，吸血鬼们的故事。\r\n\r\n这里是同时存在着人类与吸血鬼的19世纪的法国。\r\n青年吸血鬼诺亚，为了寻找向吸血鬼散布诅咒的魔导书“瓦尼塔斯之书”，而踏上了前往巴黎的旅途。\r\n在路途中的飞船上，事', '全24集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 72, 0, 72, 72, '', 0, 0, 9.7, 0, 0, 1736213195, 1735430895, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是逐渐走向毁灭的，吸血鬼们的故事。\r\n\r\n这里是同时存在着人类与吸血鬼的19世纪的法国。\r\n青年吸血鬼诺亚，为了寻找向吸血鬼散布诅咒的魔导书“瓦尼塔斯之书”，而踏上了前往巴黎的旅途。\r\n在路途中的飞船上，事件发生了。\r\n混乱之中，在诺亚面前出现的是，自称专门治疗吸血鬼的人类医生、瓦尼塔斯。\r\n在瓦尼塔斯手中的，正是诺亚在寻找着的书……。\r\n\r\n因两人的相遇，诅咒与拯救的吸血鬼谭、拉开了幕布——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032FBCDEB14B550A50E978#第02集$MOE032FBCDEB14B550A50E97B#第03集$MOE032FBCDEB14B550A50E97A#第04集$MOE032FBCDEB14B550A50E97D#第05集$MOE032FBCDEB14B550A50E97C#第06集$MOE032FBCDEB14B550A50E97F#第07集$MOE032FBCDEB14B550A50E97E#第08集$MOE032FBCDEB14B550A50E971#第09集$MOE032FBCDEB14B550A50E970#第10集$MOE032FBCDEB14B550A50E879#第11集$MOE032FBCDEB14B550A50E878#第12集$MOE032FBCDEB14B550A50E87B#第13集$MOE032FBCDEB14B550A50E87A#第14集$MOE032FBCDEB14B550A50E87D#第15集$MOE032FBCDEB14B550A50E87C#第16集$MOE032FBCDEB14B550A50E87F#第17集$MOE032FBCDEB14B550A50E87E#第18集$MOE032FBCDEB14B550A50E871#第19集$MOE032FBCDEB14B550A50E870#第20集$MOE032FBCDEB14B550A50EB79#第21集$MOE032FBCDEB14B550A50EB78#第22集$MOE032FBCDEB14B550A50EB7B#第23集$MOE032FBCDEB14B550A50EB7A#第24集$MOE032FBCDEB14B550A50EB7D$$$第01集$id_XS032FBCDEB14B550A50E978#第02集$id_XS032FBCDEB14B550A50E97B#第03集$id_XS032FBCDEB14B550A50E97A#第04集$id_XS032FBCDEB14B550A50E97D#第05集$id_XS032FBCDEB14B550A50E97C#第06集$id_XS032FBCDEB14B550A50E97F#第07集$id_XS032FBCDEB14B550A50E97E#第08集$id_XS032FBCDEB14B550A50E971#第09集$id_XS032FBCDEB14B550A50E970#第10集$id_XS032FBCDEB14B550A50E879#第11集$id_XS032FB