INSERT INTO `mac_vod` VALUES (762, 1, 0, 0, '天使的心跳', 'Angel Beats!（2010）', 'tianshidexintiao', 1, 'T', '', '62077232', '奇幻,校园,战斗,催泪', 'http://i0.hdslb.com/bfs/bangumi/803ee7dc0e151ea3f634fe49e73d3b3fb93ca433.jpg', '', '', '', '神谷浩史 / 樱井浩美 / 花泽香菜 / 木村良平 / 水岛大宙 / 高木俊 / 斋藤枫子 / 牧野由依 / 增田裕生 / 迈克尔·里瓦斯 / 德本英一郎 / 小林由美子 / 市来光弘 / 绪方惠美 / 泽城美雪 / 喜多村英梨 / 松浦千惠 / 阿澄佳奈 / 加藤英美里 / 东地宏树 / 绿川光 / 中原麻衣 / 恒松步 / 中田让治 / 藤田咲 / 关智一 / 石田彰', '岸诚二 / 桥本裕之 / 安斋刚文 / 柿本广大 / 平井义通 / 高桥正典 / 许琮', '', '', '　　故事从男主角死亡之后从“死后的世界”醒来开始，在“死后的世界”中的学校里，他与一位名为由利(ゆり)、在“死后的世界”率领着一个名为“死んだ(Shinda)世界(Sekai)战线(Sensen)”简', '全13集 OVA', '', 0, '0', '', '', '日本', '日语', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 27, 0, 27, 27, '', 0, 0, 9.8, 0, 0, 1736009707, 1735962402, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　故事从男主角死亡之后从“死后的世界”醒来开始，在“死后的世界”中的学校里，他与一位名为由利(ゆり)、在“死后的世界”率领着一个名为“死んだ(Shinda)世界(Sekai)战线(Sensen)”简称“SSS”的组织的少女相遇了。“SSS”成立的主要目的是与赐予他们生前悲哀命运的神以及神之使者——天使交战，在天使超乎常理的异能面前，“SSS”只能用枪来反抗。就这样一场发生在“死后的世界”的学校里的超能大战物语开始了……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0725BC8FBE1B5E0B50E978#第02集$MOE0725BC8FBE1B5E0B50E97B#第03集$MOE0725BC8FBE1B5E0B50E97A#第04集$MOE0725BC8FBE1B5E0B50E97D#第05集$MOE0725BC8FBE1B5E0B50E97C#第06集$MOE0725BC8FBE1B5E0B50E97F#第07集$MOE0725BC8FBE1B5E0B50E97E#第08集$MOE0725BC8FBE1B5E0B50E971#第09集$MOE0725BC8FBE1B5E0B50E970#第10集$MOE0725BC8FBE1B5E0B50E879#第11集$MOE0725BC8FBE1B5E0B50E878#第12集$MOE0725BC8FBE1B5E0B50E87B#第13集$MOE0725BC8FBE1B5E0B50E87A#OVA01$MOE0725BC8FBE1B5E0B50E87D#OVA02$MOE0725BC8FBE1B5E0B50E87C#另一个结局$MOE0725BC8FBE1B5E0B50E87F$$$第01集$id_XS0725BC8FBE1B5E0B50E978#第02集$id_XS0725BC8FBE1B5E0B50E97B#第03集$id_XS0725BC8FBE1B5E0B50E97A#第04集$id_XS0725BC8FBE1B5E0B50E97D#第05集$id_XS0725BC8FBE1B5E0B50E97C#第06集$id_XS0725BC8FBE1B5E0B50E97F#第07集$id_XS0725BC8FBE1B5E0B50E97E#第08集$id_XS0725BC8FBE1B5E0B50E971#第09集$id_XS0725BC8FBE1B5E0B50E970#第10集$id_XS0725BC8FBE1B5E0B50E879#第11集$id_XS0725BC8FBE1B5E0B50E878#第12集$id_XS0725BC8FBE1B5E0B50E87B#第13集$id_XS0725BC8FBE1B5E0B50E87A#OVA01$id_XS07