INSERT INTO `mac_vod` VALUES (768, 1, 0, 0, '重生计划', 'ReLIFE（2016）', 'zhongshengjihua', 1, 'Z', '', '8d70395f', '校园,恋爱,搞笑,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/5d07b0a76dcbf7766df4bb498edfae15d52cbbc2.png', '', '', '', '小野贤章 / 茅野爱衣 / 内田雄马 / 上田丽奈 / 户松遥 / 木村良平 / 浪川大辅 / 泽城美雪 / 羽多野涉 / 白石凉子 / 伊藤静 / 渡边明乃', '小坂知 / 关晓子 / 中田诚 / 高桥亨 / 山田弘和 / 奥野浩行 / 神原敏昭 / 备前克彦', '', '', '海崎新太（27岁）在作为新毕业生进入的公司工作了3个月就辞职了。\\r\r\n之后他的就职活动也不顺利。\\r\r\n双亲寄来的生活费也中断了，不得已只好回到乡下。\\r\r\n能够倾听他烦恼的朋友和女友全都没有……\\r\r\n穷', '全17集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 0, 25, 25, '', 0, 0, 9.9, 0, 0, 1736072723, 1736007688, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>海崎新太（27岁）在作为新毕业生进入的公司工作了3个月就辞职了。\n之后他的就职活动也不顺利。\n双亲寄来的生活费也中断了，不得已只好回到乡下。\n能够倾听他烦恼的朋友和女友全都没有……\n穷途末路的海崎面前出现了一位神秘人物·夜明了。\n夜明向海崎提出，要他参加以尼特为对象的社会复归程序“ReLIFE”。\n其内容是，利用神秘的秘药，仅仅让外表回复年轻，并在一年内以高中生的身份去读高中——。</p>', 'js$$$xs$$$moe', '$$$$$$', '$$$$$$', '第01集$MOE0973BB88BA10585F50E978#第02集$MOE0973BB88BA10585F50E97B#第03集$MOE0973BB88BA10585F50E97A#第04集$MOE0973BB88BA10585F50E97D#第05集$MOE0973BB88BA10585F50E97C#第06集$MOE0973BB88BA10585F50E97F#第07集$MOE0973BB88BA10585F50E97E#第08集$MOE0973BB88BA10585F50E971#第09集$MOE0973BB88BA10585F50E970#第10集$MOE0973BB88BA10585F50E879#第11集$MOE0973BB88BA10585F50E878#第12集$MOE0973BB88BA10585F50E87B#第13集$MOE0973BB88BA10585F50E87A#第14集$MOE0973BB88BA10585F50E87D#第15集$MOE0973BB88BA10585F50E87C#第16集$MOE0973BB88BA10585F50E87F#第17集$MOE0973BB88BA10585F50E87E$$$第01集$id_XS0973BB88BA10585F50E978#第02集$id_XS0973BB88BA10585F50E97B#第03集$id_XS0973BB88BA10585F50E97A#第04集$id_XS0973BB88BA10585F50E97D#第05集$id_XS0973BB88BA10585F50E97C#第06集$id_XS0973BB88BA10585F50E97F#第07集$id_XS0973BB88BA10585F50E97E#第08集$id_XS0973BB88BA10585F50E971#第09集$id_XS0973BB88BA10585F50E970#第10集$id_XS0973BB88BA10585F50E879#第11集$id_XS0973BB88BA10585F50E878#第12集$id_XS0973BB88BA10585F50E87B#第13集$id_XS0973BB88BA10585F50E87A#第14集$id_XS0973BB88BA10585F50E87D#第15集$id_XS0973BB88BA10585F50E87C#第16集$id_XS0973BB88BA10585F50E87F#第17集$id_XS0973BB88BA10585F50E87E$$$第01集$id_MOE0973BB88BA10585F50E978#第02集$id_MOE0973BB88BA10585F50E97B#第03集$id_MOE0973BB88BA10585F50E97A#第04集$id_MOE0973BB88BA10585F50E97D#第05集$id_MOE0973BB88BA10585F50E97C#第06集$id_MOE0973BB88BA10585F50E97F#第07集$id_MOE0973BB88BA10585F50E97E#第08集$id_MOE0973BB88BA10585F50E971#第09集$id_MOE0973BB88BA10585F50E970#第10集$id_MOE0973BB88BA10585F50E879#第11集$id_MOE0973BB88BA10585F50E878#第12集$id_MOE0973BB88BA10585F50E87B#第13集$id_MOE0973BB88BA10585F50E87A#第14集$id_MOE0973BB88BA10585F50E87D#第15集$id_MOE0973BB88BA10585F50E87C#第16集$id_MOE0973BB88BA10585F50E87F#第17集$id_MOE0973BB88BA10585F50E87E', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (769, 1, 0, 0, '我独自升级 第二季', '俺だけレベルアップな件Season 2 -Arise from the Shadow-（2025）', 'woduzishengjidierji', 1, 'W', '', 'a4d12a3e', '动作,冒险,奇幻,魔法', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2913057387.jpg', '', '', '', '坂泰斗 / 上田丽奈 / 平川大辅 / 东地宏树 / 银河万丈 / 古川慎 / 中村源太 / 三川华月', '中重俊祐', '', '', '转职为暗影君王后，程肖宇获得了操纵影子大军的能力。为了治愈生病的母亲，寻找制作“生命神水”的材料，程肖宇独自踏上攻略恶魔域的道路......', '全13集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 1928, 0, 1928, 1928, '', 0, 0, 9.7, 0, 0, 1743754315, 1736010569, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>自世界各地出现连接异次元与现实世界的通路「传送门」，已过了十多年。觉醒了特殊能力，被称为「猎人」的人们，与存在于传送门里地下城内的魔兽不断厮杀。猎人的能力在觉醒后就不再有成长空间，其等级也不会再有变化。然而，被称作是人类最弱兵器的程肖宇，在一次双重地下城的突击任务中得到了只有自己能够「升级」的能力，得以在战斗中不断变强。顺利通过转职任务，得到能操纵暗影士兵的职业「暗影君主」的肖宇，为了取得或许能医治母亲病情的道具「生命神水」的素材，而投身于新的战斗之中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5023E889BB485E5C50E978#第02集$MOE5023E889BB485E5C50E97B#第03集$MOE5023E889BB485E5C50E97A#第04集$MOE5023E889BB485E5C50E97D#第05集$MOE5023E889BB485E5C50E97C#第06集$MOE5023E889BB485E5C50E97F#第07集$MOE5023E889BB485E5C50E97E#第08集$MOE5023E889BB485E5C50E971#第09集$MOE5023E889BB485E5C50E970#第10集$MOE5023E889BB485E5C50E879#第11集$MOE5023E889BB485E5C50E878#第12集$MOE5023E889BB485E5C50E87B#第13集$MOE5023E889BB485E5C50E87A$$$第01集$id_XS5023E889BB485E5C50E978#第02集$id_XS5023E889BB485E5C50E97B#第03集$id_XS5023E889BB485E5C50E97A#第04集$id_XS5023E889BB485E5C50E97D#第05集$id_XS5023E889BB485E5C50E97C#第06集$id_XS5023E889BB485E5C50E97F#第07集$id_XS5023E889BB485E5C50E97E#第08集$id_XS5023E889BB485E5C50E971#第09集$id_XS5023E889BB485E5C50E970#第10集$id_XS5023E889BB485E5C50E879#第11集$id_XS5023E889BB485E5C50E878#第12集$id_XS5023E889BB485E5C50E87B#第13集$id_XS5023E889BB485E5C50E87A$$$第01集$id_MOE5023E889BB485E5C50E978#第02集$id_MOE5023E889BB485E5C50E97B#第03集$id_MOE5023E889BB485E5C50E97A#第04集$id_MOE5023E889BB485E5C50E97D#第05集$id_MOE5023E889BB485E5C50E97C#第06集$id_MOE5023E889BB485E5C50E97F#第07集$id_MOE5023E889BB485E5C50E97E#第08集$id_MOE5023E889BB485E5C50E971#第09集$id_MOE5023E889BB485E5C50E970#第10集$id_MOE5023E889BB485E5C50E879#第11集$id_MOE5023E889BB485E5C50E878#第12集$id_MOE5023E889BB485E5C50E87B#第13集$id_MOE5023E889BB485E5C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (770, 1, 0, 0, '我与尼特女忍者的莫名同居生活', 'ニートくノ一となぜか同棲はじめました（2025）', 'woyunitenvrenzhedemomingtongjushenghuo', 1, 'W', '', 'a2325feb', '搞笑,恋爱,悠闲', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2912489164.jpg', '', '', '', '矢野妃菜喜 / 石毛翔弥 / 菲鲁兹·蓝 / 会泽纱弥 / 木野日菜 / 野上翔 / 村上真夏 / 堀江由衣 / 千叶繁', '斋藤久', '', '', '平凡なサラリーマン・安海政を妖魔から守護するべく、', '全13集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 224, 0, 224, 224, '', 0, 0, 5.5, 0, 0, 1743339198, 1736010703, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>平凡的上班族「安海政」被妖魔袭击时，天才女忍者「出浦白津莉」一身飒爽英姿出现拯救了他。为了守护平凡，远离妖魔的魔掌，白津莉以寄宿为条件与政缔结主仆契约，保护政的安全。然而，飒爽打倒妖魔的英姿底下，白津莉其实是个热爱游戏的尼特阿宅。过着被政宠溺，无所事事的同居生活，这样的白津莉身边也集结了一群独特的女忍者们……\r\n与尼特阿宅的天才女忍者之间的同居爱情喜剧即将上演</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5025BF8ABC4F085B50E978#第02集$MOE5025BF8ABC4F085B50E97B#第03集$MOE5025BF8ABC4F085B50E97A#第04集$MOE5025BF8ABC4F085B50E97D#第05集$MOE5025BF8ABC4F085B50E97C#第06集$MOE5025BF8ABC4F085B50E97F#第07集$MOE5025BF8ABC4F085B50E97E#第08集$MOE5025BF8ABC4F085B50E971#第09集$MOE5025BF8ABC4F085B50E970#第10集$MOE5025BF8ABC4F085B50E879#第11集$MOE5025BF8ABC4F085B50E878#第12集$MOE5025BF8ABC4F085B50E87B#第13集$MOE5025BF8ABC4F085B50E87A$$$第01集$id_XS5025BF8ABC4F085B50E978#第02集$id_XS5025BF8ABC4F085B50E97B#第03集$id_XS5025BF8ABC4F085B50E97A#第04集$id_XS5025BF8ABC4F085B50E97D#第05集$id_XS5025BF8ABC4F085B50E97C#第06集$id_XS5025BF8ABC4F085B50E97F#第07集$id_XS5025BF8ABC4F085B50E97E#第08集$id_XS5025BF8ABC4F085B50E971#第09集$id_XS5025BF8ABC4F085B50E970#第10集$id_XS5025BF8ABC4F085B50E879#第11集$id_XS5025BF8ABC4F085B50E878#第12集$id_XS5025BF8ABC4F085B50E87B#第13集$id_XS5025BF8ABC4F085B50E87A$$$第01集$id_MOE5025BF8ABC4F085B50E978#第02集$id_MOE5025BF8ABC4F085B50E97B#第03集$id_MOE5025BF8ABC4F085B50E97A#第04集$id_MOE5025BF8ABC4F085B50E97D#第05集$id_MOE5025BF8ABC4F085B50E97C#第06集$id_MOE5025BF8ABC4F085B50E97F#第07集$id_MOE5025BF8ABC4F085B50E97E#第08集$id_MOE5025BF8ABC4F085B50E971#第09集$id_MOE5025BF8ABC4F085B50E970#第10集$id_MOE5025BF8ABC4F085B50E879#第11集$id_MOE5025BF8ABC4F085B50E878#第12集$id_MOE5025BF8ABC4F085B50E87B#第13集$id_MOE5025BF8ABC4F085B50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (771, 1, 0, 0, '喜欢本大爷的竟然就你一个？', '俺を好きなのはお前だけかよ（2019）', 'xihuanbendayedejingranjiuniyige', 1, 'X', '', '198f8308', '小说改,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/f15812ebce696a98ee0907c8e8ac32a07e29095f.png', '', '', '', '山下大辉 / 户松遥 / 白石晴香 / 三泽纱千香 / 内田雄马 / 三上枝织 / 东山奈央 / 齐藤朱夏 / 佐伯伊织 / 种田梨沙 / 小原好美', '秋田谷典昭 / 守田艺成 / 岛崎奈奈子 / 伊部勇志 / 矢花馨 / 高岛大辅', '', '', '题目来了。如果你有兴趣的对象邀你去约会，你会怎么做？\r\n而且对象不只一个，有冰山美人型学姊和可爱型儿时玩伴葵花这两大美少女！\r\n这种时候当然会意气风发地前往碰面地点吧？\r\n结果她们向我表明的「心意」是！……', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 41, 0, 41, 41, '', 0, 0, 9.1, 0, 0, 1736116946, 1736016134, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>题目来了。如果你有兴趣的对象邀你去约会，你会怎么做？\r\n而且对象不只一个，有冰山美人型学姊和可爱型儿时玩伴葵花这两大美少女！\r\n这种时候当然会意气风发地前往碰面地点吧？\r\n结果她们向我表明的「心意」是！……要找我「恋爱谘商」怎么追我的好友啊哈哈哈……\r\n我不干了！不干不干！\r\n我终于从「迟钝型无害角色」变回原来的本大爷啦，可是本大爷不会在这种时候怨天尤人。\r\n因为只要帮她们做这恋爱谘商，说不定她们就会喜欢上本大爷啊！\r\n然而，有一名少女从旁看著本大爷这种悲哀的孤军奋战。\r\n她是绑辫子戴眼镜的阴沉女──三色院堇子。\r\n该怎么说，本大爷讨厌这女的，偏偏……喜欢本大爷的竟然就你一个？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE002EB4DEB11A5D0150E978#第02集$MOE002EB4DEB11A5D0150E97B#第03集$MOE002EB4DEB11A5D0150E97A#第04集$MOE002EB4DEB11A5D0150E97D#第05集$MOE002EB4DEB11A5D0150E97C#第06集$MOE002EB4DEB11A5D0150E97F#第07集$MOE002EB4DEB11A5D0150E97E#第08集$MOE002EB4DEB11A5D0150E971#第09集$MOE002EB4DEB11A5D0150E970#第10集$MOE002EB4DEB11A5D0150E879#第11集$MOE002EB4DEB11A5D0150E878#第12集$MOE002EB4DEB11A5D0150E87B#OVA$MOE002EB4DEB11A5D0150E87A$$$第01集$id_XS002EB4DEB11A5D0150E978#第02集$id_XS002EB4DEB11A5D0150E97B#第03集$id_XS002EB4DEB11A5D0150E97A#第04集$id_XS002EB4DEB11A5D0150E97D#第05集$id_XS002EB4DEB11A5D0150E97C#第06集$id_XS002EB4DEB11A5D0150E97F#第07集$id_XS002EB4DEB11A5D0150E97E#第08集$id_XS002EB4DEB11A5D0150E971#第09集$id_XS002EB4DEB11A5D0150E970#第10集$id_XS002EB4DEB11A5D0150E879#第11集$id_XS002EB4DEB11A5D0150E878#第12集$id_XS002EB4DEB11A5D0150E87B#OVA$id_XS002EB4DEB11A5D0150E87A$$$第01集$id_MOE002EB4DEB11A5D0150E978#第02集$id_MOE002EB4DEB11A5D0150E97B#第03集$id_MOE002EB4DEB11A5D0150E97A#第04集$id_MOE002EB4DEB11A5D0150E97D#第05集$id_MOE002EB4DEB11A5D0150E97C#第06集$id_MOE002EB4DEB11A5D0150E97F#第07集$id_MOE002EB4DEB11A5D0150E97E#第08集$id_MOE002EB4DEB11A5D0150E971#第09集$id_MOE002EB4DEB11A5D0150E970#第10集$id_MOE002EB4DEB11A5D0150E879#第11集$id_MOE002EB4DEB11A5D0150E878#第12集$id_MOE002EB4DEB11A5D0150E87B#OVA$id_MOE002EB4DEB11A5D0150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (772, 1, 0, 0, '炎炎消防队', '炎炎ノ消防隊（2019）', 'yanyanxiaofangdui', 1, 'Y', '', '69a7a270', '漫画改,战斗,热血,奇幻', 'http://i0.hdslb.com/bfs/bangumi/4f3302a21bc658addbf9220e20ae71e18474956d.jpg', '', '', '', '梶原岳人 / 小林裕介 / 市道真央 / 楠大典 / 兴津和幸 / 日野聪 / 关智一 / 悠木碧 / 小西克幸 / Lynn / 河西健吾 / 宫野真守 / 前野智昭 / 上条沙惠子 / 铃村健一 / 中井和哉 / 津田健次郎 / 阪口大助', '八濑祐树 / 南川达马 / 古贺一臣 / 伊部勇志 / 千叶大辅 / 宫崎修治 / 堀内勇冶', '', '', '全人类都在害怕着——\r\n普通人会毫无征兆地突然「燃烧」 ，变成操纵火焰的怪物「焰人」，\r\n并向周遭倾泻其极高破坏力的「人体自燃现象」 。\r\n与火焰的恐怖对抗的「特殊消防队」 ，他们的使命是解开人体自燃现象之', '全24集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 9.2, 0, 0, 1736134128, 1736016160, 0, 0, 0, 0, 0.0, '', '774', '', '', '', '', '', '', '', '<p>全人类都在害怕着——\r\n普通人会毫无征兆地突然「燃烧」 ，变成操纵火焰的怪物「焰人」，\r\n并向周遭倾泻其极高破坏力的「人体自燃现象」 。\r\n与火焰的恐怖对抗的「特殊消防队」 ，他们的使命是解开人体自燃现象之谜并拯救人类！\r\n出于某个原因被称为「恶魔」的新入队少年・森罗，以成为「英雄」为目标，\r\n与同伴们一起，投身于与「焰人」对抗的日子中！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE072EED8FE81B5A0950E978#第02集$MOE072EED8FE81B5A0950E97B#第03集$MOE072EED8FE81B5A0950E97A#第04集$MOE072EED8FE81B5A0950E97D#第05集$MOE072EED8FE81B5A0950E97C#第06集$MOE072EED8FE81B5A0950E97F#第07集$MOE072EED8FE81B5A0950E97E#第08集$MOE072EED8FE81B5A0950E971#第09集$MOE072EED8FE81B5A0950E970#第10集$MOE072EED8FE81B5A0950E879#第11集$MOE072EED8FE81B5A0950E878#第12集$MOE072EED8FE81B5A0950E87B#第13集$MOE072EED8FE81B5A0950E87A#第14集$MOE072EED8FE81B5A0950E87D#第15集$MOE072EED8FE81B5A0950E87C#第16集$MOE072EED8FE81B5A0950E87F#第17集$MOE072EED8FE81B5A0950E87E#第18集$MOE072EED8FE81B5A0950E871#第19集$MOE072EED8FE81B5A0950E870#第20集$MOE072EED8FE81B5A0950EB79#第21集$MOE072EED8FE81B5A0950EB78#第22集$MOE072EED8FE81B5A0950EB7B#第23集$MOE072EED8FE81B5A0950EB7A#第24集$MOE072EED8FE81B5A0950EB7D$$$第01集$id_XS072EED8FE81B5A0950E978#第02集$id_XS072EED8FE81B5A0950E97B#第03集$id_XS072EED8FE81B5A0950E97A#第04集$id_XS072EED8FE81B5A0950E97D#第05集$id_XS072EED8FE81B5A0950E97C#第06集$id_XS072EED8FE81B5A0950E97F#第07集$id_XS072EED8FE81B5A0950E97E#第08集$id_XS072EED8FE81B5A0950E971#第09集$id_XS072EED8FE81B5