INSERT INTO `mac_vod` VALUES (777, 1, 0, 0, '金牌得主', 'メダリスト（2025）', 'jinpaidezhu', 1, 'J', '', '94621d19', '漫画改,热血,运动', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2892155085.jpg', '', '', '', '春濑夏美 / 大塚刚央 / 市之濑加那 / 内田雄马', '山本靖贵', '', '', '深受过往失败所苦的花式滑冰选手，遇见一心追求滑冰梦想的年轻女孩，他决定成为她的教练，与她携手朝世界级金牌前进。', '全13集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 167, 0, 167, 167, '', 0, 0, 9.9, 0, 0, 1743523242, 1736116360, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在滑冰之路上受挫的青年明浦路司，与憧憬花样滑冰的少女结束祈相遇。司被祈对滑冰的执着打动，主动担任了她的教练。天赋不断绽放的祈，作为指导者不断成长的司，二人结成搭档，目标是成为光荣的“金牌得主”！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0823BA8AB84D5C0050E978#第02集$MOE0823BA8AB84D5C0050E97B#第03集$MOE0823BA8AB84D5C0050E97A#第04集$MOE0823BA8AB84D5C0050E97D#第05集$MOE0823BA8AB84D5C0050E97C#第06集$MOE0823BA8AB84D5C0050E97F#第07集$MOE0823BA8AB84D5C0050E97E#第08集$MOE0823BA8AB84D5C0050E971#第09集$MOE0823BA8AB84D5C0050E970#第10集$MOE0823BA8AB84D5C0050E879#第11集$MOE0823BA8AB84D5C0050E878#第12集$MOE0823BA8AB84D5C0050E87B#第13集$MOE0823BA8AB84D5C0050E87A$$$第01集$id_XS0823BA8AB84D5C0050E978#第02集$id_XS0823BA8AB84D5C0050E97B#第03集$id_XS0823BA8AB84D5C0050E97A#第04集$id_XS0823BA8AB84D5C0050E97D#第05集$id_XS0823BA8AB84D5C0050E97C#第06集$id_XS0823BA8AB84D5C0050E97F#第07集$id_XS0823BA8AB84D5C0050E97E#第08集$id_XS0823BA8AB84D5C0050E971#第09集$id_XS0823BA8AB84D5C0050E970#第10集$id_XS0823BA8AB84D5C0050E879#第11集$id_XS0823BA8AB84D5C0050E878#第12集$id_XS0823BA8AB84D5C0050E87B#第13集$id_XS0823BA8AB84D5C0050E87A$$$第01集$id_MOE0823BA8AB84D5C0050E978#第02集$id_MOE0823BA8AB84D5C0050E97B#第03集$id_MOE0823BA8AB84D5C0050E97A#第04集$id_MOE0823BA8AB84D5C0050E97D#第05集$id_MOE0823BA8AB84D5C0050E97C#第06集$id_MOE0823BA8AB84D5C0050E97F#第07集$id_MOE0823BA8AB84D5C0050E97E#第08集$id_MOE0823BA8AB84D5C0050E971#第09集$id_MOE0823BA8AB84D5C0050E970#第10集$id_MOE0823BA8AB84D5C0050E879#第11集$id_MOE0823BA8AB84D5C0050E878#第12集$id_MOE0823BA8AB84D5C0050E87B#第13集$id_MOE0823BA8AB84D5C0050E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (778, 1, 0, 0, '想摆脱公主教育的我', '妃教育から逃げたい私（2025）', 'xiangbaituogongzhujiaoyudewo', 1, 'X', '', 'bab37d87', '奇幻,恋爱,搞笑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2908775279.jpg', '', '', '', '白石晴香 / 福山润 / 羽多野涉 / 齐藤佑圭', '田头忍', '', '', '绝对想取消婚约的千金 vs 无论如何都想结婚的王太子，前所未闻的爱情攻防战自此揭开序幕！', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 98, 0, 98, 98, '', 0, 0, 4.6, 0, 0, 1742778612, 1736116671, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>身为亚斯达尔王国第一王子克拉克的未婚妻的蕾蒂希亚，自小便接受严格的太子妃培训，然而其实她真正想过的是钓钓鱼、爬爬树的自由生活！一心希望「解除婚约」的蕾蒂希亚，某天目睹克拉克在舞会上成为另一名陌生女性的护花使者。原本她还为了王子变心而开心不已，以为可以解除婚约……谁知克拉克居然没有放弃婚事！\r\n想跷掉太子妃培训，过上自由自在生活的蕾蒂希亚；与用尽办法就是要追到她，坦率表达爱意的克拉克。想解除婚约的太子妃vs想要结婚的王子，两人之间欢乐吵闹又心动满点的攻防战正式开幕！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5376EE8BBE4D550E50E978#第02集$MOE5376EE8BBE4D550E50E97B#第03集$MOE5376EE8BBE4D550E50E97A#第04集$MOE5376EE8BBE4D550E50E97D#第05集$MOE5376EE8BBE4D550E50E97C#第06集$MOE5376EE8BBE4D550E50E97F#第07集$MOE5376EE8BBE4D550E50E97E#第08集$MOE5376EE8BBE4D550E50E971#第09集$MOE5376EE8BBE4D550E50E970#第10集$MOE5376EE8BBE4D550E50E879#第11集$MOE5376EE8BBE4D550E50E878#第12集$MOE5376EE8BBE4D550E50E87B$$$第01集$id_XS5376EE8BBE4D550E50E978#第02集$id_XS5376EE8BBE4D550E50E97B#第03集$id_XS5376EE8BBE4D550E50E97A#第04集$id_XS5376EE8BBE4D550E50E97D#第05集$id_XS5376EE8BBE4D550E50E97C#第06集$id_XS5376EE8BBE4D550E50E97F#第07集$id_XS5376EE8BBE4D550E50E97E#第08集$id_XS5376EE8BBE4D550E50E971#第09集$id_XS5376EE8BBE4D550E50E970#第10集$id_XS5376EE8BBE4D550E50E879#第11集$id_XS5376EE8BBE4D550E50E878#第12集$id_XS5376EE8BBE4D550E50E87B$$$第01集$id_MOE5376EE8BBE4D550E50E978#第02集$id_MOE5376EE8BBE4D550E50E97B#第03集$id_MOE5376EE8BBE4D550E50E97A#第04集$id_MOE5376EE8BBE4D550E50E97D#第05集$id_MOE5376EE8BBE4D550E50E97C#第06集$id_MOE5376EE8BBE4D550E50E97F#第07集$id_MOE5376EE8BBE4D550E50E97E#第08集$id_MOE5376EE8BBE4D550E50E971#第09集$id_MOE5376EE8BBE4D550E50E970#第10集$id_MOE5376EE8BBE4D550E50E879#第11集$id_MOE5376EE8BBE4D550E50E878#第12集$id_MOE5376EE8BBE4D550