INSERT INTO `mac_vod` VALUES (779, 1, 0, 0, '星掠者', 'プランダラ（2020）', 'xingluezhe', 1, 'X', '', 'c8c0c4cb', '架空,漫画改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/23523b8986885db62bcc7874e294aa7b5fb767f2.png', '', '', '', '中岛良树 / 本泉莉奈 / 小泽亚李 / 市川苍 / 梅原裕一郎 / 伊藤静 / 悠木碧', '神户洋行', '', '', '被称为“废弃战争”之后的未曾有过的大战之后的世界艾尔西亚。在那里，强者从弱者手里夺取证实自己存在的“数字计数”，是一个弱肉强食的世界。\r\n在那样的世界里，2人相遇了。一个是用面具隐藏身份、为了弱者而挥动', '全24集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 5.4, 0, 0, 1736169235, 1736134214, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>被称为“废弃战争”之后的未曾有过的大战之后的世界艾尔西亚。在那里，强者从弱者手里夺取证实自己存在的“数字计数”，是一个弱肉强食的世界。\r\n在那样的世界里，2人相遇了。一个是用面具隐藏身份、为了弱者而挥动大刀的青年·离人。另一个是依靠母亲的遗言踏上寻找“传说中的击坠王”旅途的少女·阳菜。\r\n以2人的相遇为契机，以“数字计数”支配一切的世界之谜变得逐渐明朗。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE522FEF88EA1D0E5B50E978#第02集$MOE522FEF88EA1D0E5B50E97B#第03集$MOE522FEF88EA1D0E5B50E97A#第04集$MOE522FEF88EA1D0E5B50E97D#第05集$MOE522FEF88EA1D0E5B50E97C#第06集$MOE522FEF88EA1D0E5B50E97F#第07集$MOE522FEF88EA1D0E5B50E97E#第08集$MOE522FEF88EA1D0E5B50E971#第09集$MOE522FEF88EA1D0E5B50E970#第10集$MOE522FEF88EA1D0E5B50E879#第11集$MOE522FEF88EA1D0E5B50E878#第12集$MOE522FEF88EA1D0E5B50E87B#第13集$MOE522FEF88EA1D0E5B50E87A#第14集$MOE522FEF88EA1D0E5B50E87D#第15集$MOE522FEF88EA1D0E5B50E87C#第16集$MOE522FEF88EA1D0E5B50E87F#第17集$MOE522FEF88EA1D0E5B50E87E#第18集$MOE522FEF88EA1D0E5B50E871#第19集$MOE522FEF88EA1D0E5B50E870#第20集$MOE522FEF88EA1D0E5B50EB79#第21集$MOE522FEF88EA1D0E5B50EB78#第22集$MOE522FEF88EA1D0E5B50EB7B#第23集$MOE522FEF88EA1D0E5B50EB7A#第24集$MOE522FEF88EA1D0E5B50EB7D$$$第01集$id_XS522FEF88EA1D0E5B50E978#第02集$id_XS522FEF88EA1D0E5B50E97B#第03集$id_XS522FEF88EA1D0E5B50E97A#第04集$id_XS522FEF88EA1D0E5B50E97D#第05集$id_XS522FEF88EA1D0E5B50E97C#第06集$id_XS522FEF88EA1D0E5B50E97F#第07集$id_XS522FEF88EA1D0E5B50E97E#第08集$id_XS522FEF88EA1D0E5B50E971#第09集$id_XS522FEF88EA1D0E5B50E970#第10集$id_XS522FEF88EA1D0E5B50E879#第11集$id_XS522FEF88EA1D0E5B50E878#第12集$id_XS522FEF88EA1D0E5B50E87B#第13集$id_XS522FEF88EA1D