INSERT INTO `mac_vod` VALUES (789, 1, 0, 0, '幻界战线', '血界戦線（2015）', 'huanjiezhanxian', 1, 'H', '', '5f94b0e3', '科幻,热血,战斗', 'http://i0.hdslb.com/bfs/bangumi/2bdc085a0b514276539fafda97e4043f5ea641bb.jpg', '', '', '', '小山力也 / 阪口大助 / 中井和哉 / 藤原启治 / 绿川光 / 宫野真守 / 宫本充 / 小林优 / 钉宫理惠 / 折笠爱 / 银河万丈 / 大塚明夫 / 石冢运升 / 石田彰', '松本理惠 / 黑川智之 / 佐藤育郎 / 筑紫大介 / 上原秀明 / 藤本次朗 / 向井雅浩 / 阿部雅司', '', '', '纽约崩坏后，一夜之间便架构成了名为“赫尔沙雷姆兹·罗特”的城市。在连系着异世界与现世界的这个魔都里，有个为了保持世界的平衡而在暗地里非常活跃的组织——秘密结社·莱布拉。\r\n少年雷欧纳鲁德·渥奇在一连串的', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 9.6, 0, 0, 1736291915, 1736232352, 0, 0, 0, 0, 0.0, '', '791', '', '', '', '', '', '', '', '<p>纽约崩坏后，一夜之间便架构成了名为“赫尔沙雷姆兹·罗特”的城市。在连系着异世界与现世界的这个魔都里，有个为了保持世界的平衡而在暗地里非常活跃的组织——秘密结社·莱布拉。\r\n少年雷欧纳鲁德·渥奇在一连串的巧合下加入了莱布拉，他身上所隐藏的秘密将会带来什么样的影响呢…？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0471B58CEB19080A50E978#第02集$MOE0471B58CEB19080A50E97B#第03集$MOE0471B58CEB19080A50E97A#第04集$MOE0471B58CEB19080A50E97D#第05集$MOE0471B58CEB19080A50E97C#第06集$MOE0471B58CEB19080A50E97F#第07集$MOE0471B58CEB19080A50E97E#第08集$MOE0471B58CEB19080A50E971#第09集$MOE0471B58CEB19080A50E970#第10集$MOE0471B58CEB19080A50E879#第10.5集$MOE0471B58CEB19080A50E878#第11集$MOE0471B58CEB19080A50E87B#第12集$MOE0471B58CEB19080A50E87A#OAD$MOE0471B58CEB19080A50E87D$$$第01集$id_XS0471B58CEB19080A50E978#第02集$id_XS0471B58CEB19080A50E97B#第03集$id_XS0471B58CEB19080A50E97A#第04集$id_XS0471B58CEB19080A50E97D#第05集$id_XS0471B58CEB19080A50E97C#第06集$id_XS0471B58CEB19080A50E97F#第07集$id_XS0471B58CEB19080A50E97E#第08集$id_XS0471B58CEB19080A50E971#第09集$id_XS0471B58CEB19080A50E970#第10集$id_XS0471B58CEB19080A50E879#第10.5集$id_XS0471B58CEB19080A50E878#第11集$id_XS0471B58CEB19080A50E87B#第12集$id_XS0471B58CEB19080A50E87A#OAD$id_XS0471B58CEB19080A50E87D$$$第01集$id_MOE0471B58CEB19080A50E978#第02集$id_MOE0471B58CEB19080A50E97B#第03集$id_MOE0471B58CEB19080A50E97A#第04集$id_MOE0471B58CEB19080A50E97D#第05集$id_MOE0471B58CEB19080A50E97C#第06集$id_MOE0471B58CEB19080A50E97F#第07集$id_MOE0471B58CEB19080A50E97E#第08集$id_MOE0471B58CEB19080A50E971#第09集$id_MOE0471B58CEB19080A50E970#第10集$id_MOE0471B58CEB19080A50E879#第10.5集$id_MOE0471B58CEB19080A50E878#第11集$id_MOE0471B58CEB19080A50E87B#第12集$id_MOE0471B58CEB19080A50E87A#OAD$id_MOE0471B58CEB19080A50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (790, 3, 0, 0, '铃芽之旅', 'すずめの戸締まり（2023）', 'lingyazhilv', 1, 'L', '', '457e8b6b', '动画', 'https://i0.hdslb.com/bfs/bangumi/image/53a57fd0999f6c00e19b1d9a52c74e410e0dee9c.png', '', '', '', '原菜乃华 / 松村北斗 / 深津绘里 / 染谷将太 / 伊藤沙莉 / 花濑琴音 / 花泽香菜 / 松本白鹦 / 神木隆之介 / 山根馅 / 三浦明里', '新海诚', '', '', '故事讲述生活在日本九州田舍的17岁少女・铃芽遇见了为了寻找“门”而踏上旅途的青年。追随着青年的脚步，铃芽来到了山上一片废墟之地，在这里静静伫立着一扇古老的门，仿佛是坍塌中存留的唯一遗迹。铃芽仿佛被什么', '简中4K', '', 0, '0', '', '', '日本', '日语', '2023', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 152, 0, 152, 152, '', 0, 0, 9.8, 0, 0, 1736345754, 1736239069, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事讲述生活在日本九州田舍的17岁少女・铃芽遇见了为了寻找“门”而踏上旅途的青年。追随着青年的脚步，铃芽来到了山上一片废墟之地，在这里静静伫立着一扇古老的门，仿佛是坍塌中存留的唯一遗迹。铃芽仿佛被什么吸引了一般，将手伸向了那扇门…\r\n不久之后，日本各地的门开始一扇一扇地打开。据说，开着的门必须关上，否则灾祸将会从门的那一边降临于现世。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0522BBDDB14B5B5B50E978$$$正片$id_MOE0522BBDDB14B5B5B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (791, 1, 0, 0, '幻界战线 第二季', '血界戦線 &amp; BEYOND（2017）', 'huanjiezhanxiandierji', 1, 'H', '', 'eefdfbf8', '奇幻,战斗,漫画改', 'http://i0.hdslb.com/bfs/bangumi/bb264d8a63e2d152ba795a1c15314cdf49d7fb49.jpg', '', '', '', '小山力也 / 阪口大助 / 中井和哉 / 宫本充 / 小林优 / 绿川光 / 折笠爱 / 银河万丈 / 宫野真守 / 藤原启治 / 内田雄马 / 水树奈奈', '高柳滋仁 / 佐藤育郎 / 大矢雄嗣 / 莲井隆弘 / 高藤聪 / 佐佐木美和 / 向井雅浩 / 丝贺慎太郎', '', '', '曾经被称为纽约的城市，仅仅一晚便消失无踪。\r\n出现在那里的城市“赫尔沙雷姆兹·罗特”。在浓雾的另一侧展开，连结“异世界”与现世的这一地区，变化成了各怀心思的人们所跋扈的“地球上最危险的城市”。\r\n为了保护', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.8, 0, 0, 1736305734, 1736262731, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>曾经被称为纽约的城市，仅仅一晚便消失无踪。\r\n出现在那里的城市“赫尔沙雷姆兹·罗特”。在浓雾的另一侧展开，连结“异世界”与现世的这一地区，变化成了各怀心思的人们所跋扈的“地球上最危险的城市”。\r\n为了保护这座混沌之城的均衡，持续着不为人知的活动的人们。\r\n以使用布雷格利德流血斗术的强硬绅士克劳斯·V·莱因赫兹为首领，面带伤疤的克劳斯的左膀右臂史蒂芬，银发不良扎普·伦弗洛与半人半鱼的齐德，不可视的人狼钱·皇与独眼的淑女K·K。以及拥有“诸神的义眼”的青年雷欧……。\r\n当骚动发生之时，秘密结社·莱布拉必定会现身。\r\n响彻小巷子里的狂乱与邪恶的怪物们。深爱的深渊与不断重复的灾变。不会结束的家常便饭现在再次开幕。\r\n并且，去往更加遥远的Beyond……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5472EADCEF4B0B0150E978#第02集$MOE5472EADCEF4B0B0150E97B#第03集$MOE5472EADCEF4B0B0150E97A#第04集$MOE5472EADCEF4B0B0150E97D#第05集$MOE5472EADCEF4B0B0150E97C#第06集$MOE5472EADCEF4B0B0150E97F#第07集$MOE5472EADCEF4B0B0150E97E#第08集$MOE5472EADCEF4B0B0150E971#第09集$MOE5472EADCEF4B0B0150E970#第10集$MOE5472EADCEF4B0B0150E879#第11集$MOE5472EADCEF4B0B0150E878#第12集$MOE5472EADCEF4B0B0150E87B#OAD$MOE5472EADCEF4B0B0150E87A$$$第01集$id_XS5472EADCEF4B0B0150E978#第02集$id_XS5472EADCEF4B0B0150E97B#第03集$id_XS5472EADCEF4B0B0150E97A#第04集$id_XS5472EADCEF4B0B0150E97D#第05集$id_XS5472EADCEF4B0B0150E97C#第06集$id_XS5472EADCEF4B0B0150E97F#第07集$id_XS5472EADCEF4B0B0150E97E#第08集$id_XS5472EADCEF4B0B0150E971#第09集$id_XS5472EADCEF4B0B0150E970#第10集$id_XS5472EADCEF4B0B0150E879#第11集$id_XS5472EADCEF4B0B0150E878#第12集$id_XS5472EADCEF4B0B0150E87B#OAD$id_XS5472EADCEF4B0B0150E87A$$$第01集$id_MOE5472EADCEF4B0B0150E978#第02集$id_MOE5472EADCEF4B0B0150E97B#第03集$id_MOE5472EADCEF4B0B0150E97A#第04集$id_MOE5472EADCEF4B0B0150E97D#第05集$id_MOE5472EADCEF4B0B0150E97C#第06集$id_MOE5472EADCEF4B0B0150E97F#第07集$id_MOE5472EADCEF4B0B0150E97E#第08集$id_MOE5472EADCEF4B0B0150E971#第09集$id_MOE5472EADCEF4B0B0150E970#第10集$id_MOE5472EADCEF4B0B0150E879#第11集$id_MOE5472EADCEF4B0B0150E878#第12集$id_MOE5472EADCEF4B0B0150E87B#OAD$id_MOE5472EADCEF4B0B0150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (792, 1, 0, 0, '我的可爱对黑岩目高不管用', '黒岩メダカに私の可愛いが通じない（2025）', 'wodekeaiduiheiyanmugaobuguanyong', 1, 'W', '', 'f8ddd8f', '漫画改,校园,恋爱,日常', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2915067594.jpg', '', '', '', '岩崎谅太 / 芹泽优 / 雨宫天 / 花泽香菜 / 矢野妃菜喜 / 前田佳织里 / 畠中祐 / 山下大辉', '奥村吉昭', '', '', '容姿端麗！ スタイル抜群！ 川井モナは、息をするようにモテる女!!', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 272, 0, 272, 272, '', 0, 0, 5.7, 0, 0, 1743517329, 1736290817, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>容姿端麗！ スタイル抜群！ 川井モナは、息をするようにモテる女!! しかし、そんな彼女に見向きもしない転校生・黒岩メダカの登場で、 モナの学校生活は一変する！ 「今までずっと、チヤホヤされて生きてきたのに!!」 あの手この手でメダカをオトそうと大奮闘！ 時にはちょっぴりカゲキなことも!? モテ女子×禁欲男子のラブコメディ、大勃発――!!</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE572FE8DCED110B144DE8#第02集$MOE572FE8DCED110B144DEB#第03集$MOE572FE8DCED110B144DEA#第04集$MOE572FE8DCED110B144DED#第05集$MOE572FE8DCED110B144DEC#第06集$MOE572FE8DCED110B144DEF#第07集$MOE572FE8DCED110B144DEE#第08集$MOE572FE8DCED110B144DE1#第09集$MOE572FE8DCED110B144DE0#第10集$MOE572FE8DCED110B144CE9#第11集$MOE572FE8DCED110B144CE8#第12集$MOE572FE8DCED110B144CEB$$$第01集$id_XS572FE8DCED110B144DE8#第02集$id_XS572FE8DCED110B144DEB#第03集$id_XS572FE8DCED110B144DEA#第04集$id_XS572FE8DCED110B144DED#第05集$id_XS572FE8DCED110B144DEC#第06集$id_XS572FE8DCED110B144DEF#第07集$id_XS572FE8DCED110B144DEE#第08集$id_XS572FE8DCED110B144DE1#第09集$id_XS572FE8DCED110B144DE0#第10集$id_XS572FE8DCED110B144CE9#第11集$id_XS572FE8DCED110B144CE8#第12集$id_XS572FE8DCED110B144CEB$$$第01集$id_MOE572FE8DCED110B144DE8#第02集$id_MOE572FE8DCED110B144DEB#第03集$id_MOE572FE8DCED110B144DEA#第04集$id_MOE572FE8DCED110B144DED#第05集$id_MOE572FE8DCED110B144DEC#第06集$id_MOE572FE8DCED110B144DEF#第07集$id_MOE572FE8DCED110B144DEE#第08集$id_MOE572FE8DCED110B144DE1#第09集$id_MOE572FE8DCED110B144DE0#第10集$id_MOE572FE8DCED110B144CE9#第11集$id_MOE572FE8DCED110B144CE8#第12集$id_MOE572FE8DCED110B144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (793, 1, 0, 0, '弹丸论破', 'ダンガンロンパ 希望の学園と絶望の高校生（2013）', 'danwanlunpo', 1, 'D', '', '74abf9ad', '推理,校园', 'http://i0.hdslb.com/bfs/bangumi/e0b1959433cc60eeee7ae8f985c65e748a4b8cf4.jpg', '', '', '', '绪方惠美 / 大本真基子 / 樱井孝宏 / 日笠阳子 / 石田彰 / 山口胜平 / 中井和哉 / 泽城美雪 / 椎名碧流 / 斋藤千和 / 鸟海浩辅 / 松本和香子 / / 丰口惠美 / 宫田幸季 / 大山羡代 / 小西克幸', '岸诚二 / 木村真一郎 / 下司泰弘 / 小林孝志 / 野亦则行 / 镰田祐辅 / 岩田义彦', '', '', '故事以「私立希望之峰学园」作为舞台，该学校的入学要求有两个：1.必须是现役高中生。2.必须在其独特的领域具有超一流的水平。由政府公认办学，可以说能够从这间学校毕业的话人生几乎是等同于成功了。而主人公苗', '全13集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 9.3, 0, 0, 1736305891, 1736292050, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事以「私立希望之峰学园」作为舞台，该学校的入学要求有两个：1.必须是现役高中生。2.必须在其独特的领域具有超一流的水平。由政府公认办学，可以说能够从这间学校毕业的话人生几乎是等同于成功了。而主人公苗木诚和有着各式各样不同风格与擅长领域的14名超高校级学生一起参加入学典礼的时候，却看到一个自称是学园长的活动布偶熊表示：「一旦进来，就必须要一辈子都待在这里才行。如果想要毕业离开的话，只要互相残杀就好了！」就这样，因为这个不合理的理由，这群被关在这个绝望学园的高材生们，陷入除了杀人之外就是被杀的阴谋当中，加上破坏学生之间信赖关系的卑劣「学级裁判」制度，更让整个真相陷入扑朔迷离当中……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0623EDDAEF100C5D50E978#第02集$MOE0623EDDAEF100C5D50E97B#第03集$MOE0623EDDAEF100C5D50E97A#第04集$MOE0623EDDAEF100C5D50E97D#第05集$MOE0623EDDAEF100C5D50E97C#第06集$MOE0623EDDAEF100C5D50E97F#第07集$MOE0623EDDAEF100C5D50E97E#第08集$MOE0623EDDAEF100C5D50E971#第09集$MOE0623EDDAEF100C5D50E970#第10集$MOE0623EDDAEF100C5D50E879#第11集$MOE0623EDDAEF100C5D50E878#第12集$MOE0623EDDAEF100C5D50E87B#第13集$MOE0623EDDAEF100C5D50E87A$$$第01集$id_XS0623EDDAEF100C5D50E978#第02集$id_XS0623EDDAEF100C5D50E97B#第03集$id_XS0623EDDAEF100C5D50E97A#第04集$id_XS0623EDDAEF100C5D50E97D#第05集$id_XS0623EDDAEF100C5D50E97C#第06集$id_XS0623EDDAEF100C5D50E97F#第07集$id_XS0623EDDAEF100C5D50E97E#第08集$id_XS0623EDDAEF100C5D50E971#第09集$id_XS0623EDDAEF100C5D50E970#第10集$id_XS0623EDDAEF100C5D50E879#第11集$id_XS0623EDDAEF100C5D50E878#第12集$id_XS0623EDDAEF100C5D50E87B#第13集$id_XS0623EDDAEF100C5D50E87A$$$第01集$id_MOE0623EDDAEF100C5D50E978#第02集$id_MOE0623EDDAEF100C5D50E97B#第03集$id_MOE0623EDDAEF100C5D50E97A#第04集$id_MOE0623EDDAEF100C5D50E97D#第05集$id_MOE0623EDDAEF100C5D50E97C#第06集$id_MOE0623EDDAEF100C5D50E97F#第07集$id_MOE0623EDDAEF100C5D50E97E#第08集$id_MOE0623EDDAEF100C5D50E971#第09集$id_MOE0623EDDAEF100C5D50E970#第10集$id_MOE0623EDDAEF100C5D50E879#第11集$id_MOE0623EDDAEF100C5D50E878#第12集$id_MOE0623EDDAEF100C5D50E87B#第13集$id_MOE0623EDDAEF100C5D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (794, 1, 0, 0, '这个美术社大有问题！', 'この美術部には問題がある！（2016）', 'zhegemeishushedayouwenti', 1, 'Z', '', '4640d6c9', '校园,日常', 'http://i0.hdslb.com/bfs/bangumi/4d55f8a62a717c954c5bc92fc26e0d2dc9e0592e.jpg', '', '', '', '小泽亚李 / 小林裕介 / 上坂堇 / 东山奈央 / 水树奈奈 / 德井青空 / 小松未可子 / 佐仓绫音', '及川启 / 池端隆史 / 平峰义大 / 岩崎光洋 / 山本天志 / 冈村正弘 / 直谷隆 / 中田诚', '', '', '存在于平凡无奇的普通学校“月杜中学”的普通美术部。那里有着虽有绘画才能却只为了描绘理想的“二次元新娘”而燃起使命的内卷昴同学，以及对无可救药的内卷同学感到在意的宇佐美瑞希同学。以及，对两人似乎关注又似', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.8, 0, 0, 1736332899, 1736292237, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>存在于平凡无奇的普通学校“月杜中学”的普通美术部。那里有着虽有绘画才能却只为了描绘理想的“二次元新娘”而燃起使命的内卷昴同学，以及对无可救药的内卷同学感到在意的宇佐美瑞希同学。以及，对两人似乎关注又似乎没有关注、总在睡觉的部长，和总带着不可思议气息的神秘部员可蕾特同学。这样稍微有些遗憾的人们所集中的美术部，今天也在发生着什么问题——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0521B888ED1F0E0050E978#第02集$MOE0521B888ED1F0E0050E97B#第03集$MOE0521B888ED1F0E0050E97A#第04集$MOE0521B888ED1F0E0050E97D#第05集$MOE0521B888ED1F0E0050E97C#第06集$MOE0521B888ED1F0E0050E97F#第07集$MOE0521B888ED1F0E0050E97E#第08集$MOE0521B888ED1F0E0050E971#第09集$MOE0521B888ED1F0E0050E970#第10集$MOE0521B888ED1F0E0050E879#第11集$MOE0521B888ED1F0E0050E878#第12集$MOE0521B888ED1F0E0050E87B$$$第01集$id_XS0521B888ED1F0E0050E978#第02集$id_XS0521B888ED1F0E0050E97B#第03集$id_XS0521B888ED1F0E0050E97A#第04集$id_XS0521B888ED1F0E0050E97D#第05集$id_XS0521B888ED1F0E0050E97C#第06集$id_XS0521B888ED1F0E0050E97F#第07集$id_XS0521B888ED1F0E0050E97E#第08集$id_XS0521B888ED1F0E0050E971#第09集$id_XS0521B888ED1F0E0050E970#第10集$id_XS0521B888ED1F0E0050E879#第11集$id_XS0521B888ED1F0E0050E878#第12集$id_XS0521B888ED1F0E0050E87B$$$第01集$id_MOE0521B888ED1F0E0050E978#第02集$id_MOE0521B888ED1F0E0050E97B#第03集$id_MOE0521B888ED1F0E0050E97A#第04集$id_MOE0521B888ED1F0E0050E97D#第05集$id_MOE0521B888ED1F0E0050E97C#第06集$id_MOE0521B888ED1F0E0050E97F#第07集$id_MOE0521B888ED1F0E0050E97E#第08集$id_MOE0521B888ED1F0E0050E971#第09集$id_MOE0521B888ED1F0E0050E970#第10集$id_MOE0521B888ED1F0E0050E879#第11集$id_MOE0521B888ED1F0E0050E878#第12集$id_MOE0521B888ED1F0E0050E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (795, 1, 0, 0, '小木乃伊到我家', 'ミイラの飼い方（2018）', 'xiaomunaiyidaowojia', 1, 'X', '', '495166f2', '漫画改,萌系,搞笑,日常', 'http://i0.hdslb.com/bfs/bangumi/64f2a5e01f9cca99cef8e6e4415b9bb867281d0c.jpg', '', '', '', '田村睦心 / 河本启佑 / 茜屋日海夏 / 茅野爱衣 / 山下诚一郎', 'かおり', '', '', '过着普通生活的男高中生·柏木空，某天突然收到了在埃及旅行的自称“冒险家”的父亲送来的木乃伊。“发现了有趣的木乃伊，就先交给你了！”面对父亲如此写下的信，不由得发抖的空。但，从送来的巨大棺材里出现的，竟', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.6, 0, 0, 1736333002, 1736292300, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>过着普通生活的男高中生·柏木空，某天突然收到了在埃及旅行的自称“冒险家”的父亲送来的木乃伊。“发现了有趣的木乃伊，就先交给你了！”面对父亲如此写下的信，不由得发抖的空。但，从送来的巨大棺材里出现的，竟然是全长12cm！？手掌大小的木乃伊……不仅尺寸小，还很胆小、爱哭，却有着说不出来的可爱，空给这样的木乃伊起名为小伊，并开始照顾它。在同一屋檐下开始一起生活，空和小伊的共同生活究竟会……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE052EB989BF1F0B0B50E978#第02集$MOE052EB989BF1F0B0B50E97B#第03集$MOE052EB989BF1F0B0B50E97A#第04集$MOE052EB989BF1F0B0B50E97D#第05集$MOE052EB989BF1F0B0B50E97C#第06集$MOE052EB989BF1F0B0B50E97F#第07集$MOE052EB989BF1F0B0B50E97E#第08集$MOE052EB989BF1F0B0B50E971#第09集$MOE052EB989BF1F0B0B50E970#第10集$MOE052EB989BF1F0B0B50E879#第11集$MOE052EB989BF1F0B0B50E878#第12集$MOE052EB989BF1F0B0B50E87B$$$第01集$id_XS052EB989BF1F0B0B50E978#第02集$id_XS052EB989BF1F0B0B50E97B#第03集$id_XS052EB989BF1F0B0B50E97A#第04集$id_XS052EB989BF1F0B0B50E97D#第05集$id_XS052EB989BF1F0B0B50E97C#第06集$id_XS052EB989BF1F0B0B50E97F#第07集$id_XS052EB989BF1F0B0B50E97E#第08集$id_XS052EB989BF1F0B0B50E971#第09集$id_XS052EB989BF1F0B0B50E970#第10集$id_XS052EB989BF1F0B0B50E879#第11集$id_XS052EB989BF1F0B0B50E878#第12集$id_XS052EB989BF1F0B0B50E87B$$$第01集$id_MOE052EB989BF1F0B0B50E978#第02集$id_MOE052EB989BF1F0B0B50E97B#第03集$id_MOE052EB989BF1F0B0B50E97A#第04集$id_MOE052EB989BF1F0B0B50E97D#第05集$id_MOE052EB989BF1F0B0B50E97C#第06集$id_MOE052EB989BF1F0B0B50E97F#第07集$id_MOE052EB989BF1F0B0B50E97E#第08集$id_MOE052EB989BF1F0B0B50E971#第09集$id_MOE052EB989BF1F0B0B50E970#第10集$id_MOE052EB989BF1F0B0B50E879#第11集$id_MOE052EB989BF1F0B0B50E878#第12集$id_MOE052EB989BF1F0B0B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (796, 1, 0, 0, '贤者之孙', '賢者の孫（2019）', 'xianzhezhisun', 1, 'X', '', 'e55f8e6b', '穿越,架空,奇幻,小说改', 'http://i0.hdslb.com/bfs/bangumi/d1f2baf4ea8217dd89d1aa3e45a75301b345b306.png', '', '', '', '小林裕介 / 小松昌平 / 本泉莉奈 / 若井友希 / 屋良有作 / 高岛雅罗 / 森川智之', '田村正文', '', '', '因意外过世的青年，转生到剑与魔法世界──强到破天荒!!!?\r\n理应意外身亡的青年，以婴儿姿态转世到了异世界!? 接着他被称为「贤者」的男人──梅林捡回家收养，取名为「西恩」。\r\n西恩在贤者身边学习魔法，并', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 6.8, 0, 0, 1736332741, 1736292327, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>因意外过世的青年，转生到剑与魔法世界──强到破天荒!!!?\r\n理应意外身亡的青年，以婴儿姿态转世到了异世界!? 接着他被称为「贤者」的男人──梅林捡回家收养，取名为「西恩」。\r\n西恩在贤者身边学习魔法，并顺利地成长，然而，他有一个致命的问题……\r\n没错，西恩十五岁时，梅林说了──「老夫忘记教常识了」!! \r\n「毫无常识」且「规格外」的主角所呈献，异世界奇幻生活开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5422B9DEB14C5B5B50E978#第02集$MOE5422B9DEB14C5B5B50E97B#第03集$MOE5422B9DEB14C5B5B50E97A#第04集$MOE5422B9DEB14C5B5B50E97D#第05集$MOE5422B9DEB14C5B5B50E97C#第06集$MOE5422B9DEB14C5B5B50E97F#第07集$MOE5422B9DEB14C5B5B50E97E#第08集$MOE5422B9DEB14C5B5B50E971#第09集$MOE5422B9DEB14C5B5B50E970#第10集$MOE5422B9DEB14C5B5B50E879#第11集$MOE5422B9DEB14C5B5B50E878#第12集$MOE5422B9DEB14C5B5B50E87B$$$第01集$id_XS5422B9DEB14C5B5B50E978#第02集$id_XS5422B9DEB14C5B5B50E97B#第03集$id_XS5422B9DEB14C5B5B50E97A#第04集$id_XS5422B9DEB14C5B5B50E97D#第05集$id_XS5422B9DEB14C5B5B50E97C#第06集$id_XS5422B9DEB14C5B5B50E97F#第07集$id_XS5422B9DEB14C5B5B50E97E#第08集$id_XS5422B9DEB14C5B5B50E971#第09集$id_XS5422B9DEB14C5B5B50E970#第10集$id_XS5422B9DEB14C5B5B50E879#第11集$id_XS5422B9DEB14C5B5B50E878#第12集$id_XS5422B9DEB14C5B5B50E87B$$$第01集$id_MOE5422B9DEB14C5B5B50E978#第02集$id_MOE5422B9DEB14C5B5B50E97B#第03集$id_MOE5422B9DEB14C5B5B50E97A#第04集$id_MOE5422B9DEB14C5B5B50E97D#第05集$id_MOE5422B9DEB14C5B5B50E97C#第06集$id_MOE5422B9DEB14C5B5B50E97F#第07集$id_MOE5422B9DEB14C5B5B50E97E#第08集$id_MOE5422B9DEB14C5B5B50E971#第09集$id_MOE5422B9DEB14C5B5B50E970#第10集$id_MOE5422B9DEB14C5B5B50E879#第11集$id_MOE5422B9DEB14C5B5B50E878#第12集$i