INSERT INTO `mac_vod` VALUES (797, 1, 0, 0, '排球少年！！', 'ハイキュー!!（2014）', 'paiqiushaonian', 1, 'P', '', '528b6bcf', '漫画改,热血,校园,运动', 'http://i0.hdslb.com/bfs/bangumi/92d815e4dce3818bb96d8c41ac02dea3da528d04.jpg', '', '', '', '村濑步 / 石川界人 / 日野聪 / 入野自由 / 林勇 / 细谷佳正 / 冈本信彦 / 内山昂辉 / 齐藤壮马 / 名冢佳织 / 神谷浩史 / 田中一成 / 浪川大辅 / 吉野裕行 / 中村悠一 / 梶裕贵 / 立花慎之介 / 松川央树 / 中泽匡智 / 石井马克', '满仲劝 / 大塚隆史 / 平田智浩 / 远藤广隆 / 平向智子 / 镰仓由实 / 石川真理子 / 井端义秀 / 江岛泰男 / 古田丈司 / 铃木孝聪 / 荻原露光 / 菊田幸一 / 神原敏昭 / 丝贺慎太郎 / 村山靖', '', '', '【本片由华盟字幕社译制】小时候，日向翔阳从电视上看见排球比赛，乌野高中的一名小个子在球上的英姿，简直就是个“小巨人”，对此非常深刻，并开始迷上排球，一直想成为“小巨人”一样的人。初中时排球社不够人数，', '全25集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 9.9, 0, 0, 1736386500, 1736292425, 0, 0, 0, 0, 0.0, '', '798,799,800', '', '', '', '', '', '', '', '<p>【本片由华盟字幕社译制】小时候，日向翔阳从电视上看见排球比赛，乌野高中的一名小个子在球上的英姿，简直就是个“小巨人”，对此非常深刻，并开始迷上排球，一直想成为“小巨人”一样的人。初中时排球社不够人数，只好默默等待，后来在终于有新成员后，参与了第一次也是最后一赛的比赛，不幸对决了最强队伍，结果当然落败。单凭自己的话，是绝对无法看见那景色的，不是自己一人的话，或许就能看见了…为了能够打出“胜利”的比赛，翔阳努力考入乌野高中，为了实现成为“小巨人”的排球梦想！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0425B4DABF4B0E5F50E978#第02集$MOE0425B4DABF4B0E5F50E97B#第03集$MOE0425B4DABF4B0E5F50E97A#第04集$MOE0425B4DABF4B0E5F50E97D#第05集$MOE0425B4DABF4B0E5F50E97C#第06集$MOE0425B4DABF4B0E5F50E97F#第07集$MOE0425B4DABF4B0E5F50E97E#第08集$MOE0425B4DABF4B0E5F50E971#第09集$MOE0425B4DABF4B0E5F50E970#第10集$MOE0425B4DABF4B0E5F50E879#第11集$MOE0425B4DABF4B0E5F50E878#第12集$MOE0425B4DABF4B0E5F50E87B#第13集$MOE0425B4DABF4B0E5F50E87A#第14集$MOE0425B4DABF4B0E5F50E87D#第15集$MOE0425B4DABF4B0E5F50E87C#第16集$MOE0425B4DABF4B0E5F50E87F#第17集$MOE0425B4DABF4B0E5F50E87E#第18集$MOE0425B4DABF4B0E5F50E871#第19集$MOE0425B4DABF4B0E5F50E870#第20集$MOE0425B4DABF4B0E5F50EB79#第21集$MOE0425B4DABF4B0E5F50EB78#第22集$MOE0425B4DABF4B0E5F50EB7B#第23集$MOE0425B4DABF4B0E5F50EB7A#第24集$MOE0425B4DABF4B0E5F50EB7D#第25集$MOE0425B4DABF4B0E5F50EB7C$$$第01集$id_XS0425B4DABF4B0E5F50E978#第02集$id_XS0425B4DABF4B0E5F50E97B#第03集$id_XS0425B4DABF4B0E5F50E97A#第04集$id_XS0425B4DABF4B0E5F50E97D#第05