INSERT INTO `mac_vod` VALUES (807, 1, 0, 0, '调教咖啡厅', 'ブレンド・S（2017）', 'diaojiaokafeiting', 1, 'D', '', 'bfef78b4', '少女,萌系,漫画改,日常', 'http://i0.hdslb.com/bfs/bangumi/f0043f638a4ce8307e0a299349d6d6beb4e7b97b.jpg', '', '', '', '和气杏未 / 鬼头明里 / 春野杏 / 种崎敦美 / 德井青空 / 前野智昭 / 铃木达央', '益山亮司 / 京极尚彦 / 黑柳利充 / 松本显吾 / 河原龙太 / 河合滋树 / 筱原正宽', '', '', '以一家咖啡厅为舞台，讲述着店员之间的交流，新人店员苺香来到了有着等各种性格特异员工的咖啡厅，在这充满特色的咖啡厅中，欢乐的打工生活由此展开！', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 9.6, 0, 0, 1736561528, 1736386875, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>以一家咖啡厅为舞台，讲述着店员之间的交流，新人店员苺香来到了有着等各种性格特异员工的咖啡厅，在这充满特色的咖啡厅中，欢乐的打工生活由此展开！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5371E9DEBE110F0D50E978#第02集$MOE5371E9DEBE110F0D50E97B#第03集$MOE5371E9DEBE110F0D50E97A#第04集$MOE5371E9DEBE110F0D50E97D#第05集$MOE5371E9DEBE110F0D50E97C#第06集$MOE5371E9DEBE110F0D50E97F#第07集$MOE5371E9DEBE110F0D50E97E#第08集$MOE5371E9DEBE110F0D50E971#第09集$MOE5371E9DEBE110F0D50E970#第10集$MOE5371E9DEBE110F0D50E879#第11集$MOE5371E9DEBE110F0D50E878#第12集$MOE5371E9DEBE110F0D50E87B$$$第01集$id_XS5371E9DEBE110F0D50E978#第02集$id_XS5371E9DEBE110F0D50E97B#第03集$id_XS5371E9DEBE110F0D50E97A#第04集$id_XS5371E9DEBE110F0D50E97D#第05集$id_XS5371E9DEBE110F0D50E97C#第06集$id_XS5371E9DEBE110F0D50E97F#第07集$id_XS5371E9DEBE110F0D50E97E#第08集$id_XS5371E9DEBE110F0D50E971#第09集$id_XS5371E9DEBE110F0D50E970#第10集$id_XS5371E9DEBE110F0D50E879#第11集$id_XS5371E9DEBE110F0D50E878#第12集$id_XS5371E9DEBE110F0D50E87B$$$第01集$id_MOE5371E9DEBE110F0D50E978#第02集$id_MOE5371E9DEBE110F0D50E97B#第03集$id_MOE5371E9DEBE110F0D50E97A#第04集$id_MOE5371E9DEBE110F0D50E97D#第05集$id_MOE5371E9DEBE110F0D50E97C#第06集$id_MOE5371E9DEBE110F0D50E97F#第07集$id_MOE5371E9DEBE110F0D50E97E#第08集$id_MOE5371E9DEBE110F0D50E971#第09集$id_MOE5371E9DEBE110F0D50E970#第10集$id_MOE5371E9DEBE110F0D50E879#第11集$id_MOE5371E9DEBE110F0D50E878#第12集$id_MOE5371E9DEBE110F0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (808, 1, 0, 0, '好比是最终迷宫前的少年到新手村生活一般的故事', 'たとえばラストダンジョン前の村の少年が序盤の街で暮らすような物語（2019）', 'haobishizuizhongmigongqiandeshaoniandaoxinshoucunshenghuoyibandegushi', 1, 'H', '', 'be77e3e0', '小说改,搞笑,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/86b7857fe724f62e8000c5759b6561cfeb9a2ee7.png', '', '', '', '花守由美里 / 茅野爱衣 / 日冈夏美 / 朝日奈丸佳 / 津田美波 / 伊藤美来', 'migmi', '', '', '居住在远离都市的村落中的少年·罗伊德。梦想成为军人的他，说白了就是“村里最弱的男人”。这样的他居然以军人为目标，当然也遭到身边村民的强烈反对。然而罗伊德心意已决，出发前往王都。\r\n其实，包括他本人在内的', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 7.8, 0, 0, 1736561441, 1736386885, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>居住在远离都市的村落中的少年·罗伊德。梦想成为军人的他，说白了就是“村里最弱的男人”。这样的他居然以军人为目标，当然也遭到身边村民的强烈反对。然而罗伊德心意已决，出发前往王都。\r\n其实，包括他本人在内的村民们都尚未知道一个重大的事实。那就是，他们都是曾经拯救了世界的英雄之后裔，所有人都拥有超越人类的力量。而“村里最弱的”罗伊德，也是超乎想像的强大……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5372BB8FEC1A080950E978#第02集$MOE5372BB8FEC1A080950E97B#第03集$MOE5372BB8FEC1A080950E97A#第04集$MOE5372BB8FEC1A080950E97D#第05集$MOE5372BB8FEC1A080950E97C#第06集$MOE5372BB8FEC1A080950E97F#第07集$MOE5372BB8FEC1A080950E97E#第08集$MOE5372BB8FEC1A080950E971#第09集$MOE5372BB8FEC1A080950E970#第10集$MOE5372BB8FEC1A080950E879#第11集$MOE5372BB8FEC1A080950E878#第12集$MOE5372BB8FEC1A080950E87B$$$第01集$id_XS5372BB8FEC1A080950E978#第02集$id_XS5372BB8FEC1A080950E97B#第03集$id_XS5372BB8FEC1A080950E97A#第04集$id_XS5372BB8FEC1A080950E97D#第05集$id_XS5372BB8FEC1A080950E97C#第06集$id_XS5372BB8FEC1A080950E97F#第07集$id_XS5372BB8FEC1A080950E97E#第08集$id_XS5372BB8FEC1A080950E971#第09集$id_XS5372BB8FEC1A080950E970#第10集$id_XS5372BB8FEC1A080950E879#第11集$id_XS5372BB8FEC1A080950E878#第12集$id_XS5372BB8FEC1A080950E87B$$$第01集$id_MOE5372BB8FEC1A080950E978#第02集$id_MOE5372BB8FEC1A080950E97B#第03集$id_MOE5372BB8FEC1A080950E97A#第04集$id_MOE5372BB8FEC1A080950E97D#第05集$id_MOE5372BB8FEC1A080950E97C#第06集$id_MOE5372BB8FEC1A080950E97F#第07集$id_MOE5372BB8FEC1A080950E97E#第08集$id_MOE5372BB8FEC1A080950E971#第09集$id_MOE5372BB8FEC1A0