INSERT INTO `mac_vod` VALUES (811, 1, 0, 0, '伪恋：', 'ニセコイ：（2015）', 'weilian', 1, 'W', '', '6f86d775', '日常,校园,漫画改', 'http://i0.hdslb.com/bfs/bangumi/ea9012550c4d720dc7756de36dd72f6984bb55c7.jpg', '', '', '', '内山昂辉 / 东山奈央 / 花泽香菜 / 小松未可子 / 阿澄佳奈 / 内山夕实 / 佐仓绫音 / 梶裕贵 / 子安武人 / 沼仓爱美 / 小岩井小鸟', '新房昭之 / 龙轮直征', '', '', '本作是一部青春爱情喜剧，故事以假装成恋人的两人——日本黑道“集英组”头目的独子一条乐，与美国黑帮“蜂巢”的当家千金桐崎千棘，还有一条乐所暗恋的女生小野寺小咲的三角关系为中心展开；随后又加入了性格各异的', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 9.4, 0, 0, 1736604363, 1736386918, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本作是一部青春爱情喜剧，故事以假装成恋人的两人——日本黑道“集英组”头目的独子一条乐，与美国黑帮“蜂巢”的当家千金桐崎千棘，还有一条乐所暗恋的女生小野寺小咲的三角关系为中心展开；随后又加入了性格各异的新角色——鸫诚士郎、橘万里花、奏仓羽。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0771B48EED1E5A0C50E978#第02集$MOE0771B48EED1E5A0C50E97B#第03集$MOE0771B48EED1E5A0C50E97A#第04集$MOE0771B48EED1E5A0C50E97D#第05集$MOE0771B48EED1E5A0C50E97C#第06集$MOE0771B48EED1E5A0C50E97F#第07集$MOE0771B48EED1E5A0C50E97E#第08集$MOE0771B48EED1E5A0C50E971#第09集$MOE0771B48EED1E5A0C50E970#第10集$MOE0771B48EED1E5A0C50E879#第11集$MOE0771B48EED1E5A0C50E878#第12集$MOE0771B48EED1E5A0C50E87B#OVA$MOE0771B48EED1E5A0C50E87A$$$第01集$id_XS0771B48EED1E5A0C50E978#第02集$id_XS0771B48EED1E5A0C50E97B#第03集$id_XS0771B48EED1E5A0C50E97A#第04集$id_XS0771B48EED1E5A0C50E97D#第05集$id_XS0771B48EED1E5A0C50E97C#第06集$id_XS0771B48EED1E5A0C50E97F#第07集$id_XS0771B48EED1E5A0C50E97E#第08集$id_XS0771B48EED1E5A0C50E971#第09集$id_XS0771B48EED1E5A0C50E970#第10集$id_XS0771B48EED1E5A0C50E879#第11集$id_XS0771B48EED1E5A0C50E878#第12集$id_XS0771B48EED1E5A0C50E87B#OVA$id_XS0771B48EED1E5A0C50E87A$$$第01集$id_MOE0771B48EED1E5A0C50E978#第02集$id_MOE0771B48EED1E5A0C50E97B#第03集$id_MOE0771B48EED1E5A0C50E97A#第04集$id_MOE0771B48EED1E5A0C50E97D#第05集$id_MOE0771B48EED1E5A0C50E97C#第06集$id_MOE0771B48EED1E5A0C50E97F#第07集$id_MOE0771B48EED1E5A0C50E97E#第08集$id_MOE0771B48EED1E5A0C50E971#第09集$id_MOE0771B48EED1E5A0C50E970#第10集$id_MOE0771B48EED1E5A0C50E879#第11集$id_MOE0771B48EED1E5A0