INSERT INTO `mac_vod` VALUES (813, 1, 0, 0, '阴晴不定大哥哥', 'うらみちお兄さん（2021）', 'yinqingbudingdagege', 1, 'Y', '', 'f28400d7', '漫画改,职场,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/24efecfe4d2af1ce2a5061e3a7b38a8b0cdb9a81.png', '', '', '', '神谷浩史 / 杉田智和 / 中村悠一 / 宫野真守 / 水树奈奈 / 木村良平 / 铃村健一 / 小野大辅 / 三木真一郎 / 堀内贤雄 / 花江夏树 / 高桥未奈美 / 佐藤利奈 / 中井和哉', '长山延好', '', '', '在教育节目中带领大家做体操的大哥哥表田里道，通称“体操大哥哥”，是一个对孩子们展现笑容的温柔大哥哥。\r\n但是，偶尔能看到他的另一面。\r\n\r\n好累、好痛苦、好想做个废人。\r\n\r\n因为情绪不稳定而偶尔流露出的大人的', '全13集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 9.8, 0, 0, 1739599529, 1736443566, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '在教育节目中带领大家做体操的大哥哥表田里道，通称“体操大哥哥”，是一个对孩子们展现笑容的温柔大哥哥。\n但是，偶尔能看到他的另一面。\n\n好累、好痛苦、好想做个废人。\n\n因为情绪不稳定而偶尔流露出的大人的阴沉一面，孩子们有点被震撼到……！？\n\n不管怎样成年人还是会向前。\n哪怕这个世界再没有希望，对这个社会再绝望……！\n\n『作为教育节目的大哥哥，我想要……回应那份期待』', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5725B48CB919090E50E978#第02集$MOE5725B48CB919090E50E97B#第03集$MOE5725B48CB919090E50E97A#第04集$MOE5725B48CB919090E50E97D#第05集$MOE5725B48CB919090E50E97C#第06集$MOE5725B48CB919090E50E97F#第07集$MOE5725B48CB919090E50E97E#第08集$MOE5725B48CB919090E50E971#第09集$MOE5725B48CB919090E50E970#第10集$MOE5725B48CB919090E50E879#第11集$MOE5725B48CB919090E50E878#第12集$MOE5725B48CB919090E50E87B#第13集$MOE5725B48CB919090E50E87A$$$第01集$id_XS5725B48CB919090E50E978#第02集$id_XS5725B48CB919090E50E97B#第03集$id_XS5725B48CB919090E50E97A#第04集$id_XS5725B48CB919090E50E97D#第05集$id_XS5725B48CB919090E50E97C#第06集$id_XS5725B48CB919090E50E97F#第07集$id_XS5725B48CB919090E50E97E#第08集$id_XS5725B48CB919090E50E971#第09集$id_XS5725B48CB919090E50E970#第10集$id_XS5725B48CB919090E50E879#第11集$id_XS5725B48CB919090E50E878#第12集$id_XS5725B48CB919090E50E87B#第13集$id_XS5725B48CB919090E50E87A$$$第01集$id_MOE5725B48CB919090E50E978#第02集$id_MOE5725B48CB919090E50E97B#第03集$id_MOE5725B48CB919090E50E97A#第04集$id_MOE5725B48CB919090E50E97D#第05集$id_MOE5725B48CB919090E50E97C#第06集$id_MOE5725B48CB919090E50E97F#第07集$id_MOE5725B48CB919090E50E97E#第08集$id_