INSERT INTO `mac_vod` VALUES (829, 1, 0, 0, '请问您今天要来点兔子吗？BLOOM', 'ご注文はうさぎですか？BLOOM（2020）', 'qingwenninjintianyaolaidiantuzimaBLOOM', 1, 'Q', '', 'b1aa48cc', '漫画改,日常,萌系,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/45812fddaeb60e33cfd327280661e02238697aaa.png', '', '', '', '佐仓绫音 / 水濑祈 / 种田梨沙 / 佐藤聪美 / 内田真礼 / 德井青空 / 村川梨衣 / 早见沙织 / 速水奖 / 清川元梦 / 水树奈奈', '桥本裕之 / 筱原正宽 / 江副仁美 / 山本阳介 / 夕澄庆英 / 徐传峰', '', '', '心爱在木造房屋小镇度过的第二个夏天即将结束，季节即将变成各种盛大活动满载的秋季。\r\n不论是在学校还是在Rabbit House，都有很多开心的事情！\r\n心爱、智乃以及大家都难以抑制对未来的期待……！', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 16, 0, 16, 16, '', 0, 0, 9.9, 0, 0, 1736658174, 1736594523, 0, 0, 0, 0, 0.0, '', '830,831', '', '', '', '', '', '', '', '<p>心爱在木造房屋小镇度过的第二个夏天即将结束，季节即将变成各种盛大活动满载的秋季。\r\n不论是在学校还是在Rabbit House，都有很多开心的事情！\r\n心爱、智乃以及大家都难以抑制对未来的期待……！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5326EDD9BD110E5A50E978#第02集$MOE5326EDD9BD110E5A50E97B#第03集$MOE5326EDD9BD110E5A50E97A#第04集$MOE5326EDD9BD110E5A50E97D#第05集$MOE5326EDD9BD110E5A50E97C#第06集$MOE5326EDD9BD110E5A50E97F#第07集$MOE5326EDD9BD110E5A50E97E#第08集$MOE5326EDD9BD110E5A50E971#第09集$MOE5326EDD9BD110E5A50E970#第10集$MOE5326EDD9BD110E5A50E879#第11集$MOE5326EDD9BD110E5A50E878#第12集$MOE5326EDD9BD110E5A50E87B$$$第01集$id_XS5326EDD9BD110E5A50E978#第02集$id_XS5326EDD9BD110E5A50E97B#第03集$id_XS5326EDD9BD110E5A50E97A#第04集$id_XS5326EDD9BD110E5A50E97D#第05集$id_XS5326EDD9BD110E5A50E97C#第06集$id_XS5326EDD9BD110E5A50E97F#第07集$id_XS5326EDD9BD110E5A50E97E#第08集$id_XS5326EDD9BD110E5A50E971#第09集$id_XS5326EDD9BD110E5A50E970#第10集$id_XS5326EDD9BD110E5A50E879#第11集$id_XS5326EDD9BD110E5A50E878#第12集$id_XS5326EDD9BD110E5A50E87B$$$第01集$id_MOE5326EDD9BD110E5A50E978#第02集$id_MOE5326EDD9BD110E5A50E97B#第03集$id_MOE5326EDD9BD110E5A50E97A#第04集$id_MOE5326EDD9BD110E5A50E97D#第05集$id_MOE5326EDD9BD110E5A50E97C#第06集$id_MOE5326EDD9BD110E5A50E97F#第07集$id_MOE5326EDD9BD110E5A50E97E#第08集$id_MOE5326EDD9BD110E5A50E971#第09集$id_MOE5326EDD9BD110E5A50E970#第10集$id_MOE5326EDD9BD110E5A50E879#第11集$id_M