INSERT INTO `mac_vod` VALUES (840, 1, 0, 0, '坂本日常', 'サカモト デイズ（2025）', 'banbenrichang', 1, 'B', '', '7599d0d0', '漫画改,热血,战斗,日常', 'https://i0.hdslb.com/bfs/bangumi/image/9d731a02054c4807cc0a01fc7768f87d0bab10c1.png', '', '', '', '杉田智和 / 岛崎信长 / 佐仓绫音 / 铃木崚汰 / 东山奈央 / 木野日菜 / 花江夏树 / 早见沙织 / 八代拓 / 根本京里', '渡边正树', '', '', '【第1-4集大会员抢先1集，第5集起大会员专享】曾有一名最强杀手，名叫坂本太郎。\r\n这个受到所有恶棍畏惧，受到所有杀手仰慕的男人——在某一天，坠入了爱河！！\r\n坂本对在便利店工作的葵一见钟情，很快就从杀手', '全11集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 250, 0, 250, 250, '', 0, 0, 8.8, 0, 0, 1742164156, 1736690990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>曾有一名最强杀手，名叫坂本太郎。\r\n这个受到所有恶棍畏惧，受到所有杀手仰慕的男人——在某一天，坠入了爱河！！\r\n坂本对在便利店工作的葵一见钟情，很快就从杀手界引退。他在结婚后生下女儿，在一个祥和的城市开着私营商店，变得和以前判若两人……严重发福了！！\r\n为了守护心爱的家人与安稳的日常，前传奇杀手迎战接连袭来的刺客。\r\n日常与非日常交织的硬核战斗剧，就此开幕！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0622B581ED19090950E978#第02集$MOE0622B581ED19090950E97B#第03集$MOE0622B581ED19090950E97A#第04集$MOE0622B581ED19090950E97D#第05集$MOE0622B581ED19090950E97C#第06集$MOE0622B581ED19090950E97F#第07集$MOE0622B581ED19090950E97E#第08集$MOE0622B581ED19090950E971#第09集$MOE0622B581ED19090950E970#第10集$MOE0622B581ED19090950E879#第11集$MOE0622B581ED19090950E878$$$第01集$id_XS0622B581ED19090950E978#第02集$id_XS0622B581ED19090950E97B#第03集$id_XS0622B581ED19090950E97A#第04集$id_XS0622B581ED19090950E97D#第05集$id_XS0622B581ED19090950E97C#第06集$id_XS0622B581ED19090950E97F#第07集$id_XS0622B581ED19090950E97E#第08集$id_XS0622B581ED19090950E971#第09集$id_XS0622B581ED19090950E970#第10集$id_XS0622B581ED19090950E879#第11集$id_XS0622B581ED19090950E878$$$第01集$id_MOE0622B581ED19090950E978#第02集$id_MOE0622B581ED19090950E97B#第03集$id_MOE0622B581ED19090950E97A#第04集$id_MOE0622B581ED19090950E97D#第05集$id_MOE0622B581ED19090950E97C#第06集$id_MOE0622B581ED19090950E97F#第07集$id_MOE0622B581ED19090950E97E#第08集$id_MOE0622B581ED19090950E971#第09集$id_MOE0622B581ED19090950E970#第10集$id_MOE0622B581ED19090950E879#第11集$id_MOE0622B581ED19090950E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (841, 1, 0, 0, '超超超超超喜欢你的100个女朋友 第二季', '君のことが大大大大大好きな100人の彼女 第2期（2025）', 'chaochaochaochaochaoxihuannide100genvpengyoudierji', 1, 'C', '', '2267f784', '校园,恋爱,搞笑', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2913001787.jpg', '', '', '', '加藤涉 / 本渡枫 / 富田美忧 / 长绳麻理亚 / 濑户麻沙美 / 朝井彩加 / 上坂堇 / 三森铃子 / 进藤天音 / 高尾奏音 / Lynn / 高桥李依', '佐藤光', '', '', '中学で失恋100回を達成した愛城恋太郎は、高校でこそ彼女を！と願い訪れた神社で、現れた恋の神様から「高校で出会う運命の人は100人いる」と告げられる。', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 731, 0, 731, 731, '', 0, 0, 8.6, 0, 0, 1743383340, 1736700829, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>爱城恋太郎在国中的失恋次数达到了100次的大关，他抱着高中一定要交到女朋友的心愿访问神社。出现在那里的恋爱之神告诉他「你会在高中遇见的真命天女有100人」。然而神表示，和命中注定的人相遇的人，如果不和那个人彼此相爱并获得幸福的话就会死掉……。面对一个又一个等待着他的真命天女的相遇——恋太郎该怎么办！？100个女朋友又将何去何从！？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0325BA8FEF1E550D50E978#第02集$MOE0325BA8FEF1E550D50E97B#第03集$MOE0325BA8FEF1E550D50E97A#第04集$MOE0325BA8FEF1E550D50E97D#第05集$MOE0325BA8FEF1E550D50E97C#第06集$MOE0325BA8FEF1E550D50E97F#第07集$MOE0325BA8FEF1E550D50E97E#第08集$MOE0325BA8FEF1E550D50E971#第09集$MOE0325BA8FEF1E550D50E970#第10集$MOE0325BA8FEF1E550D50E879#第11集$MOE0325BA8FEF1E550D50E878#第12集$MOE0325BA8FEF1E550D50E87B$$$第01集$id_XS0325BA8FEF1E550D50E978#第02集$id_XS0325BA8FEF1E550D50E97B#第03集$id_XS0325BA8FEF1E550D50E97A#第04集$id_XS0325BA8FEF1E550D50E97D#第05集$id_XS0325BA8FEF1E550D50E97C#第06集$id_XS0325BA8FEF1E550D50E97F#第07集$id_XS0325BA8FEF1E550D50E97E#第08集$id_XS0325BA8FEF1E550D50E971#第09集$id_XS0325BA8FEF1E550D50E970#第10集$id_XS0325BA8FEF1E550D50E879#第11集$id_XS0325BA8FEF1E550D50E878#第12集$id_XS0325BA8FEF1E550D50E87B$$$第01集$id_MOE0325BA8FEF1E550D50E978#第02集$id_MOE0325BA8FEF1E550D50E97B#第03集$id_MOE0325BA8FEF1E550D50E97A#第04集$id_MOE0325BA8FEF1E550D50E97D#第05集$id_MOE0325BA8FEF1E550D50E97C#第06集$id_MOE0325BA8FEF1E550D50E97F#第07集$id_MOE0325BA8FEF1E550D50E97E#第08集$id_MOE0325BA8FEF1E550D50E971#第09集$id_MOE0325BA8FEF1E550D50E970#第10集$id_MOE0325BA8FEF1E550D50E879#第11集$id_MOE0325BA8FEF1E550D50E878#第12集$id_MOE0325BA8FEF1E550D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (842, 1, 0, 0, '地缚少年花子君 第二季', '地縛少年花子くん2（2025）', 'difushaonianhuazijundierji', 1, 'D', '', 'b7a87865', '漫画改,奇幻,搞笑,校园', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2914729116.jpg', '', '', '', '绪方惠美 / 鬼头明里 / 千叶翔也', '安藤正臣', '', '', '欸，你知道吗？关于海鸥学园的七大不可思议中的第七则故事。位于旧校舍三楼的女生厕所，花子就在那里，祂会实现用一个代价将自己召唤出来的人的愿望。召唤方式是敲三下门。然后──「花子、花子，您在吗？」', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 268, 0, 268, 268, '', 0, 0, 9.8, 0, 0, 1743343016, 1736702128, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>欸，你知道吗？关于海鸥学园的七大不可思议中的第七则故事。位于旧校舍三楼的女生厕所，花子就在那里，祂会实现用一个代价将自己召唤出来的人的愿望。召唤方式是敲三下门。然后──「花子、花子，您在吗？」\r\n\r\n与人称七大不可思议的第七则「厕所里的花子」的「花子同学」结缘的少女八寻宁宁，以及驱魔少年源光。他们两人每天都与花子同学一同奔走，将被改变的七大不可思议与怪异们恢复原状。\r\n某天，花子同学说了：七大不可思议中有叛徒。宁宁等人为了揪出叛徒，逐一破坏七大不可思议的附体之物。他们已破坏第二则「岬之阶梯」与第五则「16时的书库」，剩下的七大不可思议包括「厕所里的花子」在内，还有五则……\r\n另一方面，花子同学的弟弟司，与七峰樱、日向夏彦，还有变成新的七大不可思议的第三则「镜子地狱」的三叶，一同逼近宁宁他们还没见过的七大不可思议─</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5320ED80BE115B0C50E978#第02集$MOE5320ED80BE115B0C50E97B#第03集$MOE5320ED80BE115B0C50E97A#第04集$MOE5320ED80BE115B0C50E97D#第05集$MOE5320ED80BE115B0C50E97C#第06集$MOE5320ED80BE115B0C50E97F#第07集$MOE5320ED80BE115B0C50E97E#第08集$MOE5320ED80BE115B0C50E971#第09集$MOE5320ED80BE115B0C50E970#第10集$MOE5320ED80BE115B0C50E879#第11集$MOE5320ED80BE115B0C50E878#第12集$MOE5320ED80BE115B0C50E87B$$$第01集$id_XS5320ED80BE115B0C50E978#第02集$id_XS5320ED80BE115B0C50E97B#第03集$id_XS5320ED80BE115B0C50E97A#第04集$id_XS5320ED80BE115B0C50E97D#第05集$id_XS5320ED80BE115B0C50E97C#第06集$id_XS5320ED80BE115B0C50E97F#第07集$id_XS5320ED80BE115B0C50E97E#第08集$id_XS5320ED80BE115B0C50E971#第09集$id_XS5320ED80BE115B0C50E970#第10集$id_XS5320ED80BE115B0C50E879#第11集$id_XS5320ED80BE115B0C50E878#第12集$id_XS5320ED80BE115B0C50E87B$$$第01集$id_MOE5320ED80BE115B0C50E978#第02集$id_MOE5320ED80BE115B0C50E97B#第03集$id_MOE5320ED80BE115B0C50E97A#第04集$id_MOE5320ED80BE115B0C50E97D#第05集$id_MOE5320ED80BE115B0C50E97C#第06集$id_MOE5320ED80BE115B0C50E97F#第07集$id_MOE5320ED80BE115B0C50E97E#第08集$id_MOE5320ED80BE115B0C50E971#第09集$id_MOE5320ED80BE115B0C50E970#第10集$id_MOE5320ED80BE115B0C50E879#第11集$id_MOE5320ED80BE115B0C50E878#第12集$id_MOE5320ED80BE115B0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (843, 1, 0, 0, '魔鬼恋人', 'DIABOLIK LOVERS（2013）', 'moguilianren', 1, 'M', '', '3d54f436', '动作,冒险,奇幻,励志', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2031759591.jpg', '', '', '', '绿川光 / 梶裕贵 / 平川大辅 / 鸟海浩辅 / 小西克幸 / 近藤隆 / 末柄里惠', '田頭しのぶ', '', '', '故事发生在岭帝学院高校中，小森唯（末柄里慧 配音）是刚刚转校来到此处的转学生，除了拥有能够看到鬼魂的灵异体质外，她和所有同龄的女高中生别无二致。一次偶然中，小唯和神秘的逆卷家六兄弟成为了室友，然而，令', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 6.4, 0, 0, 1736742525, 1736732504, 0, 0, 0, 0, 0.0, '', '844', '', '', '', '', '', '', '', '<p>故事发生在岭帝学院高校中，小森唯（末柄里慧 配音）是刚刚转校来到此处的转学生，除了拥有能够看到鬼魂的灵异体质外，她和所有同龄的女高中生别无二致。一次偶然中，小唯和神秘的逆卷家六兄弟成为了室友，然而，令小唯非常震惊的是，逆卷家竟然是有着百年渊源的吸血鬼家族。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0273B98CEF1D5E0F50E978#第02集$MOE0273B98CEF1D5E0F50E97B#第03集$MOE0273B98CEF1D5E0F50E97A#第04集$MOE0273B98CEF1D5E0F50E97D#第05集$MOE0273B98CEF1D5E0F50E97C#第06集$MOE0273B98CEF1D5E0F50E97F#第07集$MOE0273B98CEF1D5E0F50E97E#第08集$MOE0273B98CEF1D5E0F50E971#第09集$MOE0273B98CEF1D5E0F50E970#第10集$MOE0273B98CEF1D5E0F50E879#第11集$MOE0273B98CEF1D5E0F50E878#第12集$MOE0273B98CEF1D5E0F50E87B$$$第01集$id_XS0273B98CEF1D5E0F50E978#第02集$id_XS0273B98CEF1D5E0F50E97B#第03集$id_XS0273B98CEF1D5E0F50E97A#第04集$id_XS0273B98CEF1D5E0F50E97D#第05集$id_XS0273B98CEF1D5E0F50E97C#第06集$id_XS0273B98CEF1D5E0F50E97F#第07集$id_XS0273B98CEF1D5E0F50E97E#第08集$id_XS0273B98CEF1D5E0F50E971#第09集$id_XS0273B98CEF1D5E0F50E970#第10集$id_XS0273B98CEF1D5E0F50E879#第11集$id_XS0273B98CEF1D5E0F50E878#第12集$id_XS0273B98CEF1D5E0F50E87B$$$第01集$id_MOE0273B98CEF1D5E0F50E978#第02集$id_MOE0273B98CEF1D5E0F50E97B#第03集$id_MOE0273B98CEF1D5E0F50E97A#第04集$id_MOE0273B98CEF1D5E0F50E97D#第05集$id_MOE0273B98CEF1D5E0F50E97C#第06集$id_MOE0273B98CEF1D5E0F50E97F#第07集$id_MOE0273B98CEF1D5E0F50E97E#第08集$id_MOE0273B98CEF1D5E0F50E971#第09集$id_MOE0273B98CEF1D5E0F50E970#第10集$id_MOE0273B98CEF1D5E0F50E879#第11集$id_MOE0273B98CEF1D5E0F50E878#第12集$id_MOE0273B98CEF1D5E0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (844, 1, 0, 0, '魔鬼恋人 第二季', 'DIABOLIK LOVERS MORE, BLOOD（2015）', 'moguilianrendierji', 1, 'M', '', 'b234f705', '动作,冒险,奇幻,励志', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2240130685.jpg', '', '', '', '末柄里恵 / 绿川光 / 梶裕贵 / 平川大辅 / 鸟海浩辅 / 小西克幸 / 近藤隆 / 樱井孝宏 / 木村良平 / 铃木达央 / 岸尾大辅 / 森川智之 / 森久保祥太郎', '田頭しのぶ', '', '', '《魔鬼恋人第二季》讲述主人公小森唯是个普通的高中生，因为父亲工作的原因，寄住在远房亲戚逆卷家，却发现逆卷六兄弟真实身份是吸血鬼。逃跑失败的唯，抱着不安和恐惧，开始了新生活', '全12集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 28, 0, 28, 28, '', 0, 0, 6.7, 0, 0, 1736744671, 1736732518, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《魔鬼恋人第二季》讲述主人公小森唯是个普通的高中生，因为父亲工作的原因，寄住在远房亲戚逆卷家，却发现逆卷六兄弟真实身份是吸血鬼。逃跑失败的唯，抱着不安和恐惧，开始了新生活</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5325BF8CEF1E5D0C50E978#第02集$MOE5325BF8CEF1E5D0C50E97B#第03集$MOE5325BF8CEF1E5D0C50E97A#第04集$MOE5325BF8CEF1E5D0C50E97D#第05集$MOE5325BF8CEF1E5D0C50E97C#第06集$MOE5325BF8CEF1E5D0C50E97F#第07集$MOE5325BF8CEF1E5D0C50E97E#第08集$MOE5325BF8CEF1E5D0C50E971#第09集$MOE5325BF8CEF1E5D0C50E970#第10集$MOE5325BF8CEF1E5D0C50E879#第11集$MOE5325BF8CEF1E5D0C50E878#第12集$MOE5325BF8CEF1E5D0C50E87B$$$第01集$id_XS5325BF8CEF1E5D0C50E978#第02集$id_XS5325BF8CEF1E5D0C50E97B#第03集$id_XS5325BF8CEF1E5D0C50E97A#第04集$id_XS5325BF8CEF1E5D0C50E97D#第05集$id_XS5325BF8CEF1E5D0C50E97C#第06集$id_XS5325BF8CEF1E5D0C50E97F#第07集$id_XS5325BF8CEF1E5D0C50E97E#第08集$id_XS5325BF8CEF1E5D0C50E971#第09集$id_XS5325BF8CEF1E5D0C50E970#第10集$id_XS5325BF8CEF1E5D0C50E879#第11集$id_XS5325BF8CEF1E5D0C50E878#第12集$id_XS5325BF8CEF1E5D0C50E87B$$$第01集$id_MOE5325BF8CEF1E5D0C50E978#第02集$id_MOE5325BF8CEF1E5D0C50E97B#第03集$id_MOE5325BF8CEF1E5D0C50E97A#第04集$id_MOE5325BF8CEF1E5D0C50E97D#第05集$id_MOE5325BF8CEF1E5D0C50E97C#第06集$id_MOE5325BF8CEF1E5D0C50E97F#第07集$id_MOE5325BF8CEF1E5D0C50E97E#第08集$id_MOE5325BF8CEF1E5D0C50E971#第09集$id_MOE5325BF8CEF1E5D0C50E970#第10集$id_MOE5325BF8CEF1E5D0C50E879#第11集$id_MOE5325BF8CEF1E5D0C50E878#第12集$id_MOE5325BF8CEF1E5D0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (845, 1, 0, 0, '骑士＆魔法', 'ナイツ＆マジック（2017）', 'qishimofa', 1, 'Q', '', 'f7feec88', '小说改,机战,奇幻,魔法', 'http://i0.hdslb.com/bfs/bangumi/0b06b207c8f1dbbccdc475ed387ef8873deb21ac.jpg', '', '', '', '高桥李依 / 大桥彩香 / 菅原慎介 / 内匠靖明 / 兴津和幸 / 伊藤静 / 伊丸冈笃 / 池田胜 / 大原沙耶香 / 菅生隆之 / 千本木彩花 / 土师孝也 / 木下浩之 / 加隈亚衣 / 小野大辅 / 麦人 / 松冈祯丞 / 潘惠子 / 田中敦子 / 田村由香里 / 朝井彩加 / 千叶进步 / 樱井浩美 / 稻田彻 / / 中村悠一 / 井上喜久子 / 阪口大助', '山本裕介 / 中山敦史 / 名和宗则 / 森义博 / 重原克也', '', '', '能干的程序员，同时是重度机器人宅的青年，转生到了巨大机器人“幻晶骑士（Silhouette Knight）”震动大地的骑士与魔法的异世界！？\r\n以艾尔涅斯帝·埃切贝里亚的身份转生的他，活用丰富的机械知识', '全13集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 8.8, 0, 0, 1736788438, 1736740646, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>能干的程序员，同时是重度机器人宅的青年，转生到了巨大机器人“幻晶骑士（Silhouette Knight）”震动大地的骑士与魔法的异世界！？\r\n以艾尔涅斯帝·埃切贝里亚的身份转生的他，活用丰富的机械知识以及身为程序员的才能，开始制造理想的机器人。但，他的行动演变成了超出预期的事态……！？ \r\n机器人宅的野望，将改变异世界！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5720EADDEC4A550150E978#第02集$MOE5720EADDEC4A550150E97B#第03集$MOE5720EADDEC4A550150E97A#第04集$MOE5720EADDEC4A550150E97D#第05集$MOE5720EADDEC4A550150E97C#第06集$MOE5720EADDEC4A550150E97F#第07集$MOE5720EADDEC4A550150E97E#第08集$MOE5720EADDEC4A550150E971#第09集$MOE5720EADDEC4A550150E970#第10集$MOE5720EADDEC4A550150E879#第11集$MOE5720EADDEC4A550150E878#第12集$MOE5720EADDEC4A550150E87B#第13集$MOE5720EADDEC4A550150E87A$$$第01集$id_XS5720EADDEC4A550150E978#第02集$id_XS5720EADDEC4A550150E97B#第03集$id_XS5720EADDEC4A550150E97A#第04集$id_XS5720EADDEC4A550150E97D#第05集$id_XS5720EADDEC4A550150E97C#第06集$id_XS5720EADDEC4A550150E97F#第07集$id_XS5720EADDEC4A550150E97E#第08集$id_XS5720EADDEC4A550150E971#第09集$id_XS5720EADDEC4A550150E970#第10集$id_XS5720EADDEC4A550150E879#第11集$id_XS5720EADDEC4A550150E878#第12集$id_XS5720EADDEC4A550150E87B#第13集$id_XS5720EADDEC4A550150E87A$$$第01集$id_MOE5720EADDEC4A550150E978#第02集$id_MOE5720EADDEC4A550150E97B#第03集$id_MOE5720EADDEC4A550150E97A#第04集$id_MOE5720EADDEC4A550150E97D#第05集$id_MOE5720EADDEC4A550150E97C#第06集$id_MOE5720EADDEC4A550150E97F#第07集$id_MOE5720EADDEC4A550150E97E#第08集$id_MOE5720EADDEC4A550150E971#第09集$id_MOE5720EADDEC4A550150E970#第10集$id_MOE5720EADDEC4A550150E879#第11集$id_MOE5720EADDEC4A550150E878#第12集$id_MOE5720EADDEC4A550150E87B#第13集$id_MOE5720EADDEC4A550150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (846, 1, 0, 0, '你与我最后的战场，亦或是世界起始的圣战', 'キミと僕の最後の戦場、あるいは世界が始まる聖戦（2020）', 'niyuwozuihoudezhanchangyihuoshishijieqishideshengzhan', 1, 'N', '', '21ac2dfc', '冒险,战斗,奇幻,恋爱', 'http://i0.hdslb.com/bfs/bangumi/image/7ca81f8b795dea220b9db1e35bdb6f356f31f533.png', '', '', '', '小林裕介 / 雨宫天 / 石原夏织 / 白城奈央 / 花守由美里 / 土岐隼一', '大沼心 / 凑未来', '', '', '高度发展科学技术被称为机械驱动的理想乡的“帝国”，以及驱使超自然力量的以“魔女之国”威名受到世人畏惧的“涅比利斯皇厅”。在持续了百年以上战争的两国战场上，有着两位英雄。\r\n以史上最年轻之姿晋升为帝国最强', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 19, 0, 19, 19, '', 0, 0, 8.0, 0, 0, 1736788533, 1736740659, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高度发展科学技术被称为机械驱动的理想乡的“帝国”，以及驱使超自然力量的以“魔女之国”威名受到世人畏惧的“涅比利斯皇厅”。在持续了百年以上战争的两国战场上，有着两位英雄。\r\n以史上最年轻之姿晋升为帝国最强战力的剑士·伊思卡，以及有着“冰祸魔女”称号的涅比利斯皇厅公主·爱丽丝莉洁。\r\n在战场上相遇的两人，以宿敌的身份展开了廝杀。为了保护国家、家人、同伴们，两人都抱有相互无法退让的矜持碰撞到一起。\r\n然而，在激斗过程中两人逐渐地了解对方的内心，都相互地被对方的生存之道和理想信念所吸引。即便两人心中都十分清楚无法并肩而行，能做的唯有战斗至其中一方倒下为止而已。\r\n而世界似乎也在嘲笑两人的残酷命运，两国之间形势逐日变得更加紧张，交织在各种阴谋策略之中。\r\n在这被割裂的世界，少年与少女的心却在不断靠近——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0326EDDBBB4D0B5A50E978#第02集$MOE0326EDDBBB4D0B5A50E97B#第03集$MOE0326EDDBBB4D0B5A50E97A#第04集$MOE0326EDDBBB4D0B5A50E97D#第05集$MOE0326EDDBBB4D0B5A50E97C#第06集$MOE0326EDDBBB4D0B5A50E97F#第07集$MOE0326EDDBBB4D0B5A50E97E#第08集$MOE0326EDDBBB4D0B5A50E971#第09集$MOE0326EDDBBB4D0B5A50E970#第10集$MOE0326EDDBBB4D0B5A50E879#第11集$MOE0326EDDBBB4D0B5A50E878#第12集$MOE0326EDDBBB4D0B5A50E87B$$$第01集$id_XS0326EDDBBB4D0B5A50E978#第02集$id_XS0326EDDBBB4D0B5A50E97B#第03集$id_XS0326EDDBBB4D0B5A50E97A#第04集$id_XS0326EDDBBB4D0B5A50E97D#第05集$id_XS0326EDDBBB4D0B5A50E97C#第06集$id_XS0326EDDBBB4D0B5A50E97F#第07集$id_XS0326EDDBBB4D0B5A50E97E#第08集$id_XS0326EDDBBB4D0B5A50E971#第09集$id_XS0326EDDBBB4D0B5A50E970#第10集$id_XS0326EDDBBB4D0B5A50E879#第11集$id_XS0326EDDBBB4D0B5A50E878#第12集$id_XS0326EDDBBB4D0B5A50E87B$$$第01集$id_MOE0326EDDBBB4D0B5A50E978#第02集$id_MOE0326EDDBBB4D0B5A50E97B#第03集$id_MOE0326EDDBBB4D0B5A50E97A#第04集$id_MOE0326EDDBBB4D0B5A50E97D#第05集$id_MOE0326EDDBBB4D0B5A50E97C#第06集$id_MOE0326EDDBBB4D0B5A50E97F#第07集$id_MOE0326EDDBBB4D0B5A50E97E#第08集$id_MOE0326EDDBBB4D0B5A50E971#第09集$id_MOE0326EDDBBB4D0B5A50E970#第10集$id_MOE0326EDDBBB4D0B5A50E879#第11集$id_MOE0326EDDBBB4D0B5A50E878#第12集$id_MOE0326EDDBBB4D0B5A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (847, 1, 0, 0, 'CAROLE＆TUESDAY', '卡罗尔与星期二（2019）', 'CAROLEu0026TUESDAY', 1, 'C', '', 'e53ad50f', '原创,科幻,音乐,励志', 'http://i0.hdslb.com/bfs/bangumi/b7de3941ff421c3942e8b73649318773e029a5d6.png', '', '', '', '岛袋美由利 / 市之濑加那 / 大塚明夫 / 入野自由 / 上坂堇 / 神谷浩史 / 宫野真守', '渡边信一郎 / 堀元宣 / 野亦则行 / 村田尚树 / 飞田刚 / 高藤聪 / 三宅将平 / 由井翠 / 宫泽良太', '', '', '距离人类移居到新的基地火星已经过了50年。这个时代中大多数的文化均由AI创造，人类只需要享受即可。\r\n有一位少女，生活在首都阿尔巴市，在工作之余的空闲时间里想努力成为一名音乐家，但她总感觉缺少些什么，她', '全24集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.7, 0, 0, 1736823268, 1736776883, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>距离人类移居到新的基地火星已经过了50年。这个时代中大多数的文化均由AI创造，人类只需要享受即可。\r\n有一位少女，生活在首都阿尔巴市，在工作之余的空闲时间里想努力成为一名音乐家，但她总感觉缺少些什么，她的名字叫Carole。\r\n有一位女孩，出生在赫舍尔市的富裕家庭，她的梦想是成为一名音乐家，但是周围却没有人能够理解她，她觉得自己是全世界最孤独的人，她的名字是Tuesday。\r\n一个机遇使得两人相遇。她们希望歌唱，她们希望放声。如果是两个人一起的话，她们觉得就能做到。\r\n她们也许只会掀起微小波澜，但这微小的波澜却可能会化作巨浪...</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5422BFD9ED1C5D5F50E978#第02集$MOE5422BFD9ED1C5D5F50E97B#第03集$MOE5422BFD9ED1C5D5F50E97A#第04集$MOE5422BFD9ED1C5D5F50E97D#第05集$MOE5422BFD9ED1C5D5F50E97C#第06集$MOE5422BFD9ED1C5D5F50E97F#第07集$MOE5422BFD9ED1C5D5F50E97E#第08集$MOE5422BFD9ED1C5D5F50E971#第09集$MOE5422BFD9ED1C5D5F50E970#第10集$MOE5422BFD9ED1C5D5F50E879#第11集$MOE5422BFD9ED1C5D5F50E878#第12集$MOE5422BFD9ED1C5D5F50E87B#第13集$MOE5422BFD9ED1C5D5F50E87A#第14集$MOE5422BFD9ED1C5D5F50E87D#第15集$MOE5422BFD9ED1C5D5F50E87C#第16集$MOE5422BFD9ED1C5D5F50E87F#第17集$MOE5422BFD9ED1C5D5F50E87E#第18集$MOE5422BFD9ED1C5D5F50E871#第19集$MOE5422BFD9ED1C5D5F50E870#第20集$MOE5422BFD9ED1C5D5F50EB79#第21集$MOE5422BFD9ED1C5D5F50EB78#第22集$MOE5422BFD9ED1C5D5F50EB7B#第23集$MOE5422BFD9ED1C5D5F50EB7A#第24集$MOE5422BFD9ED1C5D5F50EB7D$$$第01集$id_XS5422BFD9ED1C5D5F50E978#第02集$id_XS5422BFD9ED1C5D5F50E97B#第03集$id_XS5422BFD9ED1C5D5F50E97A#第04集$id_XS5422BFD9ED1C5D5F50E97D#第05集$id_XS5422BFD9ED1C5D5F50E97C#第06集$id_XS5422BFD9ED1C5D5F50E97F#第07集$id_XS5422BFD9ED1C5D5F50E97E#第08集$id_XS5422BFD9ED1C5D5F