INSERT INTO `mac_vod` VALUES (853, 1, 0, 0, 'One Room', 'One Room（2017）', 'OneRoom', 1, 'O', '', '2407a8c4', '泡面,日常', 'http://i0.hdslb.com/bfs/bangumi/e29fe9d62d02f153db7237f748c5b296e5da4a71.jpg', '', '', '', '市道真央 / 村川梨衣 / 三森铃子', '松本浩树', '', '', '《One Room》是由台风Graphics制作的第一人称视角原创短篇动画作品，于2017年1月11日播出。', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.7, 0, 0, 1736829127, 1736787906, 0, 0, 0, 0, 0.0, '', '854,855', '', '', '', '', '', '', '', '<p>《One Room》是由台风Graphics制作的第一人称视角原创短篇动画作品，于2017年1月11日播出。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0323BC8FE8110E0D50E978#第02集$MOE0323BC8FE8110E0D50E97B#第03集$MOE0323BC8FE8110E0D50E97A#第04集$MOE0323BC8FE8110E0D50E97D#第05集$MOE0323BC8FE8110E0D50E97C#第06集$MOE0323BC8FE8110E0D50E97F#第07集$MOE0323BC8FE8110E0D50E97E#第08集$MOE0323BC8FE8110E0D50E971#第09集$MOE0323BC8FE8110E0D50E970#第10集$MOE0323BC8FE8110E0D50E879#第11集$MOE0323BC8FE8110E0D50E878#第12集$MOE0323BC8FE8110E0D50E87B#OVA$MOE0323BC8FE8110E0D50E87A$$$第01集$id_XS0323BC8FE8110E0D50E978#第02集$id_XS0323BC8FE8110E0D50E97B#第03集$id_XS0323BC8FE8110E0D50E97A#第04集$id_XS0323BC8FE8110E0D50E97D#第05集$id_XS0323BC8FE8110E0D50E97C#第06集$id_XS0323BC8FE8110E0D50E97F#第07集$id_XS0323BC8FE8110E0D50E97E#第08集$id_XS0323BC8FE8110E0D50E971#第09集$id_XS0323BC8FE8110E0D50E970#第10集$id_XS0323BC8FE8110E0D50E879#第11集$id_XS0323BC8FE8110E0D50E878#第12集$id_XS0323BC8FE8110E0D50E87B#OVA$id_XS0323BC8FE8110E0D50E87A$$$第01集$id_MOE0323BC8FE8110E0D50E978#第02集$id_MOE0323BC8FE8110E0D50E97B#第03集$id_MOE0323BC8FE8110E0D50E97A#第04集$id_MOE0323BC8FE8110E0D50E97D#第05集$id_MOE0323BC8FE8110E0D50E97C#第06集$id_MOE0323BC8FE8110E0D50E97F#第07集$id_MOE0323BC8FE8110E0D50E97E#第08集$id_MOE0323BC8FE8110E0D50E971#第09集$id_MOE0323BC8FE8110E0D50E970#第10集$id_MOE0323BC8FE8110E0D50E879#第11集$id_MOE0323BC8FE8110E0D50E878#第12集$id_MOE0323BC8FE8110E0D50E87B#OVA$id_MOE0323BC8FE8110E0D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (854, 1, 0, 0, 'One Room 第二季', 'One Room セカンドシーズン（2018）', 'OneRoomdierji', 1, 'O', '', '1b0434fb', '恋爱,萌系,原创,治愈', 'http://i0.hdslb.com/bfs/bangumi/cc27b47f07d14e3de0f6f7d60ede625fb9ae9727.png', '', '', '', '高桥李依 / 水濑祈 / 市道真央', '上田慎一郎', '', '', '《One Room》的舞台，发生在“主角（One）的居室（Room）”当中。观众们将会跟三位少女轮番邂逅，并跟三位少女展开一段以主角的居室为中心的故事。', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 9.8, 0, 0, 1736829297, 1736787911, 0, 0, 0, 0, 0.0, '', '855', '', '', '', '', '', '', '', '<p>《One Room》的舞台，发生在“主角（One）的居室（Room）”当中。观众们将会跟三位少女轮番邂逅，并跟三位少女展开一段以主角的居室为中心的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第00集$MOE0075BC8CBA1D0B5B50E979#第01集$MOE0075BC8CBA1D0B5B50E978#第02集$MOE0075BC8CBA1D0B5B50E97B#第03集$MOE0075BC8CBA1D0B5B50E97A#第04集$MOE0075BC8CBA1D0B5B50E97D#第05集$MOE0075BC8CBA1D0B5B50E97C#第06集$MOE0075BC8CBA1D0B5B50E97F#第07集$MOE0075BC8CBA1D0B5B50E97E#第08集$MOE0075BC8CBA1D0B5B50E971#第09集$MOE0075BC8CBA1D0B5B50E970#第10集$MOE0075BC8CBA1D0B5B50E879#第11集$MOE0075BC8CBA1D0B5B50E878#第12集$MOE0075BC8CBA1D0B5B50E87B#OVA$MOE0075BC8CBA1D0B5B50E87A$$$第00集$id_XS0075BC8CBA1D0B5B50E979#第01集$id_XS0075BC8CBA1D0B5B50E978#第02集$id_XS0075BC8CBA1D0B5B50E97B#第03集$id_XS0075BC8CBA1D0B5B50E97A#第04集$id_XS0075BC8CBA1D0B5B50E97D#第05集$id_XS0075BC8CBA1D0B5B50E97C#第06集$id_XS0075BC8CBA1D0B5B50E97F#第07集$id_XS0075BC8CBA1D0B5B50E97E#第08集$id_XS0075BC8CBA1D0B5B50E971#第09集$id_XS0075BC8CBA1D0B5B50E970#第10集$id_XS0075BC8CBA1D0B5B50E879#第11集$id_XS0075BC8CBA1D0B5B50E878#第12集$id_XS0075BC8CBA1D0B5B50E87B#OVA$id_XS0075BC8CBA1D0B5B50E87A$$$第00集$id_MOE0075BC8CBA1D0B5B50E979#第01集$id_MOE0075BC8CBA1D0B5B50E978#第02集$id_MOE0075BC8CBA1D0B5B50E97B#第03集$id_MOE0075BC8CBA1D0B5B50E97A#第04集$id_MOE0075BC8CBA1D0B5B50E97D#第05集$id_MOE0075BC8CBA1D0B5B50E97C#第06集$id_MOE0075BC8CBA1D0B5B50E97F#第07集$id_MOE0075BC8CBA1D0B5B50E97E#第08集$id_MOE0075BC8CBA1D0B5B50E971#第09集$id_MOE0075BC8CBA1D0B5B50E970#第10集$id_MOE0075BC8CBA1D0B5B50E879#第11集$id_MOE0075BC8CBA1D0B5B