INSERT INTO `mac_vod` VALUES (855, 1, 0, 0, 'One Room 第三季', 'One Room サードシーズン（2020）', 'OneRoomdisanji', 1, 'O', '', '561a97a9', '日常,恋爱,治愈,泡面', 'http://i0.hdslb.com/bfs/bangumi/image/2f5f1903ca9e30cb85efd51d341c29f11ea207b3.png', '', '', '', '市道真央 / 村川梨衣 / 高桥李依 / 富田美忧 / 花守由美里', '谷拓也', '', '', '《One Room》的舞台，发生在“主角（One）的居室（Room）”当中。以第一视角和性格各异的女孩子们相处的故事！', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.8, 0, 0, 1736831022, 1736787917, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《One Room》的舞台，发生在“主角（One）的居室（Room）”当中。以第一视角和性格各异的女孩子们相处的故事！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0421BDD9B01E0C0050E978#第02集$MOE0421BDD9B01E0C0050E97B#第03集$MOE0421BDD9B01E0C0050E97A#第04集$MOE0421BDD9B01E0C0050E97D#第05集$MOE0421BDD9B01E0C0050E97C#第06集$MOE0421BDD9B01E0C0050E97F#第07集$MOE0421BDD9B01E0C0050E97E#第08集$MOE0421BDD9B01E0C0050E971#第09集$MOE0421BDD9B01E0C0050E970#第10集$MOE0421BDD9B01E0C0050E879#第11集$MOE0421BDD9B01E0C0050E878#第12集$MOE0421BDD9B01E0C0050E87B$$$第01集$id_XS0421BDD9B01E0C0050E978#第02集$id_XS0421BDD9B01E0C0050E97B#第03集$id_XS0421BDD9B01E0C0050E97A#第04集$id_XS0421BDD9B01E0C0050E97D#第05集$id_XS0421BDD9B01E0C0050E97C#第06集$id_XS0421BDD9B01E0C0050E97F#第07集$id_XS0421BDD9B01E0C0050E97E#第08集$id_XS0421BDD9B01E0C0050E971#第09集$id_XS0421BDD9B01E0C0050E970#第10集$id_XS0421BDD9B01E0C0050E879#第11集$id_XS0421BDD9B01E0C0050E878#第12集$id_XS0421BDD9B01E0C0050E87B$$$第01集$id_MOE0421BDD9B01E0C0050E978#第02集$id_MOE0421BDD9B01E0C0050E97B#第03集$id_MOE0421BDD9B01E0C0050E97A#第04集$id_MOE0421BDD9B01E0C0050E97D#第05集$id_MOE0421BDD9B01E0C0050E97C#第06集$id_MOE0421BDD9B01E0C0050E97F#第07集$id_MOE0421BDD9B01E0C0050E97E#第08集$id_MOE0421BDD9B01E0C0050E971#第09集$id_MOE0421BDD9B01E0C0050E970#第10集$id_MOE0421BDD9B01E0C0050E879#第11集$id_MOE0421BDD9B01E0C0050E878#第12集$id_MOE0421BDD9B01E0C0050E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (856, 1, 0, 0, '重来吧，魔王大人！', '魔王様、リトライ!（2019）', 'zhonglaibamowangdaren', 1, 'Z', '', 'f1648a6d', '小说改,奇幻,魔法,穿越', 'http://i0.hdslb.com/bfs/bangumi/6dc385fee54865a0bd673ecfbb711997fffffd6c.png', '', '', '', '津田健次郎 / 高尾奏音 / 石原夏织 / 户松遥 / 丰崎爱生 / 佐藤利奈 / 生天目仁美 / 德井青空 / 森久保祥太郎 / 久保由利香 / 荒浪和沙 / 木下铃奈 / 樱咲千依 / 市道真央 / 关智一 / 斋藤千和', '木村宽', '', '', '大野晶在登录着自己运营的游戏当中的最终BOSS“魔王·九内伯斗”的账号时， 突然被转移到了异世界中。\r\n他与在那里遇到的腿脚不便的少女一起开始旅行，但周边的人们不会把拥有压倒性力量的“魔王”这一存在放任', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 8.3, 0, 0, 1736841012, 1736787964, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>大野晶在登录着自己运营的游戏当中的最终BOSS“魔王·九内伯斗”的账号时， 突然被转移到了异世界中。\r\n他与在那里遇到的腿脚不便的少女一起开始旅行，但周边的人们不会把拥有压倒性力量的“魔王”这一存在放任不管。\r\n他被意图讨伐魔王的国家和圣女所盯上，一行人在旅途中不断引发了各种骚动……！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5726BA8CB1485B5D50E978#第02集$MOE5726BA8CB1485B5D50E97B#第03集$MOE5726BA8CB1485B5D50E97A#第04集$MOE5726BA8CB1485B5D50E97D#第05集$MOE5726BA8CB1485B5D50E97C#第06集$MOE5726BA8CB1485B5D50E97F#第07集$MOE5726BA8CB1485B5D50E97E#第08集$MOE5726BA8CB1485B5D50E971#第09集$MOE5726BA8CB1485B5D50E970#第10集$MOE5726BA8CB1485B5D50E879#第11集$MOE5726BA8CB1485B5D50E878#第12集$MOE5726BA8CB1485B5D50E87B$$$第01集$id_XS5726BA8CB1485B5D50E978#第02集$id_XS5726BA8CB1485B5D50E97B#第03集$id_XS5726BA8CB1485B5D50E97A#第04集$id_XS5726BA8CB1485B5D50E97D#第05集$id_XS5726BA8CB1485B5D50E97C#第06集$id_XS5726BA8CB1485B5D50E97F#第07集$id_XS5726BA8CB1485B5D50E97E#第08集$id_XS5726BA8CB1485B5D50E971#第09集$id_XS5726BA8CB1485B5D50E970#第10集$id_XS5726BA8CB1485B5D50E879#第11集$id_XS5726BA8CB1485B5D50E878#第12集$id_XS5726BA8CB1485B5D50E87B$$$第01集$id_MOE5726BA8CB1485B5D50E978#第02集$id_MOE5726BA8CB1485B5D50E97B#第03集$id_MOE5726BA8CB1485B5D50E97A#第04集$id_MOE5726BA8CB1485B5D50E97D#第05集$id_MOE5726BA8CB1485B5D50E97C#第06集$id_MOE5726BA8CB1485B5D50E97F#第07集$id_MOE5726BA8CB1485B5D50E97E#第08集$id_MOE5726BA8CB1485B5D50E971#第09集$id_MOE5726BA8CB1485B5D50E970#第10集$id_MOE5726BA8CB1485B5D50E879#第11集$