INSERT INTO `mac_vod` VALUES (879, 1, 0, 0, '街角魔族 第二季', 'まちカドまぞく 2丁目（2022）', 'jiejiaomozudierji', 1, 'J', '', 'b40f1a41', '漫画改,日常,萌系,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/a29f3b00a94d1b4a029054f72963cc10d98bae99.jpg', '', '', '', '小原好美 / 鬼头明里 / 高桥未奈美 / 高柳知叶 / 千本木彩花 / 诹访彩花 / 大和田仁美 / 大原沙耶香 / 伊藤彩沙 / 松山鹰志', '樱井弘明 / 则座诚 / 安藤良 / 深濑重 / 田中瑛 / 海宝兴藏 / 野上良之 / 堀内直树 / 羽多野浩平', '', '', '超人气小镇日常奇幻故事回来啦！\r\n自身魔族的力量苏醒之后，为了解除暗之一族的封印，主人公夏美子尽管实力微弱却依然奋斗着。\r\n魔法少女桃原本应是她的对手，但不知为何她们却开始互相协助，一起追寻消失在镇上的魔', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.9, 0, 0, 1737139870, 1737113166, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>超人气小镇日常奇幻故事回来啦！\r\n自身魔族的力量苏醒之后，为了解除暗之一族的封印，主人公夏美子尽管实力微弱却依然奋斗着。\r\n魔法少女桃原本应是她的对手，但不知为何她们却开始互相协助，一起追寻消失在镇上的魔法少女身上的谜团…\r\n而藏在镇里的新魔族也将出场，夏美子等人的未来究竟会如何呢——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5323BCDEB848590850E978#第02集$MOE5323BCDEB848590850E97B#第03集$MOE5323BCDEB848590850E97A#第04集$MOE5323BCDEB848590850E97D#第05集$MOE5323BCDEB848590850E97C#第06集$MOE5323BCDEB848590850E97F#第07集$MOE5323BCDEB848590850E97E#第08集$MOE5323BCDEB848590850E971#第09集$MOE5323BCDEB848590850E970#第10集$MOE5323BCDEB848590850E879#第11集$MOE5323BCDEB848590850E878#第12集$MOE5323BCDEB848590850E87B$$$第01集$id_XS5323BCDEB848590850E978#第02集$id_XS5323BCDEB848590850E97B#第03集$id_XS5323BCDEB848590850E97A#第04集$id_XS5323BCDEB848590850E97D#第05集$id_XS5323BCDEB848590850E97C#第06集$id_XS5323BCDEB848590850E97F#第07集$id_XS5323BCDEB848590850E97E#第08集$id_XS5323BCDEB848590850E971#第09集$id_XS5323BCDEB848590850E970#第10集$id_XS5323BCDEB848590850E879#第11集$id_XS5323BCDEB848590850E878#第12集$id_XS5323BCDEB848590850E87B$$$第01集$id_MOE5323BCDEB848590850E978#第02集$id_MOE5323BCDEB848590850E97B#第03集$id_MOE5323BCDEB848590850E97A#第04集$id_MOE5323BCDEB848590850E97D#第05集$id_MOE5323BCDEB848590850E97C#第06集$id_MOE5323BCDEB848590850E97F#第07集$id_MOE5323BCDEB848590850E97E#第08集$id_MOE5323BCDEB848590850E971#第09集$id_MOE5323BCDEB848590850E970#第10集$id_MOE5323BCD