INSERT INTO `mac_vod` VALUES (882, 1, 0, 0, 'Love Live! School Idol Project', 'ラブライブ! School idol project（2013）', 'LoveLiveSchoolIdolProject', 1, 'L', '', '63b58809', '校园,音乐,偶像,社团', 'https://i0.hdslb.com/bfs/bangumi/133030604f6d68986249fe34ba909c800eb685d5.jpg', '', '', '', '新田惠海 / 南条爱乃 / 内田彩 / 饭田里穗 / 楠田亚衣奈 / 三森铃子 / 久保由利香 / 德井青空 / 堀绘梨子', '京极尚彦', '', '', '【本字幕由LoveEcho!字幕组协力译制】位于东京都千代田区的传统高校“音乃木阪学院”，因为入读的学生人数骤减，所以正面临着废校的危机。其中九位少女为了保护她们喜爱的学校而决定成为偶像，因为只要她们', '全13集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.7, 0, 0, 1737199645, 1737140120, 0, 0, 0, 0, 0.0, '', '883', '', '', '', '', '', '', '', '<p>【本字幕由LoveEcho!字幕组协力译制】位于东京都千代田区的传统高校“音乃木阪学院”，因为入读的学生人数骤减，所以正面临着废校的危机。其中九位少女为了保护她们喜爱的学校而决定成为偶像，因为只要她们成为偶像，学校的名气便会増加，而入读学生的人数也会随之上升。就这样，九位个性鲜明的少女开始朝着她们的偶像之路而努力迈进了！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0724EE8DB1115D0050E978#第02集$MOE0724EE8DB1115D0050E97B#第03集$MOE0724EE8DB1115D0050E97A#第04集$MOE0724EE8DB1115D0050E97D#第05集$MOE0724EE8DB1115D0050E97C#第06集$MOE0724EE8DB1115D0050E97F#第07集$MOE0724EE8DB1115D0050E97E#第08集$MOE0724EE8DB1115D0050E971#第09集$MOE0724EE8DB1115D0050E970#第10集$MOE0724EE8DB1115D0050E879#第11集$MOE0724EE8DB1115D0050E878#第12集$MOE0724EE8DB1115D0050E87B#第13集$MOE0724EE8DB1115D0050E87A$$$第01集$id_XS0724EE8DB1115D0050E978#第02集$id_XS0724EE8DB1115D0050E97B#第03集$id_XS0724EE8DB1115D0050E97A#第04集$id_XS0724EE8DB1115D0050E97D#第05集$id_XS0724EE8DB1115D0050E97C#第06集$id_XS0724EE8DB1115D0050E97F#第07集$id_XS0724EE8DB1115D0050E97E#第08集$id_XS0724EE8DB1115D0050E971#第09集$id_XS0724EE8DB1115D0050E970#第10集$id_XS0724EE8DB1115D0050E879#第11集$id_XS0724EE8DB1115D0050E878#第12集$id_XS0724EE8DB1115D0050E87B#第13集$id_XS0724EE8DB1115D0050E87A$$$第01集$id_MOE0724EE8DB1115D0050E978#第02集$id_MOE0724EE8DB1115D0050E97B#第03集$id_MOE0724EE8DB1115D0050E97A#第04集$id_MOE0724EE8DB1115D0050E97D#第05集$id_MOE0724EE8DB1115D0050E97C#第06集$id_MOE0724EE8DB1115D0050E97F#第07集$id_MOE0724EE8DB1115D0050E97E#第08集$id_MOE0724EE8DB1115D0050E971#第09集$id_MOE0724EE8DB1115D0050E970#第10集$id_MOE0724EE8DB1115D0050E879#第11集$id_MOE0724EE8DB1115D0050E878#第12集$id_MOE0724EE8DB1115D0050E87B#第13集$id_MOE0724EE8DB1115D0050E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (883, 1, 0, 0, 'Love Live! School Idol Project（第二季）', 'ラブライブ! School idol project 第2期（2014）', 'LoveLiveSchoolIdolProjectdierji', 1, 'L', '', 'a06d02a2', '校园,音乐,偶像,社团', 'https://i0.hdslb.com/bfs/bangumi/1180c222b427a3171faae1245c46a6452f14bdee.jpg', '', '', '', '新田惠海 / 内田彩 / 三森铃子 / 南条爱乃 / 楠田亚衣奈 / 堀绘梨子 / 饭田里穗 / 久保由利香 / 德井青空', '京极尚彦', '', '', '【本字幕由LoveEcho!字幕组协力译制】在秋叶原，神田和神保町这三条街上的传统学校，音乃木坂学园正面临着废校的大危机。\r\n面对学校的危机，以二年生高坂穗乃果为中心的九位女生站了出来。\r\n为了保护我们最', '全13集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.8, 0, 0, 1737199664, 1737140132, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本字幕由LoveEcho!字幕组协力译制】在秋叶原，神田和神保町这三条街上的传统学校，音乃木坂学园正面临着废校的大危机。\r\n面对学校的危机，以二年生高坂穗乃果为中心的九位女生站了出来。\r\n为了保护我们最喜欢的学校，我们能做的事情……。就是，成为偶像！\r\n通过成为学院偶像向外宣传学校，增加学生人数！从这里开始，她们实现梦想的故事开始了！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5027BADCB91B0C0B50E978#第02集$MOE5027BADCB91B0C0B50E97B#第03集$MOE5027BADCB91B0C0B50E97A#第04集$MOE5027BADCB91B0C0B50E97D#第05集$MOE5027BADCB91B0C0B50E97C#第06集$MOE5027BADCB91B0C0B50E97F#第07集$MOE5027BADCB91B0C0B50E97E#第08集$MOE5027BADCB91B0C0B50E971#第09集$MOE5027BADCB91B0C0B50E970#第10集$MOE5027BADCB91B0C0B50E879#第11集$MOE5027BADCB91B0C0B50E878#第12集$MOE5027BADCB91B0C0B50E87B#第13集$MOE5027BADCB91B0C0B50E87A$$$第01集$id_XS5027BADCB91B0C0B50E978#第02集$id_XS5027BADCB91B0C0B50E97B#第03集$id_XS5027BADCB91B0C0B50E97A#第04集$id_XS5027BADCB91B0C0B50E97D#第05集$id_XS5027BADCB91B0C0B50E97C#第06集$id_XS5027BADCB91B0C0B50E97F#第07集$id_XS5027BADCB91B0C0B50E97E#第08集$id_XS5027BADCB91B0C0B50E971#第09集$id_XS5027BADCB91B0C0B50E970#第10集$id_XS5027BADCB91B0C0B50E879#第11集$id_XS5027BADCB91B0C0B50E878#第12集$id_XS5027BADCB91B0C0B50E87B#第13集$id_XS5027BADCB91B0C0B50E87A$$$第01集$id_MOE5027BADCB91B0C0B50E978#第02集$id_MOE5027BADCB91B0C0B50E97B#第03集$id_MOE5027BADCB91B0C0B50E97A#第04集$id_MOE5027BADCB91B0C0B50E97D#第05集$id_MOE5027BADCB91B0C0B50E97C#第06集$id_MOE5027BADCB91B0C0B50E97F#第07集$id_MOE5027BADCB91B0C0B50E97E#第08集$id_