INSERT INTO `mac_vod` VALUES (893, 1, 0, 0, '我们无法一起学习', 'ぼくたちは勉強ができない（2019）', 'womenwufayiqixuexi', 1, 'W', '', '6bb290ab', '漫画改,日常,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/7625ac0a9409923bd3b285a978aeba04db4fd406.png', '', '', '', '逢坂良太 / 白石晴香 / 富田美忧 / 铃代纱弓 / Lynn / 朝日奈丸佳', '岩崎良明', '', '', '刻苦学习的高中3年生·唯我成幸，为了获得免除大学学费的“特别VIP推荐”资格，而要去担任为备考而苦战的同级生们的教育指导员。教导的对象是“文学之森的睡美人”古桥文乃和“机关精巧的拇指姑娘”绪方理珠这两', '全13集 OAD', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 9.2, 0, 0, 1737268212, 1737200478, 0, 0, 0, 0, 0.0, '', '895', '', '', '', '', '', '', '', '<p>刻苦学习的高中3年生·唯我成幸，为了获得免除大学学费的“特别VIP推荐”资格，而要去担任为备考而苦战的同级生们的教育指导员。教导的对象是“文学之森的睡美人”古桥文乃和“机关精巧的拇指姑娘”绪方理珠这两位学园顶尖的天才美少女！原本以为她们的学习能力完美无缺，没想到对于不擅长的学科却完全无能……！？成幸一边被充满个性的“学不来女孩”们玩弄于股掌之间，一边为了让她们努力通过大学考试！无论学习还是恋爱都“学不来”的天才们的恋爱喜剧，就此开幕！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775EE8AB0190C5B50E978#第02集$MOE0775EE8AB0190C5B50E97B#第03集$MOE0775EE8AB0190C5B50E97A#第04集$MOE0775EE8AB0190C5B50E97D#第05集$MOE0775EE8AB0190C5B50E97C#第06集$MOE0775EE8AB0190C5B50E97F#第07集$MOE0775EE8AB0190C5B50E97E#第08集$MOE0775EE8AB0190C5B50E971#第09集$MOE0775EE8AB0190C5B50E970#第10集$MOE0775EE8AB0190C5B50E879#第11集$MOE0775EE8AB0190C5B50E878#第12集$MOE0775EE8AB0190C5B50E87B#第13集$MOE0775EE8AB0190C5B50E87A#OAD$MOE0775EE8AB0190C5B50E87D$$$第01集$id_XS0775EE8AB0190C5B50E978#第02集$id_XS0775EE8AB0190C5B50E97B#第03集$id_XS0775EE8AB0190C5B50E97A#第04集$id_XS0775EE8AB0190C5B50E97D#第05集$id_XS0775EE8AB0190C5B50E97C#第06集$id_XS0775EE8AB0190C5B50E97F#第07集$id_XS0775EE8AB0190C5B50E97E#第08集$id_XS0775EE8AB0190C5B50E971#第09集$id_XS0775EE8AB0190C5B50E970#第10集$id_XS0775EE8AB0190C5B50E879#第11集$id_XS0775EE8AB0190C5B50E878#第12集$id_XS0775EE8AB0190C5B50E87B#第13集$id_XS0775EE8AB0190C5B50E87A#OAD$id_XS0775EE8AB0190C5B50E87D$$$第01集$id_MOE0775EE8AB0190C5B50E978#第02集$id_MOE0775EE8AB0190C5B50E97B#第03集$id_MOE0775EE8AB0190C5B50E97A#第04集$id_MOE0775EE8AB0190C5B50E97D#第05集$id_MOE0775EE8AB0190C5B50E97C#第06集$id_MOE0775EE8AB0190C5B50E97F#第07集$id_MOE0775EE8AB0190C5B50E97E#第08集$id_MOE0775EE8AB0190C5B50E971#第09集$id_MOE0775EE8AB0190C5B50E970#第10集$id_MOE0775EE8AB0190C5B50E879#第11集$id_MOE0775EE8AB0190C5B50E878#第12集$id_MOE0775EE8AB0190C5B50E87B#第13集$id_MOE0775EE8AB0190C5B50E87A#OAD$id_MOE0775EE8AB0190C5B50E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (894, 1, 0, 0, '嘻嘻嘻嘻吸血鬼', 'ババンババンバンバンパイア（2025）', 'xixixixixixuegui', 1, 'X', '', '83b4ffb0', '漫画改,奇幻,日常,搞笑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2915724530.webp', '', '', '', '浪川大辅 / 小林裕介 / 风间万裕子 / 八代拓 / 小西克幸 / 关根明良 / 中村悠一', '川崎逸朗', '', '', '森兰丸——一位对食物追求极致的吸血鬼，只为了完美的18岁处男血的口感不惜忍辱负重潜伏在澡堂打工10年。', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 101, 0, 101, 101, '', 0, 0, 6.1, 0, 0, 1743754187, 1737243825, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>森兰丸——一位对食物追求极致的吸血鬼，只为了完美的18岁处男血的口感不惜忍辱负重潜伏在澡堂打工10年。 只剩3年将要得偿所愿，但现在已经有点难以忍耐了！！怎么办！！难道10年来的坚持就要毁于一旦了吗？难道将要打破自己一直追求的信念吗？ 不！要忍耐！ 但是，他为什么告诉我他有喜欢的人了啊啊啊啊啊？？！！明明我都在拼命忍耐了！为什么你却担上了稍不注意就会被吃干抹净的危险！不行！在我把他吃掉之前......他的童贞由我来守护！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0924EE8CEF4F0F0950E978#第02集$MOE0924EE8CEF4F0F0950E97B#第03集$MOE0924EE8CEF4F0F0950E97A#第04集$MOE0924EE8CEF4F0F0950E97D#第05集$MOE0924EE8CEF4F0F0950E97C#第06集$MOE0924EE8CEF4F0F0950E97F#第07集$MOE0924EE8CEF4F0F0950E97E#第08集$MOE0924EE8CEF4F0F0950E971#第09集$MOE0924EE8CEF4F0F0950E970#第10集$MOE0924EE8CEF4F0F0950E879#第11集$MOE0924EE8CEF4F0F0950E878#第12集$MOE0924EE8CEF4F0F0950E87B$$$第01集$id_XS0924EE8CEF4F0F0950E978#第02集$id_XS0924EE8CEF4F0F0950E97B#第03集$id_XS0924EE8CEF4F0F0950E97A#第04集$id_XS0924EE8CEF4F0F0950E97D#第05集$id_XS0924EE8CEF4F0F0950E97C#第06集$id_XS0924EE8CEF4F0F0950E97F#第07集$id_XS0924EE8CEF4F0F0950E97E#第08集$id_XS0924EE8CEF4F0F0950E971#第09集$id_XS0924EE8CEF4F0F0950E970#第10集$id_XS0924EE8CEF4F0F0950E879#第11集$id_XS0924EE8CEF4F0F0950E878#第12集$id_XS0924EE8CEF4F0F0950E87B$$$第01集$id_MOE0924EE8CEF4F0F0950E978#第02集$id_MOE0924EE8CEF4F0F0950E97B#第03集$id_MOE0924EE8CEF4F0F0950E97A#第04集$id_MOE0924EE8CEF4F0F0950E97D#第05集$id_MOE0924EE8CEF4F0F0950E97C#第06集$id_MOE0924EE8CEF4F0F0950E97F#第07集$id_MOE0924EE8CEF4F0F0950E97E#第08集$id_MOE0924EE8CEF4F0F0950E971#第09集$id_MOE0924EE8CEF4F0F0950E970#第10集$id_MOE0924EE8CEF4F0F0950E879#第11集$id_MOE0924EE8CEF4F0F0950E878#第12集$id_MOE0924EE8CEF4F0