INSERT INTO `mac_vod` VALUES (897, 1, 0, 0, 'Just Because!', '仅仅因为（2017）', 'JustBecause', 1, 'J', '', 'e86d5898', '恋爱,原创,校园', 'http://i0.hdslb.com/bfs/bangumi/6194f3436d4447a0d6aef90c87013db8daf57605.jpg', '', '', '', '市川苍 / 矶部花凛 / 村田太志 / 芳野由奈 / Lynn / 樱庭有纱 / 贯井柚佳 / 近藤玲奈 / 千本木彩花 / 天崎滉平 / 山本祥太 / 柳田淳一 / 小林大纪 / 大川透', '小林敦 / 林直孝 / 米田光宏 / 古贺一臣 / 川畑荣郎 / 高村雄太 / 室谷靖 / 村上勉 / 三浦慧 / 羽多野浩平 / 野木森达哉 / 佐佐木纯人 / 须之内佑典', '', '', '高中三年级的冬天、剩下没多久的高中生活，大家都认为会在毫无变化的情况下迎来毕业之日……但在某一天，他突然回来了，在中学时搬到遥远城镇的同学，变成不合时节的转学生再次相会，伴随着某种不确定的感情、转变开', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 3, 9, 9, '', 0, 0, 9.5, 0, 0, 1737350680, 1737293951, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高中三年级的冬天、剩下没多久的高中生活，大家都认为会在毫无变化的情况下迎来毕业之日……但在某一天，他突然回来了，在中学时搬到遥远城镇的同学，变成不合时节的转学生再次相会，伴随着某种不确定的感情、转变开始的信号微弱的发出了声响……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE542FBADCBC11540150E978#第02集$MOE542FBADCBC11540150E97B#第03集$MOE542FBADCBC11540150E97A#第04集$MOE542FBADCBC11540150E97D#第05集$MOE542FBADCBC11540150E97C#第06集$MOE542FBADCBC11540150E97F#第07集$MOE542FBADCBC11540150E97E#第08集$MOE542FBADCBC11540150E971#第09集$MOE542FBADCBC11540150E970#第10集$MOE542FBADCBC11540150E879#第11集$MOE542FBADCBC11540150E878#第12集$MOE542FBADCBC11540150E87B$$$第01集$id_XS542FBADCBC11540150E978#第02集$id_XS542FBADCBC11540150E97B#第03集$id_XS542FBADCBC11540150E97A#第04集$id_XS542FBADCBC11540150E97D#第05集$id_XS542FBADCBC11540150E97C#第06集$id_XS542FBADCBC11540150E97F#第07集$id_XS542FBADCBC11540150E97E#第08集$id_XS542FBADCBC11540150E971#第09集$id_XS542FBADCBC11540150E970#第10集$id_XS542FBADCBC11540150E879#第11集$id_XS542FBADCBC11540150E878#第12集$id_XS542FBADCBC11540150E87B$$$第01集$id_MOE542FBADCBC11540150E978#第02集$id_MOE542FBADCBC11540150E97B#第03集$id_MOE542FBADCBC11540150E97A#第04集$id_MOE542FBADCBC11540150E97D#第05集$id_MOE542FBADCBC11540150E97C#第06集$id_MOE542FBADCBC11540150E97F#第07集$id_MOE542FBADCBC11540150E97E#第08集$id_MOE542FBADCBC11540150E971#第09集$id_MOE542FBADCBC11540150E970#第10集$id_MOE542FBADCBC115401