INSERT INTO `mac_vod` VALUES (899, 1, 0, 0, '无头骑士异闻录', 'デュラララ!!（2010）', 'wutouqishiyiwenlu', 1, 'W', '', 'cda56e18', '奇幻,日常,声控,小说改', 'http://i0.hdslb.com/bfs/bangumi/446c6c7e1806c0debbc3e40ba2e9d9dd00cb4a08.jpg', '', '', '', '丰永利行 / 宫野真守 / 花泽香菜 / 神谷浩史 / 小野大辅 / 福山润 / 中村悠一 / 梶裕贵 / 高垣彩阳 / 堀江一真 / 小林沙苗 / 黑田崇矢 / 泽城美雪', '大森贵弘 / 川面真也 / 山崎光惠 / 八濑祐树 / 古谷田顺久 / 市村彻夫 / 松田清 / 山本天志', '', '', '《无头骑士异闻录 DuRaRaRa!!》是由日本小说家成田良悟所写的轻小说作品，日文版由电击文库出版，中文版则由台湾角川出版、港澳地区由香港角川洲立代理销售。小说由ヤスダスズヒト（安田典生）作插画。以', '全25集', '', 0, '0', '', '', '日本', '日语', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 9.7, 0, 0, 1737371208, 1737294261, 0, 0, 0, 0, 0.0, '', '900', '', '', '', '', '', '', '', '<p>《无头骑士异闻录 DuRaRaRa!!》是由日本小说家成田良悟所写的轻小说作品，日文版由电击文库出版，中文版则由台湾角川出版、港澳地区由香港角川洲立代理销售。小说由ヤスダスズヒト（安田典生）作插画。以池袋为舞台，一个以向往非日常的少年、爱找碴的小混混、跟踪狂的电波系少女、以作情报贩子“为乐”的青年、专接不寻常病患的密医、迷上魔物的高中生以及骑着漆黑色机车的“无头骑士”等展开一连串不正常但爽快的恋爱故事。在《月刊GFantasy》2009年5月号开始漫画化并连载。2009年7月宣布动画化，2010年1月开始播放。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5273ED8DBF4C5C0150E978#第02集$MOE5273ED8DBF4C5C0150E97B#第03集$MOE5273ED8DBF4C5C0150E97A#第04集$MOE5273ED8DBF4C5C0150E97D#第05集$MOE5273ED8DBF4C5C0150E97C#第06集$MOE5273ED8DBF4C5C0150E97F#第07集$MOE5273ED8DBF4C5C0150E97E#第08集$MOE5273ED8DBF4C5C0150E971#第09集$MOE5273ED8DBF4C5C0150E970#第10集$MOE5273ED8DBF4C5C0150E879#第11集$MOE5273ED8DBF4C5C0150E878#第12集$MOE5273ED8DBF4C5C0150E87B#第12.5集$MOE5273ED8DBF4C5C0150E87A#第13集$MOE5273ED8DBF4C5C0150E87D#第14集$MOE5273ED8DBF4C5C0150E87C#第15集$MOE5273ED8DBF4C5C0150E87F#第16集$MOE5273ED8DBF4C5C0150E87E#第17集$MOE5273ED8DBF4C5C0150E871#第18集$MOE5273ED8DBF4C5C0150E870#第19集$MOE5273ED8DBF4C5C0150EB79#第20集$MOE5273ED8DBF4C5C0150EB78#第21集$MOE5273ED8DBF4C5C0150EB7B#第22集$MOE5273ED8DBF4C5C0150EB7A#第23集$MOE5273ED8DBF4C5C0150EB7D#第24集$MOE5273ED8DBF4C5C0150EB7C#第25集$MOE5273ED8DBF4C5C0150EB7F$$$第01集$id_XS5273ED8DBF4C5C0150E978#第02集$id_XS5273ED8DBF4C5C0150E97B#第03集$id_XS5273ED8DBF4C5C0150E97A#第04集$id_XS5273ED8DBF4C5C0150E97D#第05集$id_XS5273ED8DBF4C5C0150E97C#第06集$id_XS5273E