INSERT INTO `mac_vod` VALUES (901, 1, 0, 0, '超地下偶像', '地下すぎアイドル あかえちゃん（2014）', 'chaodixiaouxiang', 1, 'C', '', '2c427654', '搞笑,少女,泡面', 'http://i0.hdslb.com/bfs/bangumi/9fa6eb59d675efd2437edc92f5ccb0a0d7f021be.jpg', '', '', '', '渡部優衣 / 明坂聪美 / 渊上舞 / 山村響 / 久保ユリカ / 高橋伸也 / 高野麻里佳', '', '', '', '故事以有着众多地下偶像的六本木地下空间为舞台，众多偶像为了“地上进出”（商业出道）而努力进行着偶像活动。在这其中，人气最低的位居地下500层的5人组合“超地下公主”也每天对着鼹鼠和蚯蚓努力表演，渴望早', '全12集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 0.0, 0, 0, 1737382261, 1737372964, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事以有着众多地下偶像的六本木地下空间为舞台，众多偶像为了“地上进出”（商业出道）而努力进行着偶像活动。在这其中，人气最低的位居地下500层的5人组合“超地下公主”也每天对着鼹鼠和蚯蚓努力表演，渴望早日成为“地上的偶像”。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0374B88ABE1F580D50E978#第02集$MOE0374B88ABE1F580D50E97B#第03集$MOE0374B88ABE1F580D50E97A#第04集$MOE0374B88ABE1F580D50E97D#第05集$MOE0374B88ABE1F580D50E97C#第06集$MOE0374B88ABE1F580D50E97F#第07集$MOE0374B88ABE1F580D50E97E#第08集$MOE0374B88ABE1F580D50E971#第09集$MOE0374B88ABE1F580D50E970#第10集$MOE0374B88ABE1F580D50E879#第11集$MOE0374B88ABE1F580D50E878#第12集$MOE0374B88ABE1F580D50E87B$$$第01集$id_XS0374B88ABE1F580D50E978#第02集$id_XS0374B88ABE1F580D50E97B#第03集$id_XS0374B88ABE1F580D50E97A#第04集$id_XS0374B88ABE1F580D50E97D#第05集$id_XS0374B88ABE1F580D50E97C#第06集$id_XS0374B88ABE1F580D50E97F#第07集$id_XS0374B88ABE1F580D50E97E#第08集$id_XS0374B88ABE1F580D50E971#第09集$id_XS0374B88ABE1F580D50E970#第10集$id_XS0374B88ABE1F580D50E879#第11集$id_XS0374B88ABE1F580D50E878#第12集$id_XS0374B88ABE1F580D50E87B$$$第01集$id_MOE0374B88ABE1F580D50E978#第02集$id_MOE0374B88ABE1F580D50E97B#第03集$id_MOE0374B88ABE1F580D50E97A#第04集$id_MOE0374B88ABE1F580D50E97D#第05集$id_MOE0374B88ABE1F580D50E97C#第06集$id_MOE0374B88ABE1F580D50E97F#第07集$id_MOE0374B88ABE1F580D50E97E#第08集$id_MOE0374B88ABE1F580D50E971#第09集$id_MOE0374B88ABE1F580D50E970#第10集$id_MOE0374B88ABE1F580D50E879#第11集$id_MOE0374B88ABE1F580D50E878#第12集$id_MOE0374B88ABE1F580D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (902, 1, 0, 0, '魔卡少女樱 CLEAR CARD篇', 'カードキャプターさくら クリアカード編（2018）', 'mokashaonvyingCLEARCARDpian', 1, 'M', '', 'c7dd16c5', '少女,魔法,漫画改', 'http://i0.hdslb.com/bfs/bangumi/07245c4bf4acb03a5819762fea3210c656aba66c.jpg', '', '', '', '丹下樱 / 熊井统子 / 岩男润子 / 绪方惠美 / 久川绫 / 关智一 / 田中秀幸 / 铃木实里 / 花江夏树 / 佐佐木望 / 筱原惠美', '浅香守生 / 细川秀树 / 市村彻夫 / 菱川直树 / 筑紫大介 / 高岛大辅 / 友田政晴 / 神原敏昭 / 菊池聪延 / 加藤显 / 饭村正之 / 熨斗谷充孝', '', '', '樱集齐了会给世间带来灾难的“库洛牌”，并用魔法的力量将它们变成了自己的牌。樱花盛开的4月，小樱升入了初中1年级。而后，小樱与曾返回香港的小狼重逢，并一起开心地去往学校。某个夜里，收集的牌出现了异常……', '全22集 OAD', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.8, 0, 0, 1737463574, 1737418927, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>樱集齐了会给世间带来灾难的“库洛牌”，并用魔法的力量将它们变成了自己的牌。樱花盛开的4月，小樱升入了初中1年级。而后，小樱与曾返回香港的小狼重逢，并一起开心地去往学校。某个夜里，收集的牌出现了异常……而友枝町接连发生奇怪的事。小樱在梦中遇见的“钥匙”的指引下，再次开始收集卡片。这时，班里转来一个女孩子……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5220E8DCB81F0E0C50E978#第02集$MOE5220E8DCB81F0E0C50E97B#第03集$MOE5220E8DCB81F0E0C50E97A#第04集$MOE5220E8DCB81F0E0C50E97D#第05集$MOE5220E8DCB81F0E0C50E97C#第06集$MOE5220E8DCB81F0E0C50E97F#第07集$MOE5220E8DCB81F0E0C50E97E#第08集$MOE5220E8DCB81F0E0C50E971#第09集$MOE5220E8DCB81F0E0C50E970#第10集$MOE5220E8DCB81F0E0C50E879#第11集$MOE5220E8DCB81F0E0C50E878#第12集$MOE5220E8DCB81F0E0C50E87B#第13集$MOE5220E8DCB81F0E0C50E87A#第14集$MOE5220E8DCB81F0E0C50E87D#第15集$MOE5220E8DCB81F0E0C50E87C#第16集$MOE5220E8DCB81F0E0C50E87F#第17集$MOE5220E8DCB81F0E0C50E87E#第18集$MOE5220E8DCB81F0E0C50E871#第19集$MOE5220E8DCB81F0E0C50E870#第20集$MOE5220E8DCB81F0E0C50EB79#第21集$MOE5220E8DCB81F0E0C50EB78#第22集$MOE5220E8DCB81F0E0C50EB7B#OAD$MOE5220E8DCB81F0E0C50EB7A$$$第01集$id_XS5220E8DCB81F0E0C50E978#第02集$id_XS5220E8DCB81F0E0C50E97B#第03集$id_XS5220E8DCB81F0E0C50E97A#第04集$id_XS5220E8DCB81F0E0C50E97D#第05集$id_XS5220E8DCB81F0E0C50E97C#第06集$id_XS5220E8DCB81F0E0C50E97F#第07集$id_XS5220E8DCB81F0E0C50E97E#第08集$id_XS5220E8DCB81F0E0C50E971#第09集$id_XS5220E8DCB81F0E0C50E970#第10集$id_XS5220E8DCB81F0E0C50E879#第11集$id_