INSERT INTO `mac_vod` VALUES (911, 1, 0, 0, '只有我不存在的城市', '僕だけがいない街（2016）', 'zhiyouwobucunzaidechengshi', 1, 'Z', '', '6df615ea', '推理,治愈,催泪,穿越', 'http://i0.hdslb.com/bfs/bangumi/image/7f5c1d29ede597590cbfab7820a5096469b6030e.png', '', '', '', '土屋太凤 / 满岛真之介 / 悠木碧 / 赤崎千夏 / 大地叶 / 水岛大宙 / 高山南 / 宫本充', '伊藤智彦 / 石井俊匡 / 绵田慎也 / 鹿间贵裕 / 森大贵 / 星野真', '', '', '藤沼悟是一个三流漫画家，但是他却拥有着名为“再上映”（可以穿越到事件发生之前的时间点，阻止事件发生，但失败了会一直重复）的能力。某天，当回到家里的时候他发现了自己母亲遇害的一幕，并且自己被嫁祸为杀人凶', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 23, 0, 23, 23, '', 0, 0, 9.7, 0, 0, 1737553105, 1737470655, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>藤沼悟是一个三流漫画家，但是他却拥有着名为“再上映”（可以穿越到事件发生之前的时间点，阻止事件发生，但失败了会一直重复）的能力。某天，当回到家里的时候他发现了自己母亲遇害的一幕，并且自己被嫁祸为杀人凶手。就在这时候，由于再上映的关系，他突然回到了18年前·小学五年级的时候，而这一刻他不但要拯救母亲，也要为了同学的安全而战……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0773EA8EB81C085850E978#第02集$MOE0773EA8EB81C085850E97B#第03集$MOE0773EA8EB81C085850E97A#第04集$MOE0773EA8EB81C085850E97D#第05集$MOE0773EA8EB81C085850E97C#第06集$MOE0773EA8EB81C085850E97F#第07集$MOE0773EA8EB81C085850E97E#第08集$MOE0773EA8EB81C085850E971#第09集$MOE0773EA8EB81C085850E970#第10集$MOE0773EA8EB81C085850E879#第11集$MOE0773EA8EB81C085850E878#第12集$MOE0773EA8EB81C085850E87B$$$第01集$id_XS0773EA8EB81C085850E978#第02集$id_XS0773EA8EB81C085850E97B#第03集$id_XS0773EA8EB81C085850E97A#第04集$id_XS0773EA8EB81C085850E97D#第05集$id_XS0773EA8EB81C085850E97C#第06集$id_XS0773EA8EB81C085850E97F#第07集$id_XS0773EA8EB81C085850E97E#第08集$id_XS0773EA8EB81C085850E971#第09集$id_XS0773EA8EB81C085850E970#第10集$id_XS0773EA8EB81C085850E879#第11集$id_XS0773EA8EB81C085850E878#第12集$id_XS0773EA8EB81C085850E87B$$$第01集$id_MOE0773EA8EB81C085850E978#第02集$id_MOE0773EA8EB81C085850E97B#第03集$id_MOE0773EA8EB81C085850E97A#第04集$id_MOE0773EA8EB81C085850E97D#第05集$id_MOE0773EA8EB81C085850E97C#第06集$id_MOE0773EA8EB81C085850E97F#第07集$id_MOE0773EA8EB81C085850E97E#第08集$id_MOE0773EA8EB81C085850E971#第09集$id_MOE0773EA8EB81C085850E970#第10集$id_MOE0773EA8EB81C085850E879#第11集$id_MOE