INSERT INTO `mac_vod` VALUES (913, 1, 0, 0, '俺物语！！', 'My Love Story / Ore Monogatari（2015）', 'anwuyu', 1, 'A', '', '14c99efa', '漫画改,日常,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/image/77da71f81a9bde18d20a9b1fddaa18fe51748f25.jpg', '', '', '', '江口拓也 / 岛崎信长 / 潘惠美 / 井上喜久子 / 茅野爱衣 / 福山润 / 榎木淳弥 / 石川英郎', '浅香守生 / 渡边琴乃 / 长滨亘彦 / 细川秀树 / 渊上真 / 岛崎奈奈子 / 水本叶月 / 羽原久美子 / 田中智也', '', '', '故事主要以有着魁梧的身材和耿直的性格、深受男性们爱戴却没有女人缘的高中1年级学生刚田猛男，与温柔的少女大和凛子，以及猛男的幼时好友——帅哥砂川诚为中心展开，主要描写了他们相互的理解以及彼此的交流。', '全24集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.9, 0, 0, 1737610118, 1737470669, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事主要以有着魁梧的身材和耿直的性格、深受男性们爱戴却没有女人缘的高中1年级学生刚田猛男，与温柔的少女大和凛子，以及猛男的幼时好友——帅哥砂川诚为中心展开，主要描写了他们相互的理解以及彼此的交流。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0023EF81B04C0B5850E978#第02集$MOE0023EF81B04C0B5850E97B#第03集$MOE0023EF81B04C0B5850E97A#第04集$MOE0023EF81B04C0B5850E97D#第05集$MOE0023EF81B04C0B5850E97C#第06集$MOE0023EF81B04C0B5850E97F#第07集$MOE0023EF81B04C0B5850E97E#第08集$MOE0023EF81B04C0B5850E971#第09集$MOE0023EF81B04C0B5850E970#第10集$MOE0023EF81B04C0B5850E879#第11集$MOE0023EF81B04C0B5850E878#第12集$MOE0023EF81B04C0B5850E87B#第13集$MOE0023EF81B04C0B5850E87A#第14集$MOE0023EF81B04C0B5850E87D#第15集$MOE0023EF81B04C0B5850E87C#第16集$MOE0023EF81B04C0B5850E87F#第17集$MOE0023EF81B04C0B5850E87E#第18集$MOE0023EF81B04C0B5850E871#第19集$MOE0023EF81B04C0B5850E870#第20集$MOE0023EF81B04C0B5850EB79#第21集$MOE0023EF81B04C0B5850EB78#第22集$MOE0023EF81B04C0B5850EB7B#第23集$MOE0023EF81B04C0B5850EB7A#第24集$MOE0023EF81B04C0B5850EB7D$$$第01集$id_XS0023EF81B04C0B5850E978#第02集$id_XS0023EF81B04C0B5850E97B#第03集$id_XS0023EF81B04C0B5850E97A#第04集$id_XS0023EF81B04C0B5850E97D#第05集$id_XS0023EF81B04C0B5850E97C#第06集$id_XS0023EF81B04C0B5850E97F#第07集$id_XS0023EF81B04C0B5850E97E#第08集$id_XS0023EF81B04C0B5850E971#第09集$id_XS0023EF81B04C0B5850E970#第10集$id_XS0023EF81B04C0B5850E879#第11集$id_XS0023EF81B04C0B5850E878#第12集$id_XS0023EF81B04C0B5850E87B#第13集$id_XS0023EF81B04C0B58