INSERT INTO `mac_vod` VALUES (914, 1, 0, 0, '没落要塞 / DECA-DENCE', 'デカダンス（2020）', 'meiluoyaosaiDECADENCE', 1, 'M', '', '3be30ecd', '原创,科幻,架空,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/d5d7441c20614dc5ddc69f333f1906a09eddcee2.png', '', '', '', '小西克幸 / 楠木灯 / 鸟海浩辅 / 喜多村英梨 / 柴田芽衣 / 青山吉能 / 竹内荣治', '立川让', '', '', '自从人类因突然出现的未知生命体「伽德鲁」而陷入灭亡的危机，已经过了漫长的岁月。残存的人们为了从「伽德鲁」的威胁当中自保，而建造了全高3,000M的巨大移动要塞「DECA-DENCE」，并在其中生活。', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.7, 0, 0, 1737610317, 1737470677, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>自从人类因突然出现的未知生命体「伽德鲁」而陷入灭亡的危机，已经过了漫长的岁月。残存的人们为了从「伽德鲁」的威胁当中自保，而建造了全高3,000M的巨大移动要塞「DECA-DENCE」，并在其中生活。&nbsp;</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0275E98BB94C0E5D50E978#第02集$MOE0275E98BB94C0E5D50E97B#第03集$MOE0275E98BB94C0E5D50E97A#第04集$MOE0275E98BB94C0E5D50E97D#第05集$MOE0275E98BB94C0E5D50E97C#第06集$MOE0275E98BB94C0E5D50E97F#第07集$MOE0275E98BB94C0E5D50E97E#第08集$MOE0275E98BB94C0E5D50E971#第09集$MOE0275E98BB94C0E5D50E970#第10集$MOE0275E98BB94C0E5D50E879#第11集$MOE0275E98BB94C0E5D50E878#第12集$MOE0275E98BB94C0E5D50E87B$$$第01集$id_XS0275E98BB94C0E5D50E978#第02集$id_XS0275E98BB94C0E5D50E97B#第03集$id_XS0275E98BB94C0E5D50E97A#第04集$id_XS0275E98BB94C0E5D50E97D#第05集$id_XS0275E98BB94C0E5D50E97C#第06集$id_XS0275E98BB94C0E5D50E97F#第07集$id_XS0275E98BB94C0E5D50E97E#第08集$id_XS0275E98BB94C0E5D50E971#第09集$id_XS0275E98BB94C0E5D50E970#第10集$id_XS0275E98BB94C0E5D50E879#第11集$id_XS0275E98BB94C0E5D50E878#第12集$id_XS0275E98BB94C0E5D50E87B$$$第01集$id_MOE0275E98BB94C0E5D50E978#第02集$id_MOE0275E98BB94C0E5D50E97B#第03集$id_MOE0275E98BB94C0E5D50E97A#第04集$id_MOE0275E98BB94C0E5D50E97D#第05集$id_MOE0275E98BB94C0E5D50E97C#第06集$id_MOE0275E98BB94C0E5D50E97F#第07集$id_MOE0275E98BB94C0E5D50E97E#第08集$id_MOE0275E98BB94C0E5D50E971#第09集$id_MOE0275E98BB94C0E5D50E970#第10集$id_MOE0275E98BB94C0E5D50E879#第11集$id_MOE0275E98BB94C0E5D50E878#第12集$id_MOE0275E98BB94C0E5D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (915, 1, 0, 0, 'SSSS.电光机王', 'SSSS.DYNAZENON（2021）', 'SSSSdianguangjiwang', 1, 'S', '', '22ee70a1', '机战,特摄,原创,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/6f55217ca57a821c1e855a8fa96e77880e25a119.png', '', '', '', '滨野大辉 / 榎木淳弥 / 若山诗音 / 梅原裕一郎 / 安济知佳 / 神谷浩史 / 内田雄马 / 诹访彩花 / 内山昂辉 / 伊濑茉莉也 / 田所梓 / 小笠原仁 / 梶原岳人 / 土屋李央 / 远野光', '雨宫哲', '', '', '本作改编自特摄作品《电光超人古立特》。高中一年生的麻中蓬，在某日回家的路上，对自称「怪兽使」却饿倒在路旁的谜之青年失马施以援手。为了迎击突然出现的怪兽，蓬与同班同学南梦芽、无业青年山中历、飞鸟川千濑共', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.8, 0, 0, 1737610439, 1737470694, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本作改编自特摄作品《电光超人古立特》。高中一年生的麻中蓬，在某日回家的路上，对自称「怪兽使」却饿倒在路旁的谜之青年失马施以援手。为了迎击突然出现的怪兽，蓬与同班同学南梦芽、无业青年山中历、飞鸟川千濑共同被卷入了战斗之中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0325E9DDBE190C0850E978#第02集$MOE0325E9DDBE190C0850E97B#第03集$MOE0325E9DDBE190C0850E97A#第04集$MOE0325E9DDBE190C0850E97D#第05集$MOE0325E9DDBE190C0850E97C#第06集$MOE0325E9DDBE190C0850E97F#第07集$MOE0325E9DDBE190C0850E97E#第08集$MOE0325E9DDBE190C0850E971#第09集$MOE0325E9DDBE190C0850E970#第10集$MOE0325E9DDBE190C0850E879#第11集$MOE0325E9DDBE190C0850E878#第12集$MOE0325E9DDBE190C0850E87B$$$第01集$id_XS0325E9DDBE190C0850E978#第02集$id_XS0325E9DDBE190C0850E97B#第03集$id_XS0325E9DDBE190C0850E97A#第04集$id_XS0325E9DDBE190C0850E97D#第05集$id_XS0325E9DDBE190C0850E97C#第06集$id_XS0325E9DDBE190C0850E97F#第07集$id_XS0325E9DDBE190C0850E97E#第08集$id_XS0325E9DDBE190C0850E971#第09集$id_XS0325E9DDBE190C0850E970#第10集$id_XS0325E9DDBE190C0850E879#第11集$id_XS0325E9DDBE190C0850E878#第12集$id_XS0325E9DDBE190C0850E87B$$$第01集$id_MOE0325E9DDBE190C0850E978#第02集$id_MOE0325E9DDBE190C0850E97B#第03集$id_MOE0325E9DDBE190C0850E97A#第04集$id_MOE0325E9DDBE190C0850E97D#第05集$id_MOE0325E9DDBE190C0850E97C#第06集$id_MOE0325E9DDBE190C0850E97F#第07集$id_MOE0325E9DDBE190C0850E97E#第08集$id_MOE0325E9DDBE190C0850E971#第09集$id_MOE0325E9DDBE190C0850E970#第10集$id_MOE0325E9DDBE190C0850E879#第11集$id_MOE0325E9DDBE190C0850E878#第12集$id_MOE0325E