INSERT INTO `mac_vod` VALUES (917, 1, 0, 0, '灰与幻想的格林姆迦尔', '灰と幻想のグリムガル（2016）', 'huiyuhuanxiangdegelinmujiaer', 1, 'H', '', '28e37285', '战斗,穿越,冒险,架空', 'http://i0.hdslb.com/bfs/bangumi/7fb4945f864e9e988212b7d20f206df2677053f8.jpg', '', '', '', '细谷佳正 / 吉野裕行 / 岛崎信长 / 落合福嗣 / 小松未可子 / 照井春佳 / 安济知佳 / 关智一 / 浪川大辅 / 安元洋贵 / 能登麻美子 / 野岛健儿 / 杉田智和 / 古木望 / 中田让治 / 高桥广树 / 木内秀信 / 户松遥 / 武内骏辅 / 增田俊树', '中村亮介 / 尾崎隆晴 / 工藤进 / 下司泰弘 / 井端义秀 / 柴山智隆 / 大和直道 / 西村博昭 / 飞田刚 / 原英和 / 三上喜子 / 山内东生雄', '', '', '电视动画《灰与幻想的格林姆迦尔》改编自日本轻小说家十文字青原作白井锐利插画的同名轻小说。\r\n我们为什么要这么做…？\r\n哈尔希洛回过神来，才发现自己身处在黑暗当中，他完全不知道自己人在何处，也不明白这个地方', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.8, 0, 0, 1737639410, 1737470720, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>电视动画《灰与幻想的格林姆迦尔》改编自日本轻小说家十文字青原作白井锐利插画的同名轻小说。\r\n我们为什么要这么做…？\r\n哈尔希洛回过神来，才发现自己身处在黑暗当中，他完全不知道自己人在何处，也不明白这个地方是哪里。\r\n他的身边有一群和他一样失去记忆，只记得自己名字的男女；而离开了地底後，等待着众人的是一个「宛如游戏」的世界。\r\n为求生存，哈尔希洛与自己有著相同境遇的夥伴们组成队伍、学习技能，以义勇兵见习者的身分踏入了这个世界——「格林姆迦尔」。\r\n没有人知道未来会遇见什么…这一切，就是从灰烬之中所诞生的冒险谭。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032FE98BBE1B550C50E978#第02集$MOE032FE98BBE1B550C50E97B#第03集$MOE032FE98BBE1B550C50E97A#第04集$MOE032FE98BBE1B550C50E97D#第05集$MOE032FE98BBE1B550C50E97C#第06集$MOE032FE98BBE1B550C50E97F#第07集$MOE032FE98BBE1B550C50E97E#第08集$MOE032FE98BBE1B550C50E971#第09集$MOE032FE98BBE1B550C50E970#第10集$MOE032FE98BBE1B550C50E879#第11集$MOE032FE98BBE1B550C50E878#第12集$MOE032FE98BBE1B550C50E87B#OVA$MOE032FE98BBE1B550C50E87A$$$第01集$id_XS032FE98BBE1B550C50E978#第02集$id_XS032FE98BBE1B550C50E97B#第03集$id_XS032FE98BBE1B550C50E97A#第04集$id_XS032FE98BBE1B550C50E97D#第05集$id_XS032FE98BBE1B550C50E97C#第06集$id_XS032FE98BBE1B550C50E97F#第07集$id_XS032FE98BBE1B550C50E97E#第08集$id_XS032FE98BBE1B550C50E971#第09集$id_XS032FE98BBE1B550C50E970#第10集$id_XS032FE98BBE1B550C50E879#第11集$id_XS032FE98BBE1B550C50E878#第12集$id_XS032FE98BBE1B550C50E87B#OVA$id_XS032FE98BBE1B550C50E87A$$$第01集$id_MOE032FE98BBE1B550C50E978#第02集$id_MOE032FE9