INSERT INTO `mac_vod` VALUES (938, 1, 0, 0, '一起一起这里那里', 'あっちこっち（2012）', 'yiqiyiqizhelinali', 1, 'Y', '', '51eb8d4b', '萌系,日常,治愈,萝莉', 'http://i0.hdslb.com/bfs/bangumi/6de861925c772076a747844427bf49c252a8accf.jpg', '', '', '', '大久保瑠美 / 冈本信彦 / 福原香织 / 生天目仁美 / 浅沼晋太郎 / 皆口裕子 / 高森奈津美 / 今野宏美 / 代永翼 / 三宅麻理惠 / 岩男润子', '追崎史敏 / 铃木薰 / 岛崎奈奈子 / 古田丈司 / 渡部周 / 安藤贵史 / 吉田理纱子 / 越田知明', '', '', '摘希虽然喜欢伊御，却没办法坦率的表现出来。伊御虽然不清楚摘希的心意，却还是温柔的对待她。两人的关系维持在朋友程度，尚未成为恋人。两人的朋友们总是在一旁热热闹闹的守护他们。\r\n自2006年10月号以三个月', '全13集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.8, 0, 0, 1737844681, 1737719832, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>摘希虽然喜欢伊御，却没办法坦率的表现出来。伊御虽然不清楚摘希的心意，却还是温柔的对待她。两人的关系维持在朋友程度，尚未成为恋人。两人的朋友们总是在一旁热热闹闹的守护他们。\r\n自2006年10月号以三个月的短篇的形式开始在“まんがタイムきらら”连载。标题的英文为“PLACE TO PLACE”。摘希（尖端出版社译名）和伊御两人微妙的距离感让旁观的人反而比他们更害羞，这时两人的朋友会代替读者对他们吐槽。在第一集书腰上写着“看了之后一定会想要在地上打滚”。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0426E9DAB14D595B50E978#第02集$MOE0426E9DAB14D595B50E97B#第03集$MOE0426E9DAB14D595B50E97A#第04集$MOE0426E9DAB14D595B50E97D#第05集$MOE0426E9DAB14D595B50E97C#第06集$MOE0426E9DAB14D595B50E97F#第07集$MOE0426E9DAB14D595B50E97E#第08集$MOE0426E9DAB14D595B50E971#第09集$MOE0426E9DAB14D595B50E970#第10集$MOE0426E9DAB14D595B50E879#第11集$MOE0426E9DAB14D595B50E878#第12集$MOE0426E9DAB14D595B50E87B#第13集$MOE0426E9DAB14D595B50E87A$$$第01集$id_XS0426E9DAB14D595B50E978#第02集$id_XS0426E9DAB14D595B50E97B#第03集$id_XS0426E9DAB14D595B50E97A#第04集$id_XS0426E9DAB14D595B50E97D#第05集$id_XS0426E9DAB14D595B50E97C#第06集$id_XS0426E9DAB14D595B50E97F#第07集$id_XS0426E9DAB14D595B50E97E#第08集$id_XS0426E9DAB14D595B50E971#第09集$id_XS0426E9DAB14D595B50E970#第10集$id_XS0426E9DAB14D595B50E879#第11集$id_XS0426E9DAB14D595B50E878#第12集$id_XS0426E9DAB14D595B50E87B#第13集$id_XS0426E9DAB14D595B50E87A$$$第01集$id_MOE0426E9DAB14D595B50E978#第02集$id_MOE0426E9DAB14D595B50E97B#第03集$id_MOE0426E9DAB14D595B50E97A#第04集$id_MOE0426E9DAB14D595B50E97D#第05集$id_MOE0426E9DAB14D595B50E97C#第06集$id_MOE0426E9DAB14D595B50E97F#第07集$id_MOE0426E9DAB14D595B50E97E#第08集$id_MOE0426E9DAB14D595B50E971#第09集$id_MOE0426E9DAB14D595B50E970#第10集$id_MOE0426E9DAB14D595B50E879#第11集$id_MOE0426E9DAB14D595B50E878#第12集$id_MOE0426E9DAB14D595B50E87B#第13集$id_MOE0426E9DAB14D595B50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (939, 1, 0, 0, '学园孤岛', 'がっこうぐらし！（2015）', 'xueyuangudao', 1, 'X', '', '34b2a1a', '冒险,日常,萌系,校园', 'http://i0.hdslb.com/bfs/bangumi/image/86b4b78cd908b30a26c772e6419de5d1385b1cb3.jpg', '', '', '', '水濑祈 / 小泽亚李 / 市道真央 / 高桥李依 / 茅野爱衣 / 加藤英美里 / 木村珠莉', '安藤正臣 / 木野目优 / 吉田俊司 / 铃木芳成 / 矢野孝典 / 高林久弥 / 江副仁美 / 富永恒雄', '', '', '巡之丘学园生活社成员的丈枪由纪，将与顾问老师佐仓惠、社长若狭悠里及随身带著圆锹的恵飞须泽胡桃一起度过乍看之下快乐无比的校园生活。但事实上学校早已被一群僵尸所包围，但由纪却犹如失忆般的活在正常生活的幻想', '全12集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.6, 0, 0, 1737844999, 1737719841, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>巡之丘学园生活社成员的丈枪由纪，将与顾问老师佐仓惠、社长若狭悠里及随身带著圆锹的恵飞须泽胡桃一起度过乍看之下快乐无比的校园生活。但事实上学校早已被一群僵尸所包围，但由纪却犹如失忆般的活在正常生活的幻想之中。其馀成员们为了保护她，必须一边与渐渐逼近的僵尸及生活问题对抗，一边维持正常学生生活以避免刺激到由纪。一场在幻想与现实中交错的故事，一群少女身处在名为学园的孤岛上的艰困生活才正要开始……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0223EE8AE8180C144DE8#第02集$MOE0223EE8AE8180C144DEB#第03集$MOE0223EE8AE8180C144DEA#第04集$MOE0223EE8AE8180C144DED#第05集$MOE0223EE8AE8180C144DEC#第06集$MOE0223EE8AE8180C144DEF#第07集$MOE0223EE8AE8180C144DEE#第08集$MOE0223EE8AE8180C144DE1#第09集$MOE0223EE8AE8180C144DE0#第10集$MOE0223EE8AE8180C144CE9#第11集$MOE0223EE8AE8180C144CE8#第12集$MOE0223EE8AE8180C144CEB$$$第01集$id_XS0223EE8AE8180C144DE8#第02集$id_XS0223EE8AE8180C144DEB#第03集$id_XS0223EE8AE8180C144DEA#第04集$id_XS0223EE8AE8180C144DED#第05集$id_XS0223EE8AE8180C144DEC#第06集$id_XS0223EE8AE8180C144DEF#第07集$id_XS0223EE8AE8180C144DEE#第08集$id_XS0223EE8AE8180C144DE1#第09集$id_XS0223EE8AE8180C144DE0#第10集$id_XS0223EE8AE8180C144CE9#第11集$id_XS0223EE8AE8180C144CE8#第12集$id_XS0223EE8AE8180C144CEB$$$第01集$id_MOE0223EE8AE8180C144DE8#第02集$id_MOE0223EE8AE8180C144DEB#第03集$id_MOE0223EE8AE8180C144DEA#第04集$id_MOE0223EE8AE8180C144DED#第05集$id_MOE0223EE8AE8180C144DEC#第06集$id_MOE0223EE8AE8180C144DEF#第07集$id_MOE0223EE8AE8180C144DEE#第08集$id_MOE0223EE8AE8180C144DE1#第09集$id_MOE0223EE8AE8180C144DE0#第10集$id_MOE0223EE8AE8180C144CE9#第11集$id_MOE0223EE8AE8180C144CE8#第12集$id_MOE0223EE8AE8180C144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (125, 1, 0, 0, '政宗君的复仇', '政宗くんのリベンジ（2017）', 'zhengzongjundefuchou', 1, 'Z', '', 'a48e13d7', '恋爱,漫画改,搞笑,校园', 'http://i0.hdslb.com/bfs/bangumi/image/8d3fe4278e6e9d7e3a8a3794f4395066e4529914.png', '', '', '', '花江夏树 / 大桥彩香 / 水濑祈 / 三森铃子 / 田所梓 / 早见沙织 / 斋贺光希 / 小仓唯 / 大龟明日香 / 大地叶 / 小清水亚美', '凑未来 / 井上圭介 / 五味伸介 / 伊部勇志 / 高桥贤', '', '', '为了复仇，我又回到这座城市了！\r\n8年前，被美少女安达垣爱姬残忍拒绝的肥胖少年真壁政宗，变得超瘦又更改了名字，变身成帅哥回来了。没错，一切都是为了让那个号称残虐公主的抖S女生迷上自己，完成最高形式的复仇', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 38, 0, 38, 38, '', 0, 0, 4.1, 0, 0, 1737863150, 1737719848, 0, 0, 0, 0, 0.0, '', '940', '', '', '', '', '', '', '', '<p>为了复仇，我又回到这座城市了！\r\n8年前，被美少女安达垣爱姬残忍拒绝的肥胖少年真壁政宗，变得超瘦又更改了名字，变身成帅哥回来了。没错，一切都是为了让那个号称残虐公主的抖S女生迷上自己，完成最高形式的复仇——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5023B4DDB81A090E50E978#第02集$MOE5023B4DDB81A090E50E97B#第03集$MOE5023B4DDB81A090E50E97A#第04集$MOE5023B4DDB81A090E50E97D#第05集$MOE5023B4DDB81A090E50E97C#第06集$MOE5023B4DDB81A090E50E97F#第07集$MOE5023B4DDB81A090E50E97E#第08集$MOE5023B4DDB81A090E50E971#第09集$MOE5023B4DDB81A090E50E970#第10集$MOE5023B4DDB81A090E50E879#第11集$MOE5023B4DDB81A090E50E878#第12集$MOE5023B4DDB81A090E50E87B#OAD$MOE5023B4DDB81A090E50E87A$$$第01集$id_XS5023B4DDB81A090E50E978#第02集$id_XS5023B4DDB81A090E50E97B#第03集$id_XS5023B4DDB81A090E50E97A#第04集$id_XS5023B4DDB81A090E50E97D#第05集$id_XS5023B4DDB81A090E50E97C#第06集$id_XS5023B4DDB81A090E50E97F#第07集$id_XS5023B4DDB81A090E50E97E#第08集$id_XS5023B4DDB81A090E50E971#第09集$id_XS5023B4DDB81A090E50E970#第10集$id_XS5023B4DDB81A090E50E879#第11集$id_XS5023B4DDB81A090E50E878#第12集$id_XS5023B4DDB81A090E50E87B#OAD$id_XS5023B4DDB81A090E50E87A$$$第01集$id_MOE5023B4DDB81A090E50E978#第02集$id_MOE5023B4DDB81A090E50E97B#第03集$id_MOE5023B4DDB81A090E50E97A#第04集$id_MOE5023B4DDB81A090E50E97D#第05集$id_MOE5023B4DDB81A090E50E97C#第06集$id_MOE5023B4DDB81A090E50E97F#第07集$id_MOE5023B4DDB81A090E50E97E#第08集$id_MOE5023B4DDB81A090E50E971#第09集$id_MOE5023B4DDB81A090E50E970#第10集$id_MOE5023B4DDB81