INSERT INTO `mac_vod` VALUES (943, 1, 0, 0, 'NEW GAME!!', 'NEW GAME!!（2017）', 'NEWGAME', 1, 'N', '', 'cfb55b35', '职场,漫画改', 'http://i0.hdslb.com/bfs/bangumi/5190b555298eb99c7d7f62eb2ca3891389bd00f8.jpg', '', '', '', '高田忧希 / 日笠阳子 / 茅野爱衣 / 山口爱 / 户田惠 / 竹尾步美 / 朝日奈丸佳 / 森永千才 / 喜多村英梨 / 铃木亚理沙 / 大和田仁美 / 石见舞菜香 / 名冢佳织', '藤原佳幸 / 山崎光惠 / 木村泰大 / 平牧大辅 / 伊藤良太 / 藤井隆文 / 守田艺成 / 野吕纯惠 / 津田义三 / 藏本穗高 / 野木森达哉', '', '', '——有想要实现的梦想！\r\n高中毕业后，进入游戏制作公司“Eagle Jump”的凉风青叶，开始参与她自幼热衷的游戏《妖精物语》系列的最新作《妖精物语3》的制作。\r\n与使自己立志成为角色设计师的契机——八神', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.6, 0, 0, 1737901163, 1737846406, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>——有想要实现的梦想！\r\n高中毕业后，进入游戏制作公司“Eagle Jump”的凉风青叶，开始参与她自幼热衷的游戏《妖精物语》系列的最新作《妖精物语3》的制作。\r\n与使自己立志成为角色设计师的契机——八神光相遇，由此开始，在可靠的前辈们帮助下，一点一点成长的青叶。\r\n之后《妖精物语3》也顺利完成，从青叶入社开始刚好过了1年，又到了“Eagle Jump”迎来新员工的季节。\r\n曾经是个一窍不通的菜鸟的自己也终于要成为前辈，一想到这里就无法抑制心中激动的青叶。\r\n“我是前辈凉风青叶哦！请多指教！”青叶在“Eagle Jump”的入口重复地练习打招呼……。\r\n描绘在游戏公司工作的女孩子们日常的工作少女喜剧再度开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5271EE8DBC4B5E0C50E978#第02集$MOE5271EE8DBC4B5E0C50E97B#第03集$MOE5271EE8DBC4B5E0C50E97A#第04集$MOE5271EE8DBC4B5E0C50E97D#第05集$MOE5271EE8DBC4B5E0C50E97C#第06集$MOE5271EE8DBC4B5E0C50E97F#第07集$MOE5271EE8DBC4B5E0C50E97E#第08集$MOE5271EE8DBC4B5E0C50E971#第09集$MOE5271EE8DBC4B5E0C50E970#第10集$MOE5271EE8DBC4B5E0C50E879#第11集$MOE5271EE8DBC4B5E0C50E878#第12集$MOE5271EE8DBC4B5E0C50E87B$$$第01集$id_XS5271EE8DBC4B5E0C50E978#第02集$id_XS5271EE8DBC4B5E0C50E97B#第03集$id_XS5271EE8DBC4B5E0C50E97A#第04集$id_XS5271EE8DBC4B5E0C50E97D#第05集$id_XS5271EE8DBC4B5E0C50E97C#第06集$id_XS5271EE8DBC4B5E0C50E97F#第07集$id_XS5271EE8DBC4B5E0C50E97E#第08集$id_XS5271EE8DBC4B5E0C50E971#第09集$id_XS5271EE8DBC4B5E0C50E970#第10集$id_XS5271EE8DBC4B5E0C50E879#第11集$id_XS5271EE8DBC4B5E0C50E878#第12集$id_XS5271EE8DBC4B5E0C50E87B$$$第01集$id_MOE5271EE8DBC4B5E0C50E978#第02集$id_MOE5271EE8DBC4B5E0C50E97B#第03集$id_MOE5271EE8DBC4B5E0C50E97A#第04集$id_MOE5271EE8DBC4B5E0C50E97D#第05集$id_MOE5271EE8DBC4B5E0C50E97C#第06集$id_MOE5271EE8DBC4B5E0C50E97F#第07集$id_MOE5271EE8DBC4B5E0C50E97E#第08集$id_MOE5271EE8DBC4B5E0C50E971#第09集$id_MOE5271EE8DBC4B5E0C50E970#第10集$id_MOE5271EE8DBC4B5E0C50E879#第11集$id_MOE5271EE8DBC4B5E0C50E878#第12集$id_MOE5271EE8DBC4B5E0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (944, 1, 0, 0, '刺客守则', 'アサシンズプライド（2019）', 'cikeshouze', 1, 'C', '', '9494901a', '架空,小说改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/63f236818c51f8f52dcf1b14c1892ed68affc4f3.png', '', '', '', '小野友树 / 楠木灯 / 石川由依 / 薮内满里奈 / 佐仓绫音 / 森川智之 / 铃木达央', '相浦和也', '', '', '拥有名为玛那这一能力的贵族，肩负着保护人类这一使命。就读于能力者育成学校的贵族，却没有一点玛那的特殊少女梅莉达·安杰尔。为了发掘她的才能，库法·梵皮尔被派来担任她的家庭教师。\r\n他同时也肩负“倘若确认她', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 6.5, 0, 0, 1737937355, 1737846424, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>拥有名为玛那这一能力的贵族，肩负着保护人类这一使命。就读于能力者育成学校的贵族，却没有一点玛那的特殊少女梅莉达·安杰尔。为了发掘她的才能，库法·梵皮尔被派来担任她的家庭教师。\r\n他同时也肩负“倘若确认她没有才能，就暗杀掉”的任务——。在这个能力即是一切的社会，面对坚持着没有任何成果的努力的梅莉达，库法是否会对她下达残酷的处决……\r\n“要不要试着把生命托付给我？”并非以刺客或单纯的教师身份，而是赌上暗杀教师的骄傲，向世界展现少女的价值！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0823B58CB0195C5850E978#第02集$MOE0823B58CB0195C5850E97B#第03集$MOE0823B58CB0195C5850E97A#第04集$MOE0823B58CB0195C5850E97D#第05集$MOE0823B58CB0195C5850E97C#第06集$MOE0823B58CB0195C5850E97F#第07集$MOE0823B58CB0195C5850E97E#第08集$MOE0823B58CB0195C5850E971#第09集$MOE0823B58CB0195C5850E970#第10集$MOE0823B58CB0195C5850E879#第11集$MOE0823B58CB0195C5850E878#第12集$MOE0823B58CB0195C5850E87B$$$第01集$id_XS0823B58CB0195C5850E978#第02集$id_XS0823B58CB0195C5850E97B#第03集$id_XS0823B58CB0195C5850E97A#第04集$id_XS0823B58CB0195C5850E97D#第05集$id_XS0823B58CB0195C5850E97C#第06集$id_XS0823B58CB0195C5850E97F#第07集$id_XS0823B58CB0195C5850E97E#第08集$id_XS0823B58CB0195C5850E971#第09集$id_XS0823B58CB0195C5850E970#第10集$id_XS0823B58CB0195C5850E879#第11集$id_XS0823B58CB0195C5850E878#第12集$id_XS0823B58CB0195C5850E87B$$$第01集$id_MOE0823B58CB0195C5850E978#第02集$id_MOE0823B58CB0195C5850E97B#第03集$id_MOE0823B58CB0195C5850E97A#第04集$id_MOE0823B58CB0195C5850E97D#第05集$id_MOE0823B58CB0195C5850E97C#第06集$id_MOE0823B58CB0195C5850E97F#第07集$id_MOE0823B58CB0195C5850E97E#第08集$id_MOE0823B58CB0195C5850E971#第09集$id_MOE0823B58CB0195C5850E970#第10集$id_MOE0823B58CB0195C5850E879#第11集$id_MOE0823B58CB0195C5850E878#第12集$id_MOE0823B58CB0195C5850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (945, 1, 0, 0, '鬼灯的冷彻', '鬼灯の冷徹（2014）', 'guidengdelengche', 1, 'G', '', 'e0571c00', '日常,神魔', 'http://i0.hdslb.com/bfs/bangumi/6c6f6b21d51753a2041ba4acf5cef1d5a6b2e4b2.jpg', '', '', '', '安元洋贵 / 长嶝高士 / 平川大辅 / 小林由美子 / 后藤弘树 / 松山鹰志 / 柿原彻也 / 青山桐子 / 喜多村英梨 / 游佐浩二', '镝木宏 / 长沼范裕 / 川越崇弘 / 山田弘和 / 江副仁美 / 金森阳子 / 水本叶月 / 羽原久美子 / 川久保圭史 / 野木森达哉', '', '', '【本片翻译由WOLF字幕组友情提供】阎罗王手下的第一补佐官·鬼灯在地狱中充满超级S的日常生活以及超现实的黑色幽默。主要舞台是描述住在日本的地狱的当地居民们的生活、除此之外还有神话、日本童话、怪谈等多数', '全13集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 9.6, 0, 0, 1737937484, 1737846438, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由WOLF字幕组友情提供】阎罗王手下的第一补佐官·鬼灯在地狱中充满超级S的日常生活以及超现实的黑色幽默。主要舞台是描述住在日本的地狱的当地居民们的生活、除此之外还有神话、日本童话、怪谈等多数故事人物登场、另外不限于日本，国外的恶魔和妖怪也会出现。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5427B98FB84A5D0950E978#第02集$MOE5427B98FB84A5D0950E97B#第03集$MOE5427B98FB84A5D0950E97A#第04集$MOE5427B98FB84A5D0950E97D#第05集$MOE5427B98FB84A5D0950E97C#第06集$MOE5427B98FB84A5D0950E97F#第07集$MOE5427B98FB84A5D0950E97E#第08集$MOE5427B98FB84A5D0950E971#第09集$MOE5427B98FB84A5D0950E970#第10集$MOE5427B98FB84A5D0950E879#第11集$MOE5427B98FB84A5D0950E878#第12集$MOE5427B98FB84A5D0950E87B#第13集$MOE5427B98FB84A5D0950E87A$$$第01集$id_XS5427B98FB84A5D0950E978#第02集$id_XS5427B98FB84A5D0950E97B#第03集$id_XS5427B98FB84A5D0950E97A#第04集$id_XS5427B98FB84A5D0950E97D#第05集$id_XS5427B98FB84A5D0950E97C#第06集$id_XS5427B98FB84A5D0950E97F#第07集$id_XS5427B98FB84A5D0950E97E#第08集$id_XS5427B98FB84A5D0950E971#第09集$id_XS5427B98FB84A5D0950E970#第10集$id_XS5427B98FB84A5D0950E879#第11集$id_XS5427B98FB84A5D0950E878#第12集$id_XS5427B98FB84A5D0950E87B#第13集$id_XS5427B98FB84A5D0950E87A$$$第01集$id_MOE5427B98FB84A5D0950E978#第02集$id_MOE5427B98FB84A5D0950E97B#第03集$id_MOE5427B98FB84A5D0950E97A#第04集$id_MOE5427B98FB84A5D0950E97D#第05集$id_MOE5427B98FB84A5D0950E97C#第06集$id_MOE5427B98FB84A5D0950E97F#第07集$id_MOE5427B98FB84A5D0950E97E#第08集$id_MOE5427B98FB84A5D0950E971#第09集$id_MOE5427B98FB84A5D0950E970#第10集$id_MOE5427B98FB84A5D0950E879#第11集$id_MOE5427B98FB84A5D0950E878#第12集$id_MOE5427B98FB84A5D0950E87B#第13集$id_MOE5427B98FB84A5D0950E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (946, 1, 0, 0, '不管我怎么去想我不受欢迎这件事都是你们的错！', '私がモテないのはどう考えてもお前らが悪い！（2013）', 'buguanwozenmequxiangwobushouhuanyingzhejianshidushinimendecuo', 1, 'B', '', 'ae518015', '漫画改,日常,搞笑,校园,治愈', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2260256352.jpg', '', '', '', '橘田泉 / 中村悠一 / 花泽香菜 / 钉宫理惠 / 野中蓝 / 早水理沙 / 杉田智和', '大沼心 / 永冈智佳 / 神保昌登 / 德本善信 / 岩本保雄 / 玉村仁', '', '', '原本还算有着可爱的脸蛋，可是不知为何总给人一种阴冷诡异不好接近的感觉。这便是刚刚升入高中不久的黑木智子（橘田いずみ 配音），她蓬头垢面，少言寡语，脸上是极度痴迷游戏后留下的黑眼圈。原本以为自己会成为乙', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 35, 0, 35, 35, '', 0, 0, 8.0, 0, 0, 1737907340, 1737892199, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>原本还算有着可爱的脸蛋，可是不知为何总给人一种阴冷诡异不好接近的感觉。这便是刚刚升入高中不久的黑木智子（橘田いずみ 配音），她蓬头垢面，少言寡语，脸上是极度痴迷游戏后留下的黑眼圈。原本以为自己会成为乙女游戏中众星捧月的校花，谁知却注定要成为没有朋友、无人关注的丧女。更无法忍受的，是初中与之同类型的死党成濑优（花澤香菜 配音）都有了翻天覆地的变化。当然，拥有强大内心的智子绝不会因此自甘沉沦，她暗自嘲笑同学的肤浅与轻浮，在妄想世界里体会着前所未有的快乐。只不过依旧耐不住寂寞，这又化作了自卑、嫉妒和各种恶毒的心语。实在逼到极点，便朝向弟弟智贵（中村悠一 配音）。总之，她之所以变成这样，都怪这个世界和周围人而已……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5072B989B1195C0C50E978#第02集$MOE5072B989B1195C0C50E97B#第03集$MOE5072B989B1195C0C50E97A#第04集$MOE5072B989B1195C0C50E97D#第05集$MOE5072B989B1195C0C50E97C#第06集$MOE5072B989B1195C0C50E97F#第07集$MOE5072B989B1195C0C50E97E#第08集$MOE5072B989B1195C0C50E971#第09集$MOE5072B989B1195C0C50E970#第10集$MOE5072B989B1195C0C50E879#第11集$MOE5072B989B1195C0C50E878#第12集$MOE5072B989B1195C0C50E87B#OAD$MOE5072B989B1195C0C50E87A$$$第01集$id_XS5072B989B1195C0C50E978#第02集$id_XS5072B989B1195C0C50E97B#第03集$id_XS5072B989B1195C0C50E97A#第04集$id_XS5072B989B1195C0C50E97D#第05集$id_XS5072B989B1195C0C50E97C#第06集$id_XS5072B989B1195C0C50E97F#第07集$id_XS5072B989B1195C0C50E97E#第08集$id_XS5072B989B1195C0C50E971#第09集$id_XS5072B989B1195C0C50E970#第10集$id_XS5072B989B1195C0C50E879#第11集$id_XS5072B989B1195C0C50E878#第12集$id_XS5072B989B1195C0C50E87B#OAD$id_XS5072B989B1195C0C50E87A$$$第01集$id_MOE5072B989B1195C0C50E978#第02集$id_MOE5072B989B1195C0C50E97B#第03集$id_MOE5072B989B1195C0C50E97A#第04集$id_MOE5072B989B1195C0C50E97D#第05集$id_MOE5072B989B1195C0C50E97C#第06集$id_MOE5072B989B1195C0C50E97F#第07集$id_MOE5072B989B1195C0C50E97E#第08集$id_MOE5072B989B1195C0C50E971#第09集$id_MOE5072B989B1195C0C50E970#第10集$id_MOE5072B989B1195C0C50E879#第11集$id_MOE5072B989B1195C0C50E878#第12集$id_MOE5072B989B1195C0C50E87B#OAD$id_MOE5072B989B1195C0C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (947, 1, 0, 0, '鬼灯的冷彻 第二季', '鬼灯の冷徹 第弐期（2017）', 'guidengdelengchedierji', 1, 'G', '', '12ac43ef', '神魔,漫画改,搞笑,日常', 'http://i0.hdslb.com/bfs/bangumi/c2c5e414d49526b00c551930c41def366c5f9136.jpg', '', '', '', '安元洋贵 / 长嶝高士 / 小林由美子 / 后藤弘树 / 松山鹰志 / 喜多村英梨 / 青山桐子 / 柿原彻也 / 种崎敦美 / 上坂堇 / 平川大辅 / 游佐浩二 / 佐藤聪美 / 小仓唯 / 诹访彩花', '米田和弘 / 曾根利幸 / 江副仁美 / 牧野友映 / 加藤显 / 安藤贵史', '', '', '那个世界存在着天国和地狱，地狱被分为八大地狱和八寒地狱两部分，其中更是划分了二百七十二个精细的部署，战后的人口爆发，恶灵（贞子一类的）的凶暴化， 那个世界陷入了前所示闻的混乱之中。不管是这个世界还是那', '全26集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.7, 0, 0, 1737937603, 1737918155, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>那个世界存在着天国和地狱，地狱被分为八大地狱和八寒地狱两部分，其中更是划分了二百七十二个精细的部署，战后的人口爆发，恶灵（贞子一类的）的凶暴化， 那个世界陷入了前所示闻的混乱之中。不管是这个世界还是那个世界，处理此等问题的就是冷静的善后工作负责人，但是—如此杰出的幕后人物却比各种领袖角色稀少多了。阎罗王手下的第一补佐官・鬼灯就是处理善后的鬼神，作为抖S的鬼灯的地狱日常生活开始了……“冷彻”指不被感情所左右能冷静客观透彻的看待事物。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0025EDDBBD1A085F50E978#第02集$MOE0025EDDBBD1A085F50E97B#第03集$MOE0025EDDBBD1A085F50E97A#第04集$MOE0025EDDBBD1A085F50E97D#第05集$MOE0025EDDBBD1A085F50E97C#第06集$MOE0025EDDBBD1A085F50E97F#第07集$MOE0025EDDBBD1A085F50E97E#第08集$MOE0025EDDBBD1A085F50E971#第09集$MOE0025EDDBBD1A085F50E970#第10集$MOE0025EDDBBD1A085F50E879#第11集$MOE0025EDDBBD1A085F50E878#第12集$MOE0025EDDBBD1A085F50E87B#第13集$MOE0025EDDBBD1A085F50E87A#第14集$MOE0025EDDBBD1A085F50E87D#第15集$MOE0025EDDBBD1A085F50E87C#第16集$MOE0025EDDBBD1A085F50E87F#第17集$MOE0025EDDBBD1A085F50E87E#第18集$MOE0025EDDBBD1A085F50E871#第19集$MOE0025EDDBBD1A085F50E870#第20集$MOE0025EDDBBD1A085F50EB79#第21集$MOE0025EDDBBD1A085F50EB78#第22集$MOE0025EDDBBD1A085F50EB7B#第23集$MOE0025EDDBBD1A085F50EB7A#第24集$MOE0025EDDBBD1A085F50EB7D#第25集$MOE0025EDDBBD1A085F50EB7C#第26集$MOE0025EDDBBD1A085F50EB7F$$$第01集$id_XS0025EDDBBD1A085F50E978#第02集$id_XS0025EDDBBD1A085F50E97B#第03集$id_XS0025EDDBBD1A085F50E97A#第04集$id_XS0025EDDBBD1A085F50E97D#第05集$id_XS0025EDDBBD1A085F50E97C#第06集$id_XS0025EDDBBD1A085F50E97F#第07集$id_XS0025EDDB