INSERT INTO `mac_vod` VALUES (953, 1, 0, 0, '记录的地平线', 'ログ・ホライズン（2013）', 'jiludedipingxian', 1, 'J', '', '9547e95f', '奇幻,智斗,架空,穿越', 'http://i0.hdslb.com/bfs/bangumi/f04c66e413c0334fb035980bd22757a5230a7fd7.jpg', '', '', '', '寺岛拓笃 / 前野智昭 / 中田让治 / 加藤英美里 / 山下大辉 / 田村奈央 / 原由实 / 高垣彩阳 / 久野美咲 / 松井惠理子 / 后藤弘树 / 樱井孝宏 / 柿原彻也 / 伊濑茉莉也 / 逢坂良太 / 名冢佳织 / 下野纮 / 冈本信彦 / 村田太志 / 日野聪 / 辻亲八 / 高桥未奈美 / 宫下荣治 / 藤原启治 / 雨宫天 / 寺杣昌纪 / 井泽诗织 / 井上麻里奈 / 白熊宽嗣 / 长岛雄一 / 村田知沙', '石平信司 / 福岛宏之 / 石山贵明 / 和田纯一 / 秦义人 / 飞田刚 / 矢野孝典 / 岩本保雄 / 安藤贵史 / 斋藤德明 / 前岛健一 / 川久保圭史', '', '', '某天，老牌网游《elder·tail》突然发生异常，约三万名日本用户被囚禁在了游戏中。游戏龄8年的大学生城惠也被卷入了异世界中，被迫不断与怪物战斗。被不安驱使的玩家充斥街头，大和地区最大的都市“秋叶原', '全25集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 9.7, 0, 0, 1738040629, 1737938690, 0, 0, 0, 0, 0.0, '', '954,955', '', '', '', '', '', '', '', '<p>某天，老牌网游《elder·tail》突然发生异常，约三万名日本用户被囚禁在了游戏中。游戏龄8年的大学生城惠也被卷入了异世界中，被迫不断与怪物战斗。被不安驱使的玩家充斥街头，大和地区最大的都市“秋叶原”就这样失去了秩序。如同孤高的狼一般自负的城惠与自己的老朋友·直继，美少女刺客·晓一起创立了公会“记录的地平线”。不擅交往的内向年轻人与他的伙伴们，一起踏上了从废墟丘耶园开始改变世界的旅程……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0822B88FEC10585F50E978#第02集$MOE0822B88FEC10585F50E97B#第03集$MOE0822B88FEC10585F50E97A#第04集$MOE0822B88FEC10585F50E97D#第05集$MOE0822B88FEC10585F50E97C#第06集$MOE0822B88FEC10585F50E97F#第07集$MOE0822B88FEC10585F50E97E#第08集$MOE0822B88FEC10585F50E971#第09集$MOE0822B88FEC10585F50E970#第10集$MOE0822B88FEC10585F50E879#第11集$MOE0822B88FEC10585F50E878#第12集$MOE0822B88FEC10585F50E87B#第13集$MOE0822B88FEC10585F50E87A#第14集$MOE0822B88FEC10585F50E87D#第15集$MOE0822B88FEC10585F50E87C#第16集$MOE0822B88FEC10585F50E87F#第17集$MOE0822B88FEC10585F50E87E#第18集$MOE0822B88FEC10585F50E871#第19集$MOE0822B88FEC10585F50E870#第20集$MOE0822B88FEC10585F50EB79#第21集$MOE0822B88FEC10585F50EB78#第22集$MOE0822B88FEC10585F50EB7B#第23集$MOE0822B88FEC10585F50EB7A#第24集$MOE0822B88FEC10585F50EB7D#第25集$MOE0822B88FEC10585F50EB7C$$$第01集$id_XS0822B88FEC10585F50E978#第02集$id_XS0822B88FEC10585F50E97B#第03集$id_XS0822B88FEC10585F50E97A#第04集$id_XS0822B88FE