INSERT INTO `mac_vod` VALUES (954, 1, 0, 0, '记录的地平线 第二季', 'ログ・ホライズン 第2シリーズ（2014）', 'jiludedipingxiandierji', 1, 'J', '', '4439d658', '冒险,穿越,智斗,奇幻', 'http://i0.hdslb.com/bfs/bangumi/2878474417b9f0b4551a5606de7f47b313915acd.jpg', '', '', '', '寺岛拓笃 / 加藤英美里 / 前野智昭 / 中田让治 / 田村奈央 / 山下大辉 / 松井惠理子 / 柿原彻也 / 下野纮 / 樱井孝宏 / 原由实 / 高垣彩阳 / 中村悠一 / 斋藤千和 / 三木真一郎', '石平信司', '', '', '热血，友情，冒险，羁绊。看到《记录的地平线》时脑海中自然而然就会蹦出这样的字眼。改变世界绝非虚言，任何时候最重要的是那颗勇敢的心，驱散不安，带着希望，迈向远方！', '全25集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 9.5, 0, 0, 1738058633, 1738018672, 0, 0, 0, 0, 0.0, '', '955', '', '', '', '', '', '', '', '<p>热血，友情，冒险，羁绊。看到《记录的地平线》时脑海中自然而然就会蹦出这样的字眼。改变世界绝非虚言，任何时候最重要的是那颗勇敢的心，驱散不安，带着希望，迈向远方！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0523BF81ED1F580150E978#第02集$MOE0523BF81ED1F580150E97B#第03集$MOE0523BF81ED1F580150E97A#第04集$MOE0523BF81ED1F580150E97D#第05集$MOE0523BF81ED1F580150E97C#第06集$MOE0523BF81ED1F580150E97F#第07集$MOE0523BF81ED1F580150E97E#第08集$MOE0523BF81ED1F580150E971#第09集$MOE0523BF81ED1F580150E970#第10集$MOE0523BF81ED1F580150E879#第11集$MOE0523BF81ED1F580150E878#第12集$MOE0523BF81ED1F580150E87B#第13集$MOE0523BF81ED1F580150E87A#第14集$MOE0523BF81ED1F580150E87D#第15集$MOE0523BF81ED1F580150E87C#第16集$MOE0523BF81ED1F580150E87F#第17集$MOE0523BF81ED1F580150E87E#第18集$MOE0523BF81ED1F580150E871#第19集$MOE0523BF81ED1F580150E870#第20集$MOE0523BF81ED1F580150EB79#第21集$MOE0523BF81ED1F580150EB78#第22集$MOE0523BF81ED1F580150EB7B#第23集$MOE0523BF81ED1F580150EB7A#第24集$MOE0523BF81ED1F580150EB7D#第25集$MOE0523BF81ED1F580150EB7C$$$第01集$id_XS0523BF81ED1F580150E978#第02集$id_XS0523BF81ED1F580150E97B#第03集$id_XS0523BF81ED1F580150E97A#第04集$id_XS0523BF81ED1F580150E97D#第05集$id_XS0523BF81ED1F580150E97C#第06集$id_XS0523BF81ED1F580150E97F#第07集$id_XS0523BF81ED1F580150E97E#第08集$id_XS0523BF81ED1F580150E971#第09集$id_XS0523BF81ED1F580150E970#第10集$id_XS0523BF81ED1F580150E879#第11集$id_XS0523BF81ED1F580150E878#第12集$id_XS0523BF81ED1F580150E87B#第13集$id_XS0523BF81ED1F580150E87A#第1