INSERT INTO `mac_vod` VALUES (955, 1, 0, 0, '记录的地平线 圆桌崩坏', 'ログ・ホライズン 円卓崩壊（2021）', 'jiludedipingxianyuanzhuobenghuai', 1, 'J', '', '920c6294', '小说改,穿越,战斗,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/26d602c2c6143db78751bc4847f382e20e376481.png', '', '', '', '寺岛拓笃 / 前野智昭 / 加藤英美里 / 中田让治 / 田村奈央 / 松井惠理子 / 柿原彻也 / 原由实 / 高垣彩阳 / 逢坂良太 / 久野美咲 / 村田太志 / 梶川翔平 / 雨宫天 / 佐藤奏美 / 高桥未奈美 / 樱井孝宏 / 名冢佳织 / 日野聪 / 斋藤宽仁 / 西田雅一 / 中村悠一 / 下野纮 / 井泽诗织 / 笹本菜津枝 / 山本祥太 / 后藤弘树 / 寺杣昌纪 / 冈本信彦 / 白熊宽嗣 / 长岛雄一 / 斋藤千和 / 伊丸冈笃 / 宫下荣治 / 井上麻里奈 / 伊濑茉莉也 / 叶', '石平信司 / 铃木勇士 / 渡部稳宽 / 久慈悟郎 / 吉田俊司 / 石田畅', '', '', '以秋叶原为据点的玩家们经过无数次的摸索与挑战，成立的自治机构“圆桌会议”，因西方大国“神圣皇国威斯特兰迪”的政治介入而面临着分崩离析的危机！秋叶原受到了拥有未知能力敌人的袭击，能够拯救危机的，只有低等', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.7, 0, 0, 1738060445, 1738018681, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>以秋叶原为据点的玩家们经过无数次的摸索与挑战，成立的自治机构“圆桌会议”，因西方大国“神圣皇国威斯特兰迪”的政治介入而面临着分崩离析的危机！秋叶原受到了拥有未知能力敌人的袭击，能够拯救危机的，只有低等级的年轻玩家们。曾经感受过无力感的他们，挺身而出，即是展现出成长轨迹的时候！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0825BCDBBF1B540D50E978#第02集$MOE0825BCDBBF1B540D50E97B#第03集$MOE0825BCDBBF1B540D50E97A#第04集$MOE0825BCDBBF1B540D50E97D#第05集$MOE0825BCDBBF1B540D50E97C#第06集$MOE0825BCDBBF1B540D50E97F#第07集$MOE0825BCDBBF1B540D50E97E#第08集$MOE0825BCDBBF1B540D50E971#第09集$MOE0825BCDBBF1B540D50E970#第10集$MOE0825BCDBBF1B540D50E879#第11集$MOE0825BCDBBF1B540D50E878#第12集$MOE0825BCDBBF1B540D50E87B$$$第01集$id_XS0825BCDBBF1B540D50E978#第02集$id_XS0825BCDBBF1B540D50E97B#第03集$id_XS0825BCDBBF1B540D50E97A#第04集$id_XS0825BCDBBF1B540D50E97D#第05集$id_XS0825BCDBBF1B540D50E97C#第06集$id_XS0825BCDBBF1B540D50E97F#第07集$id_XS0825BCDBBF1B540D50E97E#第08集$id_XS0825BCDBBF1B540D50E971#第09集$id_XS0825BCDBBF1B540D50E970#第10集$id_XS0825BCDBBF1B540D50E879#第11集$id_XS0825BCDBBF1B540D50E878#第12集$id_XS0825BCDBBF1B540D50E87B$$$第01集$id_MOE0825BCDBBF1B540D50E978#第02集$id_MOE0825BCDBBF1B540D50E97B#第03集$id_MOE0825BCDBBF1B540D50E97A#第04集$id_MOE0825BCDBBF1B540D50E97D#第05集$id_MOE0825BCDBBF1B