INSERT INTO `mac_vod` VALUES (961, 1, 0, 0, '3月的狮子', '3月のライオン（2016）', '3yuedeshizi', 1, '3', '', '8cb246d3', '漫画改,治愈,励志,日常', 'http://i0.hdslb.com/bfs/bangumi/7bfd5b9a4aabee8df09df12939d2f32c2f41a0d7.jpg', '', '', '', '河西健吾 / 茅野爱衣 / 花泽香菜 / 久野美咲 / 冈本信彦 / 井上麻里奈 / 细谷佳正 / 三木真一郎 / 杉田智和 / 木村昴 / 千叶繁 / 大川透 / 樱井孝宏 / 上田燿司 / 石田彰', '新房昭之 / 城所圣明 / 宫本幸裕 / 板村智幸 / 川畑乔 / 和田纯一 / 吉泽翠 / 大谷肇 / 原英和 / 冈田坚二朗 / 三上喜子', '', '', '独自居住在东京旧市街的17岁职业将棋棋士——桐山零。\r\n他是个幼时就因为意外失去家人，怀抱着深沉孤独的少年。\r\n出现在这样的他面前的，是明里、日向、桃三姐妹。\r\n与她们的相处后，零开始发生些许改变——。', '全44集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.8, 0, 0, 1738162500, 1738019332, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>独自居住在东京旧市街的17岁职业将棋棋士——桐山零。\r\n他是个幼时就因为意外失去家人，怀抱着深沉孤独的少年。\r\n出现在这样的他面前的，是明里、日向、桃三姐妹。\r\n与她们的相处后，零开始发生些许改变——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0974EE8ABD1F090A50E978#第02集$MOE0974EE8ABD1F090A50E97B#第03集$MOE0974EE8ABD1F090A50E97A#第04集$MOE0974EE8ABD1F090A50E97D#第05集$MOE0974EE8ABD1F090A50E97C#第06集$MOE0974EE8ABD1F090A50E97F#第07集$MOE0974EE8ABD1F090A50E97E#第08集$MOE0974EE8ABD1F090A50E971#第09集$MOE0974EE8ABD1F090A50E970#第10集$MOE0974EE8ABD1F090A50E879#第11集$MOE0974EE8ABD1F090A50E878#第11.5集$MOE0974EE8ABD1F090A50E87B#第12集$MOE0974EE8ABD1F090A50E87A#第13集$MOE0974EE8ABD1F090A50E87D#第14集$MOE0974EE8ABD1F090A50E87C#第15集$MOE0974EE8ABD1F090A50E87F#第16集$MOE0974EE8ABD1F090A50E87E#第17集$MOE0974EE8ABD1F090A50E871#第18集$MOE0974EE8ABD1F090A50E870#第19集$MOE0974EE8ABD1F090A50EB79#第20集$MOE0974EE8ABD1F090A50EB78#第21集$MOE0974EE8ABD1F090A50EB7B#第22集$MOE0974EE8ABD1F090A50EB7A#第23集$MOE0974EE8ABD1F090A50EB7D#第24集$MOE0974EE8ABD1F090A50EB7C#第25集$MOE0974EE8ABD1F090A50EB7F#第26集$MOE0974EE8ABD1F090A50EB7E#第27集$MOE0974EE8ABD1F090A50EB71#第28集$MOE0974EE8ABD1F090A50EB70#第29集$MOE0974EE8ABD1F090A50EA79#第30集$MOE0974EE8ABD1F090A50EA78#第31集$MOE0974EE8ABD1F090A50EA7B#第32集$MOE0974EE8ABD1F090A50EA7A#第33集$MOE0974EE8ABD1F090A50EA7D#第34集$MOE0974EE8ABD1F090A50EA7C#第35集$MOE0974EE8ABD1F090A50EA7