INSERT INTO `mac_vod` VALUES (962, 1, 0, 0, '佐贺偶像是传奇', 'ゾンビランドサガ（2018）', 'zuoheouxiangshichuanqi', 1, 'Z', '', '4a56c503', '原创,偶像,搞笑,音乐,励志', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537106539.jpg', '', '', '', '宫野真守 / 本渡枫 / 田野麻美 / 种田梨沙 / 河濑茉希 / 衣川里佳 / 田中美海 / 吉野裕行 / 高户靖广 / 三石琴乃', '境宗久 / 宇田钢之助 / 清水久敏 / 后藤康德', '', '', '巽幸太郎（宫野真守 配音）表面看上去是一个平凡无奇的男子，实际上，他正在策划一个名为“僵尸乐园偶像”的诡异计划，他疯狂的复活了7个可爱的女孩子，让她们成为僵尸偶像，展开了一系列的活动。', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.9, 0, 0, 1738238031, 1738019362, 0, 0, 0, 0, 0.0, '', '971', '', '', '', '', '', '', '', '<p>巽幸太郎（宫野真守 配音）表面看上去是一个平凡无奇的男子，实际上，他正在策划一个名为“僵尸乐园偶像”的诡异计划，他疯狂的复活了7个可爱的女孩子，让她们成为僵尸偶像，展开了一系列的活动。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0576B98EEA1C5D0A50E978#第02集$MOE0576B98EEA1C5D0A50E97B#第03集$MOE0576B98EEA1C5D0A50E97A#第04集$MOE0576B98EEA1C5D0A50E97D#第05集$MOE0576B98EEA1C5D0A50E97C#第06集$MOE0576B98EEA1C5D0A50E97F#第07集$MOE0576B98EEA1C5D0A50E97E#第08集$MOE0576B98EEA1C5D0A50E971#第09集$MOE0576B98EEA1C5D0A50E970#第10集$MOE0576B98EEA1C5D0A50E879#第11集$MOE0576B98EEA1C5D0A50E878#第12集$MOE0576B98EEA1C5D0A50E87B$$$第01集$id_XS0576B98EEA1C5D0A50E978#第02集$id_XS0576B98EEA1C5D0A50E97B#第03集$id_XS0576B98EEA1C5D0A50E97A#第04集$id_XS0576B98EEA1C5D0A50E97D#第05集$id_XS0576B98EEA1C5D0A50E97C#第06集$id_XS0576B98EEA1C5D0A50E97F#第07集$id_XS0576B98EEA1C5D0A50E97E#第08集$id_XS0576B98EEA1C5D0A50E971#第09集$id_XS0576B98EEA1C5D0A50E970#第10集$id_XS0576B98EEA1C5D0A50E879#第11集$id_XS0576B98EEA1C5D0A50E878#第12集$id_XS0576B98EEA1C5D0A50E87B$$$第01集$id_MOE0576B98EEA1C5D0A50E978#第02集$id_MOE0576B98EEA1C5D0A50E97B#第03集$id_MOE0576B98EEA1C5D0A50E97A#第04集$id_MOE0576B98EEA1C5D0A50E97D#第05集$id_MOE0576B98EEA1C5D0A50E97C#第06集$id_MOE0576B98EEA1C5D0A50E97F#第07集$id_MOE0576B98EEA1C5D0A50E97E#第08集$id_MOE0576B98EEA1C5D0A50E971#第09集$id_MOE0576B98EEA1C5D0A50E970#第10集$id_MOE0576B98EEA1C5D0A50E879#第11集$id_MOE0576B98EEA1C5D0A50E878#第12集$id_MOE0576B98EEA1C5D0A50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (963, 1, 0, 0, '爱吃拉面的小泉同学', 'ラーメン大好き小泉さん（2018）', 'aichilamiandexiaoquantongxue', 1, 'A', '', '39508c5a', '治愈,美食,漫画改', 'http://i0.hdslb.com/bfs/bangumi/e4dcc80598a4133af6b1a880bb8006fa5346f31b.jpg', '', '', '', '竹达彩奈 / 佐仓绫音 / 鬼头明里 / 原由实 / 植田佳奈 / 丰崎爱生 / 中村悠一', '濑藤健嗣 / 中村近世 / 村田尚树 / 藏本穗高', '', '', '今天，她也在某处享用着拉面——\r\n冷淡而沉默，不和他人亲近的神秘转学生，小泉同学。她其实是每天追求着美味拉面的拉面专家……！？正统的拉面绘卷，就此上桌！', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.2, 0, 0, 1738162575, 1738019374, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>今天，她也在某处享用着拉面——\r\n冷淡而沉默，不和他人亲近的神秘转学生，小泉同学。她其实是每天追求着美味拉面的拉面专家……！？正统的拉面绘卷，就此上桌！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE022EB988B14A585850E978#第02集$MOE022EB988B14A585850E97B#第03集$MOE022EB988B14A585850E97A#第04集$MOE022EB988B14A585850E97D#第05集$MOE022EB988B14A585850E97C#第06集$MOE022EB988B14A585850E97F#第07集$MOE022EB988B14A585850E97E#第08集$MOE022EB988B14A585850E971#第09集$MOE022EB988B14A585850E970#第10集$MOE022EB988B14A585850E879#第11集$MOE022EB988B14A585850E878#第12集$MOE022EB988B14A585850E87B$$$第01集$id_XS022EB988B14A585850E978#第02集$id_XS022EB988B14A585850E97B#第03集$id_XS022EB988B14A585850E97A#第04集$id_XS022EB988B14A585850E97D#第05集$id_XS022EB988B14A585850E97C#第06集$id_XS022EB988B14A585850E97F#第07集$id_XS022EB988B14A585850E97E#第08集$id_XS022EB988B14A585850E971#第09集$id_XS022EB988B14A585850E970#第10集$id_XS022EB988B14A585850E879#第11集$id_XS022EB988B14A585850E878#第12集$id_XS022EB988B14A585850E87B$$$第01集$id_MOE022EB988B14A585850E978#第02集$id_MOE022EB988B14A585850E97B#第03集$id_MOE022EB988B14A585850E97A#第04集$id_MOE022EB988B14A585850E97D#第05集$id_MOE022EB988B14A585850E97C#第06集$id_MOE022EB988B14A585850E97F#第07集$id_MOE022EB988B14A585850E97E#第08集$id_MOE022EB988B14A585850E971#第09集$id_MOE022EB988B14A585850E970#第10集$id_MOE022EB988B14A585850E879#第11集$id_MOE022EB988B14A585850E878#第12集$id_MOE022EB988B14A585850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (964, 1, 0, 0, 'AIR', '青空（2005）', 'AIR', 1, 'A', '', '2ac7fa71', '奇幻,日常,治愈,催泪', 'http://i0.hdslb.com/bfs/bangumi/6ce4e85797b511f9c77734af7360bda53719df7d.jpg', '', '', '', '小野大辅 / 川上伦子 / 冈本麻见 / 柚木凉香 / 久川绫 / 冬马由美 / 田村由香里 / 今野宏美 / 津田健次郎 / 山本百合子 / 永岛由子 / 金田朋子 / 矢岛晶子 / 野中蓝 / 西村千奈美 / 井上喜久子 / 潘惠子 / 斋藤千和 / 神奈延年', '石原立也 / 木上益治 / 武本康弘 / 山本宽 / 北之原孝将', '', '', '夏天，在靠近海边小小的街道上\r\n一位青年从公共汽车站下车了\r\n青年一直在旅行中\r\n这样的小镇他无心久留\r\n在赚足了路费后，他会去那些更繁华的地方\r\n他的旅伴，是母亲留给他的小小的人偶\r\n他不用手接触，人偶就能动起', '全12集 特别篇', '', 0, '0', '', '', '日本', '日语', '2005', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 44, 0, 44, 44, '', 0, 0, 9.8, 0, 0, 1738216705, 1738019387, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>夏天，在靠近海边小小的街道上\r\n一位青年从公共汽车站下车了\r\n青年一直在旅行中\r\n这样的小镇他无心久留\r\n在赚足了路费后，他会去那些更繁华的地方\r\n他的旅伴，是母亲留给他的小小的人偶\r\n他不用手接触，人偶就能动起来\r\n从母亲那里继承了这种魔法\r\n靠着表演人偶维生，他的旅途才一直能继续着\r\n青年给孩子们表演着人偶戏\r\n然而，简陋的人偶无法吸引孩子们\r\n没有得到报酬的他\r\n无力地站在夏天的烈日下\r\n迷迷糊糊地睡着了……\r\n就在这条海边的街上，青年和命运中的少女相遇了……\r\n\r\n《Air》，是日本Key会社继《Kanon》后，所出品的第二款恋爱AVG（电子小说类游戏）游戏。因为故事感人度极高，在日本也有人称为“泣きゲー” （赚人热泪的游戏）。游戏起初推出时属于“18禁”版，后来推出了“全年龄向”电脑游戏、Dreamcast、PlayStation 2以及PSP版本。该游戏亦被改编成电视动画版和剧场版动画。以夏天为主基调的《AIR》，与Key之前推出的主要发生在冬天的《Kanon》、之后推出的季节为春的《CLANNAD》，都被京都动画改编成动画版本，剧情均十分感人，所以在ACG界，三作被称为“KEY社催泪……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0376EF8FEF485A0850E978#第02集$MOE0376EF8FEF485A0850E97B#第03集$MOE0376EF8FEF485A0850E97A#第04集$MOE0376EF8FEF485A0850E97D#第05集$MOE0376EF8FEF485A0850E97C#第06集$MOE0376EF8FEF485A0850E97F#第07集$MOE0376EF8FEF485A0850E97E#第08集$MOE0376EF8FEF485A0850E971#第09集$MOE0376EF8FEF485A0850E970#第10集$MOE0376EF8FEF485A0850E879#第11集$MOE0376EF8FEF485A0850E878#第12集$MOE0376EF8FEF485A0850E87B#特别篇 前篇：山路$MOE0376EF8FEF485A0850E87A#特别篇 后篇：天地$MOE0376EF8FEF485A0850E87D$$$第01集$id_XS0376EF8FEF485A0850E978#第02集$id_XS0376EF8FEF485A0850E97B#第03集$id_XS0376EF8FEF485A0850E97A#第04集$id_XS0376EF8FEF485A0850E97D#第05集$id_XS0376EF8FEF485A0850E97C#第06集$id_XS0376EF8FEF485A0850E97F#第07集$id_XS0376EF8FEF485A0850E97E#第08集$id_XS0376EF8FEF485A0850E971#第09集$id_XS0376EF8FEF485A0850E970#第10集$id_XS0376EF8FEF485A0850E879#第11集$id_XS0376EF8FEF485A0850E878#第12集$id_XS0376EF8FEF485A0850E87B#特别篇 前篇：山路$id_XS0376EF8FEF485A0850E87A#特别篇 后篇：天地$id_XS0376EF8FEF485A0850E87D$$$第01集$id_MOE0376EF8FEF485A0850E978#第02集$id_MOE0376EF8FEF485A0850E97B#第03集$id_MOE0376EF8FEF485A0850E97A#第04集$id_MOE0376EF8FEF485A0850E97D#第05集$id_MOE0376EF8FEF485A0850E97C#第06集$id_MOE0376EF8FEF485A0850E97F#第07集$id_MOE0376EF8FEF485A0850E97E#第08集$id_MOE0376EF8FEF485A0850E971#第09集$id_MOE0376EF8FEF485A0850E970#第10集$id_MOE0376EF8FEF485A0850E879#第11集$id_MOE0376EF8FEF485A0850E878#第12集$id_MOE0376EF8FEF485A0850E87B#特别篇 前篇：山路$id_MOE0376EF8FEF485A0850E87A#特别篇 后篇：天地$id_MOE0376EF8FEF485A0850E87D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (965, 2, 0, 0, 'AIR 剧场版', '青空 剧场版（2005）', 'AIRjuchangban', 1, 'A', '', '96cc53a6', '奇幻,日常,治愈', 'http://i0.hdslb.com/bfs/bangumi/b7d9f6ce8812046b6ebc7882e21cb3f87fc2c78c.png', '', '', '', '川上伦子 / 久川绫 / 绿川光 / 西村千奈美 / 井上喜久子 / 神奈延年 / 冬马由美 / 今野宏美 / 永岛由子 / 潘惠子 / Michio Nakao / Aki Sasaki / Kanako Tateno / Sayaka Maeno', '出崎统', '', '', '　　“很久很久以前，在某个地方，有位长着翅膀的公主，她孤单一人，身边没有一个朋友”在一个能看见海和天空的小镇，很久以前就流传着这样一个故事。背上长着白色翅膀的公主 和守护她的少年之间凄美的爱情故事。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2005', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 7.8, 0, 0, 1738216864, 1738103855, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>　　“很久很久以前，在某个地方，有位长着翅膀的公主，她孤单一人，身边没有一个朋友”在一个能看见海和天空的小镇，很久以前就流传着这样一个故事。背上长着白色翅膀的公主 和守护她的少年之间凄美的爱情故事。 公主因为有着不同于常人的身体，一直被关在房间，看不到外面的世界。听说自己的母亲在很远的地方，却不能去和她想见。某一天，在孤独的公主面前出现了一个少年。少年会说些外面的事情来逗公主开心。就这样不知不觉两人相爱了。但是，却有个诅咒——有翅膀的人是根本不能有爱情的。 少女——神尾观铃 觉得孤单的自己和故事里的公主很像。体弱多病的观铃不能去上学，也没有朋友。从来没有离开过这个城市。但是，她一直期待着，说不定自己会有和故事里的公主一样的邂逅。在这样的观铃的面前，出现了一个少年——国崎往人。他是一个边为别人做人偶边旅行的少年。他死去的母亲曾对他说，“去救在空中的少女”虽然受到诅咒 仍依然相爱的有翅膀的公主和守护她的少年，与公主际遇相似的少女。还有为拯救“空中的少女”而踏上旅途的少年 现在和过去相互交错，思念超越了时空的界限。他们各自的恋情 会有一个怎么样的结果呢？</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0821EFDBBC1A0C0F50E978$$$正片$id_MOE0821EFDBBC1A0C0F50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (966, 1, 0, 0, 'GAMERS电玩咖！', 'ゲーマーズ！（2017）', 'GAMERSdianwanka', 1, 'G', '', 'b8e97e39', '小说改,校园,社团', 'http://i0.hdslb.com/bfs/bangumi/c4b692ad88d42f18d3c55acf8cf2204dc6b0086c.jpg', '', '', '', '潘惠美 / 金元寿子 / 石见舞菜香 / 大久保瑠美 / 丰永利行 / 花江夏树 / 内匠靖明 / 芳野由奈', '冈本学 / 宫泽良太 / 上坪亮树 / 米田光宏 / 中津环 / 水本叶月 / 小野田雄亮 / 野木森达哉', '', '', '“……和我一起，试着加入游戏部怎样？”兴趣是游戏，除此之外毫无显眼的特征，仅仅是个龙套的游戏玩家雨野景太，某天突然被学园第一的美少女，游戏部部长天道花怜搭话了。\r\n由此开始，景太的日常为之一转，开始了与', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.2, 0, 0, 1738217294, 1738170101, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“……和我一起，试着加入游戏部怎样？”兴趣是游戏，除此之外毫无显眼的特征，仅仅是个龙套的游戏玩家雨野景太，某天突然被学园第一的美少女，游戏部部长天道花怜搭话了。\r\n由此开始，景太的日常为之一转，开始了与喜爱游戏的美少女们共度的恋爱喜剧展开的日子……本以为如此！？只有游戏的价值观不同，特立独行的女子玩家星之守千秋。班上的中心人物，虽然有女友却私下里爱好游戏的残念现充上原祐。祐的女友，毫无游戏知识的亚玖璃。\r\n将这些人物一并卷入，重复着互相误会、徒劳无功、陷入迷途，乱成一团的游戏玩家们带来的“擦肩而过青春错综系恋爱喜剧”开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE532FE981BE4C5E0050E978#第02集$MOE532FE981BE4C5E0050E97B#第03集$MOE532FE981BE4C5E0050E97A#第04集$MOE532FE981BE4C5E0050E97D#第05集$MOE532FE981BE4C5E0050E97C#第06集$MOE532FE981BE4C5E0050E97F#第07集$MOE532FE981BE4C5E0050E97E#第08集$MOE532FE981BE4C5E0050E971#第09集$MOE532FE981BE4C5E0050E970#第10集$MOE532FE981BE4C5E0050E879#第11集$MOE532FE981BE4C5E0050E878#第12集$MOE532FE981BE4C5E0050E87B$$$第01集$id_XS532FE981BE4C5E0050E978#第02集$id_XS532FE981BE4C5E0050E97B#第03集$id_XS532FE981BE4C5E0050E97A#第04集$id_XS532FE981BE4C5E0050E97D#第05集$id_XS532FE981BE4C5E0050E97C#第06集$id_XS532FE981BE4C5E0050E97F#第07集$id_XS532FE981BE4C5E0050E97E#第08集$id_XS532FE981BE4C5E0050E971#第09集$id_XS532FE981BE4C5E0050E970#第10集$id_XS532FE981BE4C5E0050E879#第11集$id_XS532FE981BE4C5E0050E878#第12集$id_XS532FE981BE4C5E0050E87B$$$第01集$id_MOE532FE981BE4C5E0050E978#第02集$id_MOE532FE981BE4C5E0050E97B#第03集$id_MOE532FE981BE4C5E0050E97A#第04集$id_MOE532FE981BE4C5E0050E97D#第05集$id_MOE532FE981BE4C5E0050E97C#第06集$id_MOE532FE981BE4C5E0050E97F#第07集$id_MOE532FE981BE4C5E0050E97E#第08集$id_MOE532FE981BE4C5E0050E971#第09集$id_MOE532FE981BE4C5E0050E970#第10集$id_MOE532FE981BE4C5E0050E879#第11集$id_MOE532FE981BE4C5E0050E878#第12集$id_MOE532FE981BE4C5E0050E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (967, 1, 0, 0, 'Little Busters!', 'リトルバスターズ！（2012）', 'LittleBusters', 1, 'L', '', '8f5cc6fe', '校园,日常,治愈,励志', 'http://i0.hdslb.com/bfs/bangumi/image/e4d3dbad653a8091328143e262fac7c1d0da515d.png', '', '', '', '堀江由衣 / 民安智惠 / 绿川光 / 神奈延年 / 织田优成 / 柳濑夏美 / 铃木惠子 / 若林直美 / 田中凉子 / 巽悠衣子 / 德井青空 / 神田朱未 / 野中蓝 / 广桥凉 / 花泽香菜 / 本多阳子 / 平井理子 / 鸭之宫优 / 大川透 / 滨田贤二 / 小形满 / 松本忍 / 水岛大宙 / 岸尾大辅 / 田中敦子 / 村田太志 / 岛崎信长 / 杉田智和', '山川吉树 / 樱井亲良 / 岩崎良明 / 铃木洋平 / 八谷贤一 / 松泽建一 / 铃木健太郎 / 上田茂 / 桥本敏一 / 高岛大辅 / 小野田雄亮 / 大岛博之 / 冈村正弘', '', '', '《Little Busters!》是根据Key社发行的同名美少女游戏改编的电视动画，由J.C.STAFF制作。故事的主题是青春与友情，讲述了自幼父母双亡的主人公直枝理树，在深陷绝望之时被一个名为“Li', '全26集 OVA', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.7, 0, 0, 1738217525, 1738170107, 0, 0, 0, 0, 0.0, '', '968,969', '', '', '', '', '', '', '', '<p>《Little Busters!》是根据Key社发行的同名美少女游戏改编的电视动画，由J.C.STAFF制作。故事的主题是青春与友情，讲述了自幼父母双亡的主人公直枝理树，在深陷绝望之时被一个名为“Little Busters”（枣恭介、枣铃、井之原真人、宫泽谦吾）的四人组拯救了出来。之后从阴暗中走出来的理树也加入了这支号称“正义的使者”的队伍中并与恶势力作斗争。现在已升入高中的他们，正在围绕着恭介的提案——组成一支沿用“Little Busters”这个名字的棒球队伍，在棒球场上挥洒着青春。但是，某一天理树和铃在一只猫身上发现了写着“寻找这个世界的秘密”的小纸条之后，他们的日常生活渐渐发生了变化……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0971B9DBEA1F0B5C50E978#第02集$MOE0971B9DBEA1F0B5C50E97B#第03集$MOE0971B9DBEA1F0B5C50E97A#第04集$MOE0971B9DBEA1F0B5C50E97D#第05集$MOE0971B9DBEA1F0B5C50E97C#第06集$MOE0971B9DBEA1F0B5C50E97F#第07集$MOE0971B9DBEA1F0B5C50E97E#第08集$MOE0971B9DBEA1F0B5C50E971#第09集$MOE0971B9DBEA1F0B5C50E970#第10集$MOE0971B9DBEA1F0B5C50E879#第11集$MOE0971B9DBEA1F0B5C50E878#第12集$MOE0971B9DBEA1F0B5C50E87B#第13集$MOE0971B9DBEA1F0B5C50E87A#第14集$MOE0971B9DBEA1F0B5C50E87D#第15集$MOE0971B9DBEA1F0B5C50E87C#第16集$MOE0971B9DBEA1F0B5C50E87F#第17集$MOE0971B9DBEA1F0B5C50E87E#第18集$MOE0971B9DBEA1F0B5C50E871#第19集$MOE0971B9DBEA1F0B5C50E870#第20集$MOE0971B9DBEA1F0B5C50EB79#第21集$MOE0971B9DBEA1F0B5C50EB78#第22集$MOE0971B9DBEA1F0B5C50EB7B#第23集$MOE0971B9DBEA1F0B5C50EB7A#第24集$MOE0971B9DBEA1F0B5C50EB7D#第25集$MOE0971B9DBEA1F0B5C50EB7C#第26集$MOE0971B9DBE