INSERT INTO `mac_vod` VALUES (968, 1, 0, 0, 'Little Busters! ～Refrain～', 'リトルバスターズ！〜Refrain〜（2013）', 'LittleBustersRefrain', 1, 'L', '', '988c57d1', '校园,励志,游戏改', 'http://i0.hdslb.com/bfs/bangumi/94e6df21c816a824da404e466f73529761a75e68.jpg', '', '', '', '堀江由衣 / 民安智惠 / 绿川光 / 神奈延年 / 织田优成 / 柳濑夏美 / 铃木惠子 / 若林直美 / 田中凉子 / 河原木志穗 / 德井青空 / 神田朱未 / 野中蓝 / 广桥凉 / 花泽香菜 / 樱井浩美 / 平井理子 / 鸭之宫优 / 游佐浩二 / 近藤孝行 / 潘惠美 / 松本忍 / 杉田智和', '山川吉树 / 樱井亲良 / 铃木健太郎 / 松泽建一 / 桥本敏一 / 冈村正弘 / 守田艺成 / 樱美胜志', '', '', '幼时曾深陷绝望深渊的直枝理树，与4位少年少女相遇了。在那之后数年，理树作为Little Busters的一员，喧闹地过着快乐的每一天，“这样的时间能够一直持续就好了”理树所期望的只有这样。某日，恭介突', '全13集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.8, 0, 0, 1738217605, 1738201852, 0, 0, 0, 0, 0.0, '', '969', '', '', '', '', '', '', '', '<p>幼时曾深陷绝望深渊的直枝理树，与4位少年少女相遇了。在那之后数年，理树作为Little Busters的一员，喧闹地过着快乐的每一天，“这样的时间能够一直持续就好了”理树所期望的只有这样。某日，恭介突然表示要成立一支棒球队伍，理树则开始了寻找成员的任务。在这样的过程中，理树邂逅了新的成员们，和大家一起参加试胆大会，潜入女生宿舍时被换上女装，一起演人偶剧……。\r\n经历了许多快乐的事情，同时也在大家的帮助下解决了各自拥有的烦恼。在最后在棒球比赛中，理树确认了和最好的朋友们之间的牵绊。然而，这并不是结束，和来谷唯湖之间的故事，理树与铃的故事，以及理树和铃终于知晓的“世界的秘密”。Little Busters真正的物语，自此开始。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE082FB4DBBC1E090850E978#第02集$MOE082FB4DBBC1E090850E97B#第03集$MOE082FB4DBBC1E090850E97A#第04集$MOE082FB4DBBC1E090850E97D#第05集$MOE082FB4DBBC1E090850E97C#第06集$MOE082FB4DBBC1E090850E97F#第07集$MOE082FB4DBBC1E090850E97E#第08集$MOE082FB4DBBC1E090850E971#第09集$MOE082FB4DBBC1E090850E970#第10集$MOE082FB4DBBC1E090850E879#第11集$MOE082FB4DBBC1E090850E878#第12集$MOE082FB4DBBC1E090850E87B#第13集$MOE082FB4DBBC1E090850E87A$$$第01集$id_XS082FB4DBBC1E090850E978#第02集$id_XS082FB4DBBC1E090850E97B#第03集$id_XS082FB4DBBC1E090850E97A#第04集$id_XS082FB4DBBC1E090850E97D#第05集$id_XS082FB4DBBC1E090850E97C#第06集$id_XS082FB4DBBC1E090850E97F#第07集$id_XS082FB4DBBC1E090850E97E#第08集$id_XS082FB4DBBC1E090850E971#第09集$id_XS082FB4DBBC1E090850E970#第10集$id_XS082FB4DBBC1E090850E879#第11集$id_XS082FB4DBBC1E090850E878#第12集$id_XS082FB4DBBC1E090850E87B#第13集$id_XS082FB4DBBC1E090850E87A$$$第01集$id_MOE082FB4DBBC1E090850E978#第02集$id_MOE082FB4DBBC1E090850E97B#第03集$id_MOE082FB4DBBC1E090850E97A#第04集$id_MOE082FB4DBBC1E090850E97D#第05集$id_MOE082FB4DBBC1E090850E97C#第06集$id_MOE082FB4DBBC1E090850E97F#第07集$id_MOE082FB4DBBC1E090850E97E#第08集$id_MOE082FB4DBBC1E090850E971#第09集$id_MOE082FB4DBBC1E090850E970#第10集$id_MOE082FB4DBBC1E090850E879#第11集$id_MOE082FB4DBBC1E090850E878#第12集$id_MOE082FB4DBBC1E090850E87B#第13集$id_MOE082FB4DBBC1E090850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (969, 1, 0, 0, 'Little Busters! EX', 'リトルバスターズ！EX（2014）', 'LittleBustersEX', 1, 'L', '', '6f95ce36', '校园,日常,治愈,励志', 'http://i0.hdslb.com/bfs/bangumi/18e4ebae9e5a2395aef71978d4a4184947581b82.png', '', '', '', '堀江由衣 / 民安智惠 / 绿川光 / 神奈延年 / 织田优成 / 柳濑夏美 / 田中凉子 / 铃木惠子 / 若林直美 / 河原木志穗 / 德井青空 / 樱井浩美', '山川吉树 / 铃木洋平 / 铃木健太郎 / 桥本敏一', '', '', '正篇讲述关系很亲密的5个人组成的小组织“Little Busters”的成员——少年直枝理树和领袖人物枣恭介为了享受最后的高中生活而组建了一支棒球队“Little Busters”，然后棒球队的成员们', '全8集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.8, 0, 0, 1738217690, 1738201858, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>正篇讲述关系很亲密的5个人组成的小组织“Little Busters”的成员——少年直枝理树和领袖人物枣恭介为了享受最后的高中生活而组建了一支棒球队“Little Busters”，然后棒球队的成员们遇到了各种各样的烦恼的故事，本作作为特典动画剧情分别由佳奈多、佐佐美、沙耶这三名女性角色，主要会围绕她们各自的故事展开。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0771B58DEA4C5E0F50E978#第02集$MOE0771B58DEA4C5E0F50E97B#第03集$MOE0771B58DEA4C5E0F50E97A#第04集$MOE0771B58DEA4C5E0F50E97D#第05集$MOE0771B58DEA4C5E0F50E97C#第06集$MOE0771B58DEA4C5E0F50E97F#第07集$MOE0771B58DEA4C5E0F50E97E#第08集$MOE0771B58DEA4C5E0F50E971$$$第01集$id_XS0771B58DEA4C5E0F50E978#第02集$id_XS0771B58DEA4C5E0F50E97B#第03集$id_XS0771B58DEA4C5E0F50E97A#第04集$id_XS0771B58DEA4C5E0F50E97D#第05集$id_XS0771B58DEA4C5E0F50E97C#第06集$id_XS0771B58DEA4C5E0F50E97F#第07集$id_XS0771B58DEA4C5E0F50E97E#第08集$id_XS0771B58DEA4C5E0F50E971$$$第01集$id_MOE0771B58DEA4C5E0F50E978#第02集$id_MOE0771B58DEA4C5E0F50E97B#第03集$id_MOE0771B58DEA4C5E0F50E97A#第04集$id_MOE0771B58DEA4C5E0F50E97D#第05集$id_MOE0771B58DEA4C5E0F50E97C#第06集$id_MOE0771B58DEA4C5E0F50E97F#第07集$id_MOE0771B58DEA4C5E0F50E97E#第08集$id_MOE0771B58DEA4C5E0F50E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (970, 1, 0, 0, '可塑性记忆', 'プラスティック･メモリーズ（2015）', 'kesuxingjiyi', 1, 'K', '', 'bf04faa0', '科幻,青春,恋爱,治愈', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2256661990.jpg', '', '', '', '内匠靖明 / 雨宫天 / 赤崎千夏 / 矢作纱友里 / 丰口惠美 / 日野聪 / 爱美 / 上坂堇 / 飞田展男 / 拜真之介 / 津田健次郎', '藤原佳幸 / 菅原静贵 / 山崎光惠 / 饭野慎也 / 木村泰大 / 木野目优 / 野木森达哉', '', '', '故事发生在科技飞速发展的未来世界，彼时，人工智能机器人早已经不是罕见之物，正慢慢地融入人类的生活之中。高考落榜之后，十八岁的青年水柿司（内匠靖明 配音）在父母的帮助下来到了SAI社工作，SAI社的主要', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 55, 0, 55, 55, '', 0, 0, 8.1, 0, 0, 1738223655, 1738216263, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在科技飞速发展的未来世界，彼时，人工智能机器人早已经不是罕见之物，正慢慢地融入人类的生活之中。高考落榜之后，十八岁的青年水柿司（内匠靖明 配音）在父母的帮助下来到了SAI社工作，SAI社的主要产品即是名为“Giftia”的人形智能机器人。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5371BC8CEF480C0950E978#第02集$MOE5371BC8CEF480C0950E97B#第03集$MOE5371BC8CEF480C0950E97A#第04集$MOE5371BC8CEF480C0950E97D#第05集$MOE5371BC8CEF480C0950E97C#第06集$MOE5371BC8CEF480C0950E97F#第07集$MOE5371BC8CEF480C0950E97E#第08集$MOE5371BC8CEF480C0950E971#第09集$MOE5371BC8CEF480C0950E970#第10集$MOE5371BC8CEF480C0950E879#第11集$MOE5371BC8CEF480C0950E878#第12集$MOE5371BC8CEF480C0950E87B#第13集$MOE5371BC8CEF480C0950E87A$$$第01集$id_XS5371BC8CEF480C0950E978#第02集$id_XS5371BC8CEF480C0950E97B#第03集$id_XS5371BC8CEF480C0950E97A#第04集$id_XS5371BC8CEF480C0950E97D#第05集$id_XS5371BC8CEF480C0950E97C#第06集$id_XS5371BC8CEF480C0950E97F#第07集$id_XS5371BC8CEF480C0950E97E#第08集$id_XS5371BC8CEF480C0950E971#第09集$id_XS5371BC8CEF480C0950E970#第10集$id_XS5371BC8CEF480C0950E879#第11集$id_XS5371BC8CEF480C0950E878#第12集$id_XS5371BC8CEF480C0950E87B#第13集$id_XS5371BC8CEF480C0950E87A$$$第01集$id_MOE5371BC8CEF480C0950E978#第02集$id_MOE5371BC8CEF480C0950E97B#第03集$id_MOE5371BC8CEF480C0950E97A#第04集$id_MOE5371BC8CEF480C0950E97D#第05集$id_MOE5371BC8CEF480C0950E97C#第06集$id_MOE5371BC8CEF480C0950E97F#第07集$id_MOE5371BC8CEF480C0950E97E#第08集$id_MOE5371BC8CEF480C0950E971#第09集$id_MOE5371BC8CEF480C0950E970#第10集$id_MOE