INSERT INTO `mac_vod` VALUES (972, 1, 0, 0, '虫师', '蟲師（2005）', 'chongshi', 1, 'C', '', '6dffdec0', '奇幻,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/16e973742216b68db7bcc5642b20be5e6af2ef9f.png', '', '', '', '中野裕斗 / 土井美加 / 泽城美雪 / 上田祐司 / 名冢佳织 / 小林爱', '长滨博史 / 今泉贤一 / 长井龙雪 / 长峰达也 / 山崎理 / 五十岚卓哉 / 宫下新平 / 成田岁法 / 五月女浩一朗 / 真野玲 / 井之川慎太郎 / 宫田亮', '', '', '这里的虫既不是动植物，也与微生物和菌类不同，是更接近生命原生态的东西。这些东西总称为“虫”。它们的形态和存在都很暧昧，当人与虫的世界重叠之时，发生了超越人类智慧的怪异现象，此时人类才开始知道它们的存在', '全26集', '', 0, '0', '', '', '日本', '日语', '2005', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 9.9, 0, 0, 1738303327, 1738217977, 0, 0, 0, 0, 0.0, '', '978', '', '', '', '', '', '', '', '<p>这里的虫既不是动植物，也与微生物和菌类不同，是更接近生命原生态的东西。这些东西总称为“虫”。它们的形态和存在都很暧昧，当人与虫的世界重叠之时，发生了超越人类智慧的怪异现象，此时人类才开始知道它们的存在。 \r\n所谓生命，并非为威胁异己而存在。只是，各自以各自的形态存在着——作为连接这样的”虫“与人类的”虫师“--主人公银古，在旅途中不断与各种各样的人及与其关联的虫相遇。绘就了每话登场人物各不相同，读不尽的画卷。\r\n\r\n 《虫师》是由漫画家漆原友纪所创作的漫画，于1999年开始在月刊Afternoon隔月连载。2008年十月号的Afternoon杂志上连载9年的治愈系漫画《虫师》走完自己的连载生涯和喜爱自己的读者告别。\r\n &nbsp; 另有Artland公司制作的动画和2007年大友克洋执导的电影</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0773EADEED4C0E0950E978#第02集$MOE0773EADEED4C0E0950E97B#第03集$MOE0773EADEED4C0E0950E97A#第04集$MOE0773EADEED4C0E0950E97D#第05集$MOE0773EADEED4C0E0950E97C#第06集$MOE0773EADEED4C0E0950E97F#第07集$MOE0773EADEED4C0E0950E97E#第08集$MOE0773EADEED4C0E0950E971#第09集$MOE0773EADEED4C0E0950E970#第10集$MOE0773EADEED4C0E0950E879#第11集$MOE0773EADEED4C0E0950E878#第12集$MOE0773EADEED4C0E0950E87B#第13集$MOE0773EADEED4C0E0950E87A#第14集$MOE0773EADEED4C0E0950E87D#第15集$MOE0773EADEED4C0E0950E87C#第16集$MOE0773EADEED4C0E0950E87F#第17集$MOE0773EADEED4C0E0950E87E#第18集$MOE0773EADEED4C0E0950E871#第19集$MOE0773EADEED4C0E0950E870#第20集$MOE0773EADEED4C0E0950EB79#第21集$MOE0773EADEED4C0E0950EB78#第22集$MOE0773EADEED4C0E0950EB7B#第23集$MOE0773EADEED4C0E0950EB7A#第24集$MOE0773EADEED4C0E0950EB7D#第25集$MOE0773EADEED4C0E0950EB7C#第26集$MOE0773EADEED4C0E0950EB7F$$$第01集$id_XS0773EADEED4C0E0950E978#第02集$id_XS0773EADEED4C0E0950E97B#第03集$id_XS0773EADEED4C0E0950E97A#第04集$id_XS0773EADEE