INSERT INTO `mac_vod` VALUES (973, 1, 0, 0, '绝园的暴风雨', '絶園のテンペスト（2012）', 'jueyuandebaofengyu', 1, 'J', '', 'a7c2cf95', '冒险,穿越,战斗,推理', 'http://i0.hdslb.com/bfs/bangumi/eec6dc6e75d9a9c0bd89931db172b020c75834df.jpg', '', '', '', '内山昂辉 / 丰永利行 / 泽城美雪 / 水树奈奈 / 小山力也 / 吉野裕行 / 梶裕贵 / 浅沼晋太郎 / 野岛裕史 / 诹访部顺一 / 花泽香菜', '安藤真裕 / 浅井义之 / 宫下新平 / 塚田拓郎 / 伊藤秀树 / 佐藤育郎 / 安斋刚文 / 间岛崇宽 / 清水久敏 / 园田雅裕 / 绵田慎也 / 高桥健司', '', '', '【本片翻译由恶魔岛字幕组提供】某一天，最强的魔法使公主锁部叶风被部下左门暗算，困在了无人荒岛；又有一天，一位少女被唐突杀害，犯人还未逮捕时间却已流逝；然后又在某一天，围绕着复仇与魔法，超越时间与空间的', '全24集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.6, 0, 0, 1738316770, 1738217983, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由恶魔岛字幕组提供】某一天，最强的魔法使公主锁部叶风被部下左门暗算，困在了无人荒岛；又有一天，一位少女被唐突杀害，犯人还未逮捕时间却已流逝；然后又在某一天，围绕着复仇与魔法，超越时间与空间的战斗正式揭开了序幕！\r\n正气和狂气，理性和知性，自信和确信。\r\n在悲剧性的不合理的世界里，少年少女们的命运交缠纠结，故事开始了！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5020EF8AEA4F540C50E978#第02集$MOE5020EF8AEA4F540C50E97B#第03集$MOE5020EF8AEA4F540C50E97A#第04集$MOE5020EF8AEA4F540C50E97D#第05集$MOE5020EF8AEA4F540C50E97C#第06集$MOE5020EF8AEA4F540C50E97F#第07集$MOE5020EF8AEA4F540C50E97E#第08集$MOE5020EF8AEA4F540C50E971#第09集$MOE5020EF8AEA4F540C50E970#第10集$MOE5020EF8AEA4F540C50E879#第11集$MOE5020EF8AEA4F540C50E878#第12集$MOE5020EF8AEA4F540C50E87B#第13集$MOE5020EF8AEA4F540C50E87A#第14集$MOE5020EF8AEA4F540C50E87D#第15集$MOE5020EF8AEA4F540C50E87C#第16集$MOE5020EF8AEA4F540C50E87F#第17集$MOE5020EF8AEA4F540C50E87E#第18集$MOE5020EF8AEA4F540C50E871#第19集$MOE5020EF8AEA4F540C50E870#第20集$MOE5020EF8AEA4F540C50EB79#第21集$MOE5020EF8AEA4F540C50EB78#第22集$MOE5020EF8AEA4F540C50EB7B#第23集$MOE5020EF8AEA4F540C50EB7A#第24集$MOE5020EF8AEA4F540C50EB7D$$$第01集$id_XS5020EF8AEA4F540C50E978#第02集$id_XS5020EF8AEA4F540C50E97B#第03集$id_XS5020EF8AEA4F540C50E97A#第04集$id_XS5020EF8AEA4F540C50E97D#第05集$id_XS5020EF8AEA4F540C50E97C#第06集$id_XS5020EF8AEA4F540C50E97F#第07集$id_XS5020EF8AEA4F540C50E97E#第08集$id_XS5020EF8AEA4F540C50E971#第09集$id_XS5020EF8AEA4F540C50E970#第10集$id_XS5020EF8AEA4F540C