INSERT INTO `mac_vod` VALUES (974, 1, 0, 0, 'ACCA13区监察课', 'ACCA13区監察課（2017）', 'ACCA13qujianchake', 1, 'A', '', '66b5cc6e', '漫画改,奇幻,智斗', 'http://i0.hdslb.com/bfs/bangumi/0aad6593530a088c531272b9c9c0a3b81db30317.jpg', '', '', '', '下野纮 / 津田健次郎 / 诹访部顺一 / 游佐浩二 / 大川透 / 绿川光 / 安元洋贵 / 悠木碧 / 田中敦子 / 宫野真守 / 上村祐翔', '夏目真悟 / 葛谷直行 / 若林信 / 八田洋介 / 小岛庆祐 / 重原克也 / 武藤信宏 / 吉川志我津', '', '', '存在于分为13个自治区的王国中的，巨大统一组织“ACCA”。\r\n由于过去的政变危机而结成的ACCA，已持续守护了国民的和平百年之久。\r\nACCA本部监察课副课长吉恩·奥塔斯，是个有着“蹭烟的吉恩”这一绰号', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.8, 0, 0, 1738316923, 1738217990, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>存在于分为13个自治区的王国中的，巨大统一组织“ACCA”。\r\n由于过去的政变危机而结成的ACCA，已持续守护了国民的和平百年之久。\r\nACCA本部监察课副课长吉恩·奥塔斯，是个有着“蹭烟的吉恩”这一绰号的、组织里头号难对付的男人。\r\n他一边漫不经心地抽着烟，一边走遍13区进行对不法行为的视察。\r\n盯上这样的吉恩的视线、危险的传闻以及——点心时间。 \r\n吉恩的和平日常，慢慢被卷入世界的阴谋！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0721EE8DEA4A5B5C50E978#第02集$MOE0721EE8DEA4A5B5C50E97B#第03集$MOE0721EE8DEA4A5B5C50E97A#第04集$MOE0721EE8DEA4A5B5C50E97D#第05集$MOE0721EE8DEA4A5B5C50E97C#第06集$MOE0721EE8DEA4A5B5C50E97F#第07集$MOE0721EE8DEA4A5B5C50E97E#第08集$MOE0721EE8DEA4A5B5C50E971#第09集$MOE0721EE8DEA4A5B5C50E970#第10集$MOE0721EE8DEA4A5B5C50E879#第11集$MOE0721EE8DEA4A5B5C50E878#第12集$MOE0721EE8DEA4A5B5C50E87B$$$第01集$id_XS0721EE8DEA4A5B5C50E978#第02集$id_XS0721EE8DEA4A5B5C50E97B#第03集$id_XS0721EE8DEA4A5B5C50E97A#第04集$id_XS0721EE8DEA4A5B5C50E97D#第05集$id_XS0721EE8DEA4A5B5C50E97C#第06集$id_XS0721EE8DEA4A5B5C50E97F#第07集$id_XS0721EE8DEA4A5B5C50E97E#第08集$id_XS0721EE8DEA4A5B5C50E971#第09集$id_XS0721EE8DEA4A5B5C50E970#第10集$id_XS0721EE8DEA4A5B5C50E879#第11集$id_XS0721EE8DEA4A5B5C50E878#第12集$id_XS0721EE8DEA4A5B5C50E87B$$$第01集$id_MOE0721EE8DEA4A5B5C50E978#第02集$id_MOE0721EE8DEA4A5B5C50E97B#第03集$id_MOE0721EE8DEA4A5B5C50E97A#第04集$id_MOE0721EE8DEA4A5B5C50E97D#第05集$id_MOE0721EE8DEA4A5B5C50E97C#第06集$id_MOE0721EE8DEA4A5B5C50E97F#第07集$id_MOE0721EE8DEA4A5B5C50E97E#第08集$id_MOE0721EE8DEA4A5B5C50E971#第09集$id_