INSERT INTO `mac_vod` VALUES (975, 1, 0, 0, '幸运星', 'らき☆すた（2007）', 'xingyunxing', 1, 'X', '', 'ed0cd91a', '萌系,搞笑,日常,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/70f18db49c45e7d338f95602f4c12d97e26479f9.png', '', '', '', '平野绫 / 福原香织 / 加藤英美里 / 远藤绫', '山本宽 / 武本康弘 / 石原立也 / 石立太一 / 坂本一也 / 吉冈忍 / 北之原孝将 / 高雄统子 / 木上益治', '', '', '本片讲述的是一群喜爱动漫的高中女生们的日常生活。其中主角泉此方更是为了喜欢的东西会不惜一切的女孩子，整天出入OTAKU们的的圣地秋叶原、到女仆沏茶店打工、天天都有COSPLAY。这样一名标准的AKIB', '全24集 OVA', '', 0, '0', '', '', '日本', '日语', '2007', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 47, 0, 47, 47, '', 0, 0, 9.9, 0, 0, 1738323270, 1738217999, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本片讲述的是一群喜爱动漫的高中女生们的日常生活。其中主角泉此方更是为了喜欢的东西会不惜一切的女孩子，整天出入OTAKU们的的圣地秋叶原、到女仆沏茶店打工、天天都有COSPLAY。这样一名标准的AKIBA系OTAKU的她，和相对平常的柊姐妹、みゆき等好朋友一起演绎着一幕幕欢快喧嚣的、令人意外却很日常化的故事。总之，原作就是那种平常到很无聊，但是闲暇时看着却很有趣的泡沫4格。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5473BCDBED105C5850E978#第02集$MOE5473BCDBED105C5850E97B#第03集$MOE5473BCDBED105C5850E97A#第04集$MOE5473BCDBED105C5850E97D#第05集$MOE5473BCDBED105C5850E97C#第06集$MOE5473BCDBED105C5850E97F#第07集$MOE5473BCDBED105C5850E97E#第08集$MOE5473BCDBED105C5850E971#第09集$MOE5473BCDBED105C5850E970#第10集$MOE5473BCDBED105C5850E879#第11集$MOE5473BCDBED105C5850E878#第12集$MOE5473BCDBED105C5850E87B#第13集$MOE5473BCDBED105C5850E87A#第14集$MOE5473BCDBED105C5850E87D#第15集$MOE5473BCDBED105C5850E87C#第16集$MOE5473BCDBED105C5850E87F#第17集$MOE5473BCDBED105C5850E87E#第18集$MOE5473BCDBED105C5850E871#第19集$MOE5473BCDBED105C5850E870#第20集$MOE5473BCDBED105C5850EB79#第21集$MOE5473BCDBED105C5850EB78#第22集$MOE5473BCDBED105C5850EB7B#第23集$MOE5473BCDBED105C5850EB7A#第24集$MOE5473BCDBED105C5850EB7D#OVA$MOE5473BCDBED105C5850EB7C$$$第01集$id_XS5473BCDBED105C5850E978#第02集$id_XS5473BCDBED105C5850E97B#第03集$id_XS5473BCDBED105C5850E97A#第04集$id_XS5473BCDBED105C5850E97D#第05集$id_XS5473BCDBED105C5850E97C#第06集$id_XS5473BCDBED105C5850E97F#第07集$id_XS5473BCDBED105C5850E97E#第08集$id_XS5473BCDBED105C5850E971#第09集$id_XS5473BCDBED105C5850E970#第10集$id_XS5473BCDBED105C5850E879#第11集$id_XS5473BCD