INSERT INTO `mac_vod` VALUES (976, 1, 0, 0, 'NANA', 'NANA -ナナ-（2006）', 'NANA', 1, 'N', '', '44f60468', '日常,少女,音乐', 'http://i0.hdslb.com/bfs/bangumi/a58a947c478aa0532a699899c63c46c8851b98d6.jpg', '', '', '', '朴璐美 / 川菜翠 / 木内秀信 / 川原庆久 / 关智一 / 石田彰 / 平野绫 / 森川智之 / 诹访部顺一 / 本田贵子 / 高桥广树 / 小岛惠 / 金井美香 / 胜杏里 / 周防玲子 / 千叶纱子 / 立木文彦 / 滨田贤二 / 藤井启辅', '浅香守生 / 中村亮介 / 石塚敦子 / 谷田部胜义 / 钉宫洋 / 高桥亨 / 岛崎奈奈子 / 鹤冈耕次郎 / 广川和之 / 若林汉二 / 千叶大辅 / 池田重隆 / 渡边正彦', '', '', '【本片翻译由灵风工作室提供。因年代久远，无法联系到当时的字幕制作人，欢迎提供联系方式或联系该字幕负责人联系我们，如有任何意见和建议，请通过站内信的方式联系悲伤柠檬（http://space.bilib', '全47集', '', 0, '0', '', '', '日本', '日语', '2006', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 40, 0, 40, 40, '', 0, 0, 9.6, 0, 0, 1738905174, 1738218006, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由灵风工作室提供。因年代久远，无法联系到当时的字幕制作人，欢迎提供联系方式或联系该字幕负责人联系我们，如有任何意见和建议，请通过站内信的方式联系悲伤柠檬（http://space.bilibili.com/26468349）我们会着重跟进处理】\r\n在这个世界上，总能找到和你同样的名字的人。或许在你们相遇的时候，你们的命运就会交错在一起。\r\n　　小松奈奈和大崎娜娜的名字都叫NANA，但她们却是从性格到经历都不相同的两个女孩子。小松奈奈天真可爱，但生于温室里的她不懂世故，在小天地里只有她的男朋友。大崎娜娜来自破碎的家庭，她性格坚强，行事果断，渴望成为一个朋克乐手。命运让这两个性格截然相反的NANA在生命的驿站中相遇了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0523EA8EB91D5B0150E978#第02集$MOE0523EA8EB91D5B0150E97B#第03集$MOE0523EA8EB91D5B0150E97A#第04集$MOE0523EA8EB91D5B0150E97D#第05集$MOE0523EA8EB91D5B0150E97C#第06集$MOE0523EA8EB91D5B0150E97F#第07集$MOE0523EA8EB91D5B0150E97E#第08集$MOE0523EA8EB91D5B0150E971#第09集$MOE0523EA8EB91D5B0150E970#第10集$MOE0523EA8EB91D5B0150E879#第11集$MOE0523EA8EB91D5B0150E878#第11.5集$MOE0523EA8EB91D5B0150E87843F9#第12集$MOE0523EA8EB91D5B0150E87B#第13集$MOE0523EA8EB91D5B0150E87A#第14集$MOE0523EA8EB91D5B0150E87D#第15集$MOE0523EA8EB91D5B0150E87C#第16集$MOE0523EA8EB91D5B0150E87F#第17集$MOE0523EA8EB91D5B0150E87E#第18集$MOE0523EA8EB91D5B0150E871#第19集$MOE0523EA8EB91D5B0150E870#第20集$MOE0523EA8EB91D5B0150EB79#第21集$MOE0523EA8EB91D5B0150EB78#第21.5集$MOE0523EA8EB91D5B0150EB7843F9#第22集$MOE0523EA8EB91D5B0150EB7B#第23集$MOE0523EA8EB91D5B0150EB7A#第24集$MOE0523EA8EB91D5B0150EB7D#第25集$MOE0523EA8EB91D5B0150EB7C#第26集$MOE0523EA8EB91D5B0150