INSERT INTO `mac_vod` VALUES (981, 1, 0, 0, '棋魂', 'ヒカルの碁（2001）', 'qihun', 1, 'Q', '', 'c22c46c7', '漫画改,热血,奇幻,励志', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315357261.jpg', '', '', '', '川上伦子 / 千叶进步 / 小林沙苗 / 嘉数由美 / 津村真琴 / 伊藤健太郎 / 津田英三 / 藤原启治 / 浅川悠 / 樱井孝宏 / 高木礼子 / 铃村健一 / 水田山葵 / 榎本温子 / 纳谷六朗 / 铃木晶子 / 川村拓央 / 重松朋 / 渡边明乃 / 伊藤和晃 / 松冈洋子 / 山口隆行 / 坂东尚树 / 高濑右光 / 西村知道 / 岩田光央 / 石住昭彦 / 楠见尚己 / 小西克幸 / 清水敏孝 / 吉野裕行 / 北川胜博 / 游佐浩二 / 坂口贤一 / 桑原利晃 / 石波义人 / 桧山修之', '西泽晋 / 神谷纯 / 远藤彻哉 / 谷田部胜义 / 殿胜秀树 / 大隈孝晴 / 小坂春女 / 政木伸一 / 冈岛国敏 / 新留俊哉 / 所智一 / 野中卓也 / 高濑节夫 / 饭岛正胜 / 成田岁法 / 三宅雄一郎', '', '', '六年级的小学生进藤光（川上友子 配音）无意中翻出了爷爷家的旧棋盘。触碰棋盘的一瞬间也释放出了寄居在其上的平安时代棋士藤原佐为（千叶进步 配音）的灵魂。附身于小光体内的佐为视棋如命，小光在其软磨硬泡下开', '全75集', '', 0, '0', '', '', '日本', '日语', '2001', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.3, 0, 0, 1738905345, 1738878560, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>六年级的小学生进藤光（川上友子 配音）无意中翻出了爷爷家的旧棋盘。触碰棋盘的一瞬间也释放出了寄居在其上的平安时代棋士藤原佐为（千叶进步 配音）的灵魂。附身于小光体内的佐为视棋如命，小光在其软磨硬泡下开始下围棋，接触了一批厉害的棋士，其中不乏他的同龄人。小光开始对围棋产生兴趣并展现了他的天分，而佐为则成为了小光的秘密老师……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5225BEDBBD1F0E0E50E978#第02集$MOE5225BEDBBD1F0E0E50E97B#第03集$MOE5225BEDBBD1F0E0E50E97A#第04集$MOE5225BEDBBD1F0E0E50E97D#第05集$MOE5225BEDBBD1F0E0E50E97C#第06集$MOE5225BEDBBD1F0E0E50E97F#第07集$MOE5225BEDBBD1F0E0E50E97E#第08集$MOE5225BEDBBD1F0E0E50E971#第09集$MOE5225BEDBBD1F0E0E50E970#第10集$MOE5225BEDBBD1F0E0E50E879#第11集$MOE5225BEDBBD1F0E0E50E878#第12集$MOE5225BEDBBD1F0E0E50E87B#第13集$MOE5225BEDBBD1F0E0E50E87A#第14集$MOE5225BEDBBD1F0E0E50E87D#第15集$MOE5225BEDBBD1F0E0E50E87C#第16集$MOE5225BEDBBD1F0E0E50E87F#第17集$MOE5225BEDBBD1F0E0E50E87E#第18集$MOE5225BEDBBD1F0E0E50E871#第19集$MOE5225BEDBBD1F0E0E50E870#第20集$MOE5225BEDBBD1F0E0E50EB79#第21集$MOE5225BEDBBD1F0E0E50EB78#第22集$MOE5225BEDBBD1F0E0E50EB7B#第23集$MOE5225BEDBBD1F0E0E50EB7A#第24集$MOE5225BEDBBD1F0E0E50EB7D#第25集$MOE5225BEDBBD1F0E0E50EB7C#第26集$MOE5225BEDBBD1F0E0E50EB7F#第27集$MOE5225BEDBBD1F0E0E50EB7E#第28集$MOE5225BEDBBD1F0E0E50EB71#第29集$MOE5225BEDBBD1F0