INSERT INTO `mac_vod` VALUES (982, 2, 0, 0, '声之形', '聲の形（2016）', 'shengzhixing', 1, 'S', '', 'fedf7d74', '动画,爱情,剧情,漫画改', 'http://i0.hdslb.com/bfs/bangumi/4b4599ee150cf537444d68dd155718f65999b5b5.jpg', '', '', '', '入野自由 / 早见沙织 / 悠木碧 / 小野贤章 / 金子有希 / 石川由依 / 潘惠美 / 丰永利行 / 松冈茉优 / 小岛幸子 / 武田华 / 小松史法 / 谷育子 / 镰田英怜奈 / 滨口绫乃 / 绵贯龙之介 / 西谷亮 / 增元拓也 / 雪野五月 / 平松晶子', '山田尚子', '', '', '西宫硝子（早见沙织 配音）天生患有听觉障碍，需依靠助听器与外界交流，她的口语发音也因此显得格外古怪。初中时，硝子转去了一所新学校，生理缺陷让她成为了班上的“独特”存在，她因此收获了友情，却也遭到了以男', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 9.5, 0, 0, 1738936943, 1738923829, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>西宫硝子（早见沙织 配音）天生患有听觉障碍，需依靠助听器与外界交流，她的口语发音也因此显得格外古怪。初中时，硝子转去了一所新学校，生理缺陷让她成为了班上的“独特”存在，她因此收获了友情，却也遭到了以男生石田将也（入野自由 配音）为首的小团体的欺凌。无论是出于少年无心，还是恶童有意，随着时间的推移，事态逐渐升级，一系列的事件之后，最终演变成为了无法挽回的伤害，硝子也永远地消失在了众人的眼前……</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5772E8DEBE4D5A0D50E978$$$正片$id_MOE5772E8DEBE4D5A0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (983, 2, 0, 0, '秒速五厘米', '秒速5センチメートル（2007）', 'miaosuwulimi', 1, 'M', '', '8526d39f', '催泪,日常', 'http://i0.hdslb.com/bfs/bangumi/image/4fed6a1e2e9aae0f171c904c36c23384586e8d90.png', '', '', '', '水桥研二 / 近藤好美 / 花村怜美 / 尾上绫华 / 水野理纱 / 寺崎裕香 / 中村祐子 / 岩崎征实 / 内藤玲 / 下崎纮史 / 平野贵裕 / 中川玲 / 井关佳子 / 井上优 / 加古临王 / 中村梨香 / 须加美纪 / 鲑延未可 / 新鹿由美子 / 斋藤由香子', '新海诚', '', '', '【本片翻译由澄空学园字幕组提供】秒速五厘米是日本导演新海诚在2007年发布的动画电影，全作由《樱花抄》、《宇航员》和《秒速五厘米》三话组成。导演结合樱花、电车、卫星等美丽的意象，讲述了围绕着男主角远野', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2007', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 18, 0, 18, 18, '', 0, 0, 9.6, 0, 0, 1738938544, 1738923933, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>【本片翻译由澄空学园字幕组提供】秒速五厘米是日本导演新海诚在2007年发布的动画电影，全作由《樱花抄》、《宇航员》和《秒速五厘米》三话组成。导演结合樱花、电车、卫星等美丽的意象，讲述了围绕着男主角远野贵树和女主角篠原明里、澄田花苗之间所发生的唯美而又忧伤的故事。\r\n\r\n少年远野贵树与少女筱原明里，这两人是幼时的同班同学兼好友，但自从小学毕业之后却没能再见一次面。分隔两地的贵树与明里一直靠书信保持联络，直到贵树知道自己即将举家搬到鹿儿岛那个遥远的地方。两人约定了见面的时间，但计划好的行程偏偏却遇上了暴风雪……。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0922BE8EED1A545F50E978$$$正片$id_MOE0922BE8EED1A545F50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (984, 2, 0, 0, '萤火虫之墓', '火垂るの墓（1988）', 'yinghuochongzhimu', 1, 'Y', '', 'fd9c5b74', '剧场版', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237136718.jpg', '', '', '', '辰己努 / 白石绫乃 / 志乃原良子 / 山口朱美 / 端田宏三', '高畑勋', '', '', '美日战争爆发，14岁的清太带着年幼的妹妹到处逃命，当他们到达防空洞的时候，母亲已身受重伤，没过多久便不久人世。两兄妹自此过着相依为命的日子。他们只好投靠了母亲的姐妹，纵使他们把家里所有的家当都送给了阿', '简中1080P', '', 0, '0', '', '', '日本', '日语', '1988', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 8.7, 0, 0, 1738946260, 1738936317, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>美日战争爆发，14岁的清太带着年幼的妹妹到处逃命，当他们到达防空洞的时候，母亲已身受重伤，没过多久便不久人世。两兄妹自此过着相依为命的日子。他们只好投靠了母亲的姐妹，纵使他们把家里所有的家当都送给了阿姨，但当食物吃完，他们就越感到了寄人篱下的感觉，清太决定带着妹妹离开独自生活。火灾硝烟中的生活并不好过，清太为了妹妹四处偷取食物，但妹妹还是严重营养不良……</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5773B5DBBC4B5A0D50E978$$$正片$id_MOE5773B5DBBC4B5A0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (985, 2, 0, 0, '萤火之森', '蛍火の杜へ（2011）', 'yinghuozhisen', 1, 'Y', '', '7bf3c968', '漫画改,神魔,催泪,恋爱', 'http://i0.hdslb.com/bfs/bangumi/image/5e235a8a197f19be5df56da14676d9e264a601aa.jpg', '', '', '', '佐仓绫音 / 内山昂辉 / 辻亲八 / 山本兼平 / 后藤弘树 / 今井麻美', '大森贵弘', '', '', '6岁的少女竹川萤，在暑假回到乡下爷爷家的路上，在住满山神、妖怪的“山神之森”迷了路。这时，一名戴着面具的少年银，答应把萤带出森林。银是一位半人半妖的少年，若他一触碰到人类便会消失，所以萤不能触碰到银。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2011', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.7, 0, 0, 1738969491, 1738936471, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>6岁的少女竹川萤，在暑假回到乡下爷爷家的路上，在住满山神、妖怪的“山神之森”迷了路。这时，一名戴着面具的少年银，答应把萤带出森林。银是一位半人半妖的少年，若他一触碰到人类便会消失，所以萤不能触碰到银。之后，在每一年的夏天，萤都会回到乡下，希望与银重聚，年复一年，变得亭亭玉立的萤与银之间也产生了相恋的感觉，可是他们连相互触碰也做不到。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0675EA8BEA105B0150E978$$$正片$id_MOE0675EA8BEA105B0150E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (986, 2, 0, 0, '我想吃掉你的胰脏', '君の膵臓をたべたい（2018）', 'woxiangchidiaonideyizang', 1, 'W', '', '5968fdeb', '恋爱,青春', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545571306.jpg', '', '', '', '高杉真宙 / Lynn / 藤井雪代 / 内田雄马 / 福岛润 / 田中敦子 / 三木真一郎', '牛岛新一郎', '', '', '“没有名字的我，没有未来的她”', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 31, 0, 31, 31, '', 0, 0, 6.9, 0, 0, 1738969620, 1738946292, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“没有名字的我，没有未来的她”</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS042EBA80EF4D085B50E978$$$正片$id_MOE042EBA80EF4D085B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (987, 3, 0, 0, '朝花夕誓', 'さよならの朝に約束の花をかざろう（2018）', 'chaohuaxishi', 1, 'C', '', '2d9d4b2c', '奇幻,治愈', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545561196.jpg', '', '', '', '石见舞菜香 / 入野自由 / 樱井优辉 / 茅野爱衣 / 梶裕贵 / 细谷佳正 / 佐藤利奈 / 日笠阳子 / 泽城美雪 / 杉田智和 / 久野美咲 / 平田广明 / 徐斌 / 栗本有规 / 宍户准之介 / 岩川泰千 / 岩崎博 / 河本启佑 / 咲野俊介 / 伊东美弥子 / 浅野麻由美 / 莲岳大 / 内田夕夜 / 前田爱 / 松川央树 / 岩崎谅太 / 本桥大辅 / 水中雅章 / 柳田淳一 / 川上晃太 / 佐佐健太 / 岛袋美由利 / 矢野奖吾 / 笠间淳 / 藤间隼 / 绵贯龙之介', '冈田麿里 / 筱原俊哉', '', '', '故事发生在一座名为伊奥鲁夫的城市中，在这里出生的人们拥有无限的寿命，外表却会定格在15岁的模样，玛奇亚（石见舞菜香 配音）就是这样一个土生土长的伊奥鲁夫少女。一天，为了抢夺永生之血，梅萨蒂军乘坐着古代', '简中4K', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 151, 0, 151, 151, '', 0, 0, 6.9, 0, 0, 1738987909, 1738946518, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在一座名为伊奥鲁夫的城市中，在这里出生的人们拥有无限的寿命，外表却会定格在15岁的模样，玛奇亚（石见舞菜香 配音）就是这样一个土生土长的伊奥鲁夫少女。一天，为了抢夺永生之血，梅萨蒂军乘坐着古代神兽对伊奥鲁夫发动了空袭，造成了惨重的损失，玛奇亚的好友蕾莉亚（茅野爱衣 配音）被掠走了，和蕾莉亚一起失踪的，还有玛奇亚暗恋的少年克里姆（梶裕贵 配音）。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0373B5DCBD4B5F5A50E978$$$正片$id_MOE0373B5DCBD4B5F5A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (988, 1, 0, 0, '噬神者', 'ゴッドイーター（2015）', 'shishenzhe', 1, 'S', '', 'c9d5057d', '科幻,奇幻,游戏改,热血', 'http://i0.hdslb.com/bfs/bangumi/fe032695a01c4b04385306b9b2a5aed565e341cf.jpg', '', '', '', '木岛隆一 / 平田广明 / 坂本真绫 / 中井和哉 / 阪口大助 / 大原沙耶香 / 福井裕佳梨 / 田中敦子 / 楠大典 / 小山力也', '平尾隆之', '', '', '这是五十年后的未来，世界被“神”吞噬殆尽而荒芜的架空故事。 由于遭到突如其来的怪物“荒神”的破坏而失去平衡。在人类文明既有的兵器都因荒神的“捕食”本能而无效化下，生化科技企业“芬里尔”成功利用荒神细胞', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.4, 0, 0, 1739008694, 1738981888, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是五十年后的未来，世界被“神”吞噬殆尽而荒芜的架空故事。 由于遭到突如其来的怪物“荒神”的破坏而失去平衡。在人类文明既有的兵器都因荒神的“捕食”本能而无效化下，生化科技企业“芬里尔”成功利用荒神细胞开发出了名为“神机”的生物兵器。并同时组织了特殊部队“GOD EATER”。自此，人类终于获得了与荒神对抗的力量。\r\n于是，追求知性之极致的荒神，与追求物种延续的人类之间的战争便此展开。在破灭的尽头，究竟是神会先成为人，还是人会先成为神呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE522EE88DB91C5A5D50E978#第02集$MOE522EE88DB91C5A5D50E97B#第03集$MOE522EE88DB91C5A5D50E97A#第04集$MOE522EE88DB91C5A5D50E97D#第05集$MOE522EE88DB91C5A5D50E97C#第06集$MOE522EE88DB91C5A5D50E97F#第07集$MOE522EE88DB91C5A5D50E97E#第08集$MOE522EE88DB91C5A5D50E971#第09集$MOE522EE88DB91C5A5D50E970#第10集$MOE522EE88DB91C5A5D50E879#第11集$MOE522EE88DB91C5A5D50E878#第12集$MOE522EE88DB91C5A5D50E87B#第13集$MOE522EE88DB91C5A5D50E87A$$$第01集$id_XS522EE88DB91C5A5D50E978#第02集$id_XS522EE88DB91C5A5D50E97B#第03集$id_XS522EE88DB91C5A5D50E97A#第04集$id_XS522EE88DB91C5A5D50E97D#第05集$id_XS522EE88DB91C5A5D50E97C#第06集$id_XS522EE88DB91C5A5D50E97F#第07集$id_XS522EE88DB91C5A5D50E97E#第08集$id_XS522EE88DB91C5A5D50E971#第09集$id_XS522EE88DB91C5A5D50E970#第10集$id_XS522EE88DB91C5A5D50E879#第11集$id_XS522EE88DB91C5A5D50E878#第12集$id_XS522EE88DB91C5A5D50E87B#第13集$id_XS522EE88DB91C5A5D50E87A$$$第01集$id_MOE522EE88DB91C5A5D50E978#第02集$id_MOE522EE88DB91C5A5D50E97B#第03集$id_MOE522EE88DB91C5A5D50E97A#第04集$id_MOE522EE88DB91C5A5D50E97D#第05集$id_MOE522EE88DB91C5A5D50E97C#第06集$id_MOE522EE88DB91C5A5D50E97F#第07集$id_MOE522EE88DB91C5A5D50E97E#第08集$id_MOE522EE88DB91C5A5D50E971#第09集$id_MOE522EE88DB91C5A5D50E970#第10集$id_MOE522EE88DB91C5A5D50E879#第11集$id_MOE522EE88DB91C5A5D50E878#第12集$id_MOE522EE88DB91C5A5D50E87B#第13集$id_MOE522EE88DB91C5A5D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (989, 1, 0, 0, '刀剑乱舞-花丸-', '刀剣乱舞-花丸-（2016）', 'daojianluanwuhuawan', 1, 'D', '', 'dab1dd74', '游戏改,日常,架空', 'http://i0.hdslb.com/bfs/bangumi/8f67ccb853ce59adbe233da59ff6cd644a05d453.jpg', '', '', '', '市来光弘 / 增田俊树 / 新垣樽助 / 山下大辉 / 入江玲于奈 / 间岛淳司 / 兴津和幸 / 滨健人 / 齐藤壮马 / 石川界人 / 泰勇气 / 山下诚一郎 / 佐藤拓也 / 粕谷雄太 / 前野智昭 / 逢坂良太 / 高桥英则', '直谷隆 / 日色如夏 / 高村雄太 / 江副仁美 / 儿谷直树 / 藏本穗高 / 深濑重 / 由井翠 / 伊部勇志', '', '', '时为公元2205年。\r\n是以改变历史为目的的“历史修正主义者”开始对过去实施攻击的时代。\r\n被赋予了守护历史这一使命的“审神者”，由他们所唤起的最强付丧神“刀剑男士”。\r\n这是，他们以“某个本丸”为舞台，一', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.7, 0, 0, 1739018696, 1738983248, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>时为公元2205年。\r\n是以改变历史为目的的“历史修正主义者”开始对过去实施攻击的时代。\r\n被赋予了守护历史这一使命的“审神者”，由他们所唤起的最强付丧神“刀剑男士”。\r\n这是，他们以“某个本丸”为舞台，一心一意、开朗明快地生活的“花丸”日常物语——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5576EE89ED4D5A0D50E978#第02集$MOE5576EE89ED4D5A0D50E97B#第03集$MOE5576EE89ED4D5A0D50E97A#第04集$MOE5576EE89ED4D5A0D50E97D#第05集$MOE5576EE89ED4D5A0D50E97C#第06集$MOE5576EE89ED4D5A0D50E97F#第07集$MOE5576EE89ED4D5A0D50E97E#第08集$MOE5576EE89ED4D5A0D50E971#第09集$MOE5576EE89ED4D5A0D50E970#第10集$MOE5576EE89ED4D5A0D50E879#第11集$MOE5576EE89ED4D5A0D50E878#第12集$MOE5576EE89ED4D5A0D50E87B$$$第01集$id_XS5576EE89ED4D5A0D50E978#第02集$id_XS5576EE89ED4D5A0D50E97B#第03集$id_XS5576EE89ED4D5A0D50E97A#第04集$id_XS5576EE89ED4D5A0D50E97D#第05集$id_XS5576EE89ED4D5A0D50E97C#第06集$id_XS5576EE89ED4D5A0D50E97F#第07集$id_XS5576EE89ED4D5A0D50E97E#第08集$id_XS5576EE89ED4D5A0D50E971#第09集$id_XS5576EE89ED4D5A0D50E970#第10集$id_XS5576EE89ED4D5A0D50E879#第11集$id_XS5576EE89ED4D5A0D50E878#第12集$id_XS5576EE89ED4D5A0D50E87B$$$第01集$id_MOE5576EE89ED4D5A0D50E978#第02集$id_MOE5576EE89ED4D5A0D50E97B#第03集$id_MOE5576EE89ED4D5A0D50E97A#第04集$id_MOE5576EE89ED4D5A0D50E97D#第05集$id_MOE5576EE89ED4D5A0D50E97C#第06集$id_MOE5576EE89ED4D5A0D50E97F#第07集$id_MOE5576EE89ED4D5A0D50E97E#第08集$id_MOE5576EE89ED4D5A0D50E971#第09集$id_MOE5576EE89ED4D5A0D50E970#第