INSERT INTO `mac_vod` VALUES (990, 1, 0, 0, '零之使魔', 'ゼロの使い魔（2006）', 'lingzhishimo', 1, 'L', '', '992e6430', '日常,战斗,恋爱,架空', 'http://i0.hdslb.com/bfs/bangumi/7fe6ad684ad228b7d9d643160b40fae4b9694c72.jpg', '', '', '', '钉宫理惠 / 日野聪 / 堀江由衣', '岩崎良明', '', '', '在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载着四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才能的主人样露易丝。面对突然出现的迷之美少女，满心疑', '全13集', '', 0, '0', '', '', '日本', '日语', '2006', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 9.4, 0, 0, 1739078468, 1738983257, 0, 0, 0, 0, 0.0, '', '991,995,996', '', '', '', '', '', '', '', '<p>在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载着四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才能的主人样露易丝。面对突然出现的迷之美少女，满心疑惑的才人在听她讲完契约内容之后，遭遇了突如其来的强吻之后，他的手背上浮现出了不可思议的文字，才人就这样莫名其妙的成为了露易丝的使魔。\r\n　　以全寄宿制的托丽斯汀魔法学院为舞台，主人样美少女魔法使露易丝与使魔才人在争吵、责备、爱恋中开始了充满了勇气与屈辱的学园生活。在异世界波澜万丈的交流之中，露易丝和才人的命运会怎么样呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE082EBEDDBF1D5E0950E978#第02集$MOE082EBEDDBF1D5E0950E97B#第03集$MOE082EBEDDBF1D5E0950E97A#第04集$MOE082EBEDDBF1D5E0950E97D#第05集$MOE082EBEDDBF1D5E0950E97C#第06集$MOE082EBEDDBF1D5E0950E97F#第07集$MOE082EBEDDBF1D5E0950E97E#第08集$MOE082EBEDDBF1D5E0950E971#第09集$MOE082EBEDDBF1D5E0950E970#第10集$MOE082EBEDDBF1D5E0950E879#第11集$MOE082EBEDDBF1D5E0950E878#第12集$MOE082EBEDDBF1D5E0950E87B#第13集$MOE082EBEDDBF1D5E0950E87A$$$第01集$id_XS082EBEDDBF1D5E0950E978#第02集$id_XS082EBEDDBF1D5E0950E97B#第03集$id_XS082EBEDDBF1D5E0950E97A#第04集$id_XS082EBEDDBF1D5E0950E97D#第05集$id_XS082EBEDDBF1D5E0950E97C#第06集$id_XS082EBEDDBF1D5E0950E97F#第07集$id_XS082EBEDDBF1D5E0950E97E#第08集$id_XS082EBEDDBF1D5E0950E971#第09集$id_XS082EBEDDBF1D5E0950E970#第10集$id_XS082EBEDDBF1D5E0950E879#第11集$id_XS082EBEDDBF1D5E0950E878#第12集$id_XS082EBEDDBF1D5E0950E87B#第13集$id_XS082EBEDDBF1D5E0950E87A$$$第01集$id_MOE082EBEDDBF1D5E0950E978#第02集$id_MOE082EBEDDBF1D5E0950E97B#第03集$id_MOE082EBEDDBF1D5E0950E97A#第04集$id_MOE082EBEDDBF1D5E0950E97D#第05集$id_MOE082EBEDDBF1D5E0950E97C#第06集$id_MOE082EBEDDBF1D5E0950E97F#第07集$id_MOE082EBEDDBF1D5E0950E97E#第08集$id_MOE082EBEDDBF1D5E0950E971#第09集$id_MOE082EBEDDBF1D5E0950E970#第10集$id_MOE082EBEDDBF1D5E0950E879#第11集$id_MOE082EBEDDBF1D5E0950E878#第12集$id_MOE082EBEDDBF1D5E0950E87B#第13集$id_MOE082EBEDDBF1D5E0950E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (991, 1, 0, 0, '零之使魔 双月骑士', 'ゼロの使い魔 ～双月の騎士～（2007）', 'lingzhishimoshuangyueqishi', 1, 'L', '', '5eb8dd04', '奇幻,战斗,小说改,架空', 'http://i0.hdslb.com/bfs/bangumi/70ff3f06e424edf935e4d56f63bb586e1dec76be.jpg', '', '', '', '釘宮理恵 / 日野聡', '紅優', '', '', '在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载着四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才能的主人样露易丝。面对突然出现的迷之美少女，满心疑', '全12集', '', 0, '0', '', '', '日本', '日语', '2007', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.2, 0, 0, 1739078535, 1738983266, 0, 0, 0, 0, 0.0, '', '995,996', '', '', '', '', '', '', '', '<p>在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载着四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才能的主人样露易丝。面对突然出现的迷之美少女，满心疑惑的才人在听她讲完契约内容之后，遭遇了突如其来的强吻之后，他的手背上浮现出了不可思议的文字，才人就这样莫名其妙的成为了露易丝的使魔。\r\n　　以全寄宿制的托丽斯汀魔法学院为舞台，主人样美少女魔法使露易丝与使魔才人在争吵、责备、爱恋中开始了充满了勇气与屈辱的学园生活。在异世界波澜万丈的交流之中，露易丝和才人的命运会怎么样呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0472EE80ED4D5D0D50E978#第02集$MOE0472EE80ED4D5D0D50E97B#第03集$MOE0472EE80ED4D5D0D50E97A#第04集$MOE0472EE80ED4D5D0D50E97D#第05集$MOE0472EE80ED4D5D0D50E97C#第06集$MOE0472EE80ED4D5D0D50E97F#第07集$MOE0472EE80ED4D5D0D50E97E#第08集$MOE0472EE80ED4D5D0D50E971#第09集$MOE0472EE80ED4D5D0D50E970#第10集$MOE0472EE80ED4D5D0D50E879#第11集$MOE0472EE80ED4D5D0D50E878#第12集$MOE0472EE80ED4D5D0D50E87B$$$第01集$id_XS0472EE80ED4D5D0D50E978#第02集$id_XS0472EE80ED4D5D0D50E97B#第03集$id_XS0472EE80ED4D5D0D50E97A#第04集$id_XS0472EE80ED4D5D0D50E97D#第05集$id_XS0472EE80ED4D5D0D50E97C#第06集$id_XS0472EE80ED4D5D0D50E97F#第07集$id_XS0472EE80ED4D5D0D50E97E#第08集$id_XS0472EE80ED4D5D0D50E971#第09集$id_XS0472EE80ED4D5D0D50E970#第10集$id_XS0472EE80ED4D5D0D50E879#第11集$id_XS0472EE80ED4D5D0D50E878#第12集$id_XS0472EE80ED4D5D0D50E87B$$$第01集$id_MOE0472EE80ED4D5D0D50E978#第02集$id_MOE0472EE80ED4D5D0D50E97B#第03集$id_MOE0472EE80ED4D5D0D50E97A#第04集$id_MOE0472EE80ED4D5D0D50E97D#第05集$id_MOE0472EE80ED4D5D0D50E97C#第06集$id_MOE0472EE80ED4D5D0D50E97F#第07集$id_MOE0472EE80ED4D5D0D50E97E#第08集$id_MOE0472EE80ED4D5D0D50E971#第09集$id_MOE0472EE80ED4D5D0D50E970#第10集$id_MOE0472