INSERT INTO `mac_vod` VALUES (995, 1, 0, 0, '零之使魔 三美姬的轮舞', 'ゼロの使い魔 ～三美姫の輪舞～（2008）', 'lingzhishimo3sanmeijidelunwu', 1, 'L', '', '7e570f26', '小说改,奇幻,战斗,架空', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2390559006.jpg', '', '', '', '釘宮理恵 / 日野聡 / 堀江由衣', '紅優', '', '', '关键字：“恋爱”、“冒险”、“主人样”和“使魔”。在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载这四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 7.3, 0, 0, 1739078649, 1739066177, 0, 0, 0, 0, 0.0, '', '996', '', '', '', '', '', '', '', '<p>关键字：“恋爱”、“冒险”、“主人样”和“使魔”。在异世界哈尔凯尼亚被当作“使魔”被召唤出来的高中生平贺才人卷入了一场满载这四种元素的幻想罗曼史大冒险中。将才人召唤至异世界的是长相可爱却没有丝毫魔法才能的主人样·露依斯。面对突然出现的迷之美少女，满心疑惑的才人在听她讲完契约内容之后，遭遇了突如其来的强吻……之后，他的手背上浮现出了不可思议的文字，才人就这样莫名其妙的成为了露依斯的使魔……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0672B98FB94F5F0F50E978#第02集$MOE0672B98FB94F5F0F50E97B#第03集$MOE0672B98FB94F5F0F50E97A#第04集$MOE0672B98FB94F5F0F50E97D#第05集$MOE0672B98FB94F5F0F50E97C#第06集$MOE0672B98FB94F5F0F50E97F#第07集$MOE0672B98FB94F5F0F50E97E#第08集$MOE0672B98FB94F5F0F50E971#第09集$MOE0672B98FB94F5F0F50E970#第10集$MOE0672B98FB94F5F0F50E879#第11集$MOE0672B98FB94F5F0F50E878#第12集$MOE0672B98FB94F5F0F50E87B#OVA$MOE0672B98FB94F5F0F50E87A$$$第01集$id_XS0672B98FB94F5F0F50E978#第02集$id_XS0672B98FB94F5F0F50E97B#第03集$id_XS0672B98FB94F5F0F50E97A#第04集$id_XS0672B98FB94F5F0F50E97D#第05集$id_XS0672B98FB94F5F0F50E97C#第06集$id_XS0672B98FB94F5F0F50E97F#第07集$id_XS0672B98FB94F5F0F50E97E#第08集$id_XS0672B98FB94F5F0F50E971#第09集$id_XS0672B98FB94F5F0F50E970#第10集$id_XS0672B98FB94F5F0F50E879#第11集$id_XS0672B98FB94F5F0F50E878#第12集$id_XS0672B98FB94F5F0F50E87B#OVA$id_XS0672B98FB94F5F0F50E87A$$$第01集$id_MOE0672B98FB94F5F0F50E978#第02集$id_MOE0672B98FB94F5F0F50E97B#第03集$id_MOE0672B98FB94F5F0F50E97A#第04集$id_MOE0672B98FB94F5F0F50E97D#第05集$id_MOE0672B98FB94F5F0F50E97C#第06集$id_MOE0672B98FB94F5F0F50E97F#第07集$id_MOE0672B98FB94F5F0F50E97E#第08集$id_MOE0672B98FB94F5F0F50E971#第09集$id_MOE0672B98FB94F5F0F50E970#第10集$id_MOE