INSERT INTO `mac_vod` VALUES (1000, 1, 0, 0, '通灵王', 'シャーマンキング（2021）', 'tonglingwang', 1, 'T', '', 'b6b3aa4e', '漫画改,热血,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/1cd26af47cf9d9ca045ec36f56ce14a66867438d.png', '', '', '', '日笠阳子 / 林原惠美 / 小西克幸 / 犬山犬子 / 朴璐美 / 高口公介 / 田中正彦 / 高木涉 / 上田祐司 / 中岛爱 / 子安武人 / 泽海阳子 / 熊井统子 / 堀江由衣 / 中村悠一 / 水树奈奈 / 宫园拓梦 / 观世智显 / 根谷美智子 / 樱井透 / 日高里菜 / 森田成一 / 高山南 / 荻野晴朗 / 富㭴美铃 / 堀内贤雄 / 土井美加 / 中博史 / 京田尚子 / 绪方贤一 / 铃木玲子 / 谷山纪章 / 铃木达央 / 手冢秀彰 / 柴田秀胜 / 木下纱华 / 樱井智 / 广桥', '古田丈司 / 曹毅 / 嵯峨敏 / 桥本直人 / 古贺一臣 / 荻原露光 / 伊藤史夫', '', '', '“通灵王（SHAMAN KING）”\r\n那是掌管森罗万象的星球之王。\r\n能够与神明或灵体交流、被称作「通灵人」的人们，\r\n在500年一度的「通灵人大战」当中争夺这一宝座。\r\n\r\n这些通灵人其中之一的少年·麻仓叶', '全52集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 8.1, 0, 0, 1739147253, 1739078837, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“通灵王（SHAMAN KING）”\r\n那是掌管森罗万象的星球之王。\r\n能够与神明或灵体交流、被称作「通灵人」的人们，\r\n在500年一度的「通灵人大战」当中争夺这一宝座。\r\n\r\n这些通灵人其中之一的少年·麻仓叶\r\n以通灵王为目标的战斗，\r\n2021年4月，以完全新作动画的形式就此展开。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5321EE8BE848595C50E978#第02集$MOE5321EE8BE848595C50E97B#第03集$MOE5321EE8BE848595C50E97A#第04集$MOE5321EE8BE848595C50E97D#第05集$MOE5321EE8BE848595C50E97C#第06集$MOE5321EE8BE848595C50E97F#第07集$MOE5321EE8BE848595C50E97E#第08集$MOE5321EE8BE848595C50E971#第09集$MOE5321EE8BE848595C50E970#第10集$MOE5321EE8BE848595C50E879#第11集$MOE5321EE8BE848595C50E878#第12集$MOE5321EE8BE848595C50E87B#第13集$MOE5321EE8BE848595C50E87A#第14集$MOE5321EE8BE848595C50E87D#第15集$MOE5321EE8BE848595C50E87C#第16集$MOE5321EE8BE848595C50E87F#第17集$MOE5321EE8BE848595C50E87E#第18集$MOE5321EE8BE848595C50E871#第19集$MOE5321EE8BE848595C50E870#第20集$MOE5321EE8BE848595C50EB79#第21集$MOE5321EE8BE848595C50EB78#第22集$MOE5321EE8BE848595C50EB7B#第23集$MOE5321EE8BE848595C50EB7A#第24集$MOE5321EE8BE848595C50EB7D#第25集$MOE5321EE8BE848595C50EB7C#第26集$MOE5321EE8BE848595C50EB7F#第27集$MOE5321EE8BE848595C50EB7E#第28集$MOE5321EE8BE848595C50EB71#第29集$MOE5321EE8BE848595C50EB70#第30集$MOE5321EE8BE84859