INSERT INTO `mac_vod` VALUES (1002, 1, 0, 0, 'Hand Shakers', '握手者（2017）', 'HandShakers', 1, 'H', '', 'cfc1aa7f', '战斗,热血,萝莉,原创', 'http://i0.hdslb.com/bfs/bangumi/948878ec7fc44c3e824d6204b4de91abfb0dce17.jpg', '', '', '', '浅沼晋太郎 / 雨宫天 / 石川界人 / 加隈亚衣 / 茅野爱衣 / 小林裕介 / 小松未可子 / 齐藤壮马 / 佐藤聪美 / 杉田智和 / 种田梨沙 / 津田健次郎 / 浪川大辅 / 早见沙织 / 日笠阳子 / 福山润 / 村濑步 / 森久保祥太郎 / 诸星堇', '金泽洪充 / 鈴木信吾', '', '', 'Hand Shakers——\r\n将手牵起，利用从深层心理诞生的武器“宁录”互相战斗的人们。\r\n为了实现自己的“愿望”，从而见到神，将神打破，众多的Hand Shakers以那个顶点为目标，互相竞争。\r\n存在', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 8.3, 0, 0, 1739189802, 1739078873, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>Hand Shakers——\r\n将手牵起，利用从深层心理诞生的武器“宁录”互相战斗的人们。\r\n为了实现自己的“愿望”，从而见到神，将神打破，众多的Hand Shakers以那个顶点为目标，互相竞争。\r\n存在于那尽头的事物是——。\r\n去守护吧，用这双手。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5271EF89E8485A5F50E978#第02集$MOE5271EF89E8485A5F50E97B#第03集$MOE5271EF89E8485A5F50E97A#第04集$MOE5271EF89E8485A5F50E97D#第05集$MOE5271EF89E8485A5F50E97C#第06集$MOE5271EF89E8485A5F50E97F#第07集$MOE5271EF89E8485A5F50E97E#第08集$MOE5271EF89E8485A5F50E971#第09集$MOE5271EF89E8485A5F50E970#第10集$MOE5271EF89E8485A5F50E879#第11集$MOE5271EF89E8485A5F50E878#第12集$MOE5271EF89E8485A5F50E87B#OVA$MOE5271EF89E8485A5F50E87A$$$第01集$id_XS5271EF89E8485A5F50E978#第02集$id_XS5271EF89E8485A5F50E97B#第03集$id_XS5271EF89E8485A5F50E97A#第04集$id_XS5271EF89E8485A5F50E97D#第05集$id_XS5271EF89E8485A5F50E97C#第06集$id_XS5271EF89E8485A5F50E97F#第07集$id_XS5271EF89E8485A5F50E97E#第08集$id_XS5271EF89E8485A5F50E971#第09集$id_XS5271EF89E8485A5F50E970#第10集$id_XS5271EF89E8485A5F50E879#第11集$id_XS5271EF89E8485A5F50E878#第12集$id_XS5271EF89E8485A5F50E87B#OVA$id_XS5271EF89E8485A5F50E87A$$$第01集$id_MOE5271EF89E8485A5F50E978#第02集$id_MOE5271EF89E8485A5F50E97B#第03集$id_MOE5271EF89E8485A5F50E97A#第04集$id_MOE5271EF89E8485A5F50E97D#第05集$id_MOE5271EF89E8485A5F50E97C#第06集$id_MOE5271EF89E8485A5F50E97F#第07集$id_MOE5271EF89E8485A5F50E97E#第08集$id_MOE5271EF89E8485A5F50E971#第09