INSERT INTO `mac_vod` VALUES (1004, 1, 0, 0, '雏子的笔记', 'ひなこのーと（2017）', 'chuzidebiji', 1, 'C', '', 'e761b498', '萌系,日常,漫画改', 'http://i0.hdslb.com/bfs/bangumi/2298bee824a966a44b3dcff6c2f9377aa1d95fa8.jpg', '', '', '', '市道真央 / 富田美忧 / 小仓唯 / 东城日沙子 / 高野麻里佳 / 吉田有里 / 栗本有规 / 远藤璃菜', '高桥丈夫 / 三瓶圣 / 喜多幡彻 / 龙轮直征 / 末田宜史 / 重原克也 / 泷川和男 / 备前克彦 / 江副仁美 / 森义博 / 长山延好', '', '', '不擅长和人交流却受到动物喜爱，因此在乡村担任“稻草人”这一工作的主人公高中生·雏子，与充满个性的角色们一同挑战演剧的演剧喜剧。', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.5, 0, 0, 1739190174, 1739078886, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>不擅长和人交流却受到动物喜爱，因此在乡村担任“稻草人”这一工作的主人公高中生·雏子，与充满个性的角色们一同挑战演剧的演剧喜剧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5420BA89EB1D540150E978#第02集$MOE5420BA89EB1D540150E97B#第03集$MOE5420BA89EB1D540150E97A#第04集$MOE5420BA89EB1D540150E97D#第05集$MOE5420BA89EB1D540150E97C#第06集$MOE5420BA89EB1D540150E97F#第07集$MOE5420BA89EB1D540150E97E#第08集$MOE5420BA89EB1D540150E971#第09集$MOE5420BA89EB1D540150E970#第10集$MOE5420BA89EB1D540150E879#第11集$MOE5420BA89EB1D540150E878#第12集$MOE5420BA89EB1D540150E87B$$$第01集$id_XS5420BA89EB1D540150E978#第02集$id_XS5420BA89EB1D540150E97B#第03集$id_XS5420BA89EB1D540150E97A#第04集$id_XS5420BA89EB1D540150E97D#第05集$id_XS5420BA89EB1D540150E97C#第06集$id_XS5420BA89EB1D540150E97F#第07集$id_XS5420BA89EB1D540150E97E#第08集$id_XS5420BA89EB1D540150E971#第09集$id_XS5420BA89EB1D540150E970#第10集$id_XS5420BA89EB1D540150E879#第11集$id_XS5420BA89EB1D540150E878#第12集$id_XS5420BA89EB1D540150E87B$$$第01集$id_MOE5420BA89EB1D540150E978#第02集$id_MOE5420BA89EB1D540150E97B#第03集$id_MOE5420BA89EB1D540150E97A#第04集$id_MOE5420BA89EB1D540150E97D#第05集$id_MOE5420BA89EB1D540150E97C#第06集$id_MOE5420BA89EB1D540150E97F#第07集$id_MOE5420BA89EB1D540150E97E#第08集$id_MOE5420BA89EB1D540150E971#第09集$id_MOE5420BA89EB1D540150E970#第10集$id_MOE5420BA89EB1D540150E879#第11集$id_MOE5420BA89EB1D540150E878#第12集$id_MOE5420BA89EB1D540150E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1005, 1, 0, 0, '百武装战记', 'ハンドレッド（2016）', 'baiwuzhuangzhanji', 1, 'B', '', '7567158f', '恋爱,校园,战斗', 'http://i0.hdslb.com/bfs/bangumi/296a1d5fd863c94c4a0b7d8e60afd7a1cab19ff7.jpg', '', '', '', '长谷川芳明 / 大久保瑠美 / 市道真央 / 吉冈茉祐 / 奥野香耶 / 羽多野涉 / 大坪由佳 / 衣川里佳 / 牧野由依 / 堀江由衣 / 佐藤利奈 / 今村彩夏 / 加藤英美里 / 芳野由奈 / 久保由利香 / 铃木绘理 / 大森日雅 / 山下七海 / 赤崎千夏 / 千菅春香 / 大西沙织 / 齐藤真知子 / 高木裕平 / 野岛健儿 / 朴璐美 / 细谷佳正', '小林智树 / 山本天志 / 下司泰弘 / 村上勉 / 清水一伸 / 前园文夫 / 安藤健 / 驹屋健一郎', '', '', '“百武装展开！！”\r\n“HUNDRED”──那是能对抗袭击地球的神祕生物“蛮族”（Savage）的唯一武器。\r\n主角如月隼人为了成为能够驾驭HUNDRED的武艺者（Slayer），进入海上学园都市舰“Li', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 8.0, 0, 0, 1739190294, 1739078897, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“百武装展开！！”\r\n“HUNDRED”──那是能对抗袭击地球的神祕生物“蛮族”（Savage）的唯一武器。\r\n主角如月隼人为了成为能够驾驭HUNDRED的武艺者（Slayer），进入海上学园都市舰“Little Garden”就读。然而──\r\n“我好想你喔，隼人!!”\r\n“你、你到底是……？”\r\n &nbsp; 对於似乎很了解自己的室友艾米尔‧克劳福德，隼人产生了某种怀念的异样感受。不仅如此，才一入学，学园最强的武艺者“女王”克蕾亚‧哈维便向他提出决斗要求……!?\r\n　箕崎准(ocelot)×大熊猫介（Nitro ）联手推出！“究极”学园风动作小说，就此开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0622BA8FB81C555F50E978#第02集$MOE0622BA8FB81C555F50E97B#第03集$MOE0622BA8FB81C555F50E97A#第04集$MOE0622BA8FB81C555F50E97D#第05集$MOE0622BA8FB81C555F50E97C#第06集$MOE0622BA8FB81C555F50E97F#第07集$MOE0622BA8FB81C555F50E97E#第08集$MOE0622BA8FB81C555F50E971#第09集$MOE0622BA8FB81C555F50E970#第10集$MOE0622BA8FB81C555F50E879#第11集$MOE0622BA8FB81C555F50E878#第12集$MOE0622BA8FB81C555F50E87B$$$第01集$id_XS0622BA8FB81C555F50E978#第02集$id_XS0622BA8FB81C555F50E97B#第03集$id_XS0622BA8FB81C555F50E97A#第04集$id_XS0622BA8FB81C555F50E97D#第05集$id_XS0622BA8FB81C555F50E97C#第06集$id_XS0622BA8FB81C555F50E97F#第07集$id_XS0622BA8FB81C555F50E97E#第08集$id_XS0622BA8FB81C555F50E971#第09集$id_XS0622BA8FB81C555F50E970#第10集$id_XS0622BA8FB81C555F50E879#第11集$id_XS0622BA8FB81C555F50E878#第12集$id_XS0622BA8FB81C555F50E87B$$$第01集$id_MOE0622BA8FB81C555F50E978#第02集$id_MOE0622BA8FB81C555F50E97B#第03集$id_MOE0622BA8FB81