INSERT INTO `mac_vod` VALUES (1008, 1, 0, 0, '魔笛MAGI 辛巴达的冒险', 'マギ シンドバッドの冒険（2014）', 'modiMAGIxinbadademaoxian', 1, 'M', '', 'aa2adff7', '奇幻,战斗,架空,冒险', 'http://i0.hdslb.com/bfs/bangumi/a02579a8ffbaf4bfcb5b23ed6f0dc298dd02f851.jpg', '', '', '', '小野大辅 / 杉田智和 / 石田彰', '宮尾佳和', '', '', '《魔笛MAGI 辛巴达的冒险》作为《魔笛MAGI》的前章，主要讲述的是围绕30年前少年时期的七海霸主辛巴达展开的全新魔导冒险谭，而各位也能从本作中看到《魔笛MAGI》中一些角色年轻时候的样子。', '全13集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.6, 0, 0, 1739247075, 1739231874, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《魔笛MAGI 辛巴达的冒险》作为《魔笛MAGI》的前章，主要讲述的是围绕30年前少年时期的七海霸主辛巴达展开的全新魔导冒险谭，而各位也能从本作中看到《魔笛MAGI》中一些角色年轻时候的样子。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5076BED9ED4F0B0E50E978#第02集$MOE5076BED9ED4F0B0E50E97B#第03集$MOE5076BED9ED4F0B0E50E97A#第04集$MOE5076BED9ED4F0B0E50E97D#第05集$MOE5076BED9ED4F0B0E50E97C#第06集$MOE5076BED9ED4F0B0E50E97F#第07集$MOE5076BED9ED4F0B0E50E97E#第08集$MOE5076BED9ED4F0B0E50E971#第09集$MOE5076BED9ED4F0B0E50E970#第10集$MOE5076BED9ED4F0B0E50E879#第11集$MOE5076BED9ED4F0B0E50E878#第12集$MOE5076BED9ED4F0B0E50E87B#第13集$MOE5076BED9ED4F0B0E50E87A$$$第01集$id_XS5076BED9ED4F0B0E50E978#第02集$id_XS5076BED9ED4F0B0E50E97B#第03集$id_XS5076BED9ED4F0B0E50E97A#第04集$id_XS5076BED9ED4F0B0E50E97D#第05集$id_XS5076BED9ED4F0B0E50E97C#第06集$id_XS5076BED9ED4F0B0E50E97F#第07集$id_XS5076BED9ED4F0B0E50E97E#第08集$id_XS5076BED9ED4F0B0E50E971#第09集$id_XS5076BED9ED4F0B0E50E970#第10集$id_XS5076BED9ED4F0B0E50E879#第11集$id_XS5076BED9ED4F0B0E50E878#第12集$id_XS5076BED9ED4F0B0E50E87B#第13集$id_XS5076BED9ED4F0B0E50E87A$$$第01集$id_MOE5076BED9ED4F0B0E50E978#第02集$id_MOE5076BED9ED4F0B0E50E97B#第03集$id_MOE5076BED9ED4F0B0E50E97A#第04集$id_MOE5076BED9ED4F0B0E50E97D#第05集$id_MOE5076BED9ED4F0B0E50E97C#第06集$id_MOE5076BED9ED4F0B0E50E97F#第07集$id_MOE5076BED9ED4F0B0E50E97E#第08集$id_MOE5076BED9ED4F0B0E50E971#第09集$id_MOE5076BED9ED4F0B0E50E970#第10集$id_MOE5076BED9ED4F0B0E50E879#第11集$id_MOE5076BED9ED4F0B0E50E878#第12集$id_MOE5076BED9ED4F0B0E50E87B#第13集$id_MOE5076BED