INSERT INTO `mac_vod` VALUES (1009, 1, 0, 0, '滑头鬼之孙', 'ぬらりひょんの孫（2010）', 'huatouguizhisun', 1, 'H', '', '5ad227ac', '奇幻,战斗,热血,声控', 'http://i0.hdslb.com/bfs/bangumi/image/249c68c34a185cab857ffb647808c2c30333cefc.jpg', '', '', '', '福山润 / 堀江由衣 / 谷山纪章 / 前田爱 / 平野绫 / 大塚周夫 / 安元洋贵 / 鸟海浩辅 / 间岛淳司 / 樱井孝宏 / 杉田智和 / 中田让治 / 吉野裕行 / 保志总一朗', '西村纯二 / 龟井干太 / 神保昌登 / 吉田俊司 / 上田茂 / 高桥幸雄 / 雄谷将仁 / 西村博昭 / 大关雅幸 / 木村崇裕 / 宇井良和', '', '', '以现代的日本（浮世绘町）作为舞台，描绘了人和妖怪的日常的怪异空想，继承百鬼夜行大头领的少年在妖怪百鬼夜行的世界中劝善惩恶的故事 。 故事中的妖怪，大部份是出自鸟山石燕的“画图百鬼夜行”和竹原春泉的“小', '全26集', '', 0, '0', '', '', '日本', '日语', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.3, 0, 0, 1739346800, 1739233549, 0, 0, 0, 0, 0.0, '', '1010', '', '', '', '', '', '', '', '<p>以现代的日本（浮世绘町）作为舞台，描绘了人和妖怪的日常的怪异空想，继承百鬼夜行大头领的少年在妖怪百鬼夜行的世界中劝善惩恶的故事 。 故事中的妖怪，大部份是出自鸟山石燕的“画图百鬼夜行”和竹原春泉的“小人儿书一百故事”的妖怪画集。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0476E88ABB1E0C5A50E978#第02集$MOE0476E88ABB1E0C5A50E97B#第03集$MOE0476E88ABB1E0C5A50E97A#第04集$MOE0476E88ABB1E0C5A50E97D#第05集$MOE0476E88ABB1E0C5A50E97C#第06集$MOE0476E88ABB1E0C5A50E97F#第07集$MOE0476E88ABB1E0C5A50E97E#第08集$MOE0476E88ABB1E0C5A50E971#第09集$MOE0476E88ABB1E0C5A50E970#第10集$MOE0476E88ABB1E0C5A50E879#第11集$MOE0476E88ABB1E0C5A50E878#第12集$MOE0476E88ABB1E0C5A50E87B#第13集$MOE0476E88ABB1E0C5A50E87A#第14集$MOE0476E88ABB1E0C5A50E87D#第15集$MOE0476E88ABB1E0C5A50E87C#第16集$MOE0476E88ABB1E0C5A50E87F#第17集$MOE0476E88ABB1E0C5A50E87E#第18集$MOE0476E88ABB1E0C5A50E871#第19集$MOE0476E88ABB1E0C5A50E870#第20集$MOE0476E88ABB1E0C5A50EB79#第21集$MOE0476E88ABB1E0C5A50EB78#第22集$MOE0476E88ABB1E0C5A50EB7B#第23集$MOE0476E88ABB1E0C5A50EB7A#第24集$MOE0476E88ABB1E0C5A50EB7D#第25集$MOE0476E88ABB1E0C5A50EB7C#第26集$MOE0476E88ABB1E0C5A50EB7F$$$第01集$id_XS0476E88ABB1E0C5A50E978#第02集$id_XS0476E88ABB1E0C5A50E97B#第03集$id_XS0476E88ABB1E0C5A50E97A#第04集$id_XS0476E88ABB1E0C5A50E97D#第05集$id_XS0476E88ABB1E0C5A50E97C#第06集$id_XS0476E88ABB1E0C5A50E97F#第07集$id_XS0476E88ABB1E0C5A50E97E#第08集$id_XS0476E88ABB1E0C5A50E971#第09集$id_XS0476E88ABB1E0C5A50E970#第