INSERT INTO `mac_vod` VALUES (1011, 1, 0, 0, '恋爱随意链接', 'ココロコネクト（2012）', 'lianaisuiyilianjie', 1, 'L', '', 'abc68a3c', '小说改,日常,治愈,校园', 'http://i0.hdslb.com/bfs/bangumi/8274f1107032a6fe0843dc9cf875d887d6ad0f03.jpg', '', '', '', '水岛大宙 / 丰崎爱生 / 泽城美雪 / 金元寿子 / 寺岛拓笃 / 藤原启治 / 伊藤静', '大沼心 / 川面真也 / 黑川智之 / 神保昌登 / 平田丰 / 玉村仁 / 福多润 / 山口赖房 / 永冈智佳', '', '', '故事发生在私立山星高中，这所学校的文化研究部内，八重樫太一、永濑伊织、稻叶姬子、桐山唯、青木义文这五名成员面临着一个不可思议的现象。起初是唯和义文两个人在毫无前兆的情况下发生了人格交换，之后周围的其他', '全17集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.5, 0, 0, 1739347263, 1739234043, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在私立山星高中，这所学校的文化研究部内，八重樫太一、永濑伊织、稻叶姬子、桐山唯、青木义文这五名成员面临着一个不可思议的现象。起初是唯和义文两个人在毫无前兆的情况下发生了人格交换，之后周围的其他成员也是如此？！爱与青春的五角悲喜剧就此拉开了帷幕……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5075EF8EB1485E5A50E978#第02集$MOE5075EF8EB1485E5A50E97B#第03集$MOE5075EF8EB1485E5A50E97A#第04集$MOE5075EF8EB1485E5A50E97D#第05集$MOE5075EF8EB1485E5A50E97C#第06集$MOE5075EF8EB1485E5A50E97F#第07集$MOE5075EF8EB1485E5A50E97E#第08集$MOE5075EF8EB1485E5A50E971#第09集$MOE5075EF8EB1485E5A50E970#第10集$MOE5075EF8EB1485E5A50E879#第11集$MOE5075EF8EB1485E5A50E878#第12集$MOE5075EF8EB1485E5A50E87B#第13集$MOE5075EF8EB1485E5A50E87A#第14集$MOE5075EF8EB1485E5A50E87D#第15集$MOE5075EF8EB1485E5A50E87C#第16集$MOE5075EF8EB1485E5A50E87F#第17集$MOE5075EF8EB1485E5A50E87E$$$第01集$id_XS5075EF8EB1485E5A50E978#第02集$id_XS5075EF8EB1485E5A50E97B#第03集$id_XS5075EF8EB1485E5A50E97A#第04集$id_XS5075EF8EB1485E5A50E97D#第05集$id_XS5075EF8EB1485E5A50E97C#第06集$id_XS5075EF8EB1485E5A50E97F#第07集$id_XS5075EF8EB1485E5A50E97E#第08集$id_XS5075EF8EB1485E5A50E971#第09集$id_XS5075EF8EB1485E5A50E970#第10集$id_XS5075EF8EB1485E5A50E879#第11集$id_XS5075EF8EB1485E5A50E878#第12集$id_XS5075EF8EB1485E5A50E87B#第13集$id_XS5075EF8EB1485E5A50E87A#第14集$id_XS5075EF8EB1485E5A50E87D#第15集$id_XS5075EF8EB1485E5A50E87C#第16集$id_XS5075EF8EB1485E5A50E87F#第17集$id_XS5075EF8EB1485E5A50E87E$$$第01集$id_MOE5075EF8EB1485E5A50E978#第02集$id_MOE5075EF8EB1485E5A50E97B#第03集$id_MOE5075EF8EB1485E5A50E97A#第04集$id_MOE5075EF8EB1485E5A50E97D#第05集$id_MOE5075EF8EB1485E5A50E97C#第06集$id_MOE5075EF8EB1485E5A50E97F#第07集$id_MOE5075EF8EB1485E5A50E97E#第08集$id_MOE5075EF8EB1485E5A50E971#第09集$id_MOE5075EF8EB1485E5A50E970#第10集$id_MOE5075EF8EB1485E5A50E879#第11集$id_MOE5075EF8EB1485E5A50E878#第12集$id_MOE5075EF8EB1485E5A50E87B#第13集$id_MOE5075EF8EB1485E5A50E87A#第14集$id_MOE5075EF8EB1485E5A50E87D#第15集$id_MOE5075EF8EB1485E5A50E87C#第16集$id_MOE5075EF8EB1485E5A50E87F#第17集$id_MOE5075EF8EB1485E5A50E87E', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1012, 1, 0, 0, '来自新世界', '新世界より（2012）', 'laizixinshijie', 1, 'L', '', 'fac30a84', '奇幻,科幻,架空,小说改', 'http://i0.hdslb.com/bfs/bangumi/aaa60f9cb17fb4a38df464f1064ca9623e0769cc.jpg', '', '', '', '种田梨沙 / 东条加那子 / 梶裕贵 / 花泽香菜 / 工藤晴香 / 高城元气 / 藤堂真衣 / 村濑步 / 东地宏树 / 伊藤美纪 / 榊原良子 / 星野贵纪 / 浪川大辅 / 平田广明 / 堀江由衣 / 杉田智和 / 远藤绫', '石滨真史 / 山内重保 / 大和直道 / 柳沼和良 / 中山敦史 / 高桥知也 / 藤濑顺一 / 工藤宽显 / 高村雄太 / 广岛秀树 / 黑泽守 / 渊上真 / 森义博 / 冈田坚二朗', '', '', '1000年后的日本，孩子们不断地消失，只存在想象中的恐怖动物与人类展开殊死战争。反乌托邦式的未来超级社会“新世界”，是口吐真言凭藉“咒力”就能移动物体的人类，与有着等同于普通人智力的生物“妖鼠”共存的', '全25集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.5, 0, 0, 1739347344, 1739234050, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>1000年后的日本，孩子们不断地消失，只存在想象中的恐怖动物与人类展开殊死战争。反乌托邦式的未来超级社会“新世界”，是口吐真言凭藉“咒力”就能移动物体的人类，与有着等同于普通人智力的生物“妖鼠”共存的世界。乍看之下一切和平，但“新世界”的孩子们的行动被彻底地控制和管束著，不合适的记忆被消去，被认为有问题的孩子，如同不良产品般被分开处理。得到被称为“咒力”的特殊能力的人们在“八丁标”的结界中促成一个小小的团体，无论是思想还是对外界的认知，记忆、爱、甚至生命的支配都被统治着。在这其中，渡边早季、朝比奈觉、秋月真理亚、伊东守、青沼瞬五位少年和少女们，为了守护日益衰弱的世界和同伴，投身到了各种各样的冒险的旅程中......</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5776EF8BB948550D50E978#第02集$MOE5776EF8BB948550D50E97B#第03集$MOE5776EF8BB948550D50E97A#第04集$MOE5776EF8BB948550D50E97D#第05集$MOE5776EF8BB948550D50E97C#第06集$MOE5776EF8BB948550D50E97F#第07集$MOE5776EF8BB948550D50E97E#第08集$MOE5776EF8BB948550D50E971#第09集$MOE5776EF8BB948550D50E970#第10集$MOE5776EF8BB948550D50E879#第11集$MOE5776EF8BB948550D50E878#第12集$MOE5776EF8BB948550D50E87B#第13集$MOE5776EF8BB948550D50E87A#第14集$MOE5776EF8BB948550D50E87D#第15集$MOE5776EF8BB948550D50E87C#第16集$MOE5776EF8BB948550D50E87F#第17集$MOE5776EF8BB948550D50E87E#第18集$MOE5776EF8BB948550D50E871#第19集$MOE5776EF8BB948550D50E870#第20集$MOE5776EF8BB948550D50EB79#第21集$MOE5776EF8BB948550D50EB78#第22集$MOE5776EF8BB948550D50EB7B#第23集$MOE5776EF8BB948550D50EB7A#第24集$MOE5776EF8BB948550D50EB7D#第25集$MOE5776EF8BB948550D50EB7C$$$第01集$id_XS5776EF8BB948550D50E978#第02集$id_XS5776EF8BB948550D50E97B#第03集$id_XS5776EF8BB948550D50E97A#第04集$