INSERT INTO `mac_vod` VALUES (1016, 1, 0, 0, '关于完全听不懂老公在说什么的事 第一季', '旦那が何を言っているかわからない件（2014）', 'guanyuwanquantingbudonglaogongzaishuoshimedeshidiyiji', 1, 'G', '', '31701708', '日常,泡面', 'http://i0.hdslb.com/bfs/bangumi/f4535567ee32b0e96bd912e775bb5f98658694c9.jpg', '', '', '', '田村由香里 / 铃村健一 / 清水香里', '永居慎平', '', '', '原作者「酷教信者」在网络连载的四格搞笑漫画，讲述认真工作的OL与宅男老公间的日常故事。又名《关公说事》。', '全13集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 29, 0, 29, 29, '', 0, 0, 9.7, 0, 0, 1739347935, 1739234083, 0, 0, 0, 0, 0.0, '', '1017', '', '', '', '', '', '', '', '<p>原作者「酷教信者」在网络连载的四格搞笑漫画，讲述认真工作的OL与宅男老公间的日常故事。又名《关公说事》。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0226BB88B81E5D0150E978#第02集$MOE0226BB88B81E5D0150E97B#第03集$MOE0226BB88B81E5D0150E97A#第04集$MOE0226BB88B81E5D0150E97D#第05集$MOE0226BB88B81E5D0150E97C#第06集$MOE0226BB88B81E5D0150E97F#第07集$MOE0226BB88B81E5D0150E97E#第08集$MOE0226BB88B81E5D0150E971#第09集$MOE0226BB88B81E5D0150E970#第10集$MOE0226BB88B81E5D0150E879#第11集$MOE0226BB88B81E5D0150E878#第12集$MOE0226BB88B81E5D0150E87B#第13集$MOE0226BB88B81E5D0150E87A$$$第01集$id_XS0226BB88B81E5D0150E978#第02集$id_XS0226BB88B81E5D0150E97B#第03集$id_XS0226BB88B81E5D0150E97A#第04集$id_XS0226BB88B81E5D0150E97D#第05集$id_XS0226BB88B81E5D0150E97C#第06集$id_XS0226BB88B81E5D0150E97F#第07集$id_XS0226BB88B81E5D0150E97E#第08集$id_XS0226BB88B81E5D0150E971#第09集$id_XS0226BB88B81E5D0150E970#第10集$id_XS0226BB88B81E5D0150E879#第11集$id_XS0226BB88B81E5D0150E878#第12集$id_XS0226BB88B81E5D0150E87B#第13集$id_XS0226BB88B81E5D0150E87A$$$第01集$id_MOE0226BB88B81E5D0150E978#第02集$id_MOE0226BB88B81E5D0150E97B#第03集$id_MOE0226BB88B81E5D0150E97A#第04集$id_MOE0226BB88B81E5D0150E97D#第05集$id_MOE0226BB88B81E5D0150E97C#第06集$id_MOE0226BB88B81E5D0150E97F#第07集$id_MOE0226BB88B81E5D0150E97E#第08集$id_MOE0226BB88B81E5D0150E971#第09集$id_MOE0226BB88B81E5D0150E970#第10集$id_MOE0226BB88B81E5D0150E879#第11集$id_MOE0226BB88B81E5D0150E878#第12集$id_MOE0226BB88B81E5D0150E87B#第13集$id_MOE0226BB88B81E5D0150E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1017, 1, 0, 0, '关于完全听不懂老公在说什么的事 第二季', '旦那が何を言っているかわからない件 2スレ目（2015）', 'guanyuwanquantingbudonglaogongzaishuoshimedeshidierji', 1, 'G', '', '166fbd0', '日常,少女,泡面', 'http://i0.hdslb.com/bfs/bangumi/b54707a72142398ec37c29245f9a59f7a467fa7f.jpg', '', '', '', '田村ゆかり / 铃村健一 / 佐仓绫音', '永居慎平', '', '', '众望所归的第二季！\r\n有个宅男老公也许也是一件挺有趣的事吧？热心于工作的OL“薰”是个普通人，而她的老公则是沉迷于某大型网路留言版的阿宅，故事就围绕着这样的夫妻日常展开~看看本季两人又会怎样花式秀恩爱吧', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.7, 0, 0, 1739348000, 1739331592, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>众望所归的第二季！\r\n有个宅男老公也许也是一件挺有趣的事吧？热心于工作的OL“薰”是个普通人，而她的老公则是沉迷于某大型网路留言版的阿宅，故事就围绕着这样的夫妻日常展开~看看本季两人又会怎样花式秀恩爱吧！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0021BADEEB4D5D144DE8#第02集$MOE0021BADEEB4D5D144DEB#第03集$MOE0021BADEEB4D5D144DEA#第04集$MOE0021BADEEB4D5D144DED#第05集$MOE0021BADEEB4D5D144DEC#第06集$MOE0021BADEEB4D5D144DEF#第07集$MOE0021BADEEB4D5D144DEE#第08集$MOE0021BADEEB4D5D144DE1#第09集$MOE0021BADEEB4D5D144DE0#第10集$MOE0021BADEEB4D5D144CE9#第11集$MOE0021BADEEB4D5D144CE8#第12集$MOE0021BADEEB4D5D144CEB#第13集$MOE0021BADEEB4D5D144CEA$$$第01集$id_XS0021BADEEB4D5D144DE8#第02集$id_XS0021BADEEB4D5D144DEB#第03集$id_XS0021BADEEB4D5D144DEA#第04集$id_XS0021BADEEB4D5D144DED#第05集$id_XS0021BADEEB4D5D144DEC#第06集$id_XS0021BADEEB4D5D144DEF#第07集$id_XS0021BADEEB4D5D144DEE#第08集$id_XS0021BADEEB4D5D144DE1#第09集$id_XS0021BADEEB4D5D144DE0#第10集$id_XS0021BADEEB4D5D144CE9#第11集$id_XS0021BADEEB4D5D144CE8#第12集$id_XS0021BADEEB4D5D144CEB#第13集$id_XS0021BADEEB4D5D144CEA$$$第01集$id_MOE0021BADEEB4D5D144DE8#第02集$id_MOE0021BADEEB4D5D144DEB#第03集$id_MOE0021BADEEB4D5D144DEA#第04集$id_MOE0021BADEEB4D5D144DED#第05集$id_MOE0021BADEEB4D5D144DEC#第06集$id_MOE0021BADEEB4D5D144DEF#第07集$id_MOE0021BADEEB4D5D144DEE#第08集$id_MOE0021BADEEB4D5D144DE1#第09集$id_MOE0021BADEEB4D5D144DE0#第10集$id_MOE0021BADEEB4D5D144CE9#第11集$id_MOE0021BADEEB4D5D144CE8#第12集$id_MOE0021BADEEB4D5D144CEB#第13集$id_MOE0021BADEEB4D5D144CEA', ''