INSERT INTO `mac_vod` VALUES (1018, 1, 0, 0, '白沙的水族馆', '白い砂のアクアトープ（2021）', 'baishadeshuizuguan', 1, 'B', '', '3c2e8c94', '原创,日常,励志', 'http://i0.hdslb.com/bfs/bangumi/image/03983c1766f9d911044da1f8488212861602bc92.png', '', '', '', '伊藤美来 / 逢田梨香子 / 和气杏未 / Lynn / 土屋神叶 / 阿座上洋平 / 家中宏', '筱原俊哉 / 市村彻夫 / 太田知章 / 大石康之 / 本间修 / 高村彰 / 佐佐木勅嘉 / 熨斗谷充孝', '', '', '在水族馆工作的18岁高中女生·海咲野心，\r\n遇见了在东京失去了容身之地于是选择逃离的前偶像·宫泽风花。\r\n心和风花各自怀抱着不同的想法，在水族馆里度过了一段时光。\r\n\r\n但是，那个重要的地方，濒临闭馆。\r\n\r\n少', '全24集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 1, 0, 1, 1, '', 0, 0, 9.6, 0, 0, 1739348115, 1739331648, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在水族馆工作的18岁高中女生·海咲野心，\r\n遇见了在东京失去了容身之地于是选择逃离的前偶像·宫泽风花。\r\n心和风花各自怀抱着不同的想法，在水族馆里度过了一段时光。\r\n\r\n但是，那个重要的地方，濒临闭馆。\r\n\r\n少女们的梦想与现实，孤独与朋友，羁绊与纠结──。\r\n将会在今年夏天，打开这熠熠生辉的新一页。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0274BEDDB14A540D50E978#第02集$MOE0274BEDDB14A540D50E97B#第03集$MOE0274BEDDB14A540D50E97A#第04集$MOE0274BEDDB14A540D50E97D#第05集$MOE0274BEDDB14A540D50E97C#第06集$MOE0274BEDDB14A540D50E97F#第07集$MOE0274BEDDB14A540D50E97E#第08集$MOE0274BEDDB14A540D50E971#第09集$MOE0274BEDDB14A540D50E970#第10集$MOE0274BEDDB14A540D50E879#第11集$MOE0274BEDDB14A540D50E878#第12集$MOE0274BEDDB14A540D50E87B#第13集$MOE0274BEDDB14A540D50E87A#第14集$MOE0274BEDDB14A540D50E87D#第15集$MOE0274BEDDB14A540D50E87C#第16集$MOE0274BEDDB14A540D50E87F#第17集$MOE0274BEDDB14A540D50E87E#第18集$MOE0274BEDDB14A540D50E871#第19集$MOE0274BEDDB14A540D50E870#第20集$MOE0274BEDDB14A540D50EB79#第21集$MOE0274BEDDB14A540D50EB78#第22集$MOE0274BEDDB14A540D50EB7B#第23集$MOE0274BEDDB14A540D50EB7A#第24集$MOE0274BEDDB14A540D50EB7D$$$第01集$id_XS0274BEDDB14A540D50E978#第02集$id_XS0274BEDDB14A540D50E97B#第03集$id_XS0274BEDDB14A540D50E97A#第04集$id_XS0274BEDDB14A540D50E97D#第05集$id_XS0274BEDDB14A540D50E97C#第06集$id_XS0274BEDDB14A540D50E97F#第07集$id_XS0274BEDDB14A540D50E97E#第08集$id_XS0274BEDDB14A540D50E971#第09集$id_XS0274BEDDB14A540D50E970#第10集$id_XS0274BEDDB14A540D50E879#第11集$id_XS0274BEDDB14A540D50