INSERT INTO `mac_vod` VALUES (1023, 1, 0, 0, '天真与闪电', '甘々と稲妻（2016）', 'tianzhenyushandian', 1, 'T', '', '3ca724c6', '日常,治愈,萌系', 'http://i0.hdslb.com/bfs/bangumi/5626f7afbd39a0b4561dea5bd267ba1ef2248c0d.jpg', '', '', '', '中村悠一 / 远藤璃菜 / 早见沙织 / 户松遥 / 关智一 / 新井里美 / 日笠阳子 / 柚木凉香 / 茅野爱衣 / 久我心麦 / 安藤纱彩 / 鹤翔麒', '岩崎太郎 / 五月女有作', '', '', '妻子亡故后，独自努力养育女儿的数学教师·犬冢。不擅长料理又是个味觉白痴的他，在偶然之下和学生·饭田小鸟一起，开始一同做饭并和女儿三个人一起享用！被爱女和女高中生包围着，两手鲜花的餐桌剧开幕！', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.7, 0, 0, 1739708050, 1739587777, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>妻子亡故后，独自努力养育女儿的数学教师·犬冢。不擅长料理又是个味觉白痴的他，在偶然之下和学生·饭田小鸟一起，开始一同做饭并和女儿三个人一起享用！被爱女和女高中生包围着，两手鲜花的餐桌剧开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0274ED8FBB1D0E0F50E978#第02集$MOE0274ED8FBB1D0E0F50E97B#第03集$MOE0274ED8FBB1D0E0F50E97A#第04集$MOE0274ED8FBB1D0E0F50E97D#第05集$MOE0274ED8FBB1D0E0F50E97C#第06集$MOE0274ED8FBB1D0E0F50E97F#第07集$MOE0274ED8FBB1D0E0F50E97E#第08集$MOE0274ED8FBB1D0E0F50E971#第09集$MOE0274ED8FBB1D0E0F50E970#第10集$MOE0274ED8FBB1D0E0F50E879#第11集$MOE0274ED8FBB1D0E0F50E878#第12集$MOE0274ED8FBB1D0E0F50E87B$$$第01集$id_XS0274ED8FBB1D0E0F50E978#第02集$id_XS0274ED8FBB1D0E0F50E97B#第03集$id_XS0274ED8FBB1D0E0F50E97A#第04集$id_XS0274ED8FBB1D0E0F50E97D#第05集$id_XS0274ED8FBB1D0E0F50E97C#第06集$id_XS0274ED8FBB1D0E0F50E97F#第07集$id_XS0274ED8FBB1D0E0F50E97E#第08集$id_XS0274ED8FBB1D0E0F50E971#第09集$id_XS0274ED8FBB1D0E0F50E970#第10集$id_XS0274ED8FBB1D0E0F50E879#第11集$id_XS0274ED8FBB1D0E0F50E878#第12集$id_XS0274ED8FBB1D0E0F50E87B$$$第01集$id_MOE0274ED8FBB1D0E0F50E978#第02集$id_MOE0274ED8FBB1D0E0F50E97B#第03集$id_MOE0274ED8FBB1D0E0F50E97A#第04集$id_MOE0274ED8FBB1D0E0F50E97D#第05集$id_MOE0274ED8FBB1D0E0F50E97C#第06集$id_MOE0274ED8FBB1D0E0F50E97F#第07集$id_MOE0274ED8FBB1D0E0F50E97E#第08集$id_MOE0274ED8FBB1D0E0F50E971#第09集$id_MOE0274ED8FBB1D0E0F50E970#第10集$id_MOE0274ED8FBB1D0E0F50E879#第11集$id_MOE0274ED8FBB1D0E0F50E878#第12集$id_MOE0274ED8FBB1D0E0F50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1024, 1, 0, 0, '宝石商人理查德的谜鉴定', '宝石商リチャード氏の謎鑑定（2020）', 'baoshishangrenlichadedemijianding', 1, 'B', '', '159cfdff', '小说改,日常,推理,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/f77cc2a496278ed4629ad47f59b868808115249f.png', '', '', '', '樱井孝宏 / 内田雄马 / 花泽香菜 / 井口祐一', '岩崎太郎', '', '', '正义感满满的大学生中田正义某晚帮助了被醉鬼纠缠的美貌外国人理查德。了解到理查德是个宝石商人之后，中田拿着祖母生前一直珍藏的戒指拜托理查德鉴定。通过理查德的鉴定揭开了祖母的过往，真相与心愿。借此，正义开', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.3, 0, 0, 1739708124, 1739599387, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>正义感满满的大学生中田正义某晚帮助了被醉鬼纠缠的美貌外国人理查德。了解到理查德是个宝石商人之后，中田拿着祖母生前一直珍藏的戒指拜托理查德鉴定。通过理查德的鉴定揭开了祖母的过往，真相与心愿。借此，正义开始在理查德在银座宝石店“Jewelry étranger”打工。每天在揭开这些被带到étranger来的各样“谜团”的过程中，理查德和正义的关系也发生了微妙的变化。但是彼此都隐藏着不可告人的秘密。\r\n俊美宝石商和正义感满满的大学生交织出的宝石推理正在拉开帷幕——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0022B5DBEF4D0B5F50E978#第02集$MOE0022B5DBEF4D0B5F50E97B#第03集$MOE0022B5DBEF4D0B5F50E97A#第04集$MOE0022B5DBEF4D0B5F50E97D#第05集$MOE0022B5DBEF4D0B5F50E97C#第06集$MOE0022B5DBEF4D0B5F50E97F#第07集$MOE0022B5DBEF4D0B5F50E97E#第08集$MOE0022B5DBEF4D0B5F50E971#第09集$MOE0022B5DBEF4D0B5F50E970#第10集$MOE0022B5DBEF4D0B5F50E879#第11集$MOE0022B5DBEF4D0B5F50E878#第12集$MOE0022B5DBEF4D0B5F50E87B$$$第01集$id_XS0022B5DBEF4D0B5F50E978#第02集$id_XS0022B5DBEF4D0B5F50E97B#第03集$id_XS0022B5DBEF4D0B5F50E97A#第04集$id_XS0022B5DBEF4D0B5F50E97D#第05集$id_XS0022B5DBEF4D0B5F50E97C#第06集$id_XS0022B5DBEF4D0B5F50E97F#第07集$id_XS0022B5DBEF4D0B5F50E97E#第08集$id_XS0022B5DBEF4D0B5F50E971#第09集$id_XS0022B5DBEF4D0B5F50E970#第10集$id_XS0022B5DBEF4D0B5F50E879#第11集$id_XS0022B5DBEF4D0B5F50E878#第12集$id_XS0022B5DBEF4D0B5F50E87B$$$第01集$id_MOE0022B5DBEF4D0B5F50E978#第02集$id_MOE0022B5DBEF4D0B5F50E97B#第03集$id_MOE0022B5DBEF4D0B5F50E97A#第04集$id_MOE0022B5DBEF4D0B5F50E97D#第05集$id_MOE0022B5DBEF4D0B5F50E97C#第06集$id_MOE0022B5DBEF4D0B5F50E97F#第07集$id_MOE0022B5DBEF4D0B5F50E97E#第08集$id_MOE0022B5DBEF4D0B5F50E971#第09集$id_MOE0022B5DBEF4D0B5F50E970#第10集$id_MOE0022B5DBE