INSERT INTO `mac_vod` VALUES (1027, 2, 0, 0, '热诚传说～导师的黎明～', 'テイルズ オブ ゼスティリア 〜導師の夜明け〜（2014）', 'rechengchuanshuodaoshideliming', 1, 'R', '', 'c82e75c', '奇幻,架空,冒险', 'http://i0.hdslb.com/bfs/bangumi/be114160ae93cf2f608c009dab5dbd37ce459f8e.jpg', '', '', '', '木村良平 / 茅野爱衣 / 逢坂良太 / 福圆美里 / 松来未祐 / 小野大辅 / 津田健次郎', '外崎春雄', '', '', '《情热传说～导师的黎明～》是由ufotable制作的电视动画作品，于2014年12月30日播放，全1话。动画改编自万代南梦宫游戏开发的角色扮演游戏《热情传说》。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 8.8, 0, 0, 1739750808, 1739708314, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《情热传说～导师的黎明～》是由ufotable制作的电视动画作品，于2014年12月30日播放，全1话。动画改编自万代南梦宫游戏开发的角色扮演游戏《热情传说》。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS522FBEDDBE1C0E144DE8$$$正片$id_MOE522FBEDDBE1C0E144DE8', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1028, 1, 0, 0, '22/7', 'ナナブンノニジュウニ（2020）', '227', 1, '2', '', 'f62843aa', '原创,日常,萌系,音乐', 'http://i0.hdslb.com/bfs/bangumi/image/ddea3bbc9913be96245709aca36e8bdf19285b26.png', '', '', '', '西条和 / 天城莎莉 / 仓丸莉子 / 寺川千春 / 吉宫瑠织 / 白泽加奈惠 / 宫濑玲奈 / 河濑诗 / 凉花萌 / 日永丽 / 武田爱奈', '阿保孝雄', '', '', '泷川美羽突然收到来自演艺事务所“G.I.P”的一封信。信上说被选为某个新项目的成员。她半信半疑地去了信上的地方，被命运引导一样地聚集了，包含美羽在内的的8个少女们。“你们将作为偶像组合正式出道”——被', '全13集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 1, 0, 1, 1, '', 0, 0, 9.3, 0, 0, 1739750925, 1739708466, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>泷川美羽突然收到来自演艺事务所“G.I.P”的一封信。信上说被选为某个新项目的成员。她半信半疑地去了信上的地方，被命运引导一样地聚集了，包含美羽在内的的8个少女们。“你们将作为偶像组合正式出道”——被自称是合田的男子指引着，出现在她们眼前的是地下的绝密设施和神秘的“墙壁”。\r\n美羽8人向着光与暗交织的命运舞台迈进……就这样前所未有的新偶像诞生。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5721BE80BD1A0C5850E978#第02集$MOE5721BE80BD1A0C5850E97B#第03集$MOE5721BE80BD1A0C5850E97A#第04集$MOE5721BE80BD1A0C5850E97D#第05集$MOE5721BE80BD1A0C5850E97C#第06集$MOE5721BE80BD1A0C5850E97F#第07集$MOE5721BE80BD1A0C5850E97E#第08集$MOE5721BE80BD1A0C5850E971#第09集$MOE5721BE80BD1A0C5850E970#第10集$MOE5721BE80BD1A0C5850E879#第11集$MOE5721BE80BD1A0C5850E878#第12集$MOE5721BE80BD1A0C5850E87B#第13集$MOE5721BE80BD1A0C5850E87A$$$第01集$id_XS5721BE80BD1A0C5850E978#第02集$id_XS5721BE80BD1A0C5850E97B#第03集$id_XS5721BE80BD1A0C5850E97A#第04集$id_XS5721BE80BD1A0C5850E97D#第05集$id_XS5721BE80BD1A0C5850E97C#第06集$id_XS5721BE80BD1A0C5850E97F#第07集$id_XS5721BE80BD1A0C5850E97E#第08集$id_XS5721BE80BD1A0C5850E971#第09集$id_XS5721BE80BD1A0C5850E970#第10集$id_XS5721BE80BD1A0C5850E879#第11集$id_XS5721BE80BD1A0C5850E878#第12集$id_XS5721BE80BD1A0C5850E87B#第13集$id_XS5721BE80BD1A0C5850E87A$$$第01集$id_MOE5721BE80BD1A0C5850E978#第02集$id_MOE5721BE80BD1A0C5850E97B#第03集$id_MOE5721BE80BD1A0C5850E97A#第04集$id_MOE5721BE80BD1A0C5850E97D#第05集$id_MOE5721BE80BD1A0C5850E97C#第06集$id_MOE5721BE80BD1A0C5850E97F#第07集$id_MOE5721BE80BD1A0C5850E97E#第08集$id_MOE5721BE80BD1A0C5850E971#第09集$id_MOE5721BE80BD1A0C5850E970#第10集$id_MOE5721BE80BD1A0C5850E879#第11集$id_MOE5721BE80BD1A0C5850E878#第12集$id_MOE5721BE80BD1A0C5850E87B#第13集$id_MOE5721BE80BD1A0C5850E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1029, 1, 0, 0, '多田君不恋爱', '多田くんは恋をしない（2018）', 'duotianjunbulianai', 1, 'D', '', '81f97e81', '恋爱,原创', 'http://i0.hdslb.com/bfs/bangumi/493877cdb06040c52886d6ebef19ac94dcde96b6.jpg', '', '', '', '中村悠一 / 石见舞菜香 / 宫野真守 / 下地紫野 / 梅原裕一郎 / 石上静香 / 下野纮 / 水濑祈 / 樱井孝宏', '山崎光惠 / 藤原佳幸 / 越田知明 / 竹下良平 / 鸟羽聪 / 平牧大辅', '', '', '手持相机，拍摄盛开樱花照片的多田光良，与刚刚从异国他乡来到日本的少女特蕾莎·瓦格纳相遇了。从欧洲的拉森堡来到日本留学的特蕾莎，刚一到达日本，就和一起过来的伙伴走散而迷路了。由此而开始帮助她的光良，将特', '全13集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 8.9, 0, 0, 1739751015, 1739708581, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>手持相机，拍摄盛开樱花照片的多田光良，与刚刚从异国他乡来到日本的少女特蕾莎·瓦格纳相遇了。从欧洲的拉森堡来到日本留学的特蕾莎，刚一到达日本，就和一起过来的伙伴走散而迷路了。由此而开始帮助她的光良，将特蕾莎带到了祖父经营的多田咖啡店……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0926EA81BE4C550850E978#第02集$MOE0926EA81BE4C550850E97B#第03集$MOE0926EA81BE4C550850E97A#第04集$MOE0926EA81BE4C550850E97D#第05集$MOE0926EA81BE4C550850E97C#第06集$MOE0926EA81BE4C550850E97F#第07集$MOE0926EA81BE4C550850E97E#第08集$MOE0926EA81BE4C550850E971#第09集$MOE0926EA81BE4C550850E970#第10集$MOE0926EA81BE4C550850E879#第11集$MOE0926EA81BE4C550850E878#第12集$MOE0926EA81BE4C550850E87B#第13集$MOE0926EA81BE4C550850E87A$$$第01集$id_XS0926EA81BE4C550850E978#第02集$id_XS0926EA81BE4C550850E97B#第03集$id_XS0926EA81BE4C550850E97A#第04集$id_XS0926EA81BE4C550850E97D#第05集$id_XS0926EA81BE4C550850E97C#第06集$id_XS0926EA81BE4C550850E97F#第07集$id_XS0926EA81BE4C550850E97E#第08集$id_XS0926EA81BE4C550850E971#第09集$id_XS0926EA81BE4C550850E970#第10集$id_XS0926EA81BE4C550850E879#第11集$id_XS0926EA81BE4C550850E878#第12集$id_XS0926EA81BE4C550850E87B#第13集$id_XS0926EA81BE4C550850E87A$$$第01集$id_MOE0926EA81BE4C550850E978#第02集$id_MOE0926EA81BE4C550850E97B#第03集$id_MOE0926EA81BE4C550850E97A#第04集$id_MOE0926EA81BE4C550850E97D#第05集$id_MOE0926EA81BE4C550850E97C#第06集$id_MOE0926EA81BE4C550850E97F#第07集$id_MOE0926EA81BE4C550850E97E#第08集$id_MOE0926EA81BE4C550850E971#第09集$id_MOE0926EA81BE4C550850E970#第10集$id_MOE0926EA81BE4C550850E879#第11集$