INSERT INTO `mac_vod` VALUES (1033, 1, 0, 0, '青春纪行 / 金色时光', 'ゴールデンタイム（2013）', 'qingchunjixingjinseshiguang', 1, 'Q', '', '80e55a9f', '日常,小说改', 'http://i0.hdslb.com/bfs/bangumi/0f8c9a4532a7cf47ce65fb60a3ce8fbedf836694.jpg', '', '', '', '堀江由衣 / 古川慎 / 茅野爱衣 / 石川界人 / 木户衣吹 / 比上孝浩 / 佐藤聪美', '今千秋 / 则座诚 / 湖山祯崇 / 中野英明 / 山崎隆 / 本间修 / 梶井濑贺', '', '', '多田万里顺利考上大学而来到东京。上大学、来东京、一个人生活，这许许多多的第一次经验都让他雀跃不已，却在入学典礼这天突然面临挑战……压倒众人的大小姐气势！完美的人生脚本！最擅长自说自话！攻击者的名字叫做', '全24集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.5, 0, 0, 1739812642, 1739772553, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>多田万里顺利考上大学而来到东京。上大学、来东京、一个人生活，这许许多多的第一次经验都让他雀跃不已，却在入学典礼这天突然面临挑战……压倒众人的大小姐气势！完美的人生脚本！最擅长自说自话！攻击者的名字叫做加贺香子。手持玫瑰花束殴打光央的她，听说是为了跟随青梅竹马，也就是万里的好友柳泽，而进入同一间大学。耀眼又危险的香子，万里无法置之不理，校园青春爱情喜剧却又会发生什么故事？\r\n\r\nTV动画「金色时光」是由竹宫悠由子撰写，驹都英二负责插图的轻小说「金色时光」改编而来的。作品主要围绕失去高中毕业之前记忆的男大学生多田万里和外表完美内在残念的大小姐加贺香子，以及加贺香子暗恋的柳泽光央等人之间的大学校园恋爱故事展开。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0927E98DBC48545F50E978#第02集$MOE0927E98DBC48545F50E97B#第03集$MOE0927E98DBC48545F50E97A#第04集$MOE0927E98DBC48545F50E97D#第05集$MOE0927E98DBC48545F50E97C#第06集$MOE0927E98DBC48545F50E97F#第07集$MOE0927E98DBC48545F50E97E#第08集$MOE0927E98DBC48545F50E971#第09集$MOE0927E98DBC48545F50E970#第10集$MOE0927E98DBC48545F50E879#第11集$MOE0927E98DBC48545F50E878#第12集$MOE0927E98DBC48545F50E87B#第13集$MOE0927E98DBC48545F50E87A#第14集$MOE0927E98DBC48545F50E87D#第15集$MOE0927E98DBC48545F50E87C#第16集$MOE0927E98DBC48545F50E87F#第17集$MOE0927E98DBC48545F50E87E#第18集$MOE0927E98DBC48545F50E871#第19集$MOE0927E98DBC48545F50E870#第20集$MOE0927E98DBC48545F50EB79#第21集$MOE0927E98DBC48545F50EB78#第22集$MOE0927E98DBC48545F50EB7B#第23集$MOE0927E98DBC48545F50EB7A#第24集$MOE0927E98DBC48545F50EB7D$$$第01集$id_XS0927E98DBC48545F50E978#第02集$id_XS0927E98DBC48545F50E97B#第03集$id_XS0927E98DBC48545F50E97A#第04集$id_XS0927E98DBC48545F50E97D#第05集$id_XS0927E98DBC48545F50E97C#第06集$id_XS0927E98DBC48545F50E97F#第07集$id_XS0927E98DBC48545F50E97E#第08集$id_XS0927E98DBC48545F50E971#第09集$id_XS0927E98DBC48545F50E970#第10集$id_XS0927E98DBC48545F50E879#第11集$id_XS0927E98DBC48545F50E878#第12集$id_XS0927E98DBC48545F50E87B#第13集$id_XS0927E98DBC48545F50E87A#第14集$id_XS0927E98DBC48545F50E87D#第15集$id_XS0927E98DBC48545F50E87C#第16集$id_XS0927E98DBC48545F50E87F#第17集$id_XS0927E98DBC48545F50E87E#第18集$id_XS0927E98DBC48545F50E871#第19集$id_XS0927E98DBC48545F50E870#第20集$id_XS0927E98DBC48545F50EB79#第21集$id_XS0927E98DBC48545F50EB78#第22集$id_XS0927E98DBC48545F50EB7B#第23集$id_XS0927E98DBC48545F50EB7A#第24集$id_XS0927E98DBC48545F50EB7D$$$第01集$id_MOE0927E98DBC48545F50E978#第02集$id_MOE0927E98DBC48545F50E97B#第03集$id_MOE0927E98DBC48545F50E97A#第04集$id_MOE0927E98DBC48545F50E97D#第05集$id_MOE0927E98DBC48545F50E97C#第06集$id_MOE0927E98DBC48545F50E97F#第07集$id_MOE0927E98DBC48545F50E97E#第08集$id_MOE0927E98DBC48545F50E971#第09集$id_MOE0927E98DBC48545F50E970#第10集$id_MOE0927E98DBC48545F50E879#第11集$id_MOE0927E98DBC48545F50E878#第12集$id_MOE0927E98DBC48545F50E87B#第13集$id_MOE0927E98DBC48545F50E87A#第14集$id_MOE0927E98DBC48545F50E87D#第15集$id_MOE0927E98DBC48545F50E87C#第16集$id_MOE0927E98DBC48545F50E87F#第17集$id_MOE0927E98DBC48545F50E87E#第18集$id_MOE0927E98DBC48545F50E871#第19集$id_MOE0927E98DBC48545F50E870#第20集$id_MOE0927E98DBC48545F50EB79#第21集$id_MOE0927E98DBC48545F50EB78#第22集$id_MOE0927E98DBC48545F50EB7B#第23集$id_MOE0927E98DBC48545F50EB7A#第24集$id_MOE0927E98DBC48545F50EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1034, 1, 0, 0, '敦君与女朋友', 'あっくんとカノジョ（2018）', 'dunjunyunvpengyou', 1, 'D', '', '1ad1d11f', '恋爱,漫画改', 'http://i0.hdslb.com/bfs/bangumi/3ee3e267731be4cac9ef39a905714de06fd66d59.jpg', '', '', '', '铃木达央 / 诹访彩花 / 植田圭辅 / 香里有佐 / 羽多野涉 / 嘉阳光', '片贝慎', '', '', '青梅竹马的敦君和小音是一对恋人。但，敦君却以粗暴的言辞冷淡对待小音，总是一副严苛的态度……。\r\n但那却是敦君的“最喜欢小音了！”这种心情的反面表现。敦君，以及对于敦君的这种言行毫不在意地“深爱敦君”的小', '全25集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.4, 0, 0, 1739812907, 1739783353, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>青梅竹马的敦君和小音是一对恋人。但，敦君却以粗暴的言辞冷淡对待小音，总是一副严苛的态度……。\r\n但那却是敦君的“最喜欢小音了！”这种心情的反面表现。敦君，以及对于敦君的这种言行毫不在意地“深爱敦君”的小音，描绘他们之间日常的学园青春恋爱喜剧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0076E889ED185C5F50E978#第02集$MOE0076E889ED185C5F50E97B#第03集$MOE0076E889ED185C5F50E97A#第04集$MOE0076E889ED185C5F50E97D#第05集$MOE0076E889ED185C5F50E97C#第06集$MOE0076E889ED185C5F50E97F#第07集$MOE0076E889ED185C5F50E97E#第08集$MOE0076E889ED185C5F50E971#第09集$MOE0076E889ED185C5F50E970#第10集$MOE0076E889ED185C5F50E879#第11集$MOE0076E889ED185C5F50E878#第12集$MOE0076E889ED185C5F50E87B#第13集$MOE0076E889ED185C5F50E87A#第14集$MOE0076E889ED185C5F50E87D#第15集$MOE0076E889ED185C5F50E87C#第16集$MOE0076E889ED185C5F50E87F#第17集$MOE0076E889ED185C5F50E87E#第18集$MOE0076E889ED185C5F50E871#第19集$MOE0076E889ED185C5F50E870#第20集$MOE0076E889ED185C5F50EB79#第21集$MOE0076E889ED185C5F50EB78#第22集$MOE0076E889ED185C5F50EB7B#第23集$MOE0076E889ED185C5F50EB7A#第24集$MOE0076E889ED185C5F50EB7D#第25集$MOE0076E889ED185C5F50EB7C$$$第01集$id_XS0076E889ED185C5F50E978#第02集$id_XS0076E889ED185C5F50E97B#第03集$id_XS0076E889ED185C5F50E97A#第04集$id_XS0076E889ED185C5F50E97D#第05集$id_XS0076E889ED185C5F50E97C#第06集$id_XS0076E889ED185C5F50E97F#第07集$id_XS0076E889ED185C5F50E97E#第08集$id_XS0076E889ED185C5F50E971#第09集$id_XS0076E889ED185C5F50E970#第10集$id_XS0076E889ED185C5F50E879#第11集$id_XS0076E889ED185C5F50E878#第12集$id_XS0076E889ED185C5F50E87B#第13集$id_XS0076E889ED185C5F50E87A#第14集$id_XS0076E889ED185C