INSERT INTO `mac_vod` VALUES (1035, 1, 0, 0, 'Comic Girls', 'こみっくがーるず（2018）', 'ComicGirls', 1, 'C', '', '20779b11', '搞笑,日常,漫画改', 'http://i0.hdslb.com/bfs/bangumi/4d14e521d22af0d0d9747e2f063d400a0646c8d5.png', '', '', '', '赤尾光 / 本渡枫 / 大西沙织 / 高桥李依 / 远藤绫 / 津田美波 / 七濑彩夏 / 上田丽奈 / 小泽亚李 / 井泽美香子 / 市道真央 / 村川梨衣 / 能登麻美子 / 川澄绫子 / 石上静香 / 贯井柚佳 / 筱田南 / 柳田淳一', '德本善信 / 高岛大辅 / 中西和也 / 宫西哲也', '', '', '萌田薰子（笔名：薰子）15岁。女子高中生、四格漫画家！搬进漫画家专用的女子宿舍的她，被同室的少女漫画家小梦和TL漫画家琉姬、少年漫画家翼等同伴们所围绕，今天也愉快地绘制原稿，彻夜工作！可爱又有趣的漫画', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.8, 0, 0, 1739812996, 1739783444, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>萌田薰子（笔名：薰子）15岁。女子高中生、四格漫画家！搬进漫画家专用的女子宿舍的她，被同室的少女漫画家小梦和TL漫画家琉姬、少年漫画家翼等同伴们所围绕，今天也愉快地绘制原稿，彻夜工作！可爱又有趣的漫画家生活就此开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0327BB8FB04B5C0850E978#第02集$MOE0327BB8FB04B5C0850E97B#第03集$MOE0327BB8FB04B5C0850E97A#第04集$MOE0327BB8FB04B5C0850E97D#第05集$MOE0327BB8FB04B5C0850E97C#第06集$MOE0327BB8FB04B5C0850E97F#第07集$MOE0327BB8FB04B5C0850E97E#第08集$MOE0327BB8FB04B5C0850E971#第09集$MOE0327BB8FB04B5C0850E970#第10集$MOE0327BB8FB04B5C0850E879#第11集$MOE0327BB8FB04B5C0850E878#第12集$MOE0327BB8FB04B5C0850E87B$$$第01集$id_XS0327BB8FB04B5C0850E978#第02集$id_XS0327BB8FB04B5C0850E97B#第03集$id_XS0327BB8FB04B5C0850E97A#第04集$id_XS0327BB8FB04B5C0850E97D#第05集$id_XS0327BB8FB04B5C0850E97C#第06集$id_XS0327BB8FB04B5C0850E97F#第07集$id_XS0327BB8FB04B5C0850E97E#第08集$id_XS0327BB8FB04B5C0850E971#第09集$id_XS0327BB8FB04B5C0850E970#第10集$id_XS0327BB8FB04B5C0850E879#第11集$id_XS0327BB8FB04B5C0850E878#第12集$id_XS0327BB8FB04B5C0850E87B$$$第01集$id_MOE0327BB8FB04B5C0850E978#第02集$id_MOE0327BB8FB04B5C0850E97B#第03集$id_MOE0327BB8FB04B5C0850E97A#第04集$id_MOE0327BB8FB04B5C0850E97D#第05集$id_MOE0327BB8FB04B5C0850E97C#第06集$id_MOE0327BB8FB04B5C0850E97F#第07集$id_MOE0327BB8FB04B5C0850E97E#第08集$id_MOE0327BB8FB04B5C0850E971#第09集$id_MOE0327BB8FB04B5C0850E970#第10集$id_MOE0327BB8FB04B5C0850E879#第11集$id_MOE0327BB8FB04B5C0850E8