INSERT INTO `mac_vod` VALUES (1036, 1, 0, 0, '恋爱小行星', '恋する小惑星（2020）', 'lianaixiaoxingxing', 1, 'L', '', '8cc5a450', '漫画改,搞笑,日常,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/091c239253b95c1c8d32d76ae18bbd14887b8cc4.png', '', '', '', '高柳知叶 / 山口爱 / 指出毬亚 / 东山奈央 / 上坂堇 / 上田丽奈', '平牧大辅 / 藤井隆文 / 由井翠 / 关野圭一', '', '', '木之幡米拉在小时候与在露营地遇见的男生约定，“要找到小行星”。上了高中后她本打算加入天文社，但从今年开始“天文社”就和“地质研究会”合并成了“地学社”……！？\r\n和地学系女孩们一起，去寻找各种各样闪闪发', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.7, 0, 0, 1739860997, 1739783499, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>木之幡米拉在小时候与在露营地遇见的男生约定，“要找到小行星”。上了高中后她本打算加入天文社，但从今年开始“天文社”就和“地质研究会”合并成了“地学社”……！？\r\n和地学系女孩们一起，去寻找各种各样闪闪发亮的东西吧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0974EF8DE81D580950E978#第02集$MOE0974EF8DE81D580950E97B#第03集$MOE0974EF8DE81D580950E97A#第04集$MOE0974EF8DE81D580950E97D#第05集$MOE0974EF8DE81D580950E97C#第06集$MOE0974EF8DE81D580950E97F#第07集$MOE0974EF8DE81D580950E97E#第08集$MOE0974EF8DE81D580950E971#第09集$MOE0974EF8DE81D580950E970#第10集$MOE0974EF8DE81D580950E879#第11集$MOE0974EF8DE81D580950E878#第12集$MOE0974EF8DE81D580950E87B$$$第01集$id_XS0974EF8DE81D580950E978#第02集$id_XS0974EF8DE81D580950E97B#第03集$id_XS0974EF8DE81D580950E97A#第04集$id_XS0974EF8DE81D580950E97D#第05集$id_XS0974EF8DE81D580950E97C#第06集$id_XS0974EF8DE81D580950E97F#第07集$id_XS0974EF8DE81D580950E97E#第08集$id_XS0974EF8DE81D580950E971#第09集$id_XS0974EF8DE81D580950E970#第10集$id_XS0974EF8DE81D580950E879#第11集$id_XS0974EF8DE81D580950E878#第12集$id_XS0974EF8DE81D580950E87B$$$第01集$id_MOE0974EF8DE81D580950E978#第02集$id_MOE0974EF8DE81D580950E97B#第03集$id_MOE0974EF8DE81D580950E97A#第04集$id_MOE0974EF8DE81D580950E97D#第05集$id_MOE0974EF8DE81D580950E97C#第06集$id_MOE0974EF8DE81D580950E97F#第07集$id_MOE0974EF8DE81D580950E97E#第08集$id_MOE0974EF8DE81D580950E971#第09集$id_MOE0974EF8DE81D580950E970#第10集$id_MOE0974EF8DE81D580950E879#第11集$id_MOE0974EF8DE81D580950E878#第12集$id_MOE0974EF8DE81D580950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1037, 1, 0, 0, '索玛丽与森林之神', 'ソマリと森の神様（2020）', 'suomaliyusenlinzhishen', 1, 'S', '', '28641b10', '架空,漫画改,奇幻,萌系', 'http://i0.hdslb.com/bfs/bangumi/image/436df68b96dab19ecfe4c6016776b07df124ea90.jpg', '', '', '', '水濑祈 / 小野大辅 / 七海弘希 / 铃木达央 / 小野友树 / 早见沙织 / 小林优 / 速水奖 / 关智一 / 茅野爱衣 / 高垣彩阳 / 柴田理惠', '安田贤司 / 名和宗则 / 佐藤英一 / 小高义规 / 大久保朋', '', '', '“人类（那小东西）”称“哥雷姆（我）”为父亲。这是一个存在着哥雷姆、鬼、魔女等多个种族的世界，其中唯有人类遭受迫害，面临着灭绝的危机。就在某一天，森林守护者哥雷姆，与一名人类少女索玛丽相遇了。哥雷姆带', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.8, 0, 0, 1739861123, 1739783506, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“人类（那小东西）”称“哥雷姆（我）”为父亲。这是一个存在着哥雷姆、鬼、魔女等多个种族的世界，其中唯有人类遭受迫害，面临着灭绝的危机。就在某一天，森林守护者哥雷姆，与一名人类少女索玛丽相遇了。哥雷姆带着天真的索玛丽，离开森林，踏上了寻找其他人类的旅程——而在这段旅程中，原本不具备感情的哥雷姆，逐渐萌生出了心灵，许下了作为索玛丽的父亲，永远与她在一起的约定……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032FBA8CB84B5C0950E978#第02集$MOE032FBA8CB84B5C0950E97B#第03集$MOE032FBA8CB84B5C0950E97A#第04集$MOE032FBA8CB84B5C0950E97D#第05集$MOE032FBA8CB84B5C0950E97C#第06集$MOE032FBA8CB84B5C0950E97F#第07集$MOE032FBA8CB84B5C0950E97E#第08集$MOE032FBA8CB84B5C0950E971#第09集$MOE032FBA8CB84B5C0950E970#第10集$MOE032FBA8CB84B5C0950E879#第11集$MOE032FBA8CB84B5C0950E878#第12集$MOE032FBA8CB84B5C0950E87B$$$第01集$id_XS032FBA8CB84B5C0950E978#第02集$id_XS032FBA8CB84B5C0950E97B#第03集$id_XS032FBA8CB84B5C0950E97A#第04集$id_XS032FBA8CB84B5C0950E97D#第05集$id_XS032FBA8CB84B5C0950E97C#第06集$id_XS032FBA8CB84B5C0950E97F#第07集$id_XS032FBA8CB84B5C0950E97E#第08集$id_XS032FBA8CB84B5C0950E971#第09集$id_XS032FBA8CB84B5C0950E970#第10集$id_XS032FBA8CB84B5C0950E879#第11集$id_XS032FBA8CB84B5C0950E878#第12集$id_XS032FBA8CB84B5C0950E87B$$$第01集$id_MOE032FBA8CB84B5C0950E978#第02集$id_MOE032FBA8CB84B5C0950E97B#第03集$id_MOE032FBA8CB84B5C0950E97A#第04集$id_MOE032FBA8CB84B5C0950E97D#第05集$id_MOE032FBA8CB84B5C0950E97C#第06集$id_MOE032FBA8CB84B5C0950E97F#第07集$id_MOE032FBA8CB84B5C0950E97E#第08集$id_MOE032FBA8CB84B5C0950E971#第09集$id_MOE032FBA8CB84B5C0950E970#第10集$id_MOE032FBA8CB84B5C0950E879#第11集$id_MOE032FBA8CB84B5C0950E878#第12集$id_MOE032FBA8CB84B5C0950E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1038, 1, 0, 0, '逆转裁判', '逆転裁判 〜その「真実」、異議あり!〜（2016）', 'nizhuancaipan', 1, 'N', '', '6bb8205e', '推理,智斗,游戏改,职场', 'https://i0.hdslb.com/bfs/bangumi/7da415b5c2835432af78f542c2e35284334af348.jpg', '', '', '', '梶裕贵 / 悠木碧 / 玉木雅士 / 中村千绘 / 岩崎征实 / 奈良彻', '渡边步', '', '', '被卷入奇怪事件的委托人们。主人公新人律师成步堂龙一，为了洗清他们的嫌疑挺身而出。\r\n被告人是有罪，还是无罪……。成步堂信任着委托人，与对手的法官们在法庭上展开热烈的战斗。\r\n在被逼入走投无路的危机，似乎万', '全24集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.9, 0, 0, 1739861212, 1739783521, 0, 0, 0, 0, 0.0, '', '1039', '', '', '', '', '', '', '', '<p>被卷入奇怪事件的委托人们。主人公新人律师成步堂龙一，为了洗清他们的嫌疑挺身而出。\r\n被告人是有罪，还是无罪……。成步堂信任着委托人，与对手的法官们在法庭上展开热烈的战斗。\r\n在被逼入走投无路的危机，似乎万事休矣的瞬间，伴随着“有异议！”这句话，从细微的证据当中，突破矛盾，引发华丽的逆转剧！\r\n以成步堂的师父、美人律师绫里千寻，助手绫里真宵，对手检察官御剑怜侍为首，众多个性丰富的角色们所带来的，戏剧性的交涉所交织的章节也引人注目！动画还将深刻描绘成步堂与伙伴们自幼开始的牵绊以及友情。\r\n将被扭曲的真实，利用从师父那里继承的想法来逆转，动摇，发表异议，导出真相。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775EE80BB19585C50E978#第02集$MOE0775EE80BB19585C50E97B#第03集$MOE0775EE80BB19585C50E97A#第04集$MOE0775EE80BB19585C50E97D#第05集$MOE0775EE80BB19585C50E97C#第06集$MOE0775EE80BB19585C50E97F#第07集$MOE0775EE80BB19585C50E97E#第08集$MOE0775EE80BB19585C50E971#第09集$MOE0775EE80BB19585C50E970#第10集$MOE0775EE80BB19585C50E879#第11集$MOE0775EE80BB19585C50E878#第12集$MOE0775EE80BB19585C50E87B#第13集$MOE0775EE80BB19585C50E87A#第14集$MOE0775EE80BB19585C50E87D#第15集$MOE0775EE80BB19585C50E87C#第16集$MOE0775EE80BB19585C50E87F#第17集$MOE0775EE80BB19585C50E87E#第18集$MOE0775EE80BB19585C50E871#第19集$MOE0775EE80BB19585C50E870#第20集$MOE0775EE80BB19585C50EB79#第21集$MOE0775EE80BB19585C50EB78#第22集$MOE0775EE80BB19585C50EB7B#第23集$MOE0775EE80BB19585C50EB7A#第24集$MOE0775EE80BB19585C50EB7D$$$第01集$id_XS0775EE80BB19585C50E978#第02集$id_XS0775EE80BB19585C50E97B#第03集$id_XS0775EE80BB19585C50E97A#第04集$id_XS0775EE80BB19585C50E97D#第05集$id_XS0775EE80BB19585C50E97C#第06集$id_XS0775EE80BB19585C50E97F#第07集$id_XS0775EE80BB19585C50E97E#第08集$id_XS0775EE80BB19585C50E971#第09集$id_XS0775EE80BB19585C50E970#第10集$id_XS0775EE80BB19585C50E879#第11集$id_XS0775EE80BB19585C50E878#第12集$id_XS0775EE80BB19585C50E87B#第13集$id_XS0775EE80BB19585C50E87A#第14集$id_XS0775EE80BB19585C50E87D#第15集$id_XS0775EE80BB19585C50E87C#第16集$id_XS0775EE80BB19585C50E87F#第17集$id_XS0775EE80BB19585C50E87E#第18集$id_XS0775EE80BB19585C50E871#第19集$id_XS0775EE80BB19585C50E870#第20集$id_XS0775EE80BB19585C50EB79#第21集$id_XS0775EE80BB19585C50EB78#第22集$id_XS0775EE80BB19585C50EB7B#第23集$id_XS0775EE80BB19585C50EB7A#第24集$id_XS0775EE80BB19585C50EB7D$$$第01集$id_MOE0775EE80BB19585C50E978#第02集$id_MOE0775EE80BB19585C50E97B#第03集$id_MOE0775EE80BB19585C50E97A#第04集$id_MOE0775EE80BB19585C50E97D#第05集$id_MOE0775EE80BB19585C50E97C#第06集$id_MOE0775EE80BB19585C50E97F#第07集$id_MOE0775EE80BB19585C50E97E#第08集$id_MOE0775EE80BB19585C50E971#第09集$id_MOE0775EE80BB19585C50E970#第10集$id_MOE0775EE80BB19585C50E879#第11集$id_MOE0775EE80BB19585C50E878#第12集$id_MOE0775EE80BB19585C50E87B#第13集$id_MOE0775EE80BB19585C50E87A#第14集$id_MOE0775EE80BB19585C50E87D#第15集$id_MOE0775EE80BB19585C50E87C#第16集$id_MOE0775EE80BB19585C50E87F#第17集$id_MOE0775EE80BB19585C50E87E#第18集$id_MOE0775EE80BB19585C50E871#第19集$id_MOE0775EE80BB19585C50E870#第20集$id_MOE0775EE80BB19585C50EB79#第21集$id_MOE0775EE80BB19585C50EB78#第22集$id_MOE0775EE80BB19585C50EB7B#第23集$id_MOE0775EE80BB19585C50EB7A#第24集$id_MOE0775EE80BB19585C50EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1039, 1, 0, 0, '逆转裁判 第二季', '逆転裁判 ～その「真実」、異議あり！～ Season 2（2018）', 'nizhuancaipandierji', 1, 'N', '', 'ad954f17', '推理,游戏改', 'http://i0.hdslb.com/bfs/bangumi/024a6d1884244f6e27428a080327ad609d184f7d.jpg', '', '', '', '梶裕贵 / 悠木碧 / 玉木雅士 / 中村千绘 / 岩崎征实 / 奈良彻 / 平田广明', '渡边步', '', '', '被卷入奇怪事件的委托人们。主人公新人律师成步堂龙一，为了洗清他们的嫌疑挺身而出。 被告人是有罪，还是无罪……。成步堂信任着委托人，与对手的法官们在法庭上展开热烈的战斗。 在被逼入走投无路的危机，似乎万', '全23集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 9.5, 0, 0, 1739872131, 1739855949, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>被卷入奇怪事件的委托人们。主人公新人律师成步堂龙一，为了洗清他们的嫌疑挺身而出。 被告人是有罪，还是无罪……。成步堂信任着委托人，与对手的法官们在法庭上展开热烈的战斗。 在被逼入走投无路的危机，似乎万事休矣的瞬间，伴随着“有异议！”这句话，从细微的证据当中，突破矛盾，引发华丽的逆转剧！ 以成步堂的师父、美人律师绫里千寻，助手绫里真宵，对手检察官御剑怜侍为首，众多个性丰富的角色们所带来的，戏剧性的交涉所交织的章节也引人注目！动画还将深刻描绘成步堂与伙伴们自幼开始的牵绊以及友情。 将被扭曲的真实，利用从师父那里继承的想法来逆转，动摇，发表异议，导出真相。 为动画界带来新风的痛快解谜法庭战斗，敬请期待！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5073B58DBD4F5C0E50E978#第02集$MOE5073B58DBD4F5C0E50E97B#第03集$MOE5073B58DBD4F5C0E50E97A#第04集$MOE5073B58DBD4F5C0E50E97D#第05集$MOE5073B58DBD4F5C0E50E97C#第06集$MOE5073B58DBD4F5C0E50E97F#第07集$MOE5073B58DBD4F5C0E50E97E#第08集$MOE5073B58DBD4F5C0E50E971#第09集$MOE5073B58DBD4F5C0E50E970#第10集$MOE5073B58DBD4F5C0E50E879#第11集$MOE5073B58DBD4F5C0E50E878#第12集$MOE5073B58DBD4F5C0E50E87B#第13集$MOE5073B58DBD4F5C0E50E87A#第14集$MOE5073B58DBD4F5C0E50E87D#第15集$MOE5073B58DBD4F5C0E50E87C#第16集$MOE5073B58DBD4F5C0E50E87F#第17集$MOE5073B58DBD4F5C0E50E87E#第18集$MOE5073B58DBD4F5C0E50E871#第19集$MOE5073B58DBD4F5C0E50E870#第20集$MOE5073B58DBD4F5C0E50EB79#第21集$MOE5073B58DBD4F5C0E50EB78#第22集$MOE5073B58DBD4F5C0E50EB7B#第23集$MOE5073B58DBD4F5C0E50EB7A$$$第01集$id_XS5073B58DBD4F5C0E50E978#第02集$id_XS5073B58DBD4F5C0E50E97B#第03集$id_XS5073B58DBD4F5C0E50E97A#第04集$id_XS5073B58DBD4F5C0E50E97D#第05集$id_XS5073B58DBD4F5C0E50E97C#第06集$id_XS5073B58DBD4F5C0E50E97F#第07集$id_XS5073B58DBD4F5C0E50E97E#第08集$id_XS5073B58DBD4F5C0E50E971#第09集$id_XS5073B58DBD4F5C0E50E970#第10集$id_XS5073