INSERT INTO `mac_vod` VALUES (1040, 1, 0, 0, '水果篮子 (2019)', 'フルーツバスケット 1st season（2019）', 'shuiguolanzi2019', 1, 'S', '', '720a9a14', '漫画改,奇幻,校园,恋爱', 'http://i0.hdslb.com/bfs/bangumi/d07029e4116a7a424c922d9b85173915d4287fe0.png', '', '', '', '石见舞菜香 / 岛崎信长 / 内田雄马 / 中村悠一 / 种崎敦美 / 佐藤聪美 / 钉宫理惠 / 潘惠美 / 古川慎 / 兴津和幸 / 樱井孝宏 / 坂本真绫 / 泽城美雪 / 市道真央', '井端义秀 / 殿胜秀树 / 高岛大辅 / 榎本明广 / 猪狩崇 / 平向智子 / 川越崇弘 / 铃木孝聪 / 土屋康郎 / 工藤宽显 / 野木森达哉', '', '', '高中生本田透在失去了自己唯一亲人的母亲之后过起了独自一人的帐篷生活。但是，透安扎帐篷的地方刚好就是历史渊源的家族“草摩家”的领地之内！在草摩紫吴的邀请下成为了草摩家佣人的透，居然要与学校里王子般存在的', '全25集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 9.7, 0, 0, 1739895379, 1739861889, 0, 0, 0, 0, 0.0, '', '1041,1042', '', '', '', '', '', '', '', '<p>高中生本田透在失去了自己唯一亲人的母亲之后过起了独自一人的帐篷生活。但是，透安扎帐篷的地方刚好就是历史渊源的家族“草摩家”的领地之内！在草摩紫吴的邀请下成为了草摩家佣人的透，居然要与学校里王子般存在的草摩由希、以及视由希为眼中钉的草摩夹这两人一起生活。\r\n然而，透却仍未知晓。“草摩家”自从数百年前起就被忌讳的诅咒所束缚的事实……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0625BCD9B0485C0D50E978#第02集$MOE0625BCD9B0485C0D50E97B#第03集$MOE0625BCD9B0485C0D50E97A#第04集$MOE0625BCD9B0485C0D50E97D#第05集$MOE0625BCD9B0485C0D50E97C#第06集$MOE0625BCD9B0485C0D50E97F#第07集$MOE0625BCD9B0485C0D50E97E#第08集$MOE0625BCD9B0485C0D50E971#第09集$MOE0625BCD9B0485C0D50E970#第10集$MOE0625BCD9B0485C0D50E879#第11集$MOE0625BCD9B0485C0D50E878#第12集$MOE0625BCD9B0485C0D50E87B#第13集$MOE0625BCD9B0485C0D50E87A#第14集$MOE0625BCD9B0485C0D50E87D#第15集$MOE0625BCD9B0485C0D50E87C#第16集$MOE0625BCD9B0485C0D50E87F#第17集$MOE0625BCD9B0485C0D50E87E#第18集$MOE0625BCD9B0485C0D50E871#第19集$MOE0625BCD9B0485C0D50E870#第20集$MOE0625BCD9B0485C0D50EB79#第21集$MOE0625BCD9B0485C0D50EB78#第22集$MOE0625BCD9B0485C0D50EB7B#第23集$MOE0625BCD9B0485C0D50EB7A#第24集$MOE0625BCD9B0485C0D50EB7D#第25集$MOE0625BCD9B0485C0D50EB7C$$$第01集$id_XS0625BCD9B0485C0D50E978#第02集$id_XS0625BCD9B0485C0D50E97B#第03集$id_XS0625BCD9B0485C0D50E97A#第04集$id_XS0625BCD9B0485C0D50E97D#第05集$id_XS0625BCD9B0485C0D50E97C#第06集$id_XS0625BCD9B0485C0D50E97F#第07集$id_XS0625BCD9B0485C0D50E97E#第08集$id_XS0625BCD9B04