INSERT INTO `mac_vod` VALUES (1044, 1, 0, 0, '银仙', '繰繰れ! コックリさん（2014）', 'yinxian', 1, 'Y', '', 'e3f8380', '萌系,搞笑,日常,治愈', 'http://i0.hdslb.com/bfs/bangumi/39bfc409fe95db6812624f378194612de89c143d.jpg', '', '', '', '广桥凉 / 小野大辅 / 樱井孝宏 / 田村由香里 / 中田让治 / 斋藤千和 / 山本和臣 / 野上尤加奈 / 鬼头明里 / 金元寿子 / 白石凉子 / 鸟海浩辅 / 长妻树里 / 岩田光央 / 日野聪 / 飞田展男 / 石上静香 / 野中蓝 / 佐藤利奈', '平池芳正 / 古贺一臣 / 奥野浩行 / 高岛大辅 / 佐佐木纯人 / 飞田刚 / 长冈义孝', '', '', '一人独自生活的市松小雏是个缺乏常识的电波族，某天她在玩弄银仙的过程中，召唤来了一把年纪的狐耳男性——自称“银松”的帅哥妖怪。妖怪对自称“人偶”的电波族市松的不健康生活形态感到担心，忍不住留下来来照顾她', '全12集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.7, 0, 0, 1739952051, 1739924979, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>一人独自生活的市松小雏是个缺乏常识的电波族，某天她在玩弄银仙的过程中，召唤来了一把年纪的狐耳男性——自称“银松”的帅哥妖怪。妖怪对自称“人偶”的电波族市松的不健康生活形态感到担心，忍不住留下来来照顾她……一场超虚脱系又不可思议的搞笑故事就此开演。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5424EA80BA115D144DE8#第02集$MOE5424EA80BA115D144DEB#第03集$MOE5424EA80BA115D144DEA#第04集$MOE5424EA80BA115D144DED#第05集$MOE5424EA80BA115D144DEC#第06集$MOE5424EA80BA115D144DEF#第07集$MOE5424EA80BA115D144DEE#第08集$MOE5424EA80BA115D144DE1#第09集$MOE5424EA80BA115D144DE0#第10集$MOE5424EA80BA115D144CE9#第11集$MOE5424EA80BA115D144CE8#第12集$MOE5424EA80BA115D144CEB$$$第01集$id_XS5424EA80BA115D144DE8#第02集$id_XS5424EA80BA115D144DEB#第03集$id_XS5424EA80BA115D144DEA#第04集$id_XS5424EA80BA115D144DED#第05集$id_XS5424EA80BA115D144DEC#第06集$id_XS5424EA80BA115D144DEF#第07集$id_XS5424EA80BA115D144DEE#第08集$id_XS5424EA80BA115D144DE1#第09集$id_XS5424EA80BA115D144DE0#第10集$id_XS5424EA80BA115D144CE9#第11集$id_XS5424EA80BA115D144CE8#第12集$id_XS5424EA80BA115D144CEB$$$第01集$id_MOE5424EA80BA115D144DE8#第02集$id_MOE5424EA80BA115D144DEB#第03集$id_MOE5424EA80BA115D144DEA#第04集$id_MOE5424EA80BA115D144DED#第05集$id_MOE5424EA80BA115D144DEC#第06集$id_MOE5424EA80BA115D144DEF#第07集$id_MOE5424EA80BA115D144DEE#第08集$id_MOE5424EA80BA115D144DE1#第09集$id_MOE5424EA80BA115D144DE0#第10集$id_MOE5424EA80BA115D144CE9#第11集$id_MOE5424EA80BA115D144CE8#第12集$id_MOE5424EA80BA115D144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1045, 1, 0, 0, '黑岩射手 / BLACK★ROCK SHOOTER', 'ブラック★ロックシューター（2012）', 'heiyansheshouBLACKROCKSHOOTER', 1, 'H', '', 'ea64d7c8', '战斗,穿越,原创', 'http://i0.hdslb.com/bfs/bangumi/image/4e0fbafad83ee9cbb7ee344c3968d79d44f2b2f1.png', '', '', '', '花泽香菜 / 泽城美雪 / 阿澄佳奈 / 能登麻美子 / 喜多村英梨 / 沼仓爱美', '吉冈忍 / 筱原俊哉 / 今石洋之 / 雨宫哲 / 小林宽 / 藤井辰己 / 宇井良和 / 江崎慎平', '', '', '在近现实世界的日本，有一位看似平凡的少女黑衣麻陶，开始了她新一年的中学生活。这时，一位名为小鸟游优美的同班同学吸引了她的注意。对方起初不欲作深层交往，后来却因为彩虹小鸟的话题，而被麻陶见到了小鸟游受委', '全8集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.6, 0, 0, 1739957172, 1739925182, 0, 0, 0, 0, 0.0, '', '1046', '', '', '', '', '', '', '', '<p>在近现实世界的日本，有一位看似平凡的少女黑衣麻陶，开始了她新一年的中学生活。这时，一位名为小鸟游优美的同班同学吸引了她的注意。对方起初不欲作深层交往，后来却因为彩虹小鸟的话题，而被麻陶见到了小鸟游受委屈的一面……\r\n充满怪异的世界中，一群人生活于眼泪般蔚蓝的天空之下，每天都如同战士般进行着明争暗斗，仿佛正为他人承受遇到的苦恼与混乱不堪的思绪……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5476BA8CED1E0E0150E978#第02集$MOE5476BA8CED1E0E0150E97B#第03集$MOE5476BA8CED1E0E0150E97A#第04集$MOE5476BA8CED1E0E0150E97D#第05集$MOE5476BA8CED1E0E0150E97C#第06集$MOE5476BA8CED1E0E0150E97F#第07集$MOE5476BA8CED1E0E0150E97E#第08集$MOE5476BA8CED1E0E0150E971$$$第01集$id_XS5476BA8CED1E0E0150E978#第02集$id_XS5476BA8CED1E0E0150E97B#第03集$id_XS5476BA8CED1E0E0150E97A#第04集$id_XS5476BA8CED1E0E0150E97D#第05集$id_XS5476BA8CED1E0E0150E97C#第06集$id_XS5476BA8CED1E0E0150E97F#第07集$id_XS5476BA8CED1E0E0150E97E#第08集$id_XS5476BA8CED1E0E0150E971$$$第01集$id_MOE5476BA8CED1E0E0150E978#第02集$id_MOE5476BA8CED1E0E0150E97B#第03集$id_MOE5476BA8CED1E0E0150E97A#第04集$id_MOE5476BA8CED1E0E0150E97D#第05集$id_MOE5476BA8CED1E0E0150E97C#第06集$id_MOE5476BA8CED1E0E0150E97F#第07集$id_MOE5476BA8CED1E0E0150E97E#第08集$id_MOE5476BA8CED1E0E0150E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1046, 1, 0, 0, 'BLACK★ROCK SHOOTER OVA', 'ブラック★ロックシューター（2010）', 'BLACKROCKSHOOTEROVA', 1, 'B', '', '9f1a7514', '热血,战斗,奇幻', 'http://i0.hdslb.com/bfs/bangumi/20aa8ff13d6809538c16a6648adeb77d8aa767f8.jpg', '', '', '', '花泽香菜 / 泽城美雪', '吉冈忍', '', '', '《BLACK★ROCK SHOOTER》是由huke绘制插图、音乐创作社团「supercell」所制作，在niconico上受到许多人喜爱的热门音乐作品。它的动画由知名动画监督山本宽、及其带领的新动画', 'OVA', '', 0, '0', '', '', '日本', '日语', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.5, 0, 0, 1739960000, 1739949017, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《BLACK★ROCK SHOOTER》是由huke绘制插图、音乐创作社团「supercell」所制作，在niconico上受到许多人喜爱的热门音乐作品。它的动画由知名动画监督山本宽、及其带领的新动画公司「Ordet」进行制作，于2010年春季推出；而作品的宣传影片则在9月30日于日本发售。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE0871BDD9BE1C5C0D50E978$$$OVA$id_XS0871BDD9BE1C5C0D50E978$$$OVA$id_MOE0871BDD9BE1C5C0D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1047, 1, 0, 0, '黑岩射手：黎明降临', 'ブラック★★ロックシューター DAWN FALL（2022）', 'heiyansheshoulimingjianglin', 1, 'H', '', '17a97cc9', '奇幻,动作,战斗', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867313735.jpg', '', '', '', '石川由依 / 早见沙织 / 潘惠美 / 桐本拓哉 / 朝井彩加 / 久野美咲 / 杉田智和 / 友永朱音 / 堀笼沙耶 / 伊藤明日香', '天冲', '', '', '西暦2062年。労働力の大幅な自動化プロジェクトの失敗後、その中核となる人工知能アルテミスが人類との戦いを選んだ末、荒廃した二十年後の地球。', '', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 4.7, 0, 0, 1739982595, 1739949060, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>西暦2062年。労働力の大幅な自動化プロジェクトの失敗後、その中核となる人工知能アルテミスが人類との戦いを選んだ末、荒廃した二十年後の地球。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0020ED81BE4A0E0050E978#第02集$MOE0020ED81BE4A0E0050E97B#第03集$MOE0020ED81BE4A0E0050E97A#第04集$MOE0020ED81BE4A0E0050E97D#第05集$MOE0020ED81BE4A0E0050E97C#第06集$MOE0020ED81BE4A0E0050E97F#第07集$MOE0020ED81BE4A0E0050E97E#第08集$MOE0020ED81BE4A0E0050E971#第09集$MOE0020ED81BE4A0E0050E970#第10集$MOE0020ED81BE4A0E0050E879#第11集$MOE0020ED81BE4A0E0050E878#第12集$MOE0020ED81BE4A0E0050E87B$$$第01集$id_XS0020ED81BE4A0E0050E978#第02集$id_XS0020ED81BE4A0E0050E97B#第03集$id_XS0020ED81BE4A0E0050E97A#第04集$id_XS0020ED81BE4A0E0050E97D#第05集$id_XS0020ED81BE4A0E0050E97C#第06集$id_XS0020ED81BE4A0E0050E97F#第07集$id_XS0020ED81BE4A0E0050E97E#第08集$id_XS0020ED81BE4A0E0050E971#第09集$id_XS0020ED81BE4A0E0050E970#第10集$id_XS0020ED81BE4A0E0050E879#第11集$id_XS0020ED81BE4A0E0050E878#第12集$id_XS0020ED81BE4A0E0050E87B$$$第01集$id_MOE0020ED81BE4A0E0050E978#第02集$id_MOE0020ED81BE4A0E0050E97B#第03集$id_MOE0020ED81BE4A0E0050E97A#第04集$id_MOE0020ED81BE4A0E0050E97D#第05集$id_MOE0020ED81BE4A0E0050E97C#第06集$id_MOE0020ED81BE4A0E0050E97F#第07集$id_MOE0020ED81BE4A0E0050E97E#第08集$id_MOE0020ED81BE4A0E0050E971#第09集$id_MOE0020ED81BE4A0E0050E970#第10集$id_MOE0020ED81BE4A0E0050E879#第11集$id_MOE0020ED81BE4A0E0050E878#第12集$id_MOE0020ED81BE4A0E0050E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1048, 1, 0, 0, '刻刻', 'Kokkoku（2018）', 'keke', 1, 'K', '', 'bc6e7356', '科幻,漫画改', 'http://i0.hdslb.com/bfs/bangumi/4c8064cf5d498af081829e3d3ff2f589e3b254e3.jpg', '', '', '', '安济知佳 / 濑户麻沙美 / 山路和弘 / 岩田龙门 / 辻谷耕史 / 野岛裕史 / 乡田穗积 / 内田夕夜 / 吉野裕行', '大桥誉志光 / 佐藤阳 / 川越崇弘 / 江岛泰男 / 鸟羽聪 / 丸山裕介 / 汤川敦之 / 石川健朝 / 小野田雄亮 / 菅沼荣治', '', '', '佑河树里与无所事事的父亲和哥哥、养老的祖父、母亲、单亲妈妈的妹妹以及外甥一起生活。某天，她的哥哥与外甥遭人诱拐，为了拯救家人，树里的祖父使用佑河家代代相传的止界术将时间暂停，但没想到进入止界的树里一行', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.4, 0, 0, 1739982666, 1739957979, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>佑河树里与无所事事的父亲和哥哥、养老的祖父、母亲、单亲妈妈的妹妹以及外甥一起生活。某天，她的哥哥与外甥遭人诱拐，为了拯救家人，树里的祖父使用佑河家代代相传的止界术将时间暂停，但没想到进入止界的树里一行人，居然遇到其他能在止界中行动的人。面对神秘的宗教团体真纯实爱会以及保护止者的异形，树里是否能够回到原本的日常生活呢？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5374BADDBE1A580F50E978#第02集$MOE5374BADDBE1A580F50E97B#第03集$MOE5374BADDBE1A580F50E97A#第04集$MOE5374BADDBE1A580F50E97D#第05集$MOE5374BADDBE1A580F50E97C#第06集$MOE5374BADDBE1A580F50E97F#第07集$MOE5374BADDBE1A580F50E97E#第08集$MOE5374BADDBE1A580F50E971#第09集$MOE5374BADDBE1A580F50E970#第10集$MOE5374BADDBE1A580F50E879#第11集$MOE5374BADDBE1A580F50E878#第12集$MOE5374BADDBE1A580F50E87B$$$第01集$id_XS5374BADDBE1A580F50E978#第02集$id_XS5374BADDBE1A580F50E97B#第03集$id_XS5374BADDBE1A580F50E97A#第04集$id_XS5374BADDBE1A580F50E97D#第05集$id_XS5374BADDBE1A580F50E97C#第06集$id_XS5374BADDBE1A580F50E97F#第07集$id_XS5374BADDBE1A580F50E97E#第08集$id_XS5374BADDBE1A580F50E971#第09集$id_XS5374BADDBE1A580F50E970#第10集$id_XS5374BADDBE1A580F50E879#第11集$id_XS5374BADDBE1A580F50E878#第12集$id_XS5374BADDBE1A580F50E87B$$$第01集$id_MOE5374BADDBE1A580F50E978#第02集$id_MOE5374BADDBE1A580F50E97B#第03集$id_MOE5374BADDBE1A580F50E97A#第04集$id_MOE5374BADDBE1A580F50E97D#第05集$id_MOE5374BADDBE1A580F50E97C#第06集$id_MOE5374BADDBE1A580F50E97F#第07集$id_MOE5374BADDBE1A580F50E97E#第08集$id_MOE5374BADDBE1A580F50E971#第09集$id_MOE5374BADDBE1A580F50E970#第10集$id_MOE5374BADDBE1A580F50E879#第11集$id_MOE5374BA