INSERT INTO `mac_vod` VALUES (1049, 1, 0, 0, '学园偶像 阳光!!', 'ラブライブ！サンシャイン!!（2016）', 'xueyuanouxiangyangguang', 1, 'X', '', 'a20077b', '音乐,偶像', 'http://i0.hdslb.com/bfs/bangumi/image/50c1b35ea556a4389370d1d092691cd41fa8db79.jpg', '', '', '', '伊波杏树 / 逢田梨香子 / 诹访奈奈香 / 小宫有纱 / 齐藤朱夏 / 小林爱香 / 高槻加奈子 / 铃木爱奈 / 降幡爱', '酒井和男', '', '', '“LoveLive!Sunshine!!”是日升动画、Lantis和《电击G&#039;s magazine》共同打造的跨媒体偶像企划“LoveLive!学园偶像计划”于2015年公布的新企划。于2016年7月', '全13集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.3, 0, 0, 1740005181, 1739957987, 0, 0, 0, 0, 0.0, '', '1050,1051', '', '', '', '', '', '', '', '<p>“LoveLive!Sunshine!!”是日升动画、Lantis和《电击G&#39;s magazine》共同打造的跨媒体偶像企划“LoveLive!学园偶像计划”于2015年公布的新企划。于2016年7月动画化。《LoveLive!Sunshine!!》讲述了以校园偶像Aqours的身份, 高海千歌为首的九位少女以光芒为目标勇往直前的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5025BC88BE1E0F144DE8#第02集$MOE5025BC88BE1E0F144DEB#第03集$MOE5025BC88BE1E0F144DEA#第04集$MOE5025BC88BE1E0F144DED#第05集$MOE5025BC88BE1E0F144DEC#第06集$MOE5025BC88BE1E0F144DEF#第07集$MOE5025BC88BE1E0F144DEE#第08集$MOE5025BC88BE1E0F144DE1#第09集$MOE5025BC88BE1E0F144DE0#第10集$MOE5025BC88BE1E0F144CE9#第11集$MOE5025BC88BE1E0F144CE8#第12集$MOE5025BC88BE1E0F144CEB#第13集$MOE5025BC88BE1E0F144CEA$$$第01集$id_XS5025BC88BE1E0F144DE8#第02集$id_XS5025BC88BE1E0F144DEB#第03集$id_XS5025BC88BE1E0F144DEA#第04集$id_XS5025BC88BE1E0F144DED#第05集$id_XS5025BC88BE1E0F144DEC#第06集$id_XS5025BC88BE1E0F144DEF#第07集$id_XS5025BC88BE1E0F144DEE#第08集$id_XS5025BC88BE1E0F144DE1#第09集$id_XS5025BC88BE1E0F144DE0#第10集$id_XS5025BC88BE1E0F144CE9#第11集$id_XS5025BC88BE1E0F144CE8#第12集$id_XS5025BC88BE1E0F144CEB#第13集$id_XS5025BC88BE1E0F144CEA$$$第01集$id_MOE5025BC88BE1E0F144DE8#第02集$id_MOE5025BC88BE1E0F144DEB#第03集$id_MOE5025BC88BE1E0F144DEA#第04集$id_MOE5025BC88BE1E0F144DED#第05集$id_MOE5025BC88BE1E0F144DEC#第06集$id_MOE5025BC88BE1E0F144DEF#第07集$id_MOE5025BC88BE1E0F144DEE#第08集$id_MOE5025BC88BE1E0F144DE1#第09集$id_MOE5025BC88BE1E0F144DE0#第10集$id_MOE5025BC88BE1E0F144CE9#第11集$id_MOE5025BC88BE1