INSERT INTO `mac_vod` VALUES (1060, 1, 0, 0, '小魔女学园 TV版', 'リトルウィッチアカデミア（2017）', 'xiaomonvxueyuanTVban', 1, 'X', '', '880a12e1', '原创,冒险,奇幻', 'https://i0.hdslb.com/bfs/bangumi/1aa1cee348544dbd677e05cbeaa85c52c11e1a06.jpg', '', '', '', '潘惠美 / 日高范子 / 日笠阳子 / 折笠富美子 / 村川梨衣 / 上田丽奈 / 村濑迪与 / 志田有彩', '吉成曜 / 宫岛善博 / 金子祥之 / 筱原启辅 / 下平佑一 / 铃木芳成 / 有富兴二 / 粟井重纪', '', '', '自从幼年目睹夏依妮·莎莉温的魔法表演后，梦想成为魔女的亚可，进入了与莎莉温相同的传统魔女育成名门校“新月学园”。\r\n新的城镇，新的学校生活，以及新遇到的朋友。魔女学校中的扫帚飞行课程以及充满魔法气息的不', '全25集 OVA', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.7, 0, 0, 1740072471, 1740007906, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>自从幼年目睹夏依妮·莎莉温的魔法表演后，梦想成为魔女的亚可，进入了与莎莉温相同的传统魔女育成名门校“新月学园”。\r\n新的城镇，新的学校生活，以及新遇到的朋友。魔女学校中的扫帚飞行课程以及充满魔法气息的不可思议的授课等等，在这些只有魔女学校中才有的课程当中，亚可与洛蒂、苏西等人引发了大骚动！\r\n将新月学园卷入其中，亚可成为魔女的第一步就此开始——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE092FBCD9B81B080850E978#第02集$MOE092FBCD9B81B080850E97B#第03集$MOE092FBCD9B81B080850E97A#第04集$MOE092FBCD9B81B080850E97D#第05集$MOE092FBCD9B81B080850E97C#第06集$MOE092FBCD9B81B080850E97F#第07集$MOE092FBCD9B81B080850E97E#第08集$MOE092FBCD9B81B080850E971#第09集$MOE092FBCD9B81B080850E970#第10集$MOE092FBCD9B81B080850E879#第11集$MOE092FBCD9B81B080850E878#第12集$MOE092FBCD9B81B080850E87B#第13集$MOE092FBCD9B81B080850E87A#第14集$MOE092FBCD9B81B080850E87D#第15集$MOE092FBCD9B81B080850E87C#第16集$MOE092FBCD9B81B080850E87F#第17集$MOE092FBCD9B81B080850E87E#第18集$MOE092FBCD9B81B080850E871#第19集$MOE092FBCD9B81B080850E870#第20集$MOE092FBCD9B81B080850EB79#第21集$MOE092FBCD9B81B080850EB78#第22集$MOE092FBCD9B81B080850EB7B#第23集$MOE092FBCD9B81B080850EB7A#第24集$MOE092FBCD9B81B080850EB7D#第25集$MOE092FBCD9B81B080850EB7C#OVA$MOE092FBCD9B81B080850EB7F$$$第01集$id_XS092FBCD9B81B080850E978#第02集$id_XS092FBCD9B81B080850E97B#第03集$id_XS092FBCD9B81B080850E97A#第04集$id_XS092FBCD9B81B080850E97D#第05集$id_XS092FBCD9B81B080850E97C#第06集$id_XS092FBCD9B81B080850E97F#第07集$id_XS092FBCD9B81B080850E97E#第08集$id_XS092FBCD9B81B080850E971#第09集$id_XS092FBCD9B81B080