INSERT INTO `mac_vod` VALUES (1063, 1, 0, 0, '王室教师海涅', '王室教師ハイネ（2017）', 'wangshijiaoshihainie', 1, 'W', '', 'bda4fd97', '搞笑,漫画改', 'http://i0.hdslb.com/bfs/bangumi/6fbb692726fb77614ef2abf44f10a983556d913f.jpg', '', '', '', '植田圭辅 / 安里勇哉 / 安达勇人 / 广濑大介 / 苍井翔太 / 浪川大辅 / 立花慎之介 / 松井明知 / 森川智之 / 杉山佳寿子', '菊池胜也 / 柳濑雄之 / 长山延好 / 牧野友映 / 永居慎平', '', '', '“王室教师”是负责教育王子的专属家庭教师，是只有从全国各地挑选出的顶级教师才能胜任的职位。\r\n海涅·维特根斯坦因被格兰茨莱希王国聘为王室教师。\r\n他被命令教育下一任国王候补，但在王宫中，出现在海涅面前的是', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.4, 0, 0, 1740187570, 1740008236, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“王室教师”是负责教育王子的专属家庭教师，是只有从全国各地挑选出的顶级教师才能胜任的职位。\r\n海涅·维特根斯坦因被格兰茨莱希王国聘为王室教师。\r\n他被命令教育下一任国王候补，但在王宫中，出现在海涅面前的是4位超有个性的王子！而且还是四兄弟！面对这四位让前任王室教师们全部无法应付而逃走的王子，海涅的教育方法是…？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5373ED8CEF4D540E50E978#第02集$MOE5373ED8CEF4D540E50E97B#第03集$MOE5373ED8CEF4D540E50E97A#第04集$MOE5373ED8CEF4D540E50E97D#第05集$MOE5373ED8CEF4D540E50E97C#第06集$MOE5373ED8CEF4D540E50E97F#第07集$MOE5373ED8CEF4D540E50E97E#第08集$MOE5373ED8CEF4D540E50E971#第09集$MOE5373ED8CEF4D540E50E970#第10集$MOE5373ED8CEF4D540E50E879#第11集$MOE5373ED8CEF4D540E50E878#第12集$MOE5373ED8CEF4D540E50E87B$$$第01集$id_XS5373ED8CEF4D540E50E978#第02集$id_XS5373ED8CEF4D540E50E97B#第03集$id_XS5373ED8CEF4D540E50E97A#第04集$id_XS5373ED8CEF4D540E50E97D#第05集$id_XS5373ED8CEF4D540E50E97C#第06集$id_XS5373ED8CEF4D540E50E97F#第07集$id_XS5373ED8CEF4D540E50E97E#第08集$id_XS5373ED8CEF4D540E50E971#第09集$id_XS5373ED8CEF4D540E50E970#第10集$id_XS5373ED8CEF4D540E50E879#第11集$id_XS5373ED8CEF4D540E50E878#第12集$id_XS5373ED8CEF4D540E50E87B$$$第01集$id_MOE5373ED8CEF4D540E50E978#第02集$id_MOE5373ED8CEF4D540E50E97B#第03集$id_MOE5373ED8CEF4D540E50E97A#第04集$id_MOE5373ED8CEF4D540E50E97D#第05集$id_MOE5373ED8CEF4D540E50E97C#第06集$id_MOE5373ED8CEF4D540E50E97F#第07集$id_MOE5373ED8CEF4D540E50E97E#第08集$id_MOE5373ED8CEF4D540E50E971#第09集$id_MOE5373ED8CEF4D540E50E970#第10集$id_MOE5373ED8CEF4D540E50E879#第11集$id_MOE5373ED