INSERT INTO `mac_vod` VALUES (1064, 2, 0, 0, '小魔女学园：魔法游行', 'リトルウィッチアカデミア 魔法仕掛けのパレード（2015）', 'xiaomonvxueyuanmofayouxing', 1, 'X', '', '4adb655d', '奇幻,冒险', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2262669737.jpg', '', '', '', '潘惠美 / 折笠富美子 / 村濑迪与 / 日笠阳子 / 志田有彩 / 村川梨衣 / 上田丽奈 / 日高范子 / 青山桐子 / 藤村步 / 広田みのる / 水野麻里绘 / 乃村健次 / 大竹宏', '吉成曜', '', '', '「キルラキル」「ニンジャスレイヤー フロムアニメイシヨン」といった話題作を手がける気鋭のアニメーションスタジオ・TRIGGERによるオリジナル劇場用作品。2013年、文化庁の若手アニメーター育成事業「', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.9, 0, 0, 1740105462, 1740072083, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「キルラキル」「ニンジャスレイヤー フロムアニメイシヨン」といった話題作を手がける気鋭のアニメーションスタジオ・TRIGGERによるオリジナル劇場用作品。2013年、文化庁の若手アニメーター育成事業「アニメミライ」で発表された短編「リトルウィッチアカデミア」の続編となり、製作資金を米クラウドファンディングサイト「Kickstarter」を通じて募り、世界各国のファンから約7400万円が寄せられて実現した。幼い頃に見た魔女に憧れ、ヨーロッパの魔女育成名門校「ルーナノヴァ魔法学校」に入学したアッコだが、いまだにホウキにも乗れないどころか、騒動を起こしてばかり。罰として、友人のロッテ、スーシィと一緒に、魔女の歴史を再現したパレードに参加させられることに。パレードを成功させなければ落第は決定だが、どうせやるならハッピーなものにしたいと、アッコは街全体を巻き込んだパレードを計画するが……。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0576E8DABF1C585D50E978$$$正片$id_MOE0576E8DABF1C585D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1065, 2, 0, 0, '剧场版 王室教师海涅', '劇場版 王室教師ハイネ（2019）', 'juchangbanwangshijiaoshihainie', 1, 'J', '', '4f42bfee', '搞笑,漫画改', 'http://i0.hdslb.com/bfs/bangumi/0fe0bb2c64b326d5e3d5c08da55c53801477c85d.png', '', '', '', '植田圭辅 / 安里勇哉 / 安达勇人 / 广濑大介 / 苍井翔太 / 桥本祥平 / 阪本奖悟 / 森川智之 / 小野大辅 / 松井明知 / 杉山佳寿子 / 立花慎之介 / 浪川大辅 / 江口拓也 / 真田侑 / 乡田穗积 / 小西克幸 / 松井惠理子 / 佐藤花 / 长谷川芳明', '菊池胜也', '', '', '以成为下一任国王为目标，古兰兹莱希国的四位王子在王室教师海涅·维特根斯坦因的指导下，虽然有时候也会烦恼迷惘，但也跨越了重重难关，渐渐地成熟茁壮。但来自罗马诺国的双胞胎王子，却突然在他们面前现身了！\r\n虽', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.6, 0, 0, 1740187663, 1740117040, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>以成为下一任国王为目标，古兰兹莱希国的四位王子在王室教师海涅·维特根斯坦因的指导下，虽然有时候也会烦恼迷惘，但也跨越了重重难关，渐渐地成熟茁壮。但来自罗马诺国的双胞胎王子，却突然在他们面前现身了！\r\n虽然两位王子看似可爱，个性却跟外表完全相反，其实根本超级 S（虐待狂）的啊…！\r\n面对这前所未有的危机，海涅居然与四位王子一起提出了「教育意义的指导」！？</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0571B88AEB4F085C50E978$$$正片$id_MOE0571B88AEB4F085C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1066, 1, 0, 0, 'UQ HOLDER！悠久持有者！', 'UQ HOLDER! ～魔法先生ネギま！2～（2017）', 'UQHOLDERyoujiuchiyouzhe', 1, 'U', '', 'a151c6c', '热血,战斗,漫画改,冒险', 'http://i0.hdslb.com/bfs/bangumi/b58387eafd223d1a24ef97cf6a38e7df7fb8bf61.jpg', '', '', '', '高仓有加 / 松冈由贵 / 广濑有纪 / 佐藤利奈 / 茅野爱衣 / 小仓唯 / 白鸟由里 / 桑谷夏子 / 神田朱未 / 渡边明乃 / 堀江由衣 / 佐久间未帆 / 能登麻美子 / 皆川纯子 / 石田彰', '铃木洋平', '', '', '在平稳而乏味的乡村生活的少年·近卫刀太，有着前往都市一展宏图的梦想。为此，他每天都向养育了自己的亲人，同时也是优秀的魔法使·雪姬发起挑战。但，一边战斗一边和睦度日的两人面前出现的赏金猎人，宣告了平稳乡', '全12集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 6.9, 0, 0, 1740200938, 1740117096, 0, 0, 0, 0, 0.0, '', '1067', '', '', '', '', '', '', '', '<p>在平稳而乏味的乡村生活的少年·近卫刀太，有着前往都市一展宏图的梦想。为此，他每天都向养育了自己的亲人，同时也是优秀的魔法使·雪姬发起挑战。但，一边战斗一边和睦度日的两人面前出现的赏金猎人，宣告了平稳乡村生活的终结。\r\n这是一个，成为不正经者的人们的物语。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5026B989EA1F0E144DE8#第02集$MOE5026B989EA1F0E144DEB#第03集$MOE5026B989EA1F0E144DEA#第04集$MOE5026B989EA1F0E144DED#第05集$MOE5026B989EA1F0E144DEC#第06集$MOE5026B989EA1F0E144DEF#第07集$MOE5026B989EA1F0E144DEE#第08集$MOE5026B989EA1F0E144DE1#第09集$MOE5026B989EA1F0E144DE0#第10集$MOE5026B989EA1F0E144CE9#第11集$MOE5026B989EA1F0E144CE8#第12集$MOE5026B989EA1F0E144CEB$$$第01集$id_XS5026B989EA1F0E144DE8#第02集$id_XS5026B989EA1F0E144DEB#第03集$id_XS5026B989EA1F0E144DEA#第04集$id_XS5026B989EA1F0E144DED#第05集$id_XS5026B989EA1F0E144DEC#第06集$id_XS5026B989EA1F0E144DEF#第07集$id_XS5026B989EA1F0E144DEE#第08集$id_XS5026B989EA1F0E144DE1#第09集$id_XS5026B989EA1F0E144DE0#第10集$id_XS5026B989EA1F0E144CE9#第11集$id_XS5026B989EA1F0E144CE8#第12集$id_XS5026B989EA1F0E144CEB$$$第01集$id_MOE5026B989EA1F0E144DE8#第02集$id_MOE5026B989EA1F0E144DEB#第03集$id_MOE5026B989EA1F0E144DEA#第04集$id_MOE5026B989EA1F0E144DED#第05集$id_MOE5026B989EA1F0E144DEC#第06集$id_MOE5026B989EA1F0E144DEF#第07集$id_MOE5026B989EA1F0E144DEE#第08集$id_MOE5026B989EA1F0E144DE1#第09集$id_MOE5026B989EA1F0E144DE0#第10集$id_MOE5026B989EA1F0E144CE9#第11集$id_MOE5026B989EA1F0E144CE8#第12集$id_MOE5026B989EA1F0E144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1067, 1, 0, 0, 'UQ HOLDER！悠久持有者 OAD', 'UQ holder OAD amor primus〜初恋〜（2017）', 'UQHOLDERyoujiuchiyouzheOAD', 1, 'U', '', 'b5ebb6fc', '热血,战斗,漫画改,奇幻', 'http://i0.hdslb.com/bfs/bangumi/08bb7042d638e1ee6c63990e4099e3b0ce17779f.jpg', '', '', '', '高仓有加 / 松岡由貴', '铃木洋平 Suzuki Youhei', '', '', '本片为单行本第14卷/16卷/17卷同捆OAD。\r\n在平稳而乏味的乡村生活的少年·近卫刀太，有着前往都市一展宏图的梦想。为此，他每天都向养育了自己的亲人，同时也是优秀的魔法使·雪姬发起挑战。但，一边战斗', 'OAD', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.0, 0, 0, 1740201263, 1740117158, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本片为单行本第14卷/16卷/17卷同捆OAD。\r\n在平稳而乏味的乡村生活的少年·近卫刀太，有着前往都市一展宏图的梦想。为此，他每天都向养育了自己的亲人，同时也是优秀的魔法使·雪姬发起挑战。但，一边战斗一边和睦度日的两人面前出现的赏金猎人，宣告了平稳乡村生活的终结。这是一个，成为不正经者的人们的物语。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5322E9DAEB1F0B5A50E978#第02集$MOE5322E9DAEB1F0B5A50E97B#第03集$MOE5322E9DAEB1F0B5A50E97A$$$第01集$id_XS5322E9DAEB1F0B5A50E978#第02集$id_XS5322E9DAEB1F0B5A50E97B#第03集$id_XS5322E9DAEB1F0B5A50E97A$$$第01集$id_MOE5322E9DAEB1F0B5A50E978#第02集$id_MOE5322E9DAEB1F0B5A50E97B#第03集$id_MOE5322E9DAEB1F0B5A50E97A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1068, 1, 0, 0, '加速世界', 'アクセル・ワールド（2012）', 'jiasushijie', 1, 'J', '', '3a07b2aa', '校园,科幻,战斗,小说改', 'http://i0.hdslb.com/bfs/bangumi/image/1ec94c38346b1d36475e2f34e5fe17a0e12ce912.jpg', '', '', '', '梶裕贵 / 三泽纱千香 / 丰崎爱生 / 浅沼晋太郎 / 户松遥 / 铃村健一', '小原正和 / 博史池畠 / 桥本裕之 / 下司泰弘 / 森邦宏 / 所智一 / 三宅和男 / 间岛崇宽 / 佐藤真人 / 飞田刚', '', '', '故事发生在人人都使用名为“Neural Linker（神经连结装置）”的终端设备连线，生活的大半时间都建构在网络世界的不远未来。因为身材肥胖而受到欺凌的学生春雪，过着一边诅咒现实，一边躲在校内网络一角', '全24集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 8.8, 0, 0, 1740132430, 1740117261, 0, 0, 0, 0, 0.0, '', '1069,1070,1072', '', '', '', '', '', '', '', '<p>故事发生在人人都使用名为“Neural Linker（神经连结装置）”的终端设备连线，生活的大半时间都建构在网络世界的不远未来。因为身材肥胖而受到欺凌的学生春雪，过着一边诅咒现实，一边躲在校内网络一角提升自己壁球游戏的分数最高纪录的日子。某天，接受美丽的副学生会长黑雪公主邀请的春雪，使用有线连接通信下载到名为“Brain Buster”的软件，成为“Buster Linker（超频连线者）”的春雪，操纵着自己的角色，投入战斗之中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0276BC8FEB1B0C5850E978#第02集$MOE0276BC8FEB1B0C5850E97B#第03集$MOE0276BC8FEB1B0C5850E97A#第04集$MOE0276BC8FEB1B0C5850E97D#第05集$MOE0276BC8FEB1B0C5850E97C#第06集$MOE0276BC8FEB1B0C5850E97F#第07集$MOE0276BC8FEB1B0C5850E97E#第08集$MOE0276BC8FEB1B0C5850E971#第09集$MOE0276BC8FEB1B0C5850E970#第10集$MOE0276BC8FEB1B0C5850E879#第11集$MOE0276BC8FEB1B0C5850E878#第12集$MOE0276BC8FEB1B0C5850E87B#第13集$MOE0276BC8FEB1B0C5850E87A#第14集$MOE0276BC8FEB1B0C5850E87D#第15集$MOE0276BC8FEB1B0C5850E87C#第16集$MOE0276BC8FEB1B0C5850E87F#第17集$MOE0276BC8FEB1B0C5850E87E#第18集$MOE0276BC8FEB1B0C5850E871#第19集$MOE0276BC8FEB1B0C5850E870#第20集$MOE0276BC8FEB1B0C5850EB79#第21集$MOE0276BC8FEB1B0C5850EB78#第22集$MOE0276BC8FEB1B0C5850EB7B#第23集$MOE0276BC8FEB1B0C5850EB7A#第24集$MOE0276BC8FEB1B0C5850EB7D$$$第01集$id_XS0276BC8FEB1B0C5850E978#第02集$id_XS0276BC8FEB1B0C5850E97B#第03集$id_XS0276BC8FEB1B0C5850E97A#第04集$id_XS0276BC8FEB1B0C5850E97D#第05集$id_XS0276BC8FEB1B0C5850E97C#第06集$id_XS0276BC8FEB1B0C5850E97F#第07集$id_XS0276BC8FEB1B0C5850E97E#第08集$id_XS0276BC8FEB1B0C5850E971#第09集$id_XS0276BC8FEB1B0C5850E970#第10集$id_XS0276BC8FEB1B0C5850E879#第11集$id_XS0276BC8FEB1B0C5850E878#第12集$id_XS0276BC8FEB1B0C5850E87B#第13集$id_XS0276BC8FEB1B0C5850E87A#第14集$id_XS0276BC8FEB1B0C5850E87D#第15集$id_XS0276BC8FEB1B0C5850E87C#第16集$id_XS0276BC8FEB1B0C5850E87F#第17集$id_XS0276BC8FEB1B0C5850E87E#第18集$id_XS0276BC8FEB1B0C5850E871#第19集$id_XS0276BC8FEB1B0C5850E870#第20集$id_XS0276BC8FEB1B0C5850EB79#第21集$id_XS0276BC8FEB1B0C5850EB78#第22集$id_XS0276BC8FEB1B0C5850EB7B#第23集$id_XS0276BC8FEB1B0C5850EB7A#第24集$id_XS0276BC8FEB1B0C5850EB7D$$$第01集$id_MOE0276BC8FEB1B0C5850E978#第02集$id_MOE0276BC8FEB1B0C5850E97B#第03集$id_MOE0276BC8FEB1B0C5850E97A#第04集$id_MOE0276BC8FEB1B0C5850E97D#第05集$id_MOE0276BC8FEB1B0C5850E97C#第06集$id_MOE0276BC8FEB1B0C5850E97F#第07集$id_MOE0276BC8FEB1B0C5850E97E#第08集$id_MOE0276BC8FEB1B0C5850E971#第09集$id_MOE0276BC8FEB1B0C5850E970#第10集$id_MOE0276BC8FEB1B0C5850E879#第11集$id_MOE0276BC8FEB1B0C5850E878#第12集$id_MOE0276BC8FEB1B0C5850E87B#第13集$id_MOE0276BC8FEB1B0C5850E87A#第14集$id_MOE0276BC8FEB1B0C5850E87D#第15集$id_MOE0276BC8FEB1B0C5850E87C#第16集$id_MOE0276BC8FEB1B0C5850E87F#第17集$id_MOE0276BC8FEB1B0C5850E87E#第18集$id_MOE0276BC8FEB1B0C5850E871#第19集$id_MOE0276BC8FEB1B0C5850E870#第20集$id_MOE0276BC8FEB1B0C5850EB79#第21集$id_MOE0276BC8FEB1B0C5850EB78#第22集$id_MOE0276BC8FEB1B0C5850EB7B#第23集$id_MOE0276BC8FEB1B0C5850EB7A#第24集$id_MOE0276BC8FEB1B0C5850EB7D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1069, 1, 0, 0, '加速世界 OVA1 银翼的觉醒', 'アクセル・ワールド OVA #EX01 Reverberation；残響（2012）', 'jiasushijieOVA1yinyidejuexing', 1, 'J', '', 'd55221c5', '热血,机战,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/8f8936e0a6ac5f18116fceee310d668559d9b7e3.jpg', '', '', '', '梶裕贵 / 三泽纱千香 / 丰崎爱生 / 浅沼晋太郎 / 户松遥', '小原正和', '', '', 'アバター強奪事件—\r\n放課後に生徒が学内ローカルネットに取り残され、アバターの衣装やアイテムを剥ぎ取られるという事件が発生する。\r\n\r\n同時に、ローカルネット荒しに気をつけろとニコからも伝言が入る。\r\n新生《', 'OVA', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.8, 0, 0, 1740180655, 1740130353, 0, 0, 0, 0, 0.0, '', '1070,1072', '', '', '', '', '', '', '', '<p>アバター強奪事件—\r\n放課後に生徒が学内ローカルネットに取り残され、アバターの衣装やアイテムを剥ぎ取られるという事件が発生する。\r\n\r\n同時に、ローカルネット荒しに気をつけろとニコからも伝言が入る。\r\n新生《ネガ・ネビュラス》がアバター強奪事件の真相に迫る——\r\n\r\nそこで現れる最後の《アサルト・リンカー》と名乗るダシュカ、\r\n《ブレイン・バースト》とは違う加速世界《アクセル・アサルト》での戦いの果てに待つものとは——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE5522B98ABB180E0C50E978$$$OVA$id_XS5522B98ABB180E0C50E978$$$OVA$id_MOE5522B98ABB180E0C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1070, 1, 0, 0, '加速世界 OVA2 加速的顶点', 'アクセル・ワールド OVA #EX02 Vacation；温泉（2013）', 'jiasushijieOVA2jiasudedingdian', 1, 'J', '', 'c7e86225', '热血,机战,战斗', 'http://i0.hdslb.com/bfs/bangumi/441a9c0584d137921959e95394f79e957d570310.jpg', '', '', '', '梶裕贵 / 三泽纱千香 / 丰崎爱生 / 浅沼晋太郎 / 户松遥', '小原正和', '', '', '体质复查再不达标就要强制隔离医疗，无法继续参加领土战；男猪引起的减肥骚动？师傅的温泉治疗？', 'OVA', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 8.8, 0, 0, 1740180748, 1740130361, 0, 0, 0, 0, 0.0, '', '1072', '', '', '', '', '', '', '', '<p>体质复查再不达标就要强制隔离医疗，无法继续参加领土战；男猪引起的减肥骚动？师傅的温泉治疗？</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE5220E980BF1B5F0C50E978$$$OVA$id_XS5220E980BF1B5F0C50E978$$$OVA$id_MOE5220E980BF1B5F0C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1071, 2, 0, 0, '加速世界 Infinite Burst', 'アクセル・ワールド インフィニット・バースト（2016）', 'jiasushijieInfiniteBurst', 1, 'J', '', 'f0fa040d', '小说改,恋爱,战斗,励志', 'http://i0.hdslb.com/bfs/bangumi/b874a41f24f7d89bc9e7b80aeaec73b0d7f640c5.jpg', '', '', '', '三泽纱千香 / 梶裕贵 / 丰崎爱生 / 浅沼晋太郎 / 远藤绫 / 植田佳奈 / 原由实 / 日高里菜 / 川澄绫子 / 铃村健一 / 赤崎千夏 / 悠木碧 / 黑田崇矢 / 柳泽健次 / 野坂尚也 / 大龟明日香 / 小堀幸 / 樱井孝宏 / 水桥香织 / 石田彰 / 古贺葵 / 野上尤加奈', '小原正和', '', '', '故事发生在人人都使用名为“Neural Linker（神经连结装置）”的终端设备连线，生活的大半时间都建构在网络世界的不远未来。因为身材肥胖而受到欺凌的学生有田春雪，过着一边诅咒现实，一边躲在校内网络', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.8, 0, 0, 1740195917, 1740130368, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事发生在人人都使用名为“Neural Linker（神经连结装置）”的终端设备连线，生活的大半时间都建构在网络世界的不远未来。因为身材肥胖而受到欺凌的学生有田春雪，过着一边诅咒现实，一边躲在校内网络一角提升自己壁球游戏的分数最高纪录的日子。某天，美丽的副学生会长黑雪公主突然出现在他的面前，留下了谜一般的话语：“少年…想不想“加速”到更快的境界？”</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5727EAD9B91D5D5D50E978$$$正片$id_MOE5727EAD9B91D5D5D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1072, 1, 0, 0, '小加速世界', 'あくちぇる・わーるど。（2012）', 'xiaojiasushijie', 1, 'X', '', '6802785', '萌系,搞笑', 'http://i0.hdslb.com/bfs/bangumi/3e4914ed0078fc75bee8826acba5408ba2d44ec8.jpg', '', '', '', '梶裕贵 / 三泽纱千香 / 丰崎爱生 / 浅沼晋太郎', '山川吉树', '', '', '故事的背景设定于近未来，在这个时代中，透过名为“神经连结装置（Neural Linker）”的终端连线设备，人们已经可以使虚拟构建与完全数位量子化的世界与现实同步，上班族与学生们可以直接在眼中显示各类', '全8集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 8.6, 0, 0, 1740180839, 1740130375, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>故事的背景设定于近未来，在这个时代中，透过名为“神经连结装置（Neural Linker）”的终端连线设备，人们已经可以使虚拟构建与完全数位量子化的世界与现实同步，上班族与学生们可以直接在眼中显示各类介面，并以手指凭空触空操作、收发资讯，甚至透过电缆直接与他人连线共享思绪。让生活的大小诸事都已完全无法与网路脱节。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE072FBC8ABE1158144DE8#第02集$MOE072FBC8ABE1158144DEB#第03集$MOE072FBC8ABE1158144DEA#第04集$MOE072FBC8ABE1158144DED#第05集$MOE072FBC8ABE1158144DEC#第06集$MOE072FBC8ABE1158144DEF#第07集$MOE072FBC8ABE1158144DEE#第08集$MOE072FBC8ABE1158144DE1$$$第01集$id_XS072FBC8ABE1158144DE8#第02集$id_XS072FBC8ABE1158144DEB#第03集$id_XS072FBC8ABE1158144DEA#第04集$id_XS072FBC8ABE1158144DED#第05集$id_XS072FBC8ABE1158144DEC#第06集$id_XS072FBC8ABE1158144DEF#第07集$id_XS072FBC8ABE1158144DEE#第08集$id_XS072FBC8ABE1158144DE1$$$第01集$id_MOE072FBC8ABE1158144DE8#第02集$id_MOE072FBC8ABE1158144DEB#第03集$id_MOE072FBC8ABE1158144DEA#第04集$id_MOE072FBC8ABE1158144DED#第05集$id_MOE072FBC8ABE1158144DEC#第06集$id_MOE072FBC8ABE1158144DEF#第07集$id_MOE072FBC8ABE1158144DEE#第08集$id_MOE072FBC8ABE1158144DE1', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1073, 1, 0, 0, '黑白来看守所', 'ナンバカ（2016）', 'heibailaikanshousuo', 1, 'H', '', '9538e04d', '漫画改,搞笑', 'http://i0.hdslb.com/bfs/bangumi/2ed6be9050dfa4afe6e2651741d81843a0e81c67.jpg', '', '', '', '上村祐翔 / 柿原彻也 / 汐崎艾伦 / 小林大纪 / 关智一 / 明坂聪美 / 津田健次郎 / 山本匠马 / 保志总一朗 / 武内骏辅 / 奥山敬人', '高松信司', '', '', '南波刑务所——位于海上孤岛的难攻不落巨大刑务所。\r\n没有任何人能从被强悍的看守以及世界最高水准的安保所守卫的这所刑务所当中逃脱……应该是这样！？\r\n带着神秘枷锁的天才越狱囚犯·Jugo（囚犯编号15号）', '全13集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 9.2, 0, 0, 1740149263, 1740130423, 0, 0, 0, 0, 0.0, '', '1074', '', '', '', '', '', '', '', '<p>南波刑务所——位于海上孤岛的难攻不落巨大刑务所。\r\n没有任何人能从被强悍的看守以及世界最高水准的安保所守卫的这所刑务所当中逃脱……应该是这样！？\r\n带着神秘枷锁的天才越狱囚犯·Jugo（囚犯编号15号）\r\n喜欢女人的赌徒·Uno（囚犯编号11号）\r\n爱打架的美食家·Rock（囚犯编号69号）\r\n身患宿疾的阿宅·Nico（囚犯编号25号）\r\n集中在13舍13房的，有些奇怪的4名囚犯。\r\n为了阻止他们越狱，每天急速冲刺的最强看守双六一！！\r\n个性丰富的囚犯、看守们的最高纯粹笨蛋物语，在此刑务所开幕！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0822BF80EC19595D50E978#第02集$MOE0822BF80EC19595D50E97B#第03集$MOE0822BF80EC19595D50E97A#第04集$MOE0822BF80EC19595D50E97D#第05集$MOE0822BF80EC19595D50E97C#第06集$MOE0822BF80EC19595D50E97F#第07集$MOE0822BF80EC19595D50E97E#第08集$MOE0822BF80EC19595D50E971#第09集$MOE0822BF80EC19595D50E970#第10集$MOE0822BF80EC19595D50E879#第11集$MOE0822BF80EC19595D50E878#第12集$MOE0822BF80EC19595D50E87B#第13集$MOE0822BF80EC19595D50E87A$$$第01集$id_XS0822BF80EC19595D50E978#第02集$id_XS0822BF80EC19595D50E97B#第03集$id_XS0822BF80EC19595D50E97A#第04集$id_XS0822BF80EC19595D50E97D#第05集$id_XS0822BF80EC19595D50E97C#第06集$id_XS0822BF80EC19595D50E97F#第07集$id_XS0822BF80EC19595D50E97E#第08集$id_XS0822BF80EC19595D50E971#第09集$id_XS0822BF80EC19595D50E970#第10集$id_XS0822BF80EC19595D50E879#第11集$id_XS0822BF80EC19595D50E878#第12集$id_XS0822BF80EC19595D50E87B#第13集$id_XS0822BF80EC19595D50E87A$$$第01集$id_MOE0822BF80EC19595D50E978#第02集$id_MOE0822BF80EC19595D50E97B#第03集$id_MOE0822BF80EC19595D50E97A#第04集$id_MOE0822BF80EC19595D50E97D#第05集$id_MOE0822BF80EC19595D50E97C#第06集$id_MOE0822BF80EC19595D50E97F#第07集$id_MOE0822BF80EC19595D50E97E#第08集$id_MOE0822BF80EC19595D50E971#第09集$id_MOE0822BF80EC19595D50E970#第10集$id_MOE0822BF80EC19595D50E879#第11集$id_MOE0822BF80EC19595D50E878#第12集$id_MOE0822BF80EC19595D50E87B#第13集$id_MOE0822BF80EC19595D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1074, 1, 0, 0, '黑白来看守所 第二季', 'ナンバカ 第2期（2017）', 'heibailaikanshousuodierji', 1, 'H', '', 'beb1b2ea', '搞笑,漫画改', 'http://i0.hdslb.com/bfs/bangumi/0ab129325044ff4acbf808a3e38b71a1e0ea5b57.jpg', '', '', '', '上村祐翔 / 柿原彻也 / 汐崎艾伦 / 小林大纪 / 关智一 / 明坂聪美 / 津田健次郎', '高松信司', '', '', '南波刑务所——位于海上孤岛的难攻不落巨大刑务所。没有任何人能从被强悍的看守以及世界最高水准的安保所守卫的这所刑务所当中逃脱……应该是这样！？\r\n带着神秘枷锁的天才越狱囚犯·Jugo（囚犯编号15号）、喜', '全13集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.2, 0, 0, 1740179319, 1740130505, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>南波刑务所——位于海上孤岛的难攻不落巨大刑务所。没有任何人能从被强悍的看守以及世界最高水准的安保所守卫的这所刑务所当中逃脱……应该是这样！？\r\n带着神秘枷锁的天才越狱囚犯·Jugo（囚犯编号15号）、喜欢女人的赌徒·Uno（囚犯编号11号）、爱打架的美食家·Rock（囚犯编号69号）、身患宿疾的阿宅·Nico（囚犯编号25号）。\r\n集中在13舍13房的，有些奇怪的4名囚犯。为了阻止他们越狱，每天急速冲刺的最强看守双六一！！\r\n个性丰富的囚犯、看守们的最高纯粹笨蛋物语，在此刑务所开幕！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5372EE89EB1B085850E978#第02集$MOE5372EE89EB1B085850E97B#第03集$MOE5372EE89EB1B085850E97A#第04集$MOE5372EE89EB1B085850E97D#第05集$MOE5372EE89EB1B085850E97C#第06集$MOE5372EE89EB1B085850E97F#第07集$MOE5372EE89EB1B085850E97E#第08集$MOE5372EE89EB1B085850E971#第09集$MOE5372EE89EB1B085850E970#第10集$MOE5372EE89EB1B085850E879#第11集$MOE5372EE89EB1B085850E878#第12集$MOE5372EE89EB1B085850E87B#第13集$MOE5372EE89EB1B085850E87A$$$第01集$id_XS5372EE89EB1B085850E978#第02集$id_XS5372EE89EB1B085850E97B#第03集$id_XS5372EE89EB1B085850E97A#第04集$id_XS5372EE89EB1B085850E97D#第05集$id_XS5372EE89EB1B085850E97C#第06集$id_XS5372EE89EB1B085850E97F#第07集$id_XS5372EE89EB1B085850E97E#第08集$id_XS5372EE89EB1B085850E971#第09集$id_XS5372EE89EB1B085850E970#第10集$id_XS5372EE89EB1B085850E879#第11集$id_XS5372EE89EB1B085850E878#第12集$id_XS5372EE89EB1B085850E87B#第13集$id_XS5372EE89EB1B085850E87A$$$第01集$id_MOE5372EE89EB1B085850E978#第02集$id_MOE5372EE89EB1B085850E97B#第03集$id_MOE5372EE89EB1B085850E97A#第04集$id_MOE5372EE89EB1B085850E97D#第05集$id_MOE5372EE89EB1B085850E97C#第06集$id_MOE5372EE89EB1B085850E97F#第07集$id_MOE5372EE89EB1B085850E97E#第08集$id_