INSERT INTO `mac_vod` VALUES (1075, 1, 0, 0, '同居人是猫', '同居人はひざ、時々、頭のうえ。（2019）', 'tongjurenshimao', 1, 'T', '', '93f6acd1', '治愈,漫画改,萌系', 'http://i0.hdslb.com/bfs/bangumi/07586cac5807cef3a6af19dff6a449a9af9d6a1c.png', '', '', '', '小野贤章 / 山崎遥 / 下野纮 / 堀江瞬 / 安济知佳 / 中岛良树 / 村濑步 / 津田健次郎 / 杉田智和 / 东城日沙子 / 丰口惠美 / 小野大辅 / 南条爱乃', '铃木薰', '', '', '不擅长跟人接触，怕生的小说家·朏素晴与被人抛弃，过着残酷的流浪生活的猫。由于偶然的契机下一个人和一只猫开始了同居生活……？\r\n以人的视角和猫的视角来描绘每天的生活，各自的思绪互相交织在一起。\r\n故事以“温', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.7, 0, 0, 1740139058, 1740130514, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>不擅长跟人接触，怕生的小说家·朏素晴与被人抛弃，过着残酷的流浪生活的猫。由于偶然的契机下一个人和一只猫开始了同居生活……？\r\n以人的视角和猫的视角来描绘每天的生活，各自的思绪互相交织在一起。\r\n故事以“温暖人心”为话题。\r\n随着琐碎时光的积累，我们成为了“家人”——\r\n两者找到了幸福的同居生活。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0824EA8EE84A090850E978#第02集$MOE0824EA8EE84A090850E97B#第03集$MOE0824EA8EE84A090850E97A#第04集$MOE0824EA8EE84A090850E97D#第05集$MOE0824EA8EE84A090850E97C#第06集$MOE0824EA8EE84A090850E97F#第07集$MOE0824EA8EE84A090850E97E#第08集$MOE0824EA8EE84A090850E971#第09集$MOE0824EA8EE84A090850E970#第10集$MOE0824EA8EE84A090850E879#第11集$MOE0824EA8EE84A090850E878#第12集$MOE0824EA8EE84A090850E87B$$$第01集$id_XS0824EA8EE84A090850E978#第02集$id_XS0824EA8EE84A090850E97B#第03集$id_XS0824EA8EE84A090850E97A#第04集$id_XS0824EA8EE84A090850E97D#第05集$id_XS0824EA8EE84A090850E97C#第06集$id_XS0824EA8EE84A090850E97F#第07集$id_XS0824EA8EE84A090850E97E#第08集$id_XS0824EA8EE84A090850E971#第09集$id_XS0824EA8EE84A090850E970#第10集$id_XS0824EA8EE84A090850E879#第11集$id_XS0824EA8EE84A090850E878#第12集$id_XS0824EA8EE84A090850E87B$$$第01集$id_MOE0824EA8EE84A090850E978#第02集$id_MOE0824EA8EE84A090850E97B#第03集$id_MOE0824EA8EE84A090850E97A#第04集$id_MOE0824EA8EE84A090850E97D#第05集$id_MOE0824EA8EE84A090850E97C#第06集$id_MOE0824EA8EE84A090850E97F#第07集$id_MOE0824EA8EE84A090850E97E#第08集$id_MOE0824EA8EE84A090850E971#第09集$id_MOE0824EA8EE84A090850E970#第10集$id_MOE0824EA8EE84A090850E879#第11集$id_MOE0824EA8EE84A090850E878#第12集$id_MOE0824EA8EE84A090850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1076, 1, 0, 0, '天狼 Sirius the Jaeger', '天狼 Sirius the Jaeger（2018）', 'tianlangSiriustheJaeger', 1, 'T', '', '6c69c40d', '战斗,原创,架空,冒险', 'http://i0.hdslb.com/bfs/bangumi/2b0d7996d9ef2a3786da05fe3f1b92857fc2e6ad.jpg', '', '', '', '上村祐翔 / 樱井孝宏 / 堀内贤雄 / 森奈奈子 / 小林裕介 / 武内骏辅 / 高桥李依 / 间岛淳司 / 子安武人 / 津田健次郎 / 大原沙耶香', '安藤真裕', '', '', '昭和初期，帝都·东京府。怀抱乐器盒的奇妙团体，降临在东京车站。\r\n他们，是为了狩猎吸血鬼们而来的“猎人”——\r\n其中有一位格外沉静，散发出非同寻常气氛的青年。\r\n身为狼人和人类的混血儿，被吸血鬼摧毁了故乡的', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.7, 0, 0, 1740210776, 1740181456, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>昭和初期，帝都·东京府。怀抱乐器盒的奇妙团体，降临在东京车站。\r\n他们，是为了狩猎吸血鬼们而来的“猎人”——\r\n其中有一位格外沉静，散发出非同寻常气氛的青年。\r\n身为狼人和人类的混血儿，被吸血鬼摧毁了故乡的那个男人，名为尤里。\r\n围绕着名为“天狼之匣”的圣柜，与吸血鬼展开死战的尤里等人。\r\n他们在战斗的最后得知的真相会是……？\r\n悠远的恩怨和策谋的螺旋相交错。\r\n至极的悬疑动作剧，于此开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0774BA81EA1D5D5D50E978#第02集$MOE0774BA81EA1D5D5D50E97B#第03集$MOE0774BA81EA1D5D5D50E97A#第04集$MOE0774BA81EA1D5D5D50E97D#第05集$MOE0774BA81EA1D5D5D50E97C#第06集$MOE0774BA81EA1D5D5D50E97F#第07集$MOE0774BA81EA1D5D5D50E97E#第08集$MOE0774BA81EA1D5D5D50E971#第09集$MOE0774BA81EA1D5D5D50E970#第10集$MOE0774BA81EA1D5D5D50E879#第11集$MOE0774BA81EA1D5D5D50E878#第12集$MOE0774BA81EA1D5D5D50E87B$$$第01集$id_XS0774BA81EA1D5D5D50E978#第02集$id_XS0774BA81EA1D5D5D50E97B#第03集$id_XS0774BA81EA1D5D5D50E97A#第04集$id_XS0774BA81EA1D5D5D50E97D#第05集$id_XS0774BA81EA1D5D5D50E97C#第06集$id_XS0774BA81EA1D5D5D50E97F#第07集$id_XS0774BA81EA1D5D5D50E97E#第08集$id_XS0774BA81EA1D5D5D50E971#第09集$id_XS0774BA81EA1D5D5D50E970#第10集$id_XS0774BA81EA1D5D5D50E879#第11集$id_XS0774BA81EA1D5D5D50E878#第12集$id_XS0774BA81EA1D5D5D50E87B$$$第01集$id_MOE0774BA81EA1D5D5D50E978#第02集$id_MOE0774BA81EA1D5D5D50E97B#第03集$id_MOE0774BA81EA1D5D5D50E97A#第04集$id_MOE0774BA81EA1D5D5D50E97D#第05集$id_MOE0774BA81EA1D5D5D50E97C#第06集$id_MOE0774BA81EA1D5D5D50E97F#第07集$id_MOE0774BA81EA1D5D5D50E97E#第08集$id_MOE0774BA81EA1D5D5D50E971#第09集$id_MOE0774BA81EA1D5D5D50E970#第10集$id_MOE0774BA81EA1D5D5D50E879#第11集$id_MOE0774BA81EA1D5D5D50E878#第12集$id_MOE0774BA81EA1D5D5D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1077, 1, 0, 0, '替身', 'Another（2012）', 'tishen', 1, 'T', '', '6ac7acbb', '小说改,推理,悬疑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2186885848.jpg', '', '', '', '高森奈津美 / 阿部敦 / 米泽圆 / 前野智昭 / 山本和臣 / 市来光弘 / 野中蓝 / 鹰野晶 / 福圆美里 / 野水伊织 / 井上刚 / 室元气 / 平田真菜 / 河西健吾 / 小林康介 / 河本启佑 / 明坂聪美 / 岛村侑 / 南条爱乃 / 峰健一 / 浅利辽太 / 古谷静佳 / 榊原奈绪子 / 吉田圣子 / 定冈小百合 / 富㭴美铃 / 三户耕三 / 喜多川拓郎 / 矢田耕司 / 有马瑞香 / 原田瞳 / 五十岚裕美 / 佐佐木启夫 / 高桥伸也 / 平田广明', '水岛努 / 筱原俊哉 / 日色如夏 / 安斋刚文 / 岩崎太郎 / 仓川英扬 / 畑博之 / 柿本广大', '', '', '20世纪末，15岁的少年榊原恒一（阿部敦 配音）由于父亲前往海外公干的原因，于是来到亡母的家乡夜见山市，暂住阿姨三神怜子（宮牧美沙代 配音）家中等待转入新的学校。在此期间，他的旧病复发，入院治疗，某晚', '全12集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 37, 0, 37, 37, '', 0, 0, 9.7, 0, 0, 1740309310, 1740181470, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>20世纪末，15岁的少年榊原恒一（阿部敦 配音）由于父亲前往海外公干的原因，于是来到亡母的家乡夜见山市，暂住阿姨三神怜子（宮牧美沙代 配音）家中等待转入新的学校。在此期间，他的旧病复发，入院治疗，某晚，恒一在空荡荡的走廊内邂逅一名穿着水手服、左眼戴着眼罩但阴气逼人的美少女，这似乎预示着一段不平凡生活的开始。病愈出院，恒一顺利转入夜见山北中学3年3班，同学们热情亲和，可是似乎对他隐藏着什么秘密，而且他也再次看见医院的那名眼罩女孩——同班同学见崎鸣（高森奈津美 配音）。当他尝试接近见崎时，殊不知自己已经无意间掣动了死亡的闸门……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0776EF8FE84A0F5B50E978#第02集$MOE0776EF8FE84A0F5B50E97B#第03集$MOE0776EF8FE84A0F5B50E97A#第04集$MOE0776EF8FE84A0F5B50E97D#第05集$MOE0776EF8FE84A0F5B50E97C#第06集$MOE0776EF8FE84A0F5B50E97F#第07集$MOE0776EF8FE84A0F5B50E97E#第08集$MOE0776EF8FE84A0F5B50E971#第09集$MOE0776EF8FE84A0F5B50E970#第10集$MOE0776EF8FE84A0F5B50E879#第11集$MOE0776EF8FE84A0F5B50E878#第12集$MOE0776EF8FE84A0F5B50E87B$$$第01集$id_XS0776EF8FE84A0F5B50E978#第02集$id_XS0776EF8FE84A0F5B50E97B#第03集$id_XS0776EF8FE84A0F5B50E97A#第04集$id_XS0776EF8FE84A0F5B50E97D#第05集$id_XS0776EF8FE84A0F5B50E97C#第06集$id_XS0776EF8FE84A0F5B50E97F#第07集$id_XS0776EF8FE84A0F5B50E97E#第08集$id_XS0776EF8FE84A0F5B50E971#第09集$id_XS0776EF8FE84A0F5B50E970#第10集$id_XS0776EF8FE84A0F5B50E879#第11集$id_XS0776EF8FE84A0F5B50E878#第12集$id_XS0776EF8FE84A0F5B50E87B$$$第01集$id_MOE0776EF8FE84A0F5B50E978#第02集$id_MOE0776EF8FE84A0F5B50E97B#第03集$id_MOE0776EF8FE84A0F5B50E97A#第04集$id_MOE0776EF8FE84A0F5B50E97D#第05集$id_MOE0776EF8FE84A0F5B50E97C#第06集$id_MOE0776EF8FE84A0F5B50E97F#第07集$id_MOE0776EF8FE84A0F5B50E97E#第08集$id_MOE0776EF8FE84A0F5B50E971#第09集$id_MOE0776EF8FE84A0F5B50E970#第10集$id_MOE0776EF8FE84A0F5B50E879#第11集$id_MOE0776EF8FE84A0F5B50E878#第12集$id_MOE0776EF8FE84A0F5B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1078, 1, 0, 0, '化物语', '化物語（2009）', 'huawuyu', 1, 'H', '', 'bff952a4', '小说改,奇幻,校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554144600.jpg', '', '', '', '神谷浩史 / 斋藤千和 / 加藤英美里 / 泽城美雪 / 花泽香菜 / 堀江由衣 / 樱井孝宏 / 坂本真绫 / 喜多村英梨 / 井口裕香 / 立木文彦', '新房昭之 / 尾石达也 / 宫本幸裕 / 板村智幸 / 德本善信 / 铃木利正 / 美甘义人 / 大沼心', '', '', '三年同班同学却没有说过一句话，这指得就是阿良良木历（神谷浩史 配音）和战场原黑仪（斋藤千和 配音）。二人虽是同班同学，但可以说没有任何交集。本以为就会这样一直下去的阿良良木历因为一次偶然接住了意外从楼', '全15集', '', 0, '0', '', '', '日本', '日语', '2009', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.9, 0, 0, 1740219481, 1740182291, 0, 0, 0, 0, 0.0, '', '1079,1080,1081,1082,1083,1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>三年同班同学却没有说过一句话，这指得就是阿良良木历（神谷浩史 配音）和战场原黑仪（斋藤千和 配音）。二人虽是同班同学，但可以说没有任何交集。本以为就会这样一直下去的阿良良木历因为一次偶然接住了意外从楼梯上跌下来的黑仪。而这次意外的从天而降，让历知道了黑仪的秘密。而这个秘密牵扯到众多事情，虽然历发誓自己绝不会把这件事告诉任何人，但黑仪还是表示怀疑。而历也向黑仪透露出自己的小秘密。但这个城市并不是只有二人拥有神奇的力量。许多奇怪的生物和事情正在向二人靠拢。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5371EA81BC1B0C0D50E978#第02集$MOE5371EA81BC1B0C0D50E97B#第03集$MOE5371EA81BC1B0C0D50E97A#第04集$MOE5371EA81BC1B0C0D50E97D#第05集$MOE5371EA81BC1B0C0D50E97C#第06集$MOE5371EA81BC1B0C0D50E97F#第07集$MOE5371EA81BC1B0C0D50E97E#第08集$MOE5371EA81BC1B0C0D50E971#第09集$MOE5371EA81BC1B0C0D50E970#第10集$MOE5371EA81BC1B0C0D50E879#第11集$MOE5371EA81BC1B0C0D50E878#第12集$MOE5371EA81BC1B0C0D50E87B#第13集$MOE5371EA81BC1B0C0D50E87A#第14集$MOE5371EA81BC1B0C0D50E87D#第15集$MOE5371EA81BC1B0C0D50E87C$$$第01集$id_XS5371EA81BC1B0C0D50E978#第02集$id_XS5371EA81BC1B0C0D50E97B#第03集$id_XS5371EA81BC1B0C0D50E97A#第04集$id_XS5371EA81BC1B0C0D50E97D#第05集$id_XS5371EA81BC1B0C0D50E97C#第06集$id_XS5371EA81BC1B0C0D50E97F#第07集$id_XS5371EA81BC1B0C0D50E97E#第08集$id_XS5371EA81BC1B0C0D50E971#第09集$id_XS5371EA81BC1B0C0D50E970#第10集$id_XS5371EA81BC1B0C0D50E879#第11集$id_XS5371EA81BC1B0C0D50E878#第12集$id_XS5371EA81BC1B0C0D50E87B#第13集$id_XS5371EA81BC1B0C0D50E87A#第14集$id_XS5371EA81BC1B0C0D50E87D#第15集$id_XS5371EA81BC1B0C0D50E87C$$$第01集$id_MOE5371EA81BC1B0C0D50E978#第02集$id_MOE5371EA81BC1B0C0D50E97B#第03集$id_MOE5371EA81BC1B0C0D50E97A#第04集$id_MOE5371EA81BC1B0C0D50E97D#第05集$id_MOE5371EA81BC1B0C0D50E97C#第06集$id_MOE5371EA81BC1B0C0D50E97F#第07集$id_MOE5371EA81BC1B0C0D50E97E#第08集$id_MOE5371EA81BC1B0C0D50E971#第09集$id_MOE5371EA81BC1B0C0D50E970#第10集$id_MOE5371EA81BC1B0C0D50E879#第11集$id_MOE5371EA81BC1B0C0D50E878#第12集$id_MOE5371EA81BC1B0C0D50E87B#第13集$id_MOE5371EA81BC1B0C0D50E87A#第14集$id_MOE5371EA81BC1B0C0D50E87D#第15集$id_MOE5371EA81BC1B0C0D50E87C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1079, 1, 0, 0, '伪物语', '偽物語（2012）', 'weiwuyu', 1, 'W', '', '428cdabc', '小说改,奇幻,校园', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2169942916.jpg', '', '', '', '神谷浩史 / 喜多村英梨 / 井口裕香 / 斋藤千和 / 堀江由衣 / 樱井孝宏 / 坂本真绫 / 加藤英美里 / 泽城美雪 / 花泽香菜 / 早见沙织 / 白石凉子 / 三木真一郎', '新房昭之 / 八濑祐树 / 川畑乔 / 板村智幸 / 宫本幸裕 / 龙轮直征 / 美甘义人 / 石川俊介', '', '', '伪物语是伪物的物语(伪即不真实，不成熟，虚伪的)。历和女友战场原是伪物；历的两个妹妹火怜和月火是伪物；欺诈师贝木等也是伪物。而相对的，羽川是个非常强大的真物。伪物语中的怪异都与历的妹妹扯上了关系，引发', '全11集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 8.7, 0, 0, 1740226118, 1740182352, 0, 0, 0, 0, 0.0, '', '1080,1081,1082,1083,1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>伪物语是伪物的物语(伪即不真实，不成熟，虚伪的)。历和女友战场原是伪物；历的两个妹妹火怜和月火是伪物；欺诈师贝木等也是伪物。而相对的，羽川是个非常强大的真物。伪物语中的怪异都与历的妹妹扯上了关系，引发了一系列的事件。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0525B4DBED480F5A50E978#第02集$MOE0525B4DBED480F5A50E97B#第03集$MOE0525B4DBED480F5A50E97A#第04集$MOE0525B4DBED480F5A50E97D#第05集$MOE0525B4DBED480F5A50E97C#第06集$MOE0525B4DBED480F5A50E97F#第07集$MOE0525B4DBED480F5A50E97E#第08集$MOE0525B4DBED480F5A50E971#第09集$MOE0525B4DBED480F5A50E970#第10集$MOE0525B4DBED480F5A50E879#第11集$MOE0525B4DBED480F5A50E878$$$第01集$id_XS0525B4DBED480F5A50E978#第02集$id_XS0525B4DBED480F5A50E97B#第03集$id_XS0525B4DBED480F5A50E97A#第04集$id_XS0525B4DBED480F5A50E97D#第05集$id_XS0525B4DBED480F5A50E97C#第06集$id_XS0525B4DBED480F5A50E97F#第07集$id_XS0525B4DBED480F5A50E97E#第08集$id_XS0525B4DBED480F5A50E971#第09集$id_XS0525B4DBED480F5A50E970#第10集$id_XS0525B4DBED480F5A50E879#第11集$id_XS0525B4DBED480F5A50E878$$$第01集$id_MOE0525B4DBED480F5A50E978#第02集$id_MOE0525B4DBED480F5A50E97B#第03集$id_MOE0525B4DBED480F5A50E97A#第04集$id_MOE0525B4DBED480F5A50E97D#第05集$id_MOE0525B4DBED480F5A50E97C#第06集$id_MOE0525B4DBED480F5A50E97F#第07集$id_MOE0525B4DBED480F5A50E97E#第08集$id_MOE0525B4DBED480F5A50E971#第09集$id_MOE0525B4DBED480F5A50E970#第10集$id_MOE0525B4DBED480F5A50E879#第11集$id_MOE0525B4DBED480F5A50E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1080, 1, 0, 0, '猫物语(黑)', '猫物語(黒)（2012）', 'maowuyuhei', 1, 'M', '', '290458bc', '小说改,奇幻,校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2306703150.jpg', '', '', '', '神谷浩史 / 堀江由衣 / 樱井孝宏 / 坂本真绫 / 喜多村英梨 / 井口裕香', '板村智幸 / 新房昭之', '', '', '2012年にテレビアニメ化が予定されている。テレビアニメに先駆け、2012年12月29日にTOHOシネマズ六本木ヒルズにて抽選で240名を招いてイベント上映される予定であり、放送は翌々日の大晦日、12', '全4集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 8.8, 0, 0, 1740229982, 1740182377, 0, 0, 0, 0, 0.0, '', '1081,1082,1083,1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>2012年にテレビアニメ化が予定されている。テレビアニメに先駆け、2012年12月29日にTOHOシネマズ六本木ヒルズにて抽選で240名を招いてイベント上映される予定であり、放送は翌々日の大晦日、12月31日の22時から24時まで、TOKYO MX（東京地区、地上デジタル放送）、BS11（BSデジタル放送）、ニコニコ生放送（ネット配信）の3メディアで同時放送される。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032EBC8CBC110F5A50E978#第02集$MOE032EBC8CBC110F5A50E97B#第03集$MOE032EBC8CBC110F5A50E97A#第04集$MOE032EBC8CBC110F5A50E97D$$$第01集$id_XS032EBC8CBC110F5A50E978#第02集$id_XS032EBC8CBC110F5A50E97B#第03集$id_XS032EBC8CBC110F5A50E97A#第04集$id_XS032EBC8CBC110F5A50E97D$$$第01集$id_MOE032EBC8CBC110F5A50E978#第02集$id_MOE032EBC8CBC110F5A50E97B#第03集$id_MOE032EBC8CBC110F5A50E97A#第04集$id_MOE032EBC8CBC110F5A50E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1081, 1, 0, 0, '猫物语(白)', '猫物語 (白)（2013）', 'maowuyubai', 1, 'M', '', 'cb23d6af', '小说改,奇幻,校园', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2894944115.jpg', '', '', '', '堀江由衣 / 斋藤千和 / 神谷浩史 / 斋贺光希 / 折笠爱', '新房昭之', '', '', '“我不是无所不知，但我知道阿良良木的事情。”完美无缺的班长羽川翼，在第二学期首日，受到一只巨虎瞪视——这是空虚的独白，无人聆听的告白……', '全5集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.4, 0, 0, 1740234280, 1740225606, 0, 0, 0, 0, 0.0, '', '1082,1083,1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>“我不是无所不知，但我知道阿良良木的事情。”完美无缺的班长羽川翼，在第二学期首日，受到一只巨虎瞪视——这是空虚的独白，无人聆听的告白……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5275BE8BED1F0C5F50E978#第02集$MOE5275BE8BED1F0C5F50E97B#第03集$MOE5275BE8BED1F0C5F50E97A#第04集$MOE5275BE8BED1F0C5F50E97D#第05集$MOE5275BE8BED1F0C5F50E97C#总集篇$MOE5275BE8BED1F0C5F50E97F$$$第01集$id_XS5275BE8BED1F0C5F50E978#第02集$id_XS5275BE8BED1F0C5F50E97B#第03集$id_XS5275BE8BED1F0C5F50E97A#第04集$id_XS5275BE8BED1F0C5F50E97D#第05集$id_XS5275BE8BED1F0C5F50E97C#总集篇$id_XS5275BE8BED1F0C5F50E97F$$$第01集$id_MOE5275BE8BED1F0C5F50E978#第02集$id_MOE5275BE8BED1F0C5F50E97B#第03集$id_MOE5275BE8BED1F0C5F50E97A#第04集$id_MOE5275BE8BED1F0C5F50E97D#第05集$id_MOE5275BE8BED1F0C5F50E97C#总集篇$id_MOE5275BE8BED1F0C5F50E97F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1082, 1, 0, 0, '倾物语', '傾物語（2014）', 'qingwuyu', 1, 'Q', '', '14043010', '小说改,奇幻,校园', 'https://img3.doubanio.com/view/subject/m/public/s27889383.jpg', '', '', '', '堀江由衣 / 斋藤千和 / 神谷浩史 / 斋贺光希 / 折笠爱', '新房昭之', '', '', '“既然任何事物都会改变，那我连命运也要改变。”迷路的小学生——八九寺真宵。阿良良木为了她，犯下无法挽回的过错？《物语》系列史上最强的双人组，挑战名为命运的战场！这就是现代的怪异！怪异！怪异！寻找你的身', '全4集', '', 0, '', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 0.0, 0, 0, 1740236375, 1740230159, 0, 0, 0, 0, 0.0, '', '1083,1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>“既然任何事物都会改变，</p><p>那我连命运也要改变。”</p><p>迷路的小学生——八九寺真宵。</p><p>阿良良木为了她，</p><p>犯下无法挽回的过错？</p><p>《物语》系列史上最强的双人组，</p><p>挑战名为命运的战场！</p><p>这就是现代的</p><p>怪异！怪异！怪异！</p><p>寻找你的身影，迷失于归途。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0023BC8CBA195C0950E978#第02集$MOE0023BC8CBA195C0950E97B#第03集$MOE0023BC8CBA195C0950E97A#第04集$MOE0023BC8CBA195C0950E97D#总集篇$MOE0023BC8CBA195C0950E97C$$$第01集$id_XS0023BC8CBA195C0950E978#第02集$id_XS0023BC8CBA195C0950E97B#第03集$id_XS0023BC8CBA195C0950E97A#第04集$id_XS0023BC8CBA195C0950E97D#总集篇$id_XS0023BC8CBA195C0950E97C$$$第01集$id_MOE0023BC8CBA195C0950E978#第02集$id_MOE0023BC8CBA195C0950E97B#第03集$id_MOE0023BC8CBA195C0950E97A#第04集$id_MOE0023BC8CBA195C0950E97D#总集篇$id_MOE0023BC8CBA195C0950E97C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1083, 1, 0, 0, '囮物语', '囮物語（2014）', 'ewuyu', 1, 'E', '', '520b81a3', '小说改,奇幻,校园', 'https://img1.doubanio.com/view/subject/m/public/s27110768.jpg', '', '', '', '堀江由衣 / 斋藤千和 / 神谷浩史 / 斋贺光希 / 折笠爱', '新房昭之', '', '', '「明明是神，卻是大騙子。」曾經被蛇糾纏附身的少女──千石撫子。純白的使者，出現在心儀阿良良木曆的她面前。這名「使者」的真面目是……？〈物語〉朝著最終章蜿蜒、交纏、進化──這就是現代的怪異！怪異！怪異！', '全4集', '', 0, '', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 0.0, 0, 0, 1740239132, 1740234655, 0, 0, 0, 0, 0.0, '', '1084,1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>「明明是神，卻是大騙子。」</p><p>曾經被蛇糾纏附身的少女──千石撫子。</p><p>純白的使者，出現在心儀阿良良木曆的她面前。</p><p>這名「使者」的真面目是……？</p><p>〈物語〉朝著最終章蜿蜒、交纏、進化──</p><p>這就是現代的怪異！怪異！怪異！</p><p>在陷阱之中，緊咬不放，感受你的存在</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0425BCDAB1180C0A50E978#第02集$MOE0425BCDAB1180C0A50E97B#第03集$MOE0425BCDAB1180C0A50E97A#第04集$MOE0425BCDAB1180C0A50E97D#总集篇$MOE0425BCDAB1180C0A50E97C$$$第01集$id_XS0425BCDAB1180C0A50E978#第02集$id_XS0425BCDAB1180C0A50E97B#第03集$id_XS0425BCDAB1180C0A50E97A#第04集$id_XS0425BCDAB1180C0A50E97D#总集篇$id_XS0425BCDAB1180C0A50E97C$$$第01集$id_MOE0425BCDAB1180C0A50E978#第02集$id_MOE0425BCDAB1180C0A50E97B#第03集$id_MOE0425BCDAB1180C0A50E97A#第04集$id_MOE0425BCDAB1180C0A50E97D#总集篇$id_MOE0425BCDAB1180C0A50E97C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1084, 1, 0, 0, '鬼物语', '鬼物語（2014）', 'guiwuyu', 1, 'G', '', 'cb76a534', '小说改,奇幻,校园', 'https://img9.doubanio.com/view/subject/m/public/s27194714.jpg', '', '', '', '堀江由衣 / 斋藤千和 / 神谷浩史 / 斋贺光希 / 折笠爱', '新房昭之', '', '', '「不努力解除誤會，等同於說謊。」棲息於阿良良木曆影子裡的吸血鬼──忍野忍。從她的記憶中喚醒，「超越怪異的威脅」是……!?美麗吸血鬼的獨白超越時空，吞噬現在──這就是現代的怪異！怪異！怪異！這個謊言，你', '全4集', '', 0, '', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 0.0, 0, 0, 1740241735, 1740236698, 0, 0, 0, 0, 0.0, '', '1085,1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>「不努力解除誤會，等同於說謊。」</p><p>棲息於阿良良木曆影子裡的吸血鬼──忍野忍。</p><p>從她的記憶中喚醒，</p><p>「超越怪異的威脅」是……!?</p><p>美麗吸血鬼的獨白超越時空，吞噬現在──</p><p>這就是現代的怪異！怪異！怪異！</p><p>這個謊言，你肯定也早已知曉。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5275BB8EE81C5E0D50E978#第02集$MOE5275BB8EE81C5E0D50E97B#第03集$MOE5275BB8EE81C5E0D50E97A#第04集$MOE5275BB8EE81C5E0D50E97D$$$第01集$id_XS5275BB8EE81C5E0D50E978#第02集$id_XS5275BB8EE81C5E0D50E97B#第03集$id_XS5275BB8EE81C5E0D50E97A#第04集$id_XS5275BB8EE81C5E0D50E97D$$$第01集$id_MOE5275BB8EE81C5E0D50E978#第02集$id_MOE5275BB8EE81C5E0D50E97B#第03集$id_MOE5275BB8EE81C5E0D50E97A#第04集$id_MOE5275BB8EE81C5E0D50E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1085, 1, 0, 0, '恋物语', '戀物語（2014）', 'lianwuyu', 1, 'L', '', '1b7886be', '小说改,奇幻,校园', 'https://img3.doubanio.com/view/subject/m/public/s27276503.jpg', '', '', '', '堀江由衣 / 斋藤千和 / 神谷浩史 / 斋贺光希 / 折笠爱', '新房昭之', '', '', '「若能永遠單戀……不覺得比兩情相悅還幸福嗎？」為了保護阿良良木曆，和神進行生命交易的少女──戰場原黑儀。約定「忌日」將近的寒假，她選擇的是最黑、最惡劣的手段……〈物語〉承受重壓而軋轢、扭曲、哀號──這', '全6集', '', 0, '', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 0.0, 0, 0, 1740245088, 1740241097, 0, 0, 0, 0, 0.0, '', '1086,1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>「若能永遠單戀……</p><p>不覺得比兩情相悅還幸福嗎？」</p><p>為了保護阿良良木曆，</p><p>和神進行生命交易的少女──戰場原黑儀。</p><p>約定「忌日」將近的寒假，</p><p>她選擇的是最黑、最惡劣的手段……</p><p>〈物語〉承受重壓而軋轢、扭曲、哀號──</p><p>這就是現代的怪異！怪異！怪異！</p><p>青春，是為了和你相戀。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0075BB80B11F0F5C50E978#第02集$MOE0075BB80B11F0F5C50E97B#第03集$MOE0075BB80B11F0F5C50E97A#第04集$MOE0075BB80B11F0F5C50E97D#第05集$MOE0075BB80B11F0F5C50E97C#第06集$MOE0075BB80B11F0F5C50E97F$$$第01集$id_XS0075BB80B11F0F5C50E978#第02集$id_XS0075BB80B11F0F5C50E97B#第03集$id_XS0075BB80B11F0F5C50E97A#第04集$id_XS0075BB80B11F0F5C50E97D#第05集$id_XS0075BB80B11F0F5C50E97C#第06集$id_XS0075BB80B11F0F5C50E97F$$$第01集$id_MOE0075BB80B11F0F5C50E978#第02集$id_MOE0075BB80B11F0F5C50E97B#第03集$id_MOE0075BB80B11F0F5C50E97A#第04集$id_MOE0075BB80B11F0F5C50E97D#第05集$id_MOE0075BB80B11F0F5C50E97C#第06集$id_MOE0075BB80B11F0F5C50E97F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1086, 1, 0, 0, '花物语', '花物語（2014）', 'huawuyu', 1, 'H', '', '82c3bb66', '小说改,奇幻,校园', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2185662631.jpg', '', '', '', '泽城美雪 / 阿澄佳奈 / 三木真一郎 / 神谷浩史 / 喜多村英梨 / 水桥香织 / 根谷美智子 / 日笠阳子', '新房昭之 / 板村智幸 / 宫本幸裕 / 久保山英一 / 冈田坚二朗', '', '', '17岁少女神原骏河（泽城美雪 饰）拥有与众不同的人生经历，童年时代她从亡母手中接过能够帮助人实现三个愿望的猿猴之手。据说只要向猿猴之手祈愿，甚至可以改变看似不可逆转的命运，但是许愿的人也将付出巨大的代', '全5集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.7, 0, 0, 1740268889, 1740242320, 0, 0, 0, 0, 0.0, '', '1087,1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>17岁少女神原骏河（泽城美雪 饰）拥有与众不同的人生经历，童年时代她从亡母手中接过能够帮助人实现三个愿望的猿猴之手。据说只要向猿猴之手祈愿，甚至可以改变看似不可逆转的命运，但是许愿的人也将付出巨大的代价。在前辈阿良良木历（神谷浩史 饰）的帮助下，猿猴之手最终依附在骏河的左手上，她不得不每日缠着绷带掩盖不平凡的一切。这个春天，骏河成为三年级的学生了。而就在此时，学校内外关于“恶魔大人”的传言甚嚣尘上。觉察到异样的骏河展开调查，谁知却遭遇了毕生无法忘却的宿敌……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0925EF8BEB4B5B0F50E978#第02集$MOE0925EF8BEB4B5B0F50E97B#第03集$MOE0925EF8BEB4B5B0F50E97A#第04集$MOE0925EF8BEB4B5B0F50E97D#第05集$MOE0925EF8BEB4B5B0F50E97C$$$第01集$id_XS0925EF8BEB4B5B0F50E978#第02集$id_XS0925EF8BEB4B5B0F50E97B#第03集$id_XS0925EF8BEB4B5B0F50E97A#第04集$id_XS0925EF8BEB4B5B0F50E97D#第05集$id_XS0925EF8BEB4B5B0F50E97C$$$第01集$id_MOE0925EF8BEB4B5B0F50E978#第02集$id_MOE0925EF8BEB4B5B0F50E97B#第03集$id_MOE0925EF8BEB4B5B0F50E97A#第04集$id_MOE0925EF8BEB4B5B0F50E97D#第05集$id_MOE0925EF8BEB4B5B0F50E97C', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1087, 1, 0, 0, '凭物语', '憑物語（2014）', 'pingwuyu', 1, 'P', '', '48f7bf5a', '小说改,奇幻,校园', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2306703017.jpg', '', '', '', '神谷浩史 / 早见沙织 / 喜多村英梨 / 井口裕香 / 坂本真绫 / 白石凉子 / 子安武人 / 水桥香织 / 斋藤千和', '新房昭之 / 板村智幸 / 大桥一辉 / 冈田坚二朗', '', '', '阿良良木历（神谷浩史 配音）正在为了即将到来的考试进行着刻苦的准备，一次偶然中，阿历发现镜子里竟然映不出自己的身影，惊慌失措的他找到了专门研究不思议事件的斧乃木余接（早见沙织 配音）和影缝余弦（白石凉', '全4集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 8.7, 0, 0, 1740269585, 1740246253, 0, 0, 0, 0, 0.0, '', '1088,1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>阿良良木历（神谷浩史 配音）正在为了即将到来的考试进行着刻苦的准备，一次偶然中，阿历发现镜子里竟然映不出自己的身影，惊慌失措的他找到了专门研究不思议事件的斧乃木余接（早见沙织 配音）和影缝余弦（白石凉子 配音），让阿历没有想到的是，两人竟然告诉他，他即将要变成吸血鬼了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE052FEA8FEB4F585850E978#第02集$MOE052FEA8FEB4F585850E97B#第03集$MOE052FEA8FEB4F585850E97A#第04集$MOE052FEA8FEB4F585850E97D$$$第01集$id_XS052FEA8FEB4F585850E978#第02集$id_XS052FEA8FEB4F585850E97B#第03集$id_XS052FEA8FEB4F585850E97A#第04集$id_XS052FEA8FEB4F585850E97D$$$第01集$id_MOE052FEA8FEB4F585850E978#第02集$id_MOE052FEA8FEB4F585850E97B#第03集$id_MOE052FEA8FEB4F585850E97A#第04集$id_MOE052FEA8FEB4F585850E97D', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1088, 1, 0, 0, '终物语', '終物語（2015）', 'zhongwuyu', 1, 'Z', '', '29e6c7d5', '奇幻,小说改', 'http://i0.hdslb.com/bfs/bangumi/9ba055dbffa735c6f466215cd73384afca56d186.jpg', '', '', '', '神谷浩史 / 水桥香织 / 井上麻里奈 / 斋藤千和 / 堀江由衣 / 泽城美雪 / 花泽香菜 / 坂本真绫 / 早见沙织 / 雪野五月', '新房昭之 / 板村智幸 / 草川启造 / 铃木拓磨 / 大谷肇 / 吉泽翠 / 大桥一辉 / 寻田耕辅 / 冈田坚二朗', '', '', '高三的十月下旬，神原骏河向高中三年级的阿良良木历介绍了一位转校生——忍野扇。放学后，忍野扇说起了一些奇怪的事情。她曾转学过很多次，并将每一次到过的校舍都画成地图。他发现三楼的视听室被拉长，也许有隐藏的', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.7, 0, 0, 1740276180, 1740275987, 0, 0, 0, 0, 0.0, '', '1089,1090,1091,1092', '', '', '', '', '', '', '', '<p>高三的十月下旬，神原骏河向高中三年级的阿良良木历介绍了一位转校生——忍野扇。放学后，忍野扇说起了一些奇怪的事情。她曾转学过很多次，并将每一次到过的校舍都画成地图。他发现三楼的视听室被拉长，也许有隐藏的房间。扇和历发现了隐藏的房间，进去后里面有停止的时钟和推不动的门窗，一切就像停止了一样…\r\n这是解开阿良良木历构成之谜的物语，也是知晓一切起点的物语。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032EE98EEA1E090C50E978#第02集$MOE032EE98EEA1E090C50E97B#第03集$MOE032EE98EEA1E090C50E97A#第04集$MOE032EE98EEA1E090C50E97D#第05集$MOE032EE98EEA1E090C50E97C#第06集$MOE032EE98EEA1E090C50E97F#第07集$MOE032EE98EEA1E090C50E97E#第08集$MOE032EE98EEA1E090C50E971#第09集$MOE032EE98EEA1E090C50E970#第10集$MOE032EE98EEA1E090C50E879#第11集$MOE032EE98EEA1E090C50E878#第12集$MOE032EE98EEA1E090C50E87B#第13集$MOE032EE98EEA1E090C50E87A$$$第01集$id_XS032EE98EEA1E090C50E978#第02集$id_XS032EE98EEA1E090C50E97B#第03集$id_XS032EE98EEA1E090C50E97A#第04集$id_XS032EE98EEA1E090C50E97D#第05集$id_XS032EE98EEA1E090C50E97C#第06集$id_XS032EE98EEA1E090C50E97F#第07集$id_XS032EE98EEA1E090C50E97E#第08集$id_XS032EE98EEA1E090C50E971#第09集$id_XS032EE98EEA1E090C50E970#第10集$id_XS032EE98EEA1E090C50E879#第11集$id_XS032EE98EEA1E090C50E878#第12集$id_XS032EE98EEA1E090C50E87B#第13集$id_XS032EE98EEA1E090C50E87A$$$第01集$id_MOE032EE98EEA1E090C50E978#第02集$id_MOE032EE98EEA1E090C50E97B#第03集$id_MOE032EE98EEA1E090C50E97A#第04集$id_MOE032EE98EEA1E090C50E97D#第05集$id_MOE032EE98EEA1E090C50E97C#第06集$id_MOE032EE98EEA1E090C50E97F#第07集$id_MOE032EE98EEA1E090C50E97E#第08集$id_MOE032EE98EEA1E090C50E971#第09集$id_MOE032EE98EEA1E090C50E970#第10集$id_MOE032EE98EEA1E090C50E879#第11集$id_MOE032EE98EEA1E090C50E878#第12集$id_MOE032EE98EEA1E090C50E87B#第13集$id_MOE032EE98EEA1E090C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1089, 1, 0, 0, '历物语', '暦物語（2016）', 'liwuyu', 1, 'L', '', '9a02c917', '奇幻,校园', 'http://i0.hdslb.com/bfs/bangumi/9755ab42d9ed934e21d03982e02844ca516082fc.jpg', '', '', '', '神谷浩史 / 堀江由衣 / 樱井孝宏 / 斋藤千和 / 泽城美雪 / 花泽香菜 / 三木真一郎 / 喜多村英梨 / 井口裕香 / 水桥香织 / 坂本真绫 / 早见沙织 / 白石凉子 / 雪野五月', '新房昭之 / 板村智幸 / 深濑重 / 安食圭 / 大桥一辉 / 铃木拓磨', '', '', '在与美丽吸血鬼遭遇的春假之后，主人公阿良良木历迎来了新学期。本篇描述了从新学期的第一个月开始到大学入学考试为止，阿良良木历这一年间所经历的故事。\r\n随后，“物语”将迎来命运的晨曦……', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.7, 0, 0, 1740280610, 1740276023, 0, 0, 0, 0, 0.0, '', '1090,1091,1092', '', '', '', '', '', '', '', '<p>在与美丽吸血鬼遭遇的春假之后，主人公阿良良木历迎来了新学期。本篇描述了从新学期的第一个月开始到大学入学考试为止，阿良良木历这一年间所经历的故事。\r\n随后，“物语”将迎来命运的晨曦……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0876BC8AEA105C0E50E978#第02集$MOE0876BC8AEA105C0E50E97B#第03集$MOE0876BC8AEA105C0E50E97A#第04集$MOE0876BC8AEA105C0E50E97D#第05集$MOE0876BC8AEA105C0E50E97C#第06集$MOE0876BC8AEA105C0E50E97F#第07集$MOE0876BC8AEA105C0E50E97E#第08集$MOE0876BC8AEA105C0E50E971#第09集$MOE0876BC8AEA105C0E50E970#第10集$MOE0876BC8AEA105C0E50E879#第11集$MOE0876BC8AEA105C0E50E878#第12集$MOE0876BC8AEA105C0E50E87B$$$第01集$id_XS0876BC8AEA105C0E50E978#第02集$id_XS0876BC8AEA105C0E50E97B#第03集$id_XS0876BC8AEA105C0E50E97A#第04集$id_XS0876BC8AEA105C0E50E97D#第05集$id_XS0876BC8AEA105C0E50E97C#第06集$id_XS0876BC8AEA105C0E50E97F#第07集$id_XS0876BC8AEA105C0E50E97E#第08集$id_XS0876BC8AEA105C0E50E971#第09集$id_XS0876BC8AEA105C0E50E970#第10集$id_XS0876BC8AEA105C0E50E879#第11集$id_XS0876BC8AEA105C0E50E878#第12集$id_XS0876BC8AEA105C0E50E87B$$$第01集$id_MOE0876BC8AEA105C0E50E978#第02集$id_MOE0876BC8AEA105C0E50E97B#第03集$id_MOE0876BC8AEA105C0E50E97A#第04集$id_MOE0876BC8AEA105C0E50E97D#第05集$id_MOE0876BC8AEA105C0E50E97C#第06集$id_MOE0876BC8AEA105C0E50E97F#第07集$id_MOE0876BC8AEA105C0E50E97E#第08集$id_MOE0876BC8AEA105C0E50E971#第09集$id_MOE0876BC8AEA105C0E50E970#第10集$id_MOE0876BC8AEA105C0E50E879#第11集$id_MOE0876BC8AEA105C0E50E878#第12集$id_MOE0876BC8AEA105C0E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1090, 1, 0, 0, '伤物语', '傷物語（2016）', 'shangwuyu1tiexuepian', 1, 'S', '', '12b3a1e1', '小说改,奇幻,校园', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2271912811.jpg', '', '', '', '神谷浩史 / 坂本真绫 / 堀江由衣 / 樱井孝宏', '新房昭之 / 尾石达也', '', '', '樱花飞舞的3月25日，完成了一学期学业的午后。高二学生阿良良木历（神谷浩史 配音）从优等生羽川翼（堀江由衣 配音）那里听说了本町出现吸血鬼的传言。当晚，历在地铁站台见到了一个血淋林的女人。她四肢全无，', '全3集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 8.5, 0, 0, 1740305502, 1740280463, 0, 0, 0, 0, 0.0, '', '1091,1092', '', '', '', '', '', '', '', '<p>樱花飞舞的3月25日，完成了一学期学业的午后。高二学生阿良良木历（神谷浩史 配音）从优等生羽川翼（堀江由衣 配音）那里听说了本町出现吸血鬼的传言。当晚，历在地铁站台见到了一个血淋林的女人。她四肢全无，痛苦求救。而女人的身后则站着一个金色头发却目光阴冷的身影，那难道就是传言中的吸血鬼？在这个夜晚，历与活了500年的吸血鬼姬丝秀忒•雅赛劳拉莉昂•刃下心（坂本真绫 配音）完成了命运的相逢……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0025EE8BE818080850E978#第02集$MOE0025EE8BE818080850E97B#第03集$MOE0025EE8BE818080850E97A$$$第01集$id_XS0025EE8BE818080850E978#第02集$id_XS0025EE8BE818080850E97B#第03集$id_XS0025EE8BE818080850E97A$$$第01集$id_MOE0025EE8BE818080850E978#第02集$id_MOE0025EE8BE818080850E97B#第03集$id_MOE0025EE8BE818080850E97A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1091, 1, 0, 0, '终物语 下', '終物語 下（2017）', 'zhongwuyuxia', 1, 'Z', '', 'b617732e', '奇幻,神魔', 'http://i0.hdslb.com/bfs/bangumi/d364981f12c3a7b3943d53a8f801ba5c3cf37286.jpg', '', '', '', '神谷浩史 / 水桥香织 / 斋藤千和 / 堀江由衣 / 加藤英美里 / 泽城美雪 / 花泽香菜 / 喜多村英梨 / 井口裕香 / 早见沙织 / 坂本真绫 / 子安武人 / 雪野五月 / 樱井孝宏', '新房昭之 / 板村智幸 / 浅见隆司 / 宫西哲也 / 金子祥之', '', '', '在3月13日，也就是大学入学考试的当天早上，阿良良木历被卧烟伊豆湖所杀。在死后世界等待着历的，正是八九寺真宵。她将历带到某个地方，迎接他们的，则是根本想象不到的人物。（包含单行本的3个篇章，即《真宵地', '全7集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 9.8, 0, 0, 1740301427, 1740284163, 0, 0, 0, 0, 0.0, '', '1092', '', '', '', '', '', '', '', '<p>在3月13日，也就是大学入学考试的当天早上，阿良良木历被卧烟伊豆湖所杀。在死后世界等待着历的，正是八九寺真宵。她将历带到某个地方，迎接他们的，则是根本想象不到的人物。（包含单行本的3个篇章，即《真宵地狱》《黑仪约会》和《扇黑暗》）</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5321BD8FBE1A5F5C50E978#第02集$MOE5321BD8FBE1A5F5C50E97B#第03集$MOE5321BD8FBE1A5F5C50E97A#第04集$MOE5321BD8FBE1A5F5C50E97D#第05集$MOE5321BD8FBE1A5F5C50E97C#第06集$MOE5321BD8FBE1A5F5C50E97F#第07集$MOE5321BD8FBE1A5F5C50E97E$$$第01集$id_XS5321BD8FBE1A5F5C50E978#第02集$id_XS5321BD8FBE1A5F5C50E97B#第03集$id_XS5321BD8FBE1A5F5C50E97A#第04集$id_XS5321BD8FBE1A5F5C50E97D#第05集$id_XS5321BD8FBE1A5F5C50E97C#第06集$id_XS5321BD8FBE1A5F5C50E97F#第07集$id_XS5321BD8FBE1A5F5C50E97E$$$第01集$id_MOE5321BD8FBE1A5F5C50E978#第02集$id_MOE5321BD8FBE1A5F5C50E97B#第03集$id_MOE5321BD8FBE1A5F5C50E97A#第04集$id_MOE5321BD8FBE1A5F5C50E97D#第05集$id_MOE5321BD8FBE1A5F5C50E97C#第06集$id_MOE5321BD8FBE1A5F5C50E97F#第07集$id_MOE5321BD8FBE1A5F5C50E97E', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1092, 1, 0, 0, '续·终物语', '続・終物語（2018）', 'xuzhongwuyu', 1, 'X', '', '475ba72b', '小说改,奇幻,校园', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2527221882.jpg', '', '', '', '神谷浩史 / 斋藤千和 / 加藤英美里 / 泽城美雪 / 花泽香菜 / 堀江由衣 / 喜多村英梨 / 井口裕香 / 早见沙织 / 井上麻里奈 / 坂本真绫 / 水桥香织 / 根谷美智子', '新房昭之 / 冈田坚二朗 / 大谷肇 / 吉泽翠 / 浅见隆司 / 川崎丰', '', '', '和我们一起，继续成长的物语。', '全6集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.0, 0, 0, 1740301512, 1740300960, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>和我们一起，继续成长的物语。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0520B9DAE81E5F5B50E978#第02集$MOE0520B9DAE81E5F5B50E97B#第03集$MOE0520B9DAE81E5F5B50E97A#第04集$MOE0520B9DAE81E5F5B50E97D#第05集$MOE0520B9DAE81E5F5B50E97C#第06集$MOE0520B9DAE81E5F5B50E97F$$$第01集$id_XS0520B9DAE81E5F5B50E978#第02集$id_XS0520B9DAE81E5F5B50E97B#第03集$id_XS0520B9DAE81E5F5B50E97A#第04集$id_XS0520B9DAE81E5F5B50E97D#第05集$id_XS0520B9DAE81E5F5B50E97C#第06集$id_XS0520B9DAE81E5F5B50E97F$$$第01集$id_MOE0520B9DAE81E5F5B50E978#第02集$id_MOE0520B9DAE81E5F5B50E97B#第03集$id_MOE0520B9DAE81E5F5B50E97A#第04集$id_MOE0520B9DAE81E5F5B50E97D#第05集$id_MOE0520B9DAE81E5F5B50E97C#第06集$id_MOE0520B9DAE81E5F5B50E97F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1093, 1, 0, 0, '替身：因果', 'Another  The Other -因果-（2012）', 'tishenyinguo', 1, 'T', '', '4841c068', '小说改,推理,悬疑', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1562791778.jpg', '', '', '', '高森奈津美 / 五十岚裕美 / 阿部敦', '水岛努', '', '', '在一个阳光明媚的日子里，左眼戴着眼罩的美少女被人搭讪，女孩则冷冷地讲述关于二重身的恐怖传说，不久果然有一个同样戴眼罩、长相与之完全相似的女孩走了过来，吓得男孩落荒而逃。原来后来者便是见崎鸣（高森奈津美', 'OVA', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 7.7, 0, 0, 1740309433, 1740306796, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在一个阳光明媚的日子里，左眼戴着眼罩的美少女被人搭讪，女孩则冷冷地讲述关于二重身的恐怖传说，不久果然有一个同样戴眼罩、长相与之完全相似的女孩走了过来，吓得男孩落荒而逃。原来后来者便是见崎鸣（高森奈津美 配音），恶作剧的女孩则是她自幼便分离的双胞胎姐妹未咲（五十岚裕美 配音）。性格不同的两姐妹结伴游玩，讲述着关于身世、血缘最真实的感受。令见崎担忧的是，她的左眼隐隐看到即将发生在未咲身上的不祥征兆，次日去游乐场的路上，她无论如何希望守护未咲。姐妹俩快乐而短暂的一天……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE052FB889EA195B0150E978$$$OVA$id_XS052FB889EA195B0150E978$$$OVA$id_MOE052FB889EA195B0150E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1094, 1, 0, 0, '自称贤者弟子的贤者', '賢者の弟子を名乗る賢者（2022）', 'zichengxianzhedizidexianzhe', 1, 'Z', '', '9fd7ec37', '小说改,奇幻,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/876063fff133eff35b98d1e4fc8da104d135d26a.png', '', '', '', '大森日雅 / 日向未南 / 佐仓绫音 / 村濑步 / 堀江由衣 / 安元洋贵', '元永庆太郎', '', '', '拓展出无限可能性的虚拟现实大型多人在线角色扮演游戏《方舟地球网络版》。\r\n玩家建立的国度阿尔凯特王国拥有九位贤者，\r\n其中有一位威风凛凛的老年召唤术士名叫邓不利夫，是游戏玩家之一。\r\n某一天，他感受到世界发', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 15, 0, 15, 15, '', 0, 0, 6.1, 0, 0, 1740321422, 1740309132, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>拓展出无限可能性的虚拟现实大型多人在线角色扮演游戏《方舟地球网络版》。\r\n玩家建立的国度阿尔凯特王国拥有九位贤者，\r\n其中有一位威风凛凛的老年召唤术士名叫邓不利夫，是游戏玩家之一。\r\n某一天，他感受到世界发生了异常的变化。\r\n不仅产生了游戏中本没有的味觉和嗅觉，更是无法退出游戏。\r\n甚至在非玩家角色身上发现了酷似人类的反应。\r\n这证明了游戏已经成为了不折不扣的现实。\r\n而且这个世界已经走过了足足30年。\r\n更不可思议的是，邓不利夫因为种种原因身体变成了幼小而美丽的少女！为了解开面目全非的世界之谜，\r\n邓不利夫自称为贤者的弟子米菈踏上了旅途。\r\n在冒险的最后等待他的会是什么呢——。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0871E88FEC4A5E0E50E978#第02集$MOE0871E88FEC4A5E0E50E97B#第03集$MOE0871E88FEC4A5E0E50E97A#第04集$MOE0871E88FEC4A5E0E50E97D#第05集$MOE0871E88FEC4A5E0E50E97C#第06集$MOE0871E88FEC4A5E0E50E97F#第07集$MOE0871E88FEC4A5E0E50E97E#第08集$MOE0871E88FEC4A5E0E50E971#第09集$MOE0871E88FEC4A5E0E50E970#第10集$MOE0871E88FEC4A5E0E50E879#第11集$MOE0871E88FEC4A5E0E50E878#第12集$MOE0871E88FEC4A5E0E50E87B$$$第01集$id_XS0871E88FEC4A5E0E50E978#第02集$id_XS0871E88FEC4A5E0E50E97B#第03集$id_XS0871E88FEC4A5E0E50E97A#第04集$id_XS0871E88FEC4A5E0E50E97D#第05集$id_XS0871E88FEC4A5E0E50E97C#第06集$id_XS0871E88FEC4A5E0E50E97F#第07集$id_XS0871E88FEC4A5E0E50E97E#第08集$id_XS0871E88FEC4A5E0E50E971#第09集$id_XS0871E88FEC4A5E0E50E970#第10集$id_XS0871E88FEC4A5E0E50E879#第11集$id_XS0871E88FEC4A5E0E50E878#第12集$id_XS0871E88FEC4A5E0E50E87B$$$第01集$id_MOE0871E88FEC4A5E0E50E978#第02集$id_MOE0871E88FEC4A5E0E50E97B#第03集$id_MOE0871E88FEC4A5E0E50E97A#第04集$id_MOE0871E88FEC4A5E0E50E97D#第05集$id_MOE0871E88FEC4A5E0E50E97C#第06集$id_MOE0871E88FEC4A5E0E50E97F#第07集$id_MOE0871E88FEC4A5E0E50E97E#第08集$id_MOE0871E88FEC4A5E0E50E971#第09集$id_MOE0871E88FEC4A5E0E50E970#第10集$id_MOE0871E88FEC4A5E0E50E879#第11集$id_MOE0871E88FEC4A5E0E50E878#第12集$id_MOE0871E88FEC4A5E0E50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1095, 1, 0, 0, '动物新世代 / BNA', 'BNA ビー・エヌ・エー（2020）', 'dongwuxinshidaiBNA', 1, 'D', '', '6568f26e', '原创', 'http://i0.hdslb.com/bfs/bangumi/image/2f84dd532ae5dfc16980dacdb5830423e29207d7.png', '', '', '', '诸星堇 / 细谷佳正 / 长绳麻理亚 / 石川界人 / 乃村健次 / 中博史 / 家中宏 / 齐藤贵美子 / 多田野曜平 / 大塚芳忠', '吉成曜', '', '', '21世纪，一直以来隐藏在历史暗处的兽人们的存在开始为人所知。\r\n曾是普通人类的影森满，某天突然变成了狸兽人。她为了逃避人类而前往的兽人特区“动物都市”，是十年前兽人为了像兽人一样活着而建造的兽人专属的城', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.3, 0, 0, 1740352105, 1740309516, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>21世纪，一直以来隐藏在历史暗处的兽人们的存在开始为人所知。\r\n曾是普通人类的影森满，某天突然变成了狸兽人。她为了逃避人类而前往的兽人特区“动物都市”，是十年前兽人为了像兽人一样活着而建造的兽人专属的城镇。满在那里与厌恶人类的狼兽人·大神士郎相遇，并和他一起行动。在此期间，她学习到自己在人类世界所不知道的“兽人们”的烦恼、生活以及喜悦。\r\n满为何会变成兽人呢？就在追寻谜底的过程中，她自身也被卷入了意想不到的巨大事件当中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0722BA80EF1B5B5C50E978#第02集$MOE0722BA80EF1B5B5C50E97B#第03集$MOE0722BA80EF1B5B5C50E97A#第04集$MOE0722BA80EF1B5B5C50E97D#第05集$MOE0722BA80EF1B5B5C50E97C#第06集$MOE0722BA80EF1B5B5C50E97F#第07集$MOE0722BA80EF1B5B5C50E97E#第08集$MOE0722BA80EF1B5B5C50E971#第09集$MOE0722BA80EF1B5B5C50E970#第10集$MOE0722BA80EF1B5B5C50E879#第11集$MOE0722BA80EF1B5B5C50E878#第12集$MOE0722BA80EF1B5B5C50E87B$$$第01集$id_XS0722BA80EF1B5B5C50E978#第02集$id_XS0722BA80EF1B5B5C50E97B#第03集$id_XS0722BA80EF1B5B5C50E97A#第04集$id_XS0722BA80EF1B5B5C50E97D#第05集$id_XS0722BA80EF1B5B5C50E97C#第06集$id_XS0722BA80EF1B5B5C50E97F#第07集$id_XS0722BA80EF1B5B5C50E97E#第08集$id_XS0722BA80EF1B5B5C50E971#第09集$id_XS0722BA80EF1B5B5C50E970#第10集$id_XS0722BA80EF1B5B5C50E879#第11集$id_XS0722BA80EF1B5B5C50E878#第12集$id_XS0722BA80EF1B5B5C50E87B$$$第01集$id_MOE0722BA80EF1B5B5C50E978#第02集$id_MOE0722BA80EF1B5B5C50E97B#第03集$id_MOE0722BA80EF1B5B5C50E97A#第04集$id_MOE0722BA80EF1B5B5C50E97D#第05集$id_MOE0722BA80EF1B5B5C50E97C#第06集$id_MOE0722BA80EF1B5B5C50E97F#第07集$id_MOE0722BA80EF1B5B5C50E97E#第08集$id_MOE0722BA80EF1B5B5C50E971#第09集$id_MOE0722BA80EF1B5B5C50E970#第10集$id_MOE0722BA80EF1B5B5C50E879#第11集$id_MOE0722BA80EF1B5B5C50E878#第12集$id_MOE0722BA80EF1B5B5C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1096, 1, 0, 0, '一个人的〇〇小日子', 'ひとりぼっちの○○生活（2019）', 'yigerendexiaorizi', 1, 'Y', '', '7231ab52', '漫画改,日常,萌系,校园', 'http://i0.hdslb.com/bfs/bangumi/a3b2db2edeeac4fb51446724458cf93fe46d2797.jpg', '', '', '', '森下千咲 / 田中美海 / 鬼头明里 / 黑濑裕子 / 市之濑加那 / 小原好美 / 高桥未奈美', '安斋刚文 / 池下博纪 / 长滨亘彦 / 清水一伸', '', '', '极度怕生的少女一里波知，在小学时就只有一位朋友，就是这仅有的一位朋友，和波知定下了约定「波知要在中学毕业前和全班同学成为朋友」如果做不到的话就和波知绝交？！但是，一紧张就迈不开步子，无法面对他人视线的', '全12集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 9.6, 0, 0, 1740363704, 1740309522, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>极度怕生的少女一里波知，在小学时就只有一位朋友，就是这仅有的一位朋友，和波知定下了约定「波知要在中学毕业前和全班同学成为朋友」如果做不到的话就和波知绝交？！但是，一紧张就迈不开步子，无法面对他人视线的波知，做不到主动和人谈话。在之前，甚至连交朋友的方法都不知道，波知的交友作战总是伴随着小小的意外和失败，她真的能够成功交到朋友吗。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0625BF89E84B580B50E978#第02集$MOE0625BF89E84B580B50E97B#第03集$MOE0625BF89E84B580B50E97A#第04集$MOE0625BF89E84B580B50E97D#第05集$MOE0625BF89E84B580B50E97C#第06集$MOE0625BF89E84B580B50E97F#第07集$MOE0625BF89E84B580B50E97E#第08集$MOE0625BF89E84B580B50E971#第09集$MOE0625BF89E84B580B50E970#第10集$MOE0625BF89E84B580B50E879#第11集$MOE0625BF89E84B580B50E878#第12集$MOE0625BF89E84B580B50E87B$$$第01集$id_XS0625BF89E84B580B50E978#第02集$id_XS0625BF89E84B580B50E97B#第03集$id_XS0625BF89E84B580B50E97A#第04集$id_XS0625BF89E84B580B50E97D#第05集$id_XS0625BF89E84B580B50E97C#第06集$id_XS0625BF89E84B580B50E97F#第07集$id_XS0625BF89E84B580B50E97E#第08集$id_XS0625BF89E84B580B50E971#第09集$id_XS0625BF89E84B580B50E970#第10集$id_XS0625BF89E84B580B50E879#第11集$id_XS0625BF89E84B580B50E878#第12集$id_XS0625BF89E84B580B50E87B$$$第01集$id_MOE0625BF89E84B580B50E978#第02集$id_MOE0625BF89E84B580B50E97B#第03集$id_MOE0625BF89E84B580B50E97A#第04集$id_MOE0625BF89E84B580B50E97D#第05集$id_MOE0625BF89E84B580B50E97C#第06集$id_MOE0625BF89E84B580B50E97F#第07集$id_MOE0625BF89E84B580B50E97E#第08集$id_MOE0625BF89E84B580B50E971#第09集$id_MOE0625BF89E84B580B50E970#第10集$id_MOE0625BF89E84B580B50E879#第11集$id_MOE0625BF89E84B580B50E878#第12集$id_MOE0625BF89E84B580B50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1097, 1, 0, 0, '丹特丽安的书架', 'ダンタリアンの書架（2011）', 'danteliandeshujia', 1, 'D', '', '6c01745d', '奇幻,治愈,声控,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/cb7f3f5082bc540404f41df5c628b963ab63cc38.jpg', '', '', '', '小野大辅 / 泽城美雪 / 小清水亚美 / 加藤将之 / 能登麻美子 / 樱井孝宏 / 四宫豪 / 矢作纱友里 / 小林由美子 / 花泽香菜', '上村泰 / 小林治 / 村田雅彦 / 立川让', '', '', '【本字幕由诸神双语字幕组协力译制】青年修伊从收书狂的祖父那里继承了古老的宅邸以及其所有的藏书，条件只有一个——要他继承“书架”。\r\n为整理遗物而造访宅邸的修伊在充斥着书本的地下室内，遇见了身穿黑裙、胸前', '全12集', '', 0, '0', '', '', '日本', '日语', '2011', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.7, 0, 0, 1740372934, 1740309530, 0, 0, 0, 0, 0.0, '', '1098', '', '', '', '', '', '', '', '<p>【本字幕由诸神双语字幕组协力译制】青年修伊从收书狂的祖父那里继承了古老的宅邸以及其所有的藏书，条件只有一个——要他继承“书架”。\r\n为整理遗物而造访宅邸的修伊在充斥着书本的地下室内，遇见了身穿黑裙、胸前挂着巨锁的少女丹特丽安。她正是通往藏有禁断“幻书”的“丹特丽安的书架”的入口，储藏着恶魔智慧的门扉……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0774BC89BE1D585D50E978#第02集$MOE0774BC89BE1D585D50E97B#第03集$MOE0774BC89BE1D585D50E97A#第04集$MOE0774BC89BE1D585D50E97D#第05集$MOE0774BC89BE1D585D50E97C#第06集$MOE0774BC89BE1D585D50E97F#第07集$MOE0774BC89BE1D585D50E97E#第08集$MOE0774BC89BE1D585D50E971#第09集$MOE0774BC89BE1D585D50E970#第10集$MOE0774BC89BE1D585D50E879#第11集$MOE0774BC89BE1D585D50E878#第12集$MOE0774BC89BE1D585D50E87B$$$第01集$id_XS0774BC89BE1D585D50E978#第02集$id_XS0774BC89BE1D585D50E97B#第03集$id_XS0774BC89BE1D585D50E97A#第04集$id_XS0774BC89BE1D585D50E97D#第05集$id_XS0774BC89BE1D585D50E97C#第06集$id_XS0774BC89BE1D585D50E97F#第07集$id_XS0774BC89BE1D585D50E97E#第08集$id_XS0774BC89BE1D585D50E971#第09集$id_XS0774BC89BE1D585D50E970#第10集$id_XS0774BC89BE1D585D50E879#第11集$id_XS0774BC89BE1D585D50E878#第12集$id_XS0774BC89BE1D585D50E87B$$$第01集$id_MOE0774BC89BE1D585D50E978#第02集$id_MOE0774BC89BE1D585D50E97B#第03集$id_MOE0774BC89BE1D585D50E97A#第04集$id_MOE0774BC89BE1D585D50E97D#第05集$id_MOE0774BC89BE1D585D50E97C#第06集$id_MOE0774BC89BE1D585D50E97F#第07集$id_MOE0774BC89BE1D585D50E97E#第08集$id_MOE0774BC89BE1D585D50E971#第09集$id_MOE0774BC89BE1D585D50E970#第10集$id_MOE0774BC89BE1D585D50E879#第11集$id_MOE0774BC