INSERT INTO `mac_vod` VALUES (1098, 1, 0, 0, '丹特丽安的书架 OVA 荆姬', 'ダンタリアンの書架 荊姫（2011）', 'danteliandeshujiaOVAjingji', 1, 'D', '', '9f8366fe', '奇幻,战斗,悬疑', 'http://i0.hdslb.com/bfs/bangumi/63414486f19572acf8cb9778363c65b7b2afd7fd.jpg', '', '', '', '小野大辅 Daisuke Ono / 泽城美雪 Miyuki Sawashiro', '上村泰', '', '', '《丹特丽安的书架》漫画第五卷2012年8月11日与OAD「荆姬」同捆发售。\r\n这张DVD所收录的内容是TV未播放的原创故事《荆姬》，讲述幻书“深绿之书”的所有者——约翰·卡拉波斯爵士因遭遇火灾而死亡，人', 'OVA', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 9.7, 0, 0, 1740375521, 1740363730, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《丹特丽安的书架》漫画第五卷2012年8月11日与OAD「荆姬」同捆发售。\r\n这张DVD所收录的内容是TV未播放的原创故事《荆姬》，讲述幻书“深绿之书”的所有者——约翰·卡拉波斯爵士因遭遇火灾而死亡，人们根据情报认为这本书已经和房屋一起烧毁了。前往卡拉波斯爵士领地的达利安和修伊在森林中迷路了，这时他们遇见一名女性药草师，帮助他们摆脱了困境。据说约翰·卡拉波斯还有个女儿滞留在附近的别墅，但……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE0871B48BBF1F0B5C50E978$$$OVA$id_XS0871B48BBF1F0B5C50E978$$$OVA$id_MOE0871B48BBF1F0B5C50E978', '', '', '', '', 0, '', '');
