INSERT INTO `mac_vod` VALUES (1104, 1, 0, 0, '重装武器', 'ヘヴィーオブジェクト（2015）', 'zhongzhuangwuqi', 1, 'Z', '', '6bc7b6d1', '热血,机战,科幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/dda7ab354eef4e9fedc299af313faccbfd1276e3.jpg', '', '', '', '花江夏树 / 石川界人 / 铃木绘理 / 伊藤静 / 内田真礼 / 横尾麻里 / 松本忍 / 山下大辉 / 芳野由奈 / 山本格 / 本渡枫 / 竹内良太 / 高桥未奈美 / 小西克幸 / 内匠靖明 / 大西沙织 / 小山力也 / 大林隆介 / 大久保瑠美 / 金元寿子 / 佐藤利奈 / 新井里美 / 细谷佳正 / 菅生隆之 / 木村珠莉 / 叶山郁美 / 中津真莉 / 水濑祈 / 辻亲八 / 斧笃 / 柳田淳一 / 手冢宏通 / Lynn / 千本木彩花 / 村中知 / 山崎遥 / 绫濑有 / 森奈奈子', '渡部高志 / 樱井亲良 / 则座诚 / 岩崎良明 / 铃木健太郎 / 五月女浩一朗 / 佐佐木纯人 / 筱原正宽 / 桥本敏一 / 奥野浩行 / 森义博 / 高岛大辅 / 铃木洋平', '', '', '《重装武器》（ヘヴィーオブジェクト）是镰池和马继轻小说《魔法禁书目录》后的又一作品，讲述的是少年库温瑟与好友贺维亚，两人与使用超大型兵器“重装武器”的少女相遇，一起战斗的故事。\r\n小说于2009年10月', '全24集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.3, 0, 0, 1740415308, 1740386249, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《重装武器》（ヘヴィーオブジェクト）是镰池和马继轻小说《魔法禁书目录》后的又一作品，讲述的是少年库温瑟与好友贺维亚，两人与使用超大型兵器“重装武器”的少女相遇，一起战斗的故事。\r\n小说于2009年10月开始由电击文库刊行，ASCII MEDIA WORKS（现角川公司KADOKAWA旗下出版厂牌）出版。此外，的漫画版于2009年12月17日开始连载。2014年十月，电击文库秋之祭奠宣布《重装武器》动画化。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0775EF8FEB1F090850E978#第02集$MOE0775EF8FEB1F090850E97B#第03集$MOE0775EF8FEB1F090850E97A#第04集$MOE0775EF8FEB1F090850E97D#第05集$MOE0775EF8FEB1F090850E97C#第06集$MOE0775EF8FEB1F090850E97F#第07集$MOE0775EF8FEB1F090850E97E#第08集$MOE0775EF8FEB1F090850E971#第09集$MOE0775EF8FEB1F090850E970#第10集$MOE0775EF8FEB1F090850E879#第11集$MOE0775EF8FEB1F090850E878#第12集$MOE0775EF8FEB1F090850E87B#第13集$MOE0775EF8FEB1F090850E87A#第14集$MOE0775EF8FEB1F090850E87D#第15集$MOE0775EF8FEB1F090850E87C#第16集$MOE0775EF8FEB1F090850E87F#第17集$MOE0775EF8FEB1F090850E87E#第18集$MOE0775EF8FEB1F090850E871#第19集$MOE0775EF8FEB1F090850E870#第20集$MOE0775EF8FEB1F090850EB79#第21集$MOE0775EF8FEB1F090850EB78#第22集$MOE0775EF8FEB1F090850EB7B#第23集$MOE0775EF8FEB1F090850EB7A#第24集$MOE0775EF8FEB1F090850EB7D$$$第01集$id_XS0775EF8FEB1F090850E978#第02集$id_XS0775EF8FEB1F090850E97B#第03集$id_XS0775EF8FEB1F090850E