INSERT INTO `mac_vod` VALUES (1105, 1, 0, 0, '猫娘乐园', 'ネコぱら（2020）', 'maoniangleyuan', 1, 'M', '', '60c362a', '游戏改,日常,治愈,萌系', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2611987879.jpg', '', '', '', '八木侑纪 / 佐伯伊织 / 井泽诗织 / 伊藤美来 / 野口百合 / 水谷麻铃 / 市道真央 / 立花慎之介 / 森岛优花', '山本靖贵', '', '', '水无月嘉祥（立花慎之介 配音）出生于一个非常传统的日式糕点世家之中，但他真正想要制作的，却是精美的西式点心。为了实现自己的梦想，水无月嘉祥离开了故乡，并且创立了自己的品牌La Soleil，成为了店里', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 7.4, 0, 0, 1740460554, 1740387758, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>水无月嘉祥（立花慎之介 配音）出生于一个非常传统的日式糕点世家之中，但他真正想要制作的，却是精美的西式点心。为了实现自己的梦想，水无月嘉祥离开了故乡，并且创立了自己的品牌La Soleil，成为了店里的店长兼糕点师。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0727EF8BBF1B0C144DE8#第02集$MOE0727EF8BBF1B0C144DEB#第03集$MOE0727EF8BBF1B0C144DEA#第04集$MOE0727EF8BBF1B0C144DED#第05集$MOE0727EF8BBF1B0C144DEC#第06集$MOE0727EF8BBF1B0C144DEF#第07集$MOE0727EF8BBF1B0C144DEE#第08集$MOE0727EF8BBF1B0C144DE1#第09集$MOE0727EF8BBF1B0C144DE0#第10集$MOE0727EF8BBF1B0C144CE9#第11集$MOE0727EF8BBF1B0C144CE8#第12集$MOE0727EF8BBF1B0C144CEB$$$第01集$id_XS0727EF8BBF1B0C144DE8#第02集$id_XS0727EF8BBF1B0C144DEB#第03集$id_XS0727EF8BBF1B0C144DEA#第04集$id_XS0727EF8BBF1B0C144DED#第05集$id_XS0727EF8BBF1B0C144DEC#第06集$id_XS0727EF8BBF1B0C144DEF#第07集$id_XS0727EF8BBF1B0C144DEE#第08集$id_XS0727EF8BBF1B0C144DE1#第09集$id_XS0727EF8BBF1B0C144DE0#第10集$id_XS0727EF8BBF1B0C144CE9#第11集$id_XS0727EF8BBF1B0C144CE8#第12集$id_XS0727EF8BBF1B0C144CEB$$$第01集$id_MOE0727EF8BBF1B0C144DE8#第02集$id_MOE0727EF8BBF1B0C144DEB#第03集$id_MOE0727EF8BBF1B0C144DEA#第04集$id_MOE0727EF8BBF1B0C144DED#第05集$id_MOE0727EF8BBF1B0C144DEC#第06集$id_MOE0727EF8BBF1B0C144DEF#第07集$id_MOE0727EF8BBF1B0C144DEE#第08集$id_MOE0727EF8BBF1B0C144DE1#第09集$id_MOE0727EF8BBF1B0C144DE0#第10集$id_MOE0727EF8BBF1B0C144CE9#第11集$id_MOE0727EF8BBF1B0C144CE8#第12集$id_MOE0727EF8BBF1B0C144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1106, 2, 0, 0, '巧克力与香子兰', 'ネコぱらOVA（2017）', 'qiaokeliyuxiangzilan', 1, 'Q', '', 'e42baaa9', '游戏改,日常,治愈,萌系', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2508886707.jpg', '', '', '', '立花慎之介 / 朋永真季 / 猪口有佳 / 永井真衣 / 成濑未亚 / 小仓结衣 / 冈岛妙 / 立石めぐみ', '林宏樹', '', '', 'OVA动画《巧克力与香子兰》的故事讲述了男主角水无月嘉祥离开了传统日本点心老铺的老家，以西式糕点师的身份经营着一家名为“La Soleil”的蛋糕店。然而在老家寄来的行李中，人形猫巧克力和香子兰混入其', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 5.7, 0, 0, 1740460648, 1740387852, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>OVA动画《巧克力与香子兰》的故事讲述了男主角水无月嘉祥离开了传统日本点心老铺的老家，以西式糕点师的身份经营着一家名为“La Soleil”的蛋糕店。然而在老家寄来的行李中，人形猫巧克力和香子兰混入其中。虽然嘉祥想把她们送回老家，但在她们的恳求下还是把两只喵娘留了下来，于是一个人和两只猫一起经营起“La Soleil”来。</p>', 'xs$$$moe', 'no$$$no', '$$$', 'OVA$id_XS5423BEDAE8480C0050E978$$$OVA$id_MOE5423BEDAE8480C0050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1107, 1, 0, 0, '巧克力与香子兰OVA小猫之日的约定', 'ネコぱら OVA 仔ネコの日の約束（2018）', 'qiaokeliyuxiangzilanOVAxiaomaozhirideyueding', 1, 'Q', '', '6a52ab53', '游戏改,日常,治愈,萌系', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2535307835.jpg', '', '', '', '立花慎之介 / 朋永真季 / 猪口有佳 / 永井真衣 / 成濑未亚 / 小仓结衣 / 冈岛妙 / 立石めぐみ', '山本靖貴', '', '', '时间回到嘉祥担任店长的猫娘蛋糕店『La Soleil』开张的半年前，还是小猫的巧克力跟香草刚来到水无月家，还没跟其他猫娘们打成一片的时候。开始用「主人」称呼嘉祥，并且在水无月家度过第一个圣诞节的两人，', 'OVA', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 7.6, 0, 0, 1740460727, 1740387858, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>时间回到嘉祥担任店长的猫娘蛋糕店『La Soleil』开张的半年前，还是小猫的巧克力跟香草刚来到水无月家，还没跟其他猫娘们打成一片的时候。开始用「主人」称呼嘉祥，并且在水无月家度过第一个圣诞节的两人，和嘉祥立下了一个约定。NekoparaOVA的募资达标感谢礼，将为各位送上一段全新前传！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE0776B98AE84B580A50E978$$$OVA$id_XS0776B98AE84B580A50E978$$$OVA$id_MOE0776B98AE84B580A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1108, 1, 0, 0, '棺姬嘉依卡', '棺姫のチャイカ（2014）', 'guanjijiayika', 1, 'G', '', '91293ab4', '奇幻,架空', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2175616088.jpg', '', '', '', '安济知佳 / 间岛淳司 / 原优子 / 斋藤千和 / 细谷佳正 / 佐藤健辅 / 野水伊织 / 幸田梦波 / 森嵨秀太 / 山本和臣', '増井壮一', '', '', '故事发生在大陆历一六零四年，持续了三个世纪的漫长战争终于画上了终点，整片菲尔毕斯特大陆哀鸿遍野，满目疮痍。托鲁（间岛淳司 配音）和阿卡丽（原优子 配音）虽然没有血缘关系，却结为了义兄妹，两人相互扶持经', '全12集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 6.9, 0, 0, 1740467024, 1740415348, 0, 0, 0, 0, 0.0, '', '1109,1110', '', '', '', '', '', '', '', '<p>故事发生在大陆历一六零四年，持续了三个世纪的漫长战争终于画上了终点，整片菲尔毕斯特大陆哀鸿遍野，满目疮痍。托鲁（间岛淳司 配音）和阿卡丽（原优子 配音）虽然没有血缘关系，却结为了义兄妹，两人相互扶持经历了残酷的战争，彼此之间结下了深深的羁绊。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0826BE81BA480F0D50E978#第02集$MOE0826BE81BA480F0D50E97B#第03集$MOE0826BE81BA480F0D50E97A#第04集$MOE0826BE81BA480F0D50E97D#第05集$MOE0826BE81BA480F0D50E97C#第06集$MOE0826BE81BA480F0D50E97F#第07集$MOE0826BE81BA480F0D50E97E#第08集$MOE0826BE81BA480F0D50E971#第09集$MOE0826BE81BA480F0D50E970#第10集$MOE0826BE81BA480F0D50E879#第11集$MOE0826BE81BA480F0D50E878#第12集$MOE0826BE81BA480F0D50E87B$$$第01集$id_XS0826BE81BA480F0D50E978#第02集$id_XS0826BE81BA480F0D50E97B#第03集$id_XS0826BE81BA480F0D50E97A#第04集$id_XS0826BE81BA480F0D50E97D#第05集$id_XS0826BE81BA480F0D50E97C#第06集$id_XS0826BE81BA480F0D50E97F#第07集$id_XS0826BE81BA480F0D50E97E#第08集$id_XS0826BE81BA480F0D50E971#第09集$id_XS0826BE81BA480F0D50E970#第10集$id_XS0826BE81BA480F0D50E879#第11集$id_XS0826BE81BA480F0D50E878#第12集$id_XS0826BE81BA480F0D50E87B$$$第01集$id_MOE0826BE81BA480F0D50E978#第02集$id_MOE0826BE81BA480F0D50E97B#第03集$id_MOE0826BE81BA480F0D50E97A#第04集$id_MOE0826BE81BA480F0D50E97D#第05集$id_MOE0826BE81BA480F0D50E97C#第06集$id_MOE0826BE81BA480F0D50E97F#第07集$id_MOE0826BE81BA480F0D50E97E#第08集$id_MOE0826BE81BA480F0D50E971#第09集$id_MOE0826BE81BA480F0D50E970#第10集$id_MOE0826BE81BA480F0D50E879#第11集$id_MOE0826BE81BA480F0D50E878#第12集$id_MOE0826BE81BA480F0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1109, 1, 0, 0, '棺姬嘉依卡 第二季', '棺姫のチャイカ AVENGING BATTLE（2014）', 'guanjijiayikadierji', 1, 'G', '', '979fcbb8', '奇幻,架空', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204392975.jpg', '', '', '', '安济知佳 / 间岛淳司 / 原优子 / 斋藤千和 / 细谷佳正', '增井壮一', '', '', '大陆历一六零四年，在菲尔毕斯特大陆实际已经延续了三世纪的战国时代以北方霸主贾兹帝国的崩坏迎来了终结。投入的兵力包括正规的骑士及士兵，魔法师及乱破师，佣兵团在内实际六十二万，还包括航天要塞三座在内的大量', '全10集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 1, 0, 1, 1, '', 0, 0, 7.0, 0, 0, 1740473526, 1740415356, 0, 0, 0, 0, 0.0, '', '1110', '', '', '', '', '', '', '', '<p>大陆历一六零四年，在菲尔毕斯特大陆实际已经延续了三世纪的战国时代以北方霸主贾兹帝国的崩坏迎来了终结。投入的兵力包括正规的骑士及士兵，魔法师及乱破师，佣兵团在内实际六十二万，还包括航天要塞三座在内的大量魔法兵器，弃兽兵团，天龙骑兵队等特殊战力也毫无保留的被派出，彻底地将被称为“万恶的根源”的这个贾兹帝国歼灭。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0820B5DEEA4B0F0150E978#第02集$MOE0820B5DEEA4B0F0150E97B#第03集$MOE0820B5DEEA4B0F0150E97A#第04集$MOE0820B5DEEA4B0F0150E97D#第05集$MOE0820B5DEEA4B0F0150E97C#第06集$MOE0820B5DEEA4B0F0150E97F#第07集$MOE0820B5DEEA4B0F0150E97E#第08集$MOE0820B5DEEA4B0F0150E971#第09集$MOE0820B5DEEA4B0F0150E970#第10集$MOE0820B5DEEA4B0F0150E879$$$第01集$id_XS0820B5DEEA4B0F0150E978#第02集$id_XS0820B5DEEA4B0F0150E97B#第03集$id_XS0820B5DEEA4B0F0150E97A#第04集$id_XS0820B5DEEA4B0F0150E97D#第05集$id_XS0820B5DEEA4B0F0150E97C#第06集$id_XS0820B5DEEA4B0F0150E97F#第07集$id_XS0820B5DEEA4B0F0150E97E#第08集$id_XS0820B5DEEA4B0F0150E971#第09集$id_XS0820B5DEEA4B0F0150E970#第10集$id_XS0820B5DEEA4B0F0150E879$$$第01集$id_MOE0820B5DEEA4B0F0150E978#第02集$id_MOE0820B5DEEA4B0F0150E97B#第03集$id_MOE0820B5DEEA4B0F0150E97A#第04集$id_MOE0820B5DEEA4B0F0150E97D#第05集$id_MOE0820B5DEEA4B0F0150E97C#第06集$id_MOE0820B5DEEA4B0F0150E97F#第07集$id_MOE0820B5DEEA4B0F0150E97E#第08集$id_MOE0820B5DEEA4B0F0150E971#第09集$id_MOE0820B5DEEA4B0F0150E970#第10集$id_MOE0820B5DEEA4B0F0150E879', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1110, 1, 0, 0, '棺姬嘉依卡 OVA', '棺姫のチャイカ OVA（2015）', 'guanjijiayikaOVA', 1, 'G', '', '6f28b4b9', '奇幻,架空', 'http://i0.hdslb.com/bfs/bangumi/e14f1e14d2fd7fc0ff70c9330230adb6d79ea5a7.jpg', '', '', '', '安济知佳 / 间岛淳司 / 原優子 / 斋藤千和 / 佐藤健輔 / 细谷佳正 / 野水伊织 / 幸田夢波 / 森岛秀太 / 山本和臣 / 藏合紗恵子', '増井壮一', '', '', 'TV未放送1话OVA同捆小说12卷限定版。', 'OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.4, 0, 0, 1740473614, 1740460937, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>TV未放送1话OVA同捆小说12卷限定版。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE0771BE80EB1D0F0050E978$$$OVA$id_XS0771BE80EB1D0F0050E978$$$OVA$id_MOE0771BE80EB1D0F0050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1111, 1, 0, 0, '天地创造设计部', '天地創造デザイン部（2021）', 'tiandichuangzaoshejibu', 1, 'T', '', '6fe04dcd', '漫画改,奇幻,搞笑', 'http://i0.hdslb.com/bfs/bangumi/image/10c54e07c8a63afe1623c84a89a01df0535c7481.png', '', '', '', '榎木淳弥 / 原由实 / 井上和彦 / 梅原裕一郎 / 诹访部顺一 / 岸尾大辅 / 大空直美 / 竹内良太 / 泊明日菜 / 木野日菜 / 逢坂良太 / 水岛大宙 / 龙田直树', '增井壮一', '', '', '起初，神创造天地。\r\n万能的神，创造了一切。\r\n\r\n创造光、水、大地——\r\n接下来创造住在那里的生物，动物——\r\n虽然是这么想的，但觉得太麻烦于是就委托外包了…!?\r\n\r\n受到神（客户）的委托创造生物的天地创造社。', '全13集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.5, 0, 0, 1740503765, 1740461009, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>起初，神创造天地。\r\n万能的神，创造了一切。\r\n\r\n创造光、水、大地——\r\n接下来创造住在那里的生物，动物——\r\n虽然是这么想的，但觉得太麻烦于是就委托外包了…!?\r\n\r\n受到神（客户）的委托创造生物的天地创造社。\r\n地面上存在的生物，由天地创造社的设计师们创造出来。\r\n\r\n这种生物，为什么是这个样子的呢？\r\n这种生物，为什么有这样的生态呢？\r\n\r\n生物诞生的背后，是将神乱来的委托以独创的点子来实现的设计师和工程师们苦恼而欢喜的戏剧！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0771E988BD4D0E5D50E978#第02集$MOE0771E988BD4D0E5D50E97B#第03集$MOE0771E988BD4D0E5D50E97A#第04集$MOE0771E988BD4D0E5D50E97D#第05集$MOE0771E988BD4D0E5D50E97C#第06集$MOE0771E988BD4D0E5D50E97F#第07集$MOE0771E988BD4D0E5D50E97E#第08集$MOE0771E988BD4D0E5D50E971#第09集$MOE0771E988BD4D0E5D50E970#第10集$MOE0771E988BD4D0E5D50E879#第11集$MOE0771E988BD4D0E5D50E878#第12集$MOE0771E988BD4D0E5D50E87B#第13集$MOE0771E988BD4D0E5D50E87A$$$第01集$id_XS0771E988BD4D0E5D50E978#第02集$id_XS0771E988BD4D0E5D50E97B#第03集$id_XS0771E988BD4D0E5D50E97A#第04集$id_XS0771E988BD4D0E5D50E97D#第05集$id_XS0771E988BD4D0E5D50E97C#第06集$id_XS0771E988BD4D0E5D50E97F#第07集$id_XS0771E988BD4D0E5D50E97E#第08集$id_XS0771E988BD4D0E5D50E971#第09集$id_XS0771E988BD4D0E5D50E970#第10集$id_XS0771E988BD4D0E5D50E879#第11集$id_XS0771E988BD4D0E5D50E878#第12集$id_XS0771E988BD4D0E5D50E87B#第13集$id_XS0771E988BD4D0E5D50E87A$$$第01集$id_MOE0771E988BD4D0E5D50E978#第02集$id_MOE0771E988BD4D0E5D50E97B#第03集$id_MOE0771E988BD4D0E5D50E97A#第04集$id_MOE0771E988BD4D0E5D50E97D#第05集$id_MOE0771E988BD4D0E5D50E97C#第06集$id_MOE0771E988BD4D0E5D50E97F#第07集$id_MOE0771E988BD4D0E5D50E97E#第08集$id_MOE0771E988BD4D0E5D50E971#第09集$id_MOE0771E988BD4D0E5D50E970#第10集$id_MOE0771E988BD4D0E5D50E879#第11集$id_MOE0771E988BD4D0E5D50E878#第12集$id_MOE0771E988BD4D0E5D50E87B#第13集$id_MOE0771E988BD4D0E5D50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1112, 1, 0, 0, '百炼霸王与圣约女武神', '百錬の覇王と聖約の戦乙女（2018）', 'bailianbawangyushengyuenvwushen', 1, 'B', '', '297c0d5a', '小说改,奇幻,战斗,架空', 'http://i0.hdslb.com/bfs/bangumi/a36c510217610bf3e8486b3b02c7d3db1a6b288c.jpg', '', '', '', '酒井广大 / 末柄里惠 / 伊达朱里纱 / 河濑茉希 / 高尾奏音 / 内田彩', '小林浩輔', '', '', '来自现代的少年周防勇斗，他误闯到战乱中的黎明世界「攸格多拉西尔」。\r\n这是一个弱肉强食的世界，许多氏族彼此争夺霸权，勇斗则以现代知识为武器，仅仅十六岁便登上统领千军万马的宗主之位。\r\n一位普通的少年在异世', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 6.2, 0, 0, 1740480563, 1740461025, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>来自现代的少年周防勇斗，他误闯到战乱中的黎明世界「攸格多拉西尔」。\r\n这是一个弱肉强食的世界，许多氏族彼此争夺霸权，勇斗则以现代知识为武器，仅仅十六岁便登上统领千军万马的宗主之位。\r\n一位普通的少年在异世界里称王称霸，同时还有与其缔结誓杯契约、宣誓忠诚不二之心的美丽女武神们围在身边——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE032EBBDBB94D585850E978#第02集$MOE032EBBDBB94D585850E97B#第03集$MOE032EBBDBB94D585850E97A#第04集$MOE032EBBDBB94D585850E97D#第05集$MOE032EBBDBB94D585850E97C#第06集$MOE032EBBDBB94D585850E97F#第07集$MOE032EBBDBB94D585850E97E#第08集$MOE032EBBDBB94D585850E971#第09集$MOE032EBBDBB94D585850E970#第10集$MOE032EBBDBB94D585850E879#第11集$MOE032EBBDBB94D585850E878#第12集$MOE032EBBDBB94D585850E87B$$$第01集$id_XS032EBBDBB94D585850E978#第02集$id_XS032EBBDBB94D585850E97B#第03集$id_XS032EBBDBB94D585850E97A#第04集$id_XS032EBBDBB94D585850E97D#第05集$id_XS032EBBDBB94D585850E97C#第06集$id_XS032EBBDBB94D585850E97F#第07集$id_XS032EBBDBB94D585850E97E#第08集$id_XS032EBBDBB94D585850E971#第09集$id_XS032EBBDBB94D585850E970#第10集$id_XS032EBBDBB94D585850E879#第11集$id_XS032EBBDBB94D585850E878#第12集$id_XS032EBBDBB94D585850E87B$$$第01集$id_MOE032EBBDBB94D585850E978#第02集$id_MOE032EBBDBB94D585850E97B#第03集$id_MOE032EBBDBB94D585850E97A#第04集$id_MOE032EBBDBB94D585850E97D#第05集$id_MOE032EBBDBB94D585850E97C#第06集$id_MOE032EBBDBB94D585850E97F#第07集$id_MOE032EBBDBB94D585850E97E#第08集$id_MOE032EBBDBB94D585850E971#第09集$id_MOE032EBBDBB94D585850E970#第10集$id_MOE032EBBDBB94D585850E879#第11集$id_MOE032EBBDBB94D585850E878#第12集$id_MOE032EBBDBB94D58585