INSERT INTO `mac_vod` VALUES (1114, 1, 0, 0, '晨曦公主 OAD', '暁のヨナ その背には（2015）', 'chenxigongzhuOAD', 1, 'C', '', 'f41b0039', '奇幻,少女,架空', 'http://i0.hdslb.com/bfs/bangumi/b95c479393294b8e256483703fbd3c7dea0dc7ac.jpg', '', '', '', '斋藤千和 / 前野智昭 / 森田成一 / 冈本信彦 / 诹访部顺一 / 下野纮 / 皆川纯子', '米田和弘', '', '', '单行本第19卷、第21卷和第22卷限定版同捆DVD。', 'OAD', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 9.8, 0, 0, 1740498882, 1740494248, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>单行本第19卷、第21卷和第22卷限定版同捆DVD。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5723BDDAB9195E0050E978#第02集$MOE5723BDDAB9195E0050E97B#第03集$MOE5723BDDAB9195E0050E97A$$$第01集$id_XS5723BDDAB9195E0050E978#第02集$id_XS5723BDDAB9195E0050E97B#第03集$id_XS5723BDDAB9195E0050E97A$$$第01集$id_MOE5723BDDAB9195E0050E978#第02集$id_MOE5723BDDAB9195E0050E97B#第03集$id_MOE5723BDDAB9195E0050E97A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1115, 1, 0, 0, '苍之彼方的四重奏', '蒼の彼方のフォーリズム（2016）', 'cangzhibifangdesizhongzou', 1, 'C', '', '30c6df53', '奇幻,运动,游戏改', 'http://i0.hdslb.com/bfs/bangumi/fa218bbc1f73d86824dddb3048691058a82ccf25.jpg', '', '', '', '福圆美里 / 浅仓杏美 / 山本希望 / 米泽圆 / 逢坂良太 / 若林直美 / 近藤孝行 / 种田梨沙 / 兴津和幸 / 仪武祐子 / 绪方惠美 / 高森奈津美 / 水桥香织 / 生天目仁美', '追崎史敏 / 筑紫大介 / 村田光 / 鸟羽聪 / 西村博昭 / 高桥幸雄', '', '', '这是个因「反重力鞋」的问世，人人都能轻而易举地翱翔天空的世界。转校至久奈浜学院的仓科明日香，与新的同学鸢泽美咲、日向晶也相遇，得知了穿着「反重力鞋」竞技的比赛项目「Flying Circus」（简称F', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 7.4, 0, 0, 1740532155, 1740499135, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是个因「反重力鞋」的问世，人人都能轻而易举地翱翔天空的世界。转校至久奈浜学院的仓科明日香，与新的同学鸢泽美咲、日向晶也相遇，得知了穿着「反重力鞋」竞技的比赛项目「Flying Circus」（简称FC）。迷上这项运动的明日香决意加入久奈浜学院的「FC部」，与其他伙伴一起挥洒青春的汗水。她们互帮互助，共同成长，向强力的对手发起挑战。目标——夏季大赛！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0227EF8EED4F580A50E978#第02集$MOE0227EF8EED4F580A50E97B#第03集$MOE0227EF8EED4F580A50E97A#第04集$MOE0227EF8EED4F580A50E97D#第05集$MOE0227EF8EED4F580A50E97C#第06集$MOE0227EF8EED4F580A50E97F#第07集$MOE0227EF8EED4F580A50E97E#第08集$MOE0227EF8EED4F580A50E971#第09集$MOE0227EF8EED4F580A50E970#第10集$MOE0227EF8EED4F580A50E879#第11集$MOE0227EF8EED4F580A50E878#第12集$MOE0227EF8EED4F580A50E87B$$$第01集$id_XS0227EF8EED4F580A50E978#第02集$id_XS0227EF8EED4F580A50E97B#第03集$id_XS0227EF8EED4F580A50E97A#第04集$id_XS0227EF8EED4F580A50E97D#第05集$id_XS0227EF8EED4F580A50E97C#第06集$id_XS0227EF8EED4F580A50E97F#第07集$id_XS0227EF8EED4F580A50E97E#第08集$id_XS0227EF8EED4F580A50E971#第09集$id_XS0227EF8EED4F580A50E970#第10集$id_XS0227EF8EED4F580A50E879#第11集$id_XS0227EF8EED4F580A50E878#第12集$id_XS0227EF8EED4F580A50E87B$$$第01集$id_MOE0227EF8EED4F580A50E978#第02集$id_MOE0227EF8EED4F580A50E97B#第03集$id_MOE0227EF8EED4F580A50E97A#第04集$id_MOE0227EF8EED4F580A50E97D#第05集$id_MOE0227EF8EED4F580A50E97C#第06集$id_MOE0227EF8EED4F580A50E97F#第07集$id_MOE0227EF8EED4F580A50E97E#第08集$id_MOE0227EF8EED4F580A50E971#第09集$id_MOE0227EF8EED4F580