INSERT INTO `mac_vod` VALUES (1117, 1, 0, 0, '粗点心战争', 'だがしかし（2016）', 'cudianxinzhanzheng', 1, 'C', '', '5a8eaa8c', '日常,搞笑,美食', 'http://i0.hdslb.com/bfs/bangumi/59c494b792a1379857a44f3d75b5802c89c13805.jpg', '', '', '', '竹达彩奈 / 阿部敦 / 沼仓爱美 / 铃木达央 / 藤原启治 / 杉田智和 / 田中爱美 / 本渡枫 / 西村知道 / 利根健太朗 / 田村睦心 / 荒浪和沙 / 拜真之介 / 村濑步', '高柳滋仁 / 嵯峨敏 / 藤井隆文 / 藤井辰己 / 平峰义大 / 岩崎光洋 / 宫崎修治', '', '', '位于日本超偏远地区的某家粗点心（古早的小零食一类）店中，有一位梦想成为漫画家的少年鹿田九，但他却被自己的父亲鹿田洋以半强迫的方式要求继承店面。此时，一位拥有亮丽外表的千金大小姐枝垂莹突然登场，并透露出', '全12集', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.3, 0, 0, 1740540136, 1740522637, 0, 0, 0, 0, 0.0, '', '1118', '', '', '', '', '', '', '', '<p>位于日本超偏远地区的某家粗点心（古早的小零食一类）店中，有一位梦想成为漫画家的少年鹿田九，但他却被自己的父亲鹿田洋以半强迫的方式要求继承店面。此时，一位拥有亮丽外表的千金大小姐枝垂莹突然登场，并透露出洋身为业界名人的事实。以此为契机，一连串环绕着这家小店的粗点心喜剧就此开演！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0476B4DDE848555A50E978#第02集$MOE0476B4DDE848555A50E97B#第03集$MOE0476B4DDE848555A50E97A#第04集$MOE0476B4DDE848555A50E97D#第05集$MOE0476B4DDE848555A50E97C#第06集$MOE0476B4DDE848555A50E97F#第07集$MOE0476B4DDE848555A50E97E#第08集$MOE0476B4DDE848555A50E971#第09集$MOE0476B4DDE848555A50E970#第10集$MOE0476B4DDE848555A50E879#第11集$MOE0476B4DDE848555A50E878#第12集$MOE0476B4DDE848555A50E87B$$$第01集$id_XS0476B4DDE848555A50E978#第02集$id_XS0476B4DDE848555A50E97B#第03集$id_XS0476B4DDE848555A50E97A#第04集$id_XS0476B4DDE848555A50E97D#第05集$id_XS0476B4DDE848555A50E97C#第06集$id_XS0476B4DDE848555A50E97F#第07集$id_XS0476B4DDE848555A50E97E#第08集$id_XS0476B4DDE848555A50E971#第09集$id_XS0476B4DDE848555A50E970#第10集$id_XS0476B4DDE848555A50E879#第11集$id_XS0476B4DDE848555A50E878#第12集$id_XS0476B4DDE848555A50E87B$$$第01集$id_MOE0476B4DDE848555A50E978#第02集$id_MOE0476B4DDE848555A50E97B#第03集$id_MOE0476B4DDE848555A50E97A#第04集$id_MOE0476B4DDE848555A50E97D#第05集$id_MOE0476B4DDE848555A50E97C#第06集$id_MOE0476B4DDE848555A50E97F#第07集$id_MOE0476B4DDE848555A50E97E#第08集$id_MOE0476B4DDE848555A50E971#第09集$id_MOE0476B4DDE848555A50E970#第10集$id_MOE0476B4DDE848555A50E879#第11集