INSERT INTO `mac_vod` VALUES (1118, 1, 0, 0, '粗点心战争2', 'だがしかし 2期（2018）', 'cudianxinzhanzheng2', 1, 'C', '', 'fe81ffac', '日常,美食,漫画改', 'http://i0.hdslb.com/bfs/bangumi/97d8fde6b9b3783452e3109e0823fbf473c695c3.jpg', '', '', '', '竹达彩奈 / 阿部敦 / 沼仓爱美 / 铃木达央 / 藤原启治 / 赤崎千夏 / 杉田智和', '桑原智 / 山口赖房 / 吉村文宏 / 前园文夫 / 又野弘道 / 岩本保雄', '', '', '不愿继承家业粗点心店的鹿田九，与热爱粗点心的不可思议美少女·萤。萤为了让九继承粗点心店，而开始屡次造访店中。与萤一同度过的九顺利地前进在成为粗点心店长的道路上……是不是这样还不清楚，不过与友人远藤豆、', '全12集', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.2, 0, 0, 1740545239, 1740523002, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>不愿继承家业粗点心店的鹿田九，与热爱粗点心的不可思议美少女·萤。萤为了让九继承粗点心店，而开始屡次造访店中。与萤一同度过的九顺利地前进在成为粗点心店长的道路上……是不是这样还不清楚，不过与友人远藤豆、远藤彩一同度过的愉快的暑假仍将继续！？献上实际存在的粗点心作为礼物，美味而令人怀念的粗点心喜剧！请再一次地尽情享用到饱！！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5772B489EF4F0C5A50E978#第02集$MOE5772B489EF4F0C5A50E97B#第03集$MOE5772B489EF4F0C5A50E97A#第04集$MOE5772B489EF4F0C5A50E97D#第05集$MOE5772B489EF4F0C5A50E97C#第06集$MOE5772B489EF4F0C5A50E97F#第07集$MOE5772B489EF4F0C5A50E97E#第08集$MOE5772B489EF4F0C5A50E971#第09集$MOE5772B489EF4F0C5A50E970#第10集$MOE5772B489EF4F0C5A50E879#第11集$MOE5772B489EF4F0C5A50E878#第12集$MOE5772B489EF4F0C5A50E87B$$$第01集$id_XS5772B489EF4F0C5A50E978#第02集$id_XS5772B489EF4F0C5A50E97B#第03集$id_XS5772B489EF4F0C5A50E97A#第04集$id_XS5772B489EF4F0C5A50E97D#第05集$id_XS5772B489EF4F0C5A50E97C#第06集$id_XS5772B489EF4F0C5A50E97F#第07集$id_XS5772B489EF4F0C5A50E97E#第08集$id_XS5772B489EF4F0C5A50E971#第09集$id_XS5772B489EF4F0C5A50E970#第10集$id_XS5772B489EF4F0C5A50E879#第11集$id_XS5772B489EF4F0C5A50E878#第12集$id_XS5772B489EF4F0C5A50E87B$$$第01集$id_MOE5772B489EF4F0C5A50E978#第02集$id_MOE5772B489EF4F0C5A50E97B#第03集$id_MOE5772B489EF4F0C5A50E97A#第04集$id_MOE5772B489EF4F0C5A50E97D#第05集$id_MOE5772B489EF4F0C5A50E97C#第06集$id_MOE5772B489EF4F0C5A50E97F#第07集$id_MOE5772B489EF4F0C5A50E97E#第08集$id_MOE5772B489EF4F0C5A50E971#第09集$id_MOE5772B489EF4F0C5A50E970#第10集$id_MOE5772B489EF4F0C5A50E879#第11集$id_MOE5772B489EF4F0C5A50E878#第12