INSERT INTO `mac_vod` VALUES (1119, 1, 0, 0, '夏日幻魂', 'サマーゴースト（2021）', 'xiarihuanhun', 1, 'X', '', 'abb272d9', '原创,奇幻,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/355e622928852e24e3fef4270b77270e30d164cb.png', '', '', '', '川荣李奈 / 小林千晃 / 岛袋美由利 / 岛崎信长 / 本田贵子 / 佐藤元 / 中村和正 / 高桥大辅 / 佐伯美由纪 / Loundraw', 'Loundraw', '', '', '“知道夏日幻魂吗？”\r\n通过网络相识的高中生，友也、葵、凉。\r\n据称，都市传说中被称作“夏日幻魂”的是一位年轻女性的幽灵，只要燃放烟花她就会现身。\r\n无法迈向心仪人生的“友也”\r\n寻找不到容身之处的\\', '全1集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.8, 0, 0, 1740545388, 1740523033, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“知道夏日幻魂吗？”\r\n通过网络相识的高中生，友也、葵、凉。\r\n据称，都市传说中被称作“夏日幻魂”的是一位年轻女性的幽灵，只要燃放烟花她就会现身。\r\n无法迈向心仪人生的“友也”\r\n寻找不到容身之处的\\</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '正片$MOE5075EE8ABE1B090050E978$$$正片$id_XS5075EE8ABE1B090050E978$$$正片$id_MOE5075EE8ABE1B090050E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1120, 1, 0, 0, 'GJ部', 'GJ部（2013）', 'GJbu', 1, 'G', '', 'b6c8c060', '萌系,搞笑,日常,校园', 'http://i0.hdslb.com/bfs/bangumi/4270c14cf6a0300e578a50f2b1b96356f29cbb23.jpg', '', '', '', '下野纮 / 内田真礼 / 宫本侑芽 / 三森铃子 / 荒川知佳 / 上坂堇 / 木户衣吹 / 诸星堇 / 葵若菜', '藤原佳幸 / 吉田俊司 / 江口大辅 / 赤城博昭 / 深濑重 / 福本洁 / 青井小夜 / 阿宫正和 / 畑博之 / 秦义人', '', '', '在某高校旧校舍一间教室里本体不明的社团，GJ（good job）部，被强制入部的四之宫京夜在此与他相遇的是……个子很小但是架子很大的部长真央，与姐姐真央大相径庭、有着如天使一般包容心的惠，感觉谁都和自', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 9.8, 0, 0, 1740550163, 1740523182, 0, 0, 0, 0, 0.0, '', '1121', '', '', '', '', '', '', '', '<p>在某高校旧校舍一间教室里本体不明的社团，GJ（good job）部，被强制入部的四之宫京夜在此与他相遇的是……个子很小但是架子很大的部长真央，与姐姐真央大相径庭、有着如天使一般包容心的惠，感觉谁都和自己一样虽然天才却致命性的没有常识的紫音、肚子总是饿的不可思议的绮罗罗。\r\n伴随着充满着个性的她们的、轻松愉快的时间慢慢地流逝着……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5321EF80EA195B0950E978#第02集$MOE5321EF80EA195B0950E97B#第03集$MOE5321EF80EA195B0950E97A#第04集$MOE5321EF80EA195B0950E97D#第05集$MOE5321EF80EA195B0950E97C#第06集$MOE5321EF80EA195B0950E97F#第07集$MOE5321EF80EA195B0950E97E#第08集$MOE5321EF80EA195B0950E971#第09集$MOE5321EF80EA195B0950E970#第10集$MOE5321EF80EA195B0950E879#第11集$MOE5321EF80EA195B0950E878#第12集$MOE5321EF80EA195B0950E87B$$$第01集$id_XS5321EF80EA195B0950E978#第02集$id_XS5321EF80EA195B0950E97B#第03集$id_XS5321EF80EA195B0950E97A#第04集$id_XS5321EF80EA195B0950E97D#第05集$id_XS5321EF80EA195B0950E97C#第06集$id_XS5321EF80EA195B0950E97F#第07集$id_XS5321EF80EA195B0950E97E#第08集$id_XS5321EF80EA195B0950E971#第09集$id_XS5321EF80EA195B0950E970#第10集$id_XS5321EF80EA195B0950E879#第11集$id_XS5321EF80EA195B0950E878#第12集$id_XS5321EF80EA195B0950E87B$$$第01集$id_MOE5321EF80EA195B0950E978#第02集$id_MOE5321EF80EA195B0950E97B#第03集$id_MOE5321EF80EA195B0950E97A#第04集$id_MOE5321EF80EA195B0950E97D#第05集$id_MOE5321EF80EA195B0950E97C#第06集$id_MOE5321EF80EA195B0950E97F#第07集$id_MOE5321EF80EA195B0950E97E#第08集$id_MOE5321EF80EA195B0950E971#第09集$id_MOE5321EF80EA195B0950E970#第10集$id_MOE5321EF80EA195B0950E879#第11集$id_M