INSERT INTO `mac_vod` VALUES (1149, 1, 0, 0, '未确认进行式 OVA', '未確認で進行形 見て。あれが私たちの泊まっている旅館よ。（2014）', 'weiquerenjinxingshiOVA', 1, 'W', '', '45127c7a', '萌系,搞笑', 'http://i0.hdslb.com/bfs/bangumi/37553432354ec28cca2cf73d0023b9850ebbea38.jpg', '', '', '', '照井春佳 / 松井惠理子 / 吉田有里 / 羽多野涉', '藤原佳幸', '', '', 'Blu-ray＆DVD vol.1特典\r\n   故事讲述过着平凡生活的少女夜之森小红在其16岁生日时，遇到了自称是其婚约者的少女三峰白夜、以及白夜的妹妹三峰真白，并且要和他们二人开始一同生活。加上不但是', 'OVA', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.6, 0, 0, 1740861651, 1740710519, 0, 0, 0, 0, 0.0, '', '1150', '', '', '', '', '', '', '', '<p>Blu-ray＆DVD vol.1特典\r\n &nbsp; 故事讲述过着平凡生活的少女夜之森小红在其16岁生日时，遇到了自称是其婚约者的少女三峰白夜、以及白夜的妹妹三峰真白，并且要和他们二人开始一同生活。加上不但是妹控还是变态的小红的姐姐夜之红绪，是一部描写他们的奇妙同居生活的恋爱喜剧。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OVA$MOE0522BD8ABE4A5A5850E978$$$OVA$id_XS0522BD8ABE4A5A5850E978$$$OVA$id_MOE0522BD8ABE4A5A5850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1150, 1, 0, 0, '未确认进行式 OAD', '未確認で進行形 鴨肉って緑っぽい味がするのね（2014）', 'weiquerenjinxingshiOAD', 1, 'W', '', '30fb0c63', '恋爱,日常', 'http://i0.hdslb.com/bfs/bangumi/2c7e2734bcfadf258412b7c359798d87565809fe.png', '', '', '', '照井春佳 / 松井惠理子 / 吉田有里 / 羽多野涉', '藤原佳幸', '', '', '漫画单行本第5卷同捆OAD', 'OAD', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.6, 0, 0, 1740861748, 1740710668, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>漫画单行本第5卷同捆OAD</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', 'OAD$MOE0227EADAB94A5B0A50E978$$$OAD$id_XS0227EADAB94A5B0A50E978$$$OAD$id_MOE0227EADAB94A5B0A50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1151, 1, 0, 0, '狗与剪刀的正确用法', '犬とハサミは使いよう（2013）', 'gouyujiandaodezhengqueyongfa', 1, 'G', '', 'a077ace1', '搞笑,奇幻', 'http://i0.hdslb.com/bfs/bangumi/66ae74593891a95ee80d2c7cabc41d141acec928.jpg', '', '', '', '樱井孝宏 / 井上麻里奈 / 阿澄佳奈 / 伊藤静 / 加隈亚衣 / 芹泽优 / 羽多野涉 / 内田真礼 / 五十岚裕美 / 斋藤千和 / 井口裕香', '高桥幸雄', '', '', '「还没看完怎麼能死！」某一天，我意外死在强盗手中，却由於身为书痴的执著而奇迹似地复活……以腊肠狗的外貌复活。为什麼是狗啊！这样叫我要怎麼看书！我正在烦恼时，眼前出现把剪刀当武器的虐待狂──夏野雾姬。这', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 17, 0, 17, 17, '', 0, 0, 9.1, 0, 0, 1740876864, 1740710699, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「还没看完怎麼能死！」某一天，我意外死在强盗手中，却由於身为书痴的执著而奇迹似地复活……以腊肠狗的外貌复活。为什麼是狗啊！这样叫我要怎麼看书！我正在烦恼时，眼前出现把剪刀当武器的虐待狂──夏野雾姬。这人怎麼看都是个危险分子，可是她听得懂狗语，而且，她的真实身分竟是我最崇拜的作家秋山忍！我今後该如何是好？杀死我的强盗又下落何处？第十二届ENTAME大赏优秀赏得奖作品，悬疑风格的无厘头喜剧！\r\n\r\n &nbsp; &nbsp;由更伊俊介所著、锅岛哲弘绘制插画的轻小说「狗与剪刀的正确用法」TV动画化决定，预定于今年7月开始播放。本作曾荣获第12回Entame大赏小说部门优秀赏，单行本至今已推出了本篇6卷外加短篇集2卷。而由大庭下门负责作画的漫画，已于「月刊少年Ace」2012年7月号上开始连载，单行本已发行了1卷。\r\n\r\n &nbsp; &nbsp;本作动画的制作公司确定是GONZO，4月新番「绝对防卫利维坦」以及同样也是7月开播的「有你的小镇」均是由GONZO制作的。出演动画的声优阵容与去年3月推出的广播剧CD一样，也是由樱井孝宏、井上麻里奈、阿澄佳奈、伊藤静这四位知名声优分别出演男主角春海和人、女主角夏野雾……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5027BB8FE84A080850E978#第02集$MOE5027BB8FE84A080850E97B#第03集$MOE5027BB8FE84A080850E97A#第04集$MOE5027BB8FE84A080850E97D#第05集$MOE5027BB8FE84A080850E97C#第06集$MOE5027BB8FE84A080850E97F#第07集$MOE5027BB8FE84A080850E97E#第08集$MOE5027BB8FE84A080850E971#第09集$MOE5027BB8FE84A080850E970#第10集$MOE5027BB8FE84A080850E879#第11集$MOE5027BB8FE84A080850E878#第12集$MOE5027BB8FE84A080850E87B$$$第01集$id_XS5027BB8FE84A080850E978#第02集$id_XS5027BB8FE84A080850E97B#第03集$id_XS5027BB8FE84A080850E97A#第04集$id_XS5027BB8FE84A080850E97D#第05集$id_XS5027BB8FE84A080850E97C#第06集$id_XS5027BB8FE84A080850E97F#第07集$id_XS5027BB8FE84A080850E97E#第08集$id_XS5027BB8FE84A080850E971#第09集$id_XS5027BB8FE84A080850E970#第10集$id_XS5027BB8FE84A080850E879#第11集$id_XS5027BB8FE84A080850E878#第12集$id_XS5027BB8FE84A080850E87B$$$第01集$id_MOE5027BB8FE84A080850E978#第02集$id_MOE5027BB8FE84A080850E97B#第03集$id_MOE5027BB8FE84A080850E97A#第04集$id_MOE5027BB8FE84A080850E97D#第05集$id_MOE5027BB8FE84A080850E97C#第06集$id_MOE5027BB8FE84A080850E97F#第07集$id_MOE5027BB8FE84A080850E97E#第08集$id_MOE5027BB8FE84A080850E971#第09集$id_MOE5027BB8FE84A080850E970#第10集$id_MOE5027BB8FE84A080850E879#第11集$id_MOE5027BB8FE84A080850E878#第12集$id_MOE5027BB8FE84A080850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1152, 1, 0, 0, '永生之酒', 'バッカーノ！（2007）', 'yongshengzhijiu', 1, 'Y', '', 'a656f257', '时泪,奇幻,声控,小说改', 'http://i0.hdslb.com/bfs/bangumi/c26357c3277aed90275635a5552445f2edd05ac8.jpg', '', '', '', '小野坂昌也 / 青木沙耶香 / 吉野裕行 / 宫本充 / 小林沙苗 / 藤原启治 / 阪口大助 / 小林优 / 森田成一 / 广桥凉 / 千叶进步 / 太田哲治 / 有本钦隆 / 菅生隆之 / 中田和宏 / 伊藤美纪 / 后藤沙绪里 / 神田朱未 / 子安武人 / 三宅健太 / 山口胜平 / 大林隆介 / 若本规夫 / 井上麻里奈 / 羽多野涉 / 伊丸冈笃 / 永泽菜教 / 平野俊隆 / 古泽彻 / 楠大典 / 斋藤千和 / 伊藤静 / 神奈延年 / 大畑伸太郎 / 高垣彩阳 / 斧笃 / 长克巳 / ', '大森贵弘 / 神户守 / 小坂春女 / 米田光宏 / 寺东克己 / 松浦锭平 / 中野英明 / 大畑清隆 / 川越淳 / 原博 / 田村耕太郎 / 佐藤丰', '', '', '1711年的大西洋上，背井离乡的炼金术师们从恶魔手中得到了奇妙的不死药——那便是永生之酒。喝了永生之酒的人会变得不老不死，唯一的弱点就是他们的右手。为了独占永生之酒，船上的众人开始互相残杀。\r\n1930', '全16集', '', 0, '0', '', '', '日本', '日语', '2007', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 29, 0, 29, 29, '', 0, 0, 9.8, 0, 0, 1740884166, 1740710726, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>1711年的大西洋上，背井离乡的炼金术师们从恶魔手中得到了奇妙的不死药——那便是永生之酒。喝了永生之酒的人会变得不老不死，唯一的弱点就是他们的右手。为了独占永生之酒，船上的众人开始互相残杀。\r\n1930年代的纽约，年少有为的菲洛、傻瓜盗贼夫妇、老不死的炼金术士和他的助手，以及菲洛从小的玩伴、豪门千金、恐怖组织成员、年轻的列车员……以永生之酒为契机，这群千奇百怪、充满个性的人的命运开始复杂交错起来。\r\n从芝加哥到纽约、穿越大陆的铁路列车上，命运之轮将演员们聚集到了一起。而在这辆列车上的不仅仅是人类，传说中的怪物“铁路追踪者”再次出现，旅客们从最后一节车厢开始接连消失……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5021B98EEF1B580E50E978#第02集$MOE5021B98EEF1B580E50E97B#第03集$MOE5021B98EEF1B580E50E97A#第04集$MOE5021B98EEF1B580E50E97D#第05集$MOE5021B98EEF1B580E50E97C#第06集$MOE5021B98EEF1B580E50E97F#第07集$MOE5021B98EEF1B580E50E97E#第08集$MOE5021B98EEF1B580E50E971#第09集$MOE5021B98EEF1B580E50E970#第10集$MOE5021B98EEF1B580E50E879#第11集$MOE5021B98EEF1B580E50E878#第12集$MOE5021B98EEF1B580E50E87B#第13集$MOE5021B98EEF1B580E50E87A#第14集$MOE5021B98EEF1B580E50E87D#第15集$MOE5021B98EEF1B580E50E87C#第16集$MOE5021B98EEF1B580E50E87F$$$第01集$id_XS5021B98EEF1B580E50E978#第02集$id_XS5021B98EEF1B580E50E97B#第03集$id_XS5021B98EEF1B580E50E97A#第04集$id_XS5021B98EEF1B580E50E97D#第05集$id_XS5021B98EEF1B580E50E97C#第06集$id_XS5021B98EEF1B580E50E97F#第07集$id_XS5021B98EEF1B580E50E97E#第08集$id_XS5021B98EEF1B580E50E971#第09集$id_XS5021B98EEF1B580E50E970#第10集$id_XS5021B98EEF1B580E50E879#第11集$id_XS5021B98EEF1B580E50E878#第12集$id_XS5021B98EEF1B580E50E87B#第13集$id_XS5021B98EEF1B580E50E87A#第14集$id_XS5021B98EEF1B580E50E87D#第15集$id_XS5021B98EEF1B580E50E87C#第16集$id_XS5021B98EEF1B580E50E87F$$$第01集$id_MOE5021B98EEF1B580E50E978#第02集$id_MOE5021B98EEF1B580E50E97B#第03集$id_MOE5021B98EEF1B580E50E97A#第04集$id_MOE5021B98EEF1B580E50E97D#第05集$id_MOE5021B98EEF1B580E50E97C#第06集$id_MOE5021B98EEF1B580E50E97F#第07集$id_MOE5021B98EEF1B580E50E97E#第08集$id_MOE5021B98EEF1B580E50E971#第09集$id_MOE5021B98EEF1B580E50E970#第10集$id_MOE5021B98EEF1B580E50E879#第11集$id_MOE5021B98EEF1B580E50E878#第12集$id_MOE5021B98EEF1B580E50E87B#第13集$id_MOE5021B98EEF1B580E50E87A#第14集$id_MOE5021B98EEF1B580E50E87D#第15集$id_MOE5021B98EEF1B580E50E87C#第16集$id_MOE5021B98EEF1B580E50E87F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1153, 1, 0, 0, '空战魔导士候补生的教官', '空戦魔導士候補生の教官（2015）', 'kongzhanmodaoshihoubushengdejiaoguan', 1, 'K', '', 'bfb05e12', '奇幻,热血,科幻', 'http://i0.hdslb.com/bfs/bangumi/c2d4b22675f78f07d3b6562a0e336ac110cc35d7.jpg', '', '', '', '松冈祯丞 / 山本希望 / 东山奈央 / 野水伊织 / 种田梨沙 / 山田悠希 / 藏合纱惠子 / 柿原彻也 / 安济知佳 / 原优子 / 大森日雅 / 三咲麻里 / 上仓万实 / 矢尾幸子 / 木户衣吹 / 佐藤利奈 / 齐藤次郎 / 安元洋贵', '稻垣隆行 / 则座诚', '', '', '世界受“魔甲虫”威胁，大地遭其占据，人类只能住在天空中的浮游都市里。之后，以魔力对抗“魔甲虫”的魔法师——空战魔导士诞生了。\r\n就读空战魔导士培育机构——学园浮游都市“密斯特岗”的彼方·英司，是拥有“黑', '全12集 OVA', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 11, 0, 11, 11, '', 0, 0, 7.2, 0, 0, 1740895819, 1740710762, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>世界受“魔甲虫”威胁，大地遭其占据，人类只能住在天空中的浮游都市里。之后，以魔力对抗“魔甲虫”的魔法师——空战魔导士诞生了。\r\n就读空战魔导士培育机构——学园浮游都市“密斯特岗”的彼方·英司，是拥有“黑之剑圣”称号的S128特务小队的王牌。然而，如今他却被视为“特务小队的叛徒”而受到众人的轻蔑与厌恶……\r\n某天，彼方被任命为连战皆败的E601小队教官。这支小队收容了三名个性特异的少女——？由叛徒与问题学生少女们展开的进击，现在启动！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5371EE88BC4C5C0B50E978#第02集$MOE5371EE88BC4C5C0B50E97B#第03集$MOE5371EE88BC4C5C0B50E97A#第04集$MOE5371EE88BC4C5C0B50E97D#第05集$MOE5371EE88BC4C5C0B50E97C#第06集$MOE5371EE88BC4C5C0B50E97F#第07集$MOE5371EE88BC4C5C0B50E97E#第08集$MOE5371EE88BC4C5C0B50E971#第09集$MOE5371EE88BC4C5C0B50E970#第10集$MOE5371EE88BC4C5C0B50E879#第11集$MOE5371EE88BC4C5C0B50E878#第12集$MOE5371EE88BC4C5C0B50E87B#OVA$MOE5371EE88BC4C5C0B50E87A$$$第01集$id_XS5371EE88BC4C5C0B50E978#第02集$id_XS5371EE88BC4C5C0B50E97B#第03集$id_XS5371EE88BC4C5C0B50E97A#第04集$id_XS5371EE88BC4C5C0B50E97D#第05集$id_XS5371EE88BC4C5C0B50E97C#第06集$id_XS5371EE88BC4C5C0B50E97F#第07集$id_XS5371EE88BC4C5C0B50E97E#第08集$id_XS5371EE88BC4C5C0B50E971#第09集$id_XS5371EE88BC4C5C0B50E970#第10集$id_XS5371EE88BC4C5C0B50E879#第11集$id_XS5371EE88BC4C5C0B50E878#第12集$id_XS5371EE88BC4C5C0B50E87B#OVA$id_XS5371EE88BC4C5C0B50E87A$$$第01集$id_MOE5371EE88BC4C5C0B50E978#第02集$id_MOE5371EE88BC4C5C0B50E97B#第03集$id_MOE5371EE88BC4C5C0B50E97A#第04集$id_MOE5371EE88BC4C5C0B50E97D#第05集$id_MOE5371EE88BC4C5C0B50E97C#第06集$id_MOE5371EE88BC4C5C0B50E97F#第07集$id_MOE5371EE88BC4C5C0B50E97E#第08集$id_MOE5371EE88BC4C5C0B50E971#第09集$id_MOE5371EE88BC4C5C0B50E970#第10集$id_MOE5371EE88BC4C5C0B50E879#第11集$id_MOE5371EE88BC4C5C0B50E878#第12集$id_MOE5371EE88BC4C5C0B50E87B#OVA$id_MOE5371EE88BC4C5C0B50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1154, 1, 0, 0, '史上最强大魔王转生为村民甲', '史上最強の大魔王、村人Aに転生する（2022）', 'shishangzuiqiangdamowangzhuanshengweicunminjia', 1, 'S', '', '1027549a', '小说改,奇幻,战斗,魔法', 'http://i0.hdslb.com/bfs/bangumi/image/f0a6af478f2f87ebfaa658b328eed9da03f352a8.png', '', '', '', '深町寿成 / 丸冈和佳奈 / 羊宫妃那 / 大桥彩香 / 园崎未惠 / 高桥李依 / 天崎滉平 / 甲斐田裕子 / 小仓唯 / 子安武人 / 三宅健太', '凑未来', '', '', '他是于神话中留名的史上最强魔王瓦尔瓦托斯。\r\n\r\n他以王的身份走完了一生，由于强大而无比孤独，因此向往着平凡的生活，\r\n并在数千年后的世界转生成了村民亚德·梅特尔。\r\n\r\n然而，在他转生的未来，魔法文明不断衰落', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 65, 0, 65, 65, '', 0, 0, 4.9, 0, 0, 1741026295, 1740710771, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>他是于神话中留名的史上最强魔王瓦尔瓦托斯。\r\n\r\n他以王的身份走完了一生，由于强大而无比孤独，因此向往着平凡的生活，\r\n并在数千年后的世界转生成了村民亚德·梅特尔。\r\n\r\n然而，在他转生的未来，魔法文明不断衰落。\r\n魔法本身已经无比弱小。\r\n\r\n亚德与自己的第一个朋友兼发小伊莉娜一起进入了魔法学园，\r\n虽然他尽力避免成为一个特殊人物，却藏不住自己过人的力量。\r\n\r\n敬畏他的人、想要亲近他的人络绎不绝，\r\n而过去令世界陷入恐惧的「魔族」也在暗地里展开了行动。\r\n\r\n前「魔王」究竟能否取得安稳而平凡的人生呢？\r\n波澜万丈的学园英雄奇幻故事，就此开幕！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0027BE8FBC1D545850E978#第02集$MOE0027BE8FBC1D545850E97B#第03集$MOE0027BE8FBC1D545850E97A#第04集$MOE0027BE8FBC1D545850E97D#第05集$MOE0027BE8FBC1D545850E97C#第06集$MOE0027BE8FBC1D545850E97F#第07集$MOE0027BE8FBC1D545850E97E#第08集$MOE0027BE8FBC1D545850E971#第09集$MOE0027BE8FBC1D545850E970#第10集$MOE0027BE8FBC1D545850E879#第11集$MOE0027BE8FBC1D545850E878#第12集$MOE0027BE8FBC1D545850E87B$$$第01集$id_XS0027BE8FBC1D545850E978#第02集$id_XS0027BE8FBC1D545850E97B#第03集$id_XS0027BE8FBC1D545850E97A#第04集$id_XS0027BE8FBC1D545850E97D#第05集$id_XS0027BE8FBC1D545850E97C#第06集$id_XS0027BE8FBC1D545850E97F#第07集$id_XS0027BE8FBC1D545850E97E#第08集$id_XS0027BE8FBC1D545850E971#第09集$id_XS0027BE8FBC1D545850E970#第10集$id_XS0027BE8FBC1D545850E879#第11集$id_XS0027BE8FBC1D545850E878#第12集$id_XS0027BE8FBC1D545850E87B$$$第01集$id_MOE0027BE8FBC1D545850E978#第02集$id_MOE0027BE8FBC1D545850E97B#第03集$id_MOE0027BE8FBC1D545850E97A#第04集$id_MOE0027BE8FBC1D545850E97D#第05集$id_MOE0027BE8FBC1D545850E97C#第06集$id_MOE0027BE8FBC1D545850E97F#第07集$id_MOE0027BE8FBC1D545850E97E#第08集$id_MOE0027BE8FBC1D545850E971#第09集$id_MOE0027BE8FBC1D545850E970#第10集$id_MOE0027BE8FBC1D545850E879#第11集$id_MOE0027BE8FBC1D545850E878#第12集$id_MOE0027BE8FBC1D545850E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1155, 1, 0, 0, '巴克·亚罗/BACK ARROW', 'バック・アロウ（2021）', 'bakeyaluoBACKARROW', 1, 'B', '', '8ecfa5c2', '原创,机战,架空', 'http://i0.hdslb.com/bfs/bangumi/image/fbd2849172a5ed7b206ab1f5269db6705bc49352.png', '', '', '', '梶裕贵 / 洲崎绫 / 小泽亚李 / 小野贤章 / 杉田智和 / 置鲇龙太郎 / 潘惠美 / 小清水亚美 / 小松未可子 / 上田丽奈 / 松本沙罗 / 长绳麻理亚 / 关智一 / 河本邦弘 / 堀内贤雄 / 三宅健太 / 稻田彻 / 桧山修之 / 间岛淳司 / 间宫康弘 / 远近孝一 / 北泽力 / 中村太亮 / 羽多野涉 / 三木真一郎 / 井上喜久子 / 橘龙丸 / 武内骏辅', '谷口悟朗 / 仁科邦康 / 藤濑顺一', '', '', '林伽林德——这片土地是被墙壁包围起来的世界。\r\n墙壁将这片土地覆盖、守护、哺育、培养。\r\n墙壁即是神——是这片大地，林伽林德的根基。\r\n\r\n某天，在林伽林德边境之地「艾泽村」\r\n出现了一位神秘男子「巴克·亚罗」', '全24集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.8, 0, 0, 1741052476, 1740710781, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>林伽林德——这片土地是被墙壁包围起来的世界。\r\n墙壁将这片土地覆盖、守护、哺育、培养。\r\n墙壁即是神——是这片大地，林伽林德的根基。\r\n\r\n某天，在林伽林德边境之地「艾泽村」\r\n出现了一位神秘男子「巴克·亚罗」。\r\n亚罗失去了记忆，\r\n却唯独知道自己是「从“墙壁外”来的」。\r\n\r\n亚罗为了取回记忆而以墙壁之外为目标，\r\n却逐渐被卷入围绕着自身的争斗当中——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0972EFDEE81C0E0B50E978#第02集$MOE0972EFDEE81C0E0B50E97B#第03集$MOE0972EFDEE81C0E0B50E97A#第04集$MOE0972EFDEE81C0E0B50E97D#第05集$MOE0972EFDEE81C0E0B50E97C#第06集$MOE0972EFDEE81C0E0B50E97F#第07集$MOE0972EFDEE81C0E0B50E97E#第08集$MOE0972EFDEE81C0E0B50E971#第09集$MOE0972EFDEE81C0E0B50E970#第10集$MOE0972EFDEE81C0E0B50E879#第11集$MOE0972EFDEE81C0E0B50E878#第12集$MOE0972EFDEE81C0E0B50E87B#第13集$MOE0972EFDEE81C0E0B50E87A#第14集$MOE0972EFDEE81C0E0B50E87D#第15集$MOE0972EFDEE81C0E0B50E87C#第16集$MOE0972EFDEE81C0E0B50E87F#第17集$MOE0972EFDEE81C0E0B50E87E#第18集$MOE0972EFDEE81C0E0B50E871#第19集$MOE0972EFDEE81C0E0B50E870#第20集$MOE0972EFDEE81C0E0B50EB79#第21集$MOE0972EFDEE81C0E0B50EB78#第22集$MOE0972EFDEE81C0E0B50EB7B#第23集$MOE0972EFDEE81C0E0B50EB7A#第24集$MOE0972EFDEE81C0E0B50EB7D$$$第01集$id_XS0972EFDEE81C0E0B50E978#第02集$id_XS0972EFDEE81C0E0B50E97B#第03集$id_XS0972EFDEE81C0E0B50E97A#第04集$id_XS0972EFDEE81C0E0B50E97D#第05集$id_XS0972EFDEE81C0E0B50E97C#第06集$id_XS0972EFDEE81C0E0B50E97F#第07集$id_XS09