INSERT INTO `mac_vod` VALUES (1156, 1, 0, 0, '稻荷恋之歌', 'いなり、こんこん、恋いろは。（2014）', 'daohelianzhige', 1, 'D', '', '4707baa7', '少女,奇幻,恋爱', 'http://i0.hdslb.com/bfs/bangumi/c2476f937bbd11a18a73aca48a2ecebe8db192b3.jpg', '', '', '', '大空直美 / 桑岛法子 / 冈本宽志 / 野水伊织 / 佐土原香织 / 上田燿司 / 池边久美子 / 原纱友里 / 矶边万沙子 / 子安武人 / 三上枝织', '高桥亨 / 冈本英树 / 别所诚人 / 加藤诚 / 守田艺成 / 矢花馨 / 江岛泰男 / 岩田义彦 / 清水一伸', '', '', '本作舞台发生在京都伏见。从小就一直相信神明存在的伏见伊奈里，某天早上救了一只快掉进河里的小狗。后来，当伊奈里正为失恋难过的时候，之前被她所救的小狗再次出现在她的面前。其实这只小狗是神明的使者，而小狗的', '全10集 OVA', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.0, 0, 0, 1741055914, 1740710790, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>本作舞台发生在京都伏见。从小就一直相信神明存在的伏见伊奈里，某天早上救了一只快掉进河里的小狗。后来，当伊奈里正为失恋难过的时候，之前被她所救的小狗再次出现在她的面前。其实这只小狗是神明的使者，而小狗的主人为了答谢伊奈里，答应实现她一个愿望……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0520BC8FEB480C0E50E978#第02集$MOE0520BC8FEB480C0E50E97B#第03集$MOE0520BC8FEB480C0E50E97A#第04集$MOE0520BC8FEB480C0E50E97D#第05集$MOE0520BC8FEB480C0E50E97C#第06集$MOE0520BC8FEB480C0E50E97F#第07集$MOE0520BC8FEB480C0E50E97E#第08集$MOE0520BC8FEB480C0E50E971#第09集$MOE0520BC8FEB480C0E50E970#第10集$MOE0520BC8FEB480C0E50E879#OVA$MOE0520BC8FEB480C0E50E878$$$第01集$id_XS0520BC8FEB480C0E50E978#第02集$id_XS0520BC8FEB480C0E50E97B#第03集$id_XS0520BC8FEB480C0E50E97A#第04集$id_XS0520BC8FEB480C0E50E97D#第05集$id_XS0520BC8FEB480C0E50E97C#第06集$id_XS0520BC8FEB480C0E50E97F#第07集$id_XS0520BC8FEB480C0E50E97E#第08集$id_XS0520BC8FEB480C0E50E971#第09集$id_XS0520BC8FEB480C0E50E970#第10集$id_XS0520BC8FEB480C0E50E879#OVA$id_XS0520BC8FEB480C0E50E878$$$第01集$id_MOE0520BC8FEB480C0E50E978#第02集$id_MOE0520BC8FEB480C0E50E97B#第03集$id_MOE0520BC8FEB480C0E50E97A#第04集$id_MOE0520BC8FEB480C0E50E97D#第05集$id_MOE0520BC8FEB480C0E50E97C#第06集$id_MOE0520BC8FEB480C0E50E97F#第07集$id_MOE0520BC8FEB480C0E50E97E#第08集$id_MOE0520BC8FEB480C0E50E971#第09集$id_MOE0520BC8FEB480C0E50E970#第10集$id_MOE0520BC8FEB480C0E50E879#OVA$id_MOE0520BC8FEB480C0E50E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1157, 1, 0, 0, '桃子男孩渡海而来', 'ピーチボーイリバーサイド（2021）', 'taozinanhaiduhaierlai', 1, 'T', '', '91ab794d', '漫画改,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/83dd36a567ff753eaa753be07841093a497bcdf6.png', '', '', '', '白石晴香 / 东山奈央 / 市道真央 / 增田俊树 / 户田惠 / 齐藤次郎 / 峰田茉优 / 户松遥 / 平川大辅 / 村井美里 / 久保由利香 / 鈴華ゆう子 / 三上哲 / 八代拓 / 麦人 / 天城莎莉 / 矢野正明', '上田繁', '', '', '这是很久以前的故事。\r\n某个地方住着一位老爷爷和一位老奶奶。\r\n老爷爷上山去砍柴，老奶奶到河边洗衣服——（中略）\r\n\r\n终于鬼怪都被消灭了，然而外国似乎也有鬼怪…\r\n于是桃太郎渡过大海。\r\n\r\n消灭了恶鬼，厉害！', '全12集', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 4.5, 0, 0, 1741062628, 1740710801, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>这是很久以前的故事。\r\n某个地方住着一位老爷爷和一位老奶奶。\r\n老爷爷上山去砍柴，老奶奶到河边洗衣服——（中略）\r\n\r\n终于鬼怪都被消灭了，然而外国似乎也有鬼怪…\r\n于是桃太郎渡过大海。\r\n\r\n消灭了恶鬼，厉害！\r\n拯救了世界，可喜可贺！\r\n\r\n然而不对劲的是——乐在其中了\r\n\r\n假设一下……\r\n\r\n假如漂流而来的大桃子不止一个的话…\r\n在日本漂流而来的桃子仅仅是很多桃子其中一个的话…</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0826EDDABE10595D50E978#第02集$MOE0826EDDABE10595D50E97B#第03集$MOE0826EDDABE10595D50E97A#第04集$MOE0826EDDABE10595D50E97D#第05集$MOE0826EDDABE10595D50E97C#第06集$MOE0826EDDABE10595D50E97F#第07集$MOE0826EDDABE10595D50E97E#第08集$MOE0826EDDABE10595D50E971#第09集$MOE0826EDDABE10595D50E970#第10集$MOE0826EDDABE10595D50E879#第11集$MOE0826EDDABE10595D50E878#第12集$MOE0826EDDABE10595D50E87B$$$第01集$id_XS0826EDDABE10595D50E978#第02集$id_XS0826EDDABE10595D50E97B#第03集$id_XS0826EDDABE10595D50E97A#第04集$id_XS0826EDDABE10595D50E97D#第05集$id_XS0826EDDABE10595D50E97C#第06集$id_XS0826EDDABE10595D50E97F#第07集$id_XS0826EDDABE10595D50E97E#第08集$id_XS0826EDDABE10595D50E971#第09集$id_XS0826EDDABE10595D50E970#第10集$id_XS0826EDDABE10595D50E879#第11集$id_XS0826EDDABE10595D50E878#第12集$id_XS0826EDDABE10595D50E87B$$$第01集$id_MOE0826EDDABE10595D50E978#第02集$id_MOE0826EDDABE10595D50E97B#第03集$id_MOE0826EDDABE10595D50E97A#第04集$id_MOE0826EDDABE10595D50E97D#第05集$id_MOE0826EDDABE10595D50E97C#第06集$id_MOE0826EDDABE10595D50E97F#第07集$id_MOE0826EDDABE10595D50E97E#第08集$id_MOE0826EDDABE10595D50E971#第09集$id_MOE0826EDDABE10595D50E970#第10集$id_MOE0826EDDABE10595D50E879#第11集$id_MOE0826EDDABE10595D50E878#第12集$id_MOE0826EDDABE10595D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1158, 1, 0, 0, '催眠麦克风', 'ヒプノシスマイク-Division Rap Battle- Rhyme Anima（2020）', 'cuimianmaikefeng', 1, 'C', '', '9c104207', '偶像,音乐', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2591668798.jpg', '', '', '', '木村昴 / 石谷春贵 / 天崎滉平 / 浅沼晋太郎 / 驹田航 / 白井悠介 / 齐藤壮马 / 野津山幸宏 / 速水奖 / 木岛隆一 / 伊东健人 / 神尾晋一郎 / 小林优 / 高桥智秋', '小野胜巳 / 儿谷直树 / 丸山裕介 / 关晓子 / 嵯峨敏 / 山本隆太', '', '', '武力支配的流血历史已迎来终焉，用语言来统治的时代已到来。手持可以作用到人类神经的特殊麦克风——催眠麦克风，池袋、横滨、涩谷、新宿等各区域代表的MC组合，使用「说唱」进行对决。赌上选手们威严的领土之战一', '全13集（繁）', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 6.2, 0, 0, 1740832962, 1740823616, 0, 0, 0, 0, 0.0, '', '1159', '', '', '', '', '', '', '', '<p>武力支配的流血历史已迎来终焉，用语言来统治的时代已到来。手持可以作用到人类神经的特殊麦克风——催眠麦克风，池袋、横滨、涩谷、新宿等各区域代表的MC组合，使用「说唱」进行对决。赌上选手们威严的领土之战一触即发！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0874BD88BD1B5D0E50E978#第02集$MOE0874BD88BD1B5D0E50E97B#第03集$MOE0874BD88BD1B5D0E50E97A#第04集$MOE0874BD88BD1B5D0E50E97D#第05集$MOE0874BD88BD1B5D0E50E97C#第06集$MOE0874BD88BD1B5D0E50E97F#第07集$MOE0874BD88BD1B5D0E50E97E#第08集$MOE0874BD88BD1B5D0E50E971#第09集$MOE0874BD88BD1B5D0E50E970#第10集$MOE0874BD88BD1B5D0E50E879#第11集$MOE0874BD88BD1B5D0E50E878#第12集$MOE0874BD88BD1B5D0E50E87B#第13集$MOE0874BD88BD1B5D0E50E87A$$$第01集$id_XS0874BD88BD1B5D0E50E978#第02集$id_XS0874BD88BD1B5D0E50E97B#第03集$id_XS0874BD88BD1B5D0E50E97A#第04集$id_XS0874BD88BD1B5D0E50E97D#第05集$id_XS0874BD88BD1B5D0E50E97C#第06集$id_XS0874BD88BD1B5D0E50E97F#第07集$id_XS0874BD88BD1B5D0E50E97E#第08集$id_XS0874BD88BD1B5D0E50E971#第09集$id_XS0874BD88BD1B5D0E50E970#第10集$id_XS0874BD88BD1B5D0E50E879#第11集$id_XS0874BD88BD1B5D0E50E878#第12集$id_XS0874BD88BD1B5D0E50E87B#第13集$id_XS0874BD88BD1B5D0E50E87A$$$第01集$id_MOE0874BD88BD1B5D0E50E978#第02集$id_MOE0874BD88BD1B5D0E50E97B#第03集$id_MOE0874BD88BD1B5D0E50E97A#第04集$id_MOE0874BD88BD1B5D0E50E97D#第05集$id_MOE0874BD88BD1B5D0E50E97C#第06集$id_MOE0874BD88BD1B5D0E50E97F#第07集$id_MOE0874BD88BD1B5D0E50E97E#第08集$id_MOE0874BD88BD1B5D0E50E971#第09集$id_MOE0874BD88B