INSERT INTO `mac_vod` VALUES (1160, 1, 0, 0, '心理测量者', 'PSYCHO-PASS サイコパス（2012）', 'xinliceliangzhe', 1, 'X', '', '5e414ccb', '动作,战斗,科幻,犯罪', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2918282001.jpg', '', '', '', '关智一 / 花泽香菜 / 野岛健儿 / 有本钦隆 / 石田彰 / 伊藤静 / 泽城美雪 / 樱井孝宏 / 佐仓绫音 / 浅沼晋太郎 / 浅野真澄 / 榊原良子 / 山路和弘 / 水岛大宙 / 子安武人 / 竹达彩奈 / 坂本真绫 / 茅野爱衣 / 增谷康纪 / 长克巳 / 日高范子', '本广克行 / 盐谷直义 / 川崎逸朗 / 滨名孝行 / 石黑恭平 / 吉泽俊一 / 河野利幸 / 铃木薰 / 西本由纪夫 / 平田丰 / 酒井和男 / 左藤洋二 / 野亦则行 / 江岛泰男 / 永居慎平 / 远藤广隆', '', '', '这是一个人类内心活动均能够数值化的科技时代，同样能被量化的，还有每个人的“犯罪系数”，而原先的调查和侦破都被犯罪系数的检测所替代。维持治安逮捕罪犯的职责，当然落在了警察们的头上，但同时，这些惩奸除恶的', '全22集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 14, 0, 14, 14, '', 0, 0, 9.1, 0, 0, 1740912376, 1740884779, 0, 0, 0, 0, 0.0, '', '1161,1162', '', '', '', '', '', '', '', '<p>这是一个人类内心活动均能够数值化的科技时代，同样能被量化的，还有每个人的“犯罪系数”，而原先的调查和侦破都被犯罪系数的检测所替代。维持治安逮捕罪犯的职责，当然落在了警察们的头上，但同时，这些惩奸除恶的执行官们，本身就是拥有着高犯罪系数的危险人物，因此，另一批专门监视他们的“监视官”应运而生。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0472B889BD4A0E5B50E978#第02集$MOE0472B889BD4A0E5B50E97B#第03集$MOE0472B889BD4A0E5B50E97A#第04集$MOE0472B889BD4A0E5B50E97D#第05集$MOE0472B889BD4A0E5B50E97C#第06集$MOE0472B889BD4A0E5B50E97F#第07集$MOE0472B889BD4A0E5B50E97E#第08集$MOE0472B889BD4A0E5B50E971#第09集$MOE0472B889BD4A0E5B50E970#第10集$MOE0472B889BD4A0E5B50E879#第11集$MOE0472B889BD4A0E5B50E878#第12集$MOE0472B889BD4A0E5B50E87B#第13集$MOE0472B889BD4A0E5B50E87A#第14集$MOE0472B889BD4A0E5B50E87D#第15集$MOE0472B889BD4A0E5B50E87C#第16集$MOE0472B889BD4A0E5B50E87F#第17集$MOE0472B889BD4A0E5B50E87E#第18集$MOE0472B889BD4A0E5B50E871#第19集$MOE0472B889BD4A0E5B50E870#第20集$MOE0472B889BD4A0E5B50EB79#第21集$MOE0472B889BD4A0E5B50EB78#第22集$MOE0472B889BD4A0E5B50EB7B$$$第01集$id_XS0472B889BD4A0E5B50E978#第02集$id_XS0472B889BD4A0E5B50E97B#第03集$id_XS0472B889BD4A0E5B50E97A#第04集$id_XS0472B889BD4A0E5B50E97D#第05集$id_XS0472B889BD4A0E5B50E97C#第06集$id_XS0472B889BD4A0E5B50E97F#第07集$id_XS0472B889BD4A0E5B50E97E#第08集$id_XS0472B889BD4A0E5B50E971#第09集$id_XS0472B889BD4A0E5B50E970#第