INSERT INTO `mac_vod` VALUES (1161, 1, 0, 0, '心理测量者2', 'PSYCHO-PASS サイコパス 2（2014）', 'xinliceliangzhe2', 1, 'X', '', '163de479', '动作,战斗,科幻,犯罪', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2200569309.jpg', '', '', '', '花泽香菜 / 佐仓绫音 / 野岛健儿 / 藤原启治 / 樱井孝宏 / 伊藤静 / 泽城美雪 / 浅野真澄 / 井上麻里奈 / 木村良平', '盐谷直义', '', '', '监视官常守朱在得知西比尔系统的真相后，选择遵从系统，并依然信守人性与法律秩序。她率领新生的刑事课一系，每天与犯罪者对抗着。', '全11集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.2, 0, 0, 1740922286, 1740884799, 0, 0, 0, 0, 0.0, '', '1162', '', '', '', '', '', '', '', '<p>监视官常守朱在得知西比尔系统的真相后，选择遵从系统，并依然信守人性与法律秩序。她率领新生的刑事课一系，每天与犯罪者对抗着。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0021BFDCEC1D5A0050E978#第02集$MOE0021BFDCEC1D5A0050E97B#第03集$MOE0021BFDCEC1D5A0050E97A#第04集$MOE0021BFDCEC1D5A0050E97D#第05集$MOE0021BFDCEC1D5A0050E97C#第06集$MOE0021BFDCEC1D5A0050E97F#第07集$MOE0021BFDCEC1D5A0050E97E#第08集$MOE0021BFDCEC1D5A0050E971#第09集$MOE0021BFDCEC1D5A0050E970#第10集$MOE0021BFDCEC1D5A0050E879#第11集$MOE0021BFDCEC1D5A0050E878$$$第01集$id_XS0021BFDCEC1D5A0050E978#第02集$id_XS0021BFDCEC1D5A0050E97B#第03集$id_XS0021BFDCEC1D5A0050E97A#第04集$id_XS0021BFDCEC1D5A0050E97D#第05集$id_XS0021BFDCEC1D5A0050E97C#第06集$id_XS0021BFDCEC1D5A0050E97F#第07集$id_XS0021BFDCEC1D5A0050E97E#第08集$id_XS0021BFDCEC1D5A0050E971#第09集$id_XS0021BFDCEC1D5A0050E970#第10集$id_XS0021BFDCEC1D5A0050E879#第11集$id_XS0021BFDCEC1D5A0050E878$$$第01集$id_MOE0021BFDCEC1D5A0050E978#第02集$id_MOE0021BFDCEC1D5A0050E97B#第03集$id_MOE0021BFDCEC1D5A0050E97A#第04集$id_MOE0021BFDCEC1D5A0050E97D#第05集$id_MOE0021BFDCEC1D5A0050E97C#第06集$id_MOE0021BFDCEC1D5A0050E97F#第07集$id_MOE0021BFDCEC1D5A0050E97E#第08集$id_MOE0021BFDCEC1D5A0050E971#第09集$id_MOE0021BFDCEC1D5A0050E970#第10集$id_MOE0021BFDCEC1D5A0050E879#第11集$id_MOE0021BFDCEC1D5A0050E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1162, 1, 0, 0, '心理测量者3', 'PSYCHO-PASS サイコパス 3（2019）', 'xinliceliangzhe3', 1, 'X', '', '613ad4ef', '动作,战斗,科幻,犯罪', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2569880216.jpg', '', '', '', '梶裕贵 / 中村悠一 / 樱井孝宏 / 大塚明夫 / 诹访部顺一 / 名冢佳织 / 泽城美雪 / 佐仓绫音 / 日高范子 / 关智一 / 野岛健儿 / 东地宏树 / 伊藤静 / 本田贵子 / 花泽香菜 / 宫野真守 / 中博史 / 田中敦子 / 日笠阳子 / 森川智之 / 堀内贤雄 / 矢作纱友里', '盐谷直义 / 本广克行', '', '', '“正义”，将新世界切开。', '全8集', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 7.6, 0, 0, 1740935449, 1740884811, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>“正义”，将新世界切开。 将灵魂数值化的巨大监视网络·西比拉系统维持着人类治安的近未来。在不断改变的世界中，刑警们手持用于测定与犯罪有关的数值“犯罪系数”的枪支“Dominator”，追捕着犯下罪行之前的“潜在犯”。 于2012年启动的原创TV动画作品《PSYCHO-PASS 心理测量者》的第三期作品，是两位新人监视官的故事。慎导灼与炯·米哈伊尔·伊格纳托夫，成为厚生省公安局的刑警，在这个不断改变的世界中追寻着真实。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0726BFD9ED1D085F50E978#第02集$MOE0726BFD9ED1D085F50E97B#第03集$MOE0726BFD9ED1D085F50E97A#第04集$MOE0726BFD9ED1D085F50E97D#第05集$MOE0726BFD9ED1D085F50E97C#第06集$MOE0726BFD9ED1D085F50E97F#第07集$MOE0726BFD9ED1D085F50E97E#第08集$MOE0726BFD9ED1D085F50E971$$$第01集$id_XS0726BFD9ED1D085F50E978#第02集$id_XS0726BFD9ED1D085F50E97B#第03集$id_XS0726BFD9ED1D085F50E97A#第04集$id_XS0726BFD9ED1D085F50E97D#第05集$id_XS0726BFD9ED1D085F50E97C#第06集$id_XS0726BFD9ED1D085F50E97F#第07集$id_XS0726BFD9ED1D085F50E97E#第08集$id_XS0726BFD9ED1D085F50E971$$$第01集$id_MOE0726BFD9ED1D085F50E978#第02集$id_MOE0726BFD9ED1D085F50E97B#第03集$id_MOE0726BFD9ED1D085F50E97A#第04集$id_MOE0726BFD9ED1D085F50E97D#第05集$id_MOE0726BFD9ED1D085F50E97C#第06集$id_MOE0726BFD9ED1D085F50E97F#第07集$id_MOE0726BFD9ED1D085F50E97E#第08集$id_MOE0726BFD9ED1D085F50E971', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1163, 1, 0, 0, '心理测量者 新剪辑版', 'PSYCHO-PASS サイコパス 新編集版（2014）', 'xinliceliangzhexinjianjiban', 1, 'X', '', 'f1370bf0', '动作,战斗,科幻,犯罪', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2189319862.jpg', '', '', '', '关智一 / 花泽香菜 / 石田彰 / 伊藤静 / 泽城美雪 / 野岛健儿 / 有本钦隆 / 樱井孝宏', '本广克行', '', '', '高科技能够使人类的生活更加便捷，但是，这是否就意味着更加“安全”呢？西比拉系统就是因此而被研制出来的。人类的情感、思想、状态，甚至是犯罪意图都能够被西比拉系统以数据的模式量化，统称“PSYCHO-PA', '全11集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 9.3, 0, 0, 1740961344, 1740884822, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>高科技能够使人类的生活更加便捷，但是，这是否就意味着更加“安全”呢？西比拉系统就是因此而被研制出来的。人类的情感、思想、状态，甚至是犯罪意图都能够被西比拉系统以数据的模式量化，统称“PSYCHO-PASS”，当系统检测到某人的犯罪指数超出正常范围时，便会派出“执行官”进行“强制矫正”。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5726BF8FB94B0B0950E978#第02集$MOE5726BF8FB94B0B0950E97B#第03集$MOE5726BF8FB94B0B0950E97A#第04集$MOE5726BF8FB94B0B0950E97D#第05集$MOE5726BF8FB94B0B0950E97C#第06集$MOE5726BF8FB94B0B0950E97F#第07集$MOE5726BF8FB94B0B0950E97E#第08集$MOE5726BF8FB94B0B0950E971#第09集$MOE5726BF8FB94B0B0950E970#第10集$MOE5726BF8FB94B0B0950E879#第11集$MOE5726BF8FB94B0B0950E878$$$第01集$id_XS5726BF8FB94B0B0950E978#第02集$id_XS5726BF8FB94B0B0950E97B#第03集$id_XS5726BF8FB94B0B0950E97A#第04集$id_XS5726BF8FB94B0B0950E97D#第05集$id_XS5726BF8FB94B0B0950E97C#第06集$id_XS5726BF8FB94B0B0950E97F#第07集$id_XS5726BF8FB94B0B0950E97E#第08集$id_XS5726BF8FB94B0B0950E971#第09集$id_XS5726BF8FB94B0B0950E970#第10集$id_XS5726BF8FB94B0B0950E879#第11集$id_XS5726BF8FB94B0B0950E878$$$第01集$id_MOE5726BF8FB94B0B0950E978#第02集$id_MOE5726BF8FB94B0B0950E97B#第03集$id_MOE5726BF8FB94B0B0950E97A#第04集$id_MOE5726BF8FB94B0B0950E97D#第05集$id_MOE5726BF8FB94B0B0950E97C#第06集$id_MOE5726BF8FB94B0B0950E97F#第07集$id_MOE5726BF8FB94B0B0950E97E#第08集$id_MOE5726BF8FB94B0B0950E971#第09集$id_MOE5726BF8FB94B0B0950E970#第10集$id_MOE5726BF8FB94B0B0950E879#第11集$id_MOE5726BF8FB94B0B0950E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1164, 2, 0, 0, '心理测量者 剧场版', 'PSYCHO-PASS サイコパス 劇場版（2015）', 'xinliceliangzhejuchangban', 1, 'X', '', '4db7fe8d', '动作,战斗,科幻,犯罪', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2213685572.jpg', '', '', '', '花泽香菜 / 关智一 / 野岛健儿 / 伊藤静 / 泽城美雪 / 佐仓绫音 / 樱井孝宏 / 东地宏树 / 榊原良子 / 山路和弘 / 原岛梢 / 高森奈津美 / 日高范子 / 木村昴 / 神谷浩史 / 佐佐木胜彦 / 诸星堇 / 石冢运升 / 小林未沙 / 山本兼平 / 咲野俊介 / 利根健太朗 / 水内清光 / 驹田航 / 小岛英树 / 高濑泰幸 / 山口正秀 / 田代哲哉 / 石井利奈 / 河合纱希子 / 水杜明寿香 / 寺本治子 / 大友萌 / 上田燿司', '本广克行 / 盐谷直义', '', '', '未来世界，公安局刑事课借助西比拉系统对人类的精神状态进行检测，将相关信息转化为数据后作为评判管理国民的标准，这种措施早已成为常态，不容置喙。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 8.1, 0, 0, 1740982970, 1740885280, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>未来世界，公安局刑事课借助西比拉系统对人类的精神状态进行检测，将相关信息转化为数据后作为评判管理国民的标准，这种措施早已成为常态，不容置喙。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0573EE8FEF4C555D50E978$$$正片$id_MOE0573EE8FEF4C555D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1165, 2, 0, 0, '心理测量者SS1：罪与罚', 'PSYCHO-PASS サイコパス Sinners of the System Case.1「罪と罰」（2019）', 'xinliceliangzheSS1zuiyufa', 1, 'X', '', '49b9a1d2', '动作,战斗,科幻,犯罪', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2546222468.jpg', '', '', '', '野岛健儿 / 佐仓绫音 / 弓场沙织 / 平井祥惠 / 冈宽惠 / 小山力也 / 齐藤贵美子 / 多田野曜平 / 中川庆一 / 花泽香菜 / 东地宏树 / 樱井孝宏 / 伊藤静 / 泽城美雪', '盐谷直义', '', '', '2117年冬、公安局ビルに一台の暴走車両が突入する事件が発生。その運転手は青森にある潜在犯隔離施設〈サンクチュアリ〉の心理カウンセラー・夜坂泉だった。しかし取調べ直前に夜坂の即時送還が決定する。 監視', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 7.2, 0, 0, 1740983043, 1740885309, 0, 0, 0, 0, 0.0, '', '1166,1167', '', '', '', '', '', '', '', '<p>2117年冬、公安局ビルに一台の暴走車両が突入する事件が発生。その運転手は青森にある潜在犯隔離施設〈サンクチュアリ〉の心理カウンセラー・夜坂泉だった。しかし取調べ直前に夜坂の即時送還が決定する。 監視官の霜月美佳は、執行官・宜野座伸元らとともに夜坂送還のため青森へ向かう。 そこで待っていたのは、〈偽りの楽園〉だった。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS052EEE81E818090B50E978$$$正片$id_MOE052EEE81E818090B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1166, 2, 0, 0, '心理测量者SS2：第一卫士', 'PSYCHO-PASS サイコパス Sinners of the System Case.2「First Guardian」（2019）', 'xinliceliangzheSS2diyiweishi', 1, 'X', '', 'a0051b2e', '动作,战斗,科幻,犯罪', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2548995606.jpg', '', '', '', '东地宏树 / 有本钦隆 / 浅野真澄 / 寺杣昌纪 / 大原沙耶香 / 关智一 / 野岛健儿 / 石田彰 / 伊藤静 / 泽城美雪 / 本田贵子 / 花泽香菜 / 佐仓绫音', '盐谷直义', '', '', '常守朱が公安局刑事課一係に配属される前の2112年夏、沖縄。', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 2, 0, 2, 2, '', 0, 0, 8.0, 0, 0, 1740983131, 1740885320, 0, 0, 0, 0, 0.0, '', '1167', '', '', '', '', '', '', '', '<p>常守朱が公安局刑事課一係に配属される前の2112年夏、沖縄。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5027BC8DB84B5F5C50E978$$$正片$id_MOE5027BC8DB84B5F5C50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1167, 2, 0, 0, '心理测量者SS3：在恩怨的彼方', 'PSYCHO-PASS サイコパス Sinners of the System Case.3「恩讐の彼方に＿＿」（2019）', 'xinliceliangzheSS3zaienyuandebifang', 1, 'X', '', '82f5d5e', '动作,战斗,科幻,犯罪', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2570128450.jpg', '', '', '', '关智一 / 诸星堇 / 本田贵子 / 志村知幸 / 高木涉 / 鹤冈聪 / 樱井孝宏 / 佐佐木义人 / 若林佑 / 行成桃姬 / 广濑淳 / 藤沼建人 / 松田修平 / 堀聪十郎 / 相乐信赖 / 大西弘祐 / 大井麻利衣 / 夏川朋子 / 矶部勉', '盐谷直义', '', '', '2116年に起きた東南アジア連合・SEAUnでの事件後、狡噛慎也は放浪の旅を続けていた。南アジアの小国で、狡噛は武装ゲリラに襲われている難民を乗せたバスを救う。その中には、テンジンと名乗るひとりの少女', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 7.6, 0, 0, 1740989013, 1740885329, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>2116年に起きた東南アジア連合・SEAUnでの事件後、狡噛慎也は放浪の旅を続けていた。南アジアの小国で、狡噛は武装ゲリラに襲われている難民を乗せたバスを救う。その中には、テンジンと名乗るひとりの少女がいた。かたき討ちのために戦い方を学びたいと狡噛に懇願するテンジン。出口のない世界の縁辺で、復讐を望む少女と復讐を終えた男が見届ける、この世界の様相とは…。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0925EA8DED1C08144DE8$$$正片$id_MOE0925EA8DED1C08144DE8', '', '', '', '', 0, '', '');
