INSERT INTO `mac_vod` VALUES (1172, 1, 0, 0, '狂赌之渊 双', '賭ケグルイ 双（2022）', 'kuangduzhiyuanshuang', 1, 'K', '', 'd92156c', '漫画改,校园,竞技', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2723296572.jpg', '', '', '', '田中美海', '牧田佳织', '', '', '《#狂赌之渊#》外传动画《#狂赌之渊双#》视觉图公开！动画由#MAPPA#负责制作，将于2022年8月播出！', '全6集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 27, 0, 27, 27, '', 0, 0, 8.1, 0, 0, 1741006158, 1740958957, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《#狂赌之渊#》外传动画《#狂赌之渊双#》视觉图公开！动画由#MAPPA#负责制作，将于2022年8月播出！</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE552EBE89BC1F0E144DE8#第02集$MOE552EBE89BC1F0E144DEB#第03集$MOE552EBE89BC1F0E144DEA#第04集$MOE552EBE89BC1F0E144DED#第05集$MOE552EBE89BC1F0E144DEC#第06集$MOE552EBE89BC1F0E144DEF$$$第01集$id_XS552EBE89BC1F0E144DE8#第02集$id_XS552EBE89BC1F0E144DEB#第03集$id_XS552EBE89BC1F0E144DEA#第04集$id_XS552EBE89BC1F0E144DED#第05集$id_XS552EBE89BC1F0E144DEC#第06集$id_XS552EBE89BC1F0E144DEF$$$第01集$id_MOE552EBE89BC1F0E144DE8#第02集$id_MOE552EBE89BC1F0E144DEB#第03集$id_MOE552EBE89BC1F0E144DEA#第04集$id_MOE552EBE89BC1F0E144DED#第05集$id_MOE552EBE89BC1F0E144DEC#第06集$id_MOE552EBE89BC1F0E144DEF', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1173, 1, 0, 0, 'K', 'K-project（2012）', 'K', 1, 'K', '', '330c7795', '奇幻,战斗,声控', 'http://i0.hdslb.com/bfs/bangumi/2d8e0db5b60d2f2fa8dea5a1b3bcc5023bde69a2.jpg', '', '', '', '浪川大辅 / 杉田智和 / 福山润 / 宫野真守 / 津田健次郎 / 小松未可子 / 堀江由衣 / 泽城美雪 / 小野大辅 / 樱井孝宏', '鈴木信吾', '', '', '在与现实有着微妙差异的现代日本，存在着七位拥有巨大异能之力的“王”。他们将自己的力量分给族人们，并与族人们共同组成王族。“赤之王”周防尊率领的吠舞罗与“青之王”宗像礼司率领的Scepter4，因追赶作', '全13集', '', 0, '0', '', '', '日本', '日语', '2012', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 61, 0, 61, 61, '', 0, 0, 9.5, 0, 0, 1741069872, 1741001408, 0, 0, 0, 0, 0.0, '', '1174', '', '', '', '', '', '', '', '<p>在与现实有着微妙差异的现代日本，存在着七位拥有巨大异能之力的“王”。他们将自己的力量分给族人们，并与族人们共同组成王族。“赤之王”周防尊率领的吠舞罗与“青之王”宗像礼司率领的Scepter4，因追赶作为某起杀人事件的嫌疑人小白——也就是少年伊佐那社而对立。但小白自己却对这件事毫无记忆，什么都不知道的他尝试从吠舞罗的追杀中逃跑。之后，在小白的面前出现了身着黑服的纤细少年夜刀神狗朗。与他的邂逅，使小白的命运开始加速了……\r\n故事主要描绘了王权者们固执己见导致互相的争执、异能者之间的战斗，以及被卷入其中的少年的命运。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0224BCDBBE1E540C50E978#第02集$MOE0224BCDBBE1E540C50E97B#第03集$MOE0224BCDBBE1E540C50E97A#第04集$MOE0224BCDBBE1E540C50E97D#第05集$MOE0224BCDBBE1E540C50E97C#第06集$MOE0224BCDBBE1E540C50E97F#第07集$MOE0224BCDBBE1E540C50E97E#第08集$MOE0224BCDBBE1E540C50E971#第09集$MOE0224BCDBBE1E540C50E970#第10集$MOE0224BCDBBE1E540C50E879#第11集$MOE0224BCDBBE1E540C50E878#第12集$MOE0224BCDBBE1E540C50E87B#第13集$MOE0224BCDBBE1E540C50E87A$$$第01集$id_XS0224BCDBBE1E540C50E978#第02集$id_XS0224BCDBBE1E540C50E97B#第03集$id_XS0224BCDBBE1E540C50E97A#第04集$id_XS0224BCDBBE1E540C50E97D#第05集$id_XS0224BCDBBE1E540C50E97C#第06集$id_XS0224BCDBBE1E540C50E97F#第07集$id_XS0224BCDBBE1E540C50E97E#第08集$id_XS0224BCDBBE1E540C50E971#第09集$id_XS0224BCDBBE1E540C50E970#第10集$id_XS0224BCDBBE1E540C50E879#第11集$id_XS0224BCDBBE1E540C50E878#第12集$id_XS0224BCDBBE1E540C50E87B#第13集$id_XS0224BCDBBE1E540C50E87A$$$第01集$id_MOE0224BCDBBE1E540C50E978#第02集$id_MOE0224BCDBBE1E540C50E97B#第03集$id_MOE0224BCDBBE1E540C50E97A#第04集$id_MOE0224BCDBBE1E540C50E97D#第05集$id_MOE0224BCDBBE1E540C50E97C#第06集$id_MOE0224BCDBBE1E540C50E97F#第07集$id_MOE0224BCDBBE1E540C50E97E#第08集$id_MOE0224BCDBBE1E540C50E971#第09集$id_MOE0224BCDBBE1E540C50E970#第10集$id_MOE0224BCDBBE1E540C50E879#第11集$id_MOE0224BCDBBE1E540C50E878#第12集$id_MOE0224BCDBBE1E540C50E87B#第13集$id_MOE0224BCDBBE1E540C50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1174, 1, 0, 0, 'K RETURN OF KINGS', 'K RETURN OF KINGS（2015）', 'KRETURNOFKINGS', 1, 'K', '', 'b4090422', '声控,原创,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/902812752c6c021b7e8f75f30ea2d63db8d71d7e.jpg', '', '', '', '浪川大辅 / 小野大辅 / 小松未可子 / 堀江由衣 / 杉田智和 / 兴津和幸 / 樱井孝宏 / 福山润 / 中村悠一 / 泽城美雪 / 宫野真守 / 森田成一 / 名冢佳织 / 下野纮 / 津田健次郎 / 梶裕贵 / 饭冢昭三 / 佐藤聪美 / 钉宫理惠 / 大塚芳忠', '鈴木信吾', '', '', '在与现实有着微妙差异的现代日本，存在着七位拥有巨大异能之力的“王”。他们将自己的力量分给族人们，并与族人们共同组成王族。青色结晶的秩序、暴走的赤色之炎、白银的不变光辉、以及绿色分支的变革。持有各种属性', '全13集', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.3, 0, 0, 1741115512, 1741001414, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>在与现实有着微妙差异的现代日本，存在着七位拥有巨大异能之力的“王”。他们将自己的力量分给族人们，并与族人们共同组成王族。青色结晶的秩序、暴走的赤色之炎、白银的不变光辉、以及绿色分支的变革。持有各种属性的“王”们如今——\r\n率领青之王族“Scepter 4”的“青之王”宗像礼司担负着众多的重责。原本为“黄金之王”国常路大觉管理的御柱塔，以及诞生“王”的神秘圣遗物——德累斯顿石盘，如今也处在宗像礼司的管辖之下。此外，再加上杀死先代“赤之王”周防尊而产生的“弑王”的负担。\r\n另一方面，赤之王族“吠舞罗”的族人栉名安娜，经历绿之王族“jungle”发动的御柱塔袭击之后，作为新的“赤之王”而觉醒，与“吠舞罗”的同伴们再度结下强固的羁绊。\r\n此外，白银的族人NEKO和夜刀神狗朗坚信“白银之王”伊佐那社仍然存活，寻找着他的下落。\r\n但寻找“白银之王”的并不只有他们而已。“绿之王”比水流也在寻找——\r\n以活性化的“jungle”的行动为契机，“王”们的命运再度重合。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5323BC81B91D5F0B50E978#第02集$MOE5323BC81B91D5F0B50E97B#第03集$MOE5323BC81B91D5F0B50E97A#第04集$MOE5323BC81B91D5F0B50E97D#第05集$MOE5323BC81B91D5F0B50E97C#第06集$MOE5323BC81B91D5F0B50E97F#第07集$MOE5323BC81B91D5F0B50E97E#第08集$MOE5323BC81B91D5F0B50E971#第09集$MOE5323BC81B91D5F0B50E970#第10集$MOE5323BC81B91D5F0B50E879#第11集$MOE5323BC81B91D5F0B50E878#第12集$MOE5323BC81B91D5F0B50E87B#第13集$MOE5323BC81B91D5F0B50E87A$$$第01集$id_XS5323BC81B91D5F0B50E978#第02集$id_XS5323BC81B91D5F0B50E97B#第03集$id_XS5323BC81B91D5F0B50E97A#第04集$id_XS5323BC81B91D5F0B50E97D#第05集$id_XS5323BC81B91D5F0B50E97C#第06集$id_XS5323BC81B91D5F0B50E97F#第07集$id_XS5323BC81B91D5F0B50E97E#第08集$id_XS5323BC81B91D5F0B50E971#第09集$id_XS5323BC81B91D5F0B50E970#第10集$id_XS5323BC81B91D5F0B50E879#第11集$id_XS5323BC81B91D5F0B50E878#第12集$id_XS5323BC81B91D5F0B50E87B#第13集$id_XS5323BC81B91D5F0B50E87A$$$第01集$id_MOE5323BC81B91D5F0B50E978#第02集$id_MOE5323BC81B91D5F0B50E97B#第03集$id_MOE5323BC81B91D5F0B50E97A#第04集$id_MOE5323BC81B91D5F0B50E97D#第05集$id_MOE5323BC81B91D5F0B50E97C#第06集$id_MOE5323BC81B91D5F0B50E97F#第07集$id_MOE5323BC81B91D5F0B50E97E#第08集$id_MOE5323BC81B91D5F0B50E971#第09集$id_MOE5323BC81B91D5F0B50E970#第10集$id_MOE5323BC81B91D5F0B50E879#第11集$id_MOE5323BC81B91D5F0B50E878#第12集$id_MOE5323BC81B91D5F0B50E87B#第13集$id_MOE5323BC81B91D5F0B50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1175, 2, 0, 0, 'K MISSING KINGS', '劇場版 K MISSING KINGS（2014）', 'KMISSINGKINGS', 1, 'K', '', 'dceb708d', '奇幻,战斗,声控', 'http://i0.hdslb.com/bfs/bangumi/ff85b64a18556bb5c0a28a2168048f7cd3721ce3.jpg', '', '', '', '浪川大辅 / 小野大辅 / 小松未可子 / 杉田智和 / 堀江由衣 / 兴津和幸 / 森田成一 / 下野纮 / 津田健次郎 / 梶裕贵 / 樱井孝宏 / 福山润 / 中村悠一 / 泽城美雪 / 宫野真守 / 速水奖 / 佐藤聪美 / 名冢佳织 / 浅沼晋太郎 / 柳田淳一 / 饭塚昭三 / 村田知沙', '铃木信吾', '', '', '《K MISSING KINGS》是电视动画《K》的剧场版动画，2014年7月12日于日本上映。\r\n主要讲述了赤之氏族“吠舞罗”的族人栉名安娜，经历绿之氏族“jungle”发动的御柱塔袭击之后，作为新的', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 20, 0, 20, 20, '', 0, 0, 9.5, 0, 0, 1741120247, 1741001419, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>《K MISSING KINGS》是电视动画《K》的剧场版动画，2014年7月12日于日本上映。\r\n主要讲述了赤之氏族“吠舞罗”的族人栉名安娜，经历绿之氏族“jungle”发动的御柱塔袭击之后，作为新的“赤之王”而觉醒，与吠舞罗的同伴们再度结下强固羁绊的故事。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5574E9DABE19555D50E978$$$正片$id_MOE5574E9DABE19555D50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1176, 2, 0, 0, '剧场版 K Seven Stories', 'K SEVEN STORIES（2018）', 'juchangbanKSevenStories', 1, 'J', '', '47d89d19', '声控,原创,奇幻,战斗', 'http://i0.hdslb.com/bfs/bangumi/a1412083624cfcae7fb07ed4191710a0ac5ac31b.jpg', '', '', '', '津田健次郎 / 杉田智和 / 樱井孝宏 / 梶裕贵 / 堀江由衣 / 福山润 / 宫野真守 / 中村悠一 / 泽城美雪 / 八代拓 / 浪川大辅 / 小野大辅 / 兴津和幸 / 神谷浩史', '铃木信吾', '', '', '以类似现代日本为背景所创作的《K》，讲述围绕在七位王权者和关系人物的故事，结合了刺激的异能战斗，角色的因缘纠葛和细致的美型人物设定也是一大亮点。\r\n随着TV动画的剧情，七位王权者和其氏族的相互竞合，一步', '全6章 SP', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 5, 0, 5, 5, '', 0, 0, 9.7, 0, 0, 1741141776, 1741001425, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>以类似现代日本为背景所创作的《K》，讲述围绕在七位王权者和关系人物的故事，结合了刺激的异能战斗，角色的因缘纠葛和细致的美型人物设定也是一大亮点。\r\n随着TV动画的剧情，七位王权者和其氏族的相互竞合，一步步解开了异能的来源「德累斯顿石板」以及主角「伊佐那社」的秘密。\r\n\r\n故事在TV动画已有完整结局，\r\n本次剧场版《K SEVEN STORIES》则是补全各王权者和主要角色的过去和未来，每2话为一个章节，共6章节。\r\n在六章节之后，还会有OVA《THE 偶像·K》，关于“如果「K」中的各角色化身为偶像”之后发生的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第一章(上)$MOE0520E880B04D5C0050E978#第一章(下)$MOE0520E880B04D5C0050E97B#第二章(上)$MOE0520E880B04D5C0050E97A#第二章(下)$MOE0520E880B04D5C0050E97D#第三章(上)$MOE0520E880B04D5C0050E97C#第三章(下)$MOE0520E880B04D5C0050E97F#第四章(上)$MOE0520E880B04D5C0050E97E#第四章(下)$MOE0520E880B04D5C0050E971#第五章(上)$MOE0520E880B04D5C0050E970#第五章(下)$MOE0520E880B04D5C0050E879#第六章(上)$MOE0520E880B04D5C0050E878#第六章(下)$MOE0520E880B04D5C0050E87B#SP$MOE0520E880B04D5C0050E87A$$$第一章(上)$id_XS0520E880B04D5C0050E978#第一章(下)$id_XS0520E880B04D5C0050E97B#第二章(上)$id_XS0520E880B04D5C0050E97A#第二章(下)$id_XS0520E880B04D5C0050E97D#第三章(上)$id_XS0520E880B04D5C0050E97C#第三章(下)$id_XS0520E880B04D5C0050E97F#第四章(上)$id_XS0520E880B04D5C0050E97E#第四章(下)$id_XS0520E880B04D5C0050E971#第五章(上)$id_XS0520E880B04D5C0050E970#第五章(下)$id_XS0520E880B04D5C0050E879#第六章(上)$id_XS0520E880B04D5C0050E878#第六章(下)$id_XS0520E880B04D5C0050E87B#SP$id_XS0520E880B04D5C0050E87A$$$第一章(上)$id_MOE0520E880B04D5C0050E978#第一章(下)$id_MOE0520E880B04D5C0050E97B#第二章(上)$id_MOE0520E880B04D5C0050E97A#第二章(下)$id_MOE0520E880B04D5C0050E97D#第三章(上)$id_MOE0520E880B04D5C0050E97C#第三章(下)$id_MOE0520E880B04D5C0050E97F#第四章(上)$id_MOE0520E880B04D5C0050E97E#第四章(下)$id_MOE0520E880B04D5C0050E971#第五章(上)$id_MOE0520E880B04D5C0050E970#第五章(下)$id_MOE0520E880B04D5C0050E879#第六章(上)$id_MOE0520E880B04D5C0050E878#第六章(下)$id_MOE0520E880B04D5C0050E87B#SP$id_MOE0520E880B04D5C0050E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1177, 1, 0, 0, '处刑少女的生存之道', '処刑少女の生きる道（2022）', 'chuxingshaonvdeshengcunzhidao', 1, 'C', '', '96a529c5', '小说改,战斗,奇幻', 'http://i0.hdslb.com/bfs/bangumi/image/bd276c9f3badd3ec93e2a1c4dac59a4295ca78d3.jpg', '', '', '', '佐伯伊织 / 佳原萌枝 / 金元寿子 / 市道真央 / 内田雄马 / 甲斐田裕子 / 久保田民绘 / 石见舞菜香 / 春野杏 / 渡边明乃', '川崎芳树 / 樱美胜志 / 岩崎良明 / 野上良之 / 上田茂 / 森义博', '', '', '曾经来自日本，给世界带来巨大灾害的「迷途者」。\r\n他们过去给世界带来了毁灭性的灾祸，因此被定为了「禁忌」，必须秘密将其处刑。\r\n以处刑「迷途者」为职的「处刑人」玛瑙在某一天遇见了日本少女灯里。\r\n玛瑙本打算', '全12集', '', 0, '0', '', '', '日本', '日语', '2022', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 8.3, 0, 0, 1741081324, 1741064067, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>曾经来自日本，给世界带来巨大灾害的「迷途者」。\r\n他们过去给世界带来了毁灭性的灾祸，因此被定为了「禁忌」，必须秘密将其处刑。\r\n以处刑「迷途者」为职的「处刑人」玛瑙在某一天遇见了日本少女灯里。\r\n玛瑙本打算像往常一样执行任务，却因灯里的「某种能力」以失败告终。\r\n为完成对灯里的处刑，玛瑙带上了她，踏上了前往能讨伐一切异世界人的仪式场——加尔姆大圣堂的旅途。\r\n但灯里并不知晓此行的目的，她纯粹地享受着旅途的乐趣。这让玛瑙的内心渐渐发生了转变。\r\n这，是她为了杀死她的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0821ED8DBB100E0C50E978#第02集$MOE0821ED8DBB100E0C50E97B#第03集$MOE0821ED8DBB100E0C50E97A#第04集$MOE0821ED8DBB100E0C50E97D#第05集$MOE0821ED8DBB100E0C50E97C#第06集$MOE0821ED8DBB100E0C50E97F#第07集$MOE0821ED8DBB100E0C50E97E#第08集$MOE0821ED8DBB100E0C50E971#第09集$MOE0821ED8DBB100E0C50E970#第10集$MOE0821ED8DBB100E0C50E879#第11集$MOE0821ED8DBB100E0C50E878#第12集$MOE0821ED8DBB100E0C50E87B$$$第01集$id_XS0821ED8DBB100E0C50E978#第02集$id_XS0821ED8DBB100E0C50E97B#第03集$id_XS0821ED8DBB100E0C50E97A#第04集$id_XS0821ED8DBB100E0C50E97D#第05集$id_XS0821ED8DBB100E0C50E97C#第06集$id_XS0821ED8DBB100E0C50E97F#第07集$id_XS0821ED8DBB100E0C50E97E#第08集$id_XS0821ED8DBB100E0C50E971#第09集$id_XS0821ED8DBB100E0C50E970#第10集$id_XS0821ED8DBB100E0C50E879#第11集$id_XS0821ED8DBB100E0C50E878#第12集$id_XS0821ED8DBB100E0C50E87B$$$第01集$id_MOE0821ED8DBB100E0C50E978#第02集$id_MOE0821ED8DBB100E0C50E97B#第03集$id_MOE0821ED8DBB100E0C50E97A#第04集$id_MOE0821ED8DBB100E0C50E97D#第05集$id_MOE0821ED8DBB100E0C50E97C#第06集$id_MOE0821ED8DBB100E0C50E97F#第07集$id_MOE0821ED8DBB100E0C50E97E#第08集$id_MOE0821ED8DBB100E0C50E971#第09集$id_MOE0821ED8DBB100E0C50E970#第10集$id_MOE0821ED8DBB100E0C50E879#第11集$id_MOE0821ED8DBB100E0C50E878#第12集$id_MOE0821ED8DBB100E0C50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1178, 1, 0, 0, '龙娘七七七埋藏的宝藏', '龍ヶ嬢七々々の埋蔵金（2014）', 'longniangqiqiqimaicangdebaocang', 1, 'L', '', '27f80471', '奇幻,日常,推理', 'http://i0.hdslb.com/bfs/bangumi/image/3bc752c31a8bbb2b6c8da615201b56d228c312e2.jpg', '', '', '', '小野友树 / 田边留依 / 阿澄佳奈 / 花泽香菜 / 兴津和幸 / 铃木绘理 / 早志勇纪 / 能登麻美子 / 鸟海浩辅 / 内山夕实 / 伊藤加奈惠 / 樱井浩美 / 细谷佳正', '龟井干太 / 柴田彰久 / 安藤贵史 / 河合滋树', '', '', '男主角八真重护因不愿意继承家业，而被父亲宣告断绝亲子关系，并被迫离家搬到一座人工学园岛居住。为了节省开支，八真重护预付了一年的房租，住到了一个月仅需5000日元的幸福庄202号室。但那间房内却有一位名', '全11集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 9.0, 0, 0, 1741088203, 1741064076, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>男主角八真重护因不愿意继承家业，而被父亲宣告断绝亲子关系，并被迫离家搬到一座人工学园岛居住。为了节省开支，八真重护预付了一年的房租，住到了一个月仅需5000日元的幸福庄202号室。但那间房内却有一位名为“龙娘七七七”的地缚灵？！\r\n龙娘七七七本是建立人工学园岛的天才学生集团“Great 7”的成员之一，但某天却惨遭杀害，除非找出凶手，否则她的魂魄就无法离开房间。于是，八真重护开始了与她的同居生活。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0320EA80B91D5A0850E978#第02集$MOE0320EA80B91D5A0850E97B#第03集$MOE0320EA80B91D5A0850E97A#第04集$MOE0320EA80B91D5A0850E97D#第05集$MOE0320EA80B91D5A0850E97C#第06集$MOE0320EA80B91D5A0850E97F#第07集$MOE0320EA80B91D5A0850E97E#第08集$MOE0320EA80B91D5A0850E971#第09集$MOE0320EA80B91D5A0850E970#第10集$MOE0320EA80B91D5A0850E879#第11集$MOE0320EA80B91D5A0850E878$$$第01集$id_XS0320EA80B91D5A0850E978#第02集$id_XS0320EA80B91D5A0850E97B#第03集$id_XS0320EA80B91D5A0850E97A#第04集$id_XS0320EA80B91D5A0850E97D#第05集$id_XS0320EA80B91D5A0850E97C#第06集$id_XS0320EA80B91D5A0850E97F#第07集$id_XS0320EA80B91D5A0850E97E#第08集$id_XS0320EA80B91D5A0850E971#第09集$id_XS0320EA80B91D5A0850E970#第10集$id_XS0320EA80B91D5A0850E879#第11集$id_XS0320EA80B91D5A0850E878$$$第01集$id_MOE0320EA80B91D5A0850E978#第02集$id_MOE0320EA80B91D5A0850E97B#第03集$id_MOE0320EA80B91D5A0850E97A#第04集$id_MOE0320EA80B91D5A0850E97D#第05集$id_MOE0320EA80B91D5A0850E97C#第06集$id_MOE0320EA80B91D5A0850E97F#第07集$id_MOE0320EA80B91D5A0850E97E#第08集$id_MOE0320EA80B91D5A0850E971#第09集$id_MOE0320EA80B91D5A0850E970#第10集$id_MOE0320EA80B91D5A0850E879#第11集$id_MOE0320EA80B91D5A0850E878', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1179, 1, 0, 0, '暗黑破坏神在身边。', 'ぼくのとなりに暗黒破壊神がいます。（2020）', 'anheipohuaishenzaishenbian', 1, 'A', '', 'c9db298', '漫画改,日常,搞笑,声控', 'http://i0.hdslb.com/bfs/bangumi/image/6272d50bfa30e13e98bc6f78e7e86ca7745a4c72.jpg', '', '', '', '福山润 / 樱井孝宏 / 木村良平 / 代永翼 / 立花慎之介 / 鸟海浩辅 / 茅野爱衣 / 生田善子 / 增田俊树 / 近藤孝行 / 赤崎千夏', '浊川敦 / 嵯峨敏 / 星野真 / 南康宏 / 粟井重纪', '', '', '围绕主人公小雪芹和其中二病好友花鸟兜展开的校园喜剧故事：拥有吐槽体质的小雪芹，最怕槽点满满等他吐槽的人，而升为高中生还患有重度中二病的兜，深切盼望着小雪芹的吐槽而想尽办法接近他，这两个人究竟会如何相处', '全12集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 12, 0, 12, 12, '', 0, 0, 9.2, 0, 0, 1741095176, 1741064087, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>围绕主人公小雪芹和其中二病好友花鸟兜展开的校园喜剧故事：拥有吐槽体质的小雪芹，最怕槽点满满等他吐槽的人，而升为高中生还患有重度中二病的兜，深切盼望着小雪芹的吐槽而想尽办法接近他，这两个人究竟会如何相处呢？以及身边其他个性鲜明的同学们，每天都充实着可爱又爆笑的校园趣事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE522EE8DABB1055144DE8#第02集$MOE522EE8DABB1055144DEB#第03集$MOE522EE8DABB1055144DEA#第04集$MOE522EE8DABB1055144DED#第05集$MOE522EE8DABB1055144DEC#第06集$MOE522EE8DABB1055144DEF#第07集$MOE522EE8DABB1055144DEE#第08集$MOE522EE8DABB1055144DE1#第09集$MOE522EE8DABB1055144DE0#第10集$MOE522EE8DABB1055144CE9#第11集$MOE522EE8DABB1055144CE8#第12集$MOE522EE8DABB1055144CEB$$$第01集$id_XS522EE8DABB1055144DE8#第02集$id_XS522EE8DABB1055144DEB#第03集$id_XS522EE8DABB1055144DEA#第04集$id_XS522EE8DABB1055144DED#第05集$id_XS522EE8DABB1055144DEC#第06集$id_XS522EE8DABB1055144DEF#第07集$id_XS522EE8DABB1055144DEE#第08集$id_XS522EE8DABB1055144DE1#第09集$id_XS522EE8DABB1055144DE0#第10集$id_XS522EE8DABB1055144CE9#第11集$id_XS522EE8DABB1055144CE8#第12集$id_XS522EE8DABB1055144CEB$$$第01集$id_MOE522EE8DABB1055144DE8#第02集$id_MOE522EE8DABB1055144DEB#第03集$id_MOE522EE8DABB1055144DEA#第04集$id_MOE522EE8DABB1055144DED#第05集$id_MOE522EE8DABB1055144DEC#第06集$id_MOE522EE8DABB1055144DEF#第07集$id_MOE522EE8DABB1055144DEE#第08集$id_MOE522EE8DABB1055144DE1#第09集$id_MOE522EE8DABB1055144DE0#第10集$id_MOE522EE8DABB1055144CE9#第11集$id_MOE522EE8DABB1055144CE8#第12集$id_MOE522EE8DABB1055144CEB', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1180, 1, 0, 0, '全修。', 'Zenshuu. / ZENSHU（2025）', 'quanxiu', 1, 'Q', '', 'd8507a64', '原创,异世界,奇幻,职场', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2918994422.jpg', '', '', '', '永濑安奈 / 浦和希 / 钉宫理惠 / 铃木实里 / 陶山章央 / 朴璐美 / 石见舞菜香 / 利根健太朗 / 山根雅史 / 宝龟克寿 / 大原沙耶香', '山崎光惠', '', '', '广濑夏子高中毕业后成为了一名原画师， 迅速展现出自己的才华，并很快以导演身份出道。 首次导演的作品成了社会现象般的大作，广受好评。 夏子被评价为新锐天才导演， 并决定下一部作品是以初恋为主题的剧场恋爱', '全12集', '', 0, '0', '', '', '日本', '一月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 158, 0, 158, 158, '', 0, 0, 7.6, 0, 0, 1743449771, 1741135035, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>广濑夏子高中毕业后成为了一名原画师， 迅速展现出自己的才华，并很快以导演身份出道。 首次导演的作品成了社会现象般的大作，广受好评。 夏子被评价为新锐天才导演， 并决定下一部作品是以初恋为主题的剧场恋爱喜剧。 然而，从未体验过恋爱的夏子对初恋毫无概念， 因而无法创作分镜，电影制作也陷入僵局。 某天在绘制分镜时，夏子突然失去了意识，当她醒来时， 发现自己已经身处于小时候沉迷的动画电影《灭亡物语》的世界之中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE552FB988BE485B0D50E978#第02集$MOE552FB988BE485B0D50E97B#第03集$MOE552FB988BE485B0D50E97A#第04集$MOE552FB988BE485B0D50E97D#第05集$MOE552FB988BE485B0D50E97C#第06集$MOE552FB988BE485B0D50E97F#第07集$MOE552FB988BE485B0D50E97E#第08集$MOE552FB988BE485B0D50E971#第09集$MOE552FB988BE485B0D50E970#第10集$MOE552FB988BE485B0D50E879#第11集$MOE552FB988BE485B0D50E878#第12集$MOE552FB988BE485B0D50E87B$$$第01集$id_XS552FB988BE485B0D50E978#第02集$id_XS552FB988BE485B0D50E97B#第03集$id_XS552FB988BE485B0D50E97A#第04集$id_XS552FB988BE485B0D50E97D#第05集$id_XS552FB988BE485B0D50E97C#第06集$id_XS552FB988BE485B0D50E97F#第07集$id_XS552FB988BE485B0D50E97E#第08集$id_XS552FB988BE485B0D50E971#第09集$id_XS552FB988BE485B0D50E970#第10集$id_XS552FB988BE485B0D50E879#第11集$id_XS552FB988BE485B0D50E878#第12集$id_XS552FB988BE485B0D50E87B$$$第01集$id_MOE552FB988BE485B0D50E978#第02集$id_MOE552FB988BE485B0D50E97B#第03集$id_MOE552FB988BE485B0D50E97A#第04集$id_MOE552FB988BE485B0D50E97D#第05集$id_MOE552FB988BE485B0D50E97C#第06集$id_MOE552FB988BE485B0D50E97F#第07集$id_MOE552FB988BE485B0D50E97E#第08集$id_MOE552FB988BE485B0D50E971#第09集$id_MOE552FB988BE485B0D50E970#第10集$id_MOE552FB988BE485B0D50E879#第11集$id_MOE552FB988BE485B0D50E878#第12集$id_MOE552FB988BE485B0D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1181, 2, 0, 0, '从很久以前就喜欢你了。～告白实行委员会～', 'ずっと前から好きでした。～告白実行委員会～（2016）', 'conghenjiuyiqianjiuxihuanniliaogaobaishixingweiyuanhui', 1, 'C', '', 'd6772780', '声控,校园,音乐,恋爱', 'http://i0.hdslb.com/bfs/bangumi/1eaf4c554ba073db011da2d80b5abda7960321e1.jpg', '', '', '', '神谷浩史 / 户松遥 / 梶裕贵 / 阿澄佳奈 / 铃村健一 / 丰崎爱生 / 代永翼 / 麻仓桃 / 花江夏树 / 绿川光 / 雨宫天', '柳泽哲也', '', '', '因为这是最后的练习——。\r\n樱丘高中三年级的榎本夏树，单恋着青梅竹马的濑户口优。\r\n但，她无法变得坦率，于是说要把优当做告白的“练习”对象。\r\n在一直隐藏着真正心情的过程中，\r\n夏树被同班同学绫濑恋雪邀请去约', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.5, 0, 0, 1741270382, 1741241468, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>因为这是最后的练习——。\r\n樱丘高中三年级的榎本夏树，单恋着青梅竹马的濑户口优。\r\n但，她无法变得坦率，于是说要把优当做告白的“练习”对象。\r\n在一直隐藏着真正心情的过程中，\r\n夏树被同班同学绫濑恋雪邀请去约会……？\r\n夏树的“练习”能否演变成为“正戏”！？</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5521BB8FBB1E550950E978$$$正片$id_MOE5521BB8FBB1E550950E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1182, 2, 0, 0, '喜欢上你的那个瞬间。～告白实行委员会～', '好きになるその瞬間を。～告白実行委員会～（2016）', 'xihuanshangnidenageshunjiangaobaishixingweiyuanhui', 1, 'X', '', 'd211d801', '恋爱,校园,声控', 'http://i0.hdslb.com/bfs/bangumi/6b65635d175e21331a072e012d37d08a28c447f4.jpg', '', '', '', '麻仓桃 / 花江夏树 / 代永翼 / 细谷佳正 / 松冈祯丞 / 东山奈央 / 神谷浩史 / 户松遥 / 梶裕贵 / 阿澄佳奈 / 铃村健一 / 丰崎爱生 / 雨宫天 / Gero', '柳泽哲也', '', '', '明明是最差劲的相遇，但雏却不知何时开始无法停止心动。雏被初中时的学长·恋雪所吸引，决定和他进入同所高中而拼命学习。\r\n并且，和青梅竹马的虎太朗一同进入了樱丘高中。\r\n曾经单调乏味的恋雪，为了自己单相思的对', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2016', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 9.6, 0, 0, 1741270460, 1741241475, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>明明是最差劲的相遇，但雏却不知何时开始无法停止心动。雏被初中时的学长·恋雪所吸引，决定和他进入同所高中而拼命学习。\r\n并且，和青梅竹马的虎太朗一同进入了樱丘高中。\r\n曾经单调乏味的恋雪，为了自己单相思的对象，而在假日结束后改换了形象，变得受欢迎起来。\r\n在这种状况下，雏决定要「告白」，但是——！？</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5525BD89ED115D0850E978$$$正片$id_MOE5525BD89ED115D0850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1183, 1, 0, 0, '无论何时我们的恋情都是10厘米。～告白实行委员会～', 'いつだって僕らの恋は10センチだった。（2017）', 'wulunheshiwomendelianqingdushi10limigaobaishixingweiyuanhui', 1, 'W', '', '127c8dd8', '恋爱,音乐,原创,校园', 'http://i0.hdslb.com/bfs/bangumi/f32f0f1390015c98aae1839e75fb1860065d8994.jpg', '', '', '', '铃村健一 / 丰崎爱生 / 神谷浩史 / 户松遥 / 梶裕贵 / 阿澄佳奈 / 绿川光 / Gero / 木村良平 / 莉犬', '难波日登志 / 塚田拓郎', '', '', 'TV动画以《无论何时我们的恋情都是10厘米。》为题，于2017年11月25日开始播出，全6话。主角是芹泽春辉和合田美樱。', '全6集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 13, 0, 13, 13, '', 0, 0, 9.6, 0, 0, 1741275076, 1741241482, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>TV动画以《无论何时我们的恋情都是10厘米。》为题，于2017年11月25日开始播出，全6话。主角是芹泽春辉和合田美樱。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0025BBDBB14D090150E978#第02集$MOE0025BBDBB14D090150E97B#第03集$MOE0025BBDBB14D090150E97A#第04集$MOE0025BBDBB14D090150E97D#第05集$MOE0025BBDBB14D090150E97C#第06集$MOE0025BBDBB14D090150E97F$$$第01集$id_XS0025BBDBB14D090150E978#第02集$id_XS0025BBDBB14D090150E97B#第03集$id_XS0025BBDBB14D090150E97A#第04集$id_XS0025BBDBB14D090150E97D#第05集$id_XS0025BBDBB14D090150E97C#第06集$id_XS0025BBDBB14D090150E97F$$$第01集$id_MOE0025BBDBB14D090150E978#第02集$id_MOE0025BBDBB14D090150E97B#第03集$id_MOE0025BBDBB14D090150E97A#第04集$id_MOE0025BBDBB14D090150E97D#第05集$id_MOE0025BBDBB14D090150E97C#第06集$id_MOE0025BBDBB14D090150E97F', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1184, 1, 0, 0, '神之塔', '神之塔 -Tower of God-（2020）', 'shenzhita', 1, 'S', '', 'a009d670', '漫画改,战斗,奇幻,冒险', 'http://i0.hdslb.com/bfs/bangumi/image/b7ce6fd3aacb2edd1bd75e368e8838c2d768dab8.png', '', '', '', '市川太一 / 早见沙织 / 大塚芳忠 / 冈本信彦 / 三宅健太 / 本多真梨子 / 兴津和幸 / 江口拓也 / 深町寿成 / 末柄里惠 / 关根明良', '佐野隆史 / 村田雅彦 / 矢野雄一郎 / 松村树里亚 / 工藤宽显 / 土屋康郎 / 佐藤光', '', '', '只要登上塔，就能得到任何想要得东西。\r\n塔顶上有着这世界上的一切，登上塔顶的人可以主宰这个世界……甚至成为神。\r\n这是为了追逐星空而登塔的少女·蕾哈尔，\r\n以及只要有了蕾哈尔就什么也不需要了的少年·第二十五', '全13集', '', 0, '0', '', '', '日本', '日语', '2020', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 10, 0, 10, 10, '', 0, 0, 9.3, 0, 0, 1741270258, 1741242122, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>只要登上塔，就能得到任何想要得东西。\r\n塔顶上有着这世界上的一切，登上塔顶的人可以主宰这个世界……甚至成为神。\r\n这是为了追逐星空而登塔的少女·蕾哈尔，\r\n以及只要有了蕾哈尔就什么也不需要了的少年·第二十五夜的，\r\n“完结”与“开始”的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5027BC81ED1F5A0950E978#第02集$MOE5027BC81ED1F5A0950E97B#第03集$MOE5027BC81ED1F5A0950E97A#第04集$MOE5027BC81ED1F5A0950E97D#第05集$MOE5027BC81ED1F5A0950E97C#第06集$MOE5027BC81ED1F5A0950E97F#第07集$MOE5027BC81ED1F5A0950E97E#第08集$MOE5027BC81ED1F5A0950E971#第09集$MOE5027BC81ED1F5A0950E970#第10集$MOE5027BC81ED1F5A0950E879#第11集$MOE5027BC81ED1F5A0950E878#第12集$MOE5027BC81ED1F5A0950E87B#第13集$MOE5027BC81ED1F5A0950E87A$$$第01集$id_XS5027BC81ED1F5A0950E978#第02集$id_XS5027BC81ED1F5A0950E97B#第03集$id_XS5027BC81ED1F5A0950E97A#第04集$id_XS5027BC81ED1F5A0950E97D#第05集$id_XS5027BC81ED1F5A0950E97C#第06集$id_XS5027BC81ED1F5A0950E97F#第07集$id_XS5027BC81ED1F5A0950E97E#第08集$id_XS5027BC81ED1F5A0950E971#第09集$id_XS5027BC81ED1F5A0950E970#第10集$id_XS5027BC81ED1F5A0950E879#第11集$id_XS5027BC81ED1F5A0950E878#第12集$id_XS5027BC81ED1F5A0950E87B#第13集$id_XS5027BC81ED1F5A0950E87A$$$第01集$id_MOE5027BC81ED1F5A0950E978#第02集$id_MOE5027BC81ED1F5A0950E97B#第03集$id_MOE5027BC81ED1F5A0950E97A#第04集$id_MOE5027BC81ED1F5A0950E97D#第05集$id_MOE5027BC81ED1F5A0950E97C#第06集$id_MOE5027BC81ED1F5A0950E97F#第07集$id_MOE5027BC81ED1F5A0950E97E#第08集$id_MOE5027BC81ED1F5A0950E971#第09集$id_MOE5027BC81ED1F5A0950E970#第10集$id_MOE5027BC81ED1F5A0950E879#第11集$id_MOE5027BC81ED1F5A0950E878#第12集$id_MOE5027BC81ED1F5A0950E87B#第13集$id_MOE5027BC81ED1F5A0950E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1185, 1, 0, 0, 'Free!', '男子游泳部 第一季（2013）', 'Free', 1, 'F', '', 'ca58b494', '校园,运动', 'https://i0.hdslb.com/bfs/bangumi/46872e4e59ee0e3e3afc8479ba5a2f6a3c266671.jpg', '', '', '', '岛崎信长 / 铃木达央 / 平川大辅 / 宫野真守 / 代永翼', '内海纮子 / 山田尚子 / 武本康弘 / 北之原孝将 / 小川太一 / 河浪荣作 / 木上益治', '', '', '小学时期，四位隶属游泳学会的成员于毕业前的大会夺得冠军，留下难忘的回忆后分道扬镳。时移世逆，于高中生活变得黯然无光的一位成员七濑遥，于某天突然遇上昔日的战友松冈凛。遥一边怀旧的同时向凛提出挑战，结果被', '全12集', '', 0, '0', '', '', '日本', '日语', '2013', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 26, 0, 26, 26, '', 0, 0, 9.4, 0, 0, 1741302777, 1741242499, 0, 0, 0, 0, 0.0, '', '1186,1187', '', '', '', '', '', '', '', '<p>小学时期，四位隶属游泳学会的成员于毕业前的大会夺得冠军，留下难忘的回忆后分道扬镳。时移世逆，于高中生活变得黯然无光的一位成员七濑遥，于某天突然遇上昔日的战友松冈凛。遥一边怀旧的同时向凛提出挑战，结果被对方压倒性击倒。以此为契机，遥决定跟目前同校的橘真琴和叶月渚重新集结，加上新成员龙崎怜，成立岩鸢高中的首个游泳部。充满跃动感的男子高中生，带着份外瞩目的上半身，展开了这个关于游泳、青春与羁绊的故事……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5276B980EB1D540D50E978#第02集$MOE5276B980EB1D540D50E97B#第03集$MOE5276B980EB1D540D50E97A#第04集$MOE5276B980EB1D540D50E97D#第05集$MOE5276B980EB1D540D50E97C#第06集$MOE5276B980EB1D540D50E97F#第07集$MOE5276B980EB1D540D50E97E#第08集$MOE5276B980EB1D540D50E971#第09集$MOE5276B980EB1D540D50E970#第10集$MOE5276B980EB1D540D50E879#第11集$MOE5276B980EB1D540D50E878#第12集$MOE5276B980EB1D540D50E87B$$$第01集$id_XS5276B980EB1D540D50E978#第02集$id_XS5276B980EB1D540D50E97B#第03集$id_XS5276B980EB1D540D50E97A#第04集$id_XS5276B980EB1D540D50E97D#第05集$id_XS5276B980EB1D540D50E97C#第06集$id_XS5276B980EB1D540D50E97F#第07集$id_XS5276B980EB1D540D50E97E#第08集$id_XS5276B980EB1D540D50E971#第09集$id_XS5276B980EB1D540D50E970#第10集$id_XS5276B980EB1D540D50E879#第11集$id_XS5276B980EB1D540D50E878#第12集$id_XS5276B980EB1D540D50E87B$$$第01集$id_MOE5276B980EB1D540D50E978#第02集$id_MOE5276B980EB1D540D50E97B#第03集$id_MOE5276B980EB1D540D50E97A#第04集$id_MOE5276B980EB1D540D50E97D#第05集$id_MOE5276B980EB1D540D50E97C#第06集$id_MOE5276B980EB1D540D50E97F#第07集$id_MOE5276B980EB1D540D50E97E#第08集$id_MOE5276B980EB1D540D50E971#第09集$id_MOE5276B980EB1D540D50E970#第10集$id_MOE5276B980EB1D540D50E879#第11集$id_MOE5276B980EB1D540D50E878#第12集$id_MOE5276B980EB1D540D50E87B', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1186, 1, 0, 0, 'Free! -Eternal Summer-', '男子游泳部 第二季（2014）', 'FreeEternalSummer', 1, 'F', '', '5697713c', '校园,运动', 'https://i0.hdslb.com/bfs/bangumi/d044295f382a3f992c0c240e91e17139ce7f6fce.jpg', '', '', '', '岛崎信长 / 宫野真守 / 平川大辅 / 代永翼', '内海纮子 / 山田尚子 / 北之原孝将 / 藤田春香 / 小川太一 / 山村卓也 / 河浪荣作', '', '', '经历了上一次的比赛后，进一步加深感情的遥、真琴、渚、怜在不变的日常生活中，都显示出了各自不断成长的姿态。另一方面，凛战胜过去的自己向自己的梦想前进，并且与新的伙伴一同以最棒的队伍作为目标而努力着。他们', '全13集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 25, 0, 25, 25, '', 0, 0, 9.7, 0, 0, 1741312441, 1741242506, 0, 0, 0, 0, 0.0, '', '1187', '', '', '', '', '', '', '', '<p>经历了上一次的比赛后，进一步加深感情的遥、真琴、渚、怜在不变的日常生活中，都显示出了各自不断成长的姿态。另一方面，凛战胜过去的自己向自己的梦想前进，并且与新的伙伴一同以最棒的队伍作为目标而努力着。他们各自带着隐藏在内心的想法迎接崭新的夏天……围绕岩鸢与鲛柄、伙伴与游泳以及他们的未来这些要素展开的新故事就这样正式拉开帷幕。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0421B58FBE185E5A50E978#第02集$MOE0421B58FBE185E5A50E97B#第03集$MOE0421B58FBE185E5A50E97A#第04集$MOE0421B58FBE185E5A50E97D#第05集$MOE0421B58FBE185E5A50E97C#第06集$MOE0421B58FBE185E5A50E97F#第07集$MOE0421B58FBE185E5A50E97E#第08集$MOE0421B58FBE185E5A50E971#第09集$MOE0421B58FBE185E5A50E970#第10集$MOE0421B58FBE185E5A50E879#第11集$MOE0421B58FBE185E5A50E878#第12集$MOE0421B58FBE185E5A50E87B#第13集$MOE0421B58FBE185E5A50E87A$$$第01集$id_XS0421B58FBE185E5A50E978#第02集$id_XS0421B58FBE185E5A50E97B#第03集$id_XS0421B58FBE185E5A50E97A#第04集$id_XS0421B58FBE185E5A50E97D#第05集$id_XS0421B58FBE185E5A50E97C#第06集$id_XS0421B58FBE185E5A50E97F#第07集$id_XS0421B58FBE185E5A50E97E#第08集$id_XS0421B58FBE185E5A50E971#第09集$id_XS0421B58FBE185E5A50E970#第10集$id_XS0421B58FBE185E5A50E879#第11集$id_XS0421B58FBE185E5A50E878#第12集$id_XS0421B58FBE185E5A50E87B#第13集$id_XS0421B58FBE185E5A50E87A$$$第01集$id_MOE0421B58FBE185E5A50E978#第02集$id_MOE0421B58FBE185E5A50E97B#第03集$id_MOE0421B58FBE185E5A50E97A#第04集$id_MOE0421B58FBE185E5A50E97D#第05集$id_MOE0421B58FBE185E5A50E97C#第06集$id_MOE0421B58FBE185E5A50E97F#第07集$id_MOE0421B58FBE185E5A50E97E#第08集$id_MOE0421B58FBE185E5A50E971#第09集$id_MOE0421B58FBE185E5A50E970#