INSERT INTO `mac_vod` VALUES (1199, 1, 0, 0, '悠哉日常大王 第二季', 'のんのんびより りぴーと（2015）', 'youzairichangdawangdierji', 1, 'Y', '', '5c51be29', '漫画改,日常,萌系,治愈', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2269017498.jpg', '', '', '', '小岩井小鸟 / 村川梨衣 / 佐仓绫音 / 阿澄佳奈 / 名冢佳织 / 佐藤利奈 / 福圆美里 / 新谷良子 / 平松晶子', '川面真也 / 泽井幸次 / 池端隆史 / 阿部达也 / 高村雄太 / 福多润 / 平田丰', '', '', '《悠悠哉哉少女日和》的第2期电视动画。动画第1期放送完毕后，第2期制作决定的消息在2014年4月6日的现场活动中发表，故事简介 ：在乡间里的学校，每天都有愉快的时光。 朋友们同在一起，就是悠悠哉哉的日', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2015', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.4, 0, 0, 1741394396, 1741360916, 0, 0, 0, 0, 0.0, '', '1200', '', '', '', '', '', '', '', '<p>《悠悠哉哉少女日和》的第2期电视动画。动画第1期放送完毕后，第2期制作决定的消息在2014年4月6日的现场活动中发表，故事简介 ：在乡间里的学校，每天都有愉快的时光。 朋友们同在一起，就是悠悠哉哉的日和。 全校学生只有5个人、位于超偏远乡下的旭丘分校，是一个被丰富的自然景色所包围的学校。 “难道说…我们其实…住在乡下？” 这是一部充满疗愈情怀的轻松小品漫画。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0474B989EB4C5F0050E978#第02集$MOE0474B989EB4C5F0050E97B#第03集$MOE0474B989EB4C5F0050E97A#第04集$MOE0474B989EB4C5F0050E97D#第05集$MOE0474B989EB4C5F0050E97C#第06集$MOE0474B989EB4C5F0050E97F#第07集$MOE0474B989EB4C5F0050E97E#第08集$MOE0474B989EB4C5F0050E971#第09集$MOE0474B989EB4C5F0050E970#第10集$MOE0474B989EB4C5F0050E879#第11集$MOE0474B989EB4C5F0050E878#第12集$MOE0474B989EB4C5F0050E87B#OAD$MOE0474B989EB4C5F0050E87A$$$第01集$id_XS0474B989EB4C5F0050E978#第02集$id_XS0474B989EB4C5F0050E97B#第03集$id_XS0474B989EB4C5F0050E97A#第04集$id_XS0474B989EB4C5F0050E97D#第05集$id_XS0474B989EB4C5F0050E97C#第06集$id_XS0474B989EB4C5F0050E97F#第07集$id_XS0474B989EB4C5F0050E97E#第08集$id_XS0474B989EB4C5F0050E971#第09集$id_XS0474B989EB4C5F0050E970#第10集$id_XS0474B989EB4C5F0050E879#第11集$id_XS0474B989EB4C5F0050E878#第12集$id_XS0474B989EB4C5F0050E87B#OAD$id_XS0474B989EB4C5F0050E87A$$$第01集$id_MOE0474B989EB4C5F0050E978#第02集$id_MOE0474B989EB4C5F0050E97B#第03集$id_MOE0474B989EB4C5F0050E97A#第04集$id_MOE0474B989EB4C5F0050E97D#第05集$id_MOE0474B989EB4C5F0050E97C#第06集$id_MOE0474B989EB4C5F0050E97F#第07集$id_MOE0474B989EB4C5F0050E97E#第08集$id_MOE0474B989EB4C5F0050E971#第09集$id_MOE0474B989EB4C5F0050E970#第10集$id_MOE0474B989EB4C5F0050E879#第11集$id_MOE0474B989EB4C5F0050E878#第12集$id_MOE0474B989EB4C5F0050E87B#OAD$id_MOE0474B989EB4C5F0050E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1200, 1, 0, 0, '悠哉日常大王 第三季', 'のんのんびより のんすとっぷ（2021）', 'youzairichangdawangdisanji', 1, 'Y', '', '114f1d7b', '漫画改,日常,萌系,治愈', 'http://i0.hdslb.com/bfs/bangumi/image/3ec497853b0045ee7099d1e4d4a00552ea3aa12a.png', '', '', '', '小岩井小鸟 / 村川梨衣 / 佐仓绫音 / 阿澄佳奈 / 名冢佳织 / 佐藤利奈 / 福圆美里 / 新谷良子 / 田中爱美 / 久野美咲 / 平松晶子 / 高垣彩阳', '川面真也 / 副岛惠文 / 小柴纯弥 / 稻叶友纪 / 矢吹勉 / 福多润', '', '', '「旭丘分校」的学生，仅有五人。\r\n虽然学年性格各不相同，但大家一起做菜、一起捉虫、一起试着练习乐器……春夏秋冬四季变换的乡村生活，一直都那么让人兴奋。\r\n虽然一如既往地平和，但在欢笑和感动当中，心中也变得', '全12集 OAD', '', 0, '0', '', '', '日本', '日语', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.9, 0, 0, 1741403419, 1741360931, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「旭丘分校」的学生，仅有五人。\r\n虽然学年性格各不相同，但大家一起做菜、一起捉虫、一起试着练习乐器……春夏秋冬四季变换的乡村生活，一直都那么让人兴奋。\r\n虽然一如既往地平和，但在欢笑和感动当中，心中也变得温暖起来。\r\n悠哉悠哉的几位成员所度过的日常，再一次开始了。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0026B8DEB84D5A5B50E978#第02集$MOE0026B8DEB84D5A5B50E97B#第03集$MOE0026B8DEB84D5A5B50E97A#第04集$MOE0026B8DEB84D5A5B50E97D#第05集$MOE0026B8DEB84D5A5B50E97C#第06集$MOE0026B8DEB84D5A5B50E97F#第07集$MOE0026B8DEB84D5A5B50E97E#第08集$MOE0026B8DEB84D5A5B50E971#第09集$MOE0026B8DEB84D5A5B50E970#第10集$MOE0026B8DEB84D5A5B50E879#第11集$MOE0026B8DEB84D5A5B50E878#第12集$MOE0026B8DEB84D5A5B50E87B#OAD$MOE0026B8DEB84D5A5B50E87A$$$第01集$id_XS0026B8DEB84D5A5B50E978#第02集$id_XS0026B8DEB84D5A5B50E97B#第03集$id_XS0026B8DEB84D5A5B50E97A#第04集$id_XS0026B8DEB84D5A5B50E97D#第05集$id_XS0026B8DEB84D5A5B50E97C#第06集$id_XS0026B8DEB84D5A5B50E97F#第07集$id_XS0026B8DEB84D5A5B50E97E#第08集$id_XS0026B8DEB84D5A5B50E971#第09集$id_XS0026B8DEB84D5A5B50E970#第10集$id_XS0026B8DEB84D5A5B50E879#第11集$id_XS0026B8DEB84D5A5B50E878#第12集$id_XS0026B8DEB84D5A5B50E87B#OAD$id_XS0026B8DEB84D5A5B50E87A$$$第01集$id_MOE0026B8DEB84D5A5B50E978#第02集$id_MOE0026B8DEB84D5A5B50E97B#第03集$id_MOE0026B8DEB84D5A5B50E97A#第04集$id_MOE0026B8DEB84D5A5B50E97D#第05集$id_MOE0026B8DEB84D5A5B50E97C#第06集$id_MOE0026B8DEB84D5A5B50E97F#第07集$id_MOE0026B8DEB84D5A5B50E97E#第08集$id_MOE0026B8DEB84D5A5B5