INSERT INTO `mac_vod` VALUES (1201, 2, 0, 0, '剧场版 悠哉日常大王 Vacation', '劇場版 のんのんびより ばけーしょん（2018）', 'juchangbanyouzairichangdawangVacation', 1, 'J', '', '36b8155b', '漫画改,萌系,治愈,日常', 'http://i0.hdslb.com/bfs/bangumi/03f4fbcb9f712f52ff61f68fe6a345abf47c555a.png', '', '', '', '小岩井小鸟 / 村川梨衣 / 佐仓绫音 / 阿澄佳奈 / 名冢佳织 / 佐藤利奈 / 福圆美里 / 新谷良子 / 下地紫野 / 平松晶子 / 筱原惠美 / 绫濑有', '川面真也', '', '', '「旭丘分校」的学生有五人。\r\n虽然不论是学年还是性格都不同，但总是一年四季彼此一同享受着乡村生活。\r\n某天，在百货公司的抽奖抽中了特等奖——去冲绳的旅行券。\r\n这也让众人决定，利用暑假期间一同前往冲绳去旅行', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2018', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 9.9, 0, 0, 1741406300, 1741360946, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>「旭丘分校」的学生有五人。\r\n虽然不论是学年还是性格都不同，但总是一年四季彼此一同享受着乡村生活。\r\n某天，在百货公司的抽奖抽中了特等奖——去冲绳的旅行券。\r\n这也让众人决定，利用暑假期间一同前往冲绳去旅行。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0221EE80B81C585B50E978$$$正片$id_MOE0221EE80B81C585B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1202, 1, 0, 0, '黑色四叶草', 'ブラッククローバー（2017）', 'heisesiyecao', 1, 'H', '', 'd452e040', '架空,漫画改,热血,战斗', 'http://i0.hdslb.com/bfs/bangumi/image/aecbaaf4e3e36a2796684c2eff8ceb9b0f247c6d.jpg', '', '', '', '梶原岳人 / 岛崎信长 / 诹访部顺一 / 优木加奈 / 福山润 / 室元气 / 村濑步 / 日野聪 / 水树奈奈 / 安野希世乃 / 松田健一郎 / 森川智之 / 小野大辅 / 石川界人 / 寺岛拓笃 / 鸟海浩辅 / 小西克幸 / 小林优 / 浪川大辅 / 高桥未奈美 / 绿川光 / 斋贺光希 / 赤坂柾之 / 西明日香 / 山本匠马 / 皆川纯子 / 大桥贤一郎 / 逢坂良太 / 花江夏树 / 伊濑茉莉也 / 杉田智和 / 樱井孝宏 / 森田成一 / 市道真央 / 置鲇龙太郎 / 滨野大辉 / 高冢', '吉原达矢 / 种村绫隆 / 浅见松雄 / 津田义三 / 清水明 / 秦义人 / 荻原露光 / 粟井重纪 / 小野田雄亮 / 佐土原武之 / 千叶大辅 / 榎田敬宏 / 丝贺慎太郎 / 岩泽亨', '', '', '曾经险些遭到魔神毁灭的世界，拯救它的是一位被后世称为“魔法帝”的魔导士……两位被遗弃在教堂的少年，一位是有卓越魔力跟魔法才能的四叶草魔导书的尤诺，另一位魔法值为零但却意外获得黑色五叶草的魔法书的亚斯塔', '全170集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 50, 0, 50, 50, '', 0, 0, 9.5, 0, 0, 1741529854, 1741369377, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>曾经险些遭到魔神毁灭的世界，拯救它的是一位被后世称为“魔法帝”的魔导士……两位被遗弃在教堂的少年，一位是有卓越魔力跟魔法才能的四叶草魔导书的尤诺，另一位魔法值为零但却意外获得黑色五叶草的魔法书的亚斯塔……这是关于一位没魔法能力的少年却想要成为魔法帝的故事。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5523B98AEC19590950E978#第02集$MOE5523B98AEC19590950E97B#第03集$MOE5523B98AEC19590950E97A#第04集$MOE5523B98AEC19590950E97D#第05集$MOE5523B98AEC19590950E97C#第06集$MOE5523B98AEC19590950E97F#第07集$MOE5523B98AEC19590950E97E#第08集$MOE5523B98AEC19590950E971#第09集$MOE5523B98AEC19590950E970#第10集$MOE5523B98AEC19590950E879#第11集$MOE5523B98AEC19590950E878#第12集$MOE5523B98AEC19590950E87B#第13集$MOE5523B98AEC19590950E87A#第14集$MOE5523B98AEC19590950E87D#第15集$MOE5523B98AEC19590950E87C#第16集$MOE5523B98AEC19590950E87F#第17集$MOE5523B98AEC19590950E87E#第18集$MOE5523B98AEC19590950E871#第19集$MOE5523B98AEC19590950E870#第20集$MOE5523B98AEC19590950EB79#第21集$MOE5523B98AEC19590950EB78#第22集$MOE5523B98AEC19590950EB7B#第23集$MOE5523B98AEC19590950EB7A#第24集$MOE5523B98AEC19590950EB7D#第25集$MOE5523B98AEC19590950EB7C#第26集$MOE5523B98AEC19590950EB7F#第27集$MOE5523B98AEC19590950EB7E#第28集$MOE5523B98AEC19590950EB71#第29集$MOE5523B98AEC19590950EB70#第30集$MOE55