INSERT INTO `mac_vod` VALUES (1215, 1, 0, 0, '妖怪公寓的幽雅日常', '妖怪アパートの幽雅な日常（2017）', 'yaoguaigongyudeyouyarichang', 1, 'Y', '', 'd5d636de', '日常,神魔,奇幻', 'http://i0.hdslb.com/bfs/bangumi/c521e6f0d05b8aaba24ec96265fe707d5f3b9c16.jpg', '', '', '', '阿部敦 / 中村悠一 / 石田彰 / 中井和哉 / 泽城美雪 / 森川智之 / 杉田智和 / 速水奖 / 游佐浩二 / 钉宫理惠 / 田村睦心 / 三石琴乃 / 子安武人 / 小西克幸', '桥本光夫 / 关田修 / 藤本义孝 / 西田健一 / 绪方隆秀', '', '', '因为父母双亡而艰难寄居在亲戚家的稻叶夕士，升入高中后决心独自生活。稻叶夕士找到了价格非常便宜的公寓“寿庄”。但是，那里是聚集了妖怪・幽灵・人类的“妖怪公寓”──!!\r\n稻叶夕士并不习惯去面对有着令人恐惧', '全26集', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 9.2, 0, 0, 1741702578, 1741664811, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>因为父母双亡而艰难寄居在亲戚家的稻叶夕士，升入高中后决心独自生活。稻叶夕士找到了价格非常便宜的公寓“寿庄”。但是，那里是聚集了妖怪・幽灵・人类的“妖怪公寓”──!!\r\n稻叶夕士并不习惯去面对有着令人恐惧的身姿的妖怪们以及富有个性的怪人们，但是在与他们奇妙的共同生活中，稻叶夕士逐渐敞开了紧闭的心扉…。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5522E88EBA1F095C50E978#第02集$MOE5522E88EBA1F095C50E97B#第03集$MOE5522E88EBA1F095C50E97A#第04集$MOE5522E88EBA1F095C50E97D#第05集$MOE5522E88EBA1F095C50E97C#第06集$MOE5522E88EBA1F095C50E97F#第07集$MOE5522E88EBA1F095C50E97E#第08集$MOE5522E88EBA1F095C50E971#第09集$MOE5522E88EBA1F095C50E970#第10集$MOE5522E88EBA1F095C50E879#第11集$MOE5522E88EBA1F095C50E878#第12集$MOE5522E88EBA1F095C50E87B#第13集$MOE5522E88EBA1F095C50E87A#第14集$MOE5522E88EBA1F095C50E87D#第15集$MOE5522E88EBA1F095C50E87C#第16集$MOE5522E88EBA1F095C50E87F#第17集$MOE5522E88EBA1F095C50E87E#第18集$MOE5522E88EBA1F095C50E871#第19集$MOE5522E88EBA1F095C50E870#第20集$MOE5522E88EBA1F095C50EB79#第21集$MOE5522E88EBA1F095C50EB78#第22集$MOE5522E88EBA1F095C50EB7B#第23集$MOE5522E88EBA1F095C50EB7A#第24集$MOE5522E88EBA1F095C50EB7D#第25集$MOE5522E88EBA1F095C50EB7C#第26集$MOE5522E88EBA1F095C50EB7F$$$第01集$id_XS5522E88EBA1F095C50E978#第02集$id_XS5522E88EBA1F095C50E97B#第03集$id_XS5522E88EBA1F095C50E97A#第04集$id_XS5522E88EBA1F095C50E97D#第05集$id_XS5522E88EBA1F095C50E97C#第06集$id_XS5522E88EBA1F095C50E97F#第07集$id_XS5522E88EBA1F095C50E97E#第08集$id_XS5522E88EBA1F095C50E971#第09集$id_XS5522E88EBA1F095C50E