INSERT INTO `mac_vod` VALUES (1217, 1, 0, 0, '妄想学生会2', '生徒会役員共*（2014）', 'wangxiangxueshenghui2', 1, 'W', '', '3ff1da9b', '漫画改,搞笑,校园', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2260270517.jpg', '', '', '', '日笠阳子 / 浅沼晋太郎 / 佐藤聪美 / 矢作纱友里 / 小林优 / 新井里美 / 小见川千明 / 加藤英美里 / 下田麻美 / 椎名碧流 / 斋藤千和 / 平野文 / 白石稔', '金澤洪充', '', '', '私立樱才学园本是一所女子高校，然而，在社会大趋势的冲击之下，校方决定打开大门，迎接男生们的到来。第一年，学校录取的男生仅有区区二十八人，他们所要面对的，是泱泱五百二十四位“如狼似虎”的女生们。津田隆利', '全13集 OAD', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 21, 0, 21, 21, '', 0, 0, 8.8, 0, 0, 1741750460, 1741738278, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>私立樱才学园本是一所女子高校，然而，在社会大趋势的冲击之下，校方决定打开大门，迎接男生们的到来。第一年，学校录取的男生仅有区区二十八人，他们所要面对的，是泱泱五百二十四位“如狼似虎”的女生们。津田隆利（浅沼晋太郎 配音）就是这二十八人中的一员，机缘巧合之下，他误打误撞加入了学生会之中。</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0271EA89ED48545B50E978#第02集$MOE0271EA89ED48545B50E97B#第03集$MOE0271EA89ED48545B50E97A#第04集$MOE0271EA89ED48545B50E97D#第05集$MOE0271EA89ED48545B50E97C#第06集$MOE0271EA89ED48545B50E97F#第07集$MOE0271EA89ED48545B50E97E#第08集$MOE0271EA89ED48545B50E971#第09集$MOE0271EA89ED48545B50E970#第10集$MOE0271EA89ED48545B50E879#第11集$MOE0271EA89ED48545B50E878#第12集$MOE0271EA89ED48545B50E87B#第13集$MOE0271EA89ED48545B50E87A#第14集OAD$MOE0271EA89ED48545B50E87D#第15集OAD$MOE0271EA89ED48545B50E87C#第16集OAD$MOE0271EA89ED48545B50E87F#第17集OAD$MOE0271EA89ED48545B50E87E#第18集OAD$MOE0271EA89ED48545B50E871#第19集OAD$MOE0271EA89ED48545B50E870#第20-21集OAD$MOE0271EA89ED48545B50EB79#第22集OAD$MOE0271EA89ED48545B50EB78#第23集OAD$MOE0271EA89ED48545B50EB7B#第24集OAD$MOE0271EA89ED48545B50EB7A#第25集OAD$MOE0271EA89ED48545B50EB7D$$$第01集$id_XS0271EA89ED48545B50E978#第02集$id_XS0271EA89ED48545B50E97B#第03集$id_XS0271EA89ED48545B50E97A#第04集$id_XS0271EA89ED48545B50E97D#第05集$id_XS0271EA89ED48545B50E97C#第06集$id_XS0271EA89ED48545B50E97F#第07集$id_XS0271EA89ED48545B50E97E#第08集$id_XS0271EA89ED48545B50E971#第09集$id_XS0271EA89ED48545B50E970#第10集$id_XS0271EA89ED48545B50E879#第11集$id_XS0271EA89ED48545B50E878#第12集$i