INSERT INTO `mac_vod` VALUES (1218, 2, 0, 0, '妄想学生会 剧场版', '劇場版 生徒会役員共（2017）', 'wangxiangxueshenghuijuchangban', 1, 'W', '', '168cc007', '漫画改,搞笑,校园', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2503166245.jpg', '', '', '', '浅沼晋太郎 / 日笠阳子 / 佐藤聪美 / 矢作纱友里 / 斋藤千和 / 上坂堇 / 下田麻美 / 日野未步 / 加藤英美里 / 小见川千明 / 小林优 / 新井里美 / 田村睦心 / 椎名碧流 / 平野文 / 布里德卡特·塞拉·惠美 / 田中爱美 / 白石稔 / 利根健太朗', '金泽洪充', '', '', '私立樱才学园，原本是传统的女子高中，但因少子化问题影响，不得不改制为男女合校。作为改制后第一年入学的28名男性新生之一的津田隆利，偶然之下被拉入了学校的学生会。在外人看来，学生会是美女如云的天堂，但是', '简中1080P', '', 0, '0', '', '', '日本', '日语', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 8.3, 0, 0, 1741760699, 1741756030, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>私立樱才学园，原本是传统的女子高中，但因少子化问题影响，不得不改制为男女合校。作为改制后第一年入学的28名男性新生之一的津田隆利，偶然之下被拉入了学校的学生会。在外人看来，学生会是美女如云的天堂，但是津田身边的三位学生会女干部性格都非常独特，津田开始了他每天学生会的吐槽生活。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS0021B4DBEA195D0E50E978$$$正片$id_MOE0021B4DBEA195D0E50E978', '', '', '', '', 0, '', '');
