INSERT INTO `mac_vod` VALUES (1222, 1, 0, 0, '噬魂师NOT!', 'ソウルイーターノット!（2014）', 'shihunshiNOT', 1, 'S', '', 'cdf5d57b', '漫画改,奇幻,冒险,校园', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2179617149.jpg', '', '', '', '千菅春香 / 悠木碧 / 早见沙织 / 樱井孝宏 / 山下诚一郎 / 小松未可子 / 小岩井小鸟 / 斋藤千和 / 冲佳苗 / 木村雅史 / 小见川千明 / 内山昂辉', '桥本昌和', '', '', '春鸟鸫（千菅春香 配音）是一位十四岁的平凡少女，她即将进入著名的死神武器工匠专科学校开始崭新的高中生活，在入校第一天，小鸫就幸运的遇见了EAT的玛嘉（小见川千明 配音），玛嘉送给了小鸫一本书，就此彻底', '全12集', '', 0, '0', '', '', '日本', '日语', '2014', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 3, 0, 3, 3, '', 0, 0, 6.0, 0, 0, 1742294593, 1742284080, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '春鸟鸫（千菅春香 配音）是一位十四岁的平凡少女，她即将进入著名的死神武器工匠专科学校开始崭新的高中生活，在入校第一天，小鸫就幸运的遇见了EAT的玛嘉（小见川千明 配音），玛嘉送给了小鸫一本书，就此彻底虏获了小鸫的芳心，小鸫甚至因为憧憬玛嘉，而像她一样扎起了双马尾。 多多音美美（悠木碧 配音）是小鸫的室友，个性大大咧咧，呆萌又迟钝，常常连自己的名字都忘记。阿尼娅（早见沙织 配音）是小鸫的另一位室友，样貌高贵美丽的她却对庶民的一切有着狂热的兴趣，虽然个性傲娇却有着意外可爱的一面。三个女孩在学校的精彩生活就此拉开了序幕。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5273EA8DED1C5A5B50E978#第02集$MOE5273EA8DED1C5A5B50E97B#第03集$MOE5273EA8DED1C5A5B50E97A#第04集$MOE5273EA8DED1C5A5B50E97D#第05集$MOE5273EA8DED1C5A5B50E97C#第06集$MOE5273EA8DED1C5A5B50E97F#第07集$MOE5273EA8DED1C5A5B50E97E#第08集$MOE5273EA8DED1C5A5B50E971#第09集$MOE5273EA8DED1C5A5B50E970#第10集$MOE5273EA8DED1C5A5B50E879#第11集$MOE5273EA8DED1C5A5B50E878#第12集$MOE5273EA8DED1C5A5B50E87B$$$第01集$id_XS5273EA8DED1C5A5B50E978#第02集$id_XS5273EA8DED1C5A5B50E97B#第03集$id_XS5273EA8DED1C5A5B50E97A#第04集$id_XS5273EA8DED1C5A5B50E97D#第05集$id_XS5273EA8DED1C5A5B50E97C#第06集$id_XS5273EA8DED1C5A5B50E97F#第07集$id_XS5273EA8DED1C5A5B50E97E#第08集$id_XS5273EA8DED1C5A5B50E971#第09集$id_XS5273EA8DED1C5A5B50E970#第10集$id_XS5273EA8DED1C5A5B50E879#第11集$id_XS5273EA8DED1C5A5B50E878#第12集$id_XS5273EA8DED1C5A5B50E87B$$$第01集$id_MOE5273EA8DED1C5A5B50E978#第02集$id_MOE5273EA8DED1C5A5B50E97B#第03集$id_MOE5273EA8DED1C5A5B50E97A#第04集$id_MOE5273EA8DED1C5A5B50E97D#第05集$id_MOE5273EA8DED1C5A5B50E97C#第06集$id_MOE5273EA8DED1C5A5B50E97F#第07集$id_MOE5273EA8DED1C5A5B50E97E#第08集$id_MOE5273EA8DED1C5A5B50E971#第09集$id_MOE