INSERT INTO `mac_vod` VALUES (1287, 1, 0, 0, 'Yes! 光之美少女5', 'Yes! プリキュア5（2007）', 'Yesguangzhimeishaonv5', 1, 'Y', '', '88bb951d', '热血,动作,奇幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867153444.jpg', '', '', '', '三瓶由布子 / 竹内顺子 / 伊濑茉莉也 / 永野爱 / 前田爱 / 草尾毅 / 入野自由 / 仙台惠理 / 杉山佳寿子 / 优希比吕 / 高木涉 / 丸山咏二 / 小宫和枝 / 桧山修之 / 陶山章央 / 泽海阳子 / 樱井千寻 / 泷知史 / 日野由利加 / 浅野麻由美 / 渡边久美子 / 雪野五月 / 中博史 / 金丸淳一 / 池田知聪 / 山田茉莉 / 神代知衣 / 伊东久美子 / 工藤真由 / 宫本佳那子 / 游佐浩二 / 森训久', '小村敏明 / 西尾大介 / 志水淳儿 / 长峰达也 / 大塚隆史 / 石平信司 / 松本理惠 / 冈佳广 / 川田武范 / 座古明史 / 岩井隆央', '', '', '官方网站：', '全49集', '', 0, '0', '', '', '日本', '一月', '2007', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 6, 0, 6, 6, '', 0, 0, 8.4, 0, 0, 1744361412, 1744325063, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '某日，梦原希在学校图书馆找到一本名叫魔法心愿PDA（Dream Collet）的书，并遇见来自帕鲁米埃王国的可可。可可是为了恢复被恶梦军团破坏的王国而寻找魔法心愿PDA。要使用魔法心愿PDA许愿，必须收集55个光之精灵。美美为了完成可可的心愿，跟其他4名同伴一起变身成光之美少女（プリキュア，Pretty Cure）跟阻碍帕鲁米埃王国复原的恶梦军团战斗。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE092FEEDAB01C5C5D50E978#第02集$MOE092FEEDAB01C5C5D50E97B#第03集$MOE092FEEDAB01C5C5D50E97A#第04集$MOE092FEEDAB01C5C5D50E97D#第05集$MOE092FEEDAB01C5C5D50E97C#第06集$MOE092FEEDAB01C5C5D50E97F#第07集$MOE092FEEDAB01C5C5D50E97E#第08集$MOE092FEEDAB01C5C5D50E971#第09集$MOE092FEEDAB01C5C5D50E970#第10集$MOE092FEEDAB01C5C5D50E879#第11集$MOE092FEEDAB01C5C5D50E878#第12集$MOE092FEEDAB01C5C5D50E87B#第13集$MOE092FEEDAB01C5C5D50E87A#第14集$MOE092FEEDAB01C5C5D50E87D#第15集$MOE092FEEDAB01C5C5D50E87C#第16集$MOE092FEEDAB01C5C5D50E87F#第17集$MOE092FEEDAB01C5C5D50E87E#第18集$MOE092FEEDAB01C5C5D50E871#第19集$MOE092FEEDAB01C5C5D50E870#第20集$MOE092FEEDAB01C5C5D50EB79#第21集$MOE092FEEDAB01C5C5D50EB78#第22集$MOE092FEEDAB01C5C5D50EB7B#第23集$MOE092FEEDAB01C5C5D50EB7A#第24集$MOE092FEEDAB01C5C5D50EB7D#第25集$MOE092FEEDAB01C5C5D50EB7C#第26集$MOE092FEEDAB01C5C5D50EB7F#第27集$MOE092FEEDAB01C5C5D50EB7E#第28集$MOE092FEEDAB01C5C5D50EB71#第29集$MOE092FEEDAB01C5C5D50EB70#第30集$MOE092FEEDAB01C5C5D50EA79#第31集$MOE092FEEDAB01C5C5D50EA78#第32集$MOE092FEEDAB01C5C5D50EA7B#第33集$MOE092FEEDAB01C5C5D