INSERT INTO `mac_vod` VALUES (1288, 1, 0, 0, '国王排名', '王様ランキング（2021）', 'guowangpaiming', 1, 'G', '', '2cc9b943', '漫画改,冒险,励志,奇幻', 'http://i0.hdslb.com/bfs/bangumi/image/8aead7650fb3ded88f24654b7b66823169cb9a8c.png', '', '', '', '日向未南 / 村濑步 / 梶裕贵 / 佐藤利奈 / 江口拓也 / 上田燿司 / 安元洋贵 / 田所阳向 / 山下大辉 / 三宅健太 / 本田贵子 / 坂本真绫 / 下山吉光 / 樱井孝宏', '八田洋介 / 今井有文', '', '', '国家的丰饶、麾下勇者的数量、\r\n以及国王本人如何像勇者一般强大，\r\n这些要素的综合排名，便是所谓的“国王排名”。\r\n主人公波吉是国王排名第七名的伯斯王治下王国的第一王子。\r\n但是波吉却生来又聋又哑，贫弱到挥不', '全23集', '', 0, '0', '', '', '日本', '十月', '2021', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, '', 0, 0, 7.0, 0, 0, 1744408858, 1744328831, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>国家的丰饶、麾下勇者的数量、\r\n以及国王本人如何像勇者一般强大，\r\n这些要素的综合排名，便是所谓的“国王排名”。\r\n主人公波吉是国王排名第七名的伯斯王治下王国的第一王子。\r\n但是波吉却生来又聋又哑，贫弱到挥不动剑。\r\n不止家臣甚至连民众都轻蔑地说「他实在不是当国王的料」。\r\n这样的波吉人生中第一位交到的朋友，卡克。\r\n与卡克的邂逅，以及那些微小的勇气中诞生的，\r\n波吉人生的巨变将要开始——</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0374EF81EB10590A50E978#第02集$MOE0374EF81EB10590A50E97B#第03集$MOE0374EF81EB10590A50E97A#第04集$MOE0374EF81EB10590A50E97D#第05集$MOE0374EF81EB10590A50E97C#第06集$MOE0374EF81EB10590A50E97F#第07集$MOE0374EF81EB10590A50E97E#第08集$MOE0374EF81EB10590A50E971#第09集$MOE0374EF81EB10590A50E970#第10集$MOE0374EF81EB10590A50E879#第11集$MOE0374EF81EB10590A50E878#第12集$MOE0374EF81EB10590A50E87B#第13集$MOE0374EF81EB10590A50E87A#第14集$MOE0374EF81EB10590A50E87D#第15集$MOE0374EF81EB10590A50E87C#第16集$MOE0374EF81EB10590A50E87F#第17集$MOE0374EF81EB10590A50E87E#第18集$MOE0374EF81EB10590A50E871#第19集$MOE0374EF81EB10590A50E870#第20集$MOE0374EF81EB10590A50EB79#第21集$MOE0374EF81EB10590A50EB78#第22集$MOE0374EF81EB10590A50EB7B#第23集$MOE0374EF81EB10590A50EB7A$$$第01集$id_XS0374EF81EB10590A50E978#第02集$id_XS0374EF81EB10590A50E97B#第03集$id_XS0374EF81EB10590A50E97A#第04集$id_XS0374EF81EB10590A50E97D#第05集$id_XS0374EF81EB10590A50E97C#第06集$id_XS0374EF81EB10590A50E97F#第07集$id_XS0374EF81EB10590A50E97E#第08集$id_XS0374EF81EB10590A50E971#第09集$id_XS0374EF81EB10590A50E970#第10集$id_XS0374EF81EB10590A50E879#第11集$id_XS0374EF81E