INSERT INTO `mac_vod` VALUES (1292, 1, 0, 0, '神统记', '神統記（2025）', 'shentongji', 1, 'S', '', '30655c3b', '奇幻,魔法,战争', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2905428540.jpg', '', '', '', '田村睦心 / 花泽香菜 / 松冈祯丞 / 宫内敦士 / 福西胜也 / 石见舞菜香 / 集贝花 / 中博史 / 银河万丈', '森邦宏', '', '', '人族领地遭到灰猿人族和猪人等亚人种入侵，战乱时代持续不断。', '更新至第01集', '', 0, '0', '', '（每周六）00:00更新', '日本', '四月', '2025', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 0.0, 0, 0, 1744403582, 1744391897, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '人族领地遭到灰猿人族和猪人等亚人种入侵，战乱时代持续不断。 拉格村的少年·凯为了守护村庄，每天都在战斗中度过。在被称为“加护者”的强大力量持有者的严酷战斗中，伙伴们接连倒下，而自己却突然回忆起本不该经历的不可思议的记忆。那是比这个世界更先进的文明技术和人们生活的知识。然而，原本只是一个普通村民的凯，不久后将被卷入巨大的考验之中。在残酷的世界中，一位少年的战斗与成长的壮丽奇幻故事在此展开。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0227BA8DBC4A5E5B50E978$$$第01集$id_XS0227BA8DBC4A5E5B50E978$$$第01集$id_MOE0227BA8DBC4A5E5B50E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1289, 1, 0, 0, '幼女战记', '幼女戦記（2017）', 'younvzhanji', 1, 'Y', '', 'fd158823', '小说改,奇幻,战斗', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2411087940.jpg', '', '', '', '悠木碧 / 早见沙织 / 三木真一郎 / 玄田哲章 / 大塚芳忠 / 飞田展男 / 滨野大辉 / 小林裕介 / 土师孝也 / 福岛润 / 田村睦心 / 长岛雄一 / 稻垣隆行 / 户松遥 / 堀内贤雄 / 藤原夏海 / 广濑裕也 / 相马康一 / 楠见尚己 / 鸟海浩辅', '上村泰 / 立川让 / 丸山裕介 / 高村雄太 / 赤松康裕 / 春藤佳奈 / 小野田雄亮', '', '', '统一历1923年6月。金发碧眼的幼女，谭雅·提古雷查夫，正作为部队勤务的一环而在北方军管区诺登战区第三巡逻线进行帝国军士官学校最终课程的研修。作为航空魔导师向着光辉履历踏出第一步的研修，平安无事地结束', '全12集 OVA', '', 0, '0', '', '', '日本', '一月', '2017', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 9, 0, 9, 9, '', 0, 0, 8.4, 0, 0, 1744365879, 1744355373, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>统一历1923年6月。金发碧眼的幼女，谭雅·提古雷查夫，正作为部队勤务的一环而在北方军管区诺登战区第三巡逻线进行帝国军士官学校最终课程的研修。作为航空魔导师向着光辉履历踏出第一步的研修，平安无事地结束——本该如此。 但事态却向着超出预料的方向转变。以协约联合的越境侵犯为契机，帝国与协约联合进入战争状态。随着转移至战时体制，谭雅被交付了观测任务，但协约联合军发动奇袭，谭雅陷入不得不与敌军魔导师中队单独交战的事态。敌众我寡，就连在我军抵达之前牵制敌军都无法做到，但逃跑的话则难免敌前逃亡的死罪，她面临这种绝望的状况。为了无论如何存活下去，并在面对高层时做到最好的应对，谭雅使用了某个战略……。 “那是，披着幼女皮的怪物——。”</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE5773BD8DB1115F0A50E978#第02集$MOE5773BD8DB1115F0A50E97B#第03集$MOE5773BD8DB1115F0A50E97A#第04集$MOE5773BD8DB1115F0A50E97D#第05集$MOE5773BD8DB1115F0A50E97C#第06集$MOE5773BD8DB1115F0A50E97F#第07集$MOE5773BD8DB1115F0A50E97E#第08集$MOE5773BD8DB1115F0A50E971#第09集$MOE5773BD8DB1115F0A50E970#第10集$MOE5773BD8DB1115F0A50E879#第11集$MOE5773BD8DB1115F0A50E878#第12集$MOE5773BD8DB1115F0A50E87B#OVA$MOE5773BD8DB1115F0A50E87A$$$第01集$id_XS5773BD8DB1115F0A50E978#第02集$id_XS5773BD8DB1115F0A50E97B#第03集$id_XS5773BD8DB1115F0A50E97A#第04集$id_XS5773BD8DB1115F0A50E97D#第05集$id_XS5773BD8DB1115F0A50E97C#第06集$id_XS5773BD8DB1115F0A50E97F#第07集$id_XS5773BD8DB1115F0A50E97E#第08集$id_XS5773BD8DB1115F0A50E971#第09集$id_XS5773BD8DB1115F0A50E970#第10集$id_XS5773BD8DB1115F0A50E879#第11集$id_XS5773BD8DB1115F0A50E878#第12集$id_XS5773BD8DB1115F0A50E87B#OVA$id_XS5773BD8DB1115F0A50E87A$$$第01集$id_MOE5773BD8DB1115F0A50E978#第02集$id_MOE5773BD8DB1115F0A50E97B#第03集$id_MOE5773BD8DB1115F0A50E97A#第04集$id_MOE5773BD8DB1115F0A50E97D#第05集$id_MOE5773BD8DB1115F0A50E97C#第06集$id_MOE5773BD8DB1115F0A50E97F#第07集$id_MOE5773BD8DB1115F0A50E97E#第08集$id_MOE5773BD8DB1115F0A50E971#第09集$id_MOE5773BD8DB1115F0A50E970#第10集$id_MOE5773BD8DB1115F0A50E879#第11集$id_MOE5773BD8DB1115F0A50E878#第12集$id_MOE5773BD8DB1115F0A50E87B#OVA$id_MOE5773BD8DB1115F0A50E87A', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1290, 2, 0, 0, '幼女战记 剧场版', '劇場版 幼女戦記（2019）', 'younvzhanjijuchangban', 1, 'Y', '', 'df24a22a', '小说改,奇幻,战斗', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2546111180.jpg', '', '', '', '悠木碧 / 早见沙织 / 三木真一郎 / 玄田哲章 / 大塚芳忠 / 飞田展男 / 滨野大辉 / 笠间淳 / 林大地 / 小林裕介 / 土师孝也 / 小柳良宽 / 户松遥 / 高冈瓶瓶', '上村泰', '', '', '统一历1926年。', '简中1080P', '', 0, '0', '', '', '日本', '一月', '2019', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 0, 7, 7, '', 0, 0, 7.8, 0, 0, 1744378162, 1744365479, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>统一历1926年。</p>', 'xs$$$moe', 'no$$$no', '$$$', '正片$id_XS5571BE8CE81B5F5850E978$$$正片$id_MOE5571BE8CE81B5F5850E978', '', '', '', '', 0, '', '');
INSERT INTO `mac_vod` VALUES (1291, 1, 0, 0, 'Yes! 光之美少女5 GoGo!', 'Yes!プリキュア5 GoGo!（2008）', 'Yesguangzhimeishaonv5GoGo', 1, 'Y', '', '67da016c', '热血,动作,奇幻', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2510818062.jpg', '', '', '', '三瓶由布子 / 竹内顺子 / 伊濑茉莉也 / 永野爱 / 前田爱 / 仙台惠理 / 草尾毅 / 入野自由 / 朴璐美 / 园部启一 / 水田山葵 / 皆口裕子 / 松本保典 / 安达真理 / 西原久美子 / 玉川纱己子 / 千叶繁 / 山像香 / 子安武人 / 岛田敏 / 铃木玲子 / 高木涉 / 置鲇龙太郎 / 长岛雄一 / 乃村健次 / 福松进纱 / 山田茉莉 / 神代知衣 / 伊东久美子 / 埴冈由纪子 / 道添爱美 / 冲佳苗 / 工藤真由 / 宫本佳那子 / 天野由梨 / 安井邦彦 / 加藤优子', '小村敏明 / 志水淳儿 / 大塚隆史 / 长峰达也 / 石平信司 / 松本理惠 / 山崎和男 / 植田秀仁 / 川田武范 / 宫繁之 / 三塚雅人 / 岩井隆央 / 座古明史', '', '', '', '全48集', '', 0, '0', '', '', '日本', '一月', '2008', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 4, 0, 4, 4, '', 0, 0, 8.5, 0, 0, 1744408747, 1744365955, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '美美等人消灭恶梦军团后，回归往日和平日子。某日，于美美面前出现一位少年，他交给美美一封神秘的信。“我们于玫瑰疗园恭候光临……”写信者“芙罗拉”留下这段不可思议的讯息后消失，然后信件就变成了玫瑰契约（Rosepad）。突然间新敌人出现！送信少年此时变成了巨大燕子，带美美脱离险境。可可及果果了解到新危机的降临，于是前往美美的世界，给她们新的变身工具光之手机，变身成新的光之美少女。为解开玫瑰疗园之谜而努力。', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0720E8D9B9185B5A50E978#第02集$MOE0720E8D9B9185B5A50E97B#第03集$MOE0720E8D9B9185B5A50E97A#第04集$MOE0720E8D9B9185B5A50E97D#第05集$MOE0720E8D9B9185B5A50E97C#第06集$MOE0720E8D9B9185B5A50E97F#第07集$MOE0720E8D9B9185B5A50E97E#第08集$MOE0720E8D9B9185B5A50E971#第09集$MOE0720E8D9B9185B5A50E970#第10集$MOE0720E8D9B9185B5A50E879#第11集$MOE0720E8D9B9185B5A50E878#第12集$MOE0720E8D9B9185B5A50E87B#第13集$MOE0720E8D9B9185B5A50E87A#第14集$MOE0720E8D9B9185B5A50E87D#第15集$MOE0720E8D9B9185B5A50E87C#第16集$MOE0720E8D9B9185B5A50E87F#第17集$MOE0720E8D9B9185B5A50E87E#第18集$MOE0720E8D9B9185B5A50E871#第19集$MOE0720E8D9B9185B5A50E870#第20集$MOE0720E8D9B9185B5A50EB79#第21集$MOE0720E8D9B9185B5A50EB78#第22集$MOE0720E8D9B9185B5A50EB7B#第23集$MOE0720E8D9B9185B5A50EB7A#第24集$MOE0720E8D9B9185B5A50EB7D#第25集$MOE0720E8D9B9185B5A50EB7C#第26集$MOE0720E8D9B9185B5A50EB7F#第27集$MOE0720E8D9B9185B5A50EB7E#第28集$MOE0720E8D9B9185B5A50EB71#第29集$MOE0720E8D9B9185B5A50EB70#第30集$MOE0720E8D9B9185B5A50EA79#第31集