INSERT INTO `mac_vod` VALUES (1294, 1, 0, 0, 'Heart Catch 光之美少女！', 'ハートキャッチプリキュア！（2010）', 'HeartCatchguangzhimeishaonv', 1, 'H', '', '530dde3a', '热血,动作,奇幻', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510817565.jpg', '', '', '', '水树奈奈 / 水泽史绘 / 桑岛法子 / 久川绫 / 鹤弘美 / 川田妙子 / 熊井统子 / 菊池心 / 石田彰 / 堀内贤雄 / 绿川光 / 楠大典 / 高山南 / 高乃丽 / 竹本英史 / 野岛裕史 / 坂本千夏 / 堀井茶渡 / 岩崎了 / 金田朋子 / 星野贵纪 / 金光宣明 / 加藤优子 / 远近孝一 / 冰青 / 伊藤静 / 中博史 / 汤屋敦子 / 前野智昭 / 久岛志帆 / 佐久间玲 / 牛田裕子 / 藤井雪代 / 埴冈由纪子 / 吉田圣子 / 足立友 / 渡边明乃 / 木内玲子 / 小岛', '长峰达也 / 胜间田具治 / 志水淳儿 / 小村敏明 / 植田秀仁 / 广岛秀树 / 川田武范 / 畑野森生 / 大塚隆史 / 境宗久 / 小川孝治 / 岩井隆央 / 地冈公俊 / 座古明史', '', '', '蕾是个非常喜欢花草植物的中学二年级生，绘里香是个喜欢服装设计的中学二年级生，某日她们梦见了在一个充满美丽花草的地方，还有妖精四处飞舞····· 　　而就在几天后转学到明堂学园的蕾，真的遇上了在梦里见到', '全49集', '', 0, '0', '', '', '日本', '一月', '2010', '', '', '', '', '', '', '', 0, 0, 0, 0, 0, 0, 0, 7, 1, 7, 7, '', 0, 0, 8.9, 0, 0, 1744497967, 1744443613, 0, 0, 0, 0, 0.0, '', '', '', '', '', '', '', '', '', '<p>蕾是个非常喜欢花草植物的中学二年级生，绘里香是个喜欢服装设计的中学二年级生，某日她们梦见了在一个充满美丽花草的地方，还有妖精四处飞舞····· 　　而就在几天后转学到明堂学园的蕾，真的遇上了在梦里见到的妖精，妖精也向蕾表示，希望她能够为守护“心之大树”、并让大家的“心之花”绽放而战······一次偶然的机会，绘里香也加入了进来，和蕾成为了光之美少女……</p>', 'js$$$xs$$$moe', 'no$$$no$$$no', '$$$$$$', '第01集$MOE0424BCDCED4C5E5850E978#第02集$MOE0424BCDCED4C5E5850E97B#第03集$MOE0424BCDCED4C5E5850E97A#第04集$MOE0424BCDCED4C5E5850E97D#第05集$MOE0424BCDCED4C5E5850E97C#第06集$MOE0424BCDCED4C5E5850E97F#第07集$MOE0424BCDCED4C5E5850E97E#第08集$MOE0424BCDCED4C5E5850E971#第09集$MOE0424BCDCED4C5E5850E970#第10集$MOE0424BCDCED4C5E5850E879#第11集$MOE0424BCDCED4C5E5850E878#第12集$MOE0424BCDCED4C5E5850E87B#第13集$MOE0424BCDCED4C5E5850E87A#第14集$MOE0424BCDCED4C5E5850E87D#第15集$MOE0424BCDCED4C5E5850E87C#第16集$MOE0424BCDCED4C5E5850E87F#第17集$MOE0424BCDCED4C5E5850E87E#第18集$MOE0424BCDCED4C5E5850E871#第19集$MOE0424BCDCED4C5E5850E870#第20集$MOE0424BCDCED4C5E5850EB79#第21集$MOE0424BCDCED4C5E5850EB78#第22集$MOE0424BCDCED4C5E5850EB7B#第23集$MOE0424BCDCED4C5E5850EB7A#第24集$MOE0424BCDCED4C5E5850EB7D#第25集$MOE0424BCDCED4C5E5850EB7C#第26集$MOE0424BCDCED4C5E5850EB7F#第27集$MOE0424BCDCED4C5E5850EB7E#第28集$MO